const UPLOADS    = path.join(DATA, "uploads");
const MEDIA_ARCHIVE_DIR = path.join(DATA, "uploads-archive"); // bind-mountet til mediadisk (/mnt/mediadisk/<slug>) i nye instanser
const MEDIA_HOT_LIMIT_BYTES = (parseInt(process.env.MEDIA_HOT_LIMIT_MB, 10) || 10240) * 1024 * 1024; // default 10 GB
const DEVLOG_OWNER = process.env.DEVLOG_OWNER || ("admin@" + (process.env.BASE_DOMAIN || "events-admin.no"));

// ── Media tiering ─────────────────────────────────────────────────────────
// Keeps only the most recently uploaded MEDIA_HOT_LIMIT_BYTES worth of files
// on the fast local disk (UPLOADS). Older files get moved to MEDIA_ARCHIVE_DIR
// (the mediadisk mount) with a symlink left behind at the original path, so
// every existing code path that reads from UPLOADS keeps working unchanged.
let _tierRunning = false;
async function tierMediaStorage() {
  if (_tierRunning) return;
  _tierRunning = true;
  try { await _tierMediaStorageRun(); } finally { _tierRunning = false; }
}
// Async so archiving big videos to the USB disk never blocks the event loop
// (a synchronous copy here froze every request – uploads included – for as
// long as the copy took, one minute after each restart).
async function _tierMediaStorageRun() {
  try {
    if (!fs.existsSync(UPLOADS)) return;
    fs.mkdirSync(MEDIA_ARCHIVE_DIR, { recursive: true });
  } catch(e) {
    // Mediadisk not mounted on this instance (e.g. not migrated yet) — skip quietly.
    return;
  }
  let entries;
  try { entries = await fs.promises.readdir(UPLOADS, { withFileTypes: true }); }
  catch(e) { return; }

  const files = [];
  for (const ent of entries) {
    if (!ent.isFile() && !ent.isSymbolicLink()) continue; // skip subfolders
    const full = path.join(UPLOADS, ent.name);
    let lst;
    try { lst = await fs.promises.lstat(full); } catch(e) { continue; }
    if (lst.isSymbolicLink()) continue; // already archived
    files.push({ name: ent.name, full, size: lst.size, mtimeMs: lst.mtimeMs });
  }

  // Newest first — keep the newest files "hot" on SSD up to the limit
  files.sort(function(a, b) { return b.mtimeMs - a.mtimeMs; });

  let cumulative = 0, movedCount = 0, movedBytes = 0;
  for (const f of files) {
    cumulative += f.size;
    if (cumulative <= MEDIA_HOT_LIMIT_BYTES) continue; // still within the hot window

    const archivePath = path.join(MEDIA_ARCHIVE_DIR, f.name);
    try {
      const t0 = Date.now();
      await fs.promises.copyFile(f.full, archivePath); // copy (rename fails across the SSD/mediadisk mount boundary)
      await fs.promises.unlink(f.full);                // remove the SSD copy
      await fs.promises.symlink(archivePath, f.full);  // leave a symlink so the original path still resolves
      if (Date.now() - t0 > 5000) console.log("[media-tier] " + f.name + " (" + (f.size / 1048576).toFixed(0) + " MB) took " + Math.round((Date.now() - t0) / 1000) + " s");
      movedCount++; movedBytes += f.size;
    } catch(e) {
      console.error("[media-tier] Failed to archive " + f.name + ":", e.message);
    }
  }
  if (movedCount > 0) {
    console.log("[media-tier] Moved " + movedCount + " file(s) (" + (movedBytes / 1024 / 1024).toFixed(1) + " MB) to " + MEDIA_ARCHIVE_DIR);
  }
}

// Deletes an uploaded file whether it's still on the local disk or has been
// archived to the mediadisk (a symlink) — prevents orphaned files piling up
// on the mediadisk when a since-archived upload gets deleted.
function deleteMediaFile(filename) {
  const full = path.join(UPLOADS, filename);
  try {
    const lst = fs.lstatSync(full);
    if (lst.isSymbolicLink()) {
      const target = fs.readlinkSync(full);
      try { fs.unlinkSync(target); } catch(e) {}
    }
    fs.unlinkSync(full);
  } catch(e) {
    // already gone — nothing to do
  }
}

// Run once shortly after startup, then hourly.
setTimeout(tierMediaStorage, 60 * 1000);
setInterval(tierMediaStorage, 60 * 60 * 1000);

// ── Breakglass accounts ──────────────────────────────────────────
// Provisioned via env vars only – never via UI
// BREAKGLASS_1=email:password  BREAKGLASS_2=email:password  BREAKGLASS_3=email:password
const BREAKGLASS_LOG_FILE = path.join(DATA, "breakglass_log.json");
function getBreakglassAccounts() {
  const accounts = [];
  [process.env.BREAKGLASS_1, process.env.BREAKGLASS_2, process.env.BREAKGLASS_3]
    .forEach(function(val, i) {
      if (!val) return;
      const sep = val.indexOf(":");
      if (sep < 1) return;
      accounts.push({ index: i + 1, email: val.slice(0, sep).toLowerCase().trim(), password: val.slice(sep + 1) });
    });
  return accounts;
}
function isBreakglassEmail(email) {
  return getBreakglassAccounts().some(function(a) { return a.email === email.toLowerCase(); });
}

