// displayState persisted to disk — survives restarts
const DISPLAY_STATE_FILE = path.join(DATA, "display_state.json");
function _loadDisplayState() {
  try {
    const raw = JSON.parse(fs.readFileSync(DISPLAY_STATE_FILE, "utf8"));
    const m = new Map();
    Object.entries(raw).forEach(function([k, v]) { m.set(k, v); });
    console.log("[display] Loaded state for", m.size, "event(s) from disk");
    return m;
  } catch(e) { return new Map(); }
}
function _saveDisplayState() {
  try {
    const obj = {};
    displayState.forEach(function(v, k) { obj[k] = v; });
    fs.writeFileSync(DISPLAY_STATE_FILE, JSON.stringify(obj));
  } catch(e) { console.error("[display] Save state failed:", e.message); }
}
const displayState = _loadDisplayState(); // evId → { mode, winnerName, prize, slide, slides[], ticker }

// ── TV Channel (department-level display) ────────────────────────
const TV_STATE_FILE = path.join(DATA, "tv_state.json");
function _loadTvState() {
  try {
    const raw = JSON.parse(fs.readFileSync(TV_STATE_FILE, "utf8"));
    const m = new Map();
    Object.entries(raw).forEach(function([k, v]) { m.set(k, v); });
    return m;
  } catch(e) { return new Map(); }
}
function _saveTvState() {
  try {
    const obj = {};
    tvState.forEach(function(v, k) { obj[k] = v; });
    fs.writeFileSync(TV_STATE_FILE, JSON.stringify(obj));
  } catch(e) {}
}
const tvState = _loadTvState(); // deptId → { mode, slides[], slideInterval, showEvents, ticker }
const tvClients = new Map(); // clientId → { res, deptId }
let tvNextId = 1;
// ── TV channels per group ──
// A channel is a department id, or «deptId~groupId» for one group's screen
// (/tv/romerike/mc). A group screen shows only that group's events, but uses the
// department's TV settings (slides, ticker, number of events …).
function _tvChan(chan) {
  var p = String(chan || "").split("~");
  return { dept: p[0], sg: p[1] || null };
}
function _tvEventIn(e, chan) {
  var c = _tvChan(chan);
  return e.department === c.dept && (!c.sg || e.subgroup === c.sg);
}
function broadcastTv(deptId, payload) {
  // Always include typeColors and typeNames in state messages
  var enriched = payload;
  if (payload && payload.type === "state") {
    var s = getSettings();
    enriched = Object.assign({}, payload, {
      typeColors: s.typeColors || {},
      typeNames:  s.typeNames  || {},
      colors:     s.colors     || {},
    });
  }
  // Settings changes of a department («state», «refresh») also go to its group screens;
  // event lists and the active event are per channel
  var toGroups = payload && (payload.type === "state" || payload.type === "refresh") && String(deptId).indexOf("~") < 0;
  tvClients.forEach(function(client) {
    if (client.deptId === deptId || (toGroups && String(client.deptId).indexOf(deptId + "~") === 0)) {
      try { client.res.write("data: " + JSON.stringify(enriched) + "\n\n"); } catch(e) {}
    }
  });
}
function getTvState(deptId) {
  return tvState.get(deptId) || {
    mode: "events",
    slides: [],
    slideInterval: 15,
    showEvents: true,
    eventCount: 5,
    slideOrder: "sequential",
    showLogo: true,
    ticker: "",
    progressColor: "",    // empty = use accent color
  };
}

