function broadcastDisplay(evId, payload) {
  if (payload && (payload.presentations || payload.slideDocs)) { payload = Object.assign({}, payload); delete payload.presentations; delete payload.slideDocs; } // admin-only data
  displayClients.forEach(function(client) {
    if (client.evId === evId) {
      try { client.res.write("data: " + JSON.stringify(payload) + "\n\n"); } catch(e) {}
    }
  });
}

