// ── Storage helpers ──────────────────────────────────────────────
// Previously every readJSON/writeJSON call did a *synchronous* fs.readFileSync/
// writeFileSync — which blocks Node's entire single-threaded event loop, not
// just the current request. Under real concurrent traffic (many requests at
// once, growing file sizes), that means every other in-flight request stalls
// behind whichever one is doing disk I/O at that moment.
//
// This keeps an in-memory cache of each file's parsed contents:
//   - reads become pure memory access after the first load — no disk I/O at all
//   - writes update the in-memory copy synchronously (so within a single
//     request, read-modify-write still behaves exactly as before — nothing
//     downstream needs to change) and are persisted to disk asynchronously,
//     debounced per-file so a burst of writes to the same file coalesces into
//     one disk write instead of many.
// A graceful-shutdown handler flushes anything still pending before the
// process actually exits, so a redeploy/restart can't silently drop the last
// few hundred ms of writes.
const _jsonCache      = new Map();  // absolute path -> parsed data (live reference)
const _pendingFlushes = new Map();  // absolute path -> timer handle
const _flushing        = new Set(); // paths currently being written, to avoid overlapping writes to the same file

function _flushJSON(f) {
  _pendingFlushes.delete(f);
  if (_flushing.has(f)) { _pendingFlushes.set(f, setImmediate(function(){ _flushJSON(f); })); return; }
  if (!_jsonCache.has(f)) return;
  _flushing.add(f);
  const data = _jsonCache.get(f);
  const tmp = f + ".tmp";
  const _t0 = Date.now();
  const body = JSON.stringify(data, null, 2);
  const _ms = Date.now() - _t0;
  if (_ms >= 100) {
    console.warn("[perf] Serialising " + path.basename(f) + " (" + (Buffer.byteLength(body) / 1048576).toFixed(1) + " MB) blocked the server for " + _ms + " ms");
  }
  fs.writeFile(tmp, body, function(err) {
    if (err) { console.error("[writeJSON] Failed writing " + tmp + ": " + err.message); _flushing.delete(f); return; }
    fs.rename(tmp, f, function(err2) {
      _flushing.delete(f);
      if (err2) console.error("[writeJSON] Failed renaming " + tmp + " -> " + f + ": " + err2.message);
    });
  });
}

const readJSON = function(f) {
  if (_jsonCache.has(f)) return _jsonCache.get(f);
  let data;
  try { data = JSON.parse(fs.readFileSync(f)); } catch(e) { data = []; }
  _jsonCache.set(f, data);
  return data;
};

const writeJSON = function(f, d) {
  _jsonCache.set(f, d);
  if (!_pendingFlushes.has(f)) {
    _pendingFlushes.set(f, setImmediate(function(){ _flushJSON(f); }));
  }
};

// Force any in-memory changes to disk right now, synchronously — used on
// shutdown so a restart/redeploy never loses a write that was still pending.
function flushAllJSONSync() {
  for (const [f, data] of _jsonCache) {
    try {
      const tmp = f + ".tmp";
      fs.writeFileSync(tmp, JSON.stringify(data, null, 2));
      fs.renameSync(tmp, f);
    } catch(e) { console.error("[flushAllJSONSync] Failed for " + f + ": " + e.message); }
  }
}
['SIGTERM', 'SIGINT'].forEach(function(sig) {
  process.on(sig, function() {
    console.log("[shutdown] " + sig + " received, flushing pending writes…");
    flushAllJSONSync();
    process.exit(0);
  });
});

// ── XSS-beskyttelse ───────────────────────────────────────────────
function isoWeek(d) {
  var date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
  var yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil((((date - yearStart) / 86400000) + 1) / 7);
}

function escHtml(s) {
  if (s == null) return "";
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#x27;");
}

// Server-side input sanitizer — strips script tags and event handlers
function sanitizeInput(s) {
  if (typeof s !== "string") return s;
  return s
    .replace(/<script[\s\S]*?<\/script>/gi, "")
    .replace(/on[a-z]+\s*=[^>]*/gi, "")
    .replace(/javascript\s*:/gi, "");
}

function sanitizeBody(obj) {
  if (!obj || typeof obj !== "object") return obj;
  var out = Array.isArray(obj) ? [] : {};
  Object.keys(obj).forEach(function(k) {
    var v = obj[k];
    if (typeof v === "string") out[k] = sanitizeInput(v);
    else if (v && typeof v === "object") out[k] = sanitizeBody(v);
    else out[k] = v;
  });
  return out;
}

