// ── Server-side i18n for API error/status messages ──────────────────────────
// English is the canonical source language in the codebase (so the project is
// readable to any developer, not just Norwegian speakers). Norwegian and
// Swedish are translations layered on top; if a key is missing in the active
// language, it silently falls back to English rather than showing nothing.
// Frontend sends the active UI language via the "X-Lang" request header
// (see api() in index.html); if absent/unrecognized, English is used.
//
// NB: this is being migrated in incrementally — not every hardcoded message
// in the codebase goes through st() yet. Messages not yet migrated remain as
// plain literals (still functional, just not multi-language yet).
function serverLang(req) {
  const l = (req && req.headers && (req.headers["x-lang"] || req.headers["X-Lang"])) || "en";
  return SERVER_I18N[l] ? l : "en";
}
function st(key, req, vars) {
  const lang = serverLang(req);
  let str = (SERVER_I18N[lang] && SERVER_I18N[lang][key]) || SERVER_I18N.en[key] || key;
  if (vars) Object.keys(vars).forEach(function(k) {
    str = str.replace(new RegExp("\\{" + k + "\\}", "g"), vars[k]);
  });
  return str;
}

// ══════════════════════════════════════════════════════════════════
// TRANSLATION OVERLAY
// ------------------------------------------------------------------
// All source text in this codebase is written in English. Other
// languages exist only as a translation applied on the way OUT to the
// user's screen, in whichever language that user selected.
//
// Usage:            tr("Save", req)          -> "Lagre" for a Norwegian user
// With variables:   tr("Full - {n} left", req, { n: 3 })
//
// Look-up is keyed on the ENGLISH SOURCE STRING itself, so the code
// stays readable to someone who speaks no Norwegian or Swedish: what
// you read in the source is exactly what an English user sees. If a
// string has no entry for the requested language, the English source
// is returned unchanged — a missing translation degrades to English,
// never to a blank or a raw key.
//
// TRANSLATIONS below is DATA, not code. It is the one place in the
// backend where non-English text is allowed to appear.
// ══════════════════════════════════════════════════════════════════

