function _privacyEmailProvider() {
  const h = String(process.env.SMTP_HOST || "").toLowerCase();
  if (/runbox/.test(h)) return "Runbox (Norge)";
  if (!h) return null;
  return h.replace(/^(smtp|mail|mx)\d*\./, "");
}

function servePrivacyPage(dept, ev, req, res) {
  const settings = getSettings();
  let L = String(req.query.lang || "").slice(0, 2);
  if (!_PRIV_TXT[L]) L = ev && _PRIV_TXT[ev.lang] ? ev.lang : (typeof _deptPageLang === "function" ? _deptPageLang(req) : "no");
  if (!_PRIV_TXT[L]) L = "no";
  const T = function(k, v) { const s0 = _PRIV_TXT[L][k] || _PRIV_TXT.no[k] || k; return v === undefined ? s0 : s0.replace(/\{[a-z]\}/g, v); };
  const d = dept || {};
  const orgName = d.legalName || settings.legalName || d.displayName || d.name || settings.siteName || "Event-Admin";
  const orgNo = d.orgNumber || settings.orgNumber || "";
  // A group (subgroup) can have its own contact details; each field falls back to the department
  const g = (ev && ev.subgroup && (d.subgroups || []).find(function(x) { return x.id === ev.subgroup; })) || {};
  const contactName = g.privacyContactName || d.privacyContactName || "";
  const email = g.privacyEmail || d.privacyEmail || g.contactEmail || d.contactEmail || settings.contactEmail || "";
  const phone = g.phone || d.phone || "";
  const accent = (d.appearance && d.appearance.accent) || (settings.colors && settings.colors.accent) || "#FFD100";
  const sms = (settings.sms && settings.sms.provider) || "none";
  const smsName = sms === "sveve" ? "Sveve (Norge)" : sms === "twilio" ? "Twilio (USA)" : "";
  const emailProv = _privacyEmailProvider() || (L === "en" ? "our email provider" : L === "sv" ? "vår e-postleverantör" : "vår e-postleverandør");
  const aiOn = getAIConfig().configured;
  const aiPhotos = getAIConfig().sendPhotos;
  const backHref = ev ? "/" : "/";
  const updatedTxt = new Date(PRIVACY_PAGE_UPDATED + "T12:00:00").toLocaleDateString({ no: "nb-NO", sv: "sv-SE", en: "en-GB" }[L], { day: "numeric", month: "long", year: "numeric" });
  const e = escHtml;
  const sec = function(h, body) { return '<section><h2>' + e(h) + '</h2>' + body + '</section>'; };
  const groups = ["reg", "int", "vol", "mem", "gb", "vis"].map(function(g) {
    return '<li><strong>' + e(T("g_" + g)) + '.</strong> ' + e(T("g_" + g + "_txt")) + '</li>';
  }).join("");
  const contactRows = '<dl>'
    + '<dt>' + e(T("controller")) + '</dt><dd>' + e(orgName) + (orgNo ? ' · ' + e(T("orgno")) + ' ' + e(orgNo) : '') + '</dd>'
    + ((contactName || email || phone) ? '<dt>' + e(T("contact")) + '</dt><dd>' + [contactName ? e(contactName) : '', email ? '<a href="mailto:' + e(email) + '">' + e(email) + '</a>' : '', phone ? '<a href="tel:' + e(phone.replace(/\s/g, "")) + '">' + e(phone) + '</a>' : ''].filter(Boolean).join(' · ') + '</dd>' : '')
    + '<dt>' + e(T("processor")) + '</dt><dd>' + e(T("processor_txt")) + '</dd>'
    + '</dl>';
  const body =
      '<p class="lead">' + e(T("lead")) + '</p>'
    + sec(T("h_who"), contactRows)
    + sec(T("h_what"), '<ul>' + groups + '</ul>')
    + sec(T("h_keep"), '<p>' + e(T("keep_reg", String(getRetentionDays()))) + '</p><p>' + e(T("keep_other")) + '</p>')
    + sec(T("h_share"), '<p>' + e(T("share_1")) + '</p><ul><li>' + e(T("share_email", emailProv)) + '</li><li>' + e(smsName ? T("share_sms_on", smsName) : T("share_sms_off")) + '</li></ul><p>' + e(T("share_2")) + '</p>')
    + (aiOn ? sec(T("h_ai"), '<p>' + e(T("ai_txt")) + '</p><p>' + e(aiPhotos ? T("ai_photos_on") : T("ai_photos_off")) + '</p>') : '')
    + sec(T("h_cookies"), '<p>' + e(T("cookies_txt")) + '</p><ul><li><code>events_sid</code> – ' + e(T("c1")) + '</li><li><code>minside_remember</code> – ' + e(T("c2")) + '</li><li><code>minside_wait</code> – ' + e(T("c3")) + '</li></ul>')
    + sec(T("h_sec"), '<p>' + e(T("sec_txt")) + '</p>')
    + sec(T("h_rights"), '<p>' + e(T("rights_lead")) + '</p><ul>' + ["r1", "r2", "r3", "r4", "r5", "r6"].map(function(k) { return '<li>' + e(T(k)) + '</li>'; }).join("") + '</ul>'
        + '<p>' + (email ? e(T("ask")) + ' <a href="mailto:' + e(email) + '">' + e(email) + '</a>.' : e(T("ask_none"))) + '</p>'
        + '<p>' + e(T("complain")) + ' <a href="https://www.datatilsynet.no" rel="noopener">' + e(T("dpa_no")) + '</a>' + (L === "sv" ? ' / <a href="https://www.imy.se" rel="noopener">' + e(T("dpa_sv")) + '</a>' : '') + '.</p>');
  res.setHeader("Content-Type", "text/html; charset=utf-8");
  res.setHeader("Cache-Control", "no-cache");
  res.send(_legalPageHtml(L, { title: T("title"), sub: T("sub"), orgName: orgName, accent: accent,
    backHref: backHref, backLabel: d.displayName || d.name || settings.siteName || T("back"),
    updatedLabel: T("updated"), updatedTxt: updatedTxt, body: body }));
}

// Shared layout for the public privacy and accessibility pages
function _legalPageHtml(L, o) {
  const e = escHtml;
  const langLinks = ["no", "sv", "en"].map(function(x) {
    return x === L ? '<span aria-current="true">' + x.toUpperCase() + '</span>' : '<a href="?lang=' + x + '" hreflang="' + (x === "no" ? "nb" : x) + '">' + x.toUpperCase() + '</a>';
  }).join(" · ");
  const html = '<!DOCTYPE html><html lang="' + (L === "no" ? "nb" : L) + '"><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width,initial-scale=1">'
    + '<meta name="robots" content="index,follow">'
    + '<title>' + e(o.title) + ' – ' + e(o.orgName) + '</title>'
    + '<style>'
    + '*{box-sizing:border-box}body{margin:0;background:#F6F5F1;color:#1A1A1A;font:16px/1.6 system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif}'
    + 'a{color:#1A4FA0}a:focus-visible{outline:3px solid ' + e(o.accent) + ';outline-offset:2px}'
    + '.top{background:#fff;border-bottom:3px solid ' + e(o.accent) + '}.top-in{max-width:760px;margin:0 auto;padding:14px 20px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}'
    + '.top a.back{font-weight:600;text-decoration:none;color:#1A1A1A}.langs{font-size:14px;color:#5F6368}.langs a{color:#1A1A1A}'
    + 'main{max-width:760px;margin:0 auto;padding:28px 20px 60px}h1{font-size:30px;line-height:1.2;margin:0 0 4px}'
    + '.sub{color:#5F6368;margin:0 0 4px}.upd{color:#5F6368;font-size:14px;margin:0 0 24px}'
    + '.lead{font-size:18px;background:#fff;border:1px solid #E6E4DC;border-left:4px solid ' + e(o.accent) + ';border-radius:10px;padding:14px 18px}'
    + 'section{background:#fff;border:1px solid #E6E4DC;border-radius:12px;padding:6px 20px 14px;margin-top:16px}'
    + 'h2{font-size:20px;margin:14px 0 6px}ul{padding-left:20px;margin:6px 0}li{margin:6px 0}'
    + 'dl{margin:6px 0;display:grid;grid-template-columns:minmax(140px,max-content) 1fr;gap:6px 16px}dt{font-weight:600}dd{margin:0}'
    + '@media(max-width:560px){dl{grid-template-columns:1fr}dd{margin-bottom:8px}}'
    + 'code{background:#F1EFE8;padding:1px 6px;border-radius:4px;font-size:14px}'
    + '</style></head><body>'
    + '<header class="top"><div class="top-in"><a class="back" href="' + o.backHref + '">← ' + e(o.backLabel) + '</a>'
    + '<nav class="langs" aria-label="Language">' + langLinks + '</nav></div></header>'
    + '<main id="main"><h1>' + e(o.title) + '</h1><p class="sub">' + e(o.sub) + ' – ' + e(o.orgName) + '</p>'
    + '<p class="upd">' + e(o.updatedLabel) + ': ' + e(o.updatedTxt) + '</p>'
    + o.body + '</main></body></html>';
  return html;
}

