function serveAccessibilityPage(dept, ev, req, res) {
  const settings = getSettings();
  let L = String(req.query.lang || "").slice(0, 2);
  if (!_A11Y_TXT[L]) L = ev && _A11Y_TXT[ev.lang] ? ev.lang : (typeof _deptPageLang === "function" ? _deptPageLang(req) : "no");
  if (!_A11Y_TXT[L]) L = "no";
  const T = function(k) { return _A11Y_TXT[L][k] || _A11Y_TXT.no[k] || k; };
  const e = escHtml;
  const d = dept || {};
  const orgName = d.legalName || settings.legalName || d.displayName || d.name || settings.siteName || "Event-Admin";
  const g = (ev && ev.subgroup && (d.subgroups || []).find(function(x) { return x.id === ev.subgroup; })) || {};
  const email = g.accessibilityEmail || d.accessibilityEmail || g.contactEmail || d.privacyEmail || d.contactEmail || settings.contactEmail || "";
  const phone = g.phone || d.phone || "";
  const uustatus = /^https:\/\/(www\.)?uustatus\.no\//i.test(d.uustatusUrl || "") ? d.uustatusUrl : "";
  const accent = (d.appearance && d.appearance.accent) || (settings.colors && settings.colors.accent) || "#FFD100";
  const sec = function(h, inner) { return '<section><h2>' + e(h) + '</h2>' + inner + '</section>'; };
  const list = function(keys) { return '<ul>' + keys.map(function(k) { return '<li>' + e(T(k)) + '</li>'; }).join("") + '</ul>'; };
  const link = function(href, label) { return '<a href="' + href + '" rel="noopener">' + e(label) + '</a>'; };
  const bodies = L === "sv"
    ? [link("https://www.digg.se/tdosanmalan", "DIGG"), link("https://www.do.se", "Diskrimineringsombudsmannen (DO)"), link("https://www.uutilsynet.no", "Uutilsynet"), link("https://www.diskrimineringsnemnda.no", "Diskrimineringsnemnda")]
    : [link("https://www.uutilsynet.no", "Uutilsynet"), link("https://www.diskrimineringsnemnda.no", "Diskrimineringsnemnda"), link("https://www.ldo.no", L === "en" ? "Equality and Anti-Discrimination Ombud (LDO)" : "Likestillings- og diskrimineringsombudet")]
      .concat(L === "en" ? [link("https://www.digg.se/tdosanmalan", "DIGG (Sweden)"), link("https://www.do.se", "DO (Sweden)")] : []);
  const contact = (email || phone)
    ? '<p>' + [email ? '<a href="mailto:' + e(email) + '">' + e(email) + '</a>' : '', phone ? '<a href="tel:' + e(phone.replace(/\s/g, "")) + '">' + e(phone) + '</a>' : ''].filter(Boolean).join(' · ') + '</p>'
    : '<p>' + e(T("feedback_none")) + '</p>';
  const body =
      '<p class="lead">' + e(T("lead")) + '</p>'
    + (uustatus ? '<section><p><strong>' + e(T("official")) + '</strong><br><a href="' + e(uustatus) + '" rel="noopener">' + e(T("official_link")) + '</a></p></section>' : '')
    + sec(T("h_scope"), '<p>' + e(T("scope")) + '</p>')
    + sec(T("h_status"), '<p>' + e(T("status")) + '</p>')
    + sec(T("h_done"), list(["d1", "d2", "d3", "d4", "d5", "d6", "d7"]))
    + sec(T("h_known"), list(["k1", "k2", "k3", "k4"]))
    + sec(T("h_test"), '<p>' + e(T("test")) + '</p>')
    + sec(T("h_feedback"), '<p>' + e(T("feedback")) + '</p>' + contact)
    + sec(T("h_complain"), '<p>' + e(T("complain")) + '</p><ul>' + bodies.map(function(b) { return '<li>' + b + '</li>'; }).join("") + '</ul>');
  const testedTxt = new Date(A11Y_TESTED + "T12:00:00").toLocaleDateString({ no: "nb-NO", sv: "sv-SE", en: "en-GB" }[L], { day: "numeric", month: "long", year: "numeric" });
  res.setHeader("Content-Type", "text/html; charset=utf-8");
  res.setHeader("Cache-Control", "no-cache");
  res.send(_legalPageHtml(L, { title: T("title"), sub: T("sub"), orgName: orgName, accent: accent, backHref: "/",
    backLabel: d.displayName || d.name || settings.siteName || T("back"), updatedLabel: T("updated"), updatedTxt: testedTxt, body: body }));
}

