app.get("/cdn-cgi/*", function(req, res) { res.status(204).end(); });
app.use("/static", express.static(path.join(__dirname, "static")));
// Session store - file-based so sessions survive a restart
var sessionStore;
try {
  var FileStore = require("session-file-store")(session);
  var sessionDir = path.join(DATA, "sessions");
  if (!fs.existsSync(sessionDir)) fs.mkdirSync(sessionDir, { recursive: true });
  sessionStore = new FileStore({
    path:        sessionDir,
    ttl:         Math.ceil(((parseFloat(process.env.SESSION_MAX_DAYS) || 7) * 86400)),
    retries:     1,
    reapInterval: 86400,
    touchAfter:  3600,
    logFn:       function(){},
  });
  console.log("[session] Fil-basert session store: " + sessionDir);
} catch(e) {
  console.warn("[session] session-file-store ikke tilgjengelig, bruker MemoryStore:", e.message);
  sessionStore = undefined;
}

// Admin and manager logins: logged out after 12 hours without activity, and
// after 7 days in any case (env: SESSION_IDLE_HOURS, SESSION_MAX_DAYS).
const SESSION_IDLE_MS = (parseFloat(process.env.SESSION_IDLE_HOURS) || 12) * 3600000;
const SESSION_MAX_MS  = (parseFloat(process.env.SESSION_MAX_DAYS) || 7) * 86400000;
app.use(session({
  name:  "events_sid",
  store: sessionStore,
  secret: SECRET,
  resave: false,
  saveUninitialized: false,
  rolling: true,
  cookie: {
    secure:   process.env.NODE_ENV === "production" ? "auto" : false,
    sameSite: "lax",
    maxAge:   SESSION_IDLE_MS,  // idle timeout; rolling renews it on every request
    httpOnly: true,
  }
}));
// ── BODY LIMITS ── Anonymous requests: 1 MB (sign-ups, check-ins, guestbook).
// Logged-in users: 50 MB (images as data URLs, imports). A few public routes
// that carry photos or logs get 15 MB. Real file uploads use multipart (multer).
const _BODY_PUBLIC_LARGE = ["/api/minside/", "/api/pi/", "/api/tv-job-logs", "/api/forms/", "/api/eval/"];
const _bodyParsers = {};
function _bodyParser(limit) {
  if (!_bodyParsers[limit]) _bodyParsers[limit] = [express.json({ limit: limit }), express.urlencoded({ extended: true, limit: limit })];
  return _bodyParsers[limit];
}
app.use(function(req, res, next) {
  let limit = "1mb";
  if (req.session && req.session.user) limit = "50mb";
  else if (_BODY_PUBLIC_LARGE.some(function(p) { return req.path.indexOf(p) === 0; }) || /^\/api\/events\/[^/]+\/sync$/.test(req.path)) limit = "15mb";
  const pr = _bodyParser(limit);
  pr[0](req, res, function(err) {
    if (err) return res.status(err.status || 400).json({ error: err.type === "entity.too.large" ? "Request too large" : "Invalid request body" });
    pr[1](req, res, function(err2) {
      if (err2) return res.status(err2.status || 400).json({ error: err2.type === "entity.too.large" ? "Request too large" : "Invalid request body" });
      next();
    });
  });
});

// Absolute lifetime: a login lasts at most SESSION_MAX_MS, however active.
// Sessions from before this change get their clock started now.
app.use(function(req, res, next) {
  const s = req.session;
  if (!s || !s.user) return next();
  const now = Date.now();
  if (!s.loginAt) s.loginAt = now;
  // Idle check on the server too (a copied cookie must not outlive the idle limit).
  // lastSeen is written at most every 10 minutes to keep session-file writes low.
  const idle = s.lastSeen && now - s.lastSeen > SESSION_IDLE_MS;
  if (!s.lastSeen || now - s.lastSeen > Math.min(600000, SESSION_IDLE_MS / 4)) s.lastSeen = now;
  if (idle || now - s.loginAt > SESSION_MAX_MS) {
    return s.destroy(function() {
      res.clearCookie("events_sid");
      if (req.path.indexOf("/api/") === 0) return res.status(401).json({ error: st("session_expired", req), sessionExpired: true });
      next();
    });
  }
  next();
});

// File type validation for uploads
const ALLOWED_IMAGE_TYPES = ["image/jpeg", "image/png", "image/gif", "image/webp"];
const upload = multer({
  dest: UPLOADS,
  limits: { fileSize: 80 * 1024 * 1024 },
  fileFilter: function(req, file, cb) {
    if (ALLOWED_IMAGE_TYPES.indexOf(file.mimetype) === -1) {
      return cb(new Error("Kun bilder er tillatt (jpeg, png, gif, webp)"));
    }
    cb(null, true);
  }
});

const zlib = require("zlib");

// ── JSON response compression ─────────────────────────────────────
// API payloads were sent uncompressed. Event lists and settings are highly
// repetitive JSON, so gzip/brotli typically cuts them by 80-90%. Small
// bodies are left alone: below ~1 KB the header overhead outweighs the gain.
// Compression runs on libuv's threadpool, never on the event loop. The
// synchronous variants block the single thread for the whole compress, which
// under load stalls every other in-flight request and shows up as connection
// resets rather than slow responses.
//
// Public HTML (res.send) is covered too: department and event pages were going
// out uncompressed entirely.
const _COMPRESS_MIN = 1024;

function _pickEncoding(req) {
  const a = String(req.headers["accept-encoding"] || "");
  if (/\bbr\b/.test(a))   return "br";
  if (/\bgzip\b/.test(a)) return "gzip";
  return null;
}

// Identical responses are extremely common here: the department page is served
// from a page cache, so without this every request would recompress byte-for-byte
// identical HTML. Keyed on a hash of the body plus the encoding.
const _czCache = new Map();
const _CZ_MAX = 200;

function _czKey(payload, encoding) {
  return encoding + ":" + payload.length + ":" +
    require("crypto").createHash("sha1").update(payload).digest("hex").slice(0, 16);
}

// Compress and send, off the event loop. Falls back to the raw body on any
// error so a compression failure can never lose a response.
function _sendCompressed(res, payload, encoding, contentType) {
  res.setHeader("Content-Type", contentType);
  res.setHeader("Vary", "Accept-Encoding");
  if (!encoding || payload.length < _COMPRESS_MIN) return res.end(payload);

  const key = _czKey(payload, encoding);
  const hit = _czCache.get(key);
  if (hit) {
    res.setHeader("Content-Encoding", encoding);
    res.setHeader("Content-Length", hit.length);
    return res.end(hit);
  }

  const done = function(err, out) {
    if (err || !out) { res.removeHeader("Content-Encoding"); return res.end(payload); }
    if (_czCache.size >= _CZ_MAX) _czCache.delete(_czCache.keys().next().value);
    _czCache.set(key, out);
    res.setHeader("Content-Encoding", encoding);
    res.setHeader("Content-Length", out.length);
    res.end(out);
  };
  try {
    if (encoding === "br") {
      return zlib.brotliCompress(payload, {
        params: {
          [zlib.constants.BROTLI_PARAM_QUALITY]: 4,
          [zlib.constants.BROTLI_PARAM_SIZE_HINT]: payload.length,
        },
      }, done);
    }
    return zlib.gzip(payload, { level: 5 }, done);
  } catch (e) {
    res.removeHeader("Content-Encoding");
    return res.end(payload);
  }
}

// ── Performance diagnostics ───────────────────────────────────────
// Node runs on one thread: any synchronous work (big JSON.stringify, sync
// file copies, sync child processes, heavy loops) freezes EVERY request
// until it finishes. These two logs make such stalls visible:
//   [perf] Event loop blocked …  – the server could not respond at all;
//                                  lists the requests that were in flight
//   [perf] Slow request …        – a single request took > PERF_SLOW_MS
// Tune with PERF_SLOW_MS (default 2000) and PERF_BLOCK_MS (default 300).
const _PERF_SLOW_MS  = parseInt(process.env.PERF_SLOW_MS, 10)  || 2000;
const _PERF_BLOCK_MS = parseInt(process.env.PERF_BLOCK_MS, 10) || 300;
const _inFlight = new Set();
app.use(function(req, res, next) {
  const item = { m: req.method, u: String(req.originalUrl || req.url).split("?")[0].slice(0, 120), t: Date.now() };
  _inFlight.add(item);
  let done = false;
  const finish = function() {
    if (done) return; done = true;
    _inFlight.delete(item);
    const ms = Date.now() - item.t;
    // Long-lived streams (SSE, media downloads) are expected to run long
    const ct = String(res.getHeader("Content-Type") || "");
    if (ms >= _PERF_SLOW_MS && !/event-stream|application\/zip|video\//.test(ct)) {
      console.warn("[perf] Slow request " + item.m + " " + item.u + " " + ms + " ms (status " + res.statusCode + ")");
    }
  };
  res.on("finish", finish);
  res.on("close", finish);
  next();
});
(function startEventLoopWatchdog() {
  const TICK = 250;
  let last = Date.now();
  setInterval(function() {
    const now = Date.now();
    const lag = now - last - TICK;
    last = now;
    if (lag >= _PERF_BLOCK_MS) {
      const busy = Array.from(_inFlight)
        .filter(function(r) { return now - r.t >= lag; })
        .slice(0, 8)
        .map(function(r) { return r.m + " " + r.u; });
      console.warn("[perf] Event loop blocked for " + lag + " ms" +
        (busy.length ? " – in flight: " + busy.join(", ") : " – no request in flight (a timer/background job)"));
    }
  }, TICK).unref();
})();

app.use(function(req, res, next) {
  const origJson = res.json.bind(res);
  const origSend = res.send.bind(res);

  res.json = function(body) {
    let payload;
    try { payload = Buffer.from(JSON.stringify(body), "utf8"); }
    catch (e) { return origJson(body); }
    return _sendCompressed(res, payload, _pickEncoding(req), "application/json; charset=utf-8");
  };

  // Public pages (department, event, overview, TV) go out through res.send as
  // HTML strings. These were the only large responses with no compression at
  // all - a department page is tens of KB of highly repetitive markup.
  res.send = function(body) {
    if (typeof body !== "string" || res.getHeader("Content-Encoding")) return origSend(body);
    const ct = res.getHeader("Content-Type");
    if (ct && !/text\/html|text\/plain|application\/json|text\/css|javascript/i.test(String(ct))) {
      return origSend(body);
    }
    const payload = Buffer.from(body, "utf8");
    if (payload.length < _COMPRESS_MIN) return origSend(body);
    return _sendCompressed(res, payload, _pickEncoding(req),
      String(ct || "text/html; charset=utf-8"));
  };

  next();
});

// Every HTML page sent with res.send (public pages, Min side, walk-in, loan pages…)
// gets the accessibility layer. The admin app (index.html) is sent as a file and is not touched.
app.use(function(req, res, next) {
  if (req.path.startsWith("/api")) return next();
  const _send = res.send;
  res.send = function(body) {
    if (typeof body === "string" && body.length < 8000000 && /^\s*<!doctype html/i.test(body)) {
      body = a11yInject(body);
      // Tab icon for public pages (they had none): group → department → main logo
      if (!/<link[^>]+rel=["']?(?:shortcut )?icon/i.test(body)) {
        const f = res.locals.favicon || {};
        const tag = '<link rel="icon" type="image/svg+xml" href="' + _faviconHref(f.dept, f.sg) + '"/>';
        const hi = body.search(/<\/head>/i);
        if (hi !== -1) body = body.slice(0, hi) + tag + body.slice(hi);
      }
    }
    return _send.call(this, body);
  };
  next();
});

// ── Subdomain → event page (MUST be before express.static) ────────
app.use(function(req, res, next) {
  if (req.path.startsWith("/api") || req.path === "/viewer" || req.path === "/hold" || req.path === "/agent" || req.path.startsWith("/uploads") || req.path.startsWith("/avmeld") || req.path.startsWith("/static") || req.path.startsWith("/gb-photo") || req.path.startsWith("/gb-photos") || req.path.startsWith("/logo") || req.path.startsWith("/tv") || req.path.startsWith("/display") || req.path.startsWith("/dept-thumb") || req.path.startsWith("/sw.js")) return next();

  const host = (req.headers["x-forwarded-host"] || req.hostname || "").split(",")[0].trim().toLowerCase();

  // Reserved subdomains that should not be treated as event slugs
  const RESERVED = ["sso", "www", "mail", "smtp", "ftp", "api"];
  if (host === ADMIN_DOMAIN || host === DOMAIN || host === "www." + DOMAIN) return next();
  const sub0 = host.split(".")[0];
  if (RESERVED.indexOf(sub0) !== -1) return next();

  var slug = null;
  var domains = [DOMAIN];
  try {
    var s = getSettings();
    if (s.eventDomain && domains.indexOf(s.eventDomain) === -1) domains.push(s.eventDomain);
  } catch(e) {}

  for (var i = 0; i < domains.length; i++) {
    var d = domains[i];
    if (host === d || host === "www." + d) break;
    var sub = host.replace("." + d, "");
    if (sub && sub !== host && sub !== "www") { slug = sub; break; }
  }

  // Check for tv. subdomain → TV channel for department
  var tvDomain = process.env.TV_DOMAIN || ("tv." + DOMAIN);
  if (host === tvDomain) {
    // tv.* → redirect to dept picker or default dept
    var tvSettings = getSettings();
    var depts = tvSettings.departments || [];
    if (depts.length === 1) {
      var tvSlug = depts[0].slug || depts[0].id; return res.redirect("https://" + tvDomain + "/tv/" + tvSlug);
    }
    // Show dept picker
    var accentCol = (tvSettings.colors && tvSettings.colors.accent) || "#FFD100";
    return res.send("<!DOCTYPE html><html><head><meta charset='UTF-8'/><meta name='viewport' content='width=device-width,initial-scale=1'/><title>" + (tvSettings.siteName||"TV") + "</title>"
      + "<style>*{margin:0;padding:0;box-sizing:border-box}body{background:#0a0a0a;color:#fff;font-family:sans-serif;display:flex;align-items:center;justify-content:center;min-height:100vh;flex-direction:column;gap:1rem;padding:2rem}"
      + "a{display:block;background:" + accentCol + ";color:#111;font-weight:700;padding:1rem 2rem;border-radius:8px;text-decoration:none;font-size:1.1rem;text-align:center}"
      + "</style></head><body><h2 style='margin-bottom:1rem;color:" + accentCol + "'>" + (tvSettings.siteName||"TV") + "</h2>"
      + depts.map(function(d){ var tvSlug = d.slug || d.id; return "<a href='https://" + tvDomain + "/tv/" + escHtml(tvSlug) + "'>" + escHtml(d.displayName||d.name) + "</a>"; }).join("")
      + "</body></html>");
  }

  if (slug) {
    // Check if slug matches a department
    var settings = getSettings();
    var dept = (settings.departments || []).find(function(a) { return a.slug === slug; });
    if (dept) {
      // Check for /about path
      if (PRIVACY_PATHS.indexOf(req.path.replace(/\/$/, "")) !== -1) {
        return servePrivacyPage(dept, null, req, res);
      }
      if (A11Y_PATHS.indexOf(req.path.replace(/\/$/, "")) !== -1) {
        return serveAccessibilityPage(dept, null, req, res);
      }
      if (req.path === "/about") {
        return serveDepartmentAboutPage(dept, null, req, res);
      }
      // Check for /about/subgroup-id
      var aboutMatch = req.path.match(/^\/about\/(.+)$/);
      if (aboutMatch) {
        var sg = (dept.subgroups||[]).find(function(s){ return s.id === aboutMatch[1] || s.slug === aboutMatch[1]; });
        return serveDepartmentAboutPage(dept, sg || null, req, res);
      }
      // Loan item page: /<slug> (e.g. /child-seat). Only matches a slug that exists.
      var loanSlugMatch = req.path.match(/^\/([a-z0-9][a-z0-9-]{0,59})\/?$/);
      if (loanSlugMatch && LOAN_RESERVED_SLUGS.indexOf(loanSlugMatch[1]) === -1) {
        var loanItem = findLoanItemBySlug(dept.id, loanSlugMatch[1]);
        if (loanItem) return serveLoanPage(dept, loanItem, req, res);
      }
      try {
        const ua2 = (req.headers['user-agent'] || '').toLowerCase();
        const isBot2 = /bot|crawler|spider|crawl|slurp|facebookexternalhit|preview|lighthouse|pagespeed|headless|googlebot|bingbot|yandex|duckduckbot|semrush|ahrefsbot|dotbot|mj12bot|bytespider|petalbot|gptbot|claudebot|anthropic|curl\/|wget\/|python-requests|node-fetch|axios|go-http|java\/|okhttp/i.test(ua2);
        if (!isBot2) {
          const visits2 = readJSON(VISITS_FILE);
          const ip2     = clientIp(req);
          const day2    = new Date().toISOString().slice(0, 10);
          const vid2    = require('crypto').createHash('sha256').update(ip2 + '|' + day2 + '|' + (process.env.SESSION_SECRET || 'salt')).digest('hex').slice(0, 16);
          // Deduplicate dept page visits within 5 minutes
          const now300d = Date.now() - 300000;
          const isDupe2 = visits2.some(function(v) {
            return v.vid === vid2 && v.deptId === dept.id && new Date(v.ts).getTime() > now300d;
          });
          if (!isDupe2) {
            visits2.push({ deptId: dept.id, ts: new Date().toISOString(), ref: (req.headers['referer']||'').slice(0,80)||null, vid: vid2 });
          }
          if (visits2.length > 50000) visits2.splice(0, visits2.length - 50000);
          writeJSON(VISITS_FILE, visits2);
          if (STATS_DIR && !global._statsDebounce) {
            global._statsDebounce = setTimeout(function() { global._statsDebounce = null; writeStatsReport(); }, 5 * 60 * 1000);
          }
        }
      } catch(e) {}
      return serveDepartmentPage(dept, req, res);
    }
    // Reserved slug: departments index page (avdelinger./departments.)
    if (isDeptIndexSlug(slug) && PRIVACY_PATHS.indexOf(req.path.replace(/\/$/, "")) !== -1) return servePrivacyPage(null, null, req, res);
    if (isDeptIndexSlug(slug) && A11Y_PATHS.indexOf(req.path.replace(/\/$/, "")) !== -1) return serveAccessibilityPage(null, null, req, res);
    if (isDeptIndexSlug(slug)) return serveDeptIndexPage(req, res);
    if (PRIVACY_PATHS.indexOf(req.path.replace(/\/$/, "")) !== -1) {
      var pEv = readJSON(EVENTS_FILE).find(function(e) { return e.slug === slug; });
      if (pEv) {
        var pDept = (settings.departments || []).find(function(d) { return d.id === pEv.department; }) || null;
        return servePrivacyPage(pDept, pEv, req, res);
      }
    }
    if (A11Y_PATHS.indexOf(req.path.replace(/\/$/, "")) !== -1) {
      var aEv = readJSON(EVENTS_FILE).find(function(e) { return e.slug === slug; });
      if (aEv) {
        var aDept = (settings.departments || []).find(function(d) { return d.id === aEv.department; }) || null;
        return serveAccessibilityPage(aDept, aEv, req, res);
      }
    }
    req.eventSlug = slug;
    return serveEventPage(req, res);
  }
  next();
});

// ── Walk-in kiosk page — tablet-friendly registration for on-site signups ──
app.get("/walkin/:slug", function(req, res) {
  const events = readJSON(EVENTS_FILE);
  const ev = events.find(function(e) { return e.slug === req.params.slug; });
  if (!ev) return res.status(404).send("Event not found");
  const settings = getSettings();
  const lang = ev.lang || "no";
  const deptApp = getDeptAppearance(ev);
  const accent = deptApp.accent || "#FFD100";
  const regs = (ev.registrations || []).filter(function(r) { return !r.anonymized; });
  const spotsLeft = ev.maxParticipants ? ev.maxParticipants - regs.length : null;
  const isFull = spotsLeft !== null && spotsLeft <= 0;
  const typeLabel = getTypeLabel(ev.eventType, settings);
  res.send(`<!DOCTYPE html>
<html lang="${lang}">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<meta name="apple-mobile-web-app-capable" content="yes"/>
<title>${escHtml(ev.title)} – Walk-in</title>
<style>
*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
body{background:#0a0a0a;color:#fff;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;min-height:100vh;display:flex;flex-direction:column}
.header{background:${accent}18;border-bottom:3px solid ${accent};padding:1.25rem 1.5rem;display:flex;align-items:center;gap:1rem}
.header h1{font-size:1.4rem;font-weight:800;color:#fff;flex:1}
.header .badge{background:${accent};color:#111;font-size:.72rem;font-weight:800;padding:3px 10px;border-radius:20px;text-transform:uppercase;white-space:nowrap}
.counter{text-align:center;padding:.75rem;background:#111;border-bottom:1px solid #222;font-size:.9rem;color:#aaa}
.counter strong{color:${accent}}
.form-wrap{flex:1;padding:1.5rem;max-width:600px;margin:0 auto;width:100%;display:flex;flex-direction:column;gap:1.25rem}
label{font-size:.85rem;font-weight:700;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;display:block;margin-bottom:.4rem}
input,textarea,select{width:100%;background:#1a1a1a;border:2px solid #333;border-radius:10px;color:#fff;font-size:1.1rem;padding:.75rem 1rem;outline:none;transition:border-color .15s;-webkit-appearance:none}
input:focus,textarea:focus{border-color:${accent}}
input[type=submit],button.submit{width:100%;background:${accent};color:#111;font-weight:900;font-size:1.2rem;border:none;border-radius:12px;padding:1.1rem;cursor:pointer;margin-top:.5rem;transition:opacity .15s}
button.submit:active{opacity:.8}
button.submit:disabled{opacity:.4;cursor:not-allowed}
.gdpr{font-size:.72rem;color:var(--text2);text-align:center;padding:.5rem;line-height:1.5}
.success{display:none;flex:1;align-items:center;justify-content:center;flex-direction:column;gap:1rem;padding:2rem;text-align:center}
.success .check{font-size:5rem}
.success h2{font-size:1.8rem;font-weight:900;color:${accent}}
.success p{font-size:1rem;color:var(--text2);max-width:340px}
.success button{background:${accent};color:#111;font-weight:800;font-size:1rem;border:none;border-radius:10px;padding:.85rem 2rem;cursor:pointer;margin-top:.5rem}
.full{text-align:center;padding:3rem 1.5rem;flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1rem}
.full .icon{font-size:4rem}
.full h2{color:#f87171;font-size:1.5rem;font-weight:900}
.field-group{display:flex;flex-direction:column;gap:.35rem}
</style>
</head>
<body>
<div class="header">
  <div>
    <div class="badge">${escHtml(typeLabel)} \u00b7 Walk-in</div>
    <h1>${escHtml(ev.title)}</h1>
  </div>
</div>
${ev.showCount && ev.maxParticipants ? `<div class="counter">
  <strong>${regs.length}</strong> registered \u00b7 <strong>${Math.max(0, spotsLeft)}</strong> spots left
</div>` : ''}

${isFull ? `<div class="full">
  <div class="icon">🚫</div>
  <h2>Event is full</h2>
  <p>No more spots available. Please speak to an organizer.</p>
</div>` : `
<div class="form-wrap" id="formWrap">
  ${ev.regIntro ? `<p style="font-size:.9rem;color:var(--text2);line-height:1.6;background:#111;border-radius:8px;padding:.85rem 1rem;border:1px solid #222">${escHtml(ev.regIntro)}</p>` : ''}

  <div class="field-group">
    <label>Full name *</label>
    <input type="text" id="kiName" placeholder="Your name" autocomplete="name" autocapitalize="words" required/>
  </div>
  <div class="field-group">
    <label>Email <span style="color:#9a9a9a;font-weight:400;text-transform:none">(for confirmation)</span></label>
    <input type="email" id="kiEmail" placeholder="email@example.com" autocomplete="email"/>
  </div>
  <div class="field-group">
    <label>Phone <span style="color:#9a9a9a;font-weight:400;text-transform:none">(optional)</span></label>
    <input type="tel" id="kiPhone" placeholder="+47 000 00 000" autocomplete="tel"/>
  </div>

  <p id="kiErr" style="color:#f87171;font-size:.85rem;display:none;background:#2a0000;border:1px solid #7f1d1d;border-radius:8px;padding:.65rem 1rem"></p>

  <button class="submit" id="kiBtn" onclick="kiSubmit()">✅ Register</button>
  <p class="gdpr">🔒 Your information is used only to manage this event and is not shared with third parties.</p>
</div>

<div class="success" id="successWrap">
  <div class="check">✅</div>
  <h2>Registered!</h2>
  <p id="successMsg">You are now registered for ${escHtml(ev.title)}.</p>
  <button onclick="kiReset()">Register another person</button>
</div>
`}

<script>
var EV_SLUG = ${JSON.stringify(ev.slug)};
var EV_ID   = ${JSON.stringify(ev.id)};

async function kiSubmit() {
  var name  = document.getElementById('kiName').value.trim();
  var email = document.getElementById('kiEmail').value.trim();
  var phone = document.getElementById('kiPhone').value.trim();
  var err   = document.getElementById('kiErr');
  var btn   = document.getElementById('kiBtn');

  err.style.display = 'none';
  if (!name) { err.textContent = 'Please enter your name.'; err.style.display = ''; return; }
  if (email && !/^[^@]+@[^@]+\.[^@]+$/.test(email)) { err.textContent = 'Please enter a valid email address.'; err.style.display = ''; return; }

  btn.disabled = true; btn.textContent = 'Registering\u2026';

  try {
    var r = await fetch('/api/events/' + EV_ID + '/register', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, email: email || 'noemail@walkin.local', phone, walkin: true, lang: '${lang}' })
    });
    var d = await r.json();
    if (!r.ok || d.error) {
      err.textContent = d.error || 'Registration failed. Please try again.';
      err.style.display = '';
      btn.disabled = false; btn.textContent = '\u2705 Register';
      return;
    }
    // Success
    document.getElementById('formWrap').style.display = 'none';
    var sw = document.getElementById('successWrap');
    sw.style.display = 'flex';
    if (email && email !== 'noemail@walkin.local') {
      document.getElementById('successMsg').textContent = 'You are registered! A confirmation has been sent to ' + email + '.';
    }
  } catch(e) {
    err.textContent = 'Network error. Please try again.';
    err.style.display = '';
    btn.disabled = false; btn.textContent = '\u2705 Register';
  }
}

function kiReset() {
  document.getElementById('kiName').value  = '';
  document.getElementById('kiEmail').value = '';
  document.getElementById('kiPhone').value = '';
  document.getElementById('kiErr').style.display = 'none';
  document.getElementById('kiBtn').disabled = false;
  document.getElementById('kiBtn').textContent = '\u2705 Register';
  document.getElementById('successWrap').style.display = 'none';
  document.getElementById('formWrap').style.display = '';
  document.getElementById('kiName').focus();
}

// Auto-focus name field on load
document.addEventListener('DOMContentLoaded', function() {
  var n = document.getElementById('kiName');
  if (n) n.focus();
});
</script>
</body>
</html>`);
});


app.get("/sw.js", function(req, res) {
  res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate");
  res.setHeader("Content-Type", "application/javascript");
  const domain = DOMAIN;
  res.send(`
const SW_VERSION = "event-admin-v${(APP_VERSION || "1.0.0").replace(/\./g, "-")}";
const EVENT_CACHE = SW_VERSION + "-events";

// Install – skip waiting immediately, no precaching
self.addEventListener("install", function(e) {
  e.waitUntil(self.skipWaiting());
});

// Activate – delete ALL old caches, claim all clients
self.addEventListener("activate", function(e) {
  // self.registration.active is set when a previous SW existed before this one.
  // On a first-time install there is no previous active SW, so isUpdate is false.
  // We only send SW_UPDATED on real updates so the login page is not reloaded
  // on the very first visit when the SW is installed for the first time.
  const isUpdate = !!self.registration.active;
  e.waitUntil(
    caches.keys().then(function(keys) {
      return Promise.all(keys.map(function(k) { return caches.delete(k); }));
    }).then(function() {
      return self.clients.claim();
    }).then(function() {
      if (!isUpdate) return;
      return self.clients.matchAll({ type: "window" }).then(function(clients) {
        clients.forEach(function(c) { c.postMessage({ type: "SW_UPDATED" }); });
      });
    })
  );
});

// Fetch – ONLY intercept public event subdomain pages, never admin
self.addEventListener("fetch", function(e) {
  const url = new URL(e.request.url);
  // Pass through everything on the admin domain untouched
  if (url.hostname === "${ADMIN_DOMAIN}") return;
  // Only cache GET requests for public event pages and snapshots
  if (e.request.method !== "GET") return;
  const isEventPage = url.hostname.endsWith(".${domain}") && url.pathname === "/";
  const isSnapshot  = url.pathname.match(/^\\/api\\/events\\/[^/]+\\/snapshot$/);
  if (isEventPage || isSnapshot) {
    e.respondWith(
      fetch(e.request).then(function(res) {
        var clone = res.clone();
        caches.open(EVENT_CACHE).then(function(c) { c.put(e.request, clone); });
        return res;
      }).catch(function() {
        return caches.match(e.request);
      })
    );
  }
  // All other requests: don't intercept, let browser handle normally
});

// Message from page: precache upcoming event URLs
self.addEventListener("message", function(e) {
  if (e.data && e.data.type === "PRECACHE_EVENTS") {
    var urls = e.data.urls || [];
    caches.open(EVENT_CACHE).then(function(cache) {
      urls.forEach(function(url) {
        fetch(url).then(function(res) {
          if (res.ok) cache.put(url, res);
        }).catch(function() {});
      });
    });
  }
});
`);
});


