const COMFYUI_URL = process.env.COMFYUI_URL || "http://comfyui:8188";
// COMFYUI_CONTAINER and WHISPER_CONTAINER are defined in the GPU arbitration section above

// GET /api/comfyui/status — ping ComfyUI container
app.get("/api/comfyui/status", auth, async function(req, res) {
  const dockerSt = await dockerStatus(COMFYUI_CONTAINER).catch(function() { return { online: false }; });
  if (!dockerSt.online) {
    return res.json({ ok: false, containerRunning: false, error: "Container is stopped", gpuOwner: _gpuOwner });
  }
  try {
    const r = await fetch(COMFYUI_URL + "/system_stats", { signal: AbortSignal.timeout(3000) });
    if (!r.ok) return res.json({ ok: false, containerRunning: true, error: "HTTP " + r.status });
    const data = await r.json();
    res.json({
      ok: true, containerRunning: true,
      version: (data.system && data.system.comfyui_version) || "unknown",
      vram:    (data.devices && data.devices[0] && data.devices[0].vram_total) || null,
      gpuOwner: _gpuOwner
    });
  } catch(e) {
    res.json({ ok: false, containerRunning: true, error: e.message });
  }
});

// POST /api/comfyui/start — start ComfyUI (blocked if Whisper is busy)
app.post("/api/comfyui/start", auth, async function(req, res) {
  const canStart = await gpuCanComfyStart();
  if (!canStart.ok) {
    return res.status(503).json({ ok: false, whisperBusy: true, error: canStart.reason });
  }
  try {
    const r = await dockerStart(COMFYUI_CONTAINER);
    if (r.status === 204 || r.status === 304) {
      _gpuOwner = "comfyui";
      res.json({ ok: true, alreadyRunning: r.status === 304 });
    } else {
      res.status(500).json({ error: "Docker returned " + r.status });
    }
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// POST /api/comfyui/stop — stop ComfyUI container
app.post("/api/comfyui/stop", auth, async function(req, res) {
  try {
    const r = await dockerStop(COMFYUI_CONTAINER);
    _gpuOwner = null;
    res.json({ ok: true, status: r.status });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

