app.post("/api/active-session/ping", auth, function(req, res) {
  const sid = req.sessionID;
  const u   = req.session.user;
  if (sid && u) {
    _activeSessions.set(sid, {
      name:     u.name || u.email,
      email:    u.email,
      role:     u.role,
      loginAt:  (_activeSessions.get(sid) || {}).loginAt || new Date().toISOString(),
      lastSeen: new Date().toISOString(),
      ip:       clientIp(req),
    });
  }
  res.json({ ok: true });
});

app.get("/api/active-sessions", auth, adminOnly, function(req, res) {
  const cutoff = Date.now() - 10 * 60 * 1000;
  for (const [sid, s] of _activeSessions) {
    if (new Date(s.lastSeen).getTime() < cutoff) _activeSessions.delete(sid);
  }
  res.json(Array.from(_activeSessions.values()));
});

// delete ett image from gjestebokinnlegg (only admin/manager, before godkjenning)
app.delete("/api/events/:id/guestbook/:gid/photo/:photoIdx", auth, managerOrAdmin, function(req, res) {
  const events = readJSON(EVENTS_FILE);
  const evIdx  = events.findIndex(function(e) { return e.id === req.params.id; });
  if (evIdx === -1) return res.status(404).json({ error: st("not_found_generic", req) });
  const gb = (events[evIdx].guestbook || []).find(function(g) { return g.id === req.params.gid; });
  if (!gb) return res.status(404).json({ error: st("entry_not_found", req) });
  const photoIdx = parseInt(req.params.photoIdx);
  if (!gb.photos || !gb.photos[photoIdx]) return res.status(404).json({ error: st("image_not_found", req) });
  // delete file
  const photoPath = gb.photos[photoIdx].path || gb.photos[photoIdx];
  if (photoPath && typeof photoPath === "string") {
    const fullPath = path.join(DATA, "gb-photos", path.basename(photoPath));
    try { if (fs.existsSync(fullPath)) fs.unlinkSync(fullPath); } catch(e) {}
  }
  gb.photos.splice(photoIdx, 1);
  writeJSON(EVENTS_FILE, events);
  res.json({ ok: true, photos: gb.photos });
});
app.get("/api/guestbook/pending", auth, function(req, res) {
  const user   = req.session.user;
  const events = readJSON(EVENTS_FILE);
  const result = [];
  events.forEach(function(ev) {
    if (!ev.guestbook) return;
    // filter on access
    if (user.role !== "admin") {
      const access = getAccessList(user);
      if (access.length && !access.includes(ev.department)) return;
    }
    const pending = ev.guestbook.filter(function(g) { return !g.approved && !g.anonymized; });
    if (pending.length) {
      result.push({
        evId:      ev.id,
        evTitle:   ev.title || ev.slug,
        evSlug:    ev.slug,
        dept:      ev.department,
        eventType: ev.eventType || 'mote',
        entries:   pending.map(function(g) {
          return { id: g.id, name: g.name, message: g.message, createdAt: g.createdAt };
        }),
      });
    }
  });
  res.json(result);
});

