const LAB_CONTAINER = process.env.LAB_CONTAINER || "events-lab";
const LAB_DATA_DIR  = process.env.LAB_DATA_DIR  || "";  // /lab-data montert fra prod
const LAB_APP_DIR   = process.env.LAB_APP_DIR   || "";  // /lab-app montert fra prod
const DOCKER_SOCK   = "/var/run/docker.sock";
const STATS_DIR     = process.env.STATS_DIR     || "";  // Shared folder for stats reporting (e.g. /stats-report)

function dockerRestart(container) {
  return new Promise(function(resolve, reject) {
    if (!fs.existsSync(DOCKER_SOCK)) return reject(new Error("Docker socket ikke tilgjengelig – monter /var/run/docker.sock i docker-compose"));
    const opts = {
      socketPath: DOCKER_SOCK,
      path: "/containers/" + container + "/restart",
      method: "POST",
      headers: { "Content-Type": "application/json" },
    };
    const req = require("http").request(opts, function(r) {
      resolve({ status: r.statusCode });
    });
    req.on("error", reject);
    req.end();
  });
}

function dockerStart(container) {
  return new Promise(function(resolve, reject) {
    if (!fs.existsSync(DOCKER_SOCK)) return reject(new Error("Docker socket not available"));
    const opts = {
      socketPath: DOCKER_SOCK,
      path: "/containers/" + container + "/start",
      method: "POST",
      headers: { "Content-Type": "application/json", "Content-Length": 0 },
    };
    const req = require("http").request(opts, function(r) {
      resolve({ status: r.statusCode }); // 204 = started, 304 = already running
    });
    req.on("error", reject);
    req.end();
  });
}

function dockerStop(container) {
  return new Promise(function(resolve, reject) {
    if (!fs.existsSync(DOCKER_SOCK)) return reject(new Error("Docker socket not available"));
    const opts = {
      socketPath: DOCKER_SOCK,
      path: "/containers/" + container + "/stop",
      method: "POST",
      headers: { "Content-Type": "application/json" },
    };
    const req = require("http").request(opts, function(r) {
      resolve({ status: r.statusCode }); // 204 = stopped, 304 = already stopped
    });
    req.on("error", reject);
    req.end();
  });
}

function dockerStatus(container, req) {
  return new Promise(function(resolve, reject) {
    if (!fs.existsSync(DOCKER_SOCK)) return resolve({ online: false, error: st("docker_socket_missing", req) });
    const opts = {
      socketPath: DOCKER_SOCK,
      path: "/containers/" + container + "/json",
      method: "GET",
    };
    const dreq = require("http").request(opts, function(r) {
      const chunks = [];
      r.on("data", function(c) { chunks.push(c); });
      r.on("end", function() {
        try {
          const d = JSON.parse(Buffer.concat(chunks).toString());
          const s = d.State || {};
          resolve({ online: s.Running === true, status: s.Status, exitCode: s.ExitCode });
        } catch(e) { resolve({ online: false, error: e.message }); }
      });
    });
    req.on("error", function(e) { resolve({ online: false, error: e.message }); });
    req.end();
  });
}

// GET /api/lab/stats — visitor stats across all environments (LAB only)
// Reads pre-computed JSON reports written by each instance to STATS_DIR
app.get("/api/lab/stats", auth, adminOnly, function(req, res) {
  if (!IS_LAB) return res.status(403).json({ err: "Only available in LAB container" });
  const dir = STATS_DIR || LAB_DATA_DIR;
  if (!dir || !fs.existsSync(dir)) {
    return res.status(503).json({ err: "STATS_DIR not configured or not mounted. Set STATS_DIR env var and mount the shared volume." });
  }
  const days = Math.min(parseInt(req.query.days) || 30, 365);
  const since = new Date(Date.now() - days * 86400000).toISOString().slice(0, 10);

  try {
    const files = fs.readdirSync(dir).filter(function(f) { return f.endsWith(".json") && !f.startsWith("_"); });

    const results = files.map(function(fname) {
      try {
        const raw = JSON.parse(fs.readFileSync(path.join(dir, fname), "utf8"));
        const byDay = raw.stats && raw.stats.byDay ? raw.stats.byDay : {};

        // Build day array for the requested period
        const dayArr = [];
        for (let i = days - 1; i >= 0; i--) {
          const d = new Date(Date.now() - i * 86400000).toISOString().slice(0, 10);
          dayArr.push({ date: d, count: byDay[d] || 0 });
        }
        const periodTotal = dayArr.reduce(function(s, d) { return s + d.count; }, 0);

        return {
          envName:   raw.slug      || fname.replace(".json", ""),
          siteName:  raw.siteName  || raw.slug || fname.replace(".json", ""),
          domain:    raw.domain    || "",
          version:   raw.version   || "?",
          updatedAt: raw.updatedAt || null,
          isDemo:    raw.isDemo    || false,
          total:     periodTotal,
          today:     raw.stats ? (raw.stats.today     || 0) : 0,
          yesterday: raw.stats ? (raw.stats.yesterday || 0) : 0,
          allTime:   raw.stats ? (raw.stats.allTime   || 0) : 0,
          days:      dayArr,
        };
      } catch(e) {
        return null;
      }
    }).filter(Boolean);

    // Sort: demo first, then by total desc
    results.sort(function(a, b) {
      if (a.isDemo !== b.isDemo) return a.isDemo ? -1 : 1;
      return b.total - a.total;
    });

    res.json({ ok: true, days, environments: results });
  } catch(e) {
    res.status(500).json({ err: e.message });
  }
});

function getLabBackups() {
  if (!LAB_DATA_DIR || !fs.existsSync(LAB_DATA_DIR)) return [];
  try {
    return fs.readdirSync(LAB_DATA_DIR)
      .filter(function(e) { return e.startsWith("_update_backup_"); })
      .map(function(e) {
        const version = e.replace("_update_backup_", "");
        const dir     = path.join(LAB_DATA_DIR, e);
        const files   = fs.existsSync(dir) ? fs.readdirSync(dir) : [];
        let createdAt = null;
        try { createdAt = fs.statSync(path.join(dir, "server.js")).mtime.toISOString(); } catch(e2) {}
        return { version, files, createdAt };
      })
      .filter(function(b) { return b.files.includes("server.js"); })
      .sort(function(a, b) { return (b.createdAt || "").localeCompare(a.createdAt || ""); });
  } catch(e) { return []; }
}

