// POST /api/lab/remote/control  { action: "restart" | "restore", version?: "1.x.x" }
app.post("/api/lab/remote/control", auth, adminOnly, rateLimit(10, 60000), async function(req, res) {
  const action  = req.body.action;
  const version = req.body.version;
  if (!["restart", "restore", "copy-from-prod"].includes(action)) return res.status(400).json({ err: "Ugyldig handling" });

  // Kopier file to lab and restart
  if (action === "copy-from-prod") {
    if (!LAB_APP_DIR) return res.status(503).json({ err: "LAB_APP_DIR ikke konfigurert" });
    if (!fs.existsSync(LAB_APP_DIR)) return res.status(503).json({ err: "LAB_APP_DIR finnes ikke – sjekk volume-mount" });
    try {
      const files = ["server.js", "index.html", "package.json"];
      const copied = [];
      files.forEach(function(f) {
        const src = path.join(__dirname, f);
        const dst = path.join(LAB_APP_DIR, f);
        if (fs.existsSync(src)) { fs.copyFileSync(src, dst); copied.push(f); }
      });
      if (!copied.includes("server.js")) return res.status(500).json({ err: "server.js ikke funnet i /app" });
      await dockerRestart(LAB_CONTAINER);
      return res.json({ ok: true, files: copied, message: "Files copied to lab - restarting now" });
    } catch(e) {
      return res.status(500).json({ err: e.message });
    }
  }

  if (action === "restore") {
    if (!version) return res.status(400).json({ err: "version is required" });
    if (!LAB_DATA_DIR || !LAB_APP_DIR) return res.status(503).json({ err: "LAB_DATA_DIR and LAB_APP_DIR must be mounted in docker-compose" });
    const backupDir = path.join(LAB_DATA_DIR, "_update_backup_" + version);
    if (!fs.existsSync(backupDir)) return res.status(404).json({ err: "Backup v" + version + " ikke funnet" });
    try {
      const files = ["server.js", "index.html", "package.json"];
      const restored = [];
      files.forEach(function(f) {
        const src = path.join(backupDir, f);
        const dst = path.join(LAB_APP_DIR, f);
        if (fs.existsSync(src)) { fs.copyFileSync(src, dst); restored.push(f); }
      });
      if (!restored.includes("server.js")) return res.status(500).json({ err: "server.js ikke funnet i backup" });
      await dockerRestart(LAB_CONTAINER);
      return res.json({ ok: true, version, files: restored, message: "Restoring v" + version + " - the lab is restarting now" });
    } catch(e) {
      return res.status(500).json({ err: e.message });
    }
  }

  if (action === "restart") {
    try {
      await dockerRestart(LAB_CONTAINER);
      return res.json({ ok: true, message: LAB_CONTAINER + " restartes…" });
    } catch(e) {
      return res.status(500).json({ err: e.message });
    }
  }
});

// ── Kunde-provisjonering via Portainer API ───────────────────────
app.post("/api/provision/customer", auth, adminOnly, rateLimit(5, 60000), async function(req, res) {
  const { slug, orgName, domain, contactEmail, portainerUrl, portainerKey, endpointId, existingStackId, cf, demoMode, demoEmail, demoPassword, demoResetH } = req.body || {};

  if (!slug || !orgName || !domain || !contactEmail || !portainerUrl || !portainerKey)
    return res.status(400).json({ err: "Mangler påkrevde felt" });
  if (!/^[a-z0-9-]+$/.test(slug))
    return res.status(400).json({ err: "Slug kan bare inneholde lowercase bokstaver, tall og bindestrek" });

  const crypto     = require("crypto");
  const bcryptLib  = require("bcrypt");
  const sessionSecret = crypto.randomBytes(32).toString("hex");
  const backupSecret  = crypto.randomBytes(32).toString("hex");
  const adminPassword = crypto.randomBytes(9).toString("base64").replace(/[+/=]/g,"").slice(0,12);
  const stackName     = slug + "-events";
  const dataPath      = "/compute/appdata/" + slug;
  const mediaPath     = "/mnt/mediadisk/" + slug; // dedikert mappe på USB-mediadisken, separat per kunde
  const updateUrl     = process.env.UPDATE_URL || "https://raw.githubusercontent.com/your-org/events-admin/main";
  const steps         = [];

  function step(text, status) { steps.push({ text, status }); }

  // ── 1. Cloudflare DNS ──────────────────────────────────────────
  if (cf && cf.token && cf.zone) {
    try {
      step("Oppretter DNS-records i Cloudflare…", "pending");
      const cfHeaders = {
        "Authorization": "Bearer " + cf.token,
        "Content-Type": "application/json",
      };
      const cfBase = "https://api.cloudflare.com/client/v4/zones/" + cf.zone + "/dns_records";

      // Fetch the current IP from existing A records in the zone (follows a dynamic IP automatically)
      let serverIp = "0.0.0.0";
      try {
        const existingRes = await fetch(
          "https://api.cloudflare.com/client/v4/zones/" + cf.zone + "/dns_records?type=A&per_page=1",
          { headers: cfHeaders }
        );
        const existingData = await existingRes.json().catch(() => ({}));
        const firstA = (existingData.result || [])[0];
        if (firstA && firstA.content) {
          serverIp = firstA.content;
          step("Henter gjeldende IP fra Cloudflare: " + serverIp + " ✓", "ok");
        } else {
          step("Ingen eksisterende A-record funnet – bruker 0.0.0.0, oppdater manuelt", "info");
        }
      } catch(e) {
        step("Kunne ikke hente IP fra Cloudflare: " + e.message, "info");
      }

      const records = [
        { type: "A", name: domain,        content: serverIp, proxied: cf.proxied },
        { type: "A", name: "*." + domain, content: serverIp, proxied: cf.proxied },
      ];
      for (const rec of records) {
        const r = await fetch(cfBase, { method: "POST", headers: cfHeaders, body: JSON.stringify(rec) });
        const d = await r.json().catch(() => ({}));
        if (!r.ok && !(d.errors || []).some(function(e) { return e.code === 81057; })) {
          // 81057 = record already exists – not an error
          step("DNS feil: " + (d.errors?.[0]?.message || ("HTTP " + r.status)), "err");
          return res.status(502).json({ err: "Cloudflare DNS feil", steps });
        }
      }
      step("DNS A-record og wildcard opprettet ✓", "ok");
    } catch(e) {
      step("DNS feil: " + e.message, "err");
      return res.status(502).json({ err: "Cloudflare DNS feil: " + e.message, steps });
    }
  } else {
    step("Cloudflare ikke konfigurert – DNS settes manuelt", "info");
  }

  // ── 2. Portainer Stack ─────────────────────────────────────────
  const domainEscaped = domain.replace(/\./g, "\\.");
  const Q = '"';
  const composeYaml = [
    "services:",
    "  " + stackName + ":",
    "    container_name: " + slug,
    "    image: node:18-bookworm-slim",
    "    working_dir: /app",
    "    networks:",
    "      - bridge",
    "    volumes:",
    "      - " + dataPath + ":/app",
    "      - " + dataPath + "/data:/data",
    "      - " + dataPath + "/public:/public",
    "      - " + mediaPath + ":/data/uploads-archive", // eldre media flyttes hit automatisk (se MEDIA_HOT_LIMIT_MB)
    "    command: sh -c '[ -f /usr/bin/ffmpeg ] || (apt-get update -qq && apt-get install -y -qq ffmpeg && rm -rf /var/lib/apt/lists/*); [ -d node_modules ] || npm install --omit=dev; exec node server.js'",
    "    environment:",
    "      - NODE_ENV=production",
    demoMode ? "      - DEMO_MODE=true" : null,
    demoMode ? "      - DEMO_EMAIL=" + (demoEmail || "demo@event-admin.online") : null,
    demoMode ? "      - DEMO_PASSWORD=" + (demoPassword || "Demo2026!") : null,
    demoMode ? "      - DEMO_RESET_HOURS=" + (demoResetH || 24) : null,
    "      - DATA_DIR=/data",
    "      - MEDIA_HOT_LIMIT_MB=10240", // sist opplastede 10 GB blir liggende på SSD, resten flyttes til mediadisk
    "      - BASE_DOMAIN=" + domain,
    "      - ADMIN_DOMAIN=admin." + domain,
    "      - TV_DOMAIN=tv." + domain,
    "      - SESSION_SECRET=" + sessionSecret,
    "      - BACKUP_SECRET=" + backupSecret,
    "      - UPDATE_URL=" + updateUrl,
    "      - ANTHROPIC_API_KEY=",
    "    restart: unless-stopped",
    "    healthcheck:",
    "      test: [\"CMD-SHELL\", \"wget -qO- http://localhost:3000/health || exit 1\"]",
    "      interval: 15s",
    "      timeout: 5s",
    "      retries: 3",
    "      start_period: 30s",

    "    labels:",
    "      - " + Q + "traefik.enable=true" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-root.rule=Host(`" + domain + "`) || Host(`www." + domain + "`)" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-root.entrypoints=web-secure" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-root.tls=true" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-root.tls.certresolver=cloudflare" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-root.service=" + slug + "-events" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-root.priority=30" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-admin.rule=Host(`admin." + domain + "`)" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-admin.entrypoints=web-secure" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-admin.tls=true" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-admin.tls.certresolver=cloudflare" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-admin.tls.domains[0].main=" + domain + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-admin.tls.domains[0].sans=*." + domain + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-admin.service=" + slug + "-events" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-admin.priority=20" + Q,
    "      - 'traefik.http.routers." + slug + "-sub.rule=HostRegexp(`^[a-z0-9-]+\\." + domainEscaped + "$`) && !Host(`admin." + domain + "`)'",
    "      - " + Q + "traefik.http.routers." + slug + "-sub.entrypoints=web-secure" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-sub.tls=true" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-sub.tls.certresolver=cloudflare" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-sub.service=" + slug + "-events" + Q,
    "      - " + Q + "traefik.http.routers." + slug + "-sub.priority=10" + Q,
    "      - " + Q + "traefik.http.services." + slug + "-events.loadbalancer.server.port=3000" + Q,
    "",
    "networks:",
    "  bridge:",
    "    external: true",
  ].filter(Boolean).join("\n");

  try {
    step("Deployer stack i Portainer…", "pending");
    let stackRes, stackData;

    if (existingStackId) {
      // ── Update existing stack: fetch, merge service block, PUT back ──────
      step("Henter eksisterende stack (id=" + existingStackId + ")…", "pending");
      const getRes  = await fetch(portainerUrl + "/api/stacks/" + existingStackId + "/file",
        { headers: { "X-API-Key": portainerKey } });
      const getData = await getRes.json().catch(() => ({}));
      if (!getRes.ok) {
        step("Kunne ikke hente stack: " + (getData.message || "HTTP " + getRes.status), "err");
        return res.status(502).json({ err: "Kunne ikke hente eksisterende stack", steps });
      }

      // Extract service block from new compose yaml
      const newLines  = composeYaml.split("\n");
      const svcStart  = newLines.findIndex(function(l) { return l === "services:"; }) + 1;
      const netStart  = newLines.findIndex(function(l, i) { return i >= svcStart && /^networks:/.test(l); });
      const svcLines  = newLines.slice(svcStart, netStart >= 0 ? netStart : undefined);
      while (svcLines.length && svcLines[svcLines.length - 1].trim() === "") svcLines.pop();
      const svcBlock  = svcLines.join("\n");

      // Merge into existing stack yaml
      // The done-stack has: version → networks → services (networks comes FIRST)
      // So there is no networks: block AFTER services — just append to end of file
      const existing  = getData.StackFileContent.replace(/\r\n/g, "\n").trimEnd();
      const svcIdx    = existing.search(/\nservices:/);   // where services: starts
      const netAfterSvc = svcIdx >= 0
        ? existing.slice(svcIdx).search(/\nnetworks:/)    // is there a networks: AFTER services:?
        : -1;
      let mergedYaml;
      if (netAfterSvc >= 0) {
        // networks: comes after services: — insert before it
        const insertAt = svcIdx + netAfterSvc;
        mergedYaml = existing.slice(0, insertAt).trimEnd() + "\n\n" + svcBlock + "\n" + existing.slice(insertAt + 1);
      } else {
        // networks: comes before services: (or no networks at all) — append to end
        mergedYaml = existing.trimEnd() + "\n\n" + svcBlock;
      }

      console.log("[provision] Merged YAML (" + mergedYaml.length + " bytes):\n" + mergedYaml.slice(0, 800));

      // Fetch existing env vars from the stack so we don't wipe them
      const envRes  = await fetch(portainerUrl + "/api/stacks/" + existingStackId, { headers: { "X-API-Key": portainerKey } });
      const envData = await envRes.json().catch(() => ({}));
      const existingEnv = (envData.Env || []);
      stackRes  = await fetch(portainerUrl + "/api/stacks/" + existingStackId + "?endpointId=" + endpointId, {
        method:  "PUT",
        headers: { "X-API-Key": portainerKey, "Content-Type": "application/json" },
        body:    JSON.stringify({ StackFileContent: mergedYaml, Env: existingEnv, Prune: false }),
      });
      stackData = await stackRes.json().catch(() => ({}));
      if (!stackRes.ok) {
        const msg = stackData.message || stackData.err || ("HTTP " + stackRes.status);
        step("Portainer update feil: " + msg, "err");
        return res.status(502).json({ err: "Portainer feil: " + msg, steps });
      }
      step("Service lagt til i stack " + existingStackId + " ✓", "ok");

    } else {
      // ── Create new standalone stack ───────────────────────────────────────
      stackRes  = await fetch(portainerUrl + "/api/stacks/create/standalone/string?endpointId=" + endpointId, {
        method:  "POST",
        headers: { "X-API-Key": portainerKey, "Content-Type": "application/json" },
        body:    JSON.stringify({ Name: stackName, StackFileContent: composeYaml, Env: [] }),
      });
      stackData = await stackRes.json().catch(() => ({}));
      if (!stackRes.ok) {
        const msg = stackData.message || stackData.err || ("HTTP " + stackRes.status);
        step("Portainer feil: " + msg, "err");
        return res.status(502).json({ err: "Portainer feil: " + msg, steps });
      }
      step("Ny stack '" + stackName + "' deployet ✓", "ok");
    }
  } catch(e) {
    console.error("[provision] Portainer exception:", e.message);
    step("Portainer feil: " + e.message, "err");
    return res.status(500).json({ err: e.message, steps });
  }

  // ── 3. Kopier applikasjonsfiler til ny instans ───────────────────────────
  step("Kopierer applikasjonsfiler…", "pending");
  try {
    const appFiles = ["server.js", "index.html", "package.json"];
    const srcDir   = process.env.LAB_APP_DIR || __dirname;
    fs.mkdirSync(dataPath, { recursive: true });
    fs.mkdirSync(path.join(dataPath, "data"),   { recursive: true });
    fs.mkdirSync(path.join(dataPath, "public"), { recursive: true });
    fs.mkdirSync(mediaPath, { recursive: true });
    step("Mappe for media opprettet: " + mediaPath + " ✓", "ok");
    let copied = [];
    for (const f of appFiles) {
      const src = path.join(srcDir, f);
      const dst = path.join(dataPath, f);
      if (fs.existsSync(src)) { fs.copyFileSync(src, dst); copied.push(f); }
      else { step("Advarsel: " + f + " ikke funnet i " + srcDir, "info"); }
    }
    step("Filer kopiert: " + copied.join(", ") + " ✓", "ok");
  } catch(e) {
    step("Fil-kopiering feilet: " + e.message, "err");
    return res.status(500).json({ err: "Fil-kopiering feilet: " + e.message, steps });
  }

  // ── 4. Vent til instansen svarer ──────────────────────────────
  step("Waiting for the instance to start (max 3 min)…", "pending");
  const adminUrl   = "https://admin." + domain;
  const startAt    = Date.now();
  const maxWait    = 180000; // 3 min
  const pollDelay  = function(ms) { return new Promise(function(r) { setTimeout(r, ms); }); };
  let instanceUp   = false;
  while (Date.now() - startAt < maxWait) {
    try {
      const probe = await fetch(adminUrl + "/api/health", {
        signal: AbortSignal.timeout(5000),
      }).catch(() => null);
      if (probe && probe.ok) { instanceUp = true; break; }
    } catch(e) { /* still starting */ }
    await pollDelay(6000);
  }
  if (!instanceUp) {
    step("Instansen svarte ikke innen 3 min – sjekk Portainer-logg", "err");
    return res.status(504).json({ err: "Instansen startet ikke i tide", steps });
  }
  step("Instansen er oppe ✓", "ok");

  // ── 5. create admin-user via intern API ─────────────────────
  let mailSent = false;
  try {
    step("Oppretter admin-konto…", "pending");
    const adminEmail = contactEmail;
    const setupRes = await fetch(adminUrl + "/api/provision/init-admin", {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-Provision-Secret": sessionSecret },
      body: JSON.stringify({ email: adminEmail, password: adminPassword, orgName }),
      signal: AbortSignal.timeout(10000),
    }).catch(() => null);
    if (setupRes && setupRes.ok) {
      step("Admin-konto opprettet ✓", "ok");
    } else {
      step("Admin-konto kunne ikke opprettes – sett opp manuelt", "info");
    }
  } catch(e) {
    step("Admin-oppsett feil: " + e.message, "info");
  }

  // ── 5. send welcome email ───────────────────────────────────────
  try {
    step("Sender velkomstmail…", "pending");
    const mailResult = await sendEmail({
      to: contactEmail,
      subject: "Din Event-Admin er klar – " + orgName,
      html: [
        "<h2>Velkommen til Event-Admin!</h2>",
        "<p>Din instans for <strong>" + orgName + "</strong> er nå klar.</p>",
        "<table style='border-collapse:collapse;margin:1rem 0'>",
        "<tr><td style='padding:4px 12px 4px 0;color:#666'>Admin-panel:</td><td><a href='" + adminUrl + "'>" + adminUrl + "</a></td></tr>",
        "<tr><td style='padding:4px 12px 4px 0;color:#666'>E-post:</td><td>" + contactEmail + "</td></tr>",
        "<tr><td style='padding:4px 12px 4px 0;color:#666'>Passord:</td><td><strong style='font-family:monospace'>" + adminPassword + "</strong></td></tr>",
        "</table>",
        "<p style='color:#888;font-size:.9em'>Logg inn og endre passordet under Innstillinger → Min konto.</p>",
        "<p style='color:#888;font-size:.9em'>Konfigurer e-post (SMTP) under Innstillinger for å sende bekreftelses-mail til participants.</p>",
      ].join(""),
      text: "Velkommen til Event-Admin!\n\nAdmin-panel: " + adminUrl + "\nE-post: " + contactEmail + "\nPassord: " + adminPassword + "\n\nLogg inn og endre passordet under Innstillinger.",
      category: "system",
    });
    if (mailResult.ok) {
      step("Velkomstmail sendt til " + contactEmail + " ✓", "ok");
      mailSent = true;
    } else {
      step("Mail ikke sendt (" + (mailResult.reason || "SMTP ikke konfigurert") + ")", "info");
    }
  } catch(e) {
    step("Mail feil: " + e.message, "info");
  }

  console.log("[provision] Ferdig: " + stackName + " for " + orgName + " (" + domain + ")");
  return res.json({
    ok: true,
    stackName,
    domain,
    adminUrl,
    mailSent,
    steps,
  });
});

// ── Init-admin: kalles of provisjonering after oppstart ──────────
// Beskyttes av SESSION_SECRET sendt i X-Provision-Secret header
app.post("/api/provision/init-admin", async function(req, res) {
  const secret = (req.headers["x-provision-secret"] || "").trim();
  const { email, password, orgName } = req.body || {};

  // Verify secret matches this instance's SESSION_SECRET
  if (!secret || secret !== process.env.SESSION_SECRET)
    return res.status(403).json({ err: "Ugyldig provisjonerings-token" });
  if (!email || !password)
    return res.status(400).json({ err: "Mangler e-post eller passord" });

  try {
    const bcryptLib = require("bcrypt");
    const users = readJSON(USERS_FILE) || [];
    // Only run if no users exist yet (fresh instance)
    if (users.length > 0 && !(users.length === 1 && users[0].autoCreated))
      return res.status(409).json({ err: "Instansen har allerede brukere" });

    const hash = await bcryptLib.hash(password, 12);
    const newUser = { id: uuid(), email, hash, role: "admin", name: "Admin", department: null };
    writeJSON(USERS_FILE, [newUser]);

    // Set org name and mark setup as done (provisioned instances skip the wizard)
    const s = getSettings();
    if (orgName) s.siteName = orgName;
    s.setupDone = true;
    writeJSON(path.join(DATA, "settings.json"), s);

    console.log("[provision] Admin-konto opprettet:", email);
    return res.json({ ok: true });
  } catch(e) {
    console.error("[provision] init-admin feil:", e.message);
    return res.status(500).json({ err: e.message });
  }
});

// Helper: HTTP GET compatible with all Node.js versions
function httpGet(url, extraHeaders) {
  return new Promise(function(resolve, reject) {
    const mod = url.startsWith("https") ? require("https") : require("http");
    const opts = require("url").parse(url);
    // Update artefacts must never come from a CDN cache. raw.githubusercontent
    // and Cloudflare both hold these for minutes, which is why a freshly
    // published release could look "not available yet" on the client, and why
    // a stale file could fail its checksum during apply.
    opts.headers = Object.assign({
      "User-Agent": "Event-Admin/" + APP_VERSION,
      "Cache-Control": "no-cache, no-store, max-age=0",
      "Pragma": "no-cache",
    }, extraHeaders || {});
    mod.get(opts, function(res) {
      if (res.statusCode === 301 || res.statusCode === 302) {
        return httpGet(res.headers.location, extraHeaders).then(resolve).catch(reject);
      }
      const chunks = [];
      res.on("data", function(c) { chunks.push(c); });
      res.on("end",  function()  { resolve({ status: res.statusCode, body: Buffer.concat(chunks) }); });
      res.on("error", reject);
    }).on("error", reject);
  });
}


