// ── watchdog.js content (automatically saved to /watchdog/ on startup) ─
const WATCHDOG_JS = "// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n// Events Watchdog \u2013 controls the lab container via the Docker socket\n// Runs in the watchdog container (see docker-compose)\n//\n// Endpoints (all require Authorization: Bearer <WATCHDOG_TOKEN>):\n//   GET  /status           \u2013 status of the lab container\n//   GET  /backups          \u2013 list of backup versions on lab\n//   POST /restart          \u2013 restart the lab container\n//   POST /restore/:version \u2013 copy backup and restart\n// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\"use strict\";\nconst http   = require(\"http\");\nconst fs     = require(\"fs\");\nconst path   = require(\"path\");\n\nconst PORT      = parseInt(process.env.WATCHDOG_PORT) || 3001;\nconst TOKEN     = process.env.WATCHDOG_TOKEN || \"\";\nconst DATA_DIR  = process.env.DATA_DIR    || \"/lab/data\";\nconst APP_DIR   = process.env.LAB_APP_DIR || \"/lab/app\";\nconst CONTAINER = process.env.TARGET_CONTAINER || \"events-lab\";\n\nif (!TOKEN) {\n  console.error(\"[watchdog] ERROR: WATCHDOG_TOKEN is not set!\");\n  process.exit(1);\n}\n\n// \u2500\u2500 Docker socket communication \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction dockerRequest(method, urlPath, body) {\n  return new Promise(function(resolve, reject) {\n    const opts = {\n      socketPath: \"/var/run/docker.sock\",\n      path:       urlPath,\n      method:     method,\n      headers:    { \"Content-Type\": \"application/json\" },\n    };\n    const req = http.request(opts, function(res) {\n      const chunks = [];\n      res.on(\"data\", function(c) { chunks.push(c); });\n      res.on(\"end\", function() {\n        const raw = Buffer.concat(chunks).toString();\n        try { resolve({ status: res.statusCode, data: JSON.parse(raw) }); }\n        catch(e) { resolve({ status: res.statusCode, data: raw }); }\n      });\n    });\n    req.on(\"error\", reject);\n    if (body) req.write(JSON.stringify(body));\n    req.end();\n  });\n}\n\nasync function getContainerStatus() {\n  try {\n    const r = await dockerRequest(\"GET\", \"/containers/\" + CONTAINER + \"/json\");\n    if (r.status !== 200) return { online: false, error: \"Container not found\" };\n    const s = r.data.State || {};\n    return {\n      online:     s.Running === true,\n      status:     s.Status  || \"unknown\",\n      startedAt:  s.StartedAt,\n      exitCode:   s.ExitCode,\n      image:      (r.data.Config || {}).Image || \"\",\n    };\n  } catch(e) {\n    return { online: false, error: e.message };\n  }\n}\n\nasync function restartContainer() {\n  await dockerRequest(\"POST\", \"/containers/\" + CONTAINER + \"/restart\");\n}\n\n// \u2500\u2500 Backup handling \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction getBackups() {\n  try {\n    return fs.readdirSync(DATA_DIR)\n      .filter(function(e) { return e.startsWith(\"_update_backup_\"); })\n      .map(function(e) {\n        const version = e.replace(\"_update_backup_\", \"\");\n        const dir     = path.join(DATA_DIR, e);\n        const files   = fs.existsSync(dir) ? fs.readdirSync(dir) : [];\n        let createdAt = null;\n        try {\n          const stat = fs.statSync(path.join(dir, \"server.js\"));\n          createdAt = stat.mtime.toISOString();\n        } catch(e2) {}\n        return { version, files, createdAt };\n      })\n      .filter(function(b) { return b.files.includes(\"server.js\"); })\n      .sort(function(a, b) { return (b.createdAt||\"\").localeCompare(a.createdAt||\"\"); });\n  } catch(e) {\n    return [];\n  }\n}\n\nfunction restoreVersion(version) {\n  const backupDir = path.join(DATA_DIR, \"_update_backup_\" + version);\n  if (!fs.existsSync(backupDir)) {\n    throw new Error(\"Backup v\" + version + \" not found in \" + DATA_DIR);\n  }\n  const files = [\"server.js\", \"index.html\", \"package.json\"];\n  const restored = [];\n  files.forEach(function(f) {\n    const src = path.join(backupDir, f);\n    const dst = path.join(APP_DIR, f);\n    if (fs.existsSync(src)) {\n      fs.copyFileSync(src, dst);\n      restored.push(f);\n    }\n  });\n  if (!restored.includes(\"server.js\")) {\n    throw new Error(\"server.js not found in backup v\" + version);\n  }\n  return restored;\n}\n\n// \u2500\u2500 HTTP-server \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction send(res, status, data) {\n  const body = JSON.stringify(data);\n  res.writeHead(status, {\n    \"Content-Type\":                \"application/json\",\n    \"Access-Control-Allow-Origin\": \"*\",\n    \"Access-Control-Allow-Headers\":\"Authorization, Content-Type\",\n  });\n  res.end(body);\n}\n\nfunction checkAuth(req, res) {\n  if (req.method === \"OPTIONS\") { send(res, 200, {}); return false; }\n  const h = (req.headers[\"authorization\"] || \"\").trim();\n  if (h !== \"Bearer \" + TOKEN) {\n    send(res, 403, { error: \"invalid token\" });\n    return false;\n  }\n  return true;\n}\n\nconst server = http.createServer(async function(req, res) {\n  if (!checkAuth(req, res)) return;\n\n  const url = req.url.split(\"?\")[0];\n\n  // GET /status\n  if (req.method === \"GET\" && url === \"/status\") {\n    const status = await getContainerStatus();\n    return send(res, 200, status);\n  }\n\n  // GET /backups\n  if (req.method === \"GET\" && url === \"/backups\") {\n    return send(res, 200, getBackups());\n  }\n\n  // POST /restart\n  if (req.method === \"POST\" && url === \"/restart\") {\n    try {\n      await restartContainer();\n      return send(res, 200, { ok: true, message: CONTAINER + \" is restarting\u2026\" });\n    } catch(e) {\n      return send(res, 500, { error: e.message });\n    }\n  }\n\n  // POST /restore/:version\n  const restoreMatch = url.match(/^\\/restore\\/(.+)$/);\n  if (req.method === \"POST\" && restoreMatch) {\n    const version = decodeURIComponent(restoreMatch[1]);\n    if (!/^[\\w.-]{1,64}$/.test(version) || version.indexOf(\"..\") >= 0) {\n      return send(res, 400, { error: \"invalid version\" });\n    }\n    try {\n      const files = restoreVersion(version);\n      await restartContainer();\n      return send(res, 200, { ok: true, version, files, message: \"Restoring v\" + version + \" and restarting\u2026\" });\n    } catch(e) {\n      return send(res, 500, { error: e.message });\n    }\n  }\n\n  send(res, 404, { error: \"not found: \" + url });\n});\n\nserver.listen(PORT, function() {\n  console.log(\"[watchdog] Started on port \" + PORT);\n  console.log(\"[watchdog] Container: \" + CONTAINER);\n  console.log(\"[watchdog] Data dir:  \" + DATA_DIR);\n  console.log(\"[watchdog] App dir:   \" + APP_DIR);\n});\n";

