// check about update is tilgjengelig
app.get("/api/update/check", auth, adminOnly, async function(req, res) {
  try {
    const base = UPDATE_BASE + "/" + UPDATE_MANIFEST;
    const url  = base + (base.indexOf("?") === -1 ? "?" : "&") + "_t=" + Date.now();
    const r = await httpGet(url);
    if (r.status !== 200) return res.status(502).json({ err: "Manifest ikke tilgjengelig (HTTP " + r.status + ")", url: base });
    let manifest;
    try { manifest = JSON.parse(r.body.toString()); }
    catch (e) {
      console.error("[update/check] Manifest is not valid JSON from " + base + ": " + r.body.toString().slice(0, 200));
      return res.status(502).json({ err: "Manifest er ikke gyldig JSON", url: base });
    }
    const latest = manifest.version || "0.0.0";
    const hasUpdate = IS_LAB ? false : compareVersions(latest, APP_VERSION) > 0;
    if (!hasUpdate && !IS_LAB) {
      console.log("[update/check] current=" + APP_VERSION + " latest=" + latest + " -> no update offered");
    }
    res.json({
      current:   APP_VERSION,
      latest,
      hasUpdate,
      isLab:     IS_LAB,
      isDemo:    IS_DEMO,
      // Surfaced so "why is there no button" can be answered without guessing
      manifestUrl: base,
      changelog: manifest.changelog || [],
      files:     manifest.files || []
    });
  } catch(e) {
    res.status(502).json({ err: "Kunne ikke kontakte oppdateringsserver: " + e.message });
  }
});

// Installer update – loads down file and bytter dem out
app.post("/api/update/apply", auth, adminOnly, async function(req, res) {
  const { files, version: newVersion } = req.body;
  if (!files || !files.length) return res.status(400).json({ err: "Ingen filer angitt" });

  const crypto = require("crypto");
  const tmpDir = path.join(DATA, "_update_tmp");
  // Files must land beside the running server.js. process.cwd() is whatever
  // the container's WORKDIR happens to be; if that differs from __dirname the
  // update writes to a directory nothing ever reads, and the instance keeps
  // serving the old build with no error. Write to both when they differ.
  const appDirs = [__dirname];
  try { if (fs.realpathSync(process.cwd()) !== fs.realpathSync(__dirname)) appDirs.push(process.cwd()); }
  catch (e) { if (process.cwd() !== __dirname) appDirs.push(process.cwd()); }
  try { fs.mkdirSync(tmpDir, { recursive: true }); } catch(e) {}

  const allowedFiles = ["server.js", "index.html", "package.json"];

  try {
    // 1. Last ned til tmp
    for (const f of files) {
      if (!allowedFiles.includes(f.name))
        return res.status(400).json({ err: "Ugyldig filnavn: " + f.name });
      const r = await httpGet(f.url);
      if (r.status !== 200) throw new Error("Download failed for " + f.name + " (HTTP " + r.status + ")");
      // Verifiser SHA256
      if (f.sha256) {
        const hash = crypto.createHash("sha256").update(r.body).digest("hex");
        if (hash !== f.sha256) throw new Error("Checksum mismatch for " + f.name + "\nForventet: " + f.sha256.slice(0,12) + "…\nFikk:      " + hash.slice(0,12) + "…");
      }
      fs.writeFileSync(path.join(tmpDir, f.name), r.body);
    }

    // 2. Sikkerhetskopier gjeldende filer
    const backupDir = path.join(DATA, "_update_backup_" + APP_VERSION);
    try { fs.mkdirSync(backupDir, { recursive: true }); } catch(e) {}
    for (const f of files) {
      const src = path.join(appDirs[0], f.name);
      if (fs.existsSync(src)) {
        try { fs.copyFileSync(src, path.join(backupDir, f.name)); } catch(e) {}
      }
    }

    // 3. Patch APP_VERSION i server.js til ny versjon
    const targetVersion = req.body.version || newVersion || "unknown";
    const serverFile = files.find(function(f) { return f.name === "server.js"; });
    if (serverFile && targetVersion && targetVersion !== "unknown") {
      const serverPath = path.join(tmpDir, "server.js");
      let serverContent = fs.readFileSync(serverPath, "utf8");
      const patched = serverContent.replace(
        /const APP_VERSION\s*=\s*["'][^"']*["']/,
        'const APP_VERSION = "' + targetVersion + '"'
      );
      if (patched !== serverContent) {
        fs.writeFileSync(serverPath, patched);
        console.log("[update] Patched APP_VERSION to " + targetVersion);
      } else {
        console.warn("[update] WARNING: Could not patch APP_VERSION – pattern not found");
      }
    }

    // 4. Place new files in position
    for (const f of files) {
      for (const dir of appDirs) {
        const dst = path.join(dir, f.name);
        try {
          fs.copyFileSync(path.join(tmpDir, f.name), dst);
        } catch(e) {
          try { fs.writeFileSync(dst, fs.readFileSync(path.join(tmpDir, f.name))); }
          catch(e2) { console.error("[update] Could not write " + dst + ": " + e2.message); }
        }
      }
      console.log("[update] Wrote " + f.name + " to " + appDirs.join(" and "));
    }
    // Drop the cached app shell so a served page cannot come from the old build
    try { _shell.key = null; } catch(e) {}

    // 5. Rydd opp
    try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch(e) {}

    res.json({ ok: true, version: targetVersion, message: "Oppdatering til v" + targetVersion + " installert! Starter om 10 sekunder…" });
    setTimeout(function() { process.exit(0); }, 10000);

  } catch(e) {
    // Auto-rollback
    try {
      const backupDir = path.join(DATA, "_update_backup_" + APP_VERSION);
      if (fs.existsSync(backupDir)) {
        for (const f of files) {
          const bak = path.join(backupDir, f.name);
          if (fs.existsSync(bak)) {
            for (const dir of appDirs) {
              try { fs.writeFileSync(path.join(dir, f.name), fs.readFileSync(bak)); } catch(e2) {}
            }
          }
        }
      }
    } catch(re) {}
    console.error("[update/apply] Feil:", e.message);
    res.status(500).json({ err: e.message });
  }
});

// ── Version summaries: what changed in each version ───────────────
// Each version's index.html carries the Ønskeliste roadmap line with
// "<b>Title:</b> text" entries. A version's changes are the entries that
// are not in the next older version.
const _roadmapCache = {};
function _roadmapEntries(file) {
  try {
    const st = fs.statSync(file);
    const key = file + "|" + st.mtimeMs;
    if (_roadmapCache[key]) return _roadmapCache[key];
    const lines = fs.readFileSync(file, "utf8").split("\n");
    let best = "", bestN = 0;
    for (const ln of lines) {
      if (ln.indexOf(":</b>") < 0) continue;
      const n = (ln.match(/<b>[^<]{3,140}?:<\/b>/g) || []).length;
      if (n > bestN) { bestN = n; best = ln; }
    }
    const out = [];
    const re = /<b>([^<]{3,140}?):<\/b>([\s\S]*?)(?=<b>[^<]{3,140}?:<\/b>|<\/div>|$)/g;
    let m;
    while ((m = re.exec(best)) && out.length < 500) {
      const text = m[2].replace(/<[^>]+>/g, "").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/\s+/g, " ").trim();
      out.push({ title: m[1].trim(), text: text });
    }
    _roadmapCache[key] = out;
    return out;
  } catch(e) { return null; }
}
function _shortText(t) {
  t = String(t || "");
  const dot = t.search(/[.!?](\s|$)/);
  if (dot > 20 && dot < 220) t = t.slice(0, dot + 1);
  return t.length > 220 ? t.slice(0, 217).replace(/\s+\S*$/, "") + "…" : t;
}
function _versionChanges(newFile, oldFile) {
  const a = _roadmapEntries(newFile);
  if (!a || !a.length) return [];
  const b = oldFile ? _roadmapEntries(oldFile) : null;
  let list;
  if (b && b.length) {
    const seen = new Set(b.map(function(e) { return e.title; }));
    list = a.filter(function(e) { return !seen.has(e.title); });
  } else {
    list = a.slice(0, 2);
  }
  return list.slice(0, 6).map(function(e) { return { title: e.title, text: _shortText(e.text) }; });
}
function _readAppVersion(appDir) {
  try {
    const m = fs.readFileSync(path.join(appDir, "server.js"), "utf8").match(/const APP_VERSION\s*=\s*["']([^"']+)["']/);
    return m ? m[1] : null;
  } catch(e) { return null; }
}
// List backups in a data dir, newest first, with change summaries.
// appDir (optional) holds the running version, used for the "current" summary.
function _listBackupsWithSummary(dataDir, appDir) {
  let list = [];
  try {
    list = fs.readdirSync(dataDir)
      .filter(function(d) { return d.startsWith("_update_backup_") && !d.endsWith("_pre_restore") && fs.statSync(path.join(dataDir, d)).isDirectory(); })
      .map(function(d) {
        const dir = path.join(dataDir, d);
        const files = fs.readdirSync(dir);
        let createdAt = null;
        try { createdAt = fs.statSync(path.join(dir, files.includes("server.js") ? "server.js" : "")).mtime.toISOString(); } catch(e) {}
        if (!createdAt) { try { createdAt = fs.statSync(dir).mtime.toISOString(); } catch(e) {} }
        return { version: d.replace("_update_backup_", ""), dir: dir, files: files, createdAt: createdAt };
      })
      .filter(function(b) { return b.files.length; })
      .sort(function(a, b) {
        const c = compareVersions(b.version, a.version);
        return c || String(b.createdAt || "").localeCompare(String(a.createdAt || ""));
      });
  } catch(e) { list = []; }
  list.forEach(function(b, i) {
    const older = list[i + 1];
    const changes = _versionChanges(path.join(b.dir, "index.html"), older ? path.join(older.dir, "index.html") : null);
    b.changes = changes;
    b.summary = changes.map(function(c) { return c.title; }).join(" · ");
    b.partial = !older; // oldest backup: no older version to compare with
    delete b.dir;
  });
  let current = null;
  if (appDir) {
    const newest = list.length ? path.join(dataDir, "_update_backup_" + list[0].version, "index.html") : null;
    const changes = _versionChanges(path.join(appDir, "index.html"), newest);
    current = { version: _readAppVersion(appDir), changes: changes, summary: changes.map(function(c) { return c.title; }).join(" · ") };
  }
  return { current: current, backups: list };
}

// GET /api/versions/overview – version history for this instance (used on Lab:
// Lab is where versions are built and tested; Prod only follows GitHub releases)
app.get("/api/versions/overview", auth, adminOnly, function(req, res) {
  const self = _listBackupsWithSummary(DATA, process.cwd());
  if (self.current) self.current.version = APP_VERSION;
  res.json({ role: IS_LAB ? "lab" : "prod", current: self.current, backups: self.backups });
});

// Liste tilgjengelige backups
app.get("/api/update/backups", auth, adminOnly, function(req, res) {
  try {
    const dirs = fs.readdirSync(DATA)
      .filter(function(d) { return d.startsWith("_update_backup_") && fs.statSync(path.join(DATA, d)).isDirectory(); })
      .map(function(d) {
        const version = d.replace("_update_backup_", "");
        const files   = fs.readdirSync(path.join(DATA, d));
        const stat    = fs.statSync(path.join(DATA, d));
        return { version, files, createdAt: stat.mtime };
      })
      .sort(function(a, b) { return new Date(b.createdAt) - new Date(a.createdAt); });
    res.json(dirs);
  } catch(e) { res.json([]); }
});

// Restore from backup
app.post("/api/update/restore/:version", auth, adminOnly, function(req, res) {
  const version   = req.params.version;
  const backupDir = path.join(DATA, "_update_backup_" + version);
  if (!fs.existsSync(backupDir)) return res.status(404).json({ err: "Backup ikke funnet for v" + version });
  try {
    const files = fs.readdirSync(backupDir);
    if (!files.length) return res.status(400).json({ err: "Backup er tom" });
    // Sikkerhetskopier gjeldende
    const safeDir = path.join(DATA, "_update_backup_" + APP_VERSION + "_pre_restore");
    try { fs.mkdirSync(safeDir, { recursive: true }); } catch(e) {}
    for (const f of files) {
      const src = path.join(process.cwd(), f);
      if (fs.existsSync(src)) {
        try { fs.copyFileSync(src, path.join(safeDir, f)); } catch(e) {}
      }
    }
    // Gjenopprett
    for (const f of files) {
      fs.writeFileSync(path.join(process.cwd(), f), fs.readFileSync(path.join(backupDir, f)));
    }
    res.json({ ok: true, message: "v" + version + " gjenopprettet! Starter om 3 sekunder…" });
    setTimeout(function() { process.exit(0); }, 3000);
  } catch(e) {
    res.status(500).json({ err: "Gjenoppretting feilet: " + e.message });
  }
});

// ── Live tracker position proxy ─────────────────────────────────────────────
// Fetches GPS position from a live tracking share URL (Sizzapp, Garmin Share, etc.)


// ── GPS Tracker API ──────────────────────────────────────────────
// Endpoints for LILYGO T-SIM7670G tracker device
// Authentication: mTLS client certificate (Traefik forwards CN header)
// Traefik must be configured to forward: X-Forwarded-Tls-Client-Cert-Info

const TRACKER_FILE  = path.join(DATA, "tracker_log.json");
const TRACKER_SECRET = process.env.TRACKER_SECRET || "";

// mTLS auth middleware — verifies client cert CN forwarded by Traefik
// Traefik adds X-Forwarded-Tls-Client-Cert-Info header when mTLS is used
// Falls back to Bearer token for testing without Traefik
function trackerAuth(req, res, next) {
  // Check for Traefik mTLS cert info header
  const certInfo = req.headers["x-forwarded-tls-client-cert-info"] || "";
  if (certInfo) {
    // Extract CN from cert info (format: CN=tracker-01,O=NAF,C=NO)
    const cnMatch = certInfo.match(/CN=([^,;%]+)/);
    if (cnMatch) {
      req.trackerDevice = decodeURIComponent(cnMatch[1]);
      return next();
    }
  }
  // Fallback: Bearer token (for testing / non-mTLS setups)
  const auth = req.headers["authorization"] || "";
  if (TRACKER_SECRET && auth === "Bearer " + TRACKER_SECRET) {
    req.trackerDevice = req.body && req.body.deviceId ? req.body.deviceId : "unknown";
    return next();
  }
  res.status(401).json({ error: "Unauthorized — valid client cert or Bearer token required" });
}

// POST /api/tracker/location — device pushes GPS fix
app.post("/api/tracker/location", rateLimit(120, 60000), trackerAuth, function(req, res) {
  const { lat, lng, alt, speed, battery, satellites, hdop, clients } = req.body;
  const deviceId = req.body.deviceId || req.trackerDevice || "unknown";

  if (lat === undefined || lng === undefined) {
    return res.status(400).json({ error: "lat and lng required" });
  }

  const fix = {
    deviceId, lat, lng,
    alt:        alt        !== undefined ? alt        : null,
    speed:      speed      !== undefined ? speed      : null,
    battery:    battery    !== undefined ? battery    : null,
    satellites: satellites !== undefined ? satellites : null,
    hdop:       hdop       !== undefined ? hdop       : null,
    wifiClients: clients   !== undefined ? clients    : null,
    ts: new Date().toISOString()
  };

  // Append to log
  const log = readJSON(TRACKER_FILE) || [];
  log.push(fix);
  // Keep last 10 000 fixes (~3 days at 30s interval)
  if (log.length > 10000) log.splice(0, log.length - 10000);
  writeJSON(TRACKER_FILE, log);

  // Broadcast to admin clients via WebSocket
  broadcastToAll({ type: "tracker_fix", fix });

  res.json({ ok: true });
});

// GET /api/tracker/latest — last fix per device
app.get("/api/tracker/latest", auth, function(req, res) {
  const log = readJSON(TRACKER_FILE) || [];
  const latest = {};
  log.forEach(function(fix) {
    latest[fix.deviceId] = fix;
  });
  res.json({ devices: Object.values(latest) });
});

// GET /api/tracker/history — fix trail for one device
app.get("/api/tracker/history", auth, function(req, res) {
  const { deviceId, limit, since } = req.query;
  let log = readJSON(TRACKER_FILE) || [];
  if (deviceId) log = log.filter(function(f){ return f.deviceId === deviceId; });
  if (since)    log = log.filter(function(f){ return f.ts >= since; });
  const lim = parseInt(limit || "200");
  res.json({ fixes: log.slice(-lim) });
});

// DELETE /api/tracker/log — clear the log (admin only)
app.delete("/api/tracker/log", auth, adminOnly, function(req, res) {
  writeJSON(TRACKER_FILE, []);
  res.json({ ok: true });
});

