// GET /api/hardware/certs-script — generate-certs.sh
app.get("/api/hardware/certs-script", auth, function(req, res) {
  const c = _hwSettings(req);
  const s = getSettings();
  const script = [
    `#!/bin/bash`,
    `# generate-certs.sh — mTLS CA + device certificates`,
    `# Generated by ${c.siteName} \u00b7 ${new Date().toLocaleString("nb-NO")}`,
    `# Usage: sudo bash generate-certs.sh [device-name]`,
    `set -e`,
    `CERT_DIR="/compute/appdata/traefik/certs"`,
    `CA_DIR="$CERT_DIR/ca"`,
    `DEVICE=\${1:-"${c.deviceId}"}`,
    `ORG="${c.certOrg}"`,
    `COUNTRY="${c.certCountry}"`,
    `DAYS=3650`,
    `mkdir -p "$CA_DIR" "$CERT_DIR/devices"`,
    `if [ ! -f "$CA_DIR/ca.crt" ]; then`,
    `  echo "[ca] Creating Certificate Authority..."`,
    `  openssl genrsa -out "$CA_DIR/ca.key" 4096`,
    `  openssl req -new -x509 -days $DAYS -key "$CA_DIR/ca.key" \\`,
    `    -out "$CA_DIR/ca.crt" -subj "/CN=${c.siteName}-CA/O=$ORG/C=$COUNTRY"`,
    `  echo "[ca] CA created"`,
    `else`,
    `  echo "[ca] CA exists, skipping"`,
    `fi`,
    `DEV_DIR="$CERT_DIR/devices/$DEVICE"`,
    `mkdir -p "$DEV_DIR"`,
    `openssl genrsa -out "$DEV_DIR/$DEVICE.key" 2048`,
    `openssl req -new -key "$DEV_DIR/$DEVICE.key" -out "$DEV_DIR/$DEVICE.csr" \\`,
    `  -subj "/CN=$DEVICE/O=$ORG/C=$COUNTRY"`,
    `openssl x509 -req -days $DAYS \\`,
    `  -in "$DEV_DIR/$DEVICE.csr" -CA "$CA_DIR/ca.crt" -CAkey "$CA_DIR/ca.key" -CAcreateserial \\`,
    `  -out "$DEV_DIR/$DEVICE.crt"`,
    `rm "$DEV_DIR/$DEVICE.csr"`,
    `cat > "$DEV_DIR/\${DEVICE}_certs.h" << 'HEADER'`,
    `#pragma once`,
    `HEADER`,
    `# Append cert/key content (can't use heredoc inside heredoc easily)`,
    `echo 'static const char DEVICE_CERT[] = R"EOF(' >> "$DEV_DIR/\${DEVICE}_certs.h"`,
    `cat "$DEV_DIR/$DEVICE.crt" >> "$DEV_DIR/\${DEVICE}_certs.h"`,
    `echo ')EOF";' >> "$DEV_DIR/\${DEVICE}_certs.h"`,
    `echo 'static const char DEVICE_KEY[] = R"EOF(' >> "$DEV_DIR/\${DEVICE}_certs.h"`,
    `cat "$DEV_DIR/$DEVICE.key" >> "$DEV_DIR/\${DEVICE}_certs.h"`,
    `echo ')EOF";' >> "$DEV_DIR/\${DEVICE}_certs.h"`,
    `echo 'static const char CA_CERT[] = R"EOF(' >> "$DEV_DIR/\${DEVICE}_certs.h"`,
    `cat "$CA_DIR/ca.crt" >> "$DEV_DIR/\${DEVICE}_certs.h"`,
    `echo ')EOF";' >> "$DEV_DIR/\${DEVICE}_certs.h"`,
    `chmod 600 "$DEV_DIR/$DEVICE.key" "$CA_DIR/ca.key"`,
    `echo ""`,
    `echo "Done! Copy \${DEVICE}_certs.h into your Arduino sketch"`,
    `echo "Then: docker restart traefik"`,
  ].join("\n");
  res.setHeader("Content-Disposition", "attachment; filename=\"generate-certs.sh\"");
  res.setHeader("Content-Type", "text/plain");
  res.send(script);
});

