// GET /api/hardware/streaming-compose — docker-compose snippet
app.get("/api/hardware/streaming-compose", auth, function(req, res) {
  const c = _hwSettings(req);
  const yml = [
    `# streaming-compose-snippet.yml — generated by ${c.siteName}`,
    `# Add rtmp-server service to your Portainer stack`,
    `  rtmp-server:`,
    `    container_name: rtmp-server`,
    `    image: tiangolo/nginx-rtmp`,
    `    restart: unless-stopped`,
    `    networks: [bridge]`,
    `    ports:`,
    `      - "1935:1935"`,
    `      - "8088:8088"`,
    `    volumes:`,
    `      - \${APPDATA}/rtmp/nginx.conf:/etc/nginx/nginx.conf:ro`,
    `      - /tmp/hls:/tmp/hls`,
    `      - \${APPDATA}/recordings:/recordings`,
    `    environment:`,
    `      - TZ=\${TIMEZONE}`,
    `      - CAM_ROTATE_S=${c.camRotate}`,
    ``,
    `# Add to naf/event-admin environment:`,
    `#   RTMP_HOST=rtmp-server`,
    `#   RTMP_HLS=http://rtmp-server:8088`,
    `#   RECORDINGS_DIR=/recordings`,
    `# Mount the SAME recordings volume into the event-admin container too:`,
    `#   - \${APPDATA}/recordings:/recordings`,
  ].join("\n");
  res.setHeader("Content-Disposition", "attachment; filename=\"streaming-compose-snippet.yml\"");
  res.setHeader("Content-Type", "text/plain");
  res.send(yml);
});

