// GET /api/ai/config — provider, model, masked key, configured flag (admin)
app.get("/api/ai/config", auth, adminOnly, function(req, res) {
  const s = getSettings();
  const ai = s.ai || {};
  const cfg = getAIConfig();
  function mask(k){ if(!k) return ""; if(k.length<=8) return "••••"; return k.slice(0,5) + "…" + k.slice(-4); }
  res.json({
    provider: cfg.provider,
    model: ai.model || "",
    openrouterKeyMasked: mask(ai.openrouterKey || ""),
    anthropicKeyMasked: mask(ai.anthropicKey || ""),
    hasOpenrouterKey: !!ai.openrouterKey,
    hasAnthropicKey: !!(ai.anthropicKey),
    ollamaUrl: ai.ollamaUrl || "",
    ollamaEnv: !!process.env.OLLAMA_URL,
    envKeyPresent: !!process.env.ANTHROPIC_API_KEY,
    models: _aiModels(ai, cfg.provider),
    available: cfg.available,
    configured: cfg.configured,
    sendPhotos: cfg.sendPhotos
  });
});

// PUT /api/ai/config — save provider/model/keys (admin). A blank or masked
// key is ignored so saving other fields doesn't wipe the stored key.
app.put("/api/ai/config", auth, adminOnly, function(req, res) {
  const s = getSettings();
  const ai = Object.assign({}, s.ai || {});
  const b = req.body || {};
  if (b.provider === "anthropic" || b.provider === "openrouter" || b.provider === "ollama") ai.provider = b.provider;
  if (b.ollamaUrl !== undefined) {
    const u = String(b.ollamaUrl || "").trim().replace(/\/+$/, "");
    if (u && !/^https?:\/\/[^\s/]+(:\d+)?(\/.*)?$/i.test(u)) return res.status(400).json({ error: "Ollama-adressen må starte med http:// eller https://" });
    ai.ollamaUrl = u.slice(0, 200);
  }
  if (b.model !== undefined) ai.model = String(b.model || "").slice(0, 80);
  // Default model per service
  if (b.models && typeof b.models === "object") {
    const m = {};
    ["anthropic", "openrouter", "ollama"].forEach(function(p) { const v = String(b.models[p] || "").trim().slice(0, 80); if (v) m[p] = v; });
    ai.models = m;
    ai.model = "";   // replaced by the per-service models
  }
  if (b.sendPhotos !== undefined) ai.sendPhotos = b.sendPhotos === true;
  // Only update a key if a real new value is provided (not blank, not the mask)
  function isRealKey(k){ return k && k.indexOf("…") === -1 && k.indexOf("•") === -1; }
  if (b.openrouterKey !== undefined) {
    if (b.openrouterKey === "") ai.openrouterKey = "";           // explicit clear
    else if (isRealKey(b.openrouterKey)) ai.openrouterKey = String(b.openrouterKey).slice(0, 200);
  }
  if (b.anthropicKey !== undefined) {
    if (b.anthropicKey === "") ai.anthropicKey = "";
    else if (isRealKey(b.anthropicKey)) ai.anthropicKey = String(b.anthropicKey).slice(0, 200);
  }
  s.ai = ai;
  saveSettings(s);
  // answer from what was just saved (the settings file is written a moment later)
  const prov = ai.provider || (ai.openrouterKey ? "openrouter" : (ai.anthropicKey || process.env.ANTHROPIC_API_KEY) ? "anthropic" : ai.ollamaUrl ? "ollama" : "anthropic");
  const conf = prov === "openrouter" ? !!ai.openrouterKey : prov === "ollama" ? !!(ai.ollamaUrl || process.env.OLLAMA_URL) : !!(ai.anthropicKey || process.env.ANTHROPIC_API_KEY);
  res.json({ ok: true, provider: prov, configured: conf });
});

