// ── E-postlogg API ───────────────────────────────────────────────
// Correspondence is now tagged with department + eventId + category at
// send-time (see sendEmail). Admins see everything; everyone else only
// sees entries for departments they actually have access to — which
// naturally includes both the department manager and whoever is
// specifically in charge of the event (they share the same department
// access entry). Untagged entries (system/security/auth emails with no
// natural department owner) stay admin-only.
app.get("/api/email-log", auth, function(req, res) {
  const me = req.session.user;
  let log = readJSON(EMAIL_LOG_FILE);
  if (me.role !== "admin") {
    const myAcc = getAccessList(readJSON(USERS_FILE).find(function(u){ return u.id === me.id; }) || {});
    if (!myAcc.length) return res.status(403).json({ error: st("access_denied", req) });
    const myDeptIds = myAcc.map(function(a){ return a.department; }).filter(Boolean);
    log = log.filter(function(e){ return e.department && myDeptIds.includes(e.department); });
  }
  if (req.query.category) log = log.filter(function(e){ return e.category === req.query.category; });
  if (req.query.department && me.role === "admin") log = log.filter(function(e){ return e.department === req.query.department; });
  const limit = Math.min(parseInt(req.query.limit) || 100, 500);
  res.json(log.slice(0, limit));
});

// ── Analytics / visit stats ────────────────────────────────────────
// ── Raw visit log (admin only) ────────────────────────────────
app.get("/api/stats/visits/raw", auth, adminOnly, function(req, res) {
  try {
    const visits  = readJSON(VISITS_FILE);
    const events  = readJSON(EVENTS_FILE);
    const evMap   = {};
    events.forEach(function(e) { evMap[e.id] = e.title || e.id; });
    const days    = parseInt(req.query.days) || 30;
    const cutoff  = new Date(Date.now() - days * 86400000).toISOString();
    const filtered = visits
      .filter(function(v) { return v.ts >= cutoff; })
      .map(function(v) {
        return {
          ts:    v.ts,
          event: evMap[v.evId] || (v.deptId ? '📂 Avdelingsside' : '?'),
          lang:  v.lang || '?',
          ref:   v.ref || '(direkte)',
          vid:   v.vid ? v.vid.slice(0,8) : '?', // only first 8 chars of hash
        };
      })
      .reverse(); // newest first
    res.json({ total: filtered.length, visits: filtered.slice(0, 500) });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});
