  const rate = vehicle === "mc" ? rates.mc : rates.car;
  if (!rate) return { error: vehicle === "mc" ? "Det er ikke satt sats for motorsykkel." : "Det er ikke satt sats for bil." };
  if (vol.homeLat == null || vol.homeLon == null) return { error: vol.homeAddress ? "Fant ikke hjemmeadressen din i kartet – sjekk den under «Profil»." : "Legg inn hjemmeadressen din under «Profil» først." };
