// One filled form for several claims of the same volunteer: GET /api/travel-claims/reiseregning.xlsx?ids=a,b,c
app.get("/api/travel-claims/reiseregning.xlsx", auth, managerOrAdmin, function(req, res) {
  const ids = String(req.query.ids || "").split(",").filter(Boolean).slice(0, RR_MAP.spec.rows);
  const all = readTravelClaims();
  const claims = ids.map(function(id) { return all.find(function(c) { return c.id === id; }); }).filter(Boolean);
  if (!claims.length) return res.status(404).json({ error: "Not found" });
  if (claims.some(function(c) { return !_claimAccess(req.session.user, c) || c.volunteerId !== claims[0].volunteerId; })) return res.status(403).json({ error: st("no_access_department", req) });
  claims.sort(function(a, b) { return String(a.eventDate || "").localeCompare(String(b.eventDate || "")); });
  try {
    const vol = (readJSON(VOLUNTEERS_FILE) || []).find(function(v) { return v.id === claims[0].volunteerId; });
    const out = _rrFill(claims, vol);
    res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    res.setHeader("Content-Disposition", "attachment; filename*=UTF-8''" + encodeURIComponent(_rrFileName({ claims: claims, part: parseInt(req.query.part, 10) || 0 })));
    res.send(out.buf);
  } catch (e) { console.error("[reiseregning]", e.message); res.status(500).json({ error: "Kunne ikke lage reiseregning: " + e.message }); }
});
app.get("/api/travel-claims/:id/reiseregning.xlsx", auth, managerOrAdmin, function(req, res) {
  const c = readTravelClaims().find(function(x) { return x.id === req.params.id; });
  if (!c) return res.status(404).json({ error: "Not found" });
  if (!_claimAccess(req.session.user, c)) return res.status(403).json({ error: st("no_access_department", req) });
  try {
    const vol = (readJSON(VOLUNTEERS_FILE) || []).find(function(v) { return v.id === c.volunteerId; });
    const out = _rrFill([c], vol);
    res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    res.setHeader("Content-Disposition", "attachment; filename*=UTF-8''" + encodeURIComponent(_rrFileName({ claims: [c], part: 0 })));
    res.send(out.buf);
  } catch (e) { console.error("[reiseregning]", e.message); res.status(500).json({ error: "Kunne ikke lage reiseregning: " + e.message }); }
});
// Zip with filled forms + receipts. ?group=event|volunteer & the same filters as the list.
// Rejected claims are never included; with status=all only approved and paid claims are used.
app.get("/api/travel-claims/reiseregning.zip", auth, managerOrAdmin, function(req, res) {
  const q = Object.assign({}, req.query || {});
  let list = _claimsVisible(req.session.user, q).filter(function(c) { return c.status !== "rejected"; });
  if (!q.status || q.status === "all") list = list.filter(function(c) { return c.status === "approved" || c.status === "paid"; });
  if (!list.length) return res.status(404).json({ error: "Ingen godkjente kjøregodtgjørelser å lage reiseregning for." });
  try {
    const files = [];
    const vols = readJSON(VOLUNTEERS_FILE) || [];
    const used = {};
    const uniq = function(n) { let k = n, i = 2; while (used[k]) { k = n.replace(/(\.[a-z0-9]+)$/i, " (" + i++ + ")$1"); } used[k] = 1; return k; };
    const summary = [["Navn", "Fil", "Reiser", "Km", "Beløp"]];
    _rrGroups(list, q.group === "volunteer" ? "volunteer" : "event").forEach(function(g) {
      const vol = vols.find(function(v) { return v.id === g.claims[0].volunteerId; });
      const out = _rrFill(g.claims, vol);
      const fname = uniq(_rrFileName(g));
      files.push({ name: fname, data: out.buf });
      summary.push([g.claims[0].volunteerName, fname, g.claims.length, g.claims.reduce(function(s, c) { return s + (+c.km || 0); }, 0), out.total]);
      // Receipts next to the form
      g.claims.forEach(function(c) {
        (c.expenses || []).forEach(function(e, i) {
          if (!e.receipt || !e.receipt.file) return;
          const fp = path.join(RR_RECEIPT_DIR, String(c.volunteerId).replace(/[^a-zA-Z0-9_-]/g, ""), e.receipt.file);
          if (!fs.existsSync(fp)) return;
          const ext = path.extname(e.receipt.file);
          const rn = uniq("Bilag - " + _safeName(c.volunteerName) + " - " + (c.eventDate || "").slice(0, 10) + " - " + (RR_EXP_LABEL[e.type] || "Utlegg") + ext);
          files.push({ name: rn, data: fs.readFileSync(fp) });
        });
      });
    });
    const num = function(n) { return String(Math.round(n * 100) / 100).replace(".", ","); };
    const csv = "﻿" + summary.map(function(r, i) { return (i ? [r[0], r[1], r[2], num(r[3]), num(r[4])] : r).map(function(v) { v = String(v); return /[";\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; }).join(";"); }).join("\r\n");
    files.unshift({ name: "Oversikt.csv", data: Buffer.from(csv, "utf8") });
    const buf = _zipBuild(files);
    res.setHeader("Content-Type", "application/zip");
    res.setHeader("Content-Disposition", 'attachment; filename="reiseregninger-' + new Date().toISOString().slice(0, 10) + '.zip"');
    res.send(buf);
  } catch (e) { console.error("[reiseregning zip]", e.message); res.status(500).json({ error: "Kunne ikke lage reiseregninger: " + e.message }); }
});
app.get("/api/travel-claims/:id/receipt/:rid", auth, managerOrAdmin, function(req, res) {
  const c = readTravelClaims().find(function(x) { return x.id === req.params.id; });
  if (!c || !_claimAccess(req.session.user, c)) return res.status(404).end();
  const e = (c.expenses || []).find(function(x) { return x.receipt && x.receipt.id === req.params.rid; });
  if (!e) return res.status(404).end();
  const fp = path.join(RR_RECEIPT_DIR, String(c.volunteerId).replace(/[^a-zA-Z0-9_-]/g, ""), e.receipt.file);
  if (!fs.existsSync(fp)) return res.status(404).end();
  res.setHeader("Content-Type", e.receipt.mime || "application/octet-stream");
  res.setHeader("Cache-Control", "private, no-store");
  res.sendFile(fp);
});
// Department travel form template: GET (download current), POST (upload own), DELETE (back to built-in)
function _deptTplGuard(req, res) {
  const d = (getSettings().departments || []).find(function(x) { return x.id === req.params.id; });
  if (!d) { res.status(404).json({ error: "Not found" }); return null; }
  if (!hasDeptAccess(req.session.user, d.id)) { res.status(403).json({ error: st("no_access_department", req) }); return null; }
  return d;
}
app.get("/api/departments/:id/travel-template", auth, managerOrAdmin, function(req, res) {
  const d = _deptTplGuard(req, res); if (!d) return;
  const t = _rrTemplate(d.id);
  if (req.query.info) {
    let at = null; try { at = fs.statSync(_rrTemplateFile(d.id)).mtime.toISOString(); } catch (e) {}
    return res.json({ custom: t.custom, uploadedAt: t.custom ? at : null });
  }
  res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
  res.setHeader("Content-Disposition", "attachment; filename*=UTF-8''" + encodeURIComponent("Reiseregning mal - " + _safeName(d.displayName || d.name) + ".xlsx"));
  res.send(t.buf);
});
app.post("/api/departments/:id/travel-template", auth, managerOrAdmin, function(req, res) {
  const d = _deptTplGuard(req, res); if (!d) return;
  const m = /base64,(.+)$/.exec(String(req.body.data || ""));
  const buf = Buffer.from(m ? m[1] : String(req.body.data || ""), "base64");
  if (!buf.length || buf.length > 5 * 1024 * 1024) return res.status(400).json({ error: "Velg en .xlsx-fil (maks 5 MB)." });
  try { _rrCheckTemplate(buf); } catch (e) { return res.status(400).json({ error: e.message }); }
  try { fs.mkdirSync(RR_TEMPLATE_DIR, { recursive: true }); fs.writeFileSync(_rrTemplateFile(d.id), buf); }
  catch (e) { return res.status(500).json({ error: "Kunne ikke lagre malen." }); }
  res.json({ ok: true, custom: true });
});
app.delete("/api/departments/:id/travel-template", auth, managerOrAdmin, function(req, res) {
  const d = _deptTplGuard(req, res); if (!d) return;
  try { fs.unlinkSync(_rrTemplateFile(d.id)); } catch (e) {}
  res.json({ ok: true, custom: false });
});

app.post("/api/minside/:token/timelog", rateLimit(30, 60000), function(req, res) {
  const vol = _volunteerForMinsideToken(req.params.token);
  if (!vol) return res.status(401).json({ error: st("invalid_or_expired_link", req) });
  const eventId = String(req.body.eventId || "");
  if (!eventId || !_volunteerMayLogEvent(vol, eventId)) {
    return res.status(403).json({ error: st("not_linked_to_event", req) });
  }
  var all = readJSON(VOLUNTEERS_FILE) || [];
  var i = all.findIndex(function(v){ return v.id === vol.id; });
  if (i < 0) return res.status(404).json({ error: "Not found" });
  all[i].timeLogs = all[i].timeLogs || {};
  all[i].timeLogs[eventId] = all[i].timeLogs[eventId] || [];
  var row = _sanitizeTimeRow(req.body.row || {}, "volunteer");
  if (!row.minutes) return res.status(400).json({ error: st("duration_zero", req) });
  all[i].timeLogs[eventId].push(row);
  all[i].events = all[i].events || [];
  if (all[i].events.indexOf(eventId) === -1) all[i].events.push(eventId);
  writeJSON(VOLUNTEERS_FILE, all);
  // Auto-send evaluation if one exists for this event
  if (vol.email) {
    var _evs = readJSON(EVENTS_FILE) || [];
    var _ev = _evs.find(function(e){ return e.id === eventId; });
    if (_ev && _autoSendEvaluation(_ev, vol.email, vol.name, vol.id)) writeJSON(EVENTS_FILE, _evs); // save the form's send counter
  }
  res.json({ ok: true, row: row });
});

// PUT /api/minside/:token/timelog/:eventId/:rowId — edit a row the volunteer added
app.put("/api/minside/:token/timelog/:eventId/:rowId", rateLimit(30, 60000), function(req, res) {
  const vol = _volunteerForMinsideToken(req.params.token);
  if (!vol) return res.status(401).json({ error: st("invalid_or_expired_link", req) });
  var all = readJSON(VOLUNTEERS_FILE) || [];
  var i = all.findIndex(function(v){ return v.id === vol.id; });
  if (i < 0 || !all[i].timeLogs || !all[i].timeLogs[req.params.eventId]) return res.status(404).json({ error: st("not_found_generic", req) });
  var rows = all[i].timeLogs[req.params.eventId];
  var idx = rows.findIndex(function(r){ return r.id === req.params.rowId; });
  if (idx < 0) return res.status(404).json({ error: st("row_not_found", req) });
  if (rows[idx].addedBy !== "volunteer") return res.status(403).json({ error: st("cannot_edit_row", req) });
  var incoming = Object.assign({}, req.body.row || {}, { id: rows[idx].id, addedAt: rows[idx].addedAt });
  var updated = _sanitizeTimeRow(incoming, "volunteer");
  if (!updated.minutes) return res.status(400).json({ error: st("duration_zero", req) });
  rows[idx] = updated;
  writeJSON(VOLUNTEERS_FILE, all);
  res.json({ ok: true, row: updated });
});

// DELETE /api/minside/:token/timelog/:eventId/:rowId — remove a row the volunteer added
app.delete("/api/minside/:token/timelog/:eventId/:rowId", rateLimit(30, 60000), function(req, res) {
  const vol = _volunteerForMinsideToken(req.params.token);
  if (!vol) return res.status(401).json({ error: st("invalid_or_expired_link", req) });
  var all = readJSON(VOLUNTEERS_FILE) || [];
  var i = all.findIndex(function(v){ return v.id === vol.id; });
  if (i < 0 || !all[i].timeLogs || !all[i].timeLogs[req.params.eventId]) return res.status(404).json({ error: st("not_found_generic", req) });
  var rows = all[i].timeLogs[req.params.eventId];
  var before = rows.length;
  // Volunteers may only delete rows they added themselves
  all[i].timeLogs[req.params.eventId] = rows.filter(function(r){ return !(r.id === req.params.rowId && r.addedBy === "volunteer"); });
  if (all[i].timeLogs[req.params.eventId].length === before) return res.status(403).json({ error: st("cannot_delete_row", req) });
  writeJSON(VOLUNTEERS_FILE, all);
  res.json({ ok: true });
});

// GET /api/minside/:token/clothing-catalog — clothing articles to request from
app.get("/api/minside/:token/clothing-catalog", rateLimit(30, 60000), function(req, res) {
  const vol = _volunteerForMinsideToken(req.params.token);
  if (!vol) return res.status(401).json({ error: st("invalid_or_expired_link", req) });
  var inv = readJSON(INVENTORY_FILE) || [];
  var GARMENT_LABELS = { jacket:"Jakke", vest:"Vest", cap:"Caps", tshirt:"T-skjorte", hoodie:"Genser", softshell:"Softshell", other:"Annet" };
  var articles = inv
    .filter(function(i){ return i.category === "clothing"; })
    .map(function(i){
      var label = i.name || GARMENT_LABELS[i.garmentType] || "Plagg";
      if (i.batchYear) label += " (" + i.batchYear + ")";
      return { id: i.id, label: label, garmentType: i.garmentType || "", batchYear: i.batchYear || null, image: i.image || "" };
    });
  res.json(articles);
});

// POST /api/minside/:token/clothing-request — volunteer asks manager for a garment
app.post("/api/minside/:token/clothing-request", rateLimit(10, 60000), function(req, res) {
  const vol = _volunteerForMinsideToken(req.params.token);
  if (!vol) return res.status(401).json({ error: st("invalid_or_expired_link", req) });
  const item   = String(req.body.item || "").slice(0, 60).trim();
  const reason = String(req.body.reason || "").slice(0, 40).trim();
  const note   = String(req.body.note || "").slice(0, 300).trim();
  const size   = _normSize(String(req.body.size || "").slice(0, 20).trim());
  if (!item || !reason) return res.status(400).json({ error: st("select_garment_and_reason", req) });
  var reqs = readClothingRequests();
  reqs.push({
    id: uuid(),
    volunteerId: vol.id, volunteerName: vol.name || "", volunteerEmail: vol.email || "",
    department: (Array.isArray(vol.departments) && vol.departments[0]) || vol.department || null,
    item: item, reason: reason, size: size, note: note,
    status: "open", createdAt: new Date().toISOString()
  });
  writeClothingRequests(reqs);
  // Notify the configured contact email if email is on
  try {
    const settings = getSettings();
    const to = settings.contactEmail || settings.emailFrom;
    if (to && settings.emailEnabled !== false) {
      const reasonLabels = { ripped:"Ødelagt/revnet", worn:"Utslitt", missing:"Mangler", wrong_size:"Feil størrelse", other:"Annet" };
      sendEmail({
        to: to,
        subject: "👕 Bekledningsforespørsel fra " + (vol.name||"frivillig"),
        html: `<div style="font-family:sans-serif"><h3>Ny bekledningsforespørsel</h3>
          <p><strong>${escHtml(vol.name||"")}</strong> (${escHtml(vol.email||"")})</p>
          <p>Plagg: <strong>${escHtml(item)}</strong>${size?(" \u00b7 Størrelse: "+escHtml(size)):""}</p>
          <p>Årsak: ${escHtml(reasonLabels[reason]||reason)}</p>
          ${note?`<p>Melding: ${escHtml(note)}</p>`:""}</div>`,
        department: (Array.isArray(vol.departments) && vol.departments[0]) || vol.department || null,
        category: "volunteer"
      }).catch(function(){});
    }
  } catch(e){}
  res.json({ ok: true });
});

// GET /api/clothing-requests — manager view of all requests
app.get("/api/clothing-requests", auth, managerOrAdmin, function(req, res) {
  var reqs = readClothingRequests();
  // Department managers see only their department's requests
  if (req.user && !req.user.isAdmin && req.user.department) {
    reqs = reqs.filter(function(r){ return r.department === req.user.department; });
  }
  reqs.sort(function(a,b){ return (b.createdAt||"").localeCompare(a.createdAt||""); });
  res.json(reqs);
});

// PUT /api/clothing-requests/:id — manager updates status (open/done/declined)
app.put("/api/clothing-requests/:id", auth, managerOrAdmin, function(req, res) {
  var reqs = readClothingRequests();
  var r = reqs.find(function(x){ return x.id === req.params.id; });
  if (!r) return res.status(404).json({ error: st("not_found_generic", req) });
  if (["open","done","declined"].indexOf(req.body.status) >= 0) r.status = req.body.status;
  r.resolvedAt = new Date().toISOString();
  writeClothingRequests(reqs);
  res.json({ ok: true });
});

// Confirm screen shown when the email link opens in a different browser
