    + '<main>'
    + '<section class="tab" id="tab-events" aria-labelledby="pageTitle"><div id="eventsBox"><div class="empty">Laster …</div></div></section>'
    + '<section class="tab" id="tab-clothing" hidden><div id="clothingBox"></div></section>'
    + '<section class="tab" id="tab-profile" hidden><div id="profileBox"></div></section>'
    + '</main>'
    + '<div class="cta" id="ctaEvents"><button type="button" class="btn y" data-act="register"><svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>Registrer innsats</button></div>'
    + '<div class="cta" id="ctaClothing" hidden><button type="button" class="btn y" data-act="req" data-item=""><svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>Be om plagg</button></div>'
    + '<nav class="tabbar" aria-label="Min side"><div class="tabbar-in" role="tablist">'
    + '<button type="button" role="tab" id="tb-events" data-act="tab" data-val="events" aria-selected="true"><span class="ico"><svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/></svg></span>Arrangementer</button>'
    + '<button type="button" role="tab" id="tb-clothing" data-act="tab" data-val="clothing" aria-selected="false"><span class="ico"><svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.4 3.5 16 2a4 4 0 0 1-8 0L3.6 3.5a2 2 0 0 0-1.3 2.2l.6 3.5a1 1 0 0 0 1 .8H6v10a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2V10h2.1a1 1 0 0 0 1-.8l.6-3.5a2 2 0 0 0-1.3-2.2z"/></svg></span>Bekledning</button>'
    + '<button type="button" role="tab" id="tb-profile" data-act="tab" data-val="profile" aria-selected="false"><span class="ico"><svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></svg></span>Profil</button>'
    + '</div></nav>'
