    + '<label class="field">Størrelse (valgfritt)<select id="reqSize"><option value="">–</option>' + CLOTHING_SIZES.map(function(z) { return '<option value="' + z + '">' + z + '</option>'; }).join('') + '</select></label>'
    + '<label class="field">Melding (valgfritt)<textarea id="reqNote" maxlength="300"></textarea></label>'
