// ── Per-user preferences ─────────────────────────────────────────
// Language, theme and layout choices (summary boxes, table columns, last tab …)
// follow the user to every browser. Stored per user id in user-prefs.json.
// GET /api/me/prefs → { prefs, updatedAt }   PUT /api/me/prefs { prefs: { key: value|null } }
const USER_PREF_KEYS = ["events_lang", "user_theme", "evStatBoxes", "evColOrder", "evHiddenCols",
  "dashWidgets", "tvActiveTab", "statsActiveTab", "aip_stats"];
function _prefsKey(user) { return String(user.id || user.email || "").slice(0, 200); }
function _prefsAll() { const a = readJSON(USER_PREFS_FILE); return a && !Array.isArray(a) && typeof a === "object" ? a : {}; }
app.get("/api/me/prefs", auth, function(req, res) {
  const rec = _prefsAll()[_prefsKey(req.session.user)] || {};
  res.json({ prefs: rec.prefs || {}, updatedAt: rec.updatedAt || null, keys: USER_PREF_KEYS });
});
app.put("/api/me/prefs", auth, rateLimit(120, 60000), function(req, res) {
  const key = _prefsKey(req.session.user);
  if (!key) return res.status(401).json({ error: st("not_logged_in", req) });
  const incoming = (req.body && req.body.prefs && typeof req.body.prefs === "object") ? req.body.prefs : {};
  const all = _prefsAll();
  const rec = all[key] || { prefs: {} };
  const prefs = Object.assign({}, rec.prefs || {});
  Object.keys(incoming).forEach(function(k) {
    if (USER_PREF_KEYS.indexOf(k) < 0) return;
    const v = incoming[k];
    if (v === null || v === undefined) { delete prefs[k]; return; }
    const sv = String(v);
    if (sv.length <= 20000) prefs[k] = sv;
  });
  if (JSON.stringify(prefs).length > 64000) return res.status(413).json({ error: "Too large" });
  all[key] = { prefs: prefs, updatedAt: new Date().toISOString(), email: req.session.user.email || "" };
  writeJSON(USER_PREFS_FILE, all);
  res.json({ ok: true, prefs: prefs, updatedAt: all[key].updatedAt });
});

app.put("/api/me/profile", auth, async function(req, res) {
  const users = readJSON(USERS_FILE);
  const i = users.findIndex(function(u) { return u.id === req.session.user.id; });
  if (i < 0) return res.status(401).json({ error: st("not_logged_in", req) });

  // Verify current password
  const current = req.body.currentPassword || "";
  const ok = await bcrypt.compare(current, users[i].hash);
  if (!ok) return res.status(403).json({ error: st("incorrect_current_password", req) || "Feil n\u00e5v\u00e6rende passord" });

  // email
  if (req.body.email) {
    const newEmail = req.body.email.toLowerCase().trim();
    const taken = users.some(function(u, j) { return j !== i && u.email === newEmail; });
    if (taken) return res.status(409).json({ error: st("email_already_in_use", req) });
    users[i].email = newEmail;
    req.session.user.email = newEmail;
  }

  // Nytt password
  if (req.body.newPassword) {
    if (req.body.newPassword.length < 8)
      return res.status(400).json({ error: st("password_too_short", req) || "Passord m\u00e5 v\u00e6re minst 8 tegn" });
    users[i].hash = await bcrypt.hash(req.body.newPassword, 12);
    delete users[i].mustChangePassword; // clear rotation flag
  }

  writeJSON(USERS_FILE, users);
  res.json({ ok: true, email: users[i].email });
});

