// The tab icon is an SVG with the logo inside. Browsers never load outside
// resources from an SVG used as an icon (not even same-site /logo/… files), so
// a logo referenced by URL gave an empty tab icon. The logo is now embedded
// as a data URI (read from the uploads folder, or fetched once if external).
const _favLogoCache = new Map();   // logoUrl → { at, dataUri }
async function _logoDataUri(logoUrl) {
  if (!logoUrl) return null;
  if (/^data:image\//i.test(logoUrl)) return logoUrl;
  const MIME = { ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".gif": "image/gif", ".webp": "image/webp", ".svg": "image/svg+xml", ".ico": "image/x-icon" };
  // Local file: /logo/…, /uploads/…, or a full URL to this server
  let rel = null;
  try {
    const u = new URL(logoUrl, "http://local");
    if (u.host === "local" || u.hostname.endsWith(DOMAIN)) {
      const m = /^\/(?:logo|uploads)\/(.+)$/.exec(decodeURIComponent(u.pathname));
      if (m) rel = m[1];
    }
  } catch (e) {}
  if (rel) {
    const file = path.normalize(path.join(UPLOADS, rel));
    if (!file.startsWith(UPLOADS + path.sep)) return null;
    try {
      const st = fs.statSync(file);
      const hit = _favLogoCache.get(logoUrl);
      if (hit && hit.mtime === st.mtimeMs) return hit.dataUri;
      if (st.size > 3 * 1024 * 1024) return null;
      const mime = MIME[path.extname(file).toLowerCase()] || "image/png";
      const dataUri = "data:" + mime + ";base64," + fs.readFileSync(file).toString("base64");
      _favLogoCache.set(logoUrl, { mtime: st.mtimeMs, dataUri: dataUri });
      return dataUri;
    } catch (e) { return null; }
  }
  // External logo: fetch once, keep for 6 hours
  if (/^https?:\/\//i.test(logoUrl)) {
    const hit = _favLogoCache.get(logoUrl);
    if (hit && Date.now() - hit.at < 6 * 3600000) return hit.dataUri;
    try {
      const ctl = new AbortController(); const t = setTimeout(function() { ctl.abort(); }, 5000);
      const r = await fetch(logoUrl, { signal: ctl.signal }); clearTimeout(t);
      const type = (r.headers.get("content-type") || "").split(";")[0];
      if (!r.ok || !/^image\//.test(type)) throw new Error("not an image");
      const buf = Buffer.from(await r.arrayBuffer());
      if (buf.length > 3 * 1024 * 1024) throw new Error("too big");
      const dataUri = "data:" + type + ";base64," + buf.toString("base64");
      _favLogoCache.set(logoUrl, { at: Date.now(), dataUri: dataUri });
      return dataUri;
    } catch (e) { _favLogoCache.set(logoUrl, { at: Date.now() - 5.5 * 3600000, dataUri: null }); return null; }
  }
  return null;
}

app.get("/api/favicon", async function(req, res) {
  var s = getSettings();
  // ?dept=…&sg=… → that group's logo, else the department's, else the main logo
  var pick = _logoFor(req.query.dept ? String(req.query.dept) : "", req.query.sg ? String(req.query.sg) : "");
  var crop = pick.level === "site" ? s.faviconCrop : null; // the crop belongs to the main logo
  var logo = await _logoDataUri(pick.url);

  // No logo (or it could not be read): coloured square with the first letter
  if (!logo) {
    var accent = (s.colors && s.colors.accent) || "#FFD100";
    var letter = escHtml((s.siteName || "E")[0].toUpperCase());
    var svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32">'
      + '<rect width="32" height="32" rx="6" fill="' + escHtml(accent) + '"/>'
      + '<text x="16" y="23" font-family="Arial,sans-serif" font-size="20" font-weight="900" '
      + 'text-anchor="middle" fill="#111">' + letter + '</text></svg>';
    res.setHeader("Content-Type", "image/svg+xml");
    res.setHeader("Cache-Control", "public,max-age=300");
    return res.send(svg);
  }

  // Crop region baked in with the SVG viewBox trick
  var cx = crop ? crop.x : 0;
  var cy = crop ? crop.y : 0;
  var cw = crop ? crop.w : 1;
  var ch = crop ? crop.h : 1;
  var svg2 = '<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 32 32" width="32" height="32">'
    + '<defs><clipPath id="c"><rect width="32" height="32"/></clipPath></defs>'
    + '<image href="' + logo + '" xlink:href="' + logo + '" '
    + 'x="' + (-cx / cw * 32) + '" y="' + (-cy / ch * 32) + '" '
    + 'width="' + (32 / cw) + '" height="' + (32 / ch) + '" '
    + 'clip-path="url(#c)" preserveAspectRatio="' + (crop ? 'none' : 'xMidYMid meet') + '"/>'
    + '</svg>';
  res.setHeader("Content-Type", "image/svg+xml");
  res.setHeader("Cache-Control", "public,max-age=60");
  res.send(svg2);
});

// \u2500\u2500 Security: Force password rotation after breach \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Sets a flag on all users requiring them to change password on next login
app.post("/api/admin/force-password-rotation", auth, adminOnly, function(req, res) {
  var users = readJSON(USERS_FILE);
  users.forEach(function(u) {
    if (u.role !== "admin" || req.body.includeAdmins) {
      u.mustChangePassword = true;
    }
  });
  writeJSON(USERS_FILE, users);
  console.warn("[SECURITY] Password rotation forced by", req.session.user.email);
  res.json({ ok: true, affected: users.filter(function(u){ return u.mustChangePassword; }).length });
});

// \u2500\u2500 Settings API \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Any logged-in user needs settings for terminology, colours, departments and
// event types. They must not receive the credentials stored alongside them \u2014
// SMS and Spond passwords, AI/maps API keys, the TV provisioning secret.
// Writes are already admin-only; this closes the read side.
const SETTINGS_SECRET_KEY_RE = /(password|passwd|secret|apikey|api_key|authtoken|token|privatekey|credential)/i;

function redactSettingsForUser(settings, user) {
  if (user && user.role === "admin") return settings;
  function walk(v) {
    if (Array.isArray(v)) return v.map(walk);
    if (v && typeof v === "object") {
      const out = {};
      Object.keys(v).forEach(function(k) {
        if (SETTINGS_SECRET_KEY_RE.test(k)) {
          // Keep the key so the UI can still tell "configured" from "empty",
          // but never the value itself.
          const val = v[k];
          out[k] = (val === null || val === undefined || val === "") ? val : "";
        } else {
          out[k] = walk(v[k]);
        }
      });
      return out;
    }
    return v;
  }
  const red = walk(settings);
  // The provisioning secret is the whole point of that block \u2014 drop it outright
  if (red.tvProvision) red.tvProvision = { enabled: !!red.tvProvision.enabled };
  return red;
}

app.get("/api/settings", auth, function(req, res) {
  res.json(settingsForClient(getSettings(), req.session.user));
});

// Department connection credentials are never part of the settings payload \u2014
// they are read per department, masked, via /api/departments/:id/connections.
function settingsForClient(settings, user) {
  const s = redactSettingsForUser(settings, user);
  const out = (s === settings) ? Object.assign({}, s) : s;
  if (Array.isArray(out.departments)) {
    out.departments = out.departments.map(function(d) {
      if (!d || !d.connections) return d;
      const copy = Object.assign({}, d);
      delete copy.connections;
      return copy;
    });
  }
  return out;
}

