app.put("/api/settings", auth, adminOnly, function(req, res) {
  const current = getSettings();
  const body    = req.body;
  // Hviteliste tillatte field \u2013 not la body overskrive alt blindt
  const allowed = ["siteName","eventDomain","contactEmail","gdprRetentionDays",
    "defaultMaxParticipants","defaultRegDeadline","defaultHiddenTabs","shiftDefaultStart","shiftDefaultEnd",
    "shiftCalStart","shiftCalEnd","emailEnabled","emailFrom","emailFromName",
    "calStartMonth","theme","logoUrl","setupDone","colors","typography",
    "regFields","orgLevels","orgRoles","departments","emailTemplates","typeNames","typeDescs","typeEmojis","typeColors","customTypes","roleNames","deptTerm","faviconCrop","layout","spond","deptIndex","tvProvision"];
  const updated = Object.assign({}, current);
  allowed.forEach(function(k) {
    if (body[k] !== undefined) {
      // For colors: merge to preserve palette if not explicitly sent
      if (k === "colors" && body.colors && current.colors) {
        updated.colors = Object.assign({}, current.colors, body.colors);
        // Never lose palette from logo extraction
        if (!body.colors.palette || !body.colors.palette.length) {
          updated.colors.palette = current.colors.palette || [];
        }
      } else if (k === "theme" && body.theme && updated.colors && updated.colors.textColors) {
        // When theme switches, clear header/nav textColors that don't fit the new theme
        // so the JS defaults kick in correctly
        var tc = updated.colors.textColors;
        var isLight = body.theme === "light";
        function lum(h) { if(!h||h.length<7) return 128; return parseInt(h.slice(1,3),16)*0.299+parseInt(h.slice(3,5),16)*0.587+parseInt(h.slice(5,7),16)*0.114; }
        if (isLight && tc.headerBg  && lum(tc.headerBg)  < 80)  delete tc.headerBg;
        if (isLight && tc.navText   && lum(tc.navText)   > 200) delete tc.navText;
        if (!isLight && tc.headerBg && lum(tc.headerBg)  > 180) delete tc.headerBg;
        updated[k] = body[k];
      } else {
        updated[k] = body[k];
      }
    }
  });
  if (body.gdprRetentionDays !== undefined) {
    updated.gdprRetentionDays = Math.max(30, Math.min(3650, Number(body.gdprRetentionDays) || 365));
  }
  // Sanit\u00e9r siteName and eventDomain
  if (body.siteName)    updated.siteName    = (body.siteName||"").toString().slice(0,100);
  if (body.eventDomain) updated.eventDomain = (body.eventDomain||"").toString().slice(0,100).replace(/[^a-z0-9.-]/gi,"");
  // Sanitize deptTerm (free text, but length-limited - display text only, no structural meaning)
  if (body.deptTerm) {
    updated.deptTerm = {
      singular: (body.deptTerm.singular || "").toString().slice(0,30).trim(),
      plural:   (body.deptTerm.plural   || "").toString().slice(0,30).trim(),
    };
  }
  // The settings page round-trips the departments array, and the payload it
  // read never contains connections (they are stripped from GET /api/settings).
  // Re-attach the stored credentials by id so a settings save can never wipe
  // them \u2014 the client is not trusted to carry secrets back and forth.
  if (Array.isArray(updated.departments)) {
    const storedConn = {};
    (current.departments || []).forEach(function(d) {
      if (d && d.id && d.connections) storedConn[d.id] = d.connections;
    });
    updated.departments = updated.departments.map(function(d) {
      if (!d || !d.id) return d;
      if (d.connections) return d;                 // explicit write wins
      if (!storedConn[d.id]) return d;
      return Object.assign({}, d, { connections: storedConn[d.id] });
    });
  }

  // Sanitize deptIndex (departments index page + thumbnail refresh)
  if (body.deptIndex) {
    var _di = body.deptIndex;
    var _mins = parseInt(_di.refreshMinutes, 10);
    if (!_mins || isNaN(_mins)) _mins = 60;
    updated.deptIndex = {
      enabled:        _di.enabled !== false,
      refreshMinutes: Math.max(15, Math.min(1440, _mins)),
      title:          (_di.title || "").toString().slice(0, 80).trim(),
      intro:          (_di.intro || "").toString().slice(0, 400).trim(),
      hideEmpty:      !!_di.hideEmpty,
    };
  }
  saveSettings(updated);
  res.json(updated);
});

