// \u2500\u2500 Users API \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function userPublic(u, forDepts) {
  var accessList = getAccessList(u);
  if (forDepts) {
    var deptIds = Array.isArray(forDepts) ? forDepts : [forDepts];
    accessList = accessList.filter(function(t) { return deptIds.indexOf(t.department) !== -1; });
  }
  return { id: u.id, email: u.email, role: u.role, name: u.name, title: u.jobTitle || null, accessList: accessList, createdBy: u.createdBy || null };
}

app.get("/api/users", auth, function(req, res) {
  const me = req.session.user;
  const users = readJSON(USERS_FILE);
  if (me.role === "admin") return res.json(users.map(function(u) { return userPublic(u); }));
  var myTilganger2 = getAccessList(readJSON(USERS_FILE).find(function(u) { return u.id === me.id; }) || {});
  var manageRoles = ["department_manager","deptManager","dept_manager","subgroup_manager","undergruppeansvarlig","group_manager","gruppeansvarlig","activity_manager","event_manager","arrangementsansvarlig"];
  var myManageAvdIds = myTilganger2.filter(function(t){ return manageRoles.indexOf(t.role) !== -1; }).map(function(t){ return t.department; });
  if (myManageAvdIds.length > 0) {
    // Check if caller is dept manager (sees whole dept) or only subgroup manager (sees own subgroups)
    var deptMgrRoles = ["department_manager","deptManager","dept_manager"];
    var callerIsOnlySubMgr = myTilganger2.every(function(t){
      return t.role === "subgroup_manager" || t.role === "undergruppeansvarlig" ||
             t.role === "group_manager"    || t.role === "gruppeansvarlig" ||
             t.role === "activity_manager" || t.role === "event_manager"  || t.role === "arrangementsansvarlig";
    }) && !myTilganger2.some(function(t){ return deptMgrRoles.indexOf(t.role) !== -1; });
    var mySubgroupIds = myTilganger2.reduce(function(acc, t){ return acc.concat(t.subgroups || []); }, []);

    var relevant = users.filter(function(u) {
      if (u.id === me.id) return true;
      if (u.role === "admin") return false; // admins are org-wide, never department-scoped \u2014 don't leak them into a manager's team view
      var uAccess = getAccessList(u);
      // Check if user is in a dept the caller manages
      var inMyDept = uAccess.some(function(t){ return myManageAvdIds.indexOf(t.department) !== -1; });
      // Also visible if user has no dept assigned yet (orphaned) \u2014 show to all dept managers
      if (!inMyDept && uAccess.length === 0) inMyDept = true;
      if (!inMyDept) return false;
      // Subgroup manager: further restrict to users in their subgroups
      if (callerIsOnlySubMgr && mySubgroupIds.length) {
        return uAccess.some(function(t){
          return myManageAvdIds.indexOf(t.department) !== -1 &&
            (t.subgroups || []).some(function(sg){ return mySubgroupIds.indexOf(sg) !== -1; });
        });
      }
      return true;
    });
    return res.json(relevant.map(function(u) {
      if (u.id === me.id) return userPublic(u);
      // Show all accessList entries that overlap with the caller's managed depts
      return userPublic(u, myManageAvdIds);
    }));
  }
  var self = users.find(function(u) { return u.id === me.id; });
  res.json([userPublic(self || {})]);
});

// check about email finnes (for department-flyt)
app.get("/api/users/lookup", auth, function(req, res) {
  const me = req.session.user;
  var hasManageRole = me.role === "admin" || getAccessList(
    readJSON(USERS_FILE).find(function(u){ return u.id === me.id; }) || {}
  ).some(function(t){ return ["department_manager","deptManager","dept_manager","subgroup_manager","undergruppeansvarlig","group_manager","gruppeansvarlig","activity_manager","event_manager"].indexOf(t.role) !== -1; });
  if (!hasManageRole) return res.status(403).json({ error: st("access_denied", req) });
  const email = (req.query.email || "").toLowerCase();
  const users = readJSON(USERS_FILE);
  const found = users.find(function(u) { return u.email === email; });
  if (!found) return res.json({ found: false });
  res.json({ found: true, id: found.id, name: found.name, email: found.email, role: found.role });
});

app.post("/api/users", auth, function(req, res, next) {
  if (req.session.user.role === "admin") return next();
  var me   = req.session.user;
  var myT  = getAccessList(readJSON(USERS_FILE).find(function(u){ return u.id === me.id; }) || {});
  var targetDept = (req.body.newAccess || req.body.access || {}).department || req.body.department || null;

  var canCreate = false;
  myT.forEach(function(t) {
    var r = t.role || "";
    var isDeptMgr = r === "department_manager" || r === "deptManager" || r === "dept_manager";
    var isSgMgr   = r === "subgroup_manager"   || r === "group_manager" ||
                    r === "activity_manager"    || r === "event_manager";
    if (isDeptMgr || isSgMgr) {
      if (!targetDept || t.department === targetDept) canCreate = true;
    }
  });

  if (canCreate) {
    req.body.createdBy = me.id;
    return next();
  }
  res.status(403).json({ error: st("access_denied", req) });
}, async function(req, res) {
  const me       = req.session.user;
  const email    = (req.body.email || "").toLowerCase();
  const password = req.body.password;
  var _rn2 = {"undergruppeansvarlig":"subgroup_manager","gruppeansvarlig":"group_manager","arrangementsansvarlig":"event_manager","deptManager":"department_manager","avdelingsleder":"department_manager"};
  const role     = _rn2[req.body.role] || req.body.role || "department_manager";
  const name     = req.body.name || "";
  const titleValue   = req.body.jobTitle || null;
  const createdBy = req.body.createdBy || null;
  const newAccess = req.body.newAccess || req.body.access || null;
  // Normalise role aliases on the access entry
  if (newAccess && newAccess.role) {
    if (newAccess.role === "dept_manager")     newAccess.role = "department_manager";
    if (newAccess.role === "group_manager" || newAccess.role === "gruppeansvarlig" || newAccess.role === "undergruppeansvarlig") newAccess.role = "subgroup_manager";
    if (newAccess.role === "activity_manager") newAccess.role = "event_manager";
  }
  // Safety: if access has no department, inherit from creator
  if (newAccess && !newAccess.department && req.session.user.role !== "admin") {
    var creatorAccess = getAccessList(readJSON(USERS_FILE).find(function(u){ return u.id === req.session.user.id; }) || {});
    if (creatorAccess.length) newAccess.department = creatorAccess[0].department;
  }

  if (!email) return res.status(400).json({ error: "Email is required" });
  const users = readJSON(USERS_FILE);
  const existing = users.find(function(u) { return u.email === email; });

  if (existing) {
    if (!newAccess) return res.status(409).json({ error: st("email_in_use", req), existingId: existing.id });
    var accessList = getAccessList(existing).filter(function(t) { return t.department !== newAccess.department; });
    accessList.push(newAccess);
    existing.accessList = accessList;
    writeJSON(USERS_FILE, users);
    return res.json({ ok: true, merged: true });
  }

  if (!password) return res.status(400).json({ error: "Password is required for new users" });
  var initialAccessList = [];
  if (newAccess) initialAccessList.push(newAccess);
  else if (req.body.department) initialAccessList.push({ department: req.body.department, subgroups: Array.isArray(req.body.subgroups) ? req.body.subgroups : [], eventTyper: Array.isArray(req.body.eventTyper) ? req.body.eventTyper : [] });
  const phone_val = (req.body.phone || "").trim().slice(0, 30);
  users.push({ id: uuid(), email, hash: await bcrypt.hash(password, 12), role, name, phone: phone_val, title: titleValue, accessList: initialAccessList, createdBy });
  writeJSON(USERS_FILE, users);
  res.json({ ok: true, merged: false });
});

app.put("/api/users/:id", auth, async function(req, res) {
  const users = readJSON(USERS_FILE);
  // Breakglass accounts are provisioned via env vars \u2013 block any UI changes
  const targetUser = users.find(function(u){ return u.id === req.params.id; });
  if (targetUser && isBreakglassEmail(targetUser.email))
    return res.status(403).json({ error: "Breakglass accounts cannot be edited via UI \u2013 use Portainer environment variables" });

  const i = users.findIndex(function(u) { return u.id === req.params.id; });
  if (i < 0) return res.status(404).json({ error: "Not found" });
  const me = req.session.user;

  if (me.role !== "admin") {
    var myAccess2 = getAccessList(readJSON(USERS_FILE).find(function(u) { return u.id === me.id; }) || {});
    var myManageDepts = myAccess2.filter(function(t){
      return t.role === "department_manager" || t.role === "deptManager" ||
             t.role === "subgroup_manager";
    }).map(function(t){ return t.department; });

    // Can always edit yourself
    var editingSelf = users[i].id === me.id;
    // Can edit others only if they are in a dept you manage
    var targetInMyDept = !editingSelf && getAccessList(users[i]).some(function(t){
      return myManageDepts.indexOf(t.department) !== -1;
    });

    if (!editingSelf && !targetInMyDept)
      return res.status(403).json({ error: st("no_access_user", req) });

    // Non-admin cannot elevate to admin or department_manager
    if (req.body.role === "admin" || req.body.role === "department_manager")
      return res.status(403).json({ error: st("cannot_assign_role", req) });

    // Subgroup manager cannot promote beyond their own level
    var iAmOnlySubMgr = myAccess2.every(function(t){
      return t.role === "subgroup_manager" || t.role === "group_manager";
    });
    if (iAmOnlySubMgr && (req.body.newAccess || req.body.access)) {
      var newRole = (req.body.newAccess || req.body.access).role || "";
      if (newRole === "department_manager" || newRole === "deptManager")
        return res.status(403).json({ error: st("subgroup_cannot_grant_deptmanager", req) });
    }
  }

  if (req.body.name   !== undefined) users[i].name   = req.body.name;
  if (req.body.phone  !== undefined) users[i].phone  = (req.body.phone || "").trim().slice(0, 30);
  if (req.body.jobTitle !== undefined || req.body.titleValue !== undefined) users[i].jobTitle = req.body.titleValue || req.body.jobTitle || null;
  if (req.body.role   !== undefined && me.role === "admin") users[i].role = (req.body.role||"").toLowerCase().replace(/[- ]/g,"_");
  if (req.body.password) users[i].hash = await bcrypt.hash(req.body.password, 12);

  if (req.body.newAccess || req.body.access) {
    var t = req.body.newAccess || req.body.access;
    // Normalise role aliases to internal canonical names
    if (t && (t.role === "group_manager" || t.role === "gruppeansvarlig" || t.role === "undergruppeansvarlig")) t.role = "subgroup_manager";
    if (t && (t.role === "dept_manager")) t.role = "department_manager";
    if (t && (t.role === "activity_manager")) t.role = "event_manager";
    var myAvdIds3 = getAccessList(readJSON(USERS_FILE).find(function(u){ return u.id === me.id; }) || {}).map(function(t){ return t.department; });
    if (me.role !== "admin" && myAvdIds3.indexOf(t.department) === -1)
      return res.status(403).json({ error: st("cannot_edit_other_dept_access", req) });
    var rest = getAccessList(users[i]).filter(function(x) { return x.department !== t.department; });
    rest.push(t);
    users[i].accessList = rest;
  }
  if (req.body.accessList !== undefined && me.role === "admin") users[i].accessList = req.body.accessList;

  writeJSON(USERS_FILE, users);
  // If editing self, update session so permissions are fresh immediately
  if (users[i].id === req.session.user.id) {
    req.session.user.accessList = getAccessList(users[i]);
  }
  res.json({ ok: true });
});

// \u2500\u2500 Multi-department access management \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// PUT /api/users/:id/access \u2013 add or update one access entry (identified by department)
// Body: { department, role, subgroups, eventTypes, assignmentType, validUntil }
// assignmentType: "primary" | "secondary" | "temporary" (default: "primary")
// To remove an entry: { department, remove: true }
app.put("/api/users/:id/access", auth, async function(req, res) {
  const me = req.session.user;
  const users = readJSON(USERS_FILE);
  const i = users.findIndex(function(u) { return u.id === req.params.id; });
  if (i < 0) return res.status(404).json({ error: "Not found" });

  // Only admin can manage multi-dept access
  if (me.role !== "admin") {
    // Department managers can manage access for their own departments only
    const myAccess = getAccessList(readJSON(USERS_FILE).find(function(u) { return u.id === me.id; }) || {});
    const isDeptMgr = myAccess.some(function(t) { return t.role === "department_manager" || t.role === "deptManager"; });
    if (!isDeptMgr) return res.status(403).json({ error: st("access_denied", req) });
    // Dept managers can only grant access to their own departments
    const myDeptIds = myAccess.map(function(t) { return t.department; });
    if (req.body.department && myDeptIds.indexOf(req.body.department) === -1) {
      return res.status(403).json({ error: "You can only grant access to your own department" });
    }
  }

  const dept = req.body.department;
  if (!dept) return res.status(400).json({ error: "department is required" });

  if (!Array.isArray(users[i].accessList)) users[i].accessList = [];

  if (req.body.remove) {
    // Remove access for this department
    users[i].accessList = users[i].accessList.filter(function(t) { return t.department !== dept; });
  } else {
    // Add or update access entry
    var existingIdx = users[i].accessList.findIndex(function(t) { return t.department === dept; });
    var entry = {
      department:     dept,
      role:           req.body.role || "event_manager",
      subgroups:      Array.isArray(req.body.subgroups) ? req.body.subgroups : [],
      eventTypes:     Array.isArray(req.body.eventTypes) ? req.body.eventTypes : [],
      assignmentType: ["primary","secondary","temporary"].includes(req.body.assignmentType) ? req.body.assignmentType : "secondary",
    };
    if (req.body.validUntil) entry.validUntil = req.body.validUntil;
    if (existingIdx >= 0) {
      users[i].accessList[existingIdx] = entry;
    } else {
      users[i].accessList.push(entry);
    }
  }

  writeJSON(USERS_FILE, users);
  if (users[i].id === req.session.user.id) {
    req.session.user.accessList = getAccessList(users[i]);
  }
  res.json({ ok: true, accessList: users[i].accessList });
});

app.delete("/api/users/:id", auth, function(req, res) {
  const me = req.session.user;
  const users = readJSON(USERS_FILE);
  const target = users.find(function(u) { return u.id === req.params.id; });
  if (!target) return res.status(404).json({ error: "Not found" });
  // Block deletion of breakglass accounts
  if (isBreakglassEmail(target.email))
    return res.status(403).json({ error: st("breakglass_no_delete", req) });

  if (me.role === "admin") {
    writeJSON(USERS_FILE, users.filter(function(u) { return u.id !== req.params.id; }));
    try { const up = _prefsAll(); if (up[target.id]) { delete up[target.id]; writeJSON(USER_PREFS_FILE, up); } } catch (e) {}
    return res.json({ ok: true });
  }
  // Department manager can remove users from their own departments
  // Subgroup manager can remove users from their own subgroups
  var myAccDel = getAccessList(readJSON(USERS_FILE).find(function(u){ return u.id === me.id; }) || {});
  var isDeptMgr = myAccDel.some(function(t){ return t.role === "department_manager" || t.role === "deptManager"; });
  var isSubMgr  = myAccDel.some(function(t){ return t.role === "subgroup_manager"  || t.role === "undergruppeansvarlig"; });

  if (isDeptMgr || isSubMgr) {
    var myDeptsDel = myAccDel.map(function(t){ return t.department; });
    // Can only act on users in departments the caller manages
    var targetInMyDept = getAccessList(target).some(function(x){ return myDeptsDel.indexOf(x.department) !== -1; });
    if (!targetInMyDept) return res.status(403).json({ error: st("no_access_user", req) });

    // Remove only the access entries that belong to caller's departments
    var remaining = getAccessList(target).filter(function(x){ return myDeptsDel.indexOf(x.department) === -1; });
    if (remaining.length === 0) {
      writeJSON(USERS_FILE, users.filter(function(u){ return u.id !== req.params.id; }));
    } else {
      target.accessList = remaining;
      writeJSON(USERS_FILE, users);
    }
    return res.json({ ok: true });
  }
  res.status(403).json({ error: st("access_denied", req) });
});

// \u2500\u2500 Events API \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500

// SSE stream: clients connect for live updates
// \u2500\u2500 QUICK WIN 1: iCal / ICS calendar feed \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Public URL: /ical/:deptSlug.ics  (or /ical/all.ics for all events)
app.get("/ical/:slug.ics", function(req, res) {
  const slug     = req.params.slug;
  const settings = getSettings();
  const events   = readJSON(EVENTS_FILE);
  const siteName = settings.siteName || "Event-Admin";

  // Filter by department slug or show all
  const dept = slug === "all" ? null
    : (settings.departments || []).find(function(d) { return d.slug === slug || d.id === slug; });
  if (slug !== "all" && !dept) return res.status(404).send("Department not found");

  const deptId   = dept ? dept.id : null;
  const filtered = events.filter(function(ev) {
    if (ev.hidden) return false;
    if (deptId && ev.department !== deptId) return false;
    if (_evStage(ev) !== "public" || ev.hideFromList || ev.isInternal) return false;   // drafts and volunteer-only events stay out
    return ev.date;
  });

  // Dates are stored as "2026-12-12T10:00" (time included) or just "2026-12-12"
  function icsDate(dateStr, timeStr) {
    if (!dateStr) return null;
    const day = String(dateStr).slice(0, 10);
    const tm = timeStr || (String(dateStr).length > 10 ? String(dateStr).slice(11, 16) : "00:00");
    const d = new Date(day + "T" + tm + ":00");
    if (isNaN(d.getTime())) return null;
    return d.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
  }
  function icsEscape(s) {
    return (s || "").replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\n/g, "\\n");
  }
  function foldLine(line) {
    // RFC 5545: fold lines longer than 75 octets
    const chunks = [];
    while (line.length > 75) { chunks.push(line.slice(0, 75)); line = " " + line.slice(75); }
    chunks.push(line);
    return chunks.join("\r\n");
  }

  const domain = settings.adminDomain || DOMAIN;
  const lines = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//EventAdmin//" + icsEscape(siteName) + "//NO",
    "CALSCALE:GREGORIAN",
    "METHOD:PUBLISH",
    "X-WR-CALNAME:" + icsEscape((dept ? dept.name + " \u2013 " : "") + siteName),
    "X-WR-TIMEZONE:Europe/Oslo",
    "REFRESH-INTERVAL;VALUE=DURATION:PT1H",
    "X-PUBLISHED-TTL:PT1H",
  ];

  filtered.forEach(function(ev) {
    const dtstart = icsDate(ev.date, ev.time);
    if (!dtstart) return;
    let dtend = ev.endTime || ev.endDate ? icsDate(ev.endDate || ev.date, ev.endTime || (ev.endDate ? "23:59" : null)) : null;
    if (!dtend || dtend < dtstart) { const t2 = new Date(new Date(String(ev.date).slice(0, 10) + "T" + (String(ev.date).slice(11, 16) || "00:00") + ":00").getTime() + 2 * 3600 * 1000); dtend = t2.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, ""); }
    const url = "https://" + (ev.slug ? ev.slug + "." + domain : domain);
    lines.push("BEGIN:VEVENT");
    lines.push(foldLine("UID:" + ev.id + "@" + domain));
    lines.push(foldLine("DTSTAMP:" + new Date().toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "")));
    lines.push(foldLine("DTSTART:" + dtstart));
    lines.push(foldLine("DTEND:" + dtend));
    lines.push(foldLine("SUMMARY:" + icsEscape(ev.title)));
    if (ev.location)    lines.push(foldLine("LOCATION:" + icsEscape(ev.location)));
    if (ev.description) lines.push(foldLine("DESCRIPTION:" + icsEscape(String(ev.description).slice(0, 500))));
    lines.push(foldLine("URL:" + url));
    const typeEmoji = { stand:"\ud83c\udfaa", kurs:"\ud83d\udcda", tur:"\ud83d\uddfa\ufe0f", mote:"\ud83e\udd1d" }[ev.eventType] || "\ud83d\udcc5";
    lines.push(foldLine("CATEGORIES:" + typeEmoji + " " + icsEscape(ev.eventType || "stand")));
    lines.push("END:VEVENT");
  });
  lines.push("END:VCALENDAR");

  res.setHeader("Content-Type", "text/calendar; charset=utf-8");
  res.setHeader("Content-Disposition", "inline; filename=\"" + slug + ".ics\"");
  res.setHeader("Cache-Control", "public, max-age=3600");
  res.send(lines.join("\r\n"));
});

// Logged volunteer minutes per event (Min side / admin time logs), for the
// summary boxes above the event list. Only events the user can see.
app.get("/api/volunteer-hours", auth, function(req, res) {
  var user = req.session.user;
  var myAvds = getUserDepartments(user);
  var visible = new Set();
  readJSON(EVENTS_FILE).forEach(function(e) {
    if (!e || !e.id) return;
    if (user.role === "admin" || (e.department && myAvds.includes(e.department)) ||
        (e.collaborators || []).some(function(c) { return myAvds.includes(c.departmentId) && c.status === "accepted"; })) visible.add(e.id);
  });
  var byEvent = {}, people = {};
  (readJSON(VOLUNTEERS_FILE) || []).forEach(function(v) {
    var tl = (v && v.timeLogs) || {};
    Object.keys(tl).forEach(function(eid) {
      if (!visible.has(eid)) return;
      var m = 0;
      (tl[eid] || []).forEach(function(r) { m += parseInt(r && r.minutes, 10) || 0; });
      if (!m) return;
      byEvent[eid] = (byEvent[eid] || 0) + m;
      (people[eid] = people[eid] || []).push(v.id);
    });
  });
  res.json({ byEvent: byEvent, people: people });
});

app.get("/api/events/stream", function(req, res) {
  const department = req.query.department || null;
  const clientId = sseNextId++;

  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("X-Accel-Buffering", "no"); // proxies must not hold the stream back
  res.flushHeaders();

  // send immediate ping to confirm connection
  res.write("data: " + JSON.stringify({ type: "connected", clientId }) + "\n\n");

  sseClients.set(clientId, { res, department });

  // Keepalive hvert 25 sek
  const keepalive = setInterval(function() {
    try { res.write(": keepalive\n\n"); } catch(e) {}
  }, 25000);

  req.on("close", function() {
    clearInterval(keepalive);
    sseClients.delete(clientId);
  });
});

app.get("/api/events", auth, function(req, res) {
  var user = req.session.user;
  var myAvds = getUserDepartments(user);
  res.json(readJSON(EVENTS_FILE).filter(function(e) {
    // Admin ser alt
    if (user.role === "admin") return true;
    // not-admin without noen department ser ingenting
    if (!myAvds.length) return false;
    // Event must belong to one of the user's departments (or be a collaborator)
    if (e.department && myAvds.includes(e.department)) return true;
    // show events der user is collaborator (invitert from annen department)
    return (e.collaborators || []).some(function(c) {
      return myAvds.includes(c.departmentId) && (c.status === "accepted" || c.status === "pending");
    });
  }).map(function(e) {
    var isCollabGuest = !canEditEvent(e, user) && (e.collaborators || []).some(function(c) {
      return myAvds.includes(c.departmentId);
    });
    var myCollabAvdId = isCollabGuest
      ? (e.collaborators || []).find(function(c) { return myAvds.includes(c.departmentId); }).departmentId
      : null;
    var collabStatus = isCollabGuest
      ? (e.collaborators || []).find(function(c) { return myAvds.includes(c.departmentId); }).status
      : null;
    // The list view only needs summary data. Shipping the whole event object
    // meant every lottery prize image (stored as a base64 data URI) travelled
    // with it - one 2.7 MB image made this response 3 MB, fetched on every
    // page load. Heavy detail is available from GET /api/events/:id.
    const slim = Object.assign({}, e, {
      stage: _evStage(e), stageCap: _evStageCap(e),
      registrationCount: (e.registrations || []).length,
      canEdit: canEditEvent(e, user),
      isCollabGuest:  isCollabGuest,
      myCollabAvdId:  myCollabAvdId,
      collabStatus:   collabStatus,
      // remove sensitive data from other departments' staff
      guestStaff:  e.guestStaff  || {},
      guestShifts: e.guestShifts || {},
    });

    // Prize images are stored as base64 data URIs on the winner record. One
    // 2.7 MB image made this response 3 MB. The list needs the winners (for
    // counts and the consolation-email flow) but never renders the image, so
    // send a flag instead; the full record comes from GET /api/events/:id.
    if (slim.lottery && Array.isArray(slim.lottery.winners) && slim.lottery.winners.length) {
      slim.lottery = Object.assign({}, slim.lottery, {
        winners: slim.lottery.winners.map(function(w) {
          if (!w) return w;
          const copy = Object.assign({}, w);
          // Never ship image bytes in a list response - a URL is a few dozen
          // bytes and the browser caches the image itself.
          copy.prizeImage = prizeImageRef(w);
          if (copy.prizeImage && copy.prizeImage.indexOf("data:") === 0) copy.prizeImage = null;
          return copy;
        })
      });
    }
    return slim;
  }));
});

// Full lottery record including prize images. These are base64 data URIs and
// far too large for the events list, so the list sends winners without them
// and the admin panel fetches the complete record from here when opened.

// \u2500\u2500 Prize images by reference, not by value \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Inventory images are stored as base64 data URIs. Copying that blob onto
// every lottery winner put a multi-megabyte string into events.json, into
// the admin event list, into every SSE display push and into every TV
// refresh. Winners now carry a URL; the bytes are served once from here and
// cached by the browser (and by the Pi kiosks), keyed on content so a
// changed image still busts the cache.
function decodeDataUri(uri) {
  const m = /^data:([^;,]+);base64,(.*)$/s.exec(String(uri || ""));
  if (!m) return null;
  try { return { mime: m[1], buf: Buffer.from(m[2], "base64") }; }
  catch (e) { return null; }
}

// URL for a winner's prize image, tolerating older records that still hold
// the raw data URI inline.

// \u2500\u2500 Cancelled-event presentation \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// The strikethrough + AVLYST badge pairing was written out by hand in four
// places, so a change (such as making the badge immune to the inherited
// strikethrough) had to be repeated four times. One definition instead.
//
// NB the badge MUST stay display:inline-block. Text decoration propagates to
// in-flow descendants and a child cannot switch it off with
// text-decoration:none - only an atomic inline-level box escapes the line.
function cancelledTitleStyle(ev) {
  return (ev && ev.cancelled && !ev.rescheduledToDate)
    ? ' style="text-decoration:line-through;opacity:.6"' : '';
}

function cancelledBadge(ev, variant) {
  if (!ev || !ev.cancelled || ev.rescheduledToDate) return '';
  const label = 'AVLYST';
  if (variant === 'soft') {
    return '<span style="display:inline-block;background:#fee2e2;color:#991b1b;font-size:.7rem;'
         + 'font-weight:700;padding:1px 7px;border-radius:8px;margin-left:.4rem;text-decoration:none">' + label + '</span>';
  }
  if (variant === 'large') {
    return '<span style="display:inline-block;margin-left:.4rem;background:#ef4444;color:#fff;font-size:.6rem;'
         + 'font-weight:800;padding:2px 7px;border-radius:8px;letter-spacing:.04em;text-decoration:none">' + label + '</span>';
  }
  return ' <span style="display:inline-block;font-size:.65rem;background:#ef4444;color:#fff;padding:1px 5px;'
       + 'border-radius:6px;vertical-align:middle;font-weight:700;text-decoration:none">' + label + '</span>';
}

function prizeImageRef(w) {
  if (!w) return null;
  if (w.prizeImageUrl) return w.prizeImageUrl;
  if (w.prizeInventarId) return "/api/inventory/" + w.prizeInventarId + "/image";
  if (w.prizeImage && /^https?:|^\//.test(w.prizeImage)) return w.prizeImage;
  return w.prizeImage || null;   // legacy inline data URI
}

// Public: prize photos appear on the public event page and on TV screens,
// which have no session.
app.get("/api/inventory/:id/image", function(req, res) {
  const item = readJSON(INVENTORY_FILE).find(function(i) { return i.id === req.params.id; });
  if (!item || !item.image) return res.status(404).end();
  const dec = decodeDataUri(item.image);
  if (!dec) {
    // Already a URL rather than a data URI - just point at it
    if (/^https?:|^\//.test(item.image)) return res.redirect(item.image);
    return res.status(404).end();
  }
  const etag = '"' + require("crypto").createHash("sha1").update(dec.buf).digest("hex").slice(0, 16) + '"';
  if ((req.headers["if-none-match"] || "").indexOf(etag) !== -1) return res.status(304).end();
  res.setHeader("Content-Type", dec.mime);
  res.setHeader("ETag", etag);
  res.setHeader("Cache-Control", "public, max-age=86400");
  res.end(dec.buf);
});

app.get("/api/events/:id/lottery", auth, managerOrAdmin, function(req, res) {
  const ev = readJSON(EVENTS_FILE).find(function(e) { return e.id === req.params.id; });
  if (!ev) return res.status(404).json({ error: st("event_missing", req) });
  if (!canEditEvent(ev, req.session.user)) return res.status(403).json({ error: st("no_access", req) });
  const lot = ev.lottery || {};
  if (Array.isArray(lot.winners)) {
    return res.json(Object.assign({}, lot, {
      winners: lot.winners.map(function(w) {
        return Object.assign({}, w, { prizeImage: prizeImageRef(w) });
      })
    }));
  }
  res.json(lot);
});

app.get("/api/search", auth, function(req, res) {
  var q = (req.query.q || "").trim().toLowerCase();
  if (!q || q.length < 2) return res.json([]);
  var user = req.session.user;
  var myAvds = getUserDepartments(user);

  // Events (permission-filtered)
  var eventResults = readJSON(EVENTS_FILE).filter(function(e) {
    if (user.role === "admin") return true;
    if (!myAvds.length) return false;
    if (e.department && myAvds.includes(e.department)) return true;
    return (e.collaborators || []).some(function(c) {
      return myAvds.includes(c.departmentId) && (c.status === "accepted" || c.status === "pending");
    });
  }).filter(function(e) {
    return (e.title       && e.title.toLowerCase().includes(q))
        || (e.description && e.description.toLowerCase().includes(q))
        || (e.location    && e.location.toLowerCase().includes(q))
        || (e.eventType   && e.eventType.toLowerCase().includes(q));
  }).slice(0, 10).map(function(e) {
    return { kind: "event", id: e.id, title: e.title, date: e.date, location: e.location, eventType: e.eventType };
  });

  // Volunteers
  var volResults = readJSON(VOLUNTEERS_FILE).filter(function(v) {
    if (!myAvds.length && user.role !== "admin") return false;
    if (user.role === "admin") return true;
    var vDepts = Array.isArray(v.departments) && v.departments.length ? v.departments : (v.department ? [v.department] : []);
    return vDepts.some(function(d) { return myAvds.includes(d); });
  }).filter(function(v) {
    return (v.name  && v.name.toLowerCase().includes(q))
        || (v.email && v.email.toLowerCase().includes(q))
        || (v.phone && v.phone.includes(q));
  }).slice(0, 8).map(function(v) {
    return { kind: "volunteer", id: v.id, name: v.name, email: v.email || "", phone: v.phone || "" };
  });

  // Inventory
  var inventarResults = readJSON(INVENTORY_FILE).filter(function(item) {
    if (user.role === "admin") return true;
    if (!myAvds.length) return false;
    return !item.department || myAvds.includes(item.department);
  }).filter(function(item) {
    return (item.name        && item.name.toLowerCase().includes(q))
        || (item.description && item.description.toLowerCase().includes(q))
        || (item.category    && item.category.toLowerCase().includes(q));
  }).slice(0, 8).map(function(item) {
    return {
      kind: "inventar",
      id: item.id,
      name: item.name,
      category: item.category || "annet",
      quantity: item.quantity || 0,
      perPackage: item.perPackage || 1,
      enhet: item.enhet || "stk",
      image: item.image || null
    };
  });

  // Members
  var memberResults = readJSON(MEMBERS_FILE).filter(function(m) {
    if (!myAvds.length && user.role !== "admin") return false;
    if (user.role === "admin") return true;
    return myAvds.includes(m.department);
  }).filter(function(m) {
    return (m.name  && m.name.toLowerCase().includes(q))
        || (m.email && m.email.toLowerCase().includes(q))
        || (m.phone && (m.phone + "").includes(q));
  }).slice(0, 8).map(function(m) {
    return { kind: "member", id: m.id, name: m.name, email: m.email || "", phone: m.phone || "", memberNumber: m.memberNumber || "" };
  });

  // Users (login accounts): admins see all, department managers those who share a department
  var userResults = [];
  if (user.role === "admin" || myAvds.length) {
    userResults = (readJSON(USERS_FILE) || []).filter(function(u) {
      if (user.role === "admin") return true;
      return getUserDepartments(u).some(function(d) { return myAvds.includes(d); });
    }).filter(function(u) {
      return (u.name && u.name.toLowerCase().includes(q)) || (u.email && u.email.toLowerCase().includes(q));
    }).slice(0, 6).map(function(u) { return { kind: "user", id: u.id, name: u.name || "", email: u.email || "" }; });
  }

  // Forms (standalone and per event), within the same department rules
  var _evTitles = {}; readJSON(EVENTS_FILE).forEach(function(e) { _evTitles[e.id] = e.title; });
  var formResults = (readJSON(FORMS_FILE) || []).filter(function(f) {
    if (user.role === "admin") return true;
    return !!f.department && myAvds.includes(f.department);
  }).filter(function(f) {
    return f.title && f.title.toLowerCase().includes(q);
  }).slice(0, 6).map(function(f) { return { kind: "form", id: f.id, title: f.title || "", eventId: f.eventId || null, eventTitle: f.eventId ? (_evTitles[f.eventId] || "") : "" }; });

  res.json(eventResults.concat(inventarResults).concat(volResults).concat(memberResults).concat(userResults).concat(formResults));
});

app.get("/api/events/:id/routecoords", auth, async function(req, res) {
  const events = readJSON(EVENTS_FILE);
  const ev = events.find(function(e) { return e.id === req.params.id; });
  if (!ev) return res.status(404).json({ error: st("not_found_generic", req) });
  if (!ev.route || !ev.route.days) return res.json({ coords: [], dayCoords: [], coordCache: {}, geocodeStatus: [] });

  const forceRefresh = req.query.refresh === "1";

  // fetch all unike stedsnavn
  const allNames = [];
  const days = ev.route.days || [];
  days.forEach(function(day) {
    (day.stages || []).forEach(function(e) {
      if (e.from && !allNames.includes(e.from)) allNames.push(e.from);
      if (e.to && !allNames.includes(e.to)) allNames.push(e.to);
    });
  });

  // Geocode all steder \u2013 use lagrede koordinater from etappene
  const coordCache = {};
  const geocodeStatus = [];

  // fetch koordinater directly from etappene (allerede geocodet in frontend)
  days.forEach(function(day) {
    (day.stages || []).forEach(function(e) {
      if (e._fra_lat && e.from && !coordCache[e.from]) {
        coordCache[e.from] = { lat: e._fra_lat, lon: e._fra_lon };
      }
      if (e._lat && e.to && !coordCache[e.to]) {
        coordCache[e.to] = { lat: e._lat, lon: e._lon };
      }
    });
  });

  // Geocode steder som mangler koordinater via Nominatim
  const missing = allNames.filter(function(n) { return !coordCache[n]; });
  for (var i = 0; i < missing.length; i++) {
    const name = missing[i];
    try {
      const coords = await new Promise(function(resolve) {
        const url = "https://nominatim.openstreetmap.org/search?format=json&limit=1&q=" + encodeURIComponent(name + ", Norway") + "&accept-language=no";
        require("https").get(url, { headers: { "User-Agent": "event-admin/1.0" } }, function(r) {
          let data = "";
          r.on("data", function(c) { data += c; });
          r.on("end", function() {
            try {
              const d = JSON.parse(data);
              if (d && d[0]) resolve({ lat: parseFloat(d[0].lat), lon: parseFloat(d[0].lon) });
              else resolve(null);
            } catch(e) { resolve(null); }
          });
        }).on("error", function() { resolve(null); });
      });
      if (coords) {
        coordCache[name] = coords;
        geocodeStatus.push({ name, ok: true });
      } else {
        geocodeStatus.push({ name, ok: false, reason: "not found" });
      }
      if (i < missing.length - 1) await new Promise(function(resolve) { setTimeout(resolve, 200); });
    } catch(e) {
      geocodeStatus.push({ name, ok: false, reason: e.message });
    }
  }

  // build koordinat-lister per dag and totalt
  const dayCoords = [];
  const allCoords = [];

  days.forEach(function(day) {
    const dayCrds = [];
    (day.stages || []).forEach(function(e) {
      const fra = coordCache[e.from];
      const til = coordCache[e.to];
      if (fra && !dayCrds.find(function(c) { return c[0] === fra.lat && c[1] === fra.lon; }))
        dayCrds.push([fra.lat, fra.lon]);
      if (til && !dayCrds.find(function(c) { return c[0] === til.lat && c[1] === til.lon; }))
        dayCrds.push([til.lat, til.lon]);
    });
    dayCoords.push(dayCrds);
    dayCrds.forEach(function(c) {
      if (!allCoords.find(function(x) { return x[0] === c[0] && x[1] === c[1]; }))
        allCoords.push(c);
    });
  });

  res.json({ coords: allCoords, dayCoords, coordCache, geocodeStatus });
});


app.get("/api/events/:id", function(req, res) {
  const ev = readJSON(EVENTS_FILE).find(function(e) { return e.id === req.params.id || e.slug === req.params.id; });
  if (!ev) return res.status(404).json({ error: "Not found" });
  // public endpoint \u2013 never send sensitive data
  const isAuth = !!req.session.user;
  if (isAuth) {
    // Logged-in admin/staff: send everything except cancelToken and checkinPin in registrations
    var safeEv = Object.assign({}, ev);
    safeEv.registrations = (ev.registrations || []).map(function(r) {
      var safe = Object.assign({}, r);
      delete safe.cancelToken;
      return safe;
    });
    return res.json(safeEv);
  }
  // public: send only metadata without personal data
  res.json({
    id: ev.id, slug: ev.slug, title: ev.title, description: ev.description,
    date: ev.date, endDate: ev.endDate, endTime: ev.endTime, location: ev.location,
    eventType: ev.eventType, image: ev.image,
    maxParticipants: ev.maxParticipants,
    registrationCount: (ev.registrations||[]).filter(function(r){return !r.anonymized;}).length,
    showParticipants: ev.showParticipants, isPublic: ev.isPublic,
    hasPin: !!ev.staffPin, department: ev.department, lottery: ev.lottery ? {
      enabled: !!ev.lottery.enabled, prize: ev.lottery.prize||"", type: ev.lottery.type||"trekning"
    } : null,
    route: ev.route || null, roomplan: ev.roomplan || null,
  });
});

// ══ Event status: draft → volunteers → public ══════════════════════════
// One status decides who sees an event:
//   draft       – managers only (planning, «Finn dato»)
//   volunteers  – also the department's volunteers on Min side; nothing public
//   public      – also the public page and lists, TV, calendar feed (linkOnly: page by link, not listed)
// The older flags (isPublic, hideFromList) are derived from it, so every public channel follows.
// Board meetings and internal events stop at «volunteers». publishAt = planned move to «public».
const EV_STAGES = ["draft", "volunteers", "public"];
function _evStage(ev) {
  if (!ev) return "draft";
  if (EV_STAGES.indexOf(ev.stage) >= 0) return ev.stage;
  return ev.isPublic && !ev.isInternal ? "public" : "volunteers";
}
function _evStageCap(ev) { return ev.boardMeeting || ev.isInternal ? "volunteers" : "public"; }
function _applyStage(ev, stage, linkOnly) {
  if (EV_STAGES.indexOf(stage) < 0) stage = "draft";
  if (stage === "public" && _evStageCap(ev) !== "public") stage = "volunteers";
  if (linkOnly !== undefined) ev.linkOnly = !!linkOnly;
  else if (ev.linkOnly === undefined) ev.linkOnly = !!(ev.isPublic && ev.hideFromList);
  const before = ev.stage;
  ev.stage = stage;
  ev.isPublicSetByUser = true;
  if (stage === "public") {
    ev.isPublic = true; ev.hideFromList = !!ev.linkOnly; ev.publishAt = null;
    if (before !== "public") ev.publishedAt = new Date().toISOString();
  } else {
    ev.isPublic = false; ev.hideFromList = true;
  }
  if (before !== stage) ev.stageChangedAt = new Date().toISOString();
}
// Before going public: what is missing (shown as a checklist, never a hard block)
function _publishChecklist(ev) {
  const regForms = (ev.forms || []).filter(function(f) { return f && f.kind !== "evaluation"; });
  return [
    { id: "date", ok: !!ev.date, label: "Dato" },
    { id: "place", ok: !!(ev.location || ev.locationAddress), label: "Sted" },
    { id: "description", ok: !!String(ev.description || "").trim(), label: "Beskrivelse" },
    { id: "image", ok: !!(ev.image || ev.imageUrl || ev.coverImage), label: "Bilde" },
    { id: "signup", ok: !!(ev.externalRegUrl || regForms.length || ev.noRegistration || (ev.tabHidden || []).indexOf("reg") >= 0), label: "Påmelding (eller ingen påmelding)" }
  ];
}
// Tell the department's volunteers (or the board, for a board meeting) about an event
function _notifyVolunteersOfEvent(ev) {
  const s = getSettings();
  const d = (s.departments || []).find(function(x) { return x.id === ev.department; }) || {};
  const vols = readJSON(VOLUNTEERS_FILE) || [];
  let list;
  if (ev.boardMeeting) { const b = _boardForEvent(ev, s); const ids = (b ? b.members : []).map(function(m) { return m.volId; }); list = vols.filter(function(v) { return ids.indexOf(v.id) >= 0; }); }
  else list = vols.filter(function(v) { return _volDeptIds(v).indexOf(ev.department) >= 0; });
  list = list.filter(function(v) { return v.email && !v.inactive && !v.archived; });
  const siteName = s.siteName || "Event-Admin";
  const when = ev.date ? new Date(ev.date).toLocaleString("nb-NO", { weekday: "long", day: "numeric", month: "long", hour: "2-digit", minute: "2-digit", timeZone: "Europe/Oslo" }) : "Dato kommer";
  const url = _siteUrl() + "/minside";
  list.forEach(function(v) {
    const html = '<div style="font-family:sans-serif;max-width:520px;margin:0 auto;color:#111">'
      + '<h2 style="margin:0 0 .5rem">' + escHtml(ev.title || "") + '</h2>'
      + '<p style="margin:0 0 .3rem">' + escHtml(when) + (ev.location ? ' · ' + escHtml(ev.location) : '') + '</p>'
      + (ev.description ? '<p style="color:#444">' + escHtml(String(ev.description).slice(0, 400)) + '</p>' : '')
      + '<p>Hei ' + escHtml(v.name || "") + ', ' + escHtml(d.displayName || d.name || siteName) + ' har lagt ut ' + (ev.boardMeeting ? 'et styremøte' : 'et nytt arrangement') + '. Se det, meld deg som frivillig og registrer tid på Min side.</p>'
      + '<p style="margin:1.2rem 0"><a href="' + escHtml(url) + '" style="background:#FFD100;color:#111;padding:.7rem 1.4rem;border-radius:8px;text-decoration:none;font-weight:700">Åpne Min side →</a></p></div>';
    sendEmail({ to: v.email, subject: (ev.boardMeeting ? "Styremøte: " : "Nytt arrangement: ") + (ev.title || ""), html: html, department: ev.department || null, eventId: ev.id, category: "volunteer" }).catch(function() {});
  });
  return list.length;
}
// POST /api/events/:id/stage { stage, linkOnly?, publishAt?, notify? }
app.post("/api/events/:id/stage", auth, managerOrAdmin, function(req, res) {
  const events = readJSON(EVENTS_FILE) || [];
  const ev = events.find(function(e) { return e.id === req.params.id; });
  if (!ev) return res.status(404).json({ error: st("event_not_found", req) });
  if (!hasDeptAccess(req.session.user, ev.department)) return res.status(403).json({ error: st("no_access_department", req) });
  const prev = _evStage(ev);
  if (req.body.stage !== undefined) _applyStage(ev, String(req.body.stage), req.body.linkOnly === undefined ? undefined : !!req.body.linkOnly);
  else if (req.body.linkOnly !== undefined) _applyStage(ev, prev, !!req.body.linkOnly);
  if (req.body.publishAt !== undefined) {
    const t = req.body.publishAt ? new Date(req.body.publishAt) : null;
    if (t && isNaN(t.getTime())) return res.status(400).json({ error: "Ugyldig tidspunkt" });
    if (t && _evStageCap(ev) !== "public") return res.status(400).json({ error: "Dette arrangementet kan ikke publiseres offentlig." });
    ev.publishAt = t && _evStage(ev) !== "public" ? t.toISOString() : null;
    ev.publishAtBy = ev.publishAt ? (req.session.user.name || req.session.user.email || "") : null;
  }
  let notified = 0;
  if (req.body.notify && _evStage(ev) !== "draft" && !ev.cancelled) { notified = _notifyVolunteersOfEvent(ev); ev.volunteersNotifiedAt = new Date().toISOString(); }
  writeJSON(EVENTS_FILE, events);
  broadcastEventUpdate(ev.department);
  res.json({ ok: true, stage: _evStage(ev), linkOnly: !!ev.linkOnly, publishAt: ev.publishAt || null, publishedAt: ev.publishedAt || null, notified: notified, checklist: _publishChecklist(ev), cap: _evStageCap(ev) });
});
// Planned publishing: once a minute, events whose time has come go public
setInterval(function() {
  try {
    const events = readJSON(EVENTS_FILE) || [];
    const now = Date.now(); const depts = {};
    events.forEach(function(ev) {
      if (!ev.publishAt || ev.cancelled) return;
      if (new Date(ev.publishAt).getTime() > now) return;
      if (_evStageCap(ev) === "public") { _applyStage(ev, "public"); depts[ev.department || ""] = 1; console.log("[publish] " + (ev.title || ev.id) + " published as planned"); }
      ev.publishAt = null;
    });
    if (Object.keys(depts).length) { writeJSON(EVENTS_FILE, events); Object.keys(depts).forEach(function(d) { broadcastEventUpdate(d || null); }); }
  } catch (e) { console.warn("[publish] " + e.message); }
}, 60 * 1000);
// One-time: give existing events a status that keeps exactly what the public sees today
setTimeout(function() {
  try {
    const s = getSettings(); if (s._stageMigrated) return;
    const events = readJSON(EVENTS_FILE) || []; let n = 0;
    events.forEach(function(ev) {
      if (EV_STAGES.indexOf(ev.stage) >= 0) return;
      if (ev.isInternal || ev.boardMeeting) ev.stage = "volunteers";
      else if (!ev.hideFromList) { ev.stage = "public"; ev.linkOnly = false; ev.isPublic = true; }
      else if (ev.isPublic) { ev.stage = "public"; ev.linkOnly = true; }
      else ev.stage = "volunteers";
      ev.isPublicSetByUser = true; n++;
    });
    if (n) { writeJSON(EVENTS_FILE, events); console.log("[stage] gave " + n + " events a status"); }
    s._stageMigrated = new Date().toISOString(); saveSettings(s);
  } catch (e) { console.warn("[stage] " + e.message); }
}, 2500);
app.post("/api/events", auth, managerOrAdmin, upload.fields([{name:"image",maxCount:1},{name:"tvImageTop",maxCount:1},{name:"tvImageBottom",maxCount:1}]), function(req, res) {
  const title       = sanitizeInput((req.body.title || "").trim().slice(0, 200));
  const description = sanitizeInput((req.body.description || "").slice(0, 5000));
  const date = req.body.date && req.body.date.trim() ? req.body.date.trim() : null;
  const location    = sanitizeInput((req.body.location || "").slice(0, 200));
  const maxP        = Number(req.body.maxParticipants) || 0;
  const showP       = req.body.showParticipants === "true";
  const showC       = req.body.showCount === "true";
  const regDeadline = parseInt(req.body.regDeadlineDays) >= 0 ? parseInt(req.body.regDeadlineDays) : 14;
  const regDeadlineOverride = req.body.regDeadlineOverride === "true";
  const isPublic    = req.body.isPublic === "true";
  if (!title) return res.status(400).json({ error: "Title is required" });
  const s = getSettings();
  const evDomain = s.eventDomain || DOMAIN;
  const users = readJSON(USERS_FILE);
  const creator = users.find(function(u) { return u.id === req.session.user.id; });
  // Department: use explicit value from request, otherwise user's department
  var ct = creator ? getAccessList(creator) : [];
  const eventDept = req.body.department || (ct.length ? ct[0].department : null);
  const subgroup = req.body.subgroup || null;

  // Get name for department and subgroup for slug
  const deptObj = eventDept ? (s.departments || []).find(function(a){ return a.id === eventDept; }) : null;
  const ugObj  = (deptObj && subgroup) ? (deptObj.subgroups || []).find(function(u){ return u.id === subgroup; }) : null;

  function toSlugPart(str) {
    return (str || "").toLowerCase()
      .replace(/\u00e6/g,"ae").replace(/\u00f8/g,"o").replace(/\u00e5/g,"a")
      .replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"");
  }
  const parts = [toSlugPart(title)];
  if (deptObj) parts.push(toSlugPart(deptObj.name));
  if (ugObj)  parts.push(toSlugPart(ugObj.name));
  if (date)   parts.push(new Date(date).getFullYear());
  const baseSlug = parts.join("-");

  const events = readJSON(EVENTS_FILE);
  var slug = baseSlug;
  var counter = 2;
  while (events.find(function(e) { return e.slug === slug; })) {
    slug = baseSlug + "-" + counter++;
  }
  const ev = {
    id: uuid(), slug: slug, title: title, description: description,
    date: date || null, location: location,
    locationAddress: sanitizeInput((req.body.locationAddress || "").slice(0, 300)),
    basePlan: _cleanBasePlan(req.body.basePlan),
    maxParticipants: maxP, showParticipants: showP, showCount: showC,
    regDeadlineDays: regDeadline, regDeadlineOverride: regDeadlineOverride,
    externalRegUrl: (req.body.externalRegUrl || "").trim(),
    externalRegNewTab: req.body.externalRegNewTab !== "false",
    tabHidden: req.body.tabHidden ? JSON.parse(req.body.tabHidden) : (getSettings().defaultHiddenTabs || ['reg']),
    isPublic: isPublic,
    isPublicSetByUser: true,   // created non-public on purpose – publishing is a separate step
    hideFromList: req.body.hideFromList === "true",
    isInternal:    req.body.isInternal === "true",
    internalNote:  (req.body.internalNote || "").slice(0, 5000),
    emailTemplate: req.body.emailTemplate || "default",
    eventType: ["kurs","tur","mote"].indexOf(req.body.eventType) !== -1 ? req.body.eventType : "stand",
    boardMeeting: req.body.eventType === "mote" && (req.body.boardMeeting === "dept" || req.body.boardMeeting === "group") ? req.body.boardMeeting : null,
    endTime: req.body.endTime ? req.body.endTime.trim() : null,
    staffCallOffsetMin: (req.body.staffCallOffsetMin !== undefined && req.body.staffCallOffsetMin !== "") ? parseInt(req.body.staffCallOffsetMin, 10) : null,
    staffCallTime: req.body.staffCallTime ? req.body.staffCallTime.trim() : null,
    endDate: req.body.endDate ? req.body.endDate.trim() : null,
    image: (req.files && req.files["image"]) ? "/uploads/" + path.basename(req.files["image"][0].filename) : null,
    tvImageTop:    (req.files && req.files["tvImageTop"])    ? "/uploads/" + path.basename(req.files["tvImageTop"][0].filename)    : null,
    tvImageBottom: (req.files && req.files["tvImageBottom"]) ? "/uploads/" + path.basename(req.files["tvImageBottom"][0].filename) : null,
    registrations: [], staff: [], guestbook: [],
    predefinedTags: (function() { try { return JSON.parse(req.body.predefinedTags || "[]"); } catch(e) { return []; } })(),
    url: "https://" + slug + "." + evDomain,
    createdAt: new Date().toISOString(),
    createdBy: req.session.user.email,
    department: eventDept,
    subgroup: subgroup,
    purpose: ["goal_directed","member_activity","other"].indexOf(req.body.purpose) !== -1 ? req.body.purpose : null,
    targetGroup: sanitizeInput(String(req.body.targetGroup || "").trim().slice(0, 200)),
    participantCount: sanitizeInput(String(req.body.participantCount || "").trim().slice(0, 100)),
    meetupLocation: sanitizeInput((req.body.meetupLocation || "").slice(0, 200)),
    meetupAddress:  sanitizeInput((req.body.meetupAddress || "").slice(0, 300)),
    destination:    sanitizeInput((req.body.destination || "").slice(0, 200)) || null,
    destinationAddress: sanitizeInput((req.body.destinationAddress || "").slice(0, 300)) || null,
    destinationLat: req.body.destinationLat ? parseFloat(req.body.destinationLat) || null : null,
    destinationLon: req.body.destinationLon ? parseFloat(req.body.destinationLon) || null : null,
    meetupLat: req.body.meetupLat ? parseFloat(req.body.meetupLat) || null : null,
    meetupLon: req.body.meetupLon ? parseFloat(req.body.meetupLon) || null : null,
    locationLat: req.body.locationLat ? parseFloat(req.body.locationLat) || null : null,
    locationLon: req.body.locationLon ? parseFloat(req.body.locationLon) || null : null,
    staffPin: req.body.staffPin ? req.body.staffPin.trim() : null,
    isFinalized: req.body.isFinalized === "true",
    seriesId: req.body.seriesId || null,
    lottery: (function() {
      try { const l = JSON.parse(req.body.lottery || "null"); return l && l.enabled !== undefined ? { enabled: !!l.enabled, mode: l.mode || "manual", prize: (l.prize || "").slice(0, 100), winners: [] } : null; }
      catch(e) { return null; }
    })(),
  };
  _applyBoardMeeting(ev);
  // New events start as a draft unless the creator chose otherwise («Hvem skal se det?»)
  _applyStage(ev, EV_STAGES.indexOf(req.body.stage) >= 0 ? req.body.stage : (req.body.isPublic === "true" ? "public" : "draft"), req.body.linkOnly === "true");
  if (req.body.publishAt && ev.stage !== "public" && _evStageCap(ev) === "public") { const _pa = new Date(req.body.publishAt); if (!isNaN(_pa.getTime())) ev.publishAt = _pa.toISOString(); }
  events.push(ev);
  writeJSON(EVENTS_FILE, events);
  _bumpSavedPlace(ev);
  if (req.body.notifyVolunteers === "true" && ev.stage !== "draft") { _notifyVolunteersOfEvent(ev); ev.volunteersNotifiedAt = new Date().toISOString(); writeJSON(EVENTS_FILE, events); }
  broadcastEventUpdate(eventDept);
  res.json(ev);
});

