app.post("/api/events/:id/staff/checkin", rateLimit(30, 60000), function(req, res) {
  const name       = req.body.name;
  const role       = req.body.role || "";
  const department = req.body.department || "";
  const staffId    = req.body.staffId;
  const events     = readJSON(EVENTS_FILE);
  const ev = events.find(function(e) { return e.id === req.params.id || e.slug === req.params.id; });
  if (!ev) return res.status(404).json({ error: "Not found" });
  if (!ev.staff) ev.staff = [];
  if (staffId) {
    const s = ev.staff.find(function(s) { return s.id === staffId; });
    if (!s) return res.status(404).json({ error: "Not found" });
    s.checkedIn   = true;
    s.checkedInAt = new Date().toISOString();
    writeJSON(EVENTS_FILE, events);
    res.json({ ok: true, id: staffId });
  } else {
    if (!name) return res.status(400).json({ error: "Name is required" });
    const newId = uuid();
    const entry = { id: newId, name: name, role: role, checkedIn: true, addedAt: new Date().toISOString(), checkedInAt: new Date().toISOString() };
    if (department) entry.department = department;
    ev.staff.push(entry);
    writeJSON(EVENTS_FILE, events);
    res.json({ ok: true, id: newId });
  }
});


// \u2500\u2500 Walk-in self-registration (tablet, no auth) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Creates staff entry AND upserts volunteer record for statistics
// ── Interest signups ("I want more information") ─────────────────────
// Kept in ev.interestSignups – separate from registrations so they never
// count as participants, take a seat or use inventory.
function _anonymizeInterest(r) {
  r.name = "[slettet]"; r.email = "[slettet]"; r.phone = ""; r.answers = null;
  r.anonymized = true; r.anonymizedAt = new Date().toISOString();
}

function emailInterestConfirmation(ev, person, settings) {
  const tpl = resolveEmailTemplate(ev, "interest", settings);
  if (tpl && tpl.subject && tpl.body) {
    const subject = applyEmailVars(tpl.subject, ev, person, settings);
    const body    = applyEmailVars(tpl.body, ev, person, settings);
    return { subject: subject, html: _textToEmailHtml(body, settings.siteName || "Event-Admin", settings), text: body };
  }
  const L = {
    no: { s: "Takk for interessen – ", h: "Hei " + person.name + "!", b: "Vi har mottatt din henvendelse om «" + ev.title + "» og tar kontakt med mer informasjon." },
    sv: { s: "Tack för ditt intresse – ", h: "Hej " + person.name + "!", b: "Vi har tagit emot din förfrågan om «" + ev.title + "» och hör av oss med mer information." },
    en: { s: "Thanks for your interest – ", h: "Hi " + person.name + "!", b: "We have received your enquiry about «" + ev.title + "» and will get back to you with more information." },
  }[person.lang] || null;
  const m = L || { s: "Takk for interessen – ", h: "Hei " + person.name + "!", b: "Vi har mottatt din henvendelse om «" + ev.title + "» og tar kontakt med mer informasjon." };
  const text = m.h + "\n\n" + m.b + "\n\n– " + (settings.siteName || "Event-Admin");
  return { subject: m.s + ev.title, html: _textToEmailHtml(text, settings.siteName || "Event-Admin", settings), text: text };
}

app.post("/api/events/:id/interest", rateLimit(10, 60000), function(req, res) {
  const name  = sanitizeName(req.body.name);
  const email = (req.body.email || "").toLowerCase().trim().slice(0, 200);
  const phone = sanitizePhone(req.body.phone);
  if (!name) return res.status(400).json({ error: "Name is required" });
  if (!email && !phone) return res.status(400).json({ error: st("email_or_phone_required", req) });
  if (!validateName(name)) return res.status(400).json({ error: "Name contains invalid characters" });
  if (email && !validateEmail(email)) return res.status(400).json({ error: "Invalid email address" });
  if (!validatePhone(phone)) return res.status(400).json({ error: "Phone number contains invalid characters" });
  const events = readJSON(EVENTS_FILE);
  const ev = events.find(function(e) { return e.id === req.params.id || e.slug === req.params.id; });
  if (!ev) return res.status(404).json({ error: "Event not found" });
  const cfg = ev.formConfig || {};
  if (!cfg.interestEnabled) return res.status(403).json({ error: st("access_denied", req) });
  const fa = _sanitizeFormAnswers(cfg.interestFields, req.body.answers);
  if (fa.missing.length) return res.status(400).json({ error: st("required_fields_missing", req) + ": " + fa.missing.join(", ") });
  if (!ev.interestSignups) ev.interestSignups = [];
  const lang = ["no", "sv", "en"].includes(req.body.lang) ? req.body.lang : "no";
  const existing = email && ev.interestSignups.find(function(r) { return r.email === email && !r.anonymized; });
  if (existing) {
    existing.answers = Object.keys(fa.answers).length ? fa.answers : existing.answers;
    if (phone) existing.phone = phone;
    existing.updatedAt = new Date().toISOString();
    writeJSON(EVENTS_FILE, events);
    return res.json({ ok: true, alreadyRegistered: true });
  }
  const entry = { id: uuid(), name: name, email: email, phone: phone, lang: lang, registeredAt: new Date().toISOString() };
  if (Object.keys(fa.answers).length) entry.answers = fa.answers;
  ev.interestSignups.push(entry);
  writeJSON(EVENTS_FILE, events);
  broadcastEventUpdate(ev.department);
  const settings = getSettings();
  if (email) {
    const mail = emailInterestConfirmation(ev, entry, settings);
    const si = getEvSenderInfo(ev);
    sendEmail({ to: email, subject: mail.subject, html: mail.html, text: mail.text, fromName: si.name, department: ev.department, eventId: ev.id, category: "registration" }).catch(function() {});
  }
  notifyCreator(ev, "Ny interessepåmelding – " + ev.title, `
      <p>💡 <strong>${escHtml(name)}</strong> vil vite mer om <strong>${escHtml(ev.title)}</strong>.</p>
      <table style="font-size:.88rem;border-collapse:collapse;margin-top:.75rem">
        <tr><td style="padding:3px 12px 3px 0;color:#888">Navn</td><td><strong>${escHtml(name)}</strong></td></tr>
        ${email ? `<tr><td style="padding:3px 12px 3px 0;color:#888">E-post</td><td>${escHtml(email)}</td></tr>` : ''}
        ${phone ? `<tr><td style="padding:3px 12px 3px 0;color:#888">Telefon</td><td>${escHtml(phone)}</td></tr>` : ''}
        ${_formAnswerRows(cfg.interestFields, entry.answers)}
      </table>`);
  res.json({ ok: true });
});

