  if (!ev.guestShifts) ev.guestShifts = {};
  if (!ev.guestShifts[req.params.deptId]) ev.guestShifts[req.params.deptId] = [];
  ev.guestShifts[req.params.deptId].push({ id: uuid(), staffIds: ids, date, startTime, endTime });
