async function _sendPptx(req, res, slides, meta, fileBase) {
  if (!slides.length) return res.status(404).json({ error: st("not_found_generic", req) });
  const plan = planZip(buildPptxEntries(slides, meta));
  const fileName = (_safeFilePart(fileBase, 90) || "Presentation") + ".pptx";
  _sendZipHeaders(res, fileName);
  res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.presentationml.presentation");
  res.setHeader("Content-Length", String(plan.totalBytes));
  try { await streamZip(res, plan); res.end(); }
  catch (e) { if (!/client closed/.test(e.message)) console.error("[pptx] " + e.message); try { res.destroy(); } catch (e2) {} }
}

app.get("/api/events/:id/display/export.pptx", auth, managerOrAdmin, async function(req, res) {
  const ev = _findEventForMedia(req, res);
  if (!ev) return;
  const state = displayState.get(ev.id) || {};
  const slides = [];
  for (const s of (state.slides || [])) {
    const url = typeof s === "string" ? s : (s && (s.bg || s.url));
    const fp = _mediaUrlToPath(url);
    if (!fp) continue;
    let buf;
    try { buf = fs.readFileSync(fp); } catch (e) { continue; }
    buf = await _toPptxImage(buf);
    if (!buf) continue;
    const hasVideo = s && typeof s === "object" && s.type === "video-slide";
    slides.push({ buf: buf, title: ev.title || "", notes: hasVideo ? "(Video on this slide in the original presentation)" : "" });
  }
  const _pn = _presActiveName(ev.id) || ev.title || "Presentation";
  await _sendPptx(req, res, slides, { title: _pn }, _pn);
});

const _pptxUpload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 40 * 1024 * 1024, files: 400 } });
app.post("/api/pptx/from-images", auth, managerOrAdmin, rateLimit(20, 60000), _pptxUpload.array("slides", 400), async function(req, res) {
  let meta = {};
  try { meta = JSON.parse(req.body.meta || "{}"); } catch (e) {}
  const info = Array.isArray(meta.slides) ? meta.slides : [];
  const slides = [];
  for (let i = 0; i < (req.files || []).length; i++) {
    const buf = await _toPptxImage(req.files[i].buffer);
    if (!buf) continue;
    const m = info[i] || {};
    slides.push({ buf: buf, title: String(m.title || "").slice(0, 300), notes: String(m.notes || "").slice(0, 4000) });
  }
  await _sendPptx(req, res, slides, { title: String(meta.title || "").slice(0, 200) }, String(meta.title || "Presentation"));
});

