function _hex6(h, fallback) { h = String(h || "").replace("#", "").trim(); if (/^[0-9a-f]{3}$/i.test(h)) h = h.replace(/(.)/g, "$1$1"); return /^[0-9a-f]{6}$/i.test(h) ? h.toUpperCase() : fallback; }
