function _isLightHex(h) { const n = parseInt(h, 16); return (0.299 * ((n >> 16) & 255) + 0.587 * ((n >> 8) & 255) + 0.114 * (n & 255)) > 150; }
function _rotPoint(cx, cy, dx, dy, deg) { const r = deg * Math.PI / 180; return { x: cx + dx * Math.cos(r) - dy * Math.sin(r), y: cy + dx * Math.sin(r) + dy * Math.cos(r) }; }
