// POST /api/volunteers/import/preview — fuzzy name matching
app.post("/api/volunteers/import/preview", auth, managerOrAdmin, function(req, res) {
  var parsed = req.body.rows;

  // If fileBase64 provided, parse the Excel server-side using SheetJS.
  // Security: the file is parsed in memory only. Reading from a server-side
  // path (the old filePath parameter) was removed: it allowed path traversal.
  if (!parsed && req.body.filePath) {
    return res.status(400).json({ error: "filePath is no longer supported, send fileBase64" });
  }
  if (!parsed && req.body.fileBase64) {
    try {
      var buf = Buffer.from(String(req.body.fileBase64), "base64");
      if (!buf.length) return res.status(400).json({ error: "Empty file" });
      if (buf.length > 10 * 1024 * 1024) return res.status(413).json({ error: "File too large (max 10 MB)" });
      var XLSX = require("xlsx");
      var wb = XLSX.read(buf, { type: "buffer", cellDates: true });
      var ws = wb.Sheets[wb.SheetNames[0]];
      var raw = XLSX.utils.sheet_to_json(ws, { header: 1, raw: false, defval: "" });

      // Find header row
      var headerIdx = -1;
      for (var hi = 0; hi < Math.min(raw.length, 20); hi++) {
        if (raw[hi].some(function(c) { return String(c).toLowerCase().trim() === "dato"; })) { headerIdx = hi; break; }
      }
      if (headerIdx < 0) return res.status(400).json({ error: "Fant ikke header-rad med 'Dato'" });

      parsed = [];
      for (var ri = headerIdx + 1; ri < raw.length; ri++) {
        var r = raw[ri];
        var name = String(r[1] || "").trim();
        var hours = parseFloat(r[4]) || 0;
        if (!name || !hours) continue;
        var rawDate = String(r[0] || "").trim();
        var isoDate = "";
        // Try parsing the date
        var pd = new Date(rawDate);
        if (!isNaN(pd.getTime()) && pd.getFullYear() > 2020) {
          isoDate = pd.toISOString().slice(0, 10);
        }
        parsed.push({
          rawDate: rawDate, date: isoDate, name: name,
          activity: String(r[2] || "").trim(),
          description: String(r[3] || "").trim(),
          hours: hours,
        });
      }
    } catch(xlErr) {
      return res.status(500).json({ error: "Excel parse failed: " + (xlErr.message || "").slice(0, 200) });
    }
  }

  if (!Array.isArray(parsed) || !parsed.length) return res.status(400).json({ error: "No rows found" });

  parsed = parsed.filter(function(r) { return r.name && r.hours; }).map(function(r, i) {
    var actNorm = (r.activity || "").toLowerCase().trim();
    if (actNorm.indexOf("målstyr") >= 0) actNorm = "Målstyrte aktiviteter";
    else if (actNorm.indexOf("medlem") >= 0) actNorm = "Medlemsaktivitet";
    else actNorm = "Annet";
    var hours = parseFloat(r.hours) || 0;
    return {
      _idx: i, rawDate: r.rawDate || r.date || "",
      date: /^\d{4}-\d{2}-\d{2}/.test(r.date || "") ? r.date.slice(0, 10) : "",
      name: String(r.name).trim(), nameNormalized: "",
      activity: actNorm, description: String(r.description || "").trim(),
      hours: hours, minutes: Math.round(hours * 60),
    };
  });

  var nameMap = {};
  parsed.forEach(function(p) {
    var key = p.name.toLowerCase().replace(/\s+/g, " ").trim();
    if (!nameMap[key]) nameMap[key] = p.name;
  });
  parsed.forEach(function(p) {
    p.nameNormalized = nameMap[p.name.toLowerCase().replace(/\s+/g, " ").trim()];
  });

  var byName = {};
  parsed.forEach(function(p) {
    if (!byName[p.nameNormalized]) byName[p.nameNormalized] = [];
    byName[p.nameNormalized].push(p);
  });

  function normN(n) { return (n || "").toLowerCase().replace(/\s+/g, " ").trim(); }
  function nParts(n) { return normN(n).split(" ").filter(Boolean); }
  function nameScore(a, b) {
    var na = normN(a), nb = normN(b);
    if (na === nb) return 100;
    var ap = nParts(a), bp = nParts(b);
    if (ap.every(function(p) { return bp.indexOf(p) >= 0; })) return 90;
    if (bp.every(function(p) { return ap.indexOf(p) >= 0; })) return 85;
    if (ap.length && bp.length && ap[0] === bp[0]) {
      var aL = ap[ap.length - 1], bL = bp[bp.length - 1];
      if (aL.length >= 3 && bL.length >= 3 && aL.slice(0, 3) === bL.slice(0, 3)) return 75;
      return 60;
    }
    if (nb.indexOf(na) >= 0 || na.indexOf(nb) >= 0) return 50;
    return 0;
  }

  var vols = readJSON(VOLUNTEERS_FILE) || [];
  var excelNames = Object.keys(byName).sort(function(a, b) { return a.localeCompare(b, "nb"); });
  var pairings = excelNames.map(function(eName) {
    var candidates = [];
    vols.forEach(function(v) {
      var sc = nameScore(eName, v.name);
      if (sc >= 50) candidates.push({ id: v.id, name: v.name, email: v.email || "", score: sc });
    });
    candidates.sort(function(a, b) { return b.score - a.score; });
    var best = candidates[0] || null;
    return {
      excelName: eName,
      rowCount: byName[eName].length,
      totalHours: byName[eName].reduce(function(s, r) { return s + r.hours; }, 0),
      match: best && best.score >= 90 ? "exact" : best && best.score >= 50 ? "partial" : "none",
      bestMatch: best,
      candidates: candidates.slice(0, 5),
    };
  });

  var allVols = vols.map(function(v) { return { id: v.id, name: v.name, email: v.email || "" }; })
    .sort(function(a, b) { return (a.name || "").localeCompare(b.name || "", "nb"); });

  res.json({ totalParsed: parsed.length, pairings: pairings, parsedRows: parsed, allVolunteers: allVols });
});

// POST /api/volunteers/import/check — with confirmed pairings, return duplicate analysis
app.post("/api/volunteers/import/check", auth, managerOrAdmin, function(req, res) {
  var rows = req.body.rows;
  var pairMap = req.body.pairMap;
  if (!Array.isArray(rows) || !pairMap) return res.status(400).json({ error: "rows and pairMap required" });

  var vols = readJSON(VOLUNTEERS_FILE) || [];
  var events = readJSON(EVENTS_FILE) || [];

  var grouped = {};
  rows.forEach(function(r) {
    if (!r.name || !r.hours) return;
    var nk = r.nameNormalized || r.name;
    var pair = pairMap[nk];
    if (!pair) return;
    var gKey = pair.volunteerId || "new__" + nk;
    if (!grouped[gKey]) grouped[gKey] = { pair: pair, nameKey: nk, rows: [] };
    grouped[gKey].rows.push(r);
  });

  var results = [];
  Object.keys(grouped).sort().forEach(function(gKey) {
    var g = grouped[gKey];
    var vol = g.pair.volunteerId ? vols.find(function(v) { return v.id === g.pair.volunteerId; }) : null;

    var existingEntries = [];
    if (vol && vol.timeLogs) {
      Object.keys(vol.timeLogs).forEach(function(evId) {
        var ev = events.find(function(e) { return e.id === evId; });
        (vol.timeLogs[evId] || []).forEach(function(row) {
          existingEntries.push({
            eventTitle: ev ? ev.title : (evId === "_excel_import" ? "Excel-import" : "(slettet)"),
            date: row.date || (ev ? (ev.date || "").slice(0, 10) : ""),
            label: row.label || "", minutes: row.minutes || 0,
            hours: Math.round((row.minutes || 0) / 60 * 10) / 10,
          });
        });
      });
    }

    var excelRows = g.rows.map(function(r) { return Object.assign({}, r, { duplicateOf: null }); });
    var dbByDate = {};
    existingEntries.forEach(function(db) {
      if (!db.date) return;
      if (!dbByDate[db.date]) dbByDate[db.date] = [];
      dbByDate[db.date].push(Object.assign({ _matched: false }, db));
    });
    excelRows.forEach(function(er) {
      if (!er.date || !dbByDate[er.date]) return;
      var cands = dbByDate[er.date].filter(function(db) { return !db._matched; });
      var best = null, bestDiff = Infinity;
      cands.forEach(function(db) {
        var diff = Math.abs(db.minutes - er.minutes);
        if (diff <= 60 && diff < bestDiff) { best = db; bestDiff = diff; }
      });
      if (best) { best._matched = true; er.duplicateOf = { eventTitle: best.eventTitle, label: best.label, hours: best.hours }; }
    });

    results.push({
      excelName: g.nameKey, volunteerId: g.pair.volunteerId || null,
      volunteerName: g.pair.volunteerName || g.nameKey, action: g.pair.action,
      excelRows: excelRows, existingEntries: existingEntries,
      totalExcelHours: excelRows.reduce(function(s, r) { return s + r.hours; }, 0),
      totalExistingHours: existingEntries.reduce(function(s, r) { return s + r.hours; }, 0),
      newRows: excelRows.filter(function(r) { return !r.duplicateOf; }).length,
      dupeRows: excelRows.filter(function(r) { return !!r.duplicateOf; }).length,
    });
  });

  res.json({ volunteers: results });
});

// POST /api/volunteers/import/commit — import selected rows
app.post("/api/volunteers/import/commit", auth, managerOrAdmin, function(req, res) {
  var entries = req.body.entries;
  if (!Array.isArray(entries) || !entries.length) return res.status(400).json({ error: "No entries" });

  var vols = readJSON(VOLUNTEERS_FILE) || [];
  var batchId = "import_" + Date.now();
  var importEventId = "_excel_import";
  var created = 0, skipped = 0, newVols = 0;

  entries.forEach(function(e) {
    var minutes = parseInt(e.minutes, 10) || 0;
    if (!minutes) { skipped++; return; }
    var vi = -1;
    if (e.volunteerId) vi = vols.findIndex(function(v) { return v.id === e.volunteerId; });
    if (vi < 0 && e.createNew && e.name) {
      var settings = getSettings();
      var depts = settings.departments || [];
      var dd = depts.length ? depts[0].id : null;
      vols.push({ id: uuid(), name: e.name.trim(), email: "", phone: "",
        departments: dd ? [dd] : [], activeDepartment: dd, department: dd,
        events: [], timeLogs: {}, createdAt: new Date().toISOString() });
      vi = vols.length - 1; newVols++;
    }
    if (vi < 0) { skipped++; return; }
    vols[vi].timeLogs = vols[vi].timeLogs || {};
    vols[vi].timeLogs[importEventId] = vols[vi].timeLogs[importEventId] || [];
    var fp = (e.date || "") + "|" + minutes + "|" + (e.description || "").slice(0, 60);
    var isDupe = vols[vi].timeLogs[importEventId].some(function(r) {
      return (r.date || "") + "|" + (r.minutes || 0) + "|" + (r.label || "").slice(0, 60) === fp;
    });
    if (isDupe) { skipped++; return; }
    vols[vi].timeLogs[importEventId].push({
      id: uuid(), date: e.date || "", label: (e.description || "Importert").slice(0, 200),
      mode: "duration", minutes: minutes, addedBy: "import",
      addedAt: new Date().toISOString(), _batchId: batchId,
      _activity: e.activity || "", _rawDate: e.rawDate || "" });
    created++;
  });

  writeJSON(VOLUNTEERS_FILE, vols);
  res.json({ ok: true, created: created, skipped: skipped, newVolunteers: newVols, batchId: batchId });
});

// DELETE /api/volunteers/import/batch/:batchId — undo
app.delete("/api/volunteers/import/batch/:batchId", auth, managerOrAdmin, function(req, res) {
  var bid = req.params.batchId;
  var vols = readJSON(VOLUNTEERS_FILE) || [];
  var removed = 0;
  vols.forEach(function(v) {
    if (!v.timeLogs) return;
    Object.keys(v.timeLogs).forEach(function(evId) {
      var before = v.timeLogs[evId].length;
      v.timeLogs[evId] = v.timeLogs[evId].filter(function(r) { return r._batchId !== bid; });
      removed += before - v.timeLogs[evId].length;
    });
  });
  writeJSON(VOLUNTEERS_FILE, vols);
  res.json({ ok: true, removed: removed });
});

// POST /api/volunteers/bulk-email { emails[], subject, body } — send via system
app.post("/api/volunteers/bulk-email", auth, managerOrAdmin, async function(req, res) {
  const emails = Array.isArray(req.body.emails) ? req.body.emails.filter(function(e){ return e && /@/.test(e); }).slice(0, 500) : [];
  const subject = String(req.body.subject || "").slice(0, 200).trim();
  const bodyText = String(req.body.body || "").slice(0, 20000).trim();
  if (!emails.length) return res.status(400).json({ error: st("no_valid_recipients", req) });
  if (!subject || !bodyText) return res.status(400).json({ error: st("missing_subject_or_message", req) });
  const html = '<div style="font-family:sans-serif;font-size:15px;line-height:1.6;color:#111">'
             + bodyText.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/\n/g,"<br>")
             + '</div>';
  const _bulkDeptId = req.session.user.role === "admin" ? null :
    (getAccessList(readJSON(USERS_FILE).find(function(u){ return u.id === req.session.user.id; }) || {})[0] || {}).department || null;
  let sent = 0;
  for (const to of emails) {
    try { await sendEmail({ to: to, subject: subject, html: html, text: bodyText, department: _bulkDeptId, category: "volunteer" }); sent++; }
    catch(e) { /* continue; report count */ }
  }
  res.json({ ok: true, sent: sent, total: emails.length });
});

// POST /api/events/:id/staff/bulk-add { volunteerIds[] } — add selected as staff
app.post("/api/events/:id/staff/bulk-add", auth, managerOrAdmin, function(req, res) {
  const ids = Array.isArray(req.body.volunteerIds) ? req.body.volunteerIds : [];
  if (!ids.length) return res.status(400).json({ error: st("none_selected", req) });
  const events = readJSON(EVENTS_FILE) || [];
  const ev = events.find(function(e){ return e.id === req.params.id; });
  if (!ev) return res.status(404).json({ error: st("event_not_found", req) });
  const vols = readJSON(VOLUNTEERS_FILE) || [];
  ev.staff = ev.staff || [];
  let added = 0;
  ids.forEach(function(vid) {
    const v = vols.find(function(x){ return x.id === vid; });
    if (!v) return;
    const exists = ev.staff.some(function(s){ return s.volunteerId === vid || (v.email && s.email && s.email.toLowerCase() === v.email.toLowerCase()); });
    if (exists) return;
    ev.staff.push({ id: uuid(), name: v.name || "", role: "Frivillig", volunteerId: vid, email: v.email || "", addedAt: new Date().toISOString() });
    // also reflect on the volunteer's events list
    v.events = v.events || [];
    if (v.events.indexOf(ev.id) < 0) v.events.push(ev.id);
    // Auto-send evaluation if one exists
    if (v.email) _autoSendEvaluation(ev, v.email, v.name, v.id);
    added++;
  });
  writeJSON(EVENTS_FILE, events);
  writeJSON(VOLUNTEERS_FILE, vols);
  res.json({ ok: true, added: added });
});

// POST /api/volunteers/bulk-clothing-delivered { volunteerIds[], baseKey } — mark delivered
app.post("/api/volunteers/bulk-clothing-delivered", auth, managerOrAdmin, function(req, res) {
  const ids = Array.isArray(req.body.volunteerIds) ? req.body.volunteerIds : [];
  const baseKey = String(req.body.baseKey || "");
  if (!ids.length || !baseKey) return res.status(400).json({ error: st("missing_choice_or_garment", req) });
  const vols = readJSON(VOLUNTEERS_FILE) || [];
  let updated = 0;
  ids.forEach(function(vid) {
    const v = vols.find(function(x){ return x.id === vid; });
    if (!v || !v.clothing) return;
    Object.keys(v.clothing).forEach(function(k) {
      if (k.replace(/_\d+$/, "") === baseKey && v.clothing[k] && !v.clothing[k].received) {
        v.clothing[k].received = true;
        updated++;
      }
    });
  });
  writeJSON(VOLUNTEERS_FILE, vols);
  res.json({ ok: true, updated: updated });
});

// ── Manager-side time logs ──────────────────────────────────────
// GET /api/volunteers/:id/timelog — all time rows for a volunteer, grouped by event
app.get("/api/volunteers/:id/timelog", auth, managerOrAdmin, function(req, res) {
  const vols = readJSON(VOLUNTEERS_FILE) || [];
  const v = vols.find(function(x){ return x.id === req.params.id; });
  if (!v) return res.status(404).json({ error: "Not found" });
  const events = readJSON(EVENTS_FILE) || [];
  const tl = v.timeLogs || {};
  const groups = Object.keys(tl).map(function(eventId) {
    const ev = events.find(function(e){ return e.id === eventId; });
    const rows = tl[eventId] || [];
    return {
      eventId: eventId,
      title: ev ? ev.title : (eventId === "_other" ? "Annet (frivillig aktivitet)" : eventId === "_excel_import" ? "Excel-import" : "(slettet arrangement)"),
      date: ev ? ev.date : null,
      rows: rows,
      totalMin: rows.reduce(function(s, r){ return s + (parseInt(r.minutes,10)||0); }, 0)
    };
  }).sort(function(a,b){ return (b.date||"").localeCompare(a.date||""); });
  res.json({ groups: groups, yearMinutes: _volunteerYearMinutes(v, events, new Date().getFullYear()) });
});

// POST /api/volunteers/:id/timelog { eventId, row } — manager adds a row
app.post("/api/volunteers/:id/timelog", auth, managerOrAdmin, function(req, res) {
  const vols = readJSON(VOLUNTEERS_FILE) || [];
  const i = vols.findIndex(function(x){ return x.id === req.params.id; });
  if (i < 0) return res.status(404).json({ error: "Not found" });
  const eventId = String(req.body.eventId || "");
  if (!eventId) return res.status(400).json({ error: st("missing_event", req) });
  // Allow special pseudo-events for non-event activities
  var isSpecial = eventId === "_other" || eventId === "_excel_import";
  vols[i].timeLogs = vols[i].timeLogs || {};
  vols[i].timeLogs[eventId] = vols[i].timeLogs[eventId] || [];
  const row = _sanitizeTimeRow(req.body.row || {}, "manager");
  if (!row.minutes) return res.status(400).json({ error: st("duration_zero", req) });
  vols[i].timeLogs[eventId].push(row);
  // Auto-link: logging time implies involvement, so attach the event if not already linked
  vols[i].events = vols[i].events || [];
  if (vols[i].events.indexOf(eventId) === -1) vols[i].events.push(eventId);
  writeJSON(VOLUNTEERS_FILE, vols);
  res.json({ ok: true, row: row });
});

// DELETE /api/volunteers/:id/timelog/:eventId/:rowId — manager removes any row
app.delete("/api/volunteers/:id/timelog/:eventId/:rowId", auth, managerOrAdmin, function(req, res) {
  const vols = readJSON(VOLUNTEERS_FILE) || [];
  const i = vols.findIndex(function(x){ return x.id === req.params.id; });
  if (i < 0 || !vols[i].timeLogs || !vols[i].timeLogs[req.params.eventId]) return res.status(404).json({ error: st("not_found_generic", req) });
  vols[i].timeLogs[req.params.eventId] = vols[i].timeLogs[req.params.eventId].filter(function(r){ return r.id !== req.params.rowId; });
  writeJSON(VOLUNTEERS_FILE, vols);
  res.json({ ok: true });
});

// PUT /api/volunteers/:id/timelog/:eventId/:rowId/approve — manager approves a single time row
app.put("/api/volunteers/:id/timelog/:eventId/:rowId/approve", auth, managerOrAdmin, function(req, res) {
  var vols = readJSON(VOLUNTEERS_FILE) || [];
  var vi = vols.findIndex(function(x){ return x.id === req.params.id; });
  if (vi < 0) return res.status(404).json({ error: "Not found" });
  var rows = vols[vi].timeLogs && vols[vi].timeLogs[req.params.eventId];
  if (!rows) return res.status(404).json({ error: "No time entries" });
  var row = rows.find(function(r){ return r.id === req.params.rowId; });
  if (!row) return res.status(404).json({ error: "Row not found" });
  row.approved = true; row.approvedAt = new Date().toISOString(); row.approvedBy = req.session.user.email;
  writeJSON(VOLUNTEERS_FILE, vols);
  res.json({ ok: true });
});

// PUT /api/volunteers/:id/timelog/:eventId/approve — manager approves all volunteer time for an event
// This also auto-checks-in the volunteer on the event staff list.
app.put("/api/volunteers/:id/timelog/:eventId/approve", auth, managerOrAdmin, function(req, res) {
  var vols = readJSON(VOLUNTEERS_FILE) || [];
  var vi = vols.findIndex(function(x){ return x.id === req.params.id; });
  if (vi < 0) return res.status(404).json({ error: "Not found" });
  var rows = vols[vi].timeLogs && vols[vi].timeLogs[req.params.eventId];
  if (!rows || !rows.length) return res.status(404).json({ error: "No time entries" });
  // Mark all volunteer-added rows as approved
  rows.forEach(function(r){ if (r.addedBy === "volunteer") { r.approved = true; r.approvedAt = new Date().toISOString(); r.approvedBy = req.session.user.email; } });
  writeJSON(VOLUNTEERS_FILE, vols);
  // Auto check-in on the event
  var events = readJSON(EVENTS_FILE);
  var ev = events.find(function(e){ return e.id === req.params.eventId; });
  if (ev) {
    if (!ev.staff) ev.staff = [];
    var vol = vols[vi];
    var existing = ev.staff.find(function(s){ return s.volunteerId === vol.id || (vol.email && s.email && s.email.toLowerCase() === (vol.email||"").toLowerCase()); });
    if (existing && !existing.checkedIn) {
      existing.checkedIn = true;
      existing.checkedInAt = new Date().toISOString();
    } else if (!existing) {
      ev.staff.push({ id: require("crypto").randomUUID(), name: vol.name || "", email: vol.email || "", volunteerId: vol.id, checkedIn: true, checkedInAt: new Date().toISOString(), addedAt: new Date().toISOString() });
    }
    writeJSON(EVENTS_FILE, events);
  }
  res.json({ ok: true });
});

// PUT /api/volunteers/:id/timelog/:eventId/reject — manager rejects volunteer time for an event
app.put("/api/volunteers/:id/timelog/:eventId/reject", auth, managerOrAdmin, function(req, res) {
  var vols = readJSON(VOLUNTEERS_FILE) || [];
  var vi = vols.findIndex(function(x){ return x.id === req.params.id; });
  if (vi < 0) return res.status(404).json({ error: "Not found" });
  var rows = vols[vi].timeLogs && vols[vi].timeLogs[req.params.eventId];
  if (!rows) return res.status(404).json({ error: "No time entries" });
  // Remove unapproved volunteer rows
  vols[vi].timeLogs[req.params.eventId] = rows.filter(function(r){ return r.addedBy !== "volunteer" || r.approved; });
  writeJSON(VOLUNTEERS_FILE, vols);
  res.json({ ok: true });
});

// ── Manager: self-reported attendance review ────────────────────
// GET /api/self-reports — all pending (and recent) self-reports across volunteers
app.get("/api/self-reports", auth, managerOrAdmin, function(req, res) {
  const vols = readJSON(VOLUNTEERS_FILE) || [];
  const events = readJSON(EVENTS_FILE) || [];
  // deptName was referenced below but never defined in this scope, so this
  // endpoint threw a ReferenceError - a 500 - for any claim on an event that
  // had a department, which is nearly all of them.
  const _allDepts = getSettings().departments || [];
  const deptName = function(id) {
    const d = _allDepts.find(function(x){ return x.id === id; });
    return d ? (d.displayName || d.name || id) : id;
  };
  const myDepts = (req.user && req.user.departments) || null; // dept-scoping if present
  const out = [];
  vols.forEach(function(v){
    (v.selfReported || []).forEach(function(sr){
      const ev = sr.eventId ? events.find(function(e){ return e.id === sr.eventId; }) : null;
      // Department scoping: managers only see reports for events in their departments
      if (myDepts && myDepts.length && ev && ev.department && myDepts.indexOf(ev.department) < 0) return;
      out.push({
        volunteerId: v.id, volunteerName: v.name || "", volunteerEmail: v.email || "",
        // claimId is what approve/reject should post back; eventId stays for
        // older records and for anything that still keys on it.
        claimId: sr.id || sr.eventId,
        eventId: sr.eventId || null,
        eventTitle: ev ? ev.title : (sr.label || "(slettet arrangement)"),
        isFreeText: !sr.eventId,
        eventDate: ev ? ev.date : (sr.date || null),
        departmentName: ev && ev.department ? deptName(ev.department) : "",
        status: sr.status, reportedAt: sr.reportedAt
      });
    });
  });
  out.sort(function(a, b){
    // pending first, then by report date desc
    if (a.status === "pending" && b.status !== "pending") return -1;
    if (b.status === "pending" && a.status !== "pending") return 1;
    return (b.reportedAt || "").localeCompare(a.reportedAt || "");
  });
  res.json(out);
});

// PUT /api/volunteers/:id/self-report/:eventId { status } — confirm or decline
app.put("/api/volunteers/:id/self-report/:eventId", auth, managerOrAdmin, function(req, res) {
  const status = req.body.status;
  if (["confirmed", "declined", "pending"].indexOf(status) < 0) return res.status(400).json({ error: st("invalid_status", req) });
  const vols = readJSON(VOLUNTEERS_FILE) || [];
  const i = vols.findIndex(function(x){ return x.id === req.params.id; });
  if (i < 0 || !vols[i].selfReported) return res.status(404).json({ error: st("not_found_generic", req) });
  // Accepts either a claim id (free-text claims) or an eventId (legacy and
  // event-based claims), so older records keep working unchanged.
  const _key = req.params.eventId;
  const sr = vols[i].selfReported.find(function(s){ return s.id === _key || (s.eventId && s.eventId === _key); });
  if (!sr) return res.status(404).json({ error: st("self_report_not_found", req) });
  sr.status = status;
  sr.reviewedAt = new Date().toISOString();

  // On confirm, also add the volunteer as a checked-in staff entry so attendance
  // shows consistently everywhere (overview, stats, time-logging eligibility).
  if (status === "confirmed") {
    const events = readJSON(EVENTS_FILE) || [];
    // Key off the claim, not the path - the path may be a claim id. A
    // free-text claim has no event, so nothing is written to ev.staff.
    const ev = sr.eventId ? events.find(function(e){ return e.id === sr.eventId; }) : null;
    if (ev) {
      ev.staff = ev.staff || [];
      var existing = ev.staff.find(function(s){ return s.volunteerId === vols[i].id || (vols[i].email && s.email && s.email.toLowerCase() === vols[i].email.toLowerCase()); });
      if (existing) { existing.checkedIn = true; existing.checkedInAt = existing.checkedInAt || new Date().toISOString(); }
      else ev.staff.push({ id: uuid(), name: vols[i].name || "", role: "Frivillig (selvmeldt)", volunteerId: vols[i].id, email: vols[i].email || "", checkedIn: true, checkedInAt: new Date().toISOString() });
      // Auto-send evaluation if one exists
      if (vols[i].email) _autoSendEvaluation(ev, vols[i].email, vols[i].name, vols[i].id);
      writeJSON(EVENTS_FILE, events);
    }
  }
  writeJSON(VOLUNTEERS_FILE, vols);
  res.json({ ok: true });
});

// ── Dev-logg API (only DEVLOG_OWNER) ─────────────────────────────
function devlogAuth(req, res, next) {
  if (!req.session.user || req.session.user.email !== DEVLOG_OWNER)
    return res.status(403).json({ error: st("access_denied", req) });
  next();
}
function readDevlog() {
  try { return JSON.parse(fs.readFileSync(DEVLOG_F)); }
  catch(e) { return { entries: [] }; }
}

app.get("/api/devlog", auth, devlogAuth, function(req, res) {
  res.json(readDevlog());
});

app.post("/api/devlog", auth, devlogAuth, function(req, res) {
  const log = readDevlog();
  log.entries.unshift({ id: uuid(), createdAt: new Date().toISOString(), title: req.body.title || "", content: req.body.content || "", tags: Array.isArray(req.body.tags) ? req.body.tags : [] });
  fs.writeFileSync(DEVLOG_F, JSON.stringify(log, null, 2));
  res.json({ ok: true });
});

app.post("/api/devlog/entries", auth, devlogAuth, function(req, res) {
  const log = readDevlog();
  log.entries.unshift({ id: uuid(), createdAt: new Date().toISOString(), title: req.body.title || "", content: req.body.content || "", tags: Array.isArray(req.body.tags) ? req.body.tags : [] });
  fs.writeFileSync(DEVLOG_F, JSON.stringify(log, null, 2));
  res.json({ ok: true });
});

app.put("/api/devlog/entries/:id", auth, devlogAuth, function(req, res) {
  const log = readDevlog();
  const i = log.entries.findIndex(function(e) { return e.id === req.params.id; });
  if (i < 0) return res.status(404).json({ error: "Not found" });
  if (req.body.title   !== undefined) log.entries[i].title   = req.body.title;
  if (req.body.content !== undefined) log.entries[i].content = req.body.content;
  if (req.body.tags    !== undefined) log.entries[i].tags    = Array.isArray(req.body.tags) ? req.body.tags : [];
  log.entries[i].updatedAt = new Date().toISOString();
  fs.writeFileSync(DEVLOG_F, JSON.stringify(log, null, 2));
  res.json({ ok: true });
});

app.delete("/api/devlog/entries/:id", auth, devlogAuth, function(req, res) {
  const log = readDevlog();
  log.entries = log.entries.filter(function(e) { return e.id !== req.params.id; });
  fs.writeFileSync(DEVLOG_F, JSON.stringify(log, null, 2));
  res.json({ ok: true });
});
