      + (isActive ? '<span class="active-badge">Pågående nå</span>' : '')
      + (dateColLit && !isActive ? '<span class="today-badge">' + DT('today') + '</span>' : '')
      + (isPast ? '<span class="past-badge">' + DT('held') + '</span>' : '')
      + (ev.rescheduledToDate ? '<span style="font-size:.65rem;background:#f59e0b;color:#1a1a1a;padding:1px 7px;border-radius:6px;font-weight:800;margin-left:.3rem">FLYTTET</span>' : '') + '</div>'
      + '<div class="ev-title"' + cancelledTitleStyle(ev) + '>' + escHtml(ev.title || '') + cancelledBadge(ev) + '</div>'
