    + 'function switchMobTab(ki){CURRENT_KI=ki;var cols=document.querySelector(\'.cols\');if(cols)cols.style.display=\'\';var a=document.getElementById(\'colSectionAll\');if(a)a.style.display=\'none\';var hb=document.getElementById(\'histBtnAll\');if(hb)hb.style.display=\'none\';var gb=document.getElementById(\'histBtnGroup\');if(gb){var cb=document.getElementById(\'histBtn-\'+ki);if(cb){gb.style.display=\'inline-flex\';gb.textContent=cb.textContent;gb.dataset.ki=ki;}else{gb.style.display=\'none\';}}document.querySelectorAll(\'.col-section\').forEach(function(s){s.style.display=\'none\';s.classList.remove(\'mob-active\');});var tgt=document.getElementById(\'colSection\'+ki);if(tgt){tgt.style.display=\'block\';tgt.classList.add(\'mob-active\');}document.querySelectorAll(\'.mob-tab\').forEach(function(b){b.classList.toggle(\'active\',b.dataset&&b.dataset.ki===String(ki));});var w=document.getElementById(\'colWrap\'+ki);if(w){var ak=w.querySelector(\'.ev-card.active\');var tg=ak||w.querySelector(\'.ev-card\');if(tg&&!window._dpRestoring)window.scrollTo({top:Math.max(0,tg.getBoundingClientRect().top+window.scrollY-120),behavior:\'smooth\'});}if(!window._dpRestoring)_dpSaveState();}\n'    + '(function(){var _g=(location.hash.match(/^#g=([^&]+)/)||[])[1];window._dpRestoring=!!_g;if(window.innerWidth<700){if(_g&&_g!==\'all\'&&document.getElementById(\'colSection\'+_g)){switchMobTab(parseInt(_g,10));}else if(typeof switchMobTabAll==\'function\'&&document.getElementById(\'mobTabAll\')){switchMobTabAll();}else if(typeof switchMobTab==\'function\'){switchMobTab(0);}}else{document.querySelectorAll(\'.col-section\').forEach(function(s){s.style.display=\'block\';});var ab=document.getElementById(\'mobTabAll\');if(ab)ab.classList.remove(\'active\');var b0=document.querySelector(\'.mob-tab[data-ki]\');if(b0)b0.classList.add(\'active\');}})();\n'
    + 'window.addEventListener("load",function(){\n'
    + '  setTimeout(function(){\n'
