    +'<button id="ssFsBtn" onclick="ssFs()" style="background:none;border:1px solid #555;color:#fff;border-radius:5px;padding:6px 10px;font-size:.85rem;cursor:pointer;flex-shrink:0">&#x26F6;</button>'
    +'</div>'
