// Button + phone strip for the public department page. One loan item links
// straight to it; several open a small chooser. Labels are English in the
// markup and overlaid client-side (the department page is cached per dept).
function loanDeptPageClient() {
  var lang = (navigator.language || "en").toLowerCase().slice(0, 2);
  if (lang === "nb" || lang === "nn") lang = "no";
  var els = document.querySelectorAll("[data-loan-" + lang + "]");
  for (var i = 0; i < els.length; i++) els[i].textContent = els[i].getAttribute("data-loan-" + lang);
  var menu = document.getElementById("loanMenu");
  document.addEventListener("click", function(e) {
    var opener = e.target.closest ? e.target.closest("[data-loan-open]") : null;
    if (opener && menu) { e.preventDefault(); menu.style.display = "flex"; return; }
    if (menu && (e.target === menu || e.target.id === "loanMenuClose")) menu.style.display = "none";
  });
}
function buildDeptLoanSnippets(dept, c) {
  const items = loanItemsForDept(dept.id);
  if (!items.length) return { button: "", strip: "" };
  const single = items.length === 1;
  const href = single ? "/" + items[0].loanData.slug : "#";
  const openAttr = single ? "" : " data-loan-open=\"1\"";
  const label = '<span data-loan-no="Lån utstyr" data-loan-sv="Låna utrustning">Borrow equipment</span>';
  const button = '<a href="' + escHtml(href) + '"' + openAttr + ' style="flex:1;display:flex;align-items:center;justify-content:center;gap:.3rem;background:' + c.headerBg
    + ';border:1px solid ' + c.btnBorder + ';color:' + c.btnTxt + ';border-radius:8px;padding:0 .9rem;font-size:.82rem;cursor:pointer;white-space:nowrap;text-decoration:none;box-shadow:0 2px 6px rgba(0,0,0,.18)">🔑 ' + label + '</a>';
  let strip = '<style>.loan-strip{display:none}@media(max-width:640px){.loan-strip{display:flex}}</style>'
    + '<a class="loan-strip" href="' + escHtml(href) + '"' + openAttr + ' style="align-items:center;justify-content:center;gap:.4rem;padding:.5rem 1rem;font-size:.82rem;font-weight:700;text-decoration:none;color:'
    + c.btnTxt + ';background:' + c.headerBg + ';border-bottom:1px solid ' + c.btnBorder + '">🔑 ' + label + ' <span aria-hidden="true">\u203a</span></a>';
  if (!single) {
    strip += '<div id="loanMenu" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:998;align-items:center;justify-content:center;padding:1rem">'
      + '<div style="background:#fff;color:#111;border-radius:14px;padding:1rem;max-width:360px;width:100%;max-height:80vh;overflow:auto">'
      + '<div style="font-weight:800;margin-bottom:.6rem">🔑 ' + label + '</div>'
      + items.map(function(i) {
          const img = i.image ? (/^data:/.test(i.image) ? "/api/inventory/" + i.id + "/image" : i.image) : null;
          return '<a href="/' + escHtml(i.loanData.slug) + '" style="display:flex;align-items:center;gap:.7rem;padding:.55rem;border:1px solid #e5e7eb;border-radius:10px;margin-bottom:.4rem;text-decoration:none;color:#111;font-weight:700">'
            + (img ? '<img src="' + escHtml(img) + '" alt="" style="width:44px;height:44px;object-fit:cover;border-radius:7px"/>' : '<span style="font-size:1.6rem;width:44px;text-align:center">📦</span>')
            + '<span style="flex:1">' + escHtml(i.name) + '</span><span aria-hidden="true">\u203a</span></a>';
        }).join("")
      + '<button id="loanMenuClose" type="button" style="width:100%;margin-top:.3rem;background:#f3f4f6;border:none;border-radius:8px;padding:.6rem;cursor:pointer;font-weight:700" data-loan-no="Lukk" data-loan-sv="Stäng">Close</button>'
      + '</div></div>';
  }
  strip += '<script>(' + loanDeptPageClient.toString() + ')();<\/script>';
  return { button: button, strip: strip };
}

// Purchase – add quantity to stock
app.post("/api/inventory/:id/purchase", auth, managerOrAdmin, function(req, res) {
  const user  = req.session.user;
  const items = readJSON(INVENTORY_FILE);
  const idx   = items.findIndex(function(i){ return i.id === req.params.id; });
  if (idx === -1) return res.status(404).json({ err: "Not found" });
  if (user.role !== "admin" && items[idx].department) {
    const myDepts = getAccessList(readJSON(USERS_FILE).find(function(u){ return u.id === user.id; }) || {})
      .map(function(a){ return a.department; });
    if (!myDepts.includes(items[idx].department))
      return res.status(403).json({ err: "Access denied" });
  }
  const quantity = parseInt(req.body.quantity) || 0;
  if (antall <= 0) return res.status(400).json({ err: "Quantity must be greater than 0" });
  items[idx].quantity = (items[idx].quantity || 0) + antall;
  if (!items[idx].purchaseLog) items[idx].purchaseLog = [];
  items[idx].purchaseLog.push({ quantity, date: new Date().toISOString(), note: (req.body.note||"").trim() });
  writeJSON(INVENTORY_FILE, items);
  res.json({ ok: true, quantity: items[idx].quantity });
});

