// Varetelling – set nytt lagersaldo directly
app.post("/api/inventory/:id/stock-count", auth, managerOrAdmin, function(req, res) {
  const user  = req.session.user;
  const items = readJSON(INVENTORY_FILE);
  const idx   = items.findIndex(function(i){ return i.id === req.params.id; });
  if (idx === -1) return res.status(404).json({ err: "Not found" });
  if (user.role !== "admin" && items[idx].department) {
    const myDepts = getAccessList(readJSON(USERS_FILE).find(function(u){ return u.id === user.id; }) || {})
      .map(function(a){ return a.department; });
    if (!myDepts.includes(items[idx].department))
      return res.status(403).json({ err: "Access denied" });
  }
  const newCount = parseInt(req.body.quantity);
  if (isNaN(newCount) || newCount < 0) return res.status(400).json({ err: "Ugyldig antall" });
  const previousValue = items[idx].quantity || 0;
  items[idx].quantity = newCount;
  if (!items[idx].stockCountLog) items[idx].stockCountLog = [];
  items[idx].stockCountLog.push({ from: previousValue, to: newCount, date: new Date().toISOString(), note: (req.body.note||"").trim() });
  writeJSON(INVENTORY_FILE, items);
  res.json({ ok: true, quantity: newCount });
});

