// SSE stream for display screen
app.get("/api/events/:id/display/stream", function(req, res) {
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders();
  const clientId = displayNextId++;
  // Resolve slug → canonical UUID so displayState lookups always match
  const evForSse = readJSON(EVENTS_FILE).find(function(e) { return e.id === req.params.id || e.slug === req.params.id; });
  const evId = evForSse ? evForSse.id : req.params.id;
  displayClients.set(clientId, { res, evId });
  // send current state immediately — include winners from events file
  const state = displayState.get(evId) || { mode: "slides", slide: 0 };
  const winnersForSse = evForSse && evForSse.lottery && evForSse.lottery.winners
    ? evForSse.lottery.winners.map(function(w) { return { name: w.name, prize: w.prize || "", prizeImage: prizeImageRef(w), redeemedAt: w.redeemedAt || null }; })
    : [];
  res.write("data: " + JSON.stringify(Object.assign({ type: "state" }, _displayPublicState(state), { winners: winnersForSse })) + "\n\n");

  // Keepalive every 25s
  const keepAlive = setInterval(function() {
    try { res.write(": keepalive\n\n"); } catch(e) {}
  }, 25000);

  req.on("close", function() {
    displayClients.delete(clientId);
    clearInterval(keepAlive);
  });
});

// Get current display state
app.get("/api/events/:id/display/state", function(req, res) {
  const ev = readJSON(EVENTS_FILE).find(function(e) { return e.id === req.params.id || e.slug === req.params.id; });
  const evId = ev ? ev.id : req.params.id;
  const state = displayState.get(evId) || { mode: "slides", slide: 0, slides: [], ticker: "" };
  // Always inject current winners from events file (stays fresh after reload)
  const winners = ev && ev.lottery && ev.lottery.winners
    ? ev.lottery.winners.map(function(w) { return { name: w.name, prize: w.prize || "", prizeImage: prizeImageRef(w), redeemedAt: w.redeemedAt || null }; })
    : [];
  res.json(Object.assign({}, _displayPublicState(state), { winners }));
});

// Admin: update display state (mode, slide index, winner reveal, ticker)
app.post("/api/events/:id/display/state", auth, managerOrAdmin, function(req, res) {
  const _evRaw = readJSON(EVENTS_FILE).find(function(e){ return e.id === req.params.id || e.slug === req.params.id; });
  const evId = _evRaw ? _evRaw.id : req.params.id;
  const prev = displayState.get(evId) || { mode: "slides", slide: 0, slides: [], ticker: "" };
  const next = Object.assign({}, prev, {
    mode:            req.body.mode            !== undefined ? req.body.mode            : prev.mode,
    slide:           req.body.slide           !== undefined ? parseInt(req.body.slide) : prev.slide,
    winnerName:      req.body.winnerName      !== undefined ? req.body.winnerName      : prev.winnerName,
    prize:           req.body.prize           !== undefined ? req.body.prize           : prev.prize,
    ticker:          req.body.ticker          !== undefined ? String(req.body.ticker||"").slice(0,200) : prev.ticker,
    slideInterval:   req.body.slideInterval   !== undefined ? Math.max(3,  Math.min(300, parseInt(req.body.slideInterval)  || 10))  : (prev.slideInterval  || 10),
    winnerDuration:      req.body.winnerDuration      !== undefined ? Math.max(10, Math.min(3600,parseInt(req.body.winnerDuration)      || 300)) : (prev.winnerDuration      || 300),
    winnerCardInterval:  req.body.winnerCardInterval  !== undefined ? Math.max(0,  Math.min(50,  parseInt(req.body.winnerCardInterval)  || 5))   : (prev.winnerCardInterval  || 5),
  });
  displayState.set(evId, next);
  _saveDisplayState();
  broadcastDisplay(evId, Object.assign({ type: "state" }, next));
  res.json({ ok: true });
});

// ── Named presentations per event ───────────────────────────────
// An event can hold several named presentations. state.slides is always
// the ACTIVE presentation's slides (what /display/:id plays and what every
// slide endpoint edits); the others are parked in state.presentations[].slides.
// Old states without presentations[] are migrated on first use.
function _presDefaultName(ev, n, req) {
  return ((ev && ev.title) ? ev.title + " – " : "") + st("presentation_word", req) + (n > 1 ? " " + n : "");
}
function _presEnsure(evId, ev, req) {
  const prev = displayState.get(evId) || { mode: "slides", slide: 0, slides: [], ticker: "" };
  let list = Array.isArray(prev.presentations) ? prev.presentations : [];
  let activeId = prev.activePresId;
  if (!list.length) {
    const now = new Date().toISOString();
    list = [{ id: uuid(), name: _presDefaultName(ev, 1, req), createdAt: now, updatedAt: now }];
    activeId = list[0].id;
  }
  if (!list.some(function(p) { return p.id === activeId; })) activeId = list[0].id;
  const state = Object.assign({}, prev, { presentations: list, activePresId: activeId, slides: prev.slides || [] });
  displayState.set(evId, state);
  return state;
}
// Copy the live slides into the active record (before switching away)
function _presParkActive(state) {
  return state.presentations.map(function(p) {
    if (p.id !== state.activePresId) return p;
    return Object.assign({}, p, { slides: (state.slides || []).slice(), updatedAt: new Date().toISOString() });
  });
}
function _presSummary(state) {
  return {
    activePresId: state.activePresId,
    presentations: state.presentations.map(function(p) {
      const active = p.id === state.activePresId;
      const slides = active ? (state.slides || []) : (p.slides || []);
      const first = slides[0];
      return { id: p.id, name: p.name, active: active, count: slides.length,
               thumb: typeof first === "string" ? first : (first && (first.bg || first.url)) || null,
               createdAt: p.createdAt, updatedAt: p.updatedAt };
    }),
  };
}
function _presCommit(evId, state) {
  displayState.set(evId, state);
  _saveDisplayState();
  broadcastDisplay(evId, Object.assign({ type: "state" }, _displayPublicState(state)));
}
function _presEvent(req) {
  const ev = readJSON(EVENTS_FILE).find(function(e) { return e.id === req.params.id || e.slug === req.params.id; });
  return ev || null;
}
function _presName(v) { return sanitizeInput(String(v || "")).replace(/\s+/g, " ").trim().slice(0, 120); }

app.get("/api/events/:id/presentations", auth, managerOrAdmin, function(req, res) {
  const ev = _presEvent(req);
  if (!ev) return res.status(404).json({ error: "Event not found" });
  const state = _presEnsure(ev.id, ev, req);
  _saveDisplayState();
  res.json(_presSummary(state));
});

// Create a new (empty) presentation; it becomes the active one unless activate === false
app.post("/api/events/:id/presentations", auth, managerOrAdmin, function(req, res) {
  const ev = _presEvent(req);
  if (!ev) return res.status(404).json({ error: "Event not found" });
  let state = _presEnsure(ev.id, ev, req);
  if (state.presentations.length >= 50) return res.status(400).json({ error: "Too many presentations" });
  const now = new Date().toISOString();
  const pres = { id: uuid(), name: _presName(req.body.name) || _presDefaultName(ev, state.presentations.length + 1, req), createdAt: now, updatedAt: now, slides: [] };
  const list = _presParkActive(state).concat(pres);
  if (req.body.activate === false) {
    state = Object.assign({}, state, { presentations: list });
  } else {
    pres.slides = undefined;
    state = Object.assign({}, state, { presentations: list, activePresId: pres.id, slides: [], slide: 0 });
  }
  _presCommit(ev.id, state);
  res.json(Object.assign({ ok: true, id: pres.id }, _presSummary(state)));
});

// Rename
app.put("/api/events/:id/presentations/:pid", auth, managerOrAdmin, function(req, res) {
  const ev = _presEvent(req);
  if (!ev) return res.status(404).json({ error: "Event not found" });
  const state = _presEnsure(ev.id, ev, req);
  const name = _presName(req.body.name);
  if (!name) return res.status(400).json({ error: st("title_required", req) });
  if (!state.presentations.some(function(p) { return p.id === req.params.pid; })) return res.status(404).json({ error: "Presentation not found" });
  state.presentations = state.presentations.map(function(p) {
    return p.id === req.params.pid ? Object.assign({}, p, { name: name, updatedAt: new Date().toISOString() }) : p;
  });
  _presCommit(ev.id, state);
  res.json(Object.assign({ ok: true }, _presSummary(state)));
});

// Make a presentation the active one (shown on the display screen)
app.post("/api/events/:id/presentations/:pid/activate", auth, managerOrAdmin, function(req, res) {
  const ev = _presEvent(req);
  if (!ev) return res.status(404).json({ error: "Event not found" });
  let state = _presEnsure(ev.id, ev, req);
  const target = state.presentations.find(function(p) { return p.id === req.params.pid; });
  if (!target) return res.status(404).json({ error: "Presentation not found" });
  if (target.id !== state.activePresId) {
    const list = _presParkActive(state).map(function(p) {
      if (p.id !== target.id) return p;
      const copy = Object.assign({}, p); delete copy.slides; return copy;
    });
    state = Object.assign({}, state, { presentations: list, activePresId: target.id, slides: (target.slides || []).slice(), slide: 0 });
    _presCommit(ev.id, state);
  }
  res.json(Object.assign({ ok: true, slides: state.slides }, _presSummary(state)));
});

// Duplicate (copies the slide list; files are shared, so deleting is reference-aware)
app.post("/api/events/:id/presentations/:pid/duplicate", auth, managerOrAdmin, function(req, res) {
  const ev = _presEvent(req);
  if (!ev) return res.status(404).json({ error: "Event not found" });
  let state = _presEnsure(ev.id, ev, req);
  const src = state.presentations.find(function(p) { return p.id === req.params.pid; });
  if (!src) return res.status(404).json({ error: "Presentation not found" });
  const now = new Date().toISOString();
  const slides = (src.id === state.activePresId ? state.slides : src.slides) || [];
  const pres = { id: uuid(), name: _presName(req.body.name) || (src.name + " (" + st("copy_word", req) + ")").slice(0, 120), createdAt: now, updatedAt: now, slides: JSON.parse(JSON.stringify(slides)) };
  state = Object.assign({}, state, { presentations: _presParkActive(state).concat(pres) });
  _presCommit(ev.id, state);
  res.json(Object.assign({ ok: true, id: pres.id }, _presSummary(state)));
});

// Delete a presentation and the slide files no other presentation uses
app.delete("/api/events/:id/presentations/:pid", auth, managerOrAdmin, function(req, res) {
  const ev = _presEvent(req);
  if (!ev) return res.status(404).json({ error: "Event not found" });
  let state = _presEnsure(ev.id, ev, req);
  const target = state.presentations.find(function(p) { return p.id === req.params.pid; });
  if (!target) return res.status(404).json({ error: "Presentation not found" });
  const list = _presParkActive(state);
  const doomed = (list.find(function(p) { return p.id === target.id; }).slides) || [];
  const rest = list.filter(function(p) { return p.id !== target.id; });
  const keep = new Set();
  const urlOf = function(s) { return typeof s === "string" ? s : (s && (s.bg || s.url)) || ""; };
  rest.forEach(function(p) { (p.slides || []).forEach(function(s) { keep.add(urlOf(s)); }); });
  doomed.forEach(function(s) { if (!keep.has(urlOf(s))) _deleteSlideFiles(s); });
  if (!rest.length) {
    const now = new Date().toISOString();
    rest.push({ id: uuid(), name: _presDefaultName(ev, 1, req), createdAt: now, updatedAt: now, slides: [] });
  }
  let activeId = state.activePresId, slides = state.slides;
  if (target.id === state.activePresId) { activeId = rest[0].id; slides = (rest[0].slides || []).slice(); }
  const finalList = rest.map(function(p) {
    if (p.id !== activeId) return p;
    const copy = Object.assign({}, p); delete copy.slides; return copy;
  });
  state = Object.assign({}, state, { presentations: finalList, activePresId: activeId, slides: slides, slide: 0 });
  _presCommit(ev.id, state);
  res.json(Object.assign({ ok: true, slides: state.slides }, _presSummary(state)));
});

function _presActiveName(evId) {
  const st0 = displayState.get(evId);
  if (!st0 || !Array.isArray(st0.presentations)) return null;
  const p = st0.presentations.find(function(x) { return x.id === st0.activePresId; });
  return p ? p.name : null;
}

// Parked presentations are admin data: keep them out of public/SSE payloads
function _displayPublicState(state) {
  const out = Object.assign({}, state);
  delete out.presentations;
  delete out.slideDocs;
  return out;
}
// A slide file may be shared by a duplicated presentation
function _deleteSlideFilesIfUnused(state, slide) {
  const urlOf = function(x) { return typeof x === "string" ? x : (x && (x.bg || x.url)) || ""; };
  const u = urlOf(slide);
  const used = (state.presentations || []).some(function(p) {
    return p.id !== state.activePresId && (p.slides || []).some(function(x) { return urlOf(x) === u; });
  });
  if (!used) _deleteSlideFiles(slide);
}

// Upload slide image (PNG/JPG)
// Slide images keep their extension so they get the right type and long
// cache headers (multer's default name has none).
const _slideStorage = multer.diskStorage({
  destination: function(req, file, cb) { cb(null, UPLOADS); },
  filename: function(req, file, cb) {
    const ext = { "image/jpeg": ".jpg", "image/png": ".png", "image/gif": ".gif", "image/webp": ".webp" }[file.mimetype] || "";
    cb(null, crypto.randomBytes(16).toString("hex") + ext);
  },
});
app.post("/api/events/:id/display/slides", auth, managerOrAdmin,
  multer({ storage: _slideStorage, limits: { fileSize: 80 * 1024 * 1024 },
    fileFilter: function(req, file, cb) {
      cb(null, ["image/jpeg","image/png","image/gif","image/webp"].includes(file.mimetype));
    }
  }).single("slide"),
  function(req, res) {
    if (!req.file) return res.status(400).json({ error: st("no_file", req) });
    const _evSl = readJSON(EVENTS_FILE).find(function(e){ return e.id === req.params.id || e.slug === req.params.id; });
    const evId  = _evSl ? _evSl.id : req.params.id;
    const prev  = displayState.get(evId) || { mode: "slides", slide: 0, slides: [], ticker: "" };
    const newUrl = "/uploads/" + path.basename(req.file.filename);
    let slides = (prev.slides || []).slice();
    // Slide editor: «index» replaces that slide, «doc» keeps the editable layout
    const idx = req.body && req.body.index !== undefined && req.body.index !== "" ? parseInt(req.body.index, 10) : -1;
    const docs = Object.assign({}, prev.slideDocs || {});
    if (idx >= 0 && idx < slides.length) {
      const old = slides[idx];
      slides[idx] = newUrl;
      const oldUrl = typeof old === "string" ? old : (old && old.bg) || "";
      delete docs[oldUrl];
      if (!slides.some(function(x, k) { return k !== idx && x === old; })) _deleteSlideFilesIfUnused(Object.assign({}, prev, { slides: slides }), old);
    } else {
      slides.push(newUrl);
    }
    if (req.body && req.body.doc) {
      try { const d = JSON.parse(req.body.doc); if (d && typeof d === "object" && String(req.body.doc).length < 200000) docs[newUrl] = d; } catch (e) {}
    }
    const next  = Object.assign({}, prev, { slides, slideDocs: docs });
    displayState.set(evId, next);
    _saveDisplayState();
    broadcastDisplay(evId, Object.assign({ type: "state" }, next));
    res.json({ ok: true, slides, url: newUrl });
  }
);

// Editable layout of a slide made in the slide editor (null for plain images)
app.get("/api/events/:id/display/slide-doc", auth, managerOrAdmin, function(req, res) {
  const ev = _presEvent(req);
  const st0 = displayState.get(ev ? ev.id : req.params.id) || {};
  res.json({ doc: (st0.slideDocs || {})[String(req.query.url || "")] || null });
});

// Reorder: move one slide from → to
app.post("/api/events/:id/display/slides/move", auth, managerOrAdmin, function(req, res) {
  const ev = _presEvent(req);
  const evId = ev ? ev.id : req.params.id;
  const prev = displayState.get(evId) || { mode: "slides", slide: 0, slides: [], ticker: "" };
  const slides = (prev.slides || []).slice();
  const from = parseInt(req.body.from, 10), to = parseInt(req.body.to, 10);
  if (!(from >= 0 && from < slides.length && to >= 0 && to < slides.length)) return res.status(400).json({ error: "Bad index" });
  const item = slides.splice(from, 1)[0];
  slides.splice(to, 0, item);
  const next = Object.assign({}, prev, { slides: slides });
  displayState.set(evId, next);
  _saveDisplayState();
  broadcastDisplay(evId, Object.assign({ type: "state" }, next));
  res.json({ ok: true, slides: slides });
});

// Delete a slide
// Helper: delete files belonging to a slide entry
function _deleteSlideFiles(slide) {
  function tryDel(urlPath) {
    if (!urlPath) return;
    try {
      // URL is like /uploads/filename.png — resolve relative to DATA dir
      const basename = path.basename(urlPath);
      const fp = path.join(UPLOADS, basename);
      if (fs.existsSync(fp)) fs.unlinkSync(fp);
    } catch(e) {}
  }
  if (typeof slide === "string") {
    tryDel(slide);
  } else if (slide && slide.type === "video-slide") {
    tryDel(slide.bg);
    (slide.videos || []).forEach(function(v) { tryDel(v.url); });
  }
}

app.delete("/api/events/:id/display/slides/:idx", auth, managerOrAdmin, function(req, res) {
  const _evR = readJSON(EVENTS_FILE).find(function(e){ return e.id === req.params.id || e.slug === req.params.id; });
  const evId = _evR ? _evR.id : req.params.id;
  const idx  = parseInt(req.params.idx);
  const prev = displayState.get(evId) || { mode: "slides", slide: 0, slides: [], ticker: "" };
  const removed = (prev.slides || [])[idx];
  if (removed !== undefined) _deleteSlideFilesIfUnused(prev, removed);
  const slides = (prev.slides || []).filter(function(_, i) { return i !== idx; });
  const next = Object.assign({}, prev, { slides, slide: Math.min(prev.slide || 0, Math.max(0, slides.length - 1)) });
  displayState.set(evId, next);
  _saveDisplayState();
  broadcastDisplay(evId, Object.assign({ type: "state" }, next));
  res.json({ ok: true, slides });
});

