// Upload and convert PPTX to PNG slides (with video extraction)
app.post("/api/events/:id/display/pptx", auth, managerOrAdmin,
  multer({ dest: UPLOADS, limits: { fileSize: 10 * 1024 * 1024 * 1024 },
    fileFilter: function(req, file, cb) {
      const ok = [
        "application/vnd.openxmlformats-officedocument.presentationml.presentation",
        "application/vnd.ms-powerpoint",
        "application/octet-stream",
      ].includes(file.mimetype) || file.originalname.match(/\.pptx?$/i);
      cb(null, !!ok);
    }
  }).single("pptx"),
  async function(req, res) {
    if (!req.file) return res.status(400).json({ error: st("no_file_upload_pptx", req) });
    const { execFile, execSync } = require("child_process");
    const os  = require("os");
    const evId     = req.params.id;
    const pptxPath = req.file.path;
    const workDir  = path.join(os.tmpdir(), "pptx_" + evId + "_" + require("crypto").randomBytes(8).toString("hex"));
    fs.mkdirSync(workDir, { recursive: true });

    function cleanup() {
      try { fs.rmSync(workDir, { recursive: true, force: true }); } catch(e) {}
      try { fs.unlinkSync(pptxPath); } catch(e) {}
    }

    // ── Step 1: Parse PPTX with python-pptx to find video positions ─
    const videoMap = {}; // slideIndex (0-based) → [{ file, left, top, width, height }]
    const extractedVideos = {}; // mediaName → uploadPath
    try {
      const pyScript = `
import sys, json, zipfile
from pptx import Presentation

pptx_path = sys.argv[1]
prs = Presentation(pptx_path)
sw, sh = prs.slide_width, prs.slide_height
result = { "slides": [], "media": [] }

for si, slide in enumerate(prs.slides):
    vids = []
    for shape in slide.shapes:
        if shape.shape_type == 16:
            for rel in slide.part.rels.values():
                rt = rel.reltype.lower()
                if 'video' in rt or ('media' in rt and 'microsoft' not in rt):
                    vids.append({
                        "file": rel.target_ref.split("/")[-1],
                        "left": round(shape.left/sw*100,3),
                        "top":  round(shape.top/sh*100,3),
                        "width": round(shape.width/sw*100,3),
                        "height": round(shape.height/sh*100,3)
                    })
                    break
    result["slides"].append({"index":si,"videos":vids})

# List all media files
with zipfile.ZipFile(pptx_path,"r") as z:
    for f in z.namelist():
        if f.startswith("ppt/media/") and any(f.lower().endswith(e) for e in [".mp4",".m4v",".mov",".avi",".wmv"]):
            result["media"].append(f)

print(json.dumps(result))
`;
      const pyOut = execSync("python3 -c '" + pyScript.replace(/'/g, "'\''") + "' " + JSON.stringify(pptxPath),
        { timeout: 60000, maxBuffer: 1024*1024 }).toString().trim();
      const pyData = JSON.parse(pyOut);

      // Extract videos from PPTX zip
      const admzip = (() => {
        try { return require("adm-zip"); } catch(e) { return null; }
      })();

      if (admzip && pyData.media.length > 0) {
        const zip = new admzip(pptxPath);
        pyData.media.forEach(function(mediaPath) {
          const mediaName = mediaPath.split("/").pop();
          const entry = zip.getEntry(mediaPath);
          if (entry) {
            const ts   = Date.now();
            const ext  = path.extname(mediaName);
            const dest = path.join(UPLOADS, "video_" + evId + "_" + ts + "_" + mediaName);
            zip.extractEntryTo(entry, UPLOADS, false, true, false, path.basename(dest));
            // rename if needed
            const extracted = path.join(UPLOADS, mediaName);
            if (fs.existsSync(extracted)) fs.renameSync(extracted, dest);
            extractedVideos[mediaName] = "/uploads/" + path.basename(dest);
          }
        });
      } else if (pyData.media.length > 0) {
        // Fallback: use unzip command
        pyData.media.forEach(function(mediaPath) {
          const mediaName = mediaPath.split("/").pop();
          const ts   = Date.now();
          const dest = path.join(UPLOADS, "video_" + evId + "_" + ts + "_" + mediaName);
          try {
            execSync("unzip -p " + JSON.stringify(pptxPath) + " " + JSON.stringify(mediaPath) + " > " + JSON.stringify(dest), { shell:true, timeout:120000 });
            if (fs.existsSync(dest) && fs.statSync(dest).size > 0) extractedVideos[mediaName] = "/uploads/" + path.basename(dest);
          } catch(e) { console.error("[pptx] Video extract failed:", e.message); }
        });
      }

      // Build videoMap
      pyData.slides.forEach(function(s) {
        if (s.videos.length > 0) videoMap[s.index] = s.videos;
      });

      console.log("[pptx] Video slides:", Object.keys(videoMap).length, "Videos extracted:", Object.keys(extractedVideos).length);
    } catch(e) {
      console.warn("[pptx] python-pptx parse skipped:", e.message);
    }

    // ── Step 2: PPTX → PDF via LibreOffice ─────────────────────────
    // Find soffice binary directly (avoids oosplash wrapper hanging)
    const loCmd = (function() {
      const candidates = [
        "/usr/lib/libreoffice/program/soffice",
        "/usr/bin/soffice",
        "/usr/bin/libreoffice",
        "/opt/libreoffice/program/soffice"
      ];
      for (var i = 0; i < candidates.length; i++) {
        if (fs.existsSync(candidates[i])) return candidates[i];
      }
      try { return execSync("which soffice 2>/dev/null || which libreoffice 2>/dev/null").toString().trim(); } catch(e) { return null; }
    })();
    if (!loCmd) { cleanup(); return res.status(500).json({ error: st("libreoffice_missing_restart", req) }); }

    // Use spawn so we can detect when conversion is done via PDF appearing on disk
    // rather than relying on oosplash exit code
    const { spawn } = require("child_process");
    const loProc = spawn(loCmd, ["--headless","--convert-to","pdf","--outdir", workDir, pptxPath], {
      timeout: 600000,
      env: Object.assign({}, process.env, { HOME: workDir }) // isolate LO user profile
    });

    let loFinished = false;
    const loTimeout = setTimeout(function() {
      if (!loFinished) { try { loProc.kill(); } catch(e) {} }
    }, 590000);

    // Poll for PDF — wait until file size is stable (LibreOffice still writing otherwise)
    let pollCount = 0;
    let lastPdfSize = -1;
    let stableCount = 0;
    const pollInterval = setInterval(function() {
      pollCount++;
      try {
        const pdfs = fs.readdirSync(workDir).filter(function(f) { return f.endsWith(".pdf"); });
        if (pdfs.length > 0) {
          const pdfStat = fs.statSync(path.join(workDir, pdfs[0]));
          const size = pdfStat.size;
          if (size > 0 && size === lastPdfSize) {
            stableCount++;
            if (stableCount >= 3) { // same size 3 polls in a row = fully written
              clearInterval(pollInterval);
              clearTimeout(loTimeout);
              loFinished = true;
              try { loProc.kill(); } catch(e) {}
              proceedWithPdf(pdfs[0]);
            }
          } else {
            lastPdfSize = size;
            stableCount = 0;
          }
        }
      } catch(e) {}
      if (pollCount > 600) {
        clearInterval(pollInterval);
        cleanup();
        res.status(500).json({ error: "LibreOffice timeout – file may be too large for this server" });
      }
    }, 1000);

    loProc.on("error", function(err) {
      if (!loFinished) {
        clearInterval(pollInterval);
        clearTimeout(loTimeout);
        cleanup();
        res.status(500).json({ error: st("libreoffice_error_prefix", req) + err.message });
      }
    });

    function proceedWithPdf(pdfFile) {
      const pdfFiles = [pdfFile];
      if (!pdfFiles.length) { cleanup(); return res.status(500).json({ error: st("no_pdf_generated", req) }); }

      // ── Step 3: PDF → PNG via pdftoppm ─────────────────────────
      const slidePrefix = path.join(workDir, "slide");
      execFile("pdftoppm", ["-r","96","-png", pdfFiles[0].replace(workDir+"/",""), slidePrefix],
        { timeout: 600000, cwd: workDir }, function(err2) {
        if (err2) { cleanup(); return res.status(500).json({ error: st("pdftoppm_failed_prefix", req) + (err2.message||"ukjent") }); }

        const pngFiles = fs.readdirSync(workDir)
          .filter(function(f) { return f.match(/slide-\d+\.png$/); }).sort();
        if (!pngFiles.length) { cleanup(); return res.status(500).json({ error: st("no_slides_generated", req) }); }

        // ── Step 4: Build slide list — PNG or video overlay ─────────
        const ts = Date.now() + "_" + require("crypto").randomBytes(4).toString("hex");
        const slides = [];
        pngFiles.forEach(function(f, fi) {
          const src  = path.join(workDir, f);
          const dest = path.join(UPLOADS, "slide_" + evId + "_" + ts + "_" + String(fi).padStart(4,"0") + ".png");
          fs.copyFileSync(src, dest);
          const pngUrl = "/uploads/" + path.basename(dest);

          // Check if this slide has a video
          const slideVideos = videoMap[fi] || [];
          if (slideVideos.length > 0) {
            // Build a slide object with video overlay info
            const videoOverlays = slideVideos.map(function(v) {
              return Object.assign({}, v, { url: extractedVideos[v.file] || null });
            }).filter(function(v) { return v.url; });

            if (videoOverlays.length > 0) {
              // Store as JSON descriptor instead of plain URL
              slides.push({ type:"video-slide", bg: pngUrl, videos: videoOverlays });
              return;
            }
          }
          slides.push(pngUrl);
        });

        cleanup();

        // Update display state
        const prev = displayState.get(evId) || { mode:"slides", slide:0, slides:[], ticker:"" };
        const newSlides = (prev.slides || []).concat(slides);
        const next = Object.assign({}, prev, { slides: newSlides, slide:0 });
        displayState.set(evId, next);
        _saveDisplayState();
        broadcastDisplay(evId, Object.assign({ type:"state" }, next));

        const videoCount = slides.filter(function(s){ return s && s.type === "video-slide"; }).length;
        res.json({ ok:true, slides: newSlides, count: pngFiles.length, videoSlides: videoCount });
      });
    }
  }
);

// Gathers every displayable slide for one event: display-state uploads,
// main/TV images, and approved guestbook photos/videos (incl. multi-camera
// stream recordings). Shared by the cross-event slide browser and the
// year-in-review playlist generator, so both stay in sync automatically.
function buildEventSlides(ev) {
  var slides = [];
  var evTitle = ev.title || "";

  // Helper: enrich a slide with event metadata
  function tagSlide(s, uploaderName) {
    if (typeof s === "string") {
      return { type: "image", url: s, eventTitle: evTitle, uploaderName: uploaderName || "" };
    }
    if (s && typeof s === "object") {
      s.eventTitle = evTitle;
      if (uploaderName) s.uploaderName = uploaderName;
    }
    return s;
  }

  // 1. Display-state slides (lottery screen uploads)
  var state = displayState.get(ev.id);
  if (state && state.slides) {
    state.slides.forEach(function(s) {
      if (typeof s === "string" && !slides.some(function(x){ return (typeof x === "string" ? x : x.url) === s; })) slides.push(tagSlide(s));
    });
  }

  // 2. Main event image
  var _slideHasUrl = function(u){ return slides.some(function(s){ return s === u || (s && typeof s === "object" && s.url === u); }); };
  if (ev.image && !_slideHasUrl(ev.image)) slides.push(tagSlide(ev.image));

  // 3. TV top/bottom images
  if (ev.tvImageTop    && !_slideHasUrl(ev.tvImageTop))    slides.push(tagSlide(ev.tvImageTop));
  if (ev.tvImageBottom && !_slideHasUrl(ev.tvImageBottom)) slides.push(tagSlide(ev.tvImageBottom));

  // 4. Approved guestbook photos & videos
  var _isVideoUrl = function(u){ return /\.(mp4|webm|mov|m4v)$/i.test(u || ""); };
  (ev.guestbook || []).forEach(function(g) {
    if (!g.approved) return;
    var uploaderName = g.name || "";

    if (g.isStreamRecording && Array.isArray(g.angles) && g.angles.length) {
      g.angles.forEach(function(a) {
        if (!a.url || _slideHasUrl(a.url)) return;
        slides.push({
          type: "mp4-slide",
          url: a.url,
          name: a.camName || a.camKey || "Kamera",
          label: a.camName || a.camKey || "",
          duration: a.previewSeconds || 20,
          loop: true,
          eventTitle: evTitle,
          uploaderName: uploaderName,
        });
      });
      return;
    }

    (g.photos || []).forEach(function(p) {
      if (!p || _slideHasUrl(p)) return;
      if (_isVideoUrl(p)) {
        slides.push({ type: "mp4-slide", url: p, name: uploaderName || "Video", duration: 20, loop: true, eventTitle: evTitle, uploaderName: uploaderName });
      } else {
        slides.push(tagSlide(p, uploaderName));
      }
    });
  });

  return slides;
}

// Public display page — no auth required so it can run on a TV/tablet
// ── Event slides for TV (cross-event slide browser) ─────────────
// Returns all events in a dept that have slides uploaded, with slide URLs
// ── Fellesinnhold ("General Content") — browse every department's content
// that's been explicitly tagged for cross-department reuse. Unlike
// event-slides (one department only), this deliberately looks across all
// departments — that's the entire point of tagging something as general.
app.get("/api/tv/general-content", auth, managerOrAdmin, function(req, res) {
  const settings = getSettings();
  const depts = settings.departments || [];
  const deptName = function(id) { const d = depts.find(function(x){ return x.id === id; }); return d ? d.name : "Ukjent " + deptWord(); };

  const events = readJSON(EVENTS_FILE);
  const result = [];

  events.forEach(function(ev) {
    (ev.guestbook || []).forEach(function(g) {
      if (!g.approved || !g.isGeneral) return;

      var slides = [];
      var _isVideoUrl = function(u){ return /\.(mp4|webm|mov|m4v)$/i.test(u || ""); };
      if (g.isStreamRecording && Array.isArray(g.angles) && g.angles.length) {
        g.angles.forEach(function(a) {
          if (!a.url) return;
          slides.push({ type: "mp4-slide", url: a.url, name: a.camName || a.camKey || "Kamera", duration: a.previewSeconds || 20, loop: true });
        });
      } else {
        (g.photos || []).forEach(function(p) {
          if (!p) return;
          slides.push(_isVideoUrl(p) ? { type: "mp4-slide", url: p, name: g.name || "Video", duration: 20, loop: true } : p);
        });
      }
      if (!slides.length) return;

      result.push({
        evId:          ev.id,
        guestbookId:   g.id,
        eventTitle:    ev.title || "Uten tittel",
        date:          ev.date ? ev.date.slice(0, 10) : null,
        departmentId:  ev.department,
        departmentName: deptName(ev.department),
        contributedBy: g.name || "",
        slides:        slides,
      });
    });
  });

  result.sort(function(a, b) { return (b.date || "").localeCompare(a.date || ""); });
  res.json(result);
});


app.get("/api/tv/:deptId/event-slides", auth, managerOrAdmin, deptGuard, function(req, res) {
  var deptId = req.params.deptId;
  var events = readJSON(EVENTS_FILE);
  var result = [];

  events.forEach(function(ev) {
    if (ev.department !== deptId) return;
    var slides = buildEventSlides(ev);

    if (!slides.length) return;
    result.push({
      evId:      ev.id,
      title:     ev.title || "Uten tittel",
      date:      ev.date ? ev.date.slice(0, 10) : null,
      eventType: ev.eventType || "stand",
      slides:    slides,
    });
  });

  // Sort by date descending (most recent first)
  result.sort(function(a, b) {
    if (!a.date) return 1;
    if (!b.date) return -1;
    return b.date.localeCompare(a.date);
  });
  res.json(result);
});

// ── Orphaned media: files on disk not referenced by any guestbook/event ──
app.get("/api/tv/:deptId/orphaned-media", auth, managerOrAdmin, deptGuard, function(req, res) {
  var mediaExts = /\.(jpg|jpeg|png|gif|webp|mp4|webm|mov|m4v)$/i;
  var _isVideo  = function(f) { return /\.(mp4|webm|mov|m4v)$/i.test(f); };

  // 1. Collect all files on disk
  var diskFiles = [];
  [UPLOADS, path.join(DATA, "gb-photos")].forEach(function(dir) {
    if (!fs.existsSync(dir)) return;
    try {
      fs.readdirSync(dir).forEach(function(name) {
        if (name.startsWith(".") || name.startsWith("_")) return;
        if (!mediaExts.test(name)) return;
        var stat;
        try { stat = fs.statSync(path.join(dir, name)); } catch(e) { return; }
        if (!stat.isFile()) return;
        var urlPath = dir === UPLOADS
          ? "/uploads/" + name
          : "/gb-photos/" + name;
        diskFiles.push({ url: urlPath, name: name, size: stat.size, mtime: stat.mtime.toISOString() });
      });
    } catch(e) {}
  });

  // 2. Build a set of every URL referenced by events
  var referenced = new Set();
  var events = readJSON(EVENTS_FILE) || [];
  events.forEach(function(ev) {
    function addRef(u) {
      if (!u) return;
      if (typeof u === "string") referenced.add(u);
      else if (u && u.url) referenced.add(u.url);
    }
    // Main + TV images
    addRef(ev.image);
    addRef(ev.tvImageTop);
    addRef(ev.tvImageBottom);
    addRef(ev.routeMapImage);
    // Day map images
    if (Array.isArray(ev.dayMapImages)) ev.dayMapImages.forEach(addRef);
    // Guestbook photos
    (ev.guestbook || []).forEach(function(g) {
      (g.photos || []).forEach(addRef);
      if (g.isStreamRecording && Array.isArray(g.angles)) {
        g.angles.forEach(function(a) { addRef(a.url); });
      }
    });
    // TV side photos
    if (Array.isArray(ev.tvSidePhotos)) ev.tvSidePhotos.forEach(addRef);
  });

  // Also exclude files in the active display state (uploaded slides)
  displayState.forEach(function(state) {
    (state.slides || []).forEach(function(s) {
      if (typeof s === "string") referenced.add(s);
      else if (s && s.url) referenced.add(s.url);
      else if (s && s.bg) referenced.add(s.bg);
    });
  });

  // Also exclude the logo
  var settings = getSettings();
  if (settings.logoUrl) referenced.add(settings.logoUrl);

  // 3. Filter to orphans only
  var orphans = diskFiles.filter(function(f) { return !referenced.has(f.url); });

  // Sort by mtime descending (newest first)
  orphans.sort(function(a, b) { return b.mtime.localeCompare(a.mtime); });

  // Build slide-compatible output
  var slides = orphans.map(function(f) {
    if (_isVideo(f.url)) {
      return { type: "mp4-slide", url: f.url, name: f.name, duration: 20, loop: true };
    }
    return f.url;
  });

  res.json({
    count: orphans.length,
    totalBytes: orphans.reduce(function(s, f) { return s + f.size; }, 0),
    slides: slides,
    files: orphans
  });
});

// ── TV URL screenshot ────────────────────────────────────────────
app.post("/api/tv/:deptId/screenshot", auth, managerOrAdmin, deptGuard, function(req, res) {
  var url = (req.body.url || "").trim();
  if (!url || !url.startsWith("http")) return res.status(400).json({ error: st("invalid_url", req) });

  // SSRF protection
  var urlObj;
  try { urlObj = new (require("url").URL)(url); } catch(e) { return res.status(400).json({ error: st("invalid_url", req) }); }
  var hostname = urlObj.hostname.toLowerCase();
  var blocked = ["localhost","127.","0.","10.","192.168.","172.16.","172.17.","172.18.","172.19.",
    "172.20.","172.21.","172.22.","172.23.","172.24.","172.25.","172.26.","172.27.","172.28.",
    "172.29.","172.30.","172.31.","169.254.","::1","fc00:","fe80:"];
  if (blocked.some(function(b){ return hostname === b.replace(".","") || hostname.startsWith(b); })) {
    return res.status(400).json({ error: st("url_not_allowed", req) });
  }
  if (!["http:","https:"].includes(urlObj.protocol)) return res.status(400).json({ error: st("invalid_protocol", req) });

  var crypto = require("crypto");
  var hash   = crypto.createHash("md5").update(url).digest("hex").slice(0, 10);
  var dest   = path.join(UPLOADS, "screenshot_" + hash + ".jpg");

  // Serve cached version if <24h old
  if (fs.existsSync(dest)) {
    var age = Date.now() - fs.statSync(dest).mtimeMs;
    if (age < 24 * 3600 * 1000) {
      return res.json({ ok: true, screenshotUrl: "/uploads/" + path.basename(dest), cached: true });
    }
  }

  // Helper: save buffer to file and respond
  function saveAndRespond(buf) {
    try {
      fs.writeFileSync(dest, buf);
      if (fs.statSync(dest).size > 3000) {
        return res.json({ ok: true, screenshotUrl: "/uploads/" + path.basename(dest) });
      }
    } catch(e) {}
    res.status(500).json({ error: st("screenshot_save_failed", req) });
  }

  // Helper: fetch screenshot from external API
  function fetchExternal(apiUrl, cb) {
    var protocol = apiUrl.startsWith("https") ? require("https") : require("http");
    var opts = require("url").parse(apiUrl);
    opts.timeout = 20000;
    opts.headers = { "User-Agent": "Event-Admin/1.0" };
    var reqH = protocol.get(opts, function(r) {
      if (r.statusCode >= 300 && r.statusCode < 400 && r.headers.location) {
        return fetchExternal(r.headers.location, cb);
      }
      if (r.statusCode !== 200) return cb(new Error("HTTP " + r.statusCode));
      var chunks = [];
      r.on("data", function(d) { chunks.push(d); });
      r.on("end", function() { cb(null, Buffer.concat(chunks)); });
    });
    reqH.on("error", cb);
    reqH.on("timeout", function() { reqH.destroy(); cb(new Error("Timeout")); });
  }

  // Strategy 1: wkhtmltoimage (if installed on server)
  var { execFile, execFileSync } = require("child_process");
  var hasWkhtml = false;
  try { execFileSync("which", ["wkhtmltoimage"], { stdio: "ignore" }); hasWkhtml = true; } catch(e) {}

  if (hasWkhtml) {
    execFile("wkhtmltoimage", [
      "--width", "1280", "--height", "720", "--quality", "82",
      "--javascript-delay", "12000", "--no-stop-slow-scripts",
      "--load-error-handling", "ignore", "--load-media-error-handling", "ignore",
      url, dest
    ], { timeout: 30000 }, function(err) {
      if (fs.existsSync(dest) && fs.statSync(dest).size > 5000) {
        return res.json({ ok: true, screenshotUrl: "/uploads/" + path.basename(dest) });
      }
      // wkhtmltoimage failed — fall through to external API
      tryExternalApi();
    });
  } else {
    tryExternalApi();
  }

  function tryExternalApi() {
    // thum.io — free, no API key, returns JPG screenshot
    var thumUrl = "https://image.thum.io/get/width/1280/crop/720/jpg/" + encodeURIComponent(url);
    fetchExternal(thumUrl, function(err, buf) {
      if (!err && buf && buf.length > 5000) {
        return saveAndRespond(buf);
      }
      // Fallback: api.microlink.io screenshot
      var mlUrl = "https://api.microlink.io/?url=" + encodeURIComponent(url) + "&screenshot=true&meta=false&embed=screenshot.url";
      fetchExternal(mlUrl, function(err2, buf2) {
        if (!err2 && buf2 && buf2.length > 5000) {
          return saveAndRespond(buf2);
        }
        res.status(500).json({ error: st("screenshot_failed_install", req) });
      });
    });
  }
});

// ── TV Spilleliste-API ───────────────────────────────────────────

// List all playlists (optionally filtered by deptId). Includes every
// department's General Content playlists in addition to the caller's own.
app.get("/api/tv-playlists", auth, managerOrAdmin, function(req, res) {
  var list = readPlaylists();
  var u = req.session.user;
  if (u.role !== "admin") {
    var acc = getAccessList(readJSON(USERS_FILE).find(function(x){ return x.id === u.id; }) || {});
    var myDeptIds = acc.map(function(a){ return a.department; });
    list = list.filter(function(p) { return !p.deptId || myDeptIds.indexOf(p.deptId) !== -1 || p.isGeneral; });
  }
  if (req.query.dept) {
    if (!hasDeptAccess(u, req.query.dept)) return res.status(403).json({ error: st("no_access_department", req) });
    list = list.filter(function(p) { return !p.deptId || p.deptId === req.query.dept || p.isGeneral; });
  }
  res.json(list);
});

// Create playlist
app.post("/api/tv-playlists", auth, managerOrAdmin, function(req, res) {
  var deptId = req.body.deptId || null;
  if (deptId && !hasDeptAccess(req.session.user, deptId)) {
    return res.status(403).json({ error: st("no_access_department", req) });
  }
  var list = readPlaylists();
  var _validScreens = ["center","left","right","all"];
  var pl = {
    id:       uuid(),
    name:     (req.body.name || "Ny spilleliste").slice(0, 80),
    deptId:   deptId,
    slides:   req.body.slides || [],
    mode:     req.body.mode || "slides",
    slideInterval: Math.max(3, Math.min(300, parseInt(req.body.slideInterval) || 15)),
    slideOrder: req.body.slideOrder === "random" ? "random" : "sequential",
    showLogo:  req.body.showLogo !== false,
    ticker:   (req.body.ticker || "").slice(0, 300),
    schedule: req.body.schedule || null,
    targetScreen: _validScreens.includes(req.body.targetScreen) ? req.body.targetScreen : "center",
    isGeneral: !!req.body.isGeneral,
    createdAt: new Date().toISOString(),
    createdBy: req.session.user ? req.session.user.email : "unknown",
  };
  list.push(pl);
  savePlaylists(list);
  res.json(pl);
});

// ── Auto-generate a "year in review" playlist ─────────────────────
// Pulls every event from the given year in a department, gathers each
// event's media via buildEventSlides (same logic the cross-event slide
// browser uses), and assembles them in chronological order with a title
// card ahead of each event's photos/videos. Saves the result as a normal
// TV playlist, ready to activate on a screen like any other.
app.post("/api/tv-playlists/year-review", auth, managerOrAdmin, function(req, res) {
  const user   = req.session.user;
  const deptId = req.body.deptId;
  const year   = parseInt(req.body.year, 10) || new Date().getFullYear();
  if (!deptId) return res.status(400).json({ error: st("missing_prefix", req) + deptWord() });
  if (!hasDeptAccess(user, deptId)) return res.status(403).json({ error: st("no_access_department", req) });

  const settings = getSettings();
  const dept = (settings.departments || []).find(function(d) { return d.id === deptId; });
  if (!dept) return res.status(404).json({ error: deptWordCap() + " ikke funnet" });

  const events = readJSON(EVENTS_FILE)
    .filter(function(ev) {
      return ev.department === deptId && ev.date && !ev.cancelled &&
        new Date(ev.date).getFullYear() === year;
    })
    .sort(function(a, b) { return new Date(a.date) - new Date(b.date); });

  const combinedSlides = [];
  let eventsWithMedia = 0;

  events.forEach(function(ev) {
    const evSlides = buildEventSlides(ev);
    if (!evSlides.length) return; // skip events with nothing to show
    eventsWithMedia++;

    const dateLabel = ev.date ? new Date(ev.date).toLocaleDateString("nb-NO", { day: "numeric", month: "long" }) : "";
    combinedSlides.push({
      type: "multi-slide",
      duration: 5,
      panels: [{
        kind: "text",
        text: (ev.title || "Uten tittel") + (dateLabel ? "\n" + dateLabel : ""),
        textColor: "#ffffff",
        bg: "#111111"
      }]
    });
    evSlides.forEach(function(s) { combinedSlides.push(s); });
  });

  if (!combinedSlides.length) {
    return res.status(400).json({ error: st("no_events_with_media_prefix", req) + year + " i denne avdelingen" });
  }

  const list = readPlaylists();
  const pl = {
    id:       uuid(),
    name:     "Årsoppsummering " + year + " – " + dept.name,
    deptId:   deptId,
    slides:   combinedSlides,
    mode:     "slides",
    slideInterval: 10,
    slideOrder: "sequential", // chronological order matters here — never shuffle
    showLogo:  true,
    ticker:   "🎉 Takk for et flott år, " + dept.name + "! 🎉",
    schedule: null,
    targetScreen: "all",
    createdAt: new Date().toISOString(),
    createdBy: user.email || "unknown",
  };
  list.push(pl);
  savePlaylists(list);

  res.json({ ok: true, playlist: pl, eventCount: eventsWithMedia, slideCount: combinedSlides.length });
});

// Update playlist
app.put("/api/tv-playlists/:id", auth, managerOrAdmin, function(req, res) {
  var list = readPlaylists();
  var idx = list.findIndex(function(p) { return p.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: "Not found" });
  if (!hasDeptAccess(req.session.user, list[idx].deptId)) return res.status(403).json({ error: st("no_access_department", req) });
  if (req.body.deptId !== undefined && req.body.deptId !== list[idx].deptId && !hasDeptAccess(req.session.user, req.body.deptId)) {
    return res.status(403).json({ error: st("no_access_target_department", req) });
  }
  var allowed = ["name","slides","mode","slideInterval","slideOrder","showLogo","ticker","deptId","schedule","targetScreen","multiscreenConfig","isGeneral"];
  allowed.forEach(function(k) { if (req.body[k] !== undefined) list[idx][k] = req.body[k]; });
  list[idx].updatedAt = new Date().toISOString();
  savePlaylists(list);
  res.json(list[idx]);
});


// Duplicate playlist. Own playlists duplicate in place; a General Content
// playlist from another department can be duplicated into your own
// (pass targetDeptId) — the copy becomes a normal, non-general playlist
// owned by your department, not a shared reference to the original.
app.post("/api/tv-playlists/:id/duplicate", auth, managerOrAdmin, function(req, res) {
  var list = readPlaylists();
  var src = list.find(function(p) { return p.id === req.params.id; });
  if (!src) return res.status(404).json({ error: "Not found" });

  var isOwn = hasDeptAccess(req.session.user, src.deptId);
  if (!isOwn && !src.isGeneral) return res.status(403).json({ error: st("no_access_department", req) });

  var targetDeptId = src.deptId;
  if (!isOwn) { // duplicating someone else's General Content — must land in a department you own
    targetDeptId = req.body.targetDeptId;
    if (!targetDeptId || !hasDeptAccess(req.session.user, targetDeptId)) {
      return res.status(403).json({ error: "Oppgi en " + deptWord() + " du har tilgang til" });
    }
  }

  var copy = Object.assign({}, src, {
    id: uuid(),
    deptId: targetDeptId,
    isGeneral: isOwn ? !!src.isGeneral : false, // reused shared content starts private in its new home
    name: (req.body.name || (src.name + " (kopi)")).slice(0, 80),
    createdAt: new Date().toISOString(),
    createdBy: req.session.user ? req.session.user.email : "unknown",
  });
  list.push(copy);
  savePlaylists(list);
  res.json(copy);
});

// Delete playlist
app.delete("/api/tv-playlists/:id", auth, managerOrAdmin, function(req, res) {
  var list = readPlaylists();
  var target = list.find(function(p) { return p.id === req.params.id; });
  if (target && !hasDeptAccess(req.session.user, target.deptId)) {
    return res.status(403).json({ error: st("no_access_department", req) });
  }
  list = list.filter(function(p) { return p.id !== req.params.id; });
  savePlaylists(list);
  res.json({ ok: true });
});

// Activate a playlist on a TV channel – routes to correct screen(s)
app.post("/api/tv-playlists/:id/activate/:deptId", auth, managerOrAdmin, deptGuard, function(req, res) {
  var list = readPlaylists();
  var pl = list.find(function(p) { return p.id === req.params.id; });
  if (!pl) return res.status(404).json({ error: "Not found" });
  if (!hasDeptAccess(req.session.user, pl.deptId) && !pl.isGeneral) {
    return res.status(403).json({ error: st("playlist_not_shared", req) });
  }
  var deptId = req.params.deptId;
  var screen = req.body.targetScreen || pl.targetScreen || "center";
  var validScreens = ["center","left","right","all"];
  if (!validScreens.includes(screen)) screen = "center";

  // Build the state payload
  var statePayload = {
    slides:        pl.slides || [],
    mode:          pl.mode || "slides",
    slideInterval: pl.slideInterval || 15,
    slideOrder:    pl.slideOrder || "sequential",
    showLogo:      pl.showLogo !== false,
    ticker:        pl.ticker || "",
    activePlaylist: pl.id,
    activePlaylistName: pl.name,
    targetScreen:  screen,
  };

  // Determine which SSE channels to broadcast to
  var channels = [];
  if (screen === "center" || screen === "all") channels.push(deptId);
  if (screen === "left"   || screen === "all") channels.push(deptId + ":left");
  if (screen === "right"  || screen === "all") channels.push(deptId + ":right");

  // Multiscreen layout mode: main + companion screens auto-follow active event
  if (pl.multiscreenConfig) {
    statePayload.multiscreenConfig = pl.multiscreenConfig;
    // Also activate multiscreen mode on companion screens
    broadcastTv(deptId + ":left",  Object.assign({ type: "multiscreenCompanion", position: "left",  multiscreenConfig: pl.multiscreenConfig }));
    broadcastTv(deptId + ":right", Object.assign({ type: "multiscreenCompanion", position: "right", multiscreenConfig: pl.multiscreenConfig }));
  }

  channels.forEach(function(ch) {
    var prev = getTvState(ch);
    var next = Object.assign({}, prev, statePayload);
    tvState.set(ch, next);
    broadcastTv(ch, Object.assign({ type: "state" }, next));
  });

  // Always update center state so dashboard reflects active playlist
  var centerPrev = getTvState(deptId);
  var centerNext = Object.assign({}, centerPrev, statePayload);
  tvState.set(deptId, centerNext);
  _saveTvState();

  res.json({ ok: true, screen, channels });
});

// Save current TV state as a new or existing playlist
app.post("/api/tv/:deptId/save-as-playlist", auth, managerOrAdmin, deptGuard, function(req, res) {
  var deptId = req.params.deptId;
  var current = getTvState(deptId);
  var list = readPlaylists();
  var name = (req.body.name || "Ny spilleliste").slice(0, 80);
  var existingId = req.body.id; // if updating existing
  if (existingId) {
    var idx = list.findIndex(function(p) { return p.id === existingId; });
    if (idx >= 0) {
      list[idx] = Object.assign(list[idx], {
        name, slides: current.slides || [], mode: current.mode,
        slideInterval: current.slideInterval, slideOrder: current.slideOrder,
        showLogo: current.showLogo, ticker: current.ticker,
        deptId, updatedAt: new Date().toISOString()
      });
      savePlaylists(list);
      return res.json(list[idx]);
    }
  }
  var pl = {
    id: uuid(), name, deptId,
    slides: current.slides || [], mode: current.mode || "slides",
    slideInterval: current.slideInterval || 15,
    slideOrder: current.slideOrder || "sequential",
    showLogo: current.showLogo !== false, ticker: current.ticker || "",
    createdAt: new Date().toISOString(),
    createdBy: req.session.user ? req.session.user.email : "unknown",
  };
  list.push(pl);
  savePlaylists(list);
  res.json(pl);
});

// ── TV-node fjernstyring (Pi-agent over Tailscale) ────────────────
function readTvNodes() { return readJSON(TV_NODES_FILE) || []; }
function saveTvNodes(list) { writeJSON(TV_NODES_FILE, list); }

// ── HTTP management layer (heartbeat, monitoring, terminal, wifi, sd-script) ──
try {
  require("./tv-http-management")(app, {
    readTvNodes, saveTvNodes, readJSON, writeJSON, DATA,
    auth, managerOrAdmin, adminOnly, st, uuid, getProvisionConfig
  });
} catch (e) {
  console.warn("[TV-HTTP] Module not loaded:", e.message);
}

// Proxies a request to the agent running on a TV-node.
// node = { host, port, token }. path = "/status" etc.
function callAgent(node, method, agentPath, body, cb) {
  var http = require("http");
  var payload = body ? JSON.stringify(body) : null;
  var opts = {
    hostname: node.host,
    port: node.port || 9191,
    path: agentPath,
    method: method,
    headers: {
      "X-Agent-Token": node.token || "",
      "Content-Type": "application/json",
    },
    timeout: 8000,
  };
  if (payload) opts.headers["Content-Length"] = Buffer.byteLength(payload);

  var req = http.request(opts, function (res) {
    var data = "";
    res.on("data", function (c) { data += c; });
    res.on("end", function () {
      var parsed = null;
      try { parsed = JSON.parse(data); } catch (e) {}
      cb(null, res.statusCode, parsed);
    });
  });
  req.on("timeout", function () { req.destroy(); cb(new Error("Timeout")); });
  req.on("error", function (err) { cb(err); });
  if (payload) req.write(payload);
  req.end();
}

// List all registered TV-nodes (optionally filtered by department)
app.get("/api/tv-nodes", auth, managerOrAdmin, function (req, res) {
  var list = readTvNodes();
  if (req.query.dept === "unassigned") {
    list = list.filter(function (n) { return !n.deptId; });
  } else if (req.query.dept) {
    list = list.filter(function (n) { return n.deptId === req.query.dept; });
  }
  // Never leak tokens to the frontend list view
  res.json(list.map(function (n) { return Object.assign({}, n, { token: undefined, hasToken: !!n.token }); }));
});

// Register a new TV-node
app.post("/api/tv-nodes", auth, managerOrAdmin, function (req, res) {
  var b = req.body || {};
  var host = (b.host || "").trim();
  var token = (b.token || "").trim();
  // Pre-registration mode: host/token unknown yet — server generates the token,
  // host gets filled in automatically the first time the agent calls home.
  var preRegister = !host && !token;
  if (!preRegister) {
    if (!host) return res.status(400).json({ error: st("host_required", req) });
    if (!token) return res.status(400).json({ error: st("token_required", req) });
  }
  var list = readTvNodes();
  var node = {
    id: uuid(),
    name: (b.name || "TV-node").slice(0, 60),
    host: host || null,
    port: parseInt(b.port, 10) || 9191,
    token: token || require("crypto").randomBytes(24).toString("base64url"),
    deptId: b.deptId || null,
    status: preRegister ? "pending" : "registered",
    createdAt: new Date().toISOString(),
  };
  list.push(node);
  saveTvNodes(list);
  res.json(Object.assign({}, node, { token: undefined, hasToken: true, fullToken: preRegister ? node.token : undefined }));
});

// Update a TV-node (rename, change dept link, rotate token)
app.put("/api/tv-nodes/:id", auth, managerOrAdmin, function (req, res) {
  var list = readTvNodes();
  var idx = list.findIndex(function (n) { return n.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: "Not found" });
  var sessUser = req.session.user;
  if (!tvNodeVisibleTo(sessUser, list[idx])) return res.status(403).json({ error: st("no_access_department", req) });
  if (req.body.deptId && !hasDeptAccess(sessUser, req.body.deptId)) return res.status(403).json({ error: st("no_access_department", req) });
  var oldDeptId = list[idx].deptId;
  var oldName = list[idx].name;
  var allowed = ["name", "host", "port", "token", "deptId"];
  allowed.forEach(function (k) {
    if (req.body[k] !== undefined) list[idx][k] = req.body[k] || null;
  });
  saveTvNodes(list);

  // If department changed, queue a URL change and hostname update to the Pi
  var newDeptId = list[idx].deptId;
  var newName = list[idx].name;
  if (newDeptId && newDeptId !== oldDeptId) {
    var tvUrl = tvChannelUrl(newDeptId, list[idx].screen);
    if (tvUrl) {
      list[idx].kioskUrl = tvUrl;
      saveTvNodes(list);
      queueTvCommand(req.params.id, { setUrl: tvUrl });
    }
  }
  if (newName && newName !== oldName) {
    queueTvCommand(req.params.id, { setHostname: newName });
  }

  res.json(Object.assign({}, list[idx], { token: undefined, hasToken: true }));
});

// Delete a TV-node
app.delete("/api/tv-nodes/:id", auth, managerOrAdmin, function (req, res) {
  var list = readTvNodes().filter(function (n) { return n.id !== req.params.id; });
  saveTvNodes(list);
  res.json({ ok: true });
});

// Get live status from a node's agent
app.get("/api/tv-nodes/:id/status", auth, managerOrAdmin, function (req, res) {
  var nodes = readTvNodes();
  var node = nodes.find(function (n) { return n.id === req.params.id; });
  if (!node) return res.status(404).json({ error: "Not found" });

  // Try direct agent connection first
  callAgent(node, "GET", "/status", null, function (err, statusCode, data) {
    if (!err && statusCode === 200 && data) {
      return res.json(Object.assign({ online: true }, data));
    }

    // Fall back to heartbeat health data
    if (node.health && node.lastSeen) {
      var ageMs = Date.now() - new Date(node.lastSeen).getTime();
      var online = ageMs < 120000; // within 2 minutes
      var h = node.health;
      return res.json({
        online: online,
        uptimeSeconds: h.uptime || 0,
        tempC: h.cpuTemp,
        cpuLoad: h.cpuLoad,
        memory: h.memoryTotal ? { usedPercent: Math.round(h.memoryUsed / h.memoryTotal * 100) } : null,
        disk: h.diskUsed != null ? { usedPercent: h.diskUsed + "%" } : null,
        osVersion: h.osVersion,
        agentVersion: h.agentVersion,
        netIface: h.netIface, netSsid: h.netSsid, localIp: h.localIp,
        aptUpdates: h.aptUpdates, rebootRequired: h.rebootRequired,
        lastSeen: node.lastSeen,
        viaHeartbeat: true,
      });
    }

    res.status(502).json({ ok: false, online: false, error: err ? err.message : "Ingen kontakt" });
  });
});

// Reboot a node
app.post("/api/tv-nodes/:id/reboot", auth, managerOrAdmin, function (req, res) {
  var node = readTvNodes().find(function (n) { return n.id === req.params.id; });
  if (!node) return res.status(404).json({ error: "Not found" });
  callAgent(node, "POST", "/reboot", null, function (err, statusCode, data) {
    if (err) return res.status(502).json({ ok: false, error: err.message });
    res.json(data || { ok: true });
  });
});

// Show the device name fullscreen on this specific node for a couple minutes,
// then automatically revert to whatever it was showing before. Useful for
// telling identical-looking Pis apart after a move/relocation.
app.post("/api/tv-nodes/:id/identify", auth, managerOrAdmin, function (req, res) {
  var node = readTvNodes().find(function (n) { return n.id === req.params.id; });
  if (!node) return res.status(404).json({ error: "Not found" });
  var proto = req.headers["x-forwarded-proto"] || req.protocol;
  var host = req.headers.host;
  var identifyUrl = proto + "://" + host + "/tv-identify/" + node.id;
  callAgent(node, "POST", "/identify", { identifyUrl: identifyUrl, durationSeconds: 120 }, function (err, statusCode, data) {
    if (err) return res.status(502).json({ ok: false, error: err.message });
    res.json(data || { ok: true });
  });
});

// Re-run kiosk setup on a node (writes autologin, .xinitrc, tv-kiosk.service)
// without reinstalling Node.js or the agent itself. Useful when the kiosk
// service is missing after a fresh OS install or agent-only bootstrap.
app.post("/api/tv-nodes/:id/setup-kiosk", auth, managerOrAdmin, function (req, res) {
  var node = readTvNodes().find(function (n) { return n.id === req.params.id; });
  if (!node) return res.status(404).json({ error: "Not found" });
  callAgent(node, "POST", "/setup-kiosk", null, function (err, statusCode, data) {
    if (err) return res.status(502).json({ ok: false, error: err.message });
    res.json(data || { ok: true });
  });
});

// Tell the node to pull the latest agent.js from this server using its
// own token — the agent fetches the file itself and restarts. This avoids
// having to push large base64 payloads through the agent tunnel.
app.post("/api/tv-nodes/:id/update-agent", auth, managerOrAdmin, function (req, res) {
  var node = readTvNodes().find(function (n) { return n.id === req.params.id; });
  if (!node) return res.status(404).json({ error: "Not found" });
  var proto = req.headers["x-forwarded-proto"] || req.protocol;
  var host = req.headers.host;
  var agentUrl = proto + "://" + host + "/api/tv-agent/agent-code";
  callAgent(node, "POST", "/update-agent", { agentUrl: agentUrl }, function (err, statusCode, data) {
    if (err) return res.status(502).json({ ok: false, error: err.message });
    res.json(data || { ok: true });
  });
});

// Soft reset — clears token/URL/node-id so Pi can be re-registered,
// keeps OS and software intact.
app.post("/api/tv-nodes/:id/soft-reset", auth, managerOrAdmin, function (req, res) {
  var node = readTvNodes().find(function (n) { return n.id === req.params.id; });
  if (!node) return res.status(404).json({ error: "Not found" });
  callAgent(node, "POST", "/soft-reset", null, function (err, statusCode, data) {
    if (err) return res.status(502).json({ ok: false, error: err.message });
    // Optionally remove from Event-Admin device list
    if (req.body && req.body.removeFromList) {
      var nodes = readTvNodes().filter(function (n) { return n.id !== req.params.id; });
      writeJSON(TV_NODES_FILE, nodes);
    }
    res.json(data || { ok: true });
  });
});

// Hard reset — removes all agent/kiosk config from the Pi completely.
app.post("/api/tv-nodes/:id/hard-reset", auth, managerOrAdmin, function (req, res) {
  var node = readTvNodes().find(function (n) { return n.id === req.params.id; });
  if (!node) return res.status(404).json({ error: "Not found" });
  callAgent(node, "POST", "/hard-reset", null, function (err, statusCode, data) {
    // Hard reset kills the agent — a connection error after the response is expected
    if (err && err.message !== "Timeout" && !err.message.includes("ECONNRESET")) {
      return res.status(502).json({ ok: false, error: err.message });
    }
    // Always remove from Event-Admin list on hard reset (Pi needs full reinstall)
    if (req.body && req.body.removeFromList) {
      var nodes = readTvNodes().filter(function (n) { return n.id !== req.params.id; });
      writeJSON(TV_NODES_FILE, nodes);
    }
    res.json(data || { ok: true, message: "Hard reset initiated." });
  });
});

// Push a new kiosk URL to a node
app.post("/api/tv-nodes/:id/set-url", auth, managerOrAdmin, function (req, res) {
  var node = readTvNodes().find(function (n) { return n.id === req.params.id; });
  if (!node) return res.status(404).json({ error: "Not found" });
  var url = (req.body && req.body.url || "").trim();
  if (!/^https?:\/\//i.test(url)) return res.status(400).json({ error: st("invalid_url", req) });
  callAgent(node, "POST", "/set-url", { url: url }, function (err, statusCode, data) {
    if (err) return res.status(502).json({ ok: false, error: err.message });
    res.json(data || { ok: true });
  });
});

// Change the Pi's Linux login password
app.post("/api/tv-nodes/:id/change-password", auth, managerOrAdmin, function (req, res) {
  var node = readTvNodes().find(function (n) { return n.id === req.params.id; });
  if (!node) return res.status(404).json({ error: "Not found" });
  var newPassword = (req.body && req.body.newPassword || "");
  if (newPassword.length < 8) return res.status(400).json({ error: st("password_min_8_alt", req) });
  callAgent(node, "POST", "/change-password", { newPassword: newPassword }, function (err, statusCode, data) {
    if (err) return res.status(502).json({ ok: false, error: err.message });
    if (statusCode !== 200) return res.status(502).json(data || { ok: false, error: st("agent_rejected_request", req) });
    res.json(data || { ok: true });
  });
});

// -- TV agent file distribution (download to set up a new TV node) --
// ── Screen-side files (forked from Infoskjerm 4.9.71) ─────────────────
// GENERATED from the fork. Edit the files and regenerate; do not edit here.
// The agent is plain Python, the rest are shell scripts. They are kept as
// JSON strings because only server.js/index.html/package.json are deployed.
const SCREEN_FILES = {
  "infoscreen-agent.py": "#!/usr/bin/env python3\n\"\"\"\nEvent-Admin screen agent — forked from InfoScreen-Agent 4.9.71 (Infoskjerm).\nThe device protocol is unchanged (/api/provision, /api/pi/*, /viewer, /hold), so\nfixes from the Infoskjerm agent can be carried over with a plain diff.\nNot shipped with this fork: USB guard, port guard (the server does not serve them).\n\nRuns on Raspberry Pi 4/5/Zero and any Linux device (USB boot or installed).\n\nFirst boot: calls /api/provision with shared secret -> gets token\nSubsequent boots: uses saved token directly\n\nConfig: /etc/infoscreen.env\n  INFOSCREEN_URL=https://infoscreen.yourdomain.com\n  PROVISION_SECRET=YOUR_SECRET_HERE\n  PI_TOKEN=                        # filled automatically after provisioning\n  POLL_INTERVAL=15\n  BROWSER=chromium-browser\n  DISPLAY=:0\n\"\"\"\n\nAGENT_VERSION = '1.0.0'\nAGENT_UPSTREAM = 'InfoScreen-Agent 4.9.71'\n\nimport os, sys, time, json, socket, subprocess, threading, signal, logging, sqlite3, re, ipaddress\nimport urllib.parse\nimport shlex\nfrom http.server import HTTPServer, ThreadingHTTPServer, BaseHTTPRequestHandler\n\ntry:\n    import requests, psutil\nexcept ImportError:\n    print(\"Missing deps. Run: pip3 install requests psutil --break-system-packages\")\n    sys.exit(1)\n\n# v4.9.55: everything on a screen is named InfoScreen. A screen installed\n# before that keeps its old names until its next screen bundle renames it\n# (infoscreen-migrate runs as root before any file is replaced). This agent\n# reaches such a screen first, through its self-update, so it must run in both\n# states: N() gives the name the screen actually has. /etc/infoscreen.env is\n# the sign that a screen has been renamed; a new install has nothing else.\nLEGACY = 'piscreen'   # the old name: only ever used to find what a screen still has\nRENAMED = os.path.exists('/etc/infoscreen.env') or not os.path.exists(f'/etc/{LEGACY}.env')\n\n\ndef N(name):\n    \"\"\"`name` as this screen has it: as given once renamed, else the old name.\"\"\"\n    if RENAMED:\n        return name\n    return name.replace('infoscreen', LEGACY).replace('INFOSCREEN', LEGACY.upper())\n\n\n# The service manager passes the env file to the agent's environment, so on a\n# screen that is not renamed yet the settings arrive under their old prefix.\nfor _k in list(os.environ):\n    if _k.startswith(LEGACY.upper() + '_'):\n        os.environ.setdefault('INFOSCREEN_' + _k[len(LEGACY) + 1:], os.environ[_k])\n\nCONFIG_FILE = N('/etc/infoscreen.env')\nTOKEN_FILE  = N('/etc/infoscreen.token')\nSTATE_DIR   = N('/var/lib/infoscreen')\nHARDEN_BIN  = N('/usr/local/bin/infoscreen-harden')\nRUNNER_BIN  = N('/usr/local/bin/infoscreen-commands')\nRUNNER_SVC  = N('infoscreen-commands')\nGUARD_FILE  = N('infoscreen-usbguard.py')\nPORTGUARD_FILE = N('infoscreen-portguard.py')\nHOME_TOKEN  = N('~/.infoscreen.token')\n\n\ndef component_url(server, name):\n    \"\"\"Server copy of a screen component. Without ?names=infoscreen the server\n    sends the copy for screens with the old names (and for older agents).\"\"\"\n    return f'{server}/api/pi/component/{name}' + ('?names=infoscreen' if RENAMED else '')\nLIVE_PORT   = 7779\n\n\ndef _browser_lang():\n    \"\"\"Chromium UI/Accept-Language for the screen. Event-Admin serves clubs in\n    several countries, so this comes from SCREEN_LANG in the env file instead of\n    being fixed to Norwegian. Only plain language tags are accepted.\"\"\"\n    lang = str(os.environ.get('SCREEN_LANG') or '').strip()\n    if not lang:\n        try:\n            lang = str(load_config().get('SCREEN_LANG', '')).strip()\n        except Exception:\n            lang = ''\n    return lang if re.fullmatch(r'[a-z]{2,3}(-[A-Z]{2})?', lang or '') else 'nb'\n\n# v4.9.51: the agent is InfoScreen-Agent. New installs and migrated screens\n# use /opt/infoscreen-agent and the service infoscreen-agent. A screen that has\n# only received this file through its old self-update still runs it from the\n# old folder under the old service until the full screen bundle moves it (infoscreen-agent-migrate,\n# then a reboot). Everything below works in both states; nothing may assume one.\nAGENT_NAME        = 'Event-Admin screen agent'\nNEW_AGENT_DIR     = '/opt/infoscreen-agent'\nLEGACY_AGENT_DIR  = f'/opt/{LEGACY}-agent'\nAGENT_DIR         = NEW_AGENT_DIR if os.path.isdir(NEW_AGENT_DIR) else LEGACY_AGENT_DIR\n# The file this process actually runs, resolved through compatibility links:\n# self-updates must replace THIS file, whatever name it was started by.\nAGENT_FILE        = os.path.realpath(os.path.abspath(__file__))\nMETRICS_DB        = os.path.join(AGENT_DIR, 'metrics.db')\n# The path the root helper accepts for install-harden. Helpers on screens that\n# are not renamed accept only the old folder's path (a link to the new folder\n# once the agent has moved); the renamed screen's helper accepts the new one.\nHARDEN_COPY_PATH  = os.path.join(NEW_AGENT_DIR if RENAMED else LEGACY_AGENT_DIR, 'harden-kiosk.sh')\n# Both process names, for pgrep/ownership checks during the transition.\nAGENT_PROC_RE     = r'(info|pi)screen-agent\\.py'\n\n\ndef agent_service():\n    \"\"\"The init-system name of the service running THIS process.\n\n    Prefer what the kernel says (systemd puts the unit in our cgroup), so a\n    screen that already has the new unit on disk but still runs the old one\n    until its reboot restarts the right thing. Fall back to what is installed.\"\"\"\n    try:\n        with open('/proc/self/cgroup') as f:\n            cg = f.read()\n        for name in ('infoscreen-agent', f'{LEGACY}-agent'):\n            if f'/{name}.service' in cg:\n                return name\n    except Exception:\n        pass\n    for name in ('infoscreen-agent', f'{LEGACY}-agent'):\n        if os.path.exists(f'/etc/systemd/system/{name}.service') or os.path.exists(f'/etc/init.d/{name}'):\n            return name\n    return 'infoscreen-agent'\n\n\n# v4.9.53: never a fixed name in the shared /tmp for a file this agent writes.\n# /tmp is sticky: a file another user (a root-run agent, a root shell) left\n# under the same name cannot be replaced by the kiosk user, and the write fails\n# with «Permission denied» — that stopped self-updates, and the same thing on\n# the Chromium start log would stop the browser from starting.\ndef _own_tmp(name):\n    \"\"\"/tmp/<name> when this user may write it, else a per-user variant.\"\"\"\n    p = os.path.join('/tmp', name)\n    try:\n        st = os.lstat(p)\n        if st.st_uid == os.geteuid() and not os.path.islink(p):\n            return p\n    except FileNotFoundError:\n        return p\n    except OSError:\n        pass\n    base, ext = os.path.splitext(name)\n    return os.path.join('/tmp', f'{base}-{os.geteuid()}{ext}')\n\n\ndef _private_tmp(prefix, suffix=''):\n    \"\"\"A new, unique temp file owned by this process (for one-off checks).\"\"\"\n    import tempfile\n    fd, p = tempfile.mkstemp(prefix=prefix, suffix=suffix)\n    os.close(fd)\n    return p\n\n# v4.9.43: some managed networks publish both A and AAAA records while their\n# client VLAN has no working IPv6 path to the Internet. The field Pi resolves\n# the control server to IPv6 first and then waits for TCP timeout before trying\n# IPv4. That makes viewer/config requests look randomly dead even though IPv4\n# is healthy. Detect that condition once the network is up, prefer IPv4 in the\n# agent process, and tell Chromium not to make AAAA connections. IPv6 is left\n# alone when it actually works, and INFOSCREEN_IPV6=1/0 is an explicit override.\n_ORIG_GETADDRINFO = socket.getaddrinfo\n_net_family = {'checked': 0.0, 'prefer_ipv4': False, 'reason': '', 'configured': False,\n               'host': '', 'ipv4': ''}\n\ndef _ipv4_first_getaddrinfo(host, port, *args, **kwargs):\n    rows = _ORIG_GETADDRINFO(host, port, *args, **kwargs)\n    return sorted(rows, key=lambda r: 0 if r[0] == socket.AF_INET else (1 if r[0] == socket.AF_INET6 else 2))\n\ndef _family_tcp_ok(host, port, family, timeout=1.6):\n    try:\n        rows = _ORIG_GETADDRINFO(host, port, family, socket.SOCK_STREAM)\n    except Exception:\n        return None\n    if not rows:\n        return None\n    seen = set()\n    for fam, typ, proto, _canon, addr in rows:\n        key = (fam, addr)\n        if key in seen:\n            continue\n        seen.add(key)\n        sock = None\n        try:\n            sock = socket.socket(fam, typ, proto)\n            sock.settimeout(timeout)\n            sock.connect(addr)\n            return True\n        except Exception:\n            pass\n        finally:\n            try:\n                if sock: sock.close()\n            except Exception:\n                pass\n    return False\n\ndef _resolved_ipv4(host, port):\n    \"\"\"Return one current public/normal IPv4 answer for the control host.\n\n    Chromium has its own resolver, so sorting Python's getaddrinfo results does\n    not change what the renderer chooses.  When the network has a dead AAAA\n    path we pin only the InfoScreen control hostname to a verified A record for\n    this browser process.  TLS still uses the original hostname/SNI.\n    \"\"\"\n    try:\n        for fam, typ, proto, _canon, addr in _ORIG_GETADDRINFO(host, port, socket.AF_INET, socket.SOCK_STREAM):\n            ip = str(addr[0])\n            try:\n                obj = ipaddress.ip_address(ip)\n                if obj.version == 4:\n                    return ip\n            except Exception:\n                continue\n    except Exception:\n        pass\n    return ''\n\ndef configure_network_family(server, force=False):\n    \"\"\"Auto-detect broken IPv6 and prefer IPv4 without changing the OS network.\n\n    Returns True when Chromium should be launched with --disable-ipv6. A failed\n    probe while Wi-Fi is still coming up is *not* treated as broken IPv6; at\n    least one IPv4 TCP connection must succeed before the fallback is enabled.\n    \"\"\"\n    now = time.time()\n    if _net_family['configured'] and _net_family['prefer_ipv4']:\n        return True\n    if not force and now - float(_net_family.get('checked') or 0) < 20:\n        return bool(_net_family.get('prefer_ipv4'))\n    _net_family['checked'] = now\n    override = str(os.environ.get('INFOSCREEN_IPV6', '')).strip().lower()\n    try:\n        if not override and os.path.isfile(CONFIG_FILE):\n            for line in open(CONFIG_FILE, errors='replace'):\n                if line.strip().startswith(('INFOSCREEN_IPV6=', LEGACY.upper() + '_IPV6=')):\n                    override = _env_value(line.partition('=')[2]).strip().lower() if '_env_value' in globals() else line.partition('=')[2].strip().strip(\"'\\\"\").lower()\n                    break\n    except Exception:\n        pass\n    if override in ('1', 'true', 'yes', 'on', 'force'):\n        _net_family.update(configured=True, prefer_ipv4=False, reason='forced IPv6 enabled')\n        return False\n    if override in ('0', 'false', 'no', 'off', 'disable'):\n        socket.getaddrinfo = _ipv4_first_getaddrinfo\n        _net_family.update(configured=True, prefer_ipv4=True, reason='INFOSCREEN_IPV6=0')\n        return True\n    try:\n        u = urllib.parse.urlparse(server if '://' in server else 'https://' + server)\n        host = u.hostname or ''\n        port = u.port or (443 if u.scheme == 'https' else 80)\n        if not host:\n            return False\n        result = {'v4': None, 'v6': None}\n        def probe(name, family):\n            result[name] = _family_tcp_ok(host, port, family)\n        t4 = threading.Thread(target=probe, args=('v4', socket.AF_INET), daemon=True)\n        t6 = threading.Thread(target=probe, args=('v6', socket.AF_INET6), daemon=True)\n        t4.start(); t6.start(); t4.join(2.2); t6.join(2.2)\n        if result.get('v4') is True and result.get('v6') is False:\n            socket.getaddrinfo = _ipv4_first_getaddrinfo\n            ipv4 = _resolved_ipv4(host, port)\n            _net_family.update(configured=True, prefer_ipv4=True, host=host, ipv4=ipv4,\n                               reason=f'IPv6 TCP to {host}:{port} failed while IPv4 succeeded')\n            try:\n                log.warning('Broken IPv6 path detected for %s; preferring IPv4 for agent and kiosk browser%s',\n                            host, f' ({ipv4})' if ipv4 else '')\n            except Exception: pass\n            return True\n        if result.get('v4') is True or result.get('v6') is True:\n            _net_family.update(configured=True, prefer_ipv4=False, host=host, ipv4='',\n                               reason='IPv6 usable' if result.get('v6') is True else 'IPv4 only/no AAAA')\n    except Exception as e:\n        try: log.debug('network family probe: %s', e)\n        except Exception: pass\n    return bool(_net_family.get('prefer_ipv4'))\n\n# ── WebSocket send helpers ───────────────────────────────────────\n# `_ws_conn` is created by ws_connection() further down. These two exist so\n# that code above it — the screen streamer, the USB guard — can push a message\n# without each of them caring whether the socket happens to be up right now.\n\ndef _ws_is_up():\n    try:\n        return bool(_ws_conn and _ws_conn.sock and _ws_conn.sock.connected)\n    except Exception:\n        return False\n\n\ndef ws_send(payload):\n    \"\"\"Send on the agent socket. Returns False if there is no socket.\"\"\"\n    if not _ws_is_up():\n        return False\n    try:\n        _ws_conn.send(json.dumps(payload))\n        return True\n    except Exception as e:\n        log.debug('ws_send failed: %s', e)\n        return False\n\n\n# ── USB guard ────────────────────────────────────────────────────\n# Imported rather than inlined so that an agent from an older bundle, where the\n# file is simply not there, keeps running instead of crashing on startup. The\n# screen still works; it just is not locked down, and the portal says so.\n_usbguard = None\n_usb_policy_cache = None\n\ntry:\n    sys.path.insert(0, AGENT_DIR)\n    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n    import importlib.util as _ilu\n    _spec = None\n    for _cand in (os.path.join(AGENT_DIR, GUARD_FILE),\n                  os.path.join(os.path.dirname(os.path.abspath(__file__)), GUARD_FILE)):\n        if os.path.exists(_cand):\n            _spec = _ilu.spec_from_file_location('infoscreen_usbguard', _cand)\n            break\n    if _spec:\n        _usbmod = _ilu.module_from_spec(_spec)\n        _spec.loader.exec_module(_usbmod)\n        UsbGuard = _usbmod.UsbGuard\n    else:\n        UsbGuard = None\nexcept Exception as _e:\n    UsbGuard = None\n\n\ndef report_tamper(kind, payload=None):\n    \"\"\"Tell the server something happened. Socket first, HTTP if it is down.\n\n    A tamper alert is the one message in this agent where arriving late is\n    almost as bad as not arriving, so it never waits for the next heartbeat.\n    \"\"\"\n    body = dict(payload or {})\n    body['type'] = 'tamper'\n    body['kind'] = kind\n    if ws_send(body):\n        return True\n    try:\n        cfg = _cfg or {}\n        server = cfg.get('server', '')\n        token = cfg.get('token', '')\n        if server and token:\n            http_body = {k: v for k, v in body.items() if k != 'type'}\n            requests.post(f'{server}/api/pi/tamper', json=http_body,\n                          headers={'X-Pi-Token': token}, timeout=8)\n            return True\n    except Exception as e:\n        log.debug('tamper report failed: %s', e)\n    return False\n\n\n_last_topology = None\n_last_policy_applied = False\n\n\ndef report_topology(topology, policy_applied=False):\n    \"\"\"Send the list of physical USB ports the device can actually see.\"\"\"\n    global _last_topology, _last_policy_applied\n    if topology:\n        _last_topology, _last_policy_applied = topology, policy_applied\n    body = dict(topology or {})\n    body['type'] = 'hardware'\n    body['policy_applied'] = policy_applied\n    try:\n        body['components'] = component_status()\n        laptop = laptop_status()\n        if laptop:\n            body['laptop'] = laptop\n    except Exception:\n        pass\n    body['agent_version'] = AGENT_VERSION if 'AGENT_VERSION' in globals() else ''\n    try:\n        body['input_lock'] = _input_lock_public()\n    except Exception:\n        pass\n    if ws_send(body):\n        return True\n    try:\n        cfg = _cfg or {}\n        server = cfg.get('server', '')\n        token = cfg.get('token', '')\n        if server and token:\n            http_body = {k: v for k, v in body.items() if k != 'type'}\n            requests.post(f'{server}/api/pi/hardware', json=http_body,\n                          headers={'X-Pi-Token': token}, timeout=10)\n            return True\n    except Exception as e:\n        log.debug('topology report failed: %s', e)\n    return False\n\n\ndef start_usb_guard():\n    \"\"\"Bring the guard up in deny-by-default and report what we have.\"\"\"\n    global _usbguard\n    if _usbguard or not UsbGuard:\n        if not UsbGuard:\n            log.warning('%s not found — USB ports are NOT locked down', GUARD_FILE)\n        return _usbguard\n\n    _usbguard = UsbGuard(\n        report=lambda kind, payload: report_tamper(kind, payload),\n        on_topology=lambda topology: report_topology(topology,\n                                                     policy_applied=_usb_policy_cache is not None),\n    )\n    # Deny by default from the first second, before the server has said\n    # anything. A screen that boots with no rules should refuse a keyboard, not\n    # accept one until told otherwise — the gap between power-on and the first\n    # heartbeat is exactly the gap somebody would use.\n    _usbguard.set_policy({'enforce': True, 'default_action': 'lock'})\n    _usbguard.start()\n    return _usbguard\n\n\ndef apply_usb_policy(policy):\n    \"\"\"Take a policy from the server and hand it to the guard.\"\"\"\n    global _usb_policy_cache\n    if not policy:\n        return\n    if policy == _usb_policy_cache:\n        return\n    _usb_policy_cache = policy\n    guard = start_usb_guard()\n    if guard:\n        guard.set_policy(policy)\n        _input_lock_wake.set()\n        try:\n            report_topology(guard.topology(), policy_applied=True)\n        except Exception as e:\n            log.debug('topology after policy: %s', e)\n\n\ndef collect_diagnostics(reason='manual'):\n    \"\"\"Gather the same picture the installer USB dumps, and upload it.\n\n    On a laptop the installer writes a diagnostic file to the stick and you can\n    read it on any PC. A Pi hanging on a wall has neither, so when something\n    breaks there is nothing to look at — which is how several failures in this\n    system stayed invisible for days. This closes that: the device sends the\n    evidence by itself.\n    \"\"\"\n    parts = []\n\n    def section(title, cmd=None, path=None, limit=20000):\n        parts.append(f'\\n===== {title} =====')\n        try:\n            if path:\n                with open(path, 'r', errors='replace') as f:\n                    parts.append(f.read()[-limit:])\n            elif cmd:\n                r = subprocess.run(cmd, shell=True, capture_output=True, timeout=25)\n                out = (r.stdout + r.stderr).decode('utf-8', 'replace')\n                parts.append(out[-limit:] or '(no output)')\n        except Exception as e:\n            parts.append(f'(unavailable: {e})')\n\n    parts.append('InfoScreen-Agent diagnostics')\n    parts.append(f'collected: {datetime.now().isoformat()}')\n    parts.append(f'reason:    {reason}')\n    parts.append(f'agent:     {AGENT_VERSION}')\n\n    section('SYSTEM',        'uname -a; cat /etc/os-release 2>/dev/null; uptime')\n    section('HARDWARE',      'cat /proc/device-tree/model 2>/dev/null; '\n                             'cat /sys/devices/virtual/dmi/id/product_name 2>/dev/null; '\n                             'free -m; df -h')\n    section('COMPONENTS',    None)\n    try:\n        parts.append(json.dumps(component_status(), indent=2))\n        lap = laptop_status()\n        if lap:\n            parts.append('laptop: ' + json.dumps(lap, indent=2))\n    except Exception as e:\n        parts.append(f'(unavailable: {e})')\n    _svc = agent_service()\n    section('AGENT SERVICE', f'systemctl status {_svc} --no-pager 2>/dev/null || '\n                             f'rc-service {_svc} status 2>/dev/null')\n    section('AGENT LOG',     f'journalctl -u {_svc} -n 300 --no-pager 2>/dev/null || '\n                             'tail -300 /var/log/infoscreen-agent.log 2>/dev/null || '\n                             f'tail -300 /var/log/{LEGACY}-agent.log 2>/dev/null')\n    section('BROWSER / X',   'ps aux | grep -E \"chromium|Xorg|openbox\" | grep -v grep; '\n                             'ls -l /dev/dri/ 2>/dev/null; '\n                             'tail -100 /var/log/Xorg.0.log 2>/dev/null')\n    section('DISPLAY DEVICES', 'ls /dev/input/ 2>/dev/null; '\n                               'pgrep -l udevd 2>/dev/null || echo \"udevd NOT running\"')\n    section('NETWORK',       'ip addr; ip route; cat /etc/resolv.conf 2>/dev/null')\n    section('USB',           'ls -l /sys/bus/usb/devices/ 2>/dev/null')\n    try:\n        if _usbguard:\n            parts.append(json.dumps(_usbguard.topology(), indent=2, ensure_ascii=False))\n    except Exception:\n        pass\n    section('KIOSK HARDENING', None, path=os.path.join(STATE_DIR, 'hardening.json'))\n    section('INSTALL LOG',   None, path='/boot/firmware/infoskjerm-install.log', limit=30000)\n    section('DMESG',         'dmesg | tail -200')\n\n    # v4.9.54: the dump file on the card itself (infoscreen-collect-diagnostics.sh\n    # writes it to the boot partition, readable on any PC) and Chromium's own\n    # start log, so neither needs a Terminal or a card reader to be read.\n    section('CHROMIUM START LOG', None, path=_own_tmp('infoscreen-chromium-last.log'), limit=15000)\n    # v4.9.58: the screen helper says where it starts (console, see open_url).\n    try:\n        _lines = open(_own_tmp('infoscreen-chromium-last.log'), errors='replace').read().splitlines()\n        _keep = [l[:400] for l in _lines if 'skjermhjelper' in l or 'chrome-extension://' in l or 'Uncaught' in l]\n        parts.append('\\n===== SCREEN HELPER CONSOLE =====')\n        parts.append('\\n'.join(_keep[-80:]) or '(no line from the screen helper: it did not start in any page)')\n    except Exception as e:\n        parts.append(f'\\n===== SCREEN HELPER CONSOLE =====\\n(unavailable: {e})')\n    # v4.9.56: did Chromium actually load the screen helper? It records loaded\n    # extensions in the profile; a policy can make it ignore --load-extension\n    # without a word in its log.\n    parts.append('\\n===== SCREEN HELPER IN CHROMIUM =====')\n    try:\n        prof = os.path.join(_own_tmp('infoscreen-browser'), 'Default')\n        seen = []\n        for name in ('Secure Preferences', 'Preferences'):\n            fp = os.path.join(prof, name)\n            if not os.path.isfile(fp):\n                continue\n            try:\n                pj = json.load(open(fp, encoding='utf-8', errors='replace'))\n            except Exception as e:\n                seen.append(f'{name}: unreadable ({e})'); continue\n            ext = pj.get('extensions') or {}\n            seen.append(f\"{name}: developer_mode={(ext.get('ui') or {}).get('developer_mode')}\")\n            for eid, v in (ext.get('settings') or {}).items():\n                if 'cookie-dismiss' in str((v or {}).get('path', '')):\n                    keep = {k: v.get(k) for k in ('state', 'disable_reasons', 'location', 'creation_flags',\n                                                  'withholding_permissions', 'was_installed_by_default') if k in v}\n                    seen.append(f'  {eid} {v.get(\"path\")} {json.dumps(keep)}')\n        parts.append('\\n'.join(seen) or f'(no profile at {prof})')\n    except Exception as e:\n        parts.append(f'(unavailable: {e})')\n    import glob as _glob\n    dumps = []\n    # Both names: a card prepared before v4.9.55 writes its dumps under the old one.\n    for pat in [f'{d}/{n}-logs/*.txt' for n in ('infoscreen', LEGACY)\n                for d in ('/boot/firmware', '/boot', '/media/*')] + \\\n               ['/tmp/infoscreen-diag-*.txt', f'/tmp/{LEGACY}-diag-*.txt']:\n        for f in _glob.glob(pat):\n            try:\n                dumps.append((os.path.getmtime(f), f))\n            except OSError:\n                pass\n    dumps.sort(reverse=True)\n    parts.append('\\n===== SD-CARD DUMP FILES =====')\n    if not dumps:\n        _tool = next((t for t in ('/boot/firmware/infoscreen-collect-diagnostics.sh',\n                                  f'/boot/firmware/{LEGACY}-collect-diagnostics.sh') if os.path.exists(t)),\n                     '/boot/firmware/infoscreen-collect-diagnostics.sh')\n        parts.append(f'(none — run: sudo bash {_tool})')\n    for mtime, f in dumps[:10]:\n        parts.append(f'{datetime.fromtimestamp(mtime).isoformat(timespec=\"seconds\")}  {f}')\n    if dumps:\n        section(f'NEWEST DUMP: {dumps[0][1]}', None, path=dumps[0][1], limit=200000)\n\n    return '\\n'.join(parts)\n\n\ndef upload_diagnostics(server, token, reason='manual'):\n    try:\n        text = collect_diagnostics(reason)\n        r = requests.post(f'{server}/api/pi/diagnostics',\n                          json={'text': text, 'reason': reason},\n                          headers={'X-Pi-Token': token}, timeout=60)\n        if r.status_code == 200:\n            log.info('Diagnostics uploaded (%d kB, reason=%s)', len(text) // 1024, reason)\n            return True\n        log.warning('Diagnostics upload rejected: HTTP %s', r.status_code)\n    except Exception as e:\n        log.warning('Diagnostics upload failed: %s', e)\n    return False\n\n\ndef laptop_status():\n    \"\"\"Battery and lid, when the machine has them.\n\n    A laptop used as an info screen is running on mains with the lid shut. If\n    somebody unplugs it, the screen keeps working until the battery dies and\n    then simply vanishes from the portal with no warning — so report the state\n    while there is still time to do something about it.\n    \"\"\"\n    try:\n        if not os.path.isdir('/sys/class/power_supply'):\n            return None\n        out = {}\n        for name in sorted(os.listdir('/sys/class/power_supply')):\n            base = f'/sys/class/power_supply/{name}'\n            kind = ''\n            try:\n                with open(f'{base}/type') as f:\n                    kind = f.read().strip()\n            except Exception:\n                continue\n            if kind == 'Battery':\n                def rd(attr):\n                    try:\n                        with open(f'{base}/{attr}') as f:\n                            return f.read().strip()\n                    except Exception:\n                        return None\n                cap = rd('capacity')\n                out['battery_percent'] = int(cap) if cap and cap.isdigit() else None\n                out['battery_state'] = rd('status')\n            elif kind == 'Mains':\n                online = None\n                try:\n                    with open(f'{base}/online') as f:\n                        online = f.read().strip() == '1'\n                except Exception:\n                    pass\n                out['on_mains'] = online\n        if os.path.isdir('/proc/acpi/button/lid'):\n            for lid in os.listdir('/proc/acpi/button/lid'):\n                try:\n                    with open(f'/proc/acpi/button/lid/{lid}/state') as f:\n                        out['lid'] = 'closed' if 'closed' in f.read() else 'open'\n                except Exception:\n                    pass\n                break\n        return out or None\n    except Exception:\n        return None\n\n\ndef component_status():\n    \"\"\"What is actually installed on this box, as opposed to what should be.\n\n    Reported to the portal every time the hardware is, so \"cookie banners are\n    still showing\" can be answered by looking rather than by guessing. Two\n    releases in a row shipped these files and failed to install them, and\n    nothing anywhere said so.\n    \"\"\"\n    ext = os.path.join(AGENT_DIR, 'cookie-dismiss')\n    return {\n        'cookie_extension': os.path.isfile(os.path.join(ext, 'manifest.json')),\n        'cookie_extension_version': _ext_version(ext),\n        'lockdown_script': os.path.isfile(HARDEN_BIN)\n                           or os.path.isfile(os.path.join(AGENT_DIR, 'harden-kiosk.sh')),\n        'usbguard': UsbGuard is not None,\n        'usbguard_file': os.path.exists(os.path.join(AGENT_DIR, GUARD_FILE)),\n        'harden_script': os.path.exists(HARDEN_BIN)\n                         or os.path.exists(os.path.join(AGENT_DIR, 'harden-kiosk.sh')),\n        'kiosk_hardened': os.path.exists(os.path.join(STATE_DIR, 'hardening.json')),\n        'chromium_policy': any(os.path.exists(os.path.join(b, N('policies/managed/infoscreen.json')))\n                               for b in ('/etc/chromium', '/etc/chromium-browser', '/etc/opt/chrome')),\n    }\n\n\ndef _ext_version(ext_dir):\n    try:\n        with open(os.path.join(ext_dir, 'manifest.json')) as f:\n            return str(json.load(f).get('version', ''))\n    except Exception:\n        return ''\n\n\ndef ext_fingerprint(ext_dir):\n    \"\"\"SHA-256 over the extension's files, identical to extFingerprint() in\n    routes/pi-api.js. Comparing contents rather than the manifest version means\n    an edit that forgot to bump the version still reaches the screens.\"\"\"\n    import hashlib\n    try:\n        # Same selection as extFiles() in routes/pi-api.js: top-level files,\n        # minus what Chromium generates (names starting with '_').\n        names = sorted(n for n in os.listdir(ext_dir)\n                       if not n.startswith(('_', '.')) and os.path.isfile(os.path.join(ext_dir, n)))\n    except OSError:\n        return ''\n    h = hashlib.sha256()\n    for n in names:\n        h.update(n.encode('utf-8') + b'\\0')\n        with open(os.path.join(ext_dir, n), 'rb') as f:\n            h.update(f.read())\n        h.update(b'\\0')\n    return h.hexdigest()\n\n\ndef _report_ext_sync(server, token, detail):\n    \"\"\"Every extension sync outcome goes to the portal log (event\n    'extension_sync') and the component report is refreshed, so the portal\n    shows the version actually on disk. Until v4.1.3 a failed sync was only\n    in the screen's own log, and the portal kept showing an old version.\"\"\"\n    try:\n        log_event(server, token, 'extension_sync', detail[:400])\n    except Exception:\n        pass\n    try:\n        report_topology(_last_topology or {}, _last_policy_applied)\n    except Exception:\n        pass\n\n\ndef sync_extension(server, token):\n    \"\"\"Install the server's consent extension when this box's copy is missing\n    OR different. Up to v3.9.9 only a *missing* extension was fetched, so a\n    fixed extension never reached a screen that already had an old one.\n\n    The new copy is unpacked beside the old and swapped in with renames. The\n    old directory is often root-owned (install-agent.sh copied it as root) and\n    the agent on a Pi runs as the kiosk user; renaming an entry inside\n    /opt/infoscreen-agent, which the kiosk user owns, works where deleting the\n    root-owned files would not.\n\n    Returns True when the extension on disk changed (the browser must restart\n    to load it).\"\"\"\n    if not server or not token:\n        return False\n    headers = {'X-Pi-Token': token}\n    ext_dir = os.path.join(AGENT_DIR, 'cookie-dismiss')\n    have = os.path.isfile(os.path.join(ext_dir, 'manifest.json'))\n    want = None\n    try:\n        r = requests.get(f'{server}/api/pi/component/cookie-dismiss/version', headers=headers, timeout=15)\n        if r.status_code == 200:\n            want = (r.json() or {}).get('fingerprint') or None\n    except Exception as e:\n        log.debug('extension version check failed: %s', e)\n    if have and (want is None or want == ext_fingerprint(ext_dir)):\n        return False     # up to date, or a server too old to say\n    log.warning('Consent extension %s — fetching it from the server',\n                'missing' if not have else 'outdated')\n    r = requests.get(f'{server}/api/pi/component/cookie-dismiss', headers=headers, timeout=30)\n    if r.status_code != 200 or not r.content:\n        log.warning('Consent extension download failed (HTTP %s)', r.status_code)\n        return False\n    import tarfile, io\n    new_dir, old_dir = ext_dir + '.new', ext_dir + '.old'\n    shutil.rmtree(new_dir, ignore_errors=True)\n    os.makedirs(new_dir, exist_ok=True)\n    with tarfile.open(fileobj=io.BytesIO(r.content), mode='r:gz') as tar:\n        for member in tar.getmembers():\n            # Top-level files only, never flattened: a nested file written by\n            # its basename changed the fingerprint and got every update\n            # rejected (v4.1.3). Never write outside the extension directory.\n            rel = member.name[2:] if member.name.startswith('./') else member.name\n            if not member.isfile() or not rel or '/' in rel or rel.startswith(('_', '.')):\n                continue\n            name = rel\n            src = tar.extractfile(member)\n            if src:\n                with open(os.path.join(new_dir, name), 'wb') as out:\n                    out.write(src.read())\n    if not os.path.isfile(os.path.join(new_dir, 'manifest.json')):\n        log.warning('Downloaded consent extension has no manifest — keeping the current one')\n        shutil.rmtree(new_dir, ignore_errors=True)\n        return False\n    if want and ext_fingerprint(new_dir) != want:\n        got = sorted(os.listdir(new_dir))\n        log.warning('Downloaded consent extension does not match the server fingerprint — keeping the current one (files: %s)', got)\n        _report_ext_sync(server, token, f'failed: fingerprint mismatch after download; files: {\", \".join(got)}')\n        shutil.rmtree(new_dir, ignore_errors=True)\n        return False\n    for root, dirs, files in os.walk(new_dir):\n        for n in files:\n            try: os.chmod(os.path.join(root, n), 0o644)\n            except OSError: pass\n    try: os.chmod(new_dir, 0o755)\n    except OSError: pass\n    shutil.rmtree(old_dir, ignore_errors=True)\n    if os.path.exists(old_dir):                      # root-owned leftovers\n        old_dir = f'{old_dir}-{int(time.time())}'\n    if os.path.exists(ext_dir):\n        os.rename(ext_dir, old_dir)\n    os.rename(new_dir, ext_dir)\n    shutil.rmtree(old_dir, ignore_errors=True)\n    log.info('Consent extension %s installed', _ext_version(ext_dir) or '(unknown version)')\n    _report_ext_sync(server, token, f'ok: installed {_ext_version(ext_dir) or \"?\"}')\n    return True\n\n\ndef extension_sync_loop(server, browser, display):\n    \"\"\"Pick up a new consent extension from the server without a visit or an\n    agent update: update the server, and every screen follows within the\n    interval. The browser is restarted only when something actually changed.\"\"\"\n    time.sleep(60)\n    while True:\n        try:\n            token = load_saved_token() or (_cfg or {}).get('token') or _pi_token\n            if sync_extension(server, token):\n                log_event(server, token, 'extension_updated',\n                          _ext_version(os.path.join(AGENT_DIR, 'cookie-dismiss')))\n                if current_viewer_url:\n                    log.info('Restarting the browser to load the new consent extension')\n                    open_url(current_viewer_url, browser, display)\n        except Exception as e:\n            log.warning('Extension sync failed: %s', e)\n        time.sleep(300)   # one small JSON request; was 30 min\n\n\ndef heal_components(server, token):\n    \"\"\"Fetch anything missing directly from the server.\n\n    An update bundle that stages a file and forgets to install it produces a\n    screen that reports the new version and behaves like the old one. Rather\n    than depend on every future bundle being correct, the agent checks what it\n    has on each start and pulls what it is missing. Nothing here needs a\n    reflash, and nothing needs someone standing at the screen.\n\n    Returns True when something was repaired, so the caller can restart the\n    browser — the consent extension is only read at Chromium launch.\n    \"\"\"\n    if not server or not token:\n        return False\n    repaired = False\n    headers = {'X-Pi-Token': token}\n\n    try:\n        os.makedirs(AGENT_DIR, exist_ok=True)\n\n        # USB guard\n        guard_path = os.path.join(AGENT_DIR, GUARD_FILE)\n        if not os.path.exists(guard_path):\n            log.warning('USB guard missing — fetching it from the server')\n            r = requests.get(component_url(server, 'usbguard'), headers=headers, timeout=30)\n            if r.status_code == 200 and b'UsbGuard' in r.content:\n                with open(guard_path, 'wb') as f:\n                    f.write(r.content)\n                os.chmod(guard_path, 0o755)\n                log.info('USB guard installed (%d bytes) — active after the next restart', len(r.content))\n                repaired = True\n\n        # Consent extension: missing OR outdated\n        if sync_extension(server, token):\n            repaired = True\n\n        # Kiosk lockdown script. Without it infoscreen-harden.service fails on\n        # every boot and the screen runs with no Chromium policy, VT switching\n        # on and the close keys live (v4.1.0). Written where the unit's\n        # fallback path looks; the agent owns that directory, root is not\n        # needed, and the unit runs it as root on the next boot.\n        harden_local = os.path.join(AGENT_DIR, 'harden-kiosk.sh')\n        if not os.path.isfile(HARDEN_BIN) and not os.path.isfile(harden_local):\n            log.warning('Kiosk lockdown script missing — fetching it from the server')\n            r = requests.get(component_url(server, 'harden'), headers=headers, timeout=20)\n            if r.status_code == 200 and r.content.startswith(b'#!'):\n                tmp = harden_local + '.tmp'\n                with open(tmp, 'wb') as f:\n                    f.write(r.content)\n                os.chmod(tmp, 0o755)\n                os.rename(tmp, harden_local)\n                log.info('Kiosk lockdown script installed; it runs as root at the next boot')\n                repaired = True\n    except Exception as e:\n        log.warning('Component repair failed: %s', e)\n\n    return repaired\n\n\n# v4.9.55: one lockdown run at a time. At start-up the agent runs it, and the\n# component sync runs it again when it staged something new; both used to run\n# side by side as root, writing the same files.\n_hardening_lock = threading.Lock()\n\n\ndef run_hardening(server_url):\n    with _hardening_lock:\n        return _run_hardening(server_url)\n\n\ndef _run_hardening(server_url):\n    \"\"\"Run the kiosk lockdown script with the privileges it actually needs.\n\n    v4.9.20 fixes an important false-positive: a non-root Pi could fall through\n    to ``sh /usr/local/bin/infoscreen-harden`` after the sudo helper failed.  The\n    shell then hit permission errors, but this function ignored its return code\n    and logged \"applied\" anyway.  That made the portal believe the privileged\n    image runner had been repaired when it had not.\n    \"\"\"\n    if os.geteuid() != 0:\n        if os.path.isfile(HARDEN_BIN) and priv_helper_ready():\n            r = _run(['sudo', '-n', PRIV_HELPER, 'harden'], timeout=120)\n            if r and r.returncode == 0:\n                log.info('Kiosk hardening applied as root through the helper')\n                return True\n            detail = ''\n            if r:\n                try: detail = (r.stderr or r.stdout or b'').decode('utf-8', 'replace').strip()[-240:]\n                except Exception: detail = ''\n            log.warning('Kiosk hardening through the helper failed (rc=%s)%s',\n                        r.returncode if r else '?', f': {detail}' if detail else '')\n            return False\n        log.warning('Kiosk hardening requires the root helper on this non-root screen')\n        return False\n\n    for candidate in (HARDEN_BIN,\n                      os.path.join(AGENT_DIR, 'harden-kiosk.sh'),\n                      os.path.join(os.path.dirname(os.path.abspath(__file__)), 'kiosk', 'harden-kiosk.sh')):\n        if os.path.exists(candidate):\n            try:\n                r = subprocess.run(['sh', candidate, server_url or ''],\n                                   capture_output=True, timeout=60)\n                if r.returncode == 0:\n                    log.info('Kiosk hardening applied (%s)', candidate)\n                    return True\n                detail = (r.stderr or r.stdout or b'').decode('utf-8', 'replace').strip()[-240:]\n                log.warning('Kiosk hardening failed (%s, rc=%s)%s', candidate, r.returncode,\n                            f': {detail}' if detail else '')\n                return False\n            except Exception as e:\n                log.warning('Kiosk hardening failed: %s', e)\n                return False\n    log.warning('harden-kiosk.sh not found — kiosk is not locked down')\n    return False\n\n# ── Live Display Stream ──────────────────────────────────────────\n# Frames go out on the WebSocket the agent already holds open to the server.\n#\n# The previous version POSTed base64 JPEGs over HTTP twice a second while the\n# portal polled a different endpoint five times a second, and separately offered\n# an MJPEG server on port 7779 that only worked if the server could route\n# directly to the Pi. Two unsynchronised clocks and a routing assumption that\n# does not hold on a segmented network, which is why the live view usually sat\n# on \"waiting for stream\". One socket, frames pushed, no polling.\nimport base64 as _b64\nimport hashlib as _hashlib\n\n_live_stream_active = False   # kept: the HTTP fallback path still uses it\n_last_frame = None            # base64 JPEG string, for the local MJPEG server\n_frame_lock = threading.Lock()\n\n_stream_cfg = {'fps': 20, 'quality': 78, 'width': 1600}\n_stream_on = threading.Event()\n_stream_seq = 0\n_last_frame_hash = None\n\n\ndef capture_frame(quality=50, width=960):\n    \"\"\"Capture the X display as JPEG, return (base64, bytes).\n\n    Speed matters here in a way it did not in the old polling design. The\n    previous path ran scrot to write a full-resolution JPEG to disk, then, if\n    the file was large, ran ImageMagick's convert over it to resize — two\n    processes and two disk round-trips per frame. On a Pi that came out at well\n    under one frame a second with over a second of lag, which is not a live\n    view, it is a slideshow of the past.\n\n    ffmpeg's x11grab does capture, scale and encode in one pass without\n    touching the disk, so it is tried first. The old path stays as a fallback\n    for images that do not ship ffmpeg.\n    \"\"\"\n    env = os.environ.copy()\n    env['DISPLAY'] = env.get('DISPLAY') or ':0'\n    height = int(width * 9 / 16) // 2 * 2      # x11grab wants even dimensions\n    geom = f'{width}x{height}'\n\n    # ffmpeg: one process, straight to stdout, no temp file.\n    if _have_ffmpeg():\n        try:\n            # q:v runs 2 (best) to 31 (worst); our 20-90 quality scale inverts\n            # onto roughly 2-12, which is the useful part of the range.\n            qv = max(2, min(12, int(13 - (quality / 10))))\n            r = subprocess.run(\n                ['ffmpeg', '-loglevel', 'quiet', '-f', 'x11grab',\n                 '-draw_mouse', '0', '-i', env['DISPLAY'],\n                 '-frames:v', '1', '-vf', f'scale={width}:-2',\n                 '-q:v', str(qv), '-f', 'mjpeg', 'pipe:1'],\n                capture_output=True, timeout=6, env=env)\n            if r.returncode == 0 and r.stdout:\n                return _b64.b64encode(r.stdout).decode('ascii'), len(r.stdout)\n        except Exception as e:\n            log.debug('ffmpeg capture failed: %s', e)\n\n    # Fallback: scrot, and only resize when the frame is genuinely too big.\n    try:\n        out = _own_tmp('ps-frame.jpg')\n        r = subprocess.run(['scrot', '-o', '-q', str(quality), out],\n                           capture_output=True, timeout=5, env=env)\n        if r.returncode != 0:\n            subprocess.run(['import', '-window', 'root', '-resize', geom,\n                            '-quality', str(quality), out],\n                           capture_output=True, timeout=5, env=env)\n        elif os.path.exists(out) and os.path.getsize(out) > 160000:\n            subprocess.run(['convert', out, '-resize', geom, '-quality', str(quality), out],\n                           capture_output=True, timeout=5)\n        if os.path.exists(out):\n            with open(out, 'rb') as f:\n                raw = f.read()\n            return _b64.b64encode(raw).decode('ascii'), len(raw)\n    except Exception as e:\n        log.debug('Frame capture failed: %s', e)\n    return None, 0\n\n\n_ffmpeg_checked = None\ndef _have_ffmpeg():\n    global _ffmpeg_checked\n    if _ffmpeg_checked is None:\n        _ffmpeg_checked = shutil.which('ffmpeg') is not None\n        log.info('Live view capture backend: %s',\n                 'ffmpeg x11grab' if _ffmpeg_checked else 'scrot (slower)')\n    return _ffmpeg_checked\n\n\ndef set_stream(active, fps=None, quality=None, width=None):\n    \"\"\"Turn capture on or off. Driven by whether anyone is actually watching.\"\"\"\n    global _stream_cfg\n    if fps:     _stream_cfg['fps'] = max(1, min(60, int(fps)))\n    if quality: _stream_cfg['quality'] = max(20, min(95, int(quality)))\n    if width:   _stream_cfg['width'] = max(320, min(1920, int(width)))\n    if active:\n        if not _stream_on.is_set():\n            log.info('Live view: streaming at %(fps)s fps, q%(quality)s, %(width)spx', _stream_cfg)\n        _stream_on.set()\n    else:\n        if _stream_on.is_set():\n            log.info('Live view: nobody watching, capture stopped')\n        _stream_on.clear()\n\n\ndef _live_capture_budget(cfg, gpu_accelerated):\n    # A JPEG capture of 1920x1080 at 60 fps can monopolize an old Pi / Wyse\n    # even though its capture subprocess is niced. Limit preview cost only on\n    # software-composited machines; leave modern GPU machines unrestricted.\n    cfg = dict(cfg)\n    if not gpu_accelerated:\n        cfg['fps'] = min(cfg['fps'], 12)\n        cfg['width'] = min(cfg['width'], 960)\n        cfg['quality'] = min(cfg['quality'], 75)\n    return cfg\n\n\ndef _screen_stream_process(cfg):\n    \"\"\"One long-running capture/scale/encode pipeline, not one ffmpeg per frame.\n\n    image2pipe emits concatenated JPEGs. Its stdout is read in small available\n    chunks, never through BufferedReader.read(N), which waits to fill N bytes\n    and can add multiple frames of latency. Runs at a lower CPU priority so\n    the real screen's browser and video decoder win under contention.\n    \"\"\"\n    if not _have_ffmpeg():\n        return None\n    env = os.environ.copy()\n    env['DISPLAY'] = env.get('DISPLAY') or ':0'\n    width = cfg['width']\n    q = max(2, min(14, int(15 - cfg['quality'] / 8)))\n    cmd = ['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-filter_threads', '1', '-threads', '1',\n           '-f', 'x11grab', '-draw_mouse', '0',\n           '-framerate', str(cfg['fps']), '-i', env['DISPLAY'],\n           '-vf', f'scale=w=min({width}\\\\,iw):h=-2:flags=fast_bilinear',\n           '-c:v', 'mjpeg', '-q:v', str(q), '-f', 'image2pipe',\n           '-flush_packets', '1', 'pipe:1']\n    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,\n                            stdin=subprocess.DEVNULL, env=env, bufsize=0)\n    try: os.setpriority(os.PRIO_PROCESS, proc.pid, 15)\n    except (AttributeError, PermissionError, OSError): pass\n    return proc\n\n\ndef _screen_jpegs(proc, stop_requested):\n    \"\"\"Yield complete JPEGs as soon as available, bounded against bad output.\"\"\"\n    import select\n    buf = bytearray()\n    while proc.poll() is None and not stop_requested():\n        try:\n            if not select.select([proc.stdout], [], [], 0.4)[0]:\n                continue\n            data = os.read(proc.stdout.fileno(), 65536)\n        except (OSError, ValueError):\n            break\n        if not data:\n            break\n        buf.extend(data)\n        while True:\n            start = buf.find(b'\\xff\\xd8')\n            if start < 0:\n                # The 0xff from SOI may be the final byte of this chunk.\n                # Keep it so the next read can complete the marker.\n                last = buf[-1:] if buf and buf[-1] == 0xff else b''\n                buf.clear(); buf.extend(last)\n                break\n            if start:\n                del buf[:start]\n            end = buf.find(b'\\xff\\xd9', 2)\n            if end < 0:\n                break\n            end += 2\n            raw = bytes(buf[:end])\n            del buf[:end]\n            yield raw\n        if len(buf) > 8 * 1024 * 1024:\n            buf.clear()\n\n\ndef _ws_send_screen_frame(jpeg, captured, seq):\n    \"\"\"Compact, versioned binary frame. Other WebSocket traffic stays JSON.\n\n    Header: magic ISF1, unsigned big-endian captured_ms (64), seq (32),\n    jpeg length (32). The server appends its relay timestamp for the browser.\n    \"\"\"\n    if not _ws_is_up():\n        return False\n    try:\n        import websocket, struct\n        header = struct.pack('!4sQII', b'ISF1', max(0, int(captured * 1000)),\n                             seq & 0xffffffff, len(jpeg))\n        _ws_conn.send(header + jpeg, opcode=websocket.ABNF.OPCODE_BINARY)\n        return True\n    except Exception as e:\n        log.debug('binary screen frame send failed: %s', e)\n        return False\n\n\ndef screen_stream_loop():\n    \"\"\"Continuous live capture with zero frame queue and a safe old fallback.\n\n    A worker belongs only to the period it is watched. Configuration changes\n    restart ffmpeg at the new rate/quality without restarting the agent.\n    Only changed frames are transmitted, plus one frame every two seconds.\n    \"\"\"\n    global _stream_seq, _last_frame_hash, _last_frame\n    last_keyframe = 0.0\n    last_fail = 0.0\n    while True:\n        if not _stream_on.wait(timeout=2):\n            _last_frame_hash = None\n            continue\n        if not _ws_is_up():\n            time.sleep(0.25)\n            continue\n        requested_cfg = dict(_stream_cfg)\n        cfg = _live_capture_budget(requested_cfg, bool(globals().get('_launch', {}).get('gpu', False)))\n        proc = None\n        if time.monotonic() - last_fail >= 3:\n            try:\n                proc = _screen_stream_process(cfg)\n            except Exception as e:\n                log.warning('Live view continuous capture unavailable: %s', e)\n                last_fail = time.monotonic()\n        if proc is not None:\n            log.info('Live view continuous capture: %sfps quality=%s width=%s',\n                     cfg['fps'], cfg['quality'], cfg['width'])\n            count = 0\n            import queue\n            latest = queue.Queue(maxsize=1)\n            reader_done = threading.Event()\n            def stopping():\n                return not _stream_on.is_set() or requested_cfg != _stream_cfg or not _ws_is_up()\n            def drain_capture():\n                try:\n                    for raw in _screen_jpegs(proc, stopping):\n                        if stopping(): break\n                        # Reader never waits for network IO. Keep one JPEG,\n                        # replacing stale captures while a send is in flight.\n                        item = (time.time(), raw)\n                        try: latest.put_nowait(item)\n                        except queue.Full:\n                            try: latest.get_nowait()\n                            except queue.Empty: pass\n                            try: latest.put_nowait(item)\n                            except queue.Full: pass\n                finally:\n                    reader_done.set()\n            threading.Thread(target=drain_capture, daemon=True).start()\n            try:\n                while not stopping() and not (reader_done.is_set() and latest.empty()):\n                    try: captured, raw = latest.get(timeout=0.3)\n                    except queue.Empty: continue\n                    # Discard any older capture accumulated during a send.\n                    while True:\n                        try: captured, raw = latest.get_nowait()\n                        except queue.Empty: break\n                    digest = _hashlib.md5(raw).digest()\n                    if digest == _last_frame_hash and captured - last_keyframe < 2:\n                        continue\n                    _last_frame_hash = digest\n                    last_keyframe = captured\n                    _stream_seq += 1\n                    if not _ws_send_screen_frame(raw, captured, _stream_seq):\n                        break\n                    count += 1\n                    if count % 10 == 1:\n                        with _frame_lock:\n                            _last_frame = _b64.b64encode(raw).decode('ascii')\n            finally:\n                try: proc.terminate(); proc.wait(timeout=2)\n                except Exception:\n                    try: proc.kill(); proc.wait(timeout=1)\n                    except Exception: pass\n                try: proc.stdout.close()\n                except Exception: pass\n            if count == 0 and _stream_on.is_set():\n                last_fail = time.monotonic()\n            _last_frame_hash = None\n            continue\n\n        # Old images without FFmpeg or broken x11grab still get images, just\n        # not continuous video. Never run both capture pipelines together.\n        started = time.time()\n        b64, nbytes = capture_frame(cfg['quality'], cfg['width'])\n        if b64 and _stream_on.is_set() and _ws_is_up():\n            with _frame_lock:\n                _last_frame = b64\n            digest = _hashlib.md5(b64.encode('ascii')).digest()\n            if digest != _last_frame_hash or (started - last_keyframe) > 2:\n                _last_frame_hash = digest\n                last_keyframe = started\n                _stream_seq += 1\n                ws_send({'type': 'screen_frame', 'data': b64,\n                         'captured_at': int(started * 1000),\n                         'seq': _stream_seq, 'bytes': nbytes})\n        time.sleep(max(0.05, (1.0 / cfg['fps']) - (time.time() - started)))\n\n\ndef live_stream_loop(server, token):\n    \"\"\"HTTP fallback, for the case where the WebSocket cannot be established.\n\n    Kept because some sites block WebSocket upgrades outright, and a degraded\n    live view beats none. Only runs when the socket is down.\n    \"\"\"\n    global _live_stream_active, _last_frame\n    while True:\n        if _live_stream_active and not _ws_is_up():\n            b64, _ = capture_frame(50, 960)\n            if b64:\n                with _frame_lock:\n                    _last_frame = b64\n                try:\n                    requests.post(f'{server}/api/pi/live-frame',\n                                  json={'frame': b64},\n                                  headers={'X-Pi-Token': token}, timeout=5)\n                except Exception:\n                    pass\n            time.sleep(0.5)\n        else:\n            time.sleep(2)\n\n# ── Media Cache ──────────────────────────────────────────────────\n# Pre-downloads videos from the server and serves them locally.\n# Prefers /dev/shm (RAM) if enough space, falls back to /var/cache/infoscreen.\nimport shutil\nfrom datetime import datetime\nimport re, hashlib\n\nCACHE_RAM = '/dev/shm/infoscreen-cache'\nCACHE_DISK = N('/var/cache/infoscreen')\nVIDEO_EXTS = ('.mp4', '.webm', '.mov', '.avi')\n_cached_files = {}  # url_path -> local_path (only complete, verified files)\n# One sync at a time. Every config message used to start its own thread per\n# slideshow: two threads wrote the same file at once (a corrupt video that then\n# counted as cached), and each thread's clean-up deleted the videos of every\n# OTHER slideshow in the rotation, because it only knew about its own.\n_cache_lock = threading.Lock()\n_cache_pending = [None]   # latest rotation waiting to be synced\n\ndef _free_bytes(path):\n    try: return shutil.disk_usage(path).free\n    except Exception: return 0\n\ndef _cache_dir_for(size):\n    \"\"\"RAM if the file fits with 150 MB to spare, else disk.\n\n    The old rule was \"RAM if 100 MB is free\", whatever the size of the video:\n    a large file could fill /dev/shm (half the Pi's RAM) and take Chromium down\n    with it.\n    \"\"\"\n    if size and _free_bytes('/dev/shm') > size + 150 * 1024 * 1024:\n        os.makedirs(CACHE_RAM, exist_ok=True)\n        return CACHE_RAM\n    os.makedirs(CACHE_DISK, exist_ok=True)\n    return CACHE_DISK\n\ndef _video_paths(rotation, profile='smooth'):\n    out = []\n    for item in rotation or []:\n        if item.get('type') != 'slideshow':\n            continue\n        for slide in item.get('slides') or []:\n            # Config handler already chose the device's source in src. Do not\n            # silently override that choice with smooth_src here: previously\n            # quality PCs cached the 720p file instead of their 1080p master.\n            src = slide.get('src', '') if isinstance(slide, dict) else slide\n            candidates = [src]\n            if isinstance(slide, dict):\n                candidates.extend(slide.get('cache_alternates') or [])\n            for candidate in candidates:\n                if candidate and candidate.lower().endswith(VIDEO_EXTS) and candidate not in out:\n                    out.append(candidate)\n    return out\n\ndef request_cache_sync(server, token, rotation, profile='smooth'):\n    \"\"\"Queue a cache sync for the whole rotation; coalesces bursts.\"\"\"\n    _cache_pending[0] = (server, token, rotation, profile)\n    if _cache_lock.locked():\n        return   # the running sync picks up the newest rotation when it finishes\n    threading.Thread(target=_cache_worker, daemon=True).start()\n\ndef _cache_worker():\n    if not _cache_lock.acquire(blocking=False):\n        return\n    try:\n        while _cache_pending[0] is not None:\n            job, _cache_pending[0] = _cache_pending[0], None\n            try:\n                cache_media(*job)\n            except Exception as e:\n                log.warning('Media cache sync failed: %s', e)\n    finally:\n        _cache_lock.release()\n\ndef cache_media(server, token, rotation, profile='smooth'):\n    \"\"\"Download every video in the rotation and serve it locally (port 7779).\n\n    Files are written to <name>.part and renamed only once the byte count\n    matches Content-Length, so the viewer can never be handed a half-written\n    or truncated file.\n    \"\"\"\n    global _cached_files\n    wanted = _video_paths(rotation, profile)\n    new_cached = {}\n\n    for url_path in wanted:\n        name = hashlib.md5(url_path.encode()).hexdigest() + os.path.splitext(url_path)[1].lower()\n        known = _cached_files.get(url_path)\n        if known and os.path.exists(known):\n            new_cached[url_path] = known\n            continue\n        try:\n            full_url = f'{server}{url_path}'\n            r = requests.get(full_url, headers={'X-Pi-Token': token}, timeout=(15, 120), stream=True)\n            if r.status_code != 200:\n                log.warning('Cache download failed for %s: HTTP %d', url_path, r.status_code)\n                r.close(); continue\n            expected = int(r.headers.get('Content-Length') or 0)\n            cache_dir = _cache_dir_for(expected)\n            local_path = os.path.join(cache_dir, name)\n            # Survives an agent restart: same name, same size -> keep it.\n            reuse = next((os.path.join(d, name) for d in (CACHE_RAM, CACHE_DISK)\n                          if expected and os.path.isfile(os.path.join(d, name))\n                          and os.path.getsize(os.path.join(d, name)) == expected), None)\n            if reuse:\n                r.close()\n                new_cached[url_path] = reuse\n                _cached_files[url_path] = reuse\n                continue\n            if expected and _free_bytes(cache_dir) < expected + 50 * 1024 * 1024:\n                log.warning('Not caching %s: not enough space in %s', url_path, cache_dir)\n                r.close(); continue\n            log.info('Caching video: %s -> %s', url_path, local_path)\n            part = local_path + '.part'\n            got = 0\n            with open(part, 'wb') as f:\n                for chunk in r.iter_content(chunk_size=256 * 1024):\n                    if chunk:\n                        f.write(chunk); got += len(chunk)\n            if expected and got != expected:\n                log.warning('Cache download truncated for %s (%d of %d bytes) — discarded',\n                            url_path, got, expected)\n                try: os.remove(part)\n                except OSError: pass\n                continue\n            os.replace(part, local_path)\n            new_cached[url_path] = local_path\n            # Visible to the viewer as soon as it is complete, not after the\n            # whole batch.\n            _cached_files[url_path] = local_path\n            log.info('Cached: %s (%.1f MB, %s)', url_path, got / (1024 * 1024),\n                     'RAM' if local_path.startswith(CACHE_RAM) else 'disk')\n        except Exception as e:\n            log.warning('Cache download error for %s: %s', url_path, e)\n\n    # Remove what the rotation no longer uses. A file the viewer still has\n    # open keeps playing (Linux keeps the inode until it is closed).\n    # This also sweeps .part leftovers and files from a previous agent run;\n    # the lock guarantees no download is in progress while it does.\n    _cached_files = new_cached\n    keep = set(new_cached.values())\n    for d in (CACHE_RAM, CACHE_DISK):\n        try:\n            for fn in os.listdir(d):\n                fp = os.path.join(d, fn)\n                if fp not in keep:\n                    try: os.remove(fp)\n                    except OSError: pass\n        except OSError:\n            pass\n    if new_cached:\n        log.info('Media cache: %d video(s) ready', len(new_cached))\n_force_heartbeat = False\n\n# Cached apt update count — refreshed every 6 hours\n_apt_updates = {'count': 0, 'reboot_required': False, 'last_check': 0}\n_apt_upgrade_lock = threading.Lock()  # v4.9.7: never start two apt upgrades at once\n_cfg = {}  # populated in main() — server/token for background threads\n\ndef _is_alpine():\n    return os.path.exists('/etc/alpine-release')\n\n\n# The portal's terminal on an Alpine laptop is BusyBox ash, as root, where\n# neither `sudo` nor `apt` exists: \"sudo apt full-upgrade -y\" answered\n# \"sudo: not found\" (v4.6.0). This rc file (ash reads $ENV) makes the usual\n# commands do the right thing and gives the shell a real prompt.\n_TERMINAL_RC = r\"\"\"# InfoScreen terminal (v4.6.0). This machine runs Alpine Linux: you are root,\n# and packages come from apk, not apt.\nPS1='\\[\\e[1;32m\\]\\u@\\h\\[\\e[0m\\]:\\[\\e[1;34m\\]\\w\\[\\e[0m\\] \\$ '\nsudo() {\n  while [ $# -gt 0 ] && [ \"${1#-}\" != \"$1\" ]; do shift; done\n  \"$@\"\n}\napt() {\n  _c=\"$1\"; [ $# -gt 0 ] && shift\n  _p=\"\"; for _a in \"$@\"; do case \"$_a\" in -*) ;; *) _p=\"$_p $_a\" ;; esac; done\n  case \"$_c\" in\n    update) apk update ;;\n    upgrade|full-upgrade|dist-upgrade) apk update && apk upgrade ;;\n    install) apk add $_p ;;\n    remove|purge) apk del $_p ;;\n    autoremove|autoclean|clean) echo \"apk rydder selv. Ingenting å gjøre.\" ;;\n    search) apk search $_p ;;\n    list) apk list --installed ;;\n    show|policy) apk info -a $_p ;;\n    *) echo \"Denne maskinen bruker Alpine Linux. Bruk apk: apk update, apk upgrade, apk add, apk del.\"; return 1 ;;\n  esac\n}\nalias apt-get=apt\necho \"Alpine Linux, innlogget som root. «sudo» og «apt» oversettes til apk.\"\n\"\"\"\n\ndef _terminal_rc():\n    for d in (AGENT_DIR, '/tmp'):\n        p = os.path.join(d, 'terminal-rc.sh')\n        try:\n            with open(p, 'w') as f:\n                f.write(_TERMINAL_RC)\n            return p\n        except Exception:\n            continue\n    return None\n\n\ndef _platform_command(name, argv):\n    \"\"\"A named maintenance command, the way this OS does it (v4.6.0).\"\"\"\n    if _is_alpine():\n        argv = {\n            'reboot': ['reboot'], 'shutdown': ['poweroff'],\n            'restart-agent': ['sh', '-c', f'sleep 2; kill -TERM {os.getpid()}'],\n            'restart-chromium': ['sh', '-c', 'pkill -f chromium || pkill -f chrome || true'],\n            'restart-browser': ['sh', '-c', 'pkill -f chromium || pkill -f chrome || true'],\n            'apt-update': ['apk', 'update'], 'apt-upgrade': ['apk', 'upgrade'],\n            'service-status': ['sh', '-c', 'rc-status 2>/dev/null; pgrep -fa \"screen-|chromium\" || true'],\n            'journal-agent': ['sh', '-c', f'tail -n 50 /var/log/infoscreen-agent.log 2>/dev/null || tail -n 50 /var/log/{LEGACY}-agent.log 2>/dev/null || tail -n 50 /var/log/messages'],\n            'journal-browser': ['sh', '-c', 'tail -n 50 /var/log/messages'],\n        }.get(name, argv)\n    if os.geteuid() == 0 and argv and argv[0] == 'sudo':\n        argv = argv[1:]\n    return argv\n\n\ndef check_apt_updates():\n    \"\"\"Run apt update + count available upgrades. Cached for 6h.\"\"\"\n    global _apt_updates\n    now = time.time()\n    if now - _apt_updates['last_check'] < 21600:  # 6 hours\n        return _apt_updates['count']\n    if _is_alpine():                            # v4.6.0: apk, not apt\n        try:\n            subprocess.run(['apk', 'update', '-q'], capture_output=True, text=True, timeout=300)\n            r = subprocess.run(['apk', 'version', '-l', '<'], capture_output=True, text=True, timeout=60)\n            count = sum(1 for l in r.stdout.splitlines() if '<' in l)\n            _apt_updates = {'count': count, 'reboot_required': False, 'last_check': now}\n            return count\n        except Exception as e:\n            log.warning('apk check failed: %s', e)\n            return _apt_updates['count']\n    try:\n        # Refresh package lists first\n        subprocess.run(['sudo', 'apt-get', 'update', '-qq'],\n            capture_output=True, text=True, timeout=120)\n        r = subprocess.run(['apt-get', '-s', 'dist-upgrade'],\n            capture_output=True, text=True, timeout=30)\n        count = sum(1 for l in r.stdout.splitlines()\n                    if l.startswith('Inst '))\n        reboot = os.path.exists('/var/run/reboot-required')\n        _apt_updates = {'count': count, 'reboot_required': reboot, 'last_check': now}\n        if count or reboot:\n            log.info('APT updates available: %d, reboot required: %s', count, reboot)\n        return count\n    except Exception as e:\n        log.warning('apt check failed: %s', e)\n        return _apt_updates['count']\n\ndef run_apt_upgrade(callback=None):\n    \"\"\"Run apt update + dist-upgrade in background with reliable progress reporting.\"\"\"\n    # Multiple delivery paths may legitimately repeat a request until the agent\n    # confirms receipt. Keep one updater per process, and also take an OS-level\n    # flock so a second agent process cannot start another apt/dpkg transaction.\n    if not _apt_upgrade_lock.acquire(blocking=False):\n        server = _cfg.get('server', '')\n        token = _cfg.get('token', '')\n        log.info('APT upgrade requested while one is already running — ignoring duplicate')\n        log_event(server, token, 'apt_upgrade_progress', 'En OS-oppdatering kjører allerede', retries=2)\n        return False\n\n    file_lock = None\n    try:\n        import fcntl\n        file_lock = open(_own_tmp('infoscreen-apt-upgrade.lock'), 'a+')\n        try:\n            fcntl.flock(file_lock.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)\n        except BlockingIOError:\n            _apt_upgrade_lock.release()\n            server = _cfg.get('server', '')\n            token = _cfg.get('token', '')\n            log.info('Another InfoScreen process already owns the APT lock')\n            log_event(server, token, 'apt_upgrade_progress', 'En OS-oppdatering kjører allerede i en annen agentprosess', retries=2)\n            file_lock.close()\n            return False\n    except Exception as e:\n        log.warning('Could not create cross-process APT lock: %s', e)\n        file_lock = None\n\n    server = _cfg.get('server', '')\n    token = _cfg.get('token', '')\n    # This is the delivery acknowledgement. The server deliberately keeps the\n    # command pending until this event arrives, so a lost heartbeat response no\n    # longer makes the OS-update command disappear.\n    log_event(server, token, 'apt_upgrade_received', f'Kommando mottatt av agent {AGENT_VERSION}', retries=3)\n\n    def _run():\n        apt = shutil.which('apt-get') or '/usr/bin/apt-get'\n        apt_common = ['-o', 'DPkg::Lock::Timeout=120', '-o', 'Acquire::Retries=3']\n        try:\n            if _is_alpine():                    # v4.6.0: apk, not apt\n                log_event(server, token, 'apt_update_start', 'Oppdaterer pakkelister (apk)...', retries=2)\n                r = subprocess.run(['apk', 'update'], capture_output=True, text=True, timeout=300)\n                if r.returncode != 0:\n                    log_event(server, token, 'apt_update_failed', (r.stderr or r.stdout or '').strip()[-400:], retries=3)\n                    if callback: callback(False)\n                    return\n                log_event(server, token, 'apt_update_done', 'Pakkelister oppdatert', retries=2)\n                pend = subprocess.run(['apk', 'version', '-l', '<'], capture_output=True, text=True, timeout=60)\n                pk = [l.split()[0] for l in pend.stdout.splitlines() if '<' in l]\n                log_event(server, token, 'apt_upgrade_start', f'{len(pk)} pakker å oppgradere: {\", \".join(pk[:15])}', retries=2)\n                r = subprocess.run(['apk', 'upgrade', '--no-progress'], capture_output=True, text=True, timeout=7200)\n                ok = r.returncode == 0\n                log_event(server, token, 'apt_upgrade_done' if ok else 'apt_upgrade_failed',\n                          'Ferdig' if ok else (r.stderr or r.stdout or '').strip()[-400:], retries=3)\n                if ok:\n                    _apt_updates['count'] = 0\n                _apt_updates['last_check'] = time.time()\n                if callback: callback(ok)\n                return\n\n            # Phase 1: apt update. sudo -n guarantees that a broken sudoers\n            # configuration fails visibly rather than waiting for a password no\n            # one can type on a kiosk.\n            log.info('Running apt update...')\n            log_event(server, token, 'apt_update_start', 'Oppdaterer pakkelister...', retries=2)\n            r_upd = subprocess.run(['sudo', '-n', apt, 'update', '-qq', *apt_common],\n                capture_output=True, text=True, timeout=300, stdin=subprocess.DEVNULL)\n            if r_upd.returncode != 0:\n                err = (r_upd.stderr or r_upd.stdout or '').strip()[-400:]\n                log.error('apt update failed: %s', err)\n                log_event(server, token, 'apt_update_failed', err or f'apt update avsluttet med kode {r_upd.returncode}', retries=3)\n                _apt_updates['last_check'] = 0\n                if callback: callback(False)\n                return\n            log_event(server, token, 'apt_update_done', 'Pakkelister oppdatert', retries=2)\n\n            # Phase 2: count what will be upgraded\n            sim = subprocess.run([apt, '-s', 'dist-upgrade'], capture_output=True, text=True, timeout=60)\n            packages = [l.split()[1] for l in sim.stdout.splitlines() if l.startswith('Inst ')]\n            total = len(packages)\n            log.info('%d packages to upgrade', total)\n            log_event(server, token, 'apt_upgrade_start',\n                f'{total} pakke{\"r\" if total != 1 else \"\"} å oppgradere: {\", \".join(packages[:15])}{\"...\" if total > 15 else \"\"}', retries=2)\n\n            if total == 0:\n                log_event(server, token, 'apt_upgrade_done', 'Allerede oppdatert', retries=3)\n                _apt_updates['count'] = 0\n                _apt_updates['last_check'] = time.time()\n                if callback: callback(True)\n                return\n\n            # Phase 3: run the actual upgrade. We do not block forever waiting\n            # for one output line. Every minute a progress heartbeat is posted,\n            # and a hard two-hour ceiling turns a genuinely hung apt process\n            # into an explicit failure instead of \"Ingen svar\".\n            log.info('Running apt dist-upgrade...')\n            env = os.environ.copy()\n            env['DEBIAN_FRONTEND'] = 'noninteractive'\n            env['NEEDRESTART_MODE'] = 'a'\n            proc = subprocess.Popen(\n                ['sudo', '-n', apt, 'dist-upgrade', '-y', *apt_common,\n                 '-o', 'Dpkg::Options::=--force-confdef',\n                 '-o', 'Dpkg::Options::=--force-confold',\n                 '-o', 'APT::Status-Fd=1'],\n                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,\n                stdin=subprocess.DEVNULL, text=True, bufsize=1, env=env, start_new_session=True)\n\n            import select\n            from collections import deque\n            installed_count = 0\n            last_report = time.time()\n            started = time.time()\n            tail = deque(maxlen=30)\n\n            while True:\n                if time.time() - started > 2 * 60 * 60:\n                    log.error('apt dist-upgrade exceeded two hours — terminating')\n                    try: os.killpg(proc.pid, signal.SIGTERM)\n                    except Exception:\n                        try: proc.terminate()\n                        except Exception: pass\n                    try: proc.wait(timeout=20)\n                    except Exception:\n                        try: os.killpg(proc.pid, signal.SIGKILL)\n                        except Exception:\n                            try: proc.kill()\n                            except Exception: pass\n                    log_event(server, token, 'apt_upgrade_failed', 'APT brukte mer enn 2 timer og ble stoppet', retries=3)\n                    _apt_updates['last_check'] = 0\n                    if callback: callback(False)\n                    return\n\n                ready = []\n                if proc.stdout is not None:\n                    try: ready, _, _ = select.select([proc.stdout], [], [], 5)\n                    except Exception: ready = []\n                if ready:\n                    line = proc.stdout.readline()\n                    if line:\n                        line = line.strip()\n                        if line:\n                            tail.append(line)\n                            if line.startswith('pmstatus:'):\n                                parts = line.split(':', 3)\n                                if len(parts) >= 4:\n                                    pkg, pct, msg = parts[1], parts[2], parts[3]\n                                    now = time.time()\n                                    if 'Installed' in msg or 'Configuring' in msg or now - last_report > 10:\n                                        if 'Installed' in msg:\n                                            installed_count += 1\n                                        log_event(server, token, 'apt_upgrade_progress',\n                                            f'[{installed_count}/{total}] {pkg}: {msg}')\n                                        last_report = now\n                            elif line.startswith('E:') or line.startswith('Err:'):\n                                log_event(server, token, 'apt_upgrade_error', line[:300])\n\n                now = time.time()\n                if now - last_report >= 60:\n                    log_event(server, token, 'apt_upgrade_progress',\n                              f'APT kjører fortsatt ({installed_count}/{total} pakker registrert)', retries=2)\n                    last_report = now\n\n                if proc.poll() is not None:\n                    # Drain any last buffered lines so an error ends up in the\n                    # failure detail even when it arrived just before exit.\n                    if proc.stdout is not None:\n                        try:\n                            for line in proc.stdout.readlines():\n                                line = line.strip()\n                                if line: tail.append(line)\n                        except Exception:\n                            pass\n                    break\n\n            if proc.returncode != 0:\n                detail = ' | '.join(list(tail)[-5:])[-900:] or f'apt avsluttet med kode {proc.returncode}'\n                log.error('apt upgrade exited with code %d: %s', proc.returncode, detail)\n                log_event(server, token, 'apt_upgrade_failed', detail, retries=3)\n                _apt_updates['last_check'] = 0\n                if callback: callback(False)\n                return\n\n            # Phase 4: recount remaining updates\n            log.info('APT upgrade complete — rechecking...')\n            r = subprocess.run([apt, '-s', 'dist-upgrade'], capture_output=True, text=True, timeout=60)\n            remaining = sum(1 for l in r.stdout.splitlines() if l.startswith('Inst '))\n            reboot = os.path.exists('/var/run/reboot-required')\n            _apt_updates['count'] = remaining\n            _apt_updates['reboot_required'] = reboot\n            _apt_updates['last_check'] = time.time()\n            log.info('Remaining updates: %d, reboot required: %s', remaining, reboot)\n\n            summary = f'Oppgraderte {total - remaining} av {total} pakker'\n            if remaining > 0:\n                summary += f', {remaining} gjenstår'\n            if reboot:\n                summary += ' — OMSTART KREVES'\n            log_event(server, token, 'apt_upgrade_done', summary, retries=3)\n            if callback: callback(True)\n        except Exception as e:\n            log.exception('APT upgrade failed')\n            log_event(server, token, 'apt_upgrade_failed', str(e)[:900], retries=3)\n            _apt_updates['last_check'] = 0\n            if callback: callback(False)\n        finally:\n            if file_lock is not None:\n                try:\n                    import fcntl\n                    fcntl.flock(file_lock.fileno(), fcntl.LOCK_UN)\n                    file_lock.close()\n                except Exception:\n                    pass\n            _apt_upgrade_lock.release()\n    threading.Thread(target=_run, daemon=True).start()\n    return True\n\ndef open_reverse_terminal(server, token):\n    \"\"\"Open an HTTP-based terminal relay — no WebSocket needed, works through Cloudflare.\"\"\"\n    import pty as pty_mod, select, struct, fcntl, termios\n\n    log.info('Starting HTTP terminal relay...')\n    headers = {'X-Pi-Token': token, 'Content-Type': 'application/json'}\n\n    # Announce to server\n    try:\n        r = requests.post(f'{server}/api/pi/terminal/connect', headers=headers, timeout=10)\n        data = r.json()\n        if not data.get('ok'):\n            log.info('No pending terminal session')\n            return\n        session_id = data['sessionId']\n        rows = data.get('rows', 24)\n        cols = data.get('cols', 80)\n        log.info('Terminal session %s, %dx%d', session_id, cols, rows)\n    except Exception as e:\n        log.error('Terminal connect failed: %s', e)\n        return\n\n    # Spawn PTY\n    pid, fd = pty_mod.fork()\n    if pid == 0:\n        os.environ['TERM'] = 'xterm-256color'\n        os.execvp('/bin/bash', ['/bin/bash', '-l'])\n\n    # Parent — set window size\n    winsize = struct.pack('HHHH', rows, cols, 0, 0)\n    fcntl.ioctl(fd, termios.TIOCSWINSZ, winsize)\n    log.info('PTY spawned for HTTP relay, pid=%d', pid)\n\n    # Reader thread — sends PTY output to server via HTTP POST\n    def read_and_send():\n        try:\n            while True:\n                r, _, _ = select.select([fd], [], [], 0.1)\n                if fd in r:\n                    data = os.read(fd, 4096)\n                    if not data:\n                        break\n                    try:\n                        requests.post(f'{server}/api/pi/terminal/output',\n                            json={'sessionId': session_id, 'data': data.decode('utf-8', errors='replace')},\n                            headers=headers, timeout=5)\n                    except: pass\n        except (OSError, ValueError):\n            pass\n        log.info('PTY read loop ended')\n\n    reader = threading.Thread(target=read_and_send, daemon=True)\n    reader.start()\n\n    # Main loop — poll server for input\n    try:\n        while True:\n            try:\n                r = requests.get(f'{server}/api/pi/terminal/input',\n                    params={'sessionId': session_id}, headers=headers, timeout=10)\n                resp = r.json()\n                if resp.get('closed'):\n                    log.info('Terminal session closed by server')\n                    break\n                if resp.get('input'):\n                    os.write(fd, resp['input'].encode('utf-8'))\n                if resp.get('resize'):\n                    rs = resp['resize']\n                    winsize = struct.pack('HHHH', rs.get('rows',24), rs.get('cols',80), 0, 0)\n                    fcntl.ioctl(fd, termios.TIOCSWINSZ, winsize)\n            except Exception as e:\n                log.debug('Terminal poll error: %s', e)\n            time.sleep(0.08)  # ~12/second for snappy echo\n    except Exception as e:\n        log.error('Terminal relay error: %s', e)\n    finally:\n        try: os.close(fd)\n        except: pass\n        try: os.kill(pid, 9)\n        except: pass\n        try: os.waitpid(pid, os.WNOHANG)\n        except: pass\n        log.info('HTTP terminal relay ended')\n\n# ── Networks on the laptops (Alpine), v4.9.3 ─────────────────────────\n# Cable first, then the WiFi networks in the order set in the portal (lower\n# number first). Agents before 4.9.3 asked systemd whether NetworkManager\n# ran; Alpine has neither, so a WiFi profile pushed to a laptop was never\n# applied. Now the profiles go into wpa_supplicant's own file (the key is\n# derived from the password, as WPA does, so the file never holds the\n# password), wpa_supplicant and the WiFi interface start at boot, and\n# net_failover_loop keeps the cable first: a cable without link loses its\n# default route at once so WiFi takes over, and wins again when plugged in.\n_EV = {'server': None, 'token': None}\n_IS_ALPINE = os.path.exists('/etc/alpine-release')\nWPA_CONF = '/etc/wpa_supplicant/wpa_supplicant.conf'\n_NET_ROOT = ''          # tests point this at a temporary folder\n_P = lambda path: _NET_ROOT + path\n\ndef _report(event, detail):\n    if _EV['server']:\n        try:\n            log_event(_EV['server'], _EV['token'], event, detail)\n        except Exception:\n            pass\n\ndef _wifi_iface(base='/sys/class/net'):\n    try:\n        for n in sorted(os.listdir(base)):\n            if os.path.isdir(os.path.join(base, n, 'wireless')) or os.path.exists(os.path.join(base, n, 'phy80211')):\n                return n\n    except Exception:\n        pass\n    return None\n\ndef _wired_ifaces(base='/sys/class/net'):\n    try:\n        return [n for n in sorted(os.listdir(base)) if re.match(r'(eth|en)', n) and not os.path.isdir(os.path.join(base, n, 'wireless'))]\n    except Exception:\n        return []\n\ndef wpa_config(profiles):\n    \"\"\"wpa_supplicant.conf for the profiles, best first. SSIDs as hex (any\n    characters work); the key derived from the password with PBKDF2, as WPA\n    does, so the password itself is not stored.\"\"\"\n    import hashlib\n    out = ['# Written by the Infoskjerm agent (v4.9.3). Change the networks in the portal.',\n           'ctrl_interface=/var/run/wpa_supplicant', 'update_config=0', 'country=NO', '']\n    for p in sorted(profiles or [], key=lambda p: int(p.get('priority') or 0)):\n        ssid = str(p.get('ssid') or '')\n        if not ssid:\n            continue\n        pw = str(p.get('password') or '')\n        lines = ['network={', f'\\tssid={ssid.encode().hex()}', '\\tscan_ssid=1',\n                 f'\\tpriority={max(1, 100 - int(p.get(\"priority\") or 0))}']   # portal: lower wins; wpa_supplicant: higher wins\n        if not pw:\n            lines.append('\\tkey_mgmt=NONE')\n        elif re.fullmatch(r'[0-9a-fA-F]{64}', pw):\n            lines.append(f'\\tpsk={pw.lower()}')\n        else:\n            lines.append('\\tpsk=' + hashlib.pbkdf2_hmac('sha1', pw.encode(), ssid.encode(), 4096, 32).hex())\n        out += lines + ['}', '']\n    return '\\n'.join(out)\n\ndef interfaces_with_wifi(text, iface):\n    \"\"\"/etc/network/interfaces with a DHCP entry for the WiFi card, after the\n    cable (metric 600), added once.\"\"\"\n    if re.search(rf'^\\s*iface\\s+{re.escape(iface)}\\s', text, re.M):\n        return text\n    return text.rstrip('\\n') + f'\\n\\n# WiFi, after the cable (Infoskjerm agent v4.9.3)\\nauto {iface}\\niface {iface} inet dhcp\\n\\tmetric 600\\n'\n\ndef _apply_alpine(profiles):\n    iface = _wifi_iface()\n    if not iface:\n        _report('wifi_apply_failed', 'Fant ikke noe trådløst nettverkskort på denne maskinen')\n        return\n    if not shutil.which('wpa_supplicant'):\n        r = subprocess.run(['apk', 'add', '--no-cache', 'wpa_supplicant'], capture_output=True, text=True, timeout=180)\n        if r.returncode != 0 or not shutil.which('wpa_supplicant'):\n            _report('wifi_apply_failed', 'Kunne ikke installere wpa_supplicant: ' + (r.stderr or r.stdout or '').strip()[-150:])\n            return\n    os.makedirs(os.path.dirname(_P(WPA_CONF)), exist_ok=True)\n    tmp = _P(WPA_CONF) + '.tmp'\n    with open(tmp, 'w') as f:\n        f.write(wpa_config(profiles))\n    os.chmod(tmp, 0o600)\n    os.replace(tmp, _P(WPA_CONF))\n    os.makedirs(_P('/etc/conf.d'), exist_ok=True)\n    with open(_P('/etc/conf.d/wpa_supplicant'), 'w') as f:\n        f.write(f'# Infoskjerm agent v4.9.3\\nwpa_supplicant_args=\"-i {iface}\"\\nwpa_supplicant_conf=\"{WPA_CONF}\"\\n')\n    try:\n        with open(_P('/etc/network/interfaces')) as f:\n            cur = f.read()\n    except FileNotFoundError:\n        cur = 'auto lo\\niface lo inet loopback\\n'\n    new = interfaces_with_wifi(cur, iface)\n    if new != cur:\n        os.makedirs(_P('/etc/network'), exist_ok=True)\n        with open(_P('/etc/network/interfaces'), 'w') as f:\n            f.write(new)\n    subprocess.run(['rc-update', 'add', 'wpa_supplicant', 'boot'], capture_output=True, timeout=15)\n    r = subprocess.run(['rc-service', 'wpa_supplicant', 'restart'], capture_output=True, text=True, timeout=30)\n    if r.returncode != 0:\n        _report('wifi_apply_failed', 'wpa_supplicant startet ikke: ' + (r.stderr or r.stdout or '').strip()[-150:])\n        return\n    names = ', '.join(str(p.get('ssid')) for p in sorted(profiles or [], key=lambda p: int(p.get('priority') or 0)) if p.get('ssid'))\n    _report('wifi_applied', f'Kabel først, så {names}' if names else 'Ingen trådløse nett: bare kabel')\n    log.info('WiFi on %s: %s', iface, names or 'none')\n\ndef failover_actions(st):\n    \"\"\"What to do, from the state of the links. Pure, so it can be tested.\n    st: wired [names], wifi (name or None), carrier {name: bool}, ip {name: bool},\n    routes [{gw, dev, metric}], wifi_configured, wpa_running, dhcp {name: bool}.\"\"\"\n    acts = []\n    for r in st['routes']:\n        if r['dev'] in st['wired'] and not st['carrier'].get(r['dev']):\n            acts.append(['ip', 'route', 'del', 'default', 'via', r['gw'], 'dev', r['dev']])       # cable out: its route goes\n        elif r['dev'] == st['wifi'] and r['metric'] < 600:\n            acts.append(['ip', 'route', 'del', 'default', 'via', r['gw'], 'dev', r['dev'], 'metric', str(r['metric'])])\n            acts.append(['ip', 'route', 'add', 'default', 'via', r['gw'], 'dev', r['dev'], 'metric', '600'])   # WiFi after the cable\n    for n in st['wired']:\n        if st['carrier'].get(n) and not st['ip'].get(n) and not st['dhcp'].get(n):\n            acts.append(['udhcpc', '-i', n, '-b', '-R', '-p', f'/run/udhcpc.{n}.pid'])                    # cable in: ask for an address\n    w = st['wifi']\n    if w and st['wifi_configured']:\n        if not st['wpa_running']:\n            acts.append(['rc-service', 'wpa_supplicant', 'start'])\n        elif not st['ip'].get(w) and not st['dhcp'].get(w):\n            acts.append(['udhcpc', '-i', w, '-b', '-R', '-p', f'/run/udhcpc.{w}.pid'])\n    return acts\n\ndef _net_state(base='/sys/class/net'):\n    wired, wifi = _wired_ifaces(base), _wifi_iface(base)\n    def carrier(n):\n        try:\n            with open(f'{base}/{n}/carrier') as f:\n                return f.read().strip() == '1'\n        except Exception:\n            return False\n    addr = subprocess.run(['ip', '-4', '-o', 'addr', 'show'], capture_output=True, text=True, timeout=5).stdout\n    has_ip = lambda n: bool(re.search(rf'^\\d+:\\s+{re.escape(n)}\\s+inet ', addr, re.M))\n    routes = []\n    for line in subprocess.run(['ip', '-4', 'route', 'show', 'default'], capture_output=True, text=True, timeout=5).stdout.splitlines():\n        m = re.search(r'via (\\S+) dev (\\S+)', line)\n        if m:\n            mm = re.search(r'metric (\\d+)', line)\n            routes.append({'gw': m.group(1), 'dev': m.group(2), 'metric': int(mm.group(1)) if mm else 0})\n    running = lambda pat: subprocess.run(['pgrep', '-f', pat], capture_output=True, timeout=5).returncode == 0\n    try:\n        with open(_P(WPA_CONF)) as f:\n            configured = 'network={' in f.read()\n    except Exception:\n        configured = False\n    names = wired + ([wifi] if wifi else [])\n    return {'wired': wired, 'wifi': wifi, 'carrier': {n: carrier(n) for n in names}, 'ip': {n: has_ip(n) for n in names},\n            'routes': routes, 'wifi_configured': configured, 'wpa_running': running('wpa_supplicant'),\n            'dhcp': {n: running(f'udhcpc.*-i {n}') for n in names}}\n\ndef net_failover_loop():\n    \"\"\"The laptops (Alpine) only; the Pis have NetworkManager, which already puts the cable first.\"\"\"\n    while True:\n        try:\n            for cmd in failover_actions(_net_state()):\n                subprocess.run(cmd, capture_output=True, timeout=20)\n                log.info('network: %s', ' '.join(cmd))\n        except Exception as e:\n            log.debug('network check: %s', e)\n        time.sleep(10)\n\ndef apply_wifi_profiles(profiles):\n    \"\"\"Apply WiFi profiles — auto-detects NM vs netplan.\"\"\"\n    def _apply():\n        log.info(\"Applying %d WiFi profile(s)\", len(profiles))\n        try:\n            if _IS_ALPINE:                        # v4.9.3: the laptops\n                log.info(\"Using wpa_supplicant (Alpine)\")\n                _apply_alpine(profiles)\n                return\n            # Which network manager is active (no systemctl: ask nmcli itself)\n            try:\n                nm_running = subprocess.run([\"systemctl\", \"is-active\", \"NetworkManager\"],\n                    capture_output=True, text=True, timeout=5).stdout.strip() == \"active\"\n            except FileNotFoundError:\n                nm_running = bool(shutil.which('nmcli'))\n            if nm_running:\n                log.info(\"Using NetworkManager (nmcli)\")\n                _apply_nmcli(profiles)\n            else:\n                log.info(\"Using netplan\")\n                _apply_netplan(profiles)\n            _report('wifi_applied', ', '.join(str(p.get('ssid')) for p in profiles if p.get('ssid')) or 'Ingen trådløse nett')\n        except Exception as e:\n            log.error(\"WiFi apply error: %s\", e)\n            _report('wifi_apply_failed', str(e)[:160])\n    threading.Thread(target=_apply, daemon=True).start()\n\ndef _apply_nmcli(profiles):\n    \"\"\"Apply WiFi profiles via NetworkManager — handles special chars in passwords.\"\"\"\n    subprocess.run([\"sudo\", \"nmcli\", \"radio\", \"wifi\", \"on\"], capture_output=True, timeout=10)\n    subprocess.run([\"sudo\", \"nmcli\", \"dev\", \"set\", \"wlan0\", \"managed\", \"yes\"], capture_output=True, timeout=10)\n    # Brief scan to discover available networks\n    subprocess.run([\"sudo\", \"nmcli\", \"dev\", \"wifi\", \"rescan\"], capture_output=True, timeout=15)\n    time.sleep(3)\n\n    # Remove WiFi connections not in the pushed set\n    wanted_ssids = {p.get(\"ssid\",\"\") for p in profiles if p.get(\"ssid\",\"\")}\n    # Use -t (terse) with explicit field separator to handle SSIDs with colons\n    wifi_conns = subprocess.run(\n        [\"nmcli\", \"-t\", \"-f\", \"NAME,TYPE\", \"connection\", \"show\"],\n        capture_output=True, text=True, timeout=10).stdout.splitlines()\n    for line in wifi_conns:\n        # Terse mode outputs NAME:TYPE — split on last colon\n        parts = line.rsplit(\":\", 1)\n        if len(parts) == 2 and \"wireless\" in parts[1]:\n            conn_name = parts[0]\n            if conn_name not in wanted_ssids:\n                log.info(\"Removing old WiFi profile: %s\", conn_name)\n                subprocess.run([\"sudo\", \"nmcli\", \"connection\", \"delete\", conn_name],\n                    capture_output=True, timeout=15)\n\n    # Refresh existing list after removals\n    existing = subprocess.run([\"nmcli\", \"-t\", \"-f\", \"NAME\", \"connection\", \"show\"],\n        capture_output=True, text=True, timeout=10).stdout.splitlines()\n\n    for p in profiles:\n        ssid = p.get(\"ssid\",\"\")\n        pwd  = p.get(\"password\",\"\")\n        prio = p.get(\"priority\", 10)\n        if not ssid: continue\n        try:\n            if ssid in existing:\n                log.info(\"Updating NM profile: %s\", ssid)\n                modify_cmd = [\"sudo\", \"nmcli\", \"connection\", \"modify\", ssid,\n                    \"connection.autoconnect\", \"yes\",\n                    \"connection.autoconnect-priority\", str(100 - prio)]\n                if pwd:\n                    modify_cmd += [\"wifi-sec.key-mgmt\", \"wpa-psk\", \"wifi-sec.psk\", pwd]\n                subprocess.run(modify_cmd, capture_output=True, timeout=15)\n            else:\n                log.info(\"Creating NM profile: %s\", ssid)\n                cmd = [\"sudo\", \"nmcli\", \"connection\", \"add\",\n                    \"type\", \"wifi\", \"ifname\", \"wlan0\",\n                    \"con-name\", ssid, \"ssid\", ssid,\n                    \"connection.autoconnect\", \"yes\",\n                    \"connection.autoconnect-priority\", str(100 - prio)]\n                if pwd:\n                    cmd += [\"wifi-sec.key-mgmt\", \"wpa-psk\", \"wifi-sec.psk\", pwd]\n                r = subprocess.run(cmd, capture_output=True, text=True, timeout=30)\n                if r.returncode != 0:\n                    log.warning(\"nmcli add failed for %s: %s\", ssid, r.stderr.strip())\n                    continue\n            # Try to activate\n            r2 = subprocess.run([\"sudo\", \"nmcli\", \"connection\", \"up\", ssid],\n                capture_output=True, text=True, timeout=30)\n            if r2.returncode == 0:\n                log.info(\"Connected to: %s\", ssid)\n            else:\n                log.info(\"Profile saved (not in range or auth failed): %s — %s\", ssid, r2.stderr.strip())\n        except Exception as e:\n            log.error(\"nmcli error for %s: %s\", ssid, e)\n\ndef _apply_netplan(profiles):\n    \"\"\"Apply WiFi profiles via netplan.\"\"\"\n    yaml_lines = [\n        \"network:\",\n        \"  version: 2\",\n        \"  wifis:\",\n        \"    wlan0:\",\n        \"      dhcp4: true\",\n        \"      optional: true\",\n        \"      access-points:\",\n    ]\n    has_profiles = False\n    for p in profiles:\n        ssid = p.get(\"ssid\",\"\")\n        pwd  = p.get(\"password\",\"\")\n        if not ssid: continue\n        has_profiles = True\n        yaml_lines.append(\"        \\\"\" + ssid + \"\\\":\" )\n        if pwd:\n            yaml_lines.append(\"          password: \\\"\" + pwd + \"\\\"\" )\n        else:\n            yaml_lines.append(\"          {}\" )\n    if not has_profiles:\n        log.warning(\"No valid WiFi profiles to apply\")\n        return\n    yaml_content = chr(10).join(yaml_lines) + chr(10)\n    tmp_path = \"/tmp/infoscreen-wifi.yaml\"\n    netplan_conf = N(\"/etc/netplan/60-infoscreen-wifi.yaml\")\n    with open(tmp_path, \"w\") as fh:\n        fh.write(yaml_content)\n    subprocess.run([\"sudo\", \"cp\", tmp_path, netplan_conf], check=True, timeout=10)\n    subprocess.run([\"sudo\", \"chmod\", \"600\", netplan_conf], timeout=5)\n    os.unlink(tmp_path)\n    # Unblock wifi and apply\n    subprocess.run([\"sudo\", \"rfkill\", \"unblock\", \"wifi\"], capture_output=True, timeout=5)\n    r = subprocess.run([\"sudo\", \"netplan\", \"apply\"], capture_output=True, text=True, timeout=30)\n    if r.returncode == 0:\n        log.info(\"netplan apply OK\")\n    else:\n        log.warning(\"netplan apply: %s\", r.stderr.strip())\n\n_agent_update_lock = threading.Lock()\n\n\ndef self_update_agent_and_restart(server, token=None):\n    \"\"\"Install the current server agent once, even if HTTP and WS race.\n\n    Delivery can briefly arrive over both heartbeat and WebSocket before the\n    server sees our receipt event. Running two self-updates concurrently risks\n    copying/restarting the same file twice, so only one path may enter here.\n    \"\"\"\n    if not _agent_update_lock.acquire(blocking=False):\n        log.info('[self-update] duplicate delivery ignored; an agent update is already running')\n        return True\n    try:\n        ok, detail = self_update_agent(server, token)\n        log.info('[self-update] result: %s — %s', 'ok' if ok else 'FAILED', detail)\n        try:\n            log_event(server, token or _pi_token, 'agent_update',\n                      ('ok: ' if ok else 'failed: ') + detail[:400])\n        except Exception:\n            pass\n        if ok:\n            time.sleep(1.5)\n            restart_agent_process()\n        return ok\n    finally:\n        try:\n            _agent_update_lock.release()\n        except RuntimeError:\n            pass\n\n\ndef restart_agent_process():\n    \"\"\"Restart this agent, whatever is supervising it.\n\n    `systemctl restart` was the only method, which fails two ways that both\n    look like \"nothing happened\": on Alpine laptops there is no systemctl at\n    all, and when the agent runs as an unprivileged user the call is refused.\n    Popen does not raise in either case — the child just exits non-zero — so\n    the old code logged \"restarting service\" and carried on running the old\n    code forever.\n\n    The last resort is the reliable one: replace this process with the new file\n    in place. Same PID, so whatever supervises us is none the wiser, and it\n    needs no init system and no privileges.\n    \"\"\"\n    agent_file = AGENT_FILE\n    svc = agent_service()\n\n    for cmd in (['systemctl', 'restart', svc],\n                ['rc-service', svc, 'restart'],\n                ['service', svc, 'restart']):\n        if not shutil.which(cmd[0]):\n            continue\n        try:\n            r = subprocess.run(cmd, capture_output=True, timeout=30)\n            if r.returncode == 0:\n                # A successful service-manager restart does not prove THIS\n                # process was managed by that service. Older Pi/Openbox images\n                # could have an unmanaged active agent plus a supervised standby:\n                # systemctl/rc-service restarted the standby, while this old PID\n                # kept the single-instance socket and kept reporting old code.\n                # Relinquish the current process unconditionally. If the manager\n                # already killed us this line is never reached; otherwise the\n                # freshly started supervised process takes over. os._exit is\n                # required because this function is also called from worker threads.\n                log.info('[self-update] restarted via %s; exiting current PID %s to complete handoff', cmd[0], os.getpid())\n                time.sleep(0.5)\n                os._exit(0)\n            log.warning('[self-update] %s failed (rc=%s): %s',\n                        cmd[0], r.returncode,\n                        (r.stderr or b'').decode('utf-8', 'replace').strip()[:200])\n        except Exception as e:\n            log.warning('[self-update] %s raised: %s', cmd[0], e)\n\n    log.info('[self-update] no init system could restart us — re-executing in place')\n    try:\n        sys.stdout.flush(); sys.stderr.flush()\n        os.execv(sys.executable, [sys.executable, agent_file])\n    except Exception as e:\n        log.error('[self-update] re-exec failed: %s', e)\n        return False, 'none'\n\n\ndef installed_agent_version():\n    \"\"\"Read AGENT_VERSION out of the file on disk, not out of this process.\"\"\"\n    try:\n        with open(AGENT_FILE, 'r', errors='replace') as f:\n            m = re.search(r\"AGENT_VERSION\\s*=\\s*['\\\"]([^'\\\"]+)['\\\"]\", f.read(4000))\n            return m.group(1) if m else 'unknown'\n    except Exception:\n        return 'unknown'\n\n\ndef self_update_agent(server, token=None):\n    \"\"\"Fetch and install the agent. Returns (ok, detail).\n\n    Runs to completion before returning. The previous version fired a thread\n    and returned None, and the caller read `None is not False` as success — so\n    every push acked \"done\" the instant it arrived, whatever happened\n    afterwards. A download failure, a syntax check failure, a permission error\n    on the copy and a refused restart all reported 100% complete.\n    \"\"\"\n    steps = []\n    def step(msg, ok=True):\n        steps.append(('' if ok else 'FAIL: ') + msg)\n        (log.info if ok else log.error)('[self-update] %s', msg)\n\n    try:\n        before = installed_agent_version()\n        step(f'installed version before: {before}')\n\n        tmp = _private_tmp('infoscreen-agent-new-', '.py')\n        r = requests.get(f'{server}/agent', timeout=45)\n        if r.status_code != 200:\n            step(f'/agent returned HTTP {r.status_code}, trying /api/pi/agent-download')\n            r = requests.get(f'{server}/api/pi/agent-download',\n                             headers={'X-Pi-Token': token or _pi_token or ''}, timeout=45)\n        if r.status_code != 200:\n            step(f'download failed: HTTP {r.status_code}', False)\n            return False, '; '.join(steps)\n        if len(r.content) < 5000:\n            step(f'downloaded file is only {len(r.content)} bytes — refusing it', False)\n            return False, '; '.join(steps)\n        step(f'downloaded {len(r.content)} bytes')\n\n        with open(tmp, 'wb') as f:\n            f.write(r.content)\n\n        chk = subprocess.run([sys.executable, '-m', 'py_compile', tmp],\n                             capture_output=True, timeout=30)\n        try: os.remove(tmp)\n        except OSError: pass\n        if chk.returncode != 0:\n            step('downloaded agent failed the syntax check', False)\n            return False, '; '.join(steps)\n\n        m = re.search(r\"AGENT_VERSION\\s*=\\s*['\\\"]([^'\\\"]+)['\\\"]\",\n                      r.content.decode('utf-8', 'replace')[:4000])\n        incoming = m.group(1) if m else 'unknown'\n        step(f'downloaded version: {incoming}')\n\n        # The file this process runs (old or new name), never a guessed path:\n        # writing a new-named file next to an old install would update nothing.\n        target = AGENT_FILE\n        try:\n            shutil.copy(target, target + '.bak')\n        except Exception:\n            pass\n        # Install through the same atomic helper used by the component healer.\n        # Some older laptop images leave /opt/infoscreen-agent root-owned even\n        # though the running display agent is unprivileged. A plain shutil.copy\n        # then fails and the portal reports \"no response\" forever. _install_file\n        # uses direct replace when possible and the installer's narrow sudo cp\n        # permission when required (v4.9.27).\n        if not _install_file(r.content, target, 0o755):\n            step(f'cannot install {target}; current user={os.getenv(\"USER\") or os.getuid()} '\n                 f'euid={os.geteuid()} (direct write and permitted sudo install both failed)', False)\n            return False, '; '.join(steps)\n\n        after = installed_agent_version()\n        if after != incoming:\n            step(f'file on disk still reports {after} after the copy', False)\n            return False, '; '.join(steps)\n        step(f'installed version now: {after}')\n\n        try:\n            import websocket  # noqa: F401\n        except ImportError:\n            step('installing websocket-client')\n            subprocess.run([sys.executable, '-m', 'pip', 'install',\n                            '--break-system-packages', 'websocket-client'],\n                           capture_output=True, timeout=180)\n\n        # Pull anything the bundle left out while we are here, so the restart\n        # brings up a complete install rather than an agent with no extension.\n        try:\n            if heal_components(server, token or _pi_token):\n                step('repaired missing components')\n        except Exception as e:\n            step(f'component repair skipped: {e}')\n\n        return True, '; '.join(steps)\n\n    except Exception as e:\n        step(f'unexpected error: {e}', False)\n        return False, '; '.join(steps)\n\n\ndef apply_server_url(new_url):\n    \"\"\"Move to another server address: safely, in the background (v4.6.0).\n    The old version wrote the env file directly (not writable by the Pi's kiosk\n    user) and called systemctl (not present on the Alpine laptops), so it\n    could not work on either. See migrate_server.\"\"\"\n    threading.Thread(target=migrate_server, args=(new_url,), daemon=True).start()\n\n\n# ── Moving to a new server address (v4.6.0) ──────────────────────────\n# The portal's \"primary server\" migration (and the per-screen address change)\n# lands here. Nothing switches until the new address has proved it knows this\n# screen; the old address is remembered; and if the new server never answers\n# after the switch, the screen goes back by itself.\n_server_ok = {'at': 0.0}\n_move = {'busy': False, 'last_try': {}}\n\n\ndef _norm_origin(url):\n    m = re.match(r'^(https?://[A-Za-z0-9.-]+(?::\\d{1,5})?)/?$', (url or '').strip())\n    return m.group(1) if m else None\n\n\ndef _report_move(server, token, state, to, detail=''):\n    try:\n        requests.post(f'{server}/api/pi/move-status', headers={'X-Pi-Token': token},\n                      json={'state': state, 'to': to, 'detail': str(detail)[:300]}, timeout=10)\n    except Exception:\n        pass\n\n\ndef _write_server_env(url, previous=None):\n    \"\"\"INFOSCREEN_URL=url, plus the address we came from for the way back.\"\"\"\n    if os.geteuid() != 0:\n        if not priv_helper_ready():\n            log.warning('Server move: no root helper yet, cannot rewrite %s', CONFIG_FILE)\n            return False\n        r = _run(['sudo', '-n', PRIV_HELPER, 'set-url', url] + ([previous] if previous else []), timeout=30)\n        return bool(r and r.returncode == 0)\n    try:\n        lines = []\n        if os.path.exists(CONFIG_FILE):\n            with open(CONFIG_FILE) as f:\n                lines = [l for l in f if not l.startswith(tuple(f'{p}{k}=' for p in ('INFOSCREEN_', LEGACY.upper() + '_')\n                                                                 for k in ('URL', 'URL_PREVIOUS', 'MOVED_AT')))]\n        lines.append(f\"{N('INFOSCREEN_URL')}={url}\\n\")\n        if previous:\n            lines.append(f\"{N('INFOSCREEN_URL_PREVIOUS')}={previous}\\n{N('INFOSCREEN_MOVED_AT')}={int(time.time())}\\n\")\n        with open(CONFIG_FILE, 'w') as f:\n            f.writelines(lines)\n        return True\n    except Exception as e:\n        log.error('Server move: could not write %s: %s', CONFIG_FILE, e)\n        return False\n\n\ndef migrate_server(new_url):\n    new = _norm_origin(new_url)\n    cur = (_cfg.get('server') or '').rstrip('/')\n    token = _cfg.get('token') or _pi_token\n    if not new or new == cur or _move['busy']:\n        return False\n    _move['busy'] = True\n    try:\n        # 1. The new address must know THIS screen: the same server under a\n        #    new name, or a server that has received the data. Otherwise stay.\n        try:\n            r = requests.get(f'{new}/api/pi/whoami', headers={'X-Pi-Token': token}, timeout=15)\n            ok = r.status_code == 200 and bool(r.json().get('ok'))\n            why = '' if ok else f'svarte {r.status_code}'\n        except Exception as e:\n            ok, why = False, str(e)[:160]\n        if not ok:\n            log.warning('Server move to %s postponed: %s', new, why)\n            _report_move(cur, token, 'waiting', new, 'Ny server kjenner ikke skjermen ennå: ' + why)\n            return False\n        _report_move(cur, token, 'switching', new)\n        # 2. Point the config at the new server, remembering this one.\n        if not _write_server_env(new, previous=cur):\n            _report_move(cur, token, 'failed', new, f'Kunne ikke skrive {CONFIG_FILE}')\n            return False\n        # 3. Lockdown for the new origin: Chromium's allowlist and the local-\n        #    network policy name the server, so they must follow it first.\n        try:\n            run_hardening(new)\n        except Exception as e:\n            log.warning('Server move: hardening after the switch: %s', e)\n        log.warning('Server move: now %s (was %s). Restarting to connect there.', new, cur)\n        restart_agent_process()\n        return True\n    finally:\n        _move['busy'] = False\n\n\ndef _maybe_move(url):\n    \"\"\"At most one try every 5 minutes per address; the server keeps asking.\"\"\"\n    new = _norm_origin(url)\n    if not new or new == (_cfg.get('server') or '').rstrip('/'):\n        return\n    if time.time() - _move['last_try'].get(new, 0) < 300:\n        return\n    _move['last_try'][new] = time.time()\n    threading.Thread(target=migrate_server, args=(new,), daemon=True).start()\n\n\ndef move_watchdog(server, token):\n    \"\"\"Just moved? The new server must answer within 15 minutes, or go back.\"\"\"\n    cfg = load_config()\n    prev = _norm_origin(cfg.get('INFOSCREEN_URL_PREVIOUS', ''))\n    try:\n        moved = int(cfg.get('INFOSCREEN_MOVED_AT') or 0)\n    except ValueError:\n        moved = 0\n    if not prev or not moved or time.time() - moved > 3600:\n        return\n    deadline = moved + 900\n    while time.time() < deadline:\n        if _server_ok['at'] > moved:\n            log.info('Server move confirmed: %s answers', server)\n            _write_server_env(server)          # clears the way-back markers\n            return\n        time.sleep(20)\n    try:\n        r = requests.get(f'{prev}/api/pi/whoami', headers={'X-Pi-Token': token}, timeout=15)\n        back = r.status_code == 200\n    except Exception:\n        back = False\n    if not back:\n        log.error('Server move: %s never answered, and %s does not either. Staying.', server, prev)\n        return\n    log.error('Server move: %s never answered in 15 minutes. Going back to %s.', server, prev)\n    if _write_server_env(prev):\n        _report_move(prev, token, 'rolled_back', server, 'Ny server svarte ikke. Skjermen gikk tilbake.')\n        try:\n            run_hardening(prev)\n        except Exception:\n            pass\n        restart_agent_process()\n\n\ndef get_db():\n    conn = sqlite3.connect(METRICS_DB, timeout=5)\n    conn.execute('PRAGMA journal_mode=WAL')\n    conn.execute('PRAGMA synchronous=NORMAL')\n    return conn\n\ndef init_metrics_db():\n    conn = get_db()\n    conn.execute('''CREATE TABLE IF NOT EXISTS metrics (\n        id INTEGER PRIMARY KEY AUTOINCREMENT,\n        recorded_at TEXT DEFAULT (datetime('now','localtime')),\n        cpu_load REAL, cpu_temp REAL,\n        memory_used INTEGER, memory_total INTEGER,\n        disk_used INTEGER, disk_total INTEGER,\n        uptime INTEGER, browser_running INTEGER\n    )''')\n    conn.execute(\"CREATE INDEX IF NOT EXISTS idx_metrics_time ON metrics(recorded_at)\")\n    conn.commit()\n    conn.close()\n\ndef store_metrics(metrics, browser_running):\n    def _store():\n        try:\n            conn = get_db()\n            conn.execute('''INSERT INTO metrics\n            (cpu_load,cpu_temp,memory_used,memory_total,disk_used,disk_total,uptime,browser_running)\n            VALUES (?,?,?,?,?,?,?,?)''',\n            (metrics.get('cpu_load'), metrics.get('cpu_temp'),\n             metrics.get('memory_used'), metrics.get('memory_total'),\n             metrics.get('disk_used'), metrics.get('disk_total'),\n             metrics.get('uptime'), 1 if browser_running else 0))\n            conn.execute(\"DELETE FROM metrics WHERE recorded_at < datetime('now','localtime','-7 days')\")\n            conn.commit()\n            conn.close()\n        except Exception as e:\n            log.warning('metrics store error: %s', e)\n    threading.Thread(target=_store, daemon=True).start()\n\ndef get_recent_metrics(hours=1):\n    try:\n        conn = get_db()\n        conn.row_factory = sqlite3.Row\n        rows = conn.execute(\n            \"SELECT * FROM metrics WHERE recorded_at > datetime('now','localtime',? || ' hours') ORDER BY recorded_at ASC\",\n            (f'-{hours}',)).fetchall()\n        conn.close()\n        return [dict(r) for r in rows]\n    except: return []\n\nfrom http.server import HTTPServer, BaseHTTPRequestHandler\nclass LiveHandler(BaseHTTPRequestHandler):\n    def do_GET(self):\n        if self.path == '/push-heartbeat':\n            global _force_heartbeat\n            _force_heartbeat = True\n            body = b'{\"ok\":true}'\n            self.send_response(200)\n            self.send_header('Content-Type', 'application/json')\n            self.send_header('Content-Length', len(body))\n            self.end_headers()\n            self.wfile.write(body)\n            return\n\n        # MJPEG live stream of the display output\n        if self.path == '/mjpeg':\n            self.send_response(200)\n            self.send_header('Content-Type', 'multipart/x-mixed-replace; boundary=--frame')\n            self.send_header('Cache-Control', 'no-cache, no-store')\n            self.send_header('Connection', 'close')\n            self.end_headers()\n            try:\n                while True:\n                    frame = capture_frame()\n                    if frame:\n                        jpg_data = _b64.b64decode(frame)\n                        self.wfile.write(b'--frame\\r\\n')\n                        self.wfile.write(b'Content-Type: image/jpeg\\r\\n')\n                        self.wfile.write(f'Content-Length: {len(jpg_data)}\\r\\n\\r\\n'.encode())\n                        self.wfile.write(jpg_data)\n                        self.wfile.write(b'\\r\\n')\n                        self.wfile.flush()\n                    time.sleep(0.5)  # ~2fps\n            except (BrokenPipeError, ConnectionResetError):\n                pass  # client disconnected\n            return\n\n        # Serve cached media files: /cache/uploads/slides/xxx.mp4\n        if self.path.startswith('/cache/'):\n            url_path = self.path[len('/cache'):].split('?', 1)[0]\n            local_path = _cached_files.get(url_path)\n            if not (local_path and os.path.exists(local_path)):\n                self.send_response(404)\n                self.send_header('Content-Length', '0')\n                self.end_headers(); return\n            self._send_file(local_path)\n            return\n\n        if self.path != '/status':\n            self.send_response(404); self.end_headers(); return\n        metrics = get_metrics()\n        recent = get_recent_metrics(1)\n        status = {\n            'metrics': metrics,\n            'browser_running': browser_proc is not None and browser_proc.poll() is None,\n            'current_url': current_viewer_url,\n            'recent': recent[-60:] if recent else [],\n            'apt_updates': _apt_updates['count'],\n            'agent_version': AGENT_VERSION\n        }\n        body = json.dumps(status).encode()\n        self.send_response(200)\n        self.send_header('Content-Type', 'application/json')\n        self.send_header('Content-Length', len(body))\n        self.end_headers()\n        self.wfile.write(body)\n    def _send_file(self, local_path):\n        \"\"\"Serve a cached file with HTTP Range support.\n\n        Chromium's media player asks for byte ranges: to find the index of an\n        MP4 whose 'moov' atom sits at the end (most phone and editor exports),\n        and to loop or seek. Without 206 responses such files stall or fail\n        with a decode error, and every replay re-read the whole file.\n        \"\"\"\n        ext = os.path.splitext(local_path)[1].lower()\n        mime = {'.mp4': 'video/mp4', '.webm': 'video/webm', '.mov': 'video/quicktime',\n                '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.png': 'image/png',\n                '.gif': 'image/gif', '.webp': 'image/webp'}.get(ext, 'application/octet-stream')\n        size = os.path.getsize(local_path)\n        start, end = 0, size - 1\n        partial = False\n        rng = self.headers.get('Range', '')\n        m = re.match(r'bytes=(\\d*)-(\\d*)$', rng.strip()) if rng else None\n        if m and (m.group(1) or m.group(2)):\n            if m.group(1):\n                start = int(m.group(1))\n                if m.group(2): end = min(int(m.group(2)), size - 1)\n            else:                                   # suffix: last N bytes\n                start = max(0, size - int(m.group(2)))\n            if start >= size or start > end:\n                self.send_response(416)\n                self.send_header('Content-Range', f'bytes */{size}')\n                self.send_header('Content-Length', '0')\n                self.end_headers(); return\n            partial = True\n        length = end - start + 1\n        self.send_response(206 if partial else 200)\n        self.send_header('Content-Type', mime)\n        self.send_header('Accept-Ranges', 'bytes')\n        self.send_header('Content-Length', str(length))\n        if partial:\n            self.send_header('Content-Range', f'bytes {start}-{end}/{size}')\n        self.send_header('Cache-Control', 'no-cache')\n        self.end_headers()\n        if self.command == 'HEAD':\n            return\n        try:\n            with open(local_path, 'rb') as f:\n                f.seek(start)\n                left = length\n                while left > 0:\n                    chunk = f.read(min(262144, left))\n                    if not chunk: break\n                    self.wfile.write(chunk)\n                    left -= len(chunk)\n        except (BrokenPipeError, ConnectionResetError):\n            pass   # Chromium routinely drops a range request it no longer needs\n\n    def do_HEAD(self):\n        if self.path.startswith('/cache/'):\n            local_path = _cached_files.get(self.path[len('/cache'):].split('?', 1)[0])\n            if local_path and os.path.exists(local_path):\n                self._send_file(local_path); return\n        self.send_response(404)\n        self.send_header('Content-Length', '0')\n        self.end_headers()\n\n    def log_message(self, *args): pass\n\ndef start_live_server():\n    try:\n        # Threaded: the MJPEG stream (HDMI Stream popup) never returns, and\n        # with a single-threaded server one open popup blocked every video\n        # request from the viewer — the video never loaded and the slideshow\n        # stood still. Chromium also opens several range requests per video.\n        server = ThreadingHTTPServer(('0.0.0.0', LIVE_PORT), LiveHandler)\n        server.daemon_threads = True\n        t = threading.Thread(target=server.serve_forever, daemon=True)\n        t.start()\n        log.info('Live status server on port %d', LIVE_PORT)\n    except Exception as e:\n        log.warning('Could not start live server: %s', e)\n\nlogging.basicConfig(level=logging.INFO, format='%(asctime)s [EventAdmin-Screen] %(message)s')\nlog = logging.getLogger('piagent')\n\ndef _env_value(raw):\n    \"\"\"Read one VALUE from a KEY=VALUE line the way /bin/sh would.\n\n    The laptop ISO writes every value shell-quoted (build-kiosk-iso.sh sq():\n    INFOSCREEN_URL='https://…', with ' escaped as '\\\\''), so a password with a\n    space or a quote survives `. /etc/infoscreen.env`. The shell scripts unquote\n    that; this parser used to keep the quotes literally. The agent then called\n    the server at \"'https://…\" (every request failed, so the screen never\n    enrolled or showed \"waiting for approval\") and opened Chromium on it\n    (ERR_NAME_NOT_RESOLVED: \"'https's server IP address could not be found\").\n    Unquoted values (the Pi's env file) come through unchanged.\n    \"\"\"\n    v = raw.strip()\n    if not v or v[0] not in ('\"', \"'\"):\n        return v\n    try:\n        parts = shlex.split(v, comments=False, posix=True)\n        return ''.join(parts) if parts else ''\n    except ValueError:\n        # Unbalanced quote: strip one matching outer pair, keep the rest.\n        if len(v) >= 2 and v[-1] == v[0]:\n            return v[1:-1]\n        return v.lstrip('\"\\'')\n\ndef load_config():\n    cfg = {}\n    if os.path.exists(CONFIG_FILE):\n        with open(CONFIG_FILE) as f:\n            for line in f:\n                line = line.strip()\n                if line and not line.startswith('#') and '=' in line:\n                    k, _, v = line.partition('=')\n                    k = k.strip()\n                    v = _env_value(v)\n                    if k.startswith(LEGACY.upper() + '_'):      # not renamed yet\n                        k = 'INFOSCREEN_' + k[len(LEGACY) + 1:]\n                    cfg[k] = v\n                    # Also store without INFOSCREEN_ prefix for compatibility\n                    if k.startswith('INFOSCREEN_') and k != 'INFOSCREEN_URL':\n                        cfg[k[len('INFOSCREEN_'):]] = v\n    for k in ['INFOSCREEN_URL','PROVISION_SECRET','PI_TOKEN','POLL_INTERVAL','BROWSER','DISPLAY','INFOSCREEN_IPV6']:\n        if os.environ.get(k): cfg[k] = os.environ[k]\n    return cfg\n\ndef save_token(token):\n    global TOKEN_FILE\n    # Try primary location first\n    try:\n        with open(TOKEN_FILE, 'w') as f: f.write(token)\n        os.chmod(TOKEN_FILE, 0o600)\n        log.info('Token saved to %s', TOKEN_FILE)\n        return\n    except PermissionError:\n        pass\n    except Exception as e:\n        log.warning('Token save error: %s', e)\n        return\n    # Fall back to home directory\n    home_token = os.path.expanduser(HOME_TOKEN)\n    try:\n        with open(home_token, 'w') as f: f.write(token)\n        os.chmod(home_token, 0o600)\n        log.info('Token saved to %s (fallback)', home_token)\n        TOKEN_FILE = home_token\n    except Exception as e2:\n        log.warning('Could not save token anywhere: %s', e2)\n\ndef load_saved_token():\n    for path in [TOKEN_FILE, os.path.expanduser(HOME_TOKEN)]:\n        if os.path.exists(path):\n            try:\n                with open(path) as f:\n                    t = f.read().strip()\n                    if t: return t\n            except: pass\n    return None\n\ndef get_hardware_info():\n    info = {'arch': os.uname().machine, 'hostname': socket.gethostname()}\n    # Boot-mode telemetry is deliberately read-only. It lets IT distinguish a\n    # screen that is actually running in UEFI from an x86 machine that merely\n    # has an ESP on disk while firmware is still in Legacy/CSM mode. The boot\n    # repair helper writes only non-secret verification fields here.\n    if os.uname().machine.lower() in ('x86_64', 'amd64', 'i386', 'i486', 'i586', 'i686'):\n        info['firmware_mode'] = 'uefi' if os.path.isdir('/sys/firmware/efi') else 'legacy-bios'\n        try:\n            bs = {}\n            with open(os.path.join(STATE_DIR, 'boot-status'), encoding='utf-8', errors='replace') as f:\n                for line in f:\n                    if '=' not in line:\n                        continue\n                    k, v = line.rstrip('\\r\\n').split('=', 1)\n                    if k in ('state','firmware','disk','root','esp','bios_ready','uefi_ready',\n                             'pmbr_boot','nvram_ready','message','checked_at'):\n                        bs[k] = v[:240]\n            if bs:\n                info['boot_status'] = bs\n        except Exception:\n            pass\n    # Which machine is this, exactly?\n    #\n    # /proc/device-tree/model only exists on a Pi. On a laptop it is absent, so\n    # 'model' was simply never set and the portal fell back to showing the CPU\n    # name from /proc/cpuinfo below — \"Intel(R) Core(TM) i5-1135G7\" tells you\n    # nothing about which machine is on which wall. DMI has the real answer.\n    def _dmi(field):\n        try:\n            with open(f'/sys/devices/virtual/dmi/id/{field}') as f:\n                v = f.read().strip()\n            junk = ('to be filled by o.e.m.', 'system product name', 'default string',\n                    'none', 'not specified', 'o.e.m.', '')\n            return '' if v.lower() in junk else v\n        except Exception:\n            return ''\n\n    try:\n        with open('/proc/device-tree/model') as f:\n            info['model'] = f.read().strip().replace('\\x00','')\n        info['vendor'] = 'Raspberry Pi Foundation'\n        info['form_factor'] = 'sbc'\n    except Exception:\n        vendor  = _dmi('sys_vendor')\n        product = _dmi('product_name')\n        version = _dmi('product_version')\n        parts = [x for x in (vendor, product) if x]\n        model = ' '.join(parts)\n        if version and version.lower() not in model.lower():\n            model = f'{model} {version}'.strip()\n        if model:\n            info['model'] = model\n        info['vendor'] = vendor or 'unknown'\n        info['product'] = product or 'unknown'\n        info['product_family'] = _dmi('product_family')\n        info['bios_version'] = _dmi('bios_version')\n        info['bios_date'] = _dmi('bios_date')\n        # SMBIOS chassis type. 8/9/10/14/31 are the portable ones; the portal\n        # uses this to decide which machine to draw.\n        chassis = _dmi('chassis_type')\n        info['form_factor'] = {\n            '3':'desktop','4':'desktop','6':'desktop','7':'desktop',\n            '8':'laptop','9':'laptop','10':'laptop','14':'laptop','31':'laptop',\n            '30':'tablet','32':'tablet','11':'handheld',\n        }.get(chassis, 'unknown')\n        info['chassis_type'] = chassis\n\n    # Report the *browser's actual launch choice* (not an optimistic GPU guess).\n    # The server can then serve a 720p/30 decode-friendly copy only to screens\n    # running in software mode, without reducing quality on modern PCs.\n    info['browser_gpu_accelerated'] = bool(globals().get('_launch', {}).get('gpu', False))\n    info['browser_is_pc'] = bool(_IS_PC)\n    try:\n        preference = str(os.environ.get('INFOSCREEN_VIDEO_PROFILE') or load_config().get('VIDEO_PROFILE', '')).strip().lower()\n        info['video_playback_profile'] = preference if preference in ('smooth', 'balanced', 'quality') else 'auto'\n    except Exception:\n        pass\n\n    # Physical port lockdown state, so the portal can draw the machine and\n    # colour each port by whether it is actually authorized.\n    try:\n        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n        import importlib.util as _ilu\n        _pg = os.path.join(os.path.dirname(os.path.abspath(__file__)), PORTGUARD_FILE)\n        if os.path.exists(_pg):\n            _spec = _ilu.spec_from_file_location('infoscreen_portguard', _pg)\n            _mod = _ilu.module_from_spec(_spec); _spec.loader.exec_module(_mod)\n            info['ports'] = _mod.port_inventory()\n    except Exception as e:\n        info['ports_error'] = str(e)\n    try:\n        with open('/proc/cpuinfo') as f:\n            for line in f:\n                if 'Model name' in line or 'Hardware' in line:\n                    info['cpu'] = line.split(':')[1].strip(); break\n    except: pass\n    for iface in ['eth0','wlan0','enp0s3','ens3','enp1s0']:\n        p = f'/sys/class/net/{iface}/address'\n        if os.path.exists(p):\n            with open(p) as f:\n                mac = f.read().strip()\n                if mac and mac != '00:00:00:00:00:00':\n                    info['mac'] = mac; info['iface'] = iface; break\n    return info\n\ndef provision(cfg):\n    server = cfg.get('INFOSCREEN_URL','').rstrip('/')\n    secret = cfg.get('PROVISION_SECRET','')\n    if not server or not secret:\n        log.error('INFOSCREEN_URL and PROVISION_SECRET must be set in %s', CONFIG_FILE)\n        return None\n    hw = get_hardware_info()\n    hostname = hw.get('hostname', socket.gethostname())\n    mac = hw.get('mac', '')\n    install_id = cfg.get('INSTALL_ID', '') or cfg.get('install_id', '')\n    try:\n        with open('/proc/sys/kernel/random/boot_id') as _f: boot_id = _f.read().strip()\n    except Exception: boot_id = ''\n    log.info('Provisioning: server=%s hostname=%s', server, hostname)\n    while True:\n        try:\n            r = requests.post(f'{server}/api/provision', json={\n                'secret': secret, 'hostname': hostname, 'install_id': install_id,\n                'mac_address': mac, 'boot_id': boot_id, 'hardware_info': json.dumps(hw)\n            }, timeout=15, verify=True)\n            if r.status_code == 403:\n                log.error('Provisioning disabled or wrong secret. Check server settings.')\n                time.sleep(60); continue\n            data = r.json()\n            status = data.get('status')\n            if status in ('approved','already_provisioned'):\n                token = data.get('api_token')\n                log.info('Provisioned successfully!')\n                save_token(token); return token\n            elif status == 'pending':\n                log.info('Awaiting IT approval — polling every 30s')\n                while True:\n                    time.sleep(30)\n                    try:\n                        pr = requests.get(f'{server}/api/provision/poll',\n                            params={'hostname': hostname, 'install_id': install_id, 'mac': mac},\n                            headers={'X-Provision-Secret': secret}, timeout=10)\n                        if pr.status_code in (401, 403):\n                            log.warning('Enrollment proof rejected; retrying authenticated enrollment')\n                            break\n                        pd = pr.json()\n                        if pd.get('status') == 'approved':\n                            token = pd.get('api_token')\n                            log.info('Approved!'); save_token(token); return token\n                        elif pd.get('status') in ('rejected', 'expired'):\n                            log.error('%s by IT. The hold screen will ask for a restart.', pd.get('status'))\n                            time.sleep(300); break\n                        else: log.info('Still pending...')\n                    except Exception as e: log.warning('Poll error: %s', e)\n            else:\n                log.error('Unexpected response: %s', data); time.sleep(60)\n        except Exception as e:\n            log.warning('Provision error: %s -- retry in 30s', e); time.sleep(30)\n\ndef get_metrics():\n    try:\n        cpu = psutil.cpu_percent(interval=1)\n        mem = psutil.virtual_memory()\n        disk = psutil.disk_usage('/')\n        uptime = int(time.time() - psutil.boot_time())\n        temp = None\n        for p in ['/sys/class/thermal/thermal_zone0/temp','/sys/class/thermal/thermal_zone1/temp']:\n            try:\n                with open(p) as f: temp = int(f.read().strip()) / 1000.0; break\n            except: pass\n        # Get local IP\n        local_ip = None\n        try:\n            import socket\n            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)\n            s.connect(('8.8.8.8', 80))\n            local_ip = s.getsockname()[0]\n            s.close()\n        except: pass\n        # Detect active network interface and WiFi SSID\n        net_iface = None\n        net_ssid = None\n        try:\n            import subprocess as _sp\n            # Find which interface the default route uses\n            route = _sp.run(['ip', 'route', 'get', '8.8.8.8'],\n                capture_output=True, text=True, timeout=5)\n            for part in route.stdout.split():\n                if part in ('dev',):\n                    idx = route.stdout.split().index(part)\n                    net_iface = route.stdout.split()[idx+1]\n                    break\n            # If wireless, get SSID\n            if net_iface and net_iface.startswith('w'):\n                ssid_r = _sp.run(['iwgetid', net_iface, '-r'],\n                    capture_output=True, text=True, timeout=5)\n                net_ssid = ssid_r.stdout.strip() or None\n                if not net_ssid:\n                    # try nmcli\n                    nm_r = _sp.run(['nmcli', '-t', '-f', 'active,ssid', 'dev', 'wifi'],\n                        capture_output=True, text=True, timeout=5)\n                    for line in nm_r.stdout.splitlines():\n                        if line.startswith('yes:'):\n                            net_ssid = line.split(':', 1)[1].strip()\n                            break\n        except: pass\n\n        # MAC + hostname ride along so the server can reconcile hardware: the\n        # identity lives on the SD card, but the board's MAC is how a re-pair is\n        # detected when the card is moved into a new Pi.\n        _hw = get_hardware_info()\n        # Screen resolution detection\n        screen_w, screen_h = 0, 0\n        try:\n            xr = subprocess.run(['xrandr', '--current'], capture_output=True, text=True, timeout=5)\n            for line in xr.stdout.splitlines():\n                if '*' in line:\n                    parts = line.strip().split()\n                    if parts and 'x' in parts[0]:\n                        w, h = parts[0].split('x')\n                        screen_w, screen_h = int(w), int(h)\n                        break\n        except: pass\n        # Fallback: check fbset\n        if not screen_w:\n            try:\n                fb = subprocess.run(['fbset', '-s'], capture_output=True, text=True, timeout=5)\n                for line in fb.stdout.splitlines():\n                    if 'geometry' in line:\n                        parts = line.strip().split()\n                        if len(parts) >= 3:\n                            screen_w, screen_h = int(parts[1]), int(parts[2])\n                        break\n            except: pass\n        # The full screen bundle contains root-owned kiosk helpers.  On hardened\n        # installs the Python agent intentionally cannot overwrite those files;\n        # the small infoscreen-commands service runs as root and owns image/bundle\n        # updates.  Report whether that runner is actually available so the\n        # server can route image_update jobs to the right process instead of\n        # letting a non-root agent claim a job it cannot finish (v4.9.10).\n        command_runner_ready = False\n        runner = RUNNER_BIN\n        if os.path.isfile(runner) and os.access(runner, os.X_OK):\n            try:\n                if shutil.which('systemctl'):\n                    rr = subprocess.run(['systemctl', 'is-active', '--quiet', RUNNER_SVC],\n                                        timeout=3)\n                    command_runner_ready = rr.returncode == 0\n                elif shutil.which('rc-service'):\n                    rr = subprocess.run(['rc-service', RUNNER_SVC, 'status'],\n                                        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=3)\n                    command_runner_ready = rr.returncode == 0\n                else:\n                    # Very old images have no service manager command in PATH,\n                    # but an executable runner is still better than pretending it\n                    # is absent; the server's compatibility poll will verify it.\n                    command_runner_ready = True\n            except Exception:\n                command_runner_ready = False\n\n        return {'cpu_load': round(cpu,1), 'cpu_temp': round(temp,1) if temp else None,\n                'memory_used': mem.used, 'memory_total': mem.total,\n                'disk_used': disk.used, 'disk_total': disk.total,\n                'uptime': uptime, 'os_version': os.uname().release,\n                'local_ip': local_ip,\n                'agent_version': AGENT_VERSION,\n                # Which process sent this. Two agents on one screen (the Pi's\n                # systemd unit plus its openbox autostart) both send\n                # heartbeats; the server spots two PIDs and says so (v4.1.1).\n                'agent_pid': os.getpid(),\n                'agent_user': (os.getenv('USER') or str(os.getuid())),\n                'command_runner_ready': command_runner_ready,\n                'net_iface': net_iface,\n                'net_ssid': net_ssid,\n                'network_ipv4_preferred': bool(_net_family.get('prefer_ipv4')),\n                'network_family_reason': str(_net_family.get('reason') or '')[:160],\n                'mac_address': _hw.get('mac', ''),\n                'hardware_info': json.dumps(_hw),\n                'apt_updates': _apt_updates.get('count', 0),\n                'reboot_required': _apt_updates.get('reboot_required', False),\n                'screen_width': screen_w,\n                'screen_height': screen_h}\n    except Exception as e:\n        log.warning('metrics error: %s', e); return {}\n\nbrowser_proc = None\ncurrent_viewer_url = None\n# Referenced by the update/heal paths as a fallback token. It was used but\n# never assigned before v4.0.0, so those paths raised NameError whenever the\n# local token was empty.\n_pi_token = ''\n\ndef kill_browser():\n    global browser_proc\n    if browser_proc and browser_proc.poll() is None:\n        browser_proc.terminate()\n        try: browser_proc.wait(timeout=5)\n        except: browser_proc.kill()\n    browser_proc = None\n    os.system('pkill -f chromium 2>/dev/null; pkill -f firefox 2>/dev/null')\n    time.sleep(1)\n\ndef find_browser(preferred=''):\n    \"\"\"Auto-detect chromium binary name.\"\"\"\n    candidates = []\n    if preferred: candidates.append(preferred)\n    candidates += ['chromium', 'chromium-browser', 'google-chrome', 'firefox-esr', 'firefox']\n    for b in candidates:\n        result = os.popen(f'which {b} 2>/dev/null').read().strip()\n        if result: return b\n    return None\n\n# ── The kiosk window on PCs and laptops (v4.8.3) ─────────────────────\n# Found on a Dell laptop: Chromium in a white 945×1060 window in the top-left\n# corner, the rest of the screen black. That is Chromium's default size for a\n# new window on a 1920×1080 screen (half the width, the height less 20 px, at\n# 10,10). --kiosk asks the window manager for fullscreen once, when the window\n# opens, and Openbox has to be running already to act on it. On the laptop\n# the agent outlives an X restart (its loop runs in the background), and the\n# watchdog relaunched Chromium into the new X before the new Openbox was up.\n# Reproduced under Xvfb: with no window manager, and with Openbox starting 4 s\n# after Chromium, the window is exactly 945×1060+10+10. So now:\n#   - the browser waits (at most 15 s) for a window manager before it opens;\n#   - it is told the screen's size and position, which covers the screen even\n#     with no window manager at all;\n#   - (v4.8.3 to 4.9.3 opened a local start page first. The kiosk policy\n#     from harden-kiosk.sh blocks file:// URLs, so on the screens that page\n#     showed «This page is blocked» instead of the viewer. v4.9.4 opens the\n#     viewer directly again; the dark first frame below keeps it from\n#     flashing white);\n#   - the window guard checks that the browser covers the screen and puts it\n#     right if not (a fullscreen request to the window manager, and a direct\n#     resize, which works without one).\n_IS_PC = not os.path.exists('/proc/device-tree/model')   # a Pi has a device tree; a PC or laptop does not\n_launch = {'at': 0.0, 'gpu': False, 'early_exits': 0, 'gpu_off': False, 'crash_artifact': 0.0, 'crash_restarts': 0,\n           'policy_sig': None, 'policy_restart_at': 0.0}\n\n\ndef _policy_sig():\n    \"\"\"The Chromium policy files as they are now. Chromium applies some\n    policies (which extensions may load) only when it starts, so a lockdown run\n    that changes them must be followed by a browser restart (v4.9.56).\"\"\"\n    import glob as _g\n    h = hashlib.sha256()\n    for f in sorted(_g.glob('/etc/chromium/policies/managed/*.json') + _g.glob('/etc/chromium-browser/policies/managed/*.json')\n                    + _g.glob('/etc/opt/chrome/policies/managed/*.json')):\n        try:\n            h.update(f.encode()); h.update(open(f, 'rb').read())\n        except OSError:\n            pass\n    return h.hexdigest()\n\ndef _gpu_vendor():\n    \"\"\"'intel', 'amd', 'nvidia' or 'other' for the first display card, '' if none.\"\"\"\n    try:\n        for c in sorted(os.listdir('/sys/class/drm')):\n            p = f'/sys/class/drm/{c}/device/vendor'\n            if re.fullmatch(r'card\\d+', c) and os.path.exists(p):\n                with open(p) as f:\n                    return {'0x8086': 'intel', '0x1002': 'amd', '0x10de': 'nvidia'}.get(f.read().strip().lower(), 'other')\n    except Exception:\n        pass\n    return ''\n\ndef _gpu_device_id():\n    \"\"\"PCI device id for the first DRM card, e.g. ``0x1616``.\"\"\"\n    try:\n        for c in sorted(os.listdir('/sys/class/drm')):\n            p = f'/sys/class/drm/{c}/device/device'\n            if re.fullmatch(r'card\\d+', c) and os.path.exists(p):\n                with open(p) as f:\n                    return f.read().strip().lower()\n    except Exception:\n        pass\n    return ''\n\n\ndef _legacy_intel_gpu():\n    \"\"\"Older Intel iGPUs are deliberately conservative in kiosk mode.\n\n    Field diagnostics from the Dell laptop (Broadwell 0x1616) showed repeated\n    Chromium sad-tab renderer crashes while memory and the i915 kernel driver\n    stayed healthy.  Chromium also attempted a Vulkan/Dawn path with no Vulkan\n    driver installed.  Software compositing is preferable to an ``Aw, Snap!``\n    screen in a public kiosk.  INFOSCREEN_GPU=1 remains an explicit override.\n    \"\"\"\n    if _gpu_vendor() != 'intel':\n        return False\n    dev = _gpu_device_id()\n    # Haswell/Broadwell display ids are mainly 04xx/0axx/0dxx/16xx.  Keep the\n    # rule intentionally narrow; newer Intel generations retain acceleration.\n    return bool(re.fullmatch(r'0x(?:04|0a|0d|16)[0-9a-f]{2}', dev or ''))\n\n\ndef _crash_artifact_mtime():\n    \"\"\"Newest Chromium crash artifact seen on this machine.\n\n    A renderer can die while the browser parent remains alive, so process-only\n    watchdogs miss the sad-tab.  Crashpad normally writes a fresh report/meta\n    file for that case.  Watching its timestamp gives us a second recovery\n    signal without enabling remote debugging on the locked kiosk browser.\n    \"\"\"\n    homes = {'/root', '/home/kiosk', '/home/pi', os.path.expanduser('~')}\n    _prof = _own_tmp('infoscreen-browser')\n    roots = [os.path.join(_prof, 'Crashpad'), os.path.join(_prof, 'Crash Reports')]\n    for home in homes:\n        if home:\n            roots += [os.path.join(home, '.config/chromium/Crash Reports'),\n                      os.path.join(home, '.config/google-chrome/Crash Reports')]\n    newest = 0.0\n    for root in roots:\n        try:\n            if not os.path.isdir(root):\n                continue\n            for base, dirs, files in os.walk(root):\n                # Crash report trees are shallow.  Avoid wandering through an\n                # accidentally large profile if a distro layout changes.\n                if base[len(root):].count(os.sep) > 3:\n                    dirs[:] = []\n                    continue\n                for name in files:\n                    if not re.search(r'\\.(?:dmp|meta)$', name, re.I) and name not in ('pending', 'completed'):\n                        continue\n                    try:\n                        newest = max(newest, os.path.getmtime(os.path.join(base, name)))\n                    except OSError:\n                        pass\n        except Exception:\n            pass\n    return newest\n\ndef _gpu_default_on():\n    \"\"\"Use hardware compositing where field data says it is reliable.\n\n    Pi remains software rendered.  PCs with modern Intel/AMD stay accelerated,\n    while older Intel Haswell/Broadwell defaults to the safer software path\n    after repeated field renderer crashes.  INFOSCREEN_GPU=1 always overrides.\n    \"\"\"\n    return (_IS_PC and not _launch['gpu_off'] and not _legacy_intel_gpu()\n            and _gpu_vendor() in ('intel', 'amd') and os.path.exists('/dev/dri/renderD128'))\n\ndef _xlib_display(display):\n    from Xlib import display as xdisplay\n    env = _display_env(display)\n    if env.get('XAUTHORITY'):\n        os.environ.setdefault('XAUTHORITY', env['XAUTHORITY'])\n    return xdisplay.Display(env['DISPLAY'])\n\ndef _screen_size(display):\n    \"\"\"The X screen's size in pixels, or (0, 0) if it cannot be read.\"\"\"\n    try:\n        if _import_xlib():\n            d = _xlib_display(display)\n            try:\n                g = d.screen().root.get_geometry()\n                return g.width, g.height\n            finally:\n                d.close()\n    except Exception:\n        pass\n    try:\n        out = subprocess.run(['xrandr', '--current'], capture_output=True, text=True, timeout=5,\n                             env=_display_env(display)).stdout\n        m = re.search(r'current (\\d+) x (\\d+)', out)\n        if m:\n            return int(m.group(1)), int(m.group(2))\n    except Exception:\n        pass\n    return 0, 0\n\ndef _wm_running(display):\n    \"\"\"True when a window manager runs (EWMH _NET_SUPPORTING_WM_CHECK on the\n    root window), False when none does, None when that cannot be told.\"\"\"\n    try:\n        if not _import_xlib():\n            return None\n        d = _xlib_display(display)\n        try:\n            # EWMH: the root names a check window, which must still exist and\n            # name itself. A window manager that died leaves the root's\n            # property behind; its check window is gone with it.\n            atom = d.intern_atom('_NET_SUPPORTING_WM_CHECK')\n            p = d.screen().root.get_full_property(atom, 0)\n            if not (p and p.value):\n                return False\n            wid = int(p.value[0])\n            try:\n                q = d.create_resource_object('window', wid).get_full_property(atom, 0)\n            except Exception:\n                return False\n            return bool(q and q.value and int(q.value[0]) == wid)\n        finally:\n            d.close()\n    except Exception:\n        return None\n\ndef _wait_for_wm(display, timeout=30):\n    \"\"\"Wait for a usable X display, then preferably a window manager.\n\n    Before v4.9.43 `_wm_running()` returned None when X itself did not exist and\n    the caller treated None as success. The agent therefore launched Chromium\n    during boot before :0 existed, producing the field error \"Missing X server\n    or $DISPLAY\", then entered a crash/restart race. A screen geometry is now\n    required before Chromium is ever started.\n    \"\"\"\n    t0 = time.time()\n    display_seen = False\n    while time.time() - t0 < timeout:\n        sw, sh = _screen_size(display)\n        if not (sw and sh):\n            time.sleep(0.5)\n            continue\n        display_seen = True\n        up = _wm_running(display)\n        if up is None or up:\n            return True\n        time.sleep(0.5)\n    if display_seen:\n        log.warning('No window manager after %d s: opening the browser anyway, sized to the screen', timeout)\n        return True\n    log.warning('X display %s was not ready after %d s; browser launch deferred to watchdog', display, timeout)\n    return False\n\n# ── Screen resolution chosen in the portal (v4.9.70) ──────────────────\n# X picks the monitor's preferred mode from its EDID. Some screens report a\n# mode that is not what they should run (an ultrawide EDID behind a 1920x1080\n# panel, a KVM or adapter that passes on the wrong one). The portal's\n# «Skjermoppløsning» sets it; «auto» leaves X alone, as before. The choice is\n# kept on disk so it is applied before the browser starts after a reboot.\nDISPLAY_MODE_FILE = os.path.join(AGENT_DIR, 'display-mode')\n_display_mode = {'applied': None, 'loaded': False}\n_DISPLAY_MODE_RE = re.compile(r'^(auto|\\d{3,4}x\\d{3,4})$')\n\n# What «auto» means per hardware model (v4.9.70). The Dell Wyse D-class\n# (D50D/D90D, Radeon HD 6250) drives 2560x1600 over DisplayPort at its limit:\n# the monitor dropped out and came back every 100 s (a black flash). Those\n# thin clients only ever drive 1920x1080 screens, so that is their «auto».\n# /etc/infoscreen/display-mode-default (written by the installer, or by hand)\n# takes precedence over the built-in table; the portal's choice over both.\nMODEL_DISPLAY_DEFAULTS = {'D CLASS': '1920x1080'}\nDISPLAY_DEFAULT_FILE = '/etc/infoscreen/display-mode-default'\n\n\ndef _model_display_default():\n    try:\n        v = open(DISPLAY_DEFAULT_FILE).read().strip().lower()\n        if _DISPLAY_MODE_RE.match(v):\n            return '' if v == 'auto' else v\n    except OSError:\n        pass\n    try:\n        product = open('/sys/devices/virtual/dmi/id/product_name').read().strip().upper()\n    except OSError:\n        return ''\n    return MODEL_DISPLAY_DEFAULTS.get(product, '')\n\n\ndef _xrandr_outputs(display):\n    \"\"\"Connected outputs as [(name, is_primary, [mode names])], primary first.\"\"\"\n    try:\n        out = subprocess.run(['xrandr', '--query'], capture_output=True, text=True, timeout=8,\n                             env=_display_env(display)).stdout\n    except Exception:\n        return []\n    outs, cur = [], None\n    for line in out.splitlines():\n        m = re.match(r'^(\\S+) connected( primary)?', line)\n        if m:\n            cur = (m.group(1), bool(m.group(2)), [])\n            outs.append(cur)\n            continue\n        if re.match(r'^\\S', line):\n            cur = None\n            continue\n        if cur is not None:\n            t = line.split()\n            if t:\n                cur[2].append(t[0])\n    outs.sort(key=lambda o: not o[1])\n    return outs\n\n\ndef _xrandr(args, display):\n    r = subprocess.run(['xrandr'] + args, capture_output=True, text=True, timeout=10, env=_display_env(display))\n    return r.returncode == 0, (r.stderr or r.stdout or '').strip()[-200:]\n\n\ndef apply_display_mode(mode, display):\n    \"\"\"Set every connected output to `mode` ('auto' or 'WxH'). True if it took.\"\"\"\n    mode = str(mode or 'auto').strip().lower()\n    if not _DISPLAY_MODE_RE.match(mode):\n        log.warning('Display mode %r ignored (expected auto or WIDTHxHEIGHT)', mode)\n        return False\n    outs = _xrandr_outputs(display)\n    if not outs:\n        log.warning('Display mode %s: xrandr found no connected output', mode)\n        return False\n    ok_all = True\n    for name, _primary, modes in outs:\n        if mode == 'auto':\n            ok, err = _xrandr(['--output', name, '--auto'], display)\n        elif mode in modes:\n            ok, err = _xrandr(['--output', name, '--mode', mode], display)\n        else:\n            # Not in the monitor's list: make it (CVT timings, 60 Hz) and use it.\n            w, h = mode.split('x')\n            ok, err = False, 'cvt failed'\n            try:\n                cvt = subprocess.run(['cvt', w, h, '60'], capture_output=True, text=True, timeout=5).stdout\n                ml = next((l for l in cvt.splitlines() if l.startswith('Modeline')), '')\n                parts = ml.split()\n                if len(parts) > 2:\n                    new = f'{mode}_60'\n                    _xrandr(['--newmode', new] + parts[2:], display)\n                    _xrandr(['--addmode', name, new], display)\n                    ok, err = _xrandr(['--output', name, '--mode', new], display)\n            except Exception as e:\n                err = str(e)\n        if ok:\n            log.info('Display %s set to %s', name, mode)\n        else:\n            ok_all = False\n            log.warning('Display %s could not be set to %s: %s', name, mode, err)\n    return ok_all\n\n\ndef _saved_display_mode():\n    try:\n        v = open(DISPLAY_MODE_FILE).read().strip()\n        return v if _DISPLAY_MODE_RE.match(v) else 'auto'\n    except OSError:\n        return _model_display_default() or 'auto'\n\n\ndef want_display_mode(mode, display):\n    \"\"\"The server's choice for this screen. Returns True when the screen\n    size changed (the browser must be restarted to fill it).\"\"\"\n    mode = str(mode or 'auto').strip().lower()\n    if not _DISPLAY_MODE_RE.match(mode):\n        mode = 'auto'\n    if mode == 'auto':\n        mode = _model_display_default() or 'auto'   # this model's own default\n    if mode == _display_mode['applied']:\n        return False\n    before = _screen_size(display)\n    previous = _display_mode['applied'] or _saved_display_mode()\n    try:\n        with open(DISPLAY_MODE_FILE, 'w') as f:\n            f.write(mode + '\\n')\n    except OSError as e:\n        log.debug('display mode not saved: %s', e)\n    # «auto» on a screen that was never forced changes nothing (as before 4.9.70).\n    if mode == 'auto' and previous == 'auto':\n        _display_mode['applied'] = mode\n        return False\n    apply_display_mode(mode, display)\n    _display_mode['applied'] = mode\n    return _screen_size(display) != before\n\n\ndef _apply_saved_display_mode(display):\n    \"\"\"Once per agent run, before the first browser start.\"\"\"\n    if _display_mode['loaded']:\n        return\n    _display_mode['loaded'] = True\n    mode = _saved_display_mode()\n    if mode != 'auto':\n        apply_display_mode(mode, display)\n    _display_mode['applied'] = mode\n\n\ndef open_url(url, browser, display, _maint_ok=False):\n    global browser_proc\n    # Physical maintenance owns the screen: a routine navigation (a config\n    # push, a reconnect) is remembered for the end, not performed now, or the\n    # maintenance page would vanish mid-session.\n    if not _maint_ok and _maint and _maint.get('mode') == 'physical':\n        if '/viewer/maintenance' not in url:\n            _maint['viewer_url'] = url\n            return\n    if not _wait_for_wm(display):\n        return False               # watchdog retries after X/Openbox is ready\n    try:\n        _apply_saved_display_mode(display)\n    except Exception as e:\n        log.warning('saved display mode not applied: %s', e)\n    kill_browser()\n    env = os.environ.copy()\n    env['DISPLAY'] = display\n\n    # Find Xauthority — check both user home and root\n    for user in [os.environ.get('USER', 'pi'), 'pi', 'kiosk', 'root']:\n        xauth = f'/home/{user}/.Xauthority'\n        if os.path.exists(xauth):\n            env['XAUTHORITY'] = xauth\n            break\n    if not env.get('XAUTHORITY') and os.path.exists('/root/.Xauthority'):\n        env['XAUTHORITY'] = '/root/.Xauthority'\n\n    # A fresh profile on every launch (v4.5.0): nothing for Ctrl+Shift+T to\n    # restore, no history, and no old /viewer?token= addresses from before\n    # v4.4.1 lying around in a session file.\n    profile_dir = _own_tmp('infoscreen-browser')   # v4.9.53: never a root-owned leftover\n    shutil.rmtree(profile_dir, ignore_errors=True)\n\n    b = find_browser(browser)\n    if not b:\n        log.error('No browser found! Install chromium.')\n        return False\n\n    # Auto fallback only when the control server has proven working IPv4 and\n    # broken IPv6. This leaves IPv6 enabled on healthy networks.\n    _server_for_family = (_cfg or {}).get('server', '') if isinstance(_cfg, dict) else ''\n    prefer_ipv4 = configure_network_family(_server_for_family) if _server_for_family else bool(_net_family.get('prefer_ipv4'))\n\n    cmd = [b,\n        '--kiosk',\n        '--noerrdialogs',\n        '--disable-infobars',\n        '--no-first-run',\n        '--disable-session-crashed-bubble',\n        '--disable-restore-session-state',\n        # DisableLoadExtensionCommandLineSwitch: Google Chrome 137+ ignores\n        # --load-extension unless this is off. Chromium builds are unaffected;\n        # the flag is harmless there and keeps a Chrome-based box working.\n        '--disable-features=Translate,TranslateUI,ExternalProtocolDialog,DisableLoadExtensionCommandLineSwitch,Vulkan,DefaultANGLEVulkan,WebGPU',\n        '--disable-pinch',\n        '--overscroll-history-navigation=0',\n        '--check-for-update-interval=31536000',\n        '--disable-dev-shm-usage',\n        '--disable-external-intent-requests',\n        '--autoplay-policy=no-user-gesture-required',\n        f'--lang={_browser_lang()}',\n        f'--accept-lang={_browser_lang()},nb,sv,en',\n        f'--user-data-dir={profile_dir}',\n        url]\n\n    if prefer_ipv4:\n        cmd.insert(-1, '--disable-ipv6')\n        # --disable-ipv6 has not behaved consistently across Chromium builds.\n        # Pin *only* the control server hostname to the A record we just proved\n        # reachable. This avoids the field failure where every /viewer/config\n        # request spent ~8 s on a dead AAAA address before trying IPv4. It does\n        # not change DNS for third-party content and keeps HTTPS hostname/SNI.\n        try:\n            parsed = urllib.parse.urlparse(_server_for_family if '://' in _server_for_family else 'https://' + _server_for_family)\n            host = parsed.hostname or str(_net_family.get('host') or '')\n            port = parsed.port or (443 if parsed.scheme == 'https' else 80)\n            ipv4 = _resolved_ipv4(host, port) if host else ''\n            if host and ipv4:\n                _net_family['host'] = host; _net_family['ipv4'] = ipv4\n                cmd.insert(-1, f'--host-resolver-rules=MAP {host} {ipv4}')\n                log.info('Chromium control host pinned to IPv4 because IPv6 path is broken: %s', host)\n        except Exception as e:\n            log.debug('Could not add Chromium IPv4 host mapping: %s', e)\n\n    # Chromium refuses to start as uid 0 unless --no-sandbox is present.\n    # Raspberry Pi installs normally run the agent as kiosk, while some older\n    # Alpine laptop images run it as root. v4.9.26 removed --no-sandbox for all\n    # machines and those root-run laptops therefore produced a completely black\n    # screen: Chromium exited before creating a window. Keep the sandbox for\n    # every non-root screen, but add the required flag when the process itself\n    # is root. An explicit compatibility override remains available (v4.9.27).\n    no_sandbox_override = str(os.environ.get('INFOSCREEN_CHROME_NO_SANDBOX', '')).strip().lower() in ('1', 'true', 'yes', 'on')\n    if os.geteuid() == 0 or no_sandbox_override:\n        cmd.insert(-1, '--no-sandbox')\n        if os.geteuid() == 0:\n            log.warning('Chromium is being launched by a root-run legacy agent; using --no-sandbox so the kiosk can start. Reinstalling the service as kiosk is recommended.')\n        else:\n            log.warning('Chromium sandbox explicitly disabled by INFOSCREEN_CHROME_NO_SANDBOX=1')\n\n    # GPU (v4.8.3): off on a Pi, as every Pi in the field runs (video is then\n    # decoded and composited in software, which drops frames above 720p on a\n    # Pi 4); on for PCs and laptops with Intel or AMD graphics, where it is what\n    # makes fades and video smooth (_gpu_default_on). INFOSCREEN_GPU=1 in\n    # /etc/infoscreen.env forces it on (past Chromium's blocklist too), =0 off.\n    flag = str(_load_gpu_flag()).strip().lower()\n    if flag in ('1', 'true', 'yes', 'on'):\n        gpu_on = True\n        cmd.insert(-1, '--ignore-gpu-blocklist')\n        log.info('GPU acceleration forced on for this screen (INFOSCREEN_GPU=1)')\n    elif flag in ('0', 'false', 'no', 'off') or not _gpu_default_on():\n        gpu_on = False\n        cmd.insert(-1, '--disable-gpu')\n        if flag not in ('0', 'false', 'no', 'off') and _legacy_intel_gpu():\n            log.warning('Older Intel GPU %s detected: safe software rendering enabled to avoid Chromium renderer crashes. INFOSCREEN_GPU=1 overrides.', _gpu_device_id() or 'unknown')\n    else:\n        gpu_on = True\n        log.info('GPU acceleration on (PC with %s graphics; INFOSCREEN_GPU=0 in /etc/infoscreen.env turns it off)', _gpu_vendor())\n\n    # The whole screen, whatever the window manager does (v4.8.3, see _wait_for_wm).\n    sw, sh = _screen_size(display)\n    if sw and sh:\n        cmd.insert(-1, '--window-position=0,0')\n        cmd.insert(-1, f'--window-size={sw},{sh}')\n    cmd.insert(-1, '--start-fullscreen')\n    # No keyring lookups: on a machine without a keyring they can hold the\n    # new window at its first size for many seconds.\n    cmd.insert(-1, '--password-store=basic')\n    # A new Chromium window is white for its first frames (about 90 ms,\n    # measured) before the page paints: a white flash at every browser start.\n    # With the browser's own theme dark that frame is dark. Web pages keep\n    # the light colour scheme they always had (preferredColorScheme=1 is\n    # light): only Chromium's own surfaces change, and a kiosk shows none.\n    cmd.insert(-1, '--force-dark-mode')\n    # v4.9.58: page and extension console lines (and uncaught script errors)\n    # into the start log, which diagnostics show. That is how we can see\n    # whether the screen helper runs inside a website's video player at all.\n    cmd.insert(-1, '--enable-logging=stderr')\n    cmd.insert(-1, '--log-level=0')\n    cmd.insert(-1, '--blink-settings=preferredColorScheme=1')\n    # v4.9.64: no sound device. The screens are silent (uploaded videos are\n    # stored without sound), but a website video (YouTube always has a sound\n    # track) is played against the machine's audio output, and its clock\n    # drives the picture. A Pi or laptop whose ALSA/PulseAudio output opens\n    # but never plays held YouTube at the first fraction of a second with\n    # seconds of data buffered (readyState 1). Chromium's fake output plays\n    # silence on a timer, so the picture always runs. AUDIO=1 in\n    # /etc/infoscreen.env keeps the real sound device for a screen with speakers.\n    if str(_load_audio_flag()).strip().lower() in ('1', 'true', 'yes', 'on'):\n        log.info('Sound on for this screen (INFOSCREEN_AUDIO=1)')\n    else:\n        cmd.insert(-1, '--disable-audio-output')\n\n    ext_dir = os.path.join(AGENT_DIR, 'cookie-dismiss')\n    if os.path.isfile(os.path.join(ext_dir, 'manifest.json')):\n        cmd.insert(-1, f'--load-extension={ext_dir}')\n        cmd.insert(-1, f'--disable-extensions-except={ext_dir}')\n        log.info('Consent extension loaded from %s', ext_dir)\n    else:\n        # Say it out loud. Chromium starts perfectly happily without it and\n        # gives no indication that the flag pointed at nothing.\n        log.warning('NO consent extension at %s — cookie banners WILL show', ext_dir)\n\n    # v4.9.4: straight to the viewer. The kiosk policy (harden-kiosk.sh)\n    # blocks file:// URLs, so the local start page of 4.8.3 to 4.9.3 was never\n    # shown on the screens: they showed «This page is blocked» instead.\n    try:\n        log.info('Opening %s -> %s', b, url)\n        # Keep stderr for the first few seconds. Sending it to /dev/null hid the\n        # exact reason for black-screen failures such as Chromium's root/sandbox\n        # refusal. A small temporary file avoids pipe back-pressure on a kiosk\n        # that stays open for weeks (v4.9.27).\n        err_path = _own_tmp('infoscreen-chromium-last.log')\n        # Append mode, so the watchdog can cut the file down while Chromium\n        # keeps writing to it (v4.9.58: it now also carries console lines).\n        try: os.remove(err_path)\n        except OSError: pass\n        err_fh = open(err_path, 'ab')\n        browser_proc = subprocess.Popen(cmd, env=env,\n            stdout=subprocess.DEVNULL, stderr=err_fh)\n        err_fh.close()\n        _launch.update(at=time.time(), gpu=gpu_on, policy_sig=_policy_sig())\n        time.sleep(1.2)\n        _launch['crash_artifact'] = _crash_artifact_mtime()\n        rc = browser_proc.poll()\n        if rc is not None:\n            try:\n                detail = open(err_path, 'r', errors='replace').read()[-3000:].strip()\n            except Exception:\n                detail = ''\n            log.error('Chromium exited immediately (rc=%s): %s', rc, detail or 'no stderr')\n            # One conservative recovery attempt. GPU/driver startup faults are\n            # another common cause of a black kiosk on mixed laptop hardware.\n            # Do not loop endlessly: the normal process watchdog will retry.\n            if '--disable-gpu' not in cmd:\n                retry = list(cmd)\n                retry.insert(-1, '--disable-gpu')\n                log.warning('Retrying Chromium once with GPU disabled')\n                err_fh = open(err_path, 'ab')\n                browser_proc = subprocess.Popen(retry, env=env,\n                    stdout=subprocess.DEVNULL, stderr=err_fh)\n                err_fh.close()\n                _launch.update(at=time.time(), gpu=False, gpu_off=True)\n        return True\n    except Exception as e:\n        log.error('Failed to open browser: %s', e)\n        return False\n\ndef _load_gpu_flag():\n    try:\n        return load_config().get('GPU', '')\n    except Exception:\n        return ''\n\ndef _load_audio_flag():\n    try:\n        return load_config().get('AUDIO', '')\n    except Exception:\n        return ''\n\ndef show_blank(display):\n    kill_browser()\n    os.system(f'DISPLAY={display} xset s off 2>/dev/null')\n    os.system(f'DISPLAY={display} xset -dpms 2>/dev/null')\n    os.system(f'DISPLAY={display} xsetroot -solid black 2>/dev/null')\n\ncurrent_hold_state = None\n\ndef show_hold(server, browser, display, state, token='', cfg=None):\n    \"\"\"Point the kiosk browser at the branded hold/fault screen.\n\n    Shown whenever the screen is not authorised to display content — awaiting\n    approval, revoked, or being re-paired. The page itself polls /authorised and\n    jumps to the content viewer the moment the state clears, so this does not\n    have to be torn down explicitly.\n    \"\"\"\n    global current_hold_state, current_viewer_url\n    cfg = cfg or _cfg or {}\n    install = (cfg.get('INSTALL_ID') or cfg.get('install_id') or '') if isinstance(cfg, dict) else ''\n    host = socket.gethostname()\n    params = []\n    if token:   params.append('token=' + urllib.parse.quote(token))\n    if install: params.append('install=' + urllib.parse.quote(install))\n    if host:    params.append('host=' + urllib.parse.quote(host))\n    if state:   params.append('state=' + urllib.parse.quote(state))\n    url = f\"{server}/hold\" + ('?' + '&'.join(params) if params else '')\n    # Only re-open when the state actually changed, so we don't restart the\n    # browser on every heartbeat while a screen sits waiting for approval.\n    if current_hold_state == state and current_viewer_url == url:\n        return\n    log.info('Hold screen: %s', state)\n    open_url(url, browser, display)\n    current_hold_state = state\n    current_viewer_url = url\n\n_journal_last_cursor = None\n\ndef journal_forwarder(server, get_token):\n    \"\"\"Periodically read new systemd journal lines and send to server.\n\n    Alpine laptop images use OpenRC and have no journalctl.  Older agents tried\n    it every minute forever, filling the local log with a warning that could\n    never recover.  Skip the forwarder cleanly there; portal terminal and the\n    normal agent event stream remain available.\n    \"\"\"\n    global _journal_last_cursor\n    if not shutil.which('journalctl'):\n        log.info('journalctl is not available (OpenRC/Alpine); systemd journal forwarding disabled')\n        return\n    time.sleep(30)  # let agent settle before first send\n    while True:\n        try:\n            token = get_token()\n            # Read ALL journal entries (not just infoscreen-agent)\n            cmd = ['journalctl', '--no-pager', '-o', 'json']\n            if _journal_last_cursor:\n                cmd += ['--after-cursor', _journal_last_cursor]\n            else:\n                cmd += ['--since', '5 min ago']\n\n            r = subprocess.run(cmd, capture_output=True, text=True, timeout=15)\n            if r.returncode != 0:\n                time.sleep(300)\n                continue\n\n            lines_out = []\n            last_cursor = _journal_last_cursor\n            for raw_line in r.stdout.strip().splitlines():\n                if not raw_line.strip():\n                    continue\n                try:\n                    entry = json.loads(raw_line)\n                except json.JSONDecodeError:\n                    continue\n                cursor = entry.get('__CURSOR', '')\n                # Skip the cursor entry itself (--after-cursor is exclusive but just in case)\n                if cursor == _journal_last_cursor:\n                    continue\n                ts_us = entry.get('__REALTIME_TIMESTAMP', '')\n                if ts_us:\n                    ts = time.strftime('%Y-%m-%dT%H:%M:%S', time.localtime(int(ts_us) / 1_000_000))\n                else:\n                    ts = time.strftime('%Y-%m-%dT%H:%M:%S')\n                msg = entry.get('MESSAGE', '')\n                if isinstance(msg, list):\n                    msg = ' '.join(str(m) for m in msg)\n                unit = entry.get('_SYSTEMD_UNIT', entry.get('SYSLOG_IDENTIFIER', ''))\n                priority = entry.get('PRIORITY', '6')  # 0=emerg..7=debug\n                if msg:\n                    lines_out.append({'ts': ts, 'msg': msg, 'unit': unit, 'pri': str(priority)})\n                if cursor:\n                    last_cursor = cursor\n\n            if lines_out:\n                requests.post(f'{server}/api/pi/logs/bulk',\n                    json={'lines': lines_out[-500:]},\n                    headers={'X-Pi-Token': token}, timeout=10)\n                log.info('Forwarded %d journal lines to server', len(lines_out))\n\n            if last_cursor:\n                _journal_last_cursor = last_cursor\n\n        except Exception as e:\n            log.warning('Journal forwarding error: %s', e)\n\n        time.sleep(60)  # every 60 seconds\n\ndef log_event(server, token, event, detail=None, retries=1):\n    \"\"\"Send an event to the server and report whether it was accepted.\n\n    Before v4.9.9 this swallowed every network/HTTP error. For maintenance jobs\n    that made a failed result indistinguishable from a screen that never ran the\n    command. Critical callers can ask for a few short retries.\n    \"\"\"\n    attempts = max(1, int(retries or 1))\n    for attempt in range(attempts):\n        try:\n            r = requests.post(f'{server}/api/pi/log', json={'event':event,'detail':detail},\n                headers={'X-Pi-Token':token}, timeout=7)\n            if 200 <= r.status_code < 300:\n                return True\n            log.warning('Event %s rejected by server: HTTP %s', event, r.status_code)\n        except Exception as e:\n            log.warning('Event %s could not be delivered: %s', event, e)\n        if attempt + 1 < attempts:\n            time.sleep(min(2 ** attempt, 4))\n    return False\n\n# The screen's browser gets the server's read-only viewer key, never the device\n# API token (v4.4.1). Ctrl+Shift+T on a screen restored a normal browser\n# window with /viewer?token=... in the address bar, and that token receives\n# WiFi passwords and password changes, acknowledges commands and reports state.\n# The server swaps ?vk= for a cookie and reloads the page without it. Until\n# the first heartbeat or config message has delivered the key (and against a\n# server older than 4.4.1) the token is used; 4.4.1 swaps that the same way.\n_viewer_key = None\n\ndef _remember_viewer_key(data):\n    global _viewer_key\n    k = data.get('viewer_key') if isinstance(data, dict) else None\n    if k and isinstance(k, str) and k != _viewer_key:\n        _viewer_key = k\n\ndef viewer_url_for(server, token):\n    if _viewer_key:\n        return f'{server}/viewer?vk={urllib.parse.quote(_viewer_key)}'\n    return f'{server}/viewer?token={urllib.parse.quote(token)}'\n\ndef _ws_contact():\n    \"\"\"The live connection is contact too (v4.9.6), for the USB guard's\n    lock-out watchdog. While the WebSocket is up the agent sends no HTTP\n    heartbeats (the main loop only polls when it is down), and only an\n    occasional usb_policy message told the guard the server was there. So a\n    screen online the whole time was «20 minutes without contact»: the USB\n    lock was released, and put back at the next policy message, over and\n    over. Now every message, every answer to the 30-second ping, and the\n    connection opening count.\"\"\"\n    if _usbguard:\n        try:\n            _usbguard.note_contact()\n            _usbguard.resume_after_release()\n        except Exception as e:\n            log.debug('usb guard contact: %s', e)\n\ndef heartbeat(server, token, browser, display, cfg):\n    \"\"\"Returns current token (may be new if re-provisioned).\"\"\"\n    global current_viewer_url\n    try:\n        metrics = get_metrics()\n        log.info('Heartbeat...')\n        r = requests.post(f'{server}/api/pi/heartbeat', json=metrics,\n            headers={'X-Pi-Token':token}, timeout=15)\n        if r.status_code == 401:\n            log.warning('Token rejected (401) — device may have been deleted. Re-provisioning...')\n            # Show the branded \"not registered\" screen so the display never goes\n            # blank while we try to re-enrol (and stays branded if enrolment is\n            # off because IT deleted it on purpose).\n            show_hold(server, browser, display, 'unknown_device', '', cfg)\n            # Clear saved token and re-provision\n            for tf in [TOKEN_FILE, os.path.expanduser(HOME_TOKEN)]:\n                try: os.unlink(tf)\n                except: pass\n            new_token = provision(cfg)\n            if new_token:\n                token = new_token\n            return token\n        if r.status_code == 403:\n            # Revoked (or otherwise withdrawn). The token is still valid on disk,\n            # so this is not a re-provision — show the branded fault screen for\n            # whatever state the server reports and keep polling.\n            try: d403 = r.json()\n            except Exception: d403 = {}\n            state = d403.get('state') or 'revoked'\n            log.info('Heartbeat 403 (%s) — showing hold screen', state)\n            show_hold(server, browser, display, state, token, cfg)\n            return token\n        if r.status_code != 200:\n            log.warning('Heartbeat %s', r.status_code); return\n        data = r.json()\n        _remember_viewer_key(data)\n\n        # Handle reboot command from server\n        if data.get('reboot'):\n            log.info('Reboot command received — rebooting in 5 seconds...')\n            log_event(server, token, 'rebooting', 'server request')\n            time.sleep(5)\n            os.system('sudo reboot')\n            return\n\n        if data.get('apt_upgrade'):\n            log.info('APT upgrade command received')\n            run_apt_upgrade()\n\n        if data.get('agent_update'):\n            log.info('Agent update command received')\n            log_event(server, token, 'agent_update_received', f'Kommando mottatt av agent {AGENT_VERSION}', retries=3)\n            self_update_agent_and_restart(server, token)\n\n        if data.get('set_url'):\n            log.info('Server URL change command received: %s', data['set_url'])\n            apply_server_url(data['set_url'])\n\n        if data.get('terminal_requested'):\n            log.info('Terminal session requested — opening reverse tunnel')\n            threading.Thread(target=open_reverse_terminal, args=(server, token), daemon=True).start()\n\n        # ── Command bus ────────────────────────────────────────────────\n        # The server queues commands (image_update, reboot, announce, ...) and\n        # hands them out here. Without this block the server marked them 'sent'\n        # and waited forever for an ack that never came, which is why pushed\n        # updates sat at \"Sendt / 0%\".\n        cmds = data.get('commands') or []\n        if cmds:\n            log.info('Received %d queued command(s)', len(cmds))\n            for cmd in cmds:\n                threading.Thread(target=run_bus_command, args=(cmd, server, token, cfg),\n                                 daemon=True).start()\n\n        # ── Privileged command over HTTP ───────────────────────────────\n        # Same work the WebSocket 'privileged_exec' message does, for agents\n        # whose persistent socket is unavailable (blocked upgrade, missing\n        # websocket-client). Without it the server could only answer 503.\n        pexec = data.get('privileged_exec')\n        if pexec:\n            log.info('Privileged command via heartbeat: %s', pexec.get('command'))\n            threading.Thread(target=exec_privileged_command,\n                             args=(pexec.get('command'), pexec.get('request_id'), server, token),\n                             daemon=True).start()\n\n        log.info('Heartbeat keys: %s', list(data.keys()))\n        if data.get('wifi_profiles'):\n            log.info('WiFi profile update received (%d profiles)', len(data['wifi_profiles']))\n            apply_wifi_profiles(data['wifi_profiles'])\n\n        if data.get('change_password'):\n            cp = data['change_password']\n            user = cp.get('user', 'kiosk')\n            pwd = cp.get('password', '')\n            if pwd:\n                log.info('Password change via heartbeat for %s', user)\n                try:\n                    subprocess.run(['sudo', 'chpasswd'], input=f'{user}:{pwd}',\n                        capture_output=True, text=True, timeout=10, check=True)\n                    log.info('Password changed for %s', user)\n                except Exception as e:\n                    log.error('Password change failed: %s', e)\n\n        _server_ok['at'] = time.time()\n        if data.get('server_move'):\n            _maybe_move(data['server_move'])\n        if data.get('ws_now'):\n            _ws_now.set()                     # Live View is open: connect the socket now\n\n        if data.get('live_stream'):\n            global _live_stream_active\n            _live_stream_active = data['live_stream'] == 'start'\n            log.info('Live stream %s via heartbeat', 'started' if _live_stream_active else 'stopped')\n\n        # USB rules arrive on every heartbeat, not only when they change. A\n        # screen that has just been re-flashed, rolled back, or restored from an\n        # old image has no rules at all, and this makes it self-correcting\n        # without anyone having to notice and press a button.\n        # Proof of contact for the guard's lock-out watchdog. Any successful\n        # reply counts, not just one carrying a policy.\n        if _usbguard:\n            try:\n                _usbguard.note_contact()\n                _usbguard.resume_after_release()\n            except Exception:\n                pass\n        # Same proof of contact on disk, so infoscreen-portguard — which runs as a\n        # separate process from a boot hook, not inside this one — can see it.\n        try:\n            os.makedirs(STATE_DIR, exist_ok=True)\n            with open(os.path.join(STATE_DIR, 'last-contact'), 'w') as _cf:\n                _cf.write(str(int(time.time())))\n        except Exception:\n            pass\n\n        if data.get('usb_policy'):\n            try:\n                apply_usb_policy(data['usb_policy'])\n            except Exception as e:\n                log.warning('USB policy from heartbeat failed: %s', e)\n\n        if data.get('diagnostics_pending'):\n            threading.Thread(target=upload_diagnostics,\n                             args=(server, token, 'requested'), daemon=True).start()\n\n        if data.get('usb_rescan'):\n            guard = start_usb_guard()\n            if guard:\n                try:\n                    report_topology(guard.topology(), policy_applied=_usb_policy_cache is not None)\n                except Exception as e:\n                    log.debug('rescan: %s', e)\n\n        # Not authorised? Show the branded hold/fault screen, not content. This\n        # is how a revocation or a re-pair reaches the display within one\n        # heartbeat instead of needing someone to reboot the screen.\n        global current_hold_state\n        hold = data.get('hold') or (data.get('authz') if data.get('authz') not in (None, 'approved') else None)\n        if hold:\n            show_hold(server, browser, display, hold, token, cfg)\n            return token\n        if current_hold_state is not None:\n            # We were on a hold screen and are now cleared — fall through to\n            # content and reset so the next hold re-opens.\n            current_hold_state = None\n            current_viewer_url = None\n\n        # Whether or not there is content, open the viewer — it shows the branded\n        # \"no content\" screen when empty, never a black screen (unless IT set a\n        # black screen for this device in settings).\n        viewer_url = viewer_url_for(server, token)\n        if current_viewer_url != viewer_url:\n            open_url(viewer_url, browser, display)\n            current_viewer_url = viewer_url\n    except requests.exceptions.ConnectionError:\n        log.warning('Server unreachable')\n    except Exception as e:\n        log.error('Heartbeat error: %s', e)\n    return token\n\ndef _browser_binary_replaced():\n    \"\"\"True when the running Chromium's own program file has been replaced.\n\n    v4.9.52: an OS update (apt) replaced Chromium 154 with 155 while the kiosk\n    browser kept running. /proc/<pid>/exe then reads '... (deleted)'. Pages\n    still drew, but the old browser could no longer start helper processes\n    from the new files, so web video never started («Starter video …» for\n    ever) on the Pi only. Debian asks for no reboot after a browser update, so\n    nothing restarted it. Only processes of this browser count.\"\"\"\n    if browser_proc is None or browser_proc.poll() is not None:\n        return False\n    try:\n        procs = [psutil.Process(browser_proc.pid)]\n        try:\n            procs += psutil.Process(browser_proc.pid).children(recursive=True)\n        except Exception:\n            pass\n        for p in procs:\n            try:\n                exe = os.readlink(f'/proc/{p.pid}/exe')\n            except OSError:\n                continue\n            if exe.endswith(' (deleted)') and 'chrom' in os.path.basename(exe).lower():\n                return True\n    except Exception:\n        return False\n    return False\n\n\ndef _package_manager_busy():\n    \"\"\"Never restart onto a half-installed browser: wait for apt/dpkg/apk.\"\"\"\n    try:\n        for p in psutil.process_iter(['name']):\n            if (p.info.get('name') or '') in ('apt', 'apt-get', 'dpkg', 'unattended-upgr', 'apk'):\n                return True\n    except Exception:\n        pass\n    return False\n\n\ndef watchdog(server, token, browser, display):\n    # 10 s, was 20: a closed or crashed browser means a black screen in a\n    # public corridor, and the check itself costs nothing.\n    while True:\n        time.sleep(10)\n        if (current_viewer_url and not _maint and _browser_binary_replaced() and not _package_manager_busy()\n                and time.time() - float(_launch.get('binary_restart_at') or 0) > 600):\n            _launch['binary_restart_at'] = time.time()\n            log.warning('Chromium was updated on disk while running — restarting the browser on the new version')\n            open_url(current_viewer_url, browser, display)\n            log_event(server, token, 'browser_updated',\n                      'Chromium ble oppdatert mens nettleseren kjørte. Nettleseren ble startet på nytt automatisk.')\n            continue\n        if (current_viewer_url and not _maint and browser_proc is not None and browser_proc.poll() is None\n                and _launch.get('policy_sig') and _policy_sig() != _launch['policy_sig']\n                and time.time() - float(_launch.get('policy_restart_at') or 0) > 600):\n            _launch['policy_restart_at'] = time.time()\n            log.warning('Chromium policy changed since the browser started — restarting it to apply the policy')\n            open_url(current_viewer_url, browser, display)\n            log_event(server, token, 'browser_policy', 'Nettleserpolicyen ble endret av låsingen. Nettleseren ble startet på nytt for å bruke den.')\n            continue\n        try:   # the start log grows with console lines; keep it small\n            _lp = _own_tmp('infoscreen-chromium-last.log')\n            if os.path.getsize(_lp) > 8 * 1024 * 1024:\n                os.truncate(_lp, 0)\n        except OSError:\n            pass\n        if current_viewer_url and browser_proc is not None and browser_proc.poll() is None:\n            newest_crash = _crash_artifact_mtime()\n            baseline = float(_launch.get('crash_artifact') or 0.0)\n            # A new Crashpad artifact while the browser parent is still alive is\n            # normally a renderer/GPU/utility crash.  In kiosk mode we prefer a\n            # clean viewer restart to leaving a sad-tab visible indefinitely.\n            if newest_crash > baseline + 0.001:\n                _launch['crash_artifact'] = newest_crash\n                _launch['crash_restarts'] = int(_launch.get('crash_restarts') or 0) + 1\n                if _launch.get('gpu') and not _launch.get('gpu_off'):\n                    _launch['gpu_off'] = True\n                    log.warning('Chromium crash artifact detected with GPU on: switching to safe software rendering')\n                log.warning('Chromium crash artifact detected while parent browser is alive — restarting viewer')\n                open_url(current_viewer_url, browser, display)\n                log_event(server, token, 'browser_crash_artifact', 'Chromium Crashpad registrerte en ny prosesskrasj. Nettleseren ble startet på nytt automatisk.')\n                continue\n        if current_viewer_url and (browser_proc is None or browser_proc.poll() is not None):\n            code = browser_proc.poll() if browser_proc else None\n            # v4.8.3: a browser that dies within a minute of starting with the\n            # GPU on, twice running, goes on without it for the rest of this\n            # agent run, and the portal hears why: a screen that flashes as it\n            # restarts over and over is worse than one without the GPU.\n            if _launch['gpu'] and time.time() - _launch['at'] < 60:\n                _launch['early_exits'] += 1\n                if _launch['early_exits'] >= 2 and not _launch['gpu_off']:\n                    _launch['gpu_off'] = True\n                    log.warning('Browser died twice right after starting with the GPU on: GPU off from now')\n                    log_event(server, token, 'gpu_off', 'Nettleseren stoppet to ganger rett etter start med GPU på. '\n                              'Den kjører uten GPU til agenten starter på nytt.')\n            else:\n                _launch['early_exits'] = 0\n            log.info('Browser crashed — restarting')\n            open_url(current_viewer_url, browser, display)\n            log_event(server, token, 'browser_restart', f'watchdog (exit {code})')\n\n# ══════════════════════════════════════════════════════════════════════\n# Maintenance mode (v4.2.0) — see routes/maintenance.js for the whole story.\n#   remote:   admin drives the screen from Live View (input injected here)\n#   physical: USB ports open + maintenance page; someone works at the screen\n# Ending always restores: new windows and started processes closed, USB policy\n# back, normal viewer relaunched. An own timer ends it even without a server.\n# ══════════════════════════════════════════════════════════════════════\n_maint = None\n_maint_lock = threading.Lock()\n_xin = None\n\n\ndef _display_env(display):\n    env = os.environ.copy()\n    env['DISPLAY'] = display or ':0'\n    for user in [os.environ.get('USER', 'pi'), 'pi', 'kiosk', 'root']:\n        xauth = f'/home/{user}/.Xauthority'\n        if os.path.exists(xauth):\n            env['XAUTHORITY'] = xauth\n            break\n    if not env.get('XAUTHORITY') and os.path.exists('/root/.Xauthority'):\n        env['XAUTHORITY'] = '/root/.Xauthority'\n    return env\n\n\n# v4.9.40: a kiosk display must never enter X DPMS/screensaver/locker state.\n# The old setup disabled blanking only once at X/Openbox startup.  A display\n# manager, hot-plug event or an X restart can restore the defaults later, which\n# leaves a perfectly healthy agent/browser behind a black panel.  Re-assert the\n# policy throughout the life of the agent and wake the output before disabling\n# DPMS again.  Dedicated locker processes are not useful on a physically locked\n# information screen, and can otherwise cover Chromium while the agent thinks\n# everything is healthy.\n_display_awake_logged = False\n\ndef _wake_display_once(display):\n    env = _display_env(display)\n    ok = False\n    if shutil.which('xset'):\n        for args in (\n            ['xset', 's', 'reset'],\n            ['xset', 'dpms', 'force', 'on'],\n            ['xset', 's', 'off'],\n            ['xset', 's', 'noblank'],\n            ['xset', '-dpms'],\n        ):\n            try:\n                r = subprocess.run(args, env=env, stdout=subprocess.DEVNULL,\n                                   stderr=subprocess.DEVNULL, timeout=3)\n                ok = ok or r.returncode == 0\n            except Exception:\n                pass\n\n    # Older Raspberry Pi images may still expose the firmware display-power\n    # switch even when X is using KMS.  It is a best-effort second wake path;\n    # modern KMS systems simply ignore/fail it and continue with xset.\n    if not _IS_PC and shutil.which('vcgencmd'):\n        try:\n            subprocess.run(['vcgencmd', 'display_power', '1'],\n                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=3)\n        except Exception:\n            pass\n\n    # These are screen-lock/saver daemons only.  Killing them does not unlock\n    # the kiosk's USB/input policy; it prevents a desktop locker from drawing\n    # over the public display after an idle timeout.\n    for proc in ('xscreensaver', 'light-locker', 'xss-lock', 'xautolock', 'slock', 'i3lock'):\n        try:\n            subprocess.run(['pkill', '-x', proc], stdout=subprocess.DEVNULL,\n                           stderr=subprocess.DEVNULL, timeout=2)\n        except Exception:\n            pass\n    return ok\n\ndef display_keepalive_loop(display):\n    global _display_awake_logged\n    # Retry quickly while X is still starting, then keep a cheap 20-second\n    # guard for the entire kiosk session.\n    while True:\n        ok = _wake_display_once(display)\n        if ok and not _display_awake_logged:\n            _display_awake_logged = True\n            log.info('Display keep-awake active on %s (screensaver/DPMS disabled)', display)\n        time.sleep(20 if ok else 4)\n\n\n_xlib_failed_at = 0\n\ndef _import_xlib():\n    \"\"\"python-xlib, installed for this user on first use. Pure Python, so no\n    root and no apt: the agent on a Pi runs as the kiosk user.\"\"\"\n    try:\n        from Xlib import display as xdisplay, X, XK  # noqa: F401\n        from Xlib.ext import xtest  # noqa: F401\n        return True\n    except ImportError:\n        pass\n    global _xlib_failed_at\n    if time.time() - _xlib_failed_at < 600:\n        return False                      # tried recently; do not block the caller again\n    _xlib_failed_at = time.time()\n    if _os_install(['python3-xlib'], ['py3-xlib']):   # Alpine has no pip (v4.5.0)\n        try:\n            import importlib\n            importlib.invalidate_caches()\n            from Xlib import display as xdisplay, X, XK  # noqa: F401\n            from Xlib.ext import xtest  # noqa: F401\n            return True\n        except ImportError:\n            pass\n    for extra in (['--user'], []):\n        try:\n            subprocess.run([sys.executable, '-m', 'pip', 'install', '--quiet', *extra,\n                            'python-xlib', '--break-system-packages'], timeout=180,\n                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n            import site, importlib\n            try:\n                sys.path.append(site.getusersitepackages())\n            except Exception:\n                pass\n            importlib.invalidate_caches()\n            from Xlib import display as xdisplay, X, XK  # noqa: F401\n            from Xlib.ext import xtest  # noqa: F401\n            return True\n        except Exception:\n            continue\n    return False\n\n\n# Browser KeyboardEvent.key -> X keysym name\n_KEYNAMES = {\n    'Enter': 'Return', 'Backspace': 'BackSpace', 'Tab': 'Tab', 'Escape': 'Escape',\n    'ArrowLeft': 'Left', 'ArrowRight': 'Right', 'ArrowUp': 'Up', 'ArrowDown': 'Down',\n    'Delete': 'Delete', 'Insert': 'Insert', 'Home': 'Home', 'End': 'End',\n    'PageUp': 'Prior', 'PageDown': 'Next', 'Shift': 'Shift_L', 'Control': 'Control_L',\n    'Alt': 'Alt_L', 'AltGraph': 'ISO_Level3_Shift', 'Meta': 'Super_L', 'CapsLock': 'Caps_Lock',\n    ' ': 'space', 'ContextMenu': 'Menu',\n    **{f'F{i}': f'F{i}' for i in range(1, 13)},\n}\n\n\nclass _XInput:\n    \"\"\"Synthetic mouse/keyboard through the X server's XTEST extension.\"\"\"\n\n    def __init__(self, display):\n        from Xlib import display as xdisplay\n        env = _display_env(display)\n        if env.get('XAUTHORITY'):\n            os.environ['XAUTHORITY'] = env['XAUTHORITY']\n        self.d = xdisplay.Display(env['DISPLAY'])\n        scr = self.d.screen()\n        self.w, self.h = scr.width_in_pixels, scr.height_in_pixels\n        self._spare = None\n\n    def _sync(self):\n        self.d.sync()\n\n    def move(self, x, y):\n        from Xlib import X\n        from Xlib.ext import xtest\n        xtest.fake_input(self.d, X.MotionNotify, x=int(x * (self.w - 1)), y=int(y * (self.h - 1)))\n        self._sync()\n\n    def button(self, b, down):\n        from Xlib import X\n        from Xlib.ext import xtest\n        xtest.fake_input(self.d, X.ButtonPress if down else X.ButtonRelease, b)\n        self._sync()\n\n    def wheel(self, dy):\n        for _ in range(min(10, abs(int(dy)))):\n            b = 5 if dy > 0 else 4\n            self.button(b, True)\n            self.button(b, False)\n\n    def _keysym(self, key):\n        from Xlib import XK\n        if key in _KEYNAMES:\n            return XK.string_to_keysym(_KEYNAMES[key])\n        if len(key) == 1:\n            o = ord(key)\n            return o if o <= 0xFF else 0x01000000 + o   # Latin-1 keysyms equal the code point\n        return XK.string_to_keysym(key)\n\n    def _keycode(self, ks):\n        kc = self.d.keysym_to_keycode(ks)\n        if kc:\n            return kc\n        # Not on this keyboard map (e.g. å on a US map): borrow an unused\n        # keycode for it. Reused for the next unmapped character.\n        mn, mx = self.d.display.info.min_keycode, self.d.display.info.max_keycode\n        if self._spare is None:\n            mapping = self.d.get_keyboard_mapping(mn, mx - mn + 1)\n            for i in range(len(mapping) - 1, -1, -1):\n                if not any(mapping[i]):\n                    self._spare = mn + i\n                    break\n        if self._spare is None:\n            return 0\n        self.d.change_keyboard_mapping(self._spare, [(ks,) * 4])\n        self.d.sync()\n        return self._spare\n\n    def key(self, key, down):\n        from Xlib import X\n        from Xlib.ext import xtest\n        ks = self._keysym(key or '')\n        if not ks:\n            return\n        kc = self._keycode(ks)\n        if kc:\n            xtest.fake_input(self.d, X.KeyPress if down else X.KeyRelease, kc)\n            self._sync()\n\n    def client_pids(self):\n        \"\"\"{window id: pid} of the top-level windows the window manager lists.\"\"\"\n        out = {}\n        try:\n            root = self.d.screen().root\n            lst = root.get_full_property(self.d.intern_atom('_NET_CLIENT_LIST'), 0)\n            pid_atom = self.d.intern_atom('_NET_WM_PID')\n            for wid in (lst.value if lst else []):\n                try:\n                    w = self.d.create_resource_object('window', wid)\n                    p = w.get_full_property(pid_atom, 0)\n                    out[int(wid)] = int(p.value[0]) if p else 0\n                except Exception:\n                    out[int(wid)] = 0\n        except Exception:\n            pass\n        return out\n\n\ndef _xinput(display):\n    global _xin\n    if _xin is None:\n        if not _import_xlib():\n            raise RuntimeError('python-xlib is not available (pip install failed)')\n        _xin = _XInput(display)\n    return _xin\n\n\n# ── Kiosk window guard (v4.4.1) ──────────────────────────────────────\n# Found in the field: Ctrl+Shift+T on a screen restored a previously closed\n# window as an ordinary browser window, with tabs and an address bar, outside\n# --kiosk. From there the screen could be pointed anywhere on the web. The\n# key is now swallowed by Openbox (harden-kiosk.sh), but Chromium has more\n# ways to open a window than anyone can list, so this checks the outcome\n# instead: in kiosk mode the browser has exactly ONE normal top-level window.\n# A second one for two checks in a row (≈3 s) means an escape: the browser is\n# restarted fresh on the viewer (every window gone) and the portal gets an\n# incident. Not during maintenance, where an admin opens windows on purpose.\n# Its own X connection: python-xlib displays are not safe to share with the\n# maintenance input thread.\n_BROWSER_CLASSES = ('chromium', 'chrome', 'firefox', 'navigator')\n\ndef _browser_top_windows(d):\n    root = d.screen().root\n    lst = root.get_full_property(d.intern_atom('_NET_CLIENT_LIST'), 0)\n    type_atom = d.intern_atom('_NET_WM_WINDOW_TYPE')\n    normal = d.intern_atom('_NET_WM_WINDOW_TYPE_NORMAL')\n    out = []\n    for wid in (lst.value if lst else []):\n        try:\n            w = d.create_resource_object('window', wid)\n            cls = w.get_wm_class() or ()\n            if not any(b in ' '.join(cls).lower() for b in _BROWSER_CLASSES):\n                continue\n            t = w.get_full_property(type_atom, 0)\n            if t and t.value and normal not in list(t.value):\n                continue                      # dialogs, menus, tooltips, notifications\n            title = ''\n            try:\n                title = w.get_wm_name() or ''\n                if isinstance(title, bytes): title = title.decode('utf-8', 'replace')\n            except Exception:\n                title = ''\n            out.append({'wid': int(wid), 'class': '.'.join(cls), 'title': str(title)[:300]})\n        except Exception:\n            continue\n    return out\n\n_fs = {'pid': None, 'tries': 0, 'last': 0.0}\n\ndef _find_browser_window(d):\n    \"\"\"With no window manager there is no _NET_CLIENT_LIST: the browser's\n    main window is then its largest visible top-level window.\"\"\"\n    from Xlib import X\n    best, area = None, 0\n    for c in d.screen().root.query_tree().children:\n        try:\n            a = c.get_attributes()\n            if a.map_state != X.IsViewable or a.override_redirect:\n                continue\n            if not any(b in ' '.join(c.get_wm_class() or ()).lower() for b in _BROWSER_CLASSES):\n                continue\n            g = c.get_geometry()\n            if g.width * g.height > area:\n                best, area = c.id, g.width * g.height\n        except Exception:\n            continue\n    return best\n\ndef _monitors(d):\n    try:\n        r = d.xrandr_get_monitors(d.screen().root)\n        return [(m.x, m.y, m.width_in_pixels, m.height_in_pixels) for m in r.monitors]\n    except Exception:\n        return []\n\ndef _keep_fullscreen(d, wid, server, token):\n    \"\"\"The browser covers the screen, or one whole monitor (v4.8.3, see\n    _wait_for_wm). If not: a fullscreen request to the window manager (EWMH)\n    and a direct resize, which also works with no window manager. At most five\n    tries per browser start, three seconds apart: never a tug-of-war.\"\"\"\n    from Xlib import X\n    from Xlib.protocol import event as xevent\n    root = d.screen().root\n    if wid is None:\n        wid = _find_browser_window(d)\n        if wid is None:\n            return False\n    rg = root.get_geometry()\n    W, H = rg.width, rg.height\n    w = d.create_resource_object('window', wid)\n    g = w.get_geometry()\n    t = w.translate_coords(root, 0, 0)\n    x, y = -t.x, -t.y\n    covers = lambda mx, my, mw, mh: x <= mx and y <= my and x + g.width >= mx + mw and y + g.height >= my + mh\n    if covers(0, 0, W, H) or any(covers(*m) for m in _monitors(d)):\n        return False\n    pid = browser_proc.pid if browser_proc else None\n    if _fs['pid'] != pid:\n        _fs.update(pid=pid, tries=0, last=0.0)\n    now = time.time()\n    if _fs['tries'] >= 5 or now - _fs['last'] < 3:\n        return False\n    _fs['tries'] += 1\n    _fs['last'] = now\n    st, fs = d.intern_atom('_NET_WM_STATE'), d.intern_atom('_NET_WM_STATE_FULLSCREEN')\n    root.send_event(xevent.ClientMessage(window=w, client_type=st, data=(32, [1, fs, 0, 1, 0])),\n                    event_mask=X.SubstructureRedirectMask | X.SubstructureNotifyMask)\n    w.configure(x=0, y=0, width=W, height=H)\n    d.flush()\n    log.warning('Browser window %dx%d+%d+%d did not cover the screen %dx%d: made fullscreen', g.width, g.height, x, y, W, H)\n    if _fs['tries'] == 1 and server:\n        threading.Thread(target=log_event, daemon=True, args=(server, token, 'window_fullscreen_fixed',\n            f'Nettleservinduet dekket ikke skjermen ({g.width}×{g.height} ved {x},{y} på {W}×{H}). Satt til fullskjerm.')).start()\n    return True\n\ndef ensure_display_tuning(server, token, grub_default='/etc/default/grub',\n                          grub_cfg='/boot/grub/grub.cfg', cmdline='/proc/cmdline'):\n    \"\"\"Intel laptop panels (v4.8.3): Panel Self Refresh off. With PSR the panel\n    keeps showing the last frame by itself while nothing changes, and on many\n    Intel laptops (Dell among them) waking it for the next change shows as a\n    flash or flicker, exactly when a slide or the content changes.\n    i915.enable_psr=0 on the kernel line turns it off, from the next restart.\n    Written to /etc/default/grub (for any later grub-mkconfig) and to the\n    kernel lines of /boot/grub/grub.cfg, after a backup, only when the result\n    has the same lines and entries as before.\"\"\"\n    param = 'i915.enable_psr=0'\n    if not _IS_PC or os.geteuid() != 0 or _gpu_vendor() != 'intel':\n        return\n    try:\n        with open(cmdline) as f:\n            if param in f.read():\n                return\n    except Exception:\n        pass\n    changed = []\n    try:\n        p = grub_default\n        if os.path.exists(p):\n            with open(p, encoding='utf-8') as f:\n                s = f.read()\n            m = re.search(r'^GRUB_CMDLINE_LINUX_DEFAULT=\"([^\"]*)\"', s, re.M)\n            if m and param not in m.group(1):\n                with open(p, 'w', encoding='utf-8') as f:\n                    f.write(s[:m.start(1)] + (m.group(1) + ' ' + param).strip() + s[m.end(1):])\n                changed.append(p)\n        cfg = grub_cfg\n        if os.path.exists(cfg):\n            with open(cfg, encoding='utf-8') as f:\n                s = f.read()\n            new = re.sub(r'^([ \\t]*linux[ \\t]+\\S*vmlinuz\\S*[^\\n]*)$',\n                         lambda m: m.group(1) if param in m.group(1) else m.group(1).rstrip() + ' ' + param, s, flags=re.M)\n            if new != s and new.count('\\n') == s.count('\\n') and new.count('menuentry') == s.count('menuentry'):\n                shutil.copy2(cfg, cfg + '.infoscreen-bak')\n                with open(cfg + '.tmp', 'w', encoding='utf-8') as f:\n                    f.write(new)\n                os.replace(cfg + '.tmp', cfg)\n                changed.append(cfg)\n    except Exception as e:\n        log.warning('Display tuning (PSR) failed: %s', e)\n        return\n    if changed:\n        log.info('Intel graphics: Panel Self Refresh off from the next restart (%s)', ', '.join(changed))\n        log_event(server, token, 'display_tuning', 'Intel-grafikk: Panel Self Refresh slås av fra neste omstart, '\n                  'mot blinking når innholdet skifter. Start skjermen på nytt for å ta det i bruk.')\n\ndef _renderer_crash_title(title):\n    # Chrome's sad-tab title is localized. These are deliberately narrow so a\n    # normal scheduled web page cannot trigger a restart merely by containing\n    # an error word somewhere in its title.\n    t = ' '.join(str(title or '').strip().lower().split())\n    return (t.startswith('aw, snap!') or t.startswith('aw snap!') or\n            t.startswith('å, nei!') or t.startswith('uff da!') or\n            t.startswith('sad tab') or t.startswith('page crashed'))\n\n\ndef kiosk_window_guard(server, token, browser, display):\n    time.sleep(20)                            # let the first browser settle\n    while not _import_xlib():\n        log.warning('kiosk window guard waiting: python-xlib unavailable (retrying in 5 min)')\n        time.sleep(300)\n    from Xlib import display as xdisplay\n    d = None\n    strikes = 0\n    crash_strikes = 0\n    while True:\n        time.sleep(1.5)\n        try:\n            if _maint or not current_viewer_url or browser_proc is None or browser_proc.poll() is not None:\n                strikes = 0\n                crash_strikes = 0\n                continue\n            if d is None:\n                env = _display_env(display)\n                if env.get('XAUTHORITY'):\n                    os.environ.setdefault('XAUTHORITY', env['XAUTHORITY'])\n                d = xdisplay.Display(env['DISPLAY'])\n            wins = _browser_top_windows(d)\n        except Exception as e:\n            log.debug('kiosk window guard: %s', e)\n            d = None\n            time.sleep(10)\n            continue\n        # A renderer tab can die while Chromium's main process remains alive.\n        # The process watchdog cannot see that failure, so the kiosk used to sit\n        # forever on \"Aw, Snap! Error code: 5\". Two consecutive sad-tab titles\n        # are enough to self-heal without reacting to a one-frame title change.\n        crashed = len(wins) == 1 and _renderer_crash_title(wins[0].get('title'))\n        if crashed:\n            crash_strikes += 1\n            strikes = 0\n            if crash_strikes < 2:\n                continue\n            crash_strikes = 0\n            title = wins[0].get('title') or 'Chromium renderer crash'\n            detail = f'Renderer crash page detected ({title[:160]}). Browser restarted on the viewer.'\n            log.warning('RENDERER CRASH: %s', detail)\n            if _launch.get('gpu') and not _launch.get('gpu_off'):\n                _launch['gpu_off'] = True\n                log.warning('Renderer crash happened with GPU acceleration active: safe software rendering enabled for the rest of this agent run')\n            try:\n                open_url(current_viewer_url, browser, display)\n            except Exception as e:\n                log.error('renderer crash recovery: restart failed: %s', e)\n            log_event(server, token, 'renderer_crash', detail)\n            try:\n                requests.post(f'{server}/api/pi/incident', headers={'X-Pi-Token': token}, timeout=10,\n                              json={'kind': 'renderer_crash', 'severity': 'warning', 'detail': detail,\n                                    'self_healed': True})\n            except Exception:\n                pass\n            time.sleep(10)\n            continue\n        crash_strikes = 0\n\n        if len(wins) <= 1:\n            strikes = 0\n            try:\n                _keep_fullscreen(d, wins[0]['wid'] if wins else None, server, token)   # v4.8.3\n            except Exception as e:\n                log.debug('fullscreen check: %s', e)\n            continue\n        strikes += 1\n        if strikes < 2:\n            continue\n        strikes = 0\n        detail = (f'{len(wins)} browser windows open in kiosk mode — a normal browser window '\n                  f'(address bar, tabs) was opened on the screen, e.g. with Ctrl+Shift+T. '\n                  f'Browser restarted on the viewer.')\n        log.warning('KIOSK ESCAPE: %s', detail)\n        try:\n            open_url(current_viewer_url, browser, display)\n        except Exception as e:\n            log.error('kiosk window guard: restart failed: %s', e)\n        log_event(server, token, 'kiosk_escape', detail)\n        try:\n            requests.post(f'{server}/api/pi/incident', headers={'X-Pi-Token': token}, timeout=10,\n                          json={'kind': 'kiosk_escape', 'severity': 'warning', 'detail': detail,\n                                'self_healed': True})\n        except Exception:\n            pass\n        time.sleep(10)                        # the new browser needs a moment\n\n\ndef maintenance_start(mode, expires_at, server, token, browser, display, page_key=None):\n    global _maint\n    with _maint_lock:\n        if _maint and _maint['mode'] == mode:\n            _maint['expires'] = expires_at          # extended / re-sent on reconnect\n            return\n        if _maint:\n            _maint_restore_locked(server, token, browser, display, 'mode changed')\n        baseline = {}\n        try:\n            baseline = _xinput(display).client_pids()\n        except Exception as e:\n            log.warning('maintenance: window list unavailable (%s) — new windows cannot be closed at the end', e)\n        _maint = {'mode': mode, 'expires': expires_at, 'baseline': set(baseline),\n                  'procs': [], 'viewer_url': current_viewer_url}\n        if mode == 'physical':\n            guard = start_usb_guard()\n            if guard:\n                guard.set_policy({'enforce': False, 'allow_storage': True,\n                                  'allow_network': True, 'alert_on_block': False})\n            # The page's buttons need this session's page key, not the device\n            # token (v4.4.1); an older server sends none and gets the token.\n            cred = (f'mk={urllib.parse.quote(page_key)}' if page_key\n                    else f'token={urllib.parse.quote(token)}')\n            url = (f'{server}/viewer/maintenance?{cred}'\n                   f'&until={urllib.parse.quote(expires_at or \"\")}')\n            open_url(url, browser, display, _maint_ok=True)\n        log.warning('MAINTENANCE %s started (until %s)', mode, expires_at)\n        _input_lock_wake.set()\n        log_event(server, token, 'maintenance', f'started: {mode}')\n\n    def _timer(expected=_maint):\n        while True:\n            time.sleep(15)\n            with _maint_lock:\n                if _maint is not expected:\n                    return\n                try:\n                    from datetime import datetime, timezone\n                    exp = datetime.fromisoformat(str(_maint['expires']).replace('Z', '+00:00'))\n                    if datetime.now(timezone.utc) < exp:\n                        continue\n                except Exception:\n                    continue\n                log.warning('MAINTENANCE time limit reached on the screen — restoring')\n                _maint_restore_locked(server, token, browser, display, 'time limit (device timer)')\n                return\n    threading.Thread(target=_timer, daemon=True).start()\n\n\ndef _maint_restore_locked(server, token, browser, display, reason):\n    \"\"\"Put the screen back exactly as it was. Caller holds _maint_lock.\"\"\"\n    global _maint\n    m = _maint\n    if not m:\n        return\n    _maint = None\n    _input_lock_wake.set()\n    for p in m['procs']:                        # what maintenance started\n        try:\n            os.killpg(p.pid, signal.SIGTERM)\n        except Exception:\n            pass\n    closed = 0\n    try:                                        # every window opened since the start\n        browser_pid = browser_proc.pid if browser_proc else -1\n        for wid, pid in _xinput(display).client_pids().items():\n            if wid in m['baseline'] or not pid or pid in (browser_pid, os.getpid()):\n                continue\n            try:\n                os.kill(pid, signal.SIGTERM)\n                closed += 1\n            except Exception:\n                pass\n    except Exception as e:\n        log.warning('maintenance: could not list windows to close: %s', e)\n    time.sleep(1.5)\n    for p in m['procs']:\n        try:\n            os.killpg(p.pid, signal.SIGKILL)\n        except Exception:\n            pass\n    if m['mode'] == 'physical':                 # ports locked again\n        guard = start_usb_guard()\n        if guard:\n            guard.set_policy(_usb_policy_cache or {})\n    url = m.get('viewer_url') or viewer_url_for(server, token)\n    open_url(url, browser, display, _maint_ok=True)   # fresh browser: no tabs or state left over\n    log.warning('MAINTENANCE ended (%s): %d window(s) closed, viewer restarted', reason, closed)\n    log_event(server, token, 'maintenance', f'ended: {reason}; closed {closed} window(s)')\n\n\ndef maintenance_stop(server, token, browser, display, reason='ended'):\n    with _maint_lock:\n        _maint_restore_locked(server, token, browser, display, reason)\n\n\ndef maintenance_terminal(server, token, display):\n    with _maint_lock:\n        if not _maint:\n            return\n        for cand in ('x-terminal-emulator', 'lxterminal', 'xfce4-terminal', 'gnome-terminal',\n                     'xterm', 'urxvt', 'st'):\n            path = shutil.which(cand)\n            if path:\n                p = subprocess.Popen([path], env=_display_env(display), start_new_session=True,\n                                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n                _maint['procs'].append(p)\n                log_event(server, token, 'maintenance', f'terminal opened ({cand})')\n                return\n        log_event(server, token, 'maintenance', 'failed: no terminal program installed on this screen (install xterm)')\n\n\ndef maintenance_input(msg, display):\n    m = _maint\n    if not m or m['mode'] != 'remote':        # the server checks this too\n        return\n    try:\n        xi = _xinput(display)\n        k = msg.get('kind')\n        if k == 'move':\n            xi.move(msg.get('x', 0), msg.get('y', 0))\n        elif k in ('down', 'up'):\n            if 'x' in msg:\n                xi.move(msg.get('x', 0), msg.get('y', 0))\n            xi.button(int(msg.get('button', 1)), k == 'down')\n        elif k == 'wheel':\n            xi.wheel(msg.get('dy', 0))\n        elif k in ('keydown', 'keyup'):\n            xi.key(msg.get('key', ''), k == 'keydown')\n    except Exception as e:\n        log.warning('remote input failed: %s', e)\n\n\ndef handle_server_message(msg, server, token, browser, display, cfg):\n    \"\"\"Handle a message from the server (via WS or heartbeat response).\"\"\"\n    global current_viewer_url\n\n    if msg.get('type') == 'config' or msg.get('content_type'):\n        _remember_viewer_key(msg)\n        # Cache videos from rotation\n        rotation = msg.get('rotation', [])\n        if 'rotation' in msg:\n            profile = (msg.get('settings') or {}).get('local_video_profile', 'smooth')\n            # Store the chosen source in a detached cache-only representation;\n            # the viewer's server config retains the quality+smooth metadata.\n            rotation_cache = []\n            for item in rotation:\n                if item.get('type') != 'slideshow':\n                    rotation_cache.append(item)\n                    continue\n                clone = dict(item)\n                clone['slides'] = []\n                for slide in item.get('slides') or []:\n                    if not isinstance(slide, dict):\n                        clone['slides'].append(slide)\n                        continue\n                    original = slide.get('src', '')\n                    preferred = (slide.get('smooth_src') or original) if profile == 'smooth' else (\n                        (slide.get('balanced_src') or original) if profile == 'balanced' else original)\n                    # Cache the next lower cost variant too. When Chromium\n                    # detects dropped frames, it can switch on the next loop\n                    # without waiting for a new network download.\n                    alternates = ([slide.get('balanced_src'), slide.get('smooth_src')]\n                                  if profile == 'quality' else\n                                  [slide.get('smooth_src')] if profile == 'balanced' else [])\n                    cached = {**slide, 'src': preferred}\n                    cached['cache_alternates'] = [a for a in alternates if a and a != preferred]\n                    clone['slides'].append(cached)\n                rotation_cache.append(clone)\n            rotation = rotation_cache\n            request_cache_sync(server, token, rotation)\n\n        # Screen resolution chosen in the portal (v4.9.70)\n        if isinstance(msg.get('settings'), dict) and 'display_mode' in msg['settings']:\n            try:\n                if want_display_mode(msg['settings'].get('display_mode'), display) and current_viewer_url:\n                    log.info('Screen size changed — restarting the browser to fill it')\n                    open_url(current_viewer_url, browser, display)\n            except Exception as e:\n                log.warning('display mode failed: %s', e)\n\n        # Content/config update\n        if msg.get('wifi_profiles'):\n            log.info('WiFi profile update received (%d profiles)', len(msg['wifi_profiles']))\n            apply_wifi_profiles(msg['wifi_profiles'])\n\n        ct = msg.get('content_type', 'blank')\n        # Always open the viewer; it renders the branded no-content screen when\n        # empty rather than a black screen.\n        viewer_url = viewer_url_for(server, token)\n        if current_viewer_url != viewer_url:\n            open_url(viewer_url, browser, display)\n            current_viewer_url = viewer_url\n\n    elif msg.get('type') == 'reboot':\n        log.info('Reboot command received — rebooting in 5 seconds...')\n        log_event(server, token, 'rebooting', 'server request')\n        time.sleep(5)\n        os.system('sudo reboot')\n\n    elif msg.get('type') == 'apt_upgrade':\n        log.info('APT upgrade command received')\n        run_apt_upgrade()\n\n    elif msg.get('type') == 'maintenance_start':\n        threading.Thread(target=maintenance_start, daemon=True,\n                         args=(msg.get('mode'), msg.get('expires_at'), server, token, browser, display,\n                               msg.get('page_key'))).start()\n    elif msg.get('type') == 'maintenance_stop':\n        threading.Thread(target=maintenance_stop, daemon=True,\n                         args=(server, token, browser, display, msg.get('reason') or 'ended')).start()\n    elif msg.get('type') == 'maintenance_action':\n        if msg.get('action') == 'terminal':\n            threading.Thread(target=maintenance_terminal, args=(server, token, display), daemon=True).start()\n    elif msg.get('type') == 'remote_input':\n        maintenance_input(msg, display)\n    elif msg.get('type') == 'extension_check':\n        # Sent by the server on every WebSocket connect (v4.1.2). Update the\n        # screen extension now if ours differs, then restart the browser so it\n        # loads it; otherwise nothing happens.\n        want = msg.get('fingerprint') or ''\n        have = ext_fingerprint(os.path.join(AGENT_DIR, 'cookie-dismiss'))\n        if want and want != have:\n            def _sync_now():\n                try:\n                    if sync_extension(server, token):\n                        log_event(server, token, 'extension_updated',\n                                  _ext_version(os.path.join(AGENT_DIR, 'cookie-dismiss')))\n                        if current_viewer_url:\n                            log.info('Restarting the browser to load the new screen extension')\n                            open_url(current_viewer_url, browser, display)\n                except Exception as e:\n                    log.warning('Extension sync on connect failed: %s', e)\n            threading.Thread(target=_sync_now, daemon=True).start()\n    elif msg.get('type') == 'runner_repair':\n        log.warning('Privileged runner repair requested by server')\n        threading.Thread(target=repair_command_runner,\n                         args=(server, token, msg.get('reason') or 'server request'),\n                         daemon=True).start()\n\n    elif msg.get('type') == 'agent_update':\n        log.info('Agent update command received')\n        log_event(server, token, 'agent_update_received', f'Kommando mottatt av agent {AGENT_VERSION}', retries=3)\n        self_update_agent_and_restart(server, token)\n\n    elif msg.get('type') == 'set_url':\n        new_url = msg.get('url', '')\n        if new_url:\n            log.info('Server URL change via WS: %s', new_url)\n            apply_server_url(new_url)\n\n    elif msg.get('type') == 'wifi_profiles':\n        profiles = msg.get('profiles', [])\n        log.info('WiFi profile push received (%d profiles)', len(profiles))\n        apply_wifi_profiles(profiles)\n\n    elif msg.get('type') == 'change_password':\n        new_pass = msg.get('password', '')\n        user = msg.get('user', 'kiosk')\n        if new_pass:\n            log.info('Password change requested for user: %s', user)\n            try:\n                p = subprocess.run(['sudo', 'chpasswd'], input=f'{user}:{new_pass}',\n                    capture_output=True, text=True, timeout=10)\n                if p.returncode == 0:\n                    log.info('Password changed successfully for %s', user)\n                else:\n                    log.error('Password change failed: %s', p.stderr.strip())\n            except Exception as e:\n                log.error('Password change error: %s', e)\n\n    elif msg.get('type') == 'screen_stream':\n        # Driven by whether an admin actually has the live view open. The\n        # server starts it when the first watcher attaches and stops it when\n        # the last one leaves, so an unwatched screen captures nothing.\n        action = msg.get('action')\n        set_stream(action == 'start', msg.get('fps'), msg.get('quality'), msg.get('width'))\n\n    elif msg.get('type') == 'commands':\n        # Same bus as the HTTP heartbeat, arriving on the socket instead. The\n        # agent does not send HTTP heartbeats while the socket is up, so before\n        # this existed a connected screen never received a queued command at\n        # all — pushed image updates sat in the queue until the next reboot.\n        cmds = msg.get('commands') or []\n        if cmds:\n            log.info('Received %d queued command(s) over WebSocket', len(cmds))\n            cfg_local = _cfg or {}\n            for cmd in cmds:\n                threading.Thread(\n                    target=run_bus_command,\n                    args=(cmd, cfg_local.get('server', ''), cfg_local.get('token', ''), cfg_local),\n                    daemon=True).start()\n\n    elif msg.get('type') == 'server_move':\n        _maybe_move(msg.get('url'))\n    elif msg.get('type') == 'usb_policy':\n        if _usbguard:\n            try:\n                _usbguard.note_contact()\n                _usbguard.resume_after_release()\n            except Exception:\n                pass\n        apply_usb_policy(msg.get('policy'))\n\n    elif msg.get('type') == 'collect_diagnostics':\n        cfg_local = _cfg or {}\n        threading.Thread(\n            target=upload_diagnostics,\n            args=(cfg_local.get('server', ''), cfg_local.get('token', ''), 'requested'),\n            daemon=True).start()\n\n    elif msg.get('type') == 'usb_rescan':\n        guard = start_usb_guard()\n        if guard:\n            try:\n                report_topology(guard.topology(), policy_applied=_usb_policy_cache is not None)\n            except Exception as e:\n                log.warning('USB rescan failed: %s', e)\n\n    elif msg.get('type') == 'tamper':\n        # The server telling us to raise or clear the branded alert screen. The\n        # viewer page renders it; we only carry the flag and make sure the\n        # browser is actually pointed at the viewer so it can.\n        state = msg.get('state')\n        log.warning('Tamper state from server: %s (%s)', state, msg.get('label', ''))\n\n    elif msg.get('type') == 'live_stream_start':\n        log.info('Live stream started')\n        global _live_stream_active\n        _live_stream_active = True\n\n    elif msg.get('type') == 'live_stream_stop':\n        log.info('Live stream stopped')\n        _live_stream_active = False\n\n    elif msg.get('type') == 'terminal_start':\n        rows = msg.get('rows', 24)\n        cols = msg.get('cols', 80)\n        log.info('Terminal session requested (via WS)')\n        threading.Thread(target=handle_ws_terminal, args=(rows, cols), daemon=True).start()\n\n    elif msg.get('type') == 'terminal_input':\n        if _ws_terminal_fd is not None:\n            try: os.write(_ws_terminal_fd, msg['text'].encode('utf-8'))\n            except OSError: pass\n\n    elif msg.get('type') == 'terminal_resize':\n        if _ws_terminal_fd is not None:\n            set_pty_size(_ws_terminal_fd, msg.get('rows', 24), msg.get('cols', 80))\n\n    elif msg.get('type') == 'terminal_close':\n        close_ws_terminal()\n\n    elif msg.get('type') == 'privileged_exec':\n        # Execute a privileged command as root (agent runs as root via systemd)\n        # Only the server can send this — it verifies admin re-authentication first\n        cmd = msg.get('command', '')\n        request_id = msg.get('request_id', '')\n        log.info('Privileged command requested: %s (request_id=%s)', cmd, request_id)\n        threading.Thread(target=exec_privileged_command, args=(cmd, request_id), daemon=True).start()\n\n# ── Privileged command execution (runs as root) ──────────────────\n_AGENT_SVC = agent_service()   # old or new name, whichever runs this screen (v4.9.51)\nALLOWED_PRIVILEGED_COMMANDS = {\n    'reboot':           ['sudo', 'reboot'],\n    'shutdown':         ['sudo', 'shutdown', '-h', 'now'],\n    'restart-agent':    ['sudo', 'systemctl', 'restart', _AGENT_SVC],\n    'restart-chromium': ['sudo', 'systemctl', 'restart', N('infoscreen-browser')],\n    'restart-browser':  ['sudo', 'systemctl', 'restart', N('infoscreen-browser')],\n    'apt-update':       ['sudo', 'apt-get', 'update', '-y'],\n    'apt-upgrade':      ['sudo', 'apt-get', 'upgrade', '-y'],\n    'service-status':   ['systemctl', 'status', _AGENT_SVC, N('infoscreen-browser')],\n    'df':               ['df', '-h'],\n    'free':             ['free', '-h'],\n    'uptime':           ['uptime'],\n    'ip-addr':          ['ip', 'addr', 'show'],\n    'journal-agent':    ['journalctl', '-u', _AGENT_SVC, '--no-pager', '-n', '50'],\n    'journal-browser':  ['journalctl', '-u', N('infoscreen-browser'), '--no-pager', '-n', '50'],\n}\n\ndef ack_bus_command(server, token, cmd_id, status, result_text=''):\n    \"\"\"Tell the server how a queued command ended. Without an ack the server\n    leaves it in 'sent' forever, which is what kept pushed updates at 0%.\"\"\"\n    try:\n        requests.post(f'{server}/api/pi/command-ack',\n                      headers={'X-Pi-Token': token},\n                      json={'id': cmd_id, 'status': status,\n                            'result': (result_text or '')[:4000]},\n                      timeout=15)\n    except Exception as e:\n        log.error('Command ack failed for #%s: %s', cmd_id, e)\n\n\n\ndef install_device_bundle(server, token, payload):\n    \"\"\"Download, verify and install a full device-software bundle.\n\n    The Pi agent normally runs without root. The installer already grants it\n    exactly the cp/chmod commands needed for maintained kiosk files, so this\n    deliberately does not run an arbitrary bundle script through sudo.\n    \"\"\"\n    import hashlib, tarfile, tempfile\n    url = str((payload or {}).get('url') or '')\n    want_sha = str((payload or {}).get('sha256') or '').strip().lower()\n    version = str((payload or {}).get('version') or 'unknown')\n    if not url:\n        return False, 'bundle URL missing'\n    if url.startswith('/'):\n        url = server.rstrip('/') + url\n    work = tempfile.mkdtemp(prefix='infoscreen-bundle-')\n    archive = os.path.join(work, 'bundle.tar.gz')\n    extract = os.path.join(work, 'unpacked')\n    try:\n        r = requests.get(url, timeout=120)\n        if r.status_code != 200:\n            return False, f'bundle download HTTP {r.status_code}'\n        with open(archive, 'wb') as f:\n            f.write(r.content)\n        got = hashlib.sha256(r.content).hexdigest()\n        if want_sha and got != want_sha:\n            return False, f'checksum mismatch: got {got[:12]}, expected {want_sha[:12]}'\n        os.makedirs(extract, exist_ok=True)\n        with tarfile.open(archive, 'r:gz') as tar:\n            # Validate every member before extracting it.  A normal tar made\n            # with `tar -C stage .` contains a root member named `./`; that\n            # resolves to the extraction directory itself and is safe.  The\n            # old startswith(base + os.sep) check rejected that root entry on\n            # the Pi, which is why otherwise valid bundles failed as\n            # \"unsafe path in bundle\" while the laptop path succeeded.\n            base = os.path.realpath(extract)\n            safe_members = []\n            for m in tar.getmembers():\n                raw_name = str(m.name or '').replace('\\\\', '/')\n                if raw_name in ('', '.', './'):\n                    # Archive-root metadata is harmless and needs no extract.\n                    continue\n                if raw_name.startswith('/') or re.match(r'^[A-Za-z]:', raw_name):\n                    return False, f'unsafe absolute path in bundle: {raw_name[:120]}'\n                parts = [part for part in raw_name.split('/') if part not in ('', '.')]\n                if '..' in parts:\n                    return False, f'unsafe traversal path in bundle: {raw_name[:120]}'\n                # Device bundles never need links, devices, fifos or sockets.\n                # Reject them instead of trying to reason about link targets.\n                if m.issym() or m.islnk() or not (m.isfile() or m.isdir()):\n                    return False, f'unsafe member type in bundle: {raw_name[:120]}'\n                target = os.path.realpath(os.path.join(base, *parts))\n                try:\n                    if os.path.commonpath([base, target]) != base:\n                        return False, f'unsafe path in bundle: {raw_name[:120]}'\n                except ValueError:\n                    return False, f'unsafe path in bundle: {raw_name[:120]}'\n                safe_members.append(m)\n            for m in safe_members:\n                tar.extract(m, extract)\n\n        if not RENAMED:\n            # v4.9.55: the bundle's files carry the new names, and only its\n            # install.sh, run as root by the command runner, renames the rest\n            # of the screen first. This path must not mix the two.\n            return False, (f'bundle {version} must be installed by the root command runner '\n                           '(this screen still has to be renamed to InfoScreen)')\n        copies = [\n            ('agent/infoscreen-agent.py', AGENT_FILE, 0o755, False),\n            ('lib/tui.sh', '/usr/local/lib/infoscreen/tui.sh', 0o644, True),\n            ('lib/platform.sh', '/usr/local/lib/infoscreen/platform.sh', 0o644, True),\n            ('bin/infoscreen-boot', '/usr/local/bin/infoscreen-boot', 0o755, True),\n            ('bin/infoscreen-update', '/usr/local/bin/infoscreen-update', 0o755, True),\n            ('bin/infoscreen-commands', '/usr/local/bin/infoscreen-commands', 0o755, True),\n            ('bin/infoscreen-diagnostics', '/usr/local/bin/infoscreen-diagnostics', 0o755, True),\n            ('bin/infoscreen-boot-repair', '/usr/local/bin/infoscreen-boot-repair', 0o755, True),\n        ]\n        installed = []\n        for rel, dest, mode, root_needed in copies:\n            src = os.path.join(extract, rel)\n            if not os.path.isfile(src):\n                continue\n            parent = os.path.dirname(dest)\n            if root_needed and os.geteuid() != 0:\n                # 4.9.17: a hardened non-root display agent must never be the\n                # process installing the full image bundle. The root command\n                # runner owns that job. Keep a precise guard here too so a\n                # future routing regression cannot turn a missing directory\n                # into a misleading generic cp failure.\n                if parent and not os.path.isdir(parent):\n                    return False, f'privileged runner required for {rel}: missing {parent}'\n                # Legacy installs may still whitelist cp/chmod into an already\n                # prepared directory; keep that compatibility fallback.\n                cp = subprocess.run(['sudo', '-n', 'cp', src, dest], capture_output=True, text=True, timeout=30)\n                if cp.returncode != 0:\n                    return False, f'cannot install {rel}: {(cp.stderr or cp.stdout).strip()[-300:]}'\n                ch = subprocess.run(['sudo', '-n', 'chmod', oct(mode)[2:], dest], capture_output=True, text=True, timeout=15)\n                if ch.returncode != 0:\n                    return False, f'cannot chmod {dest}: {(ch.stderr or ch.stdout).strip()[-300:]}'\n            else:\n                if parent:\n                    os.makedirs(parent, exist_ok=True)\n                shutil.copy(src, dest)\n                os.chmod(dest, mode)\n            installed.append(rel)\n        if not installed:\n            return False, 'bundle contained no installable components'\n        return True, f'bundle {version} installed ({\", \".join(installed)}); sha256 {got[:12]}'\n    except Exception as e:\n        return False, f'bundle {version} failed: {e}'\n    finally:\n        shutil.rmtree(work, ignore_errors=True)\n\n\ndef run_bus_command(cmd, server, token, cfg):\n    \"\"\"Execute one command handed out by the server's command bus.\"\"\"\n    cmd_id = cmd.get('id')\n    ctype = cmd.get('type')\n    payload = cmd.get('payload') or {}\n    if isinstance(payload, str):\n        try: payload = json.loads(payload)\n        except Exception: payload = {}\n\n    log.info('Running queued command #%s: %s', cmd_id, ctype)\n    ack_bus_command(server, token, cmd_id, 'running')\n\n    try:\n        if ctype == 'image_update':\n            # A release can contain more than the Python agent: boot/update\n            # helpers and kiosk-side scripts travel with it too. Legacy\n            # commands without a bundle payload keep the old agent-only path.\n            if payload.get('url'):\n                ok, detail = install_device_bundle(server, token, payload)\n            else:\n                ok, detail = self_update_agent(server, token)\n            # Ack before restarting: the restart may replace this process.\n            ack_bus_command(server, token, cmd_id,\n                            'done' if ok else 'failed', detail[:900])\n            if ok:\n                time.sleep(1.5)\n                restart_agent_process()\n            return\n\n        if ctype == 'reboot':\n            ack_bus_command(server, token, cmd_id, 'done', 'Rebooting')\n            log_event(server, token, 'rebooting', 'queued command')\n            time.sleep(3)\n            os.system('sudo reboot')\n            return\n\n        if ctype == 'refresh_content':\n            global current_viewer_url\n            current_viewer_url = None\n            ack_bus_command(server, token, cmd_id, 'done', 'Content refresh scheduled')\n            return\n\n        if ctype == 'run_selfcheck':\n            out = ''\n            try:\n                import subprocess\n                proc = subprocess.run(['systemctl', 'is-active', agent_service()],\n                                      capture_output=True, text=True, timeout=20)\n                out = (proc.stdout or '') + (proc.stderr or '')\n            except Exception as e:\n                out = f'selfcheck error: {e}'\n            ack_bus_command(server, token, cmd_id, 'done', out)\n            return\n\n        if ctype in ('announce', 'announce_clear'):\n            # Announcements are surfaced by the viewer via /config; nothing for\n            # the agent to execute, but the server still needs the ack.\n            ack_bus_command(server, token, cmd_id, 'done', ctype)\n            return\n\n        log.warning('Unknown queued command type: %s', ctype)\n        ack_bus_command(server, token, cmd_id, 'failed', f'Unknown command type: {ctype}')\n\n    except Exception as e:\n        log.error('Queued command #%s (%s) failed: %s', cmd_id, ctype, e)\n        ack_bus_command(server, token, cmd_id, 'failed', str(e))\n\n\ndef _send_privileged_result(result, server=None, token=None):\n    \"\"\"Return a privileged-command result over the WebSocket, or over HTTP when\n    the socket is not available (blocked upgrade, missing websocket-client).\"\"\"\n    sent = False\n    if _ws_conn:\n        try:\n            _ws_conn.send(json.dumps(result))\n            sent = True\n        except Exception:\n            sent = False\n    if not sent and server and token:\n        try:\n            requests.post(f'{server}/api/pi/privileged-result',\n                          headers={'X-Pi-Token': token}, json=result, timeout=15)\n            sent = True\n        except Exception as e:\n            log.error('Could not return privileged result: %s', e)\n    return sent\n\n\ndef exec_privileged_command(cmd_key, request_id, server=None, token=None):\n    \"\"\"Execute a whitelisted privileged command and return its output.\"\"\"\n    import subprocess\n    result = {'type': 'privileged_result', 'request_id': request_id, 'command': cmd_key}\n\n    if cmd_key not in ALLOWED_PRIVILEGED_COMMANDS:\n        result['success'] = False\n        result['output'] = f'Kommandoen \"{cmd_key}\" er ikke tillatt.\\nTillatte kommandoer: {\", \".join(sorted(ALLOWED_PRIVILEGED_COMMANDS.keys()))}'\n        _send_privileged_result(result, server, token)\n        return\n\n    argv = _platform_command(cmd_key, ALLOWED_PRIVILEGED_COMMANDS[cmd_key])\n    log.info('Executing privileged command: %s → %s', cmd_key, ' '.join(argv))\n\n    try:\n        proc = subprocess.run(argv, capture_output=True, text=True, timeout=120)\n        result['success'] = proc.returncode == 0\n        result['output'] = proc.stdout + (proc.stderr if proc.stderr else '')\n        result['exit_code'] = proc.returncode\n    except subprocess.TimeoutExpired:\n        result['success'] = False\n        result['output'] = 'Kommandoen ble tidsavbrutt etter 120 sekunder.'\n    except Exception as e:\n        result['success'] = False\n        result['output'] = f'Feil: {str(e)}'\n\n    log.info('Privileged command %s: exit=%s', cmd_key, result.get('exit_code', '?'))\n    _send_privileged_result(result, server, token)\n\n# ── WebSocket terminal via persistent connection ──────────────────\n_ws_terminal_fd = None\n_ws_terminal_pid = None\n_ws_conn = None\n\ndef handle_ws_terminal(rows, cols):\n    \"\"\"Run a login shell on a real PTY and stream it to the portal.\n\n    Two things here decide whether full-screen programs — top, htop, less,\n    nano, vim, and the pager that systemctl and journalctl open by default —\n    behave like they do on a real terminal.\n\n    The first is that the byte stream must not be mangled. The previous version\n    decoded each 4096-byte read on its own with errors='replace'. Any UTF-8\n    character or escape sequence that happened to straddle a read boundary was\n    turned into replacement characters, which corrupts the very sequence that\n    restores the normal screen when a program exits. The program had quit\n    correctly; the terminal just never got the instruction to put the old\n    screen back, so it sat there looking frozen. An incremental decoder fixes\n    that by holding the tail of a partial character until the rest arrives.\n\n    The second is the window size, which has to be right before the program\n    starts or curses draws to the wrong geometry.\n    \"\"\"\n    global _ws_terminal_fd, _ws_terminal_pid\n    import pty as pty_mod, select, struct, fcntl, termios, codecs\n    close_ws_terminal()  # Clean up any previous\n\n    shell = None\n    for candidate in ('/bin/bash', '/usr/bin/bash', '/bin/ash', '/bin/sh'):\n        if os.path.exists(candidate):\n            shell = candidate\n            break\n    shell = shell or '/bin/sh'\n    rc = None if shell.endswith('bash') else _terminal_rc()\n\n    pid, fd = pty_mod.fork()\n    if pid == 0:\n        os.environ['TERM'] = 'xterm-256color'\n        os.environ['COLORTERM'] = 'truecolor'\n        os.environ['LANG'] = os.environ.get('LANG') or 'C.UTF-8'\n        # systemctl and journalctl pipe through less by default. That is fine —\n        # q exits it — but the default options leave the output on screen and\n        # swallow the quit on some builds. These are the flags systemd itself\n        # recommends for an interactive pager.\n        os.environ['SYSTEMD_LESS'] = 'FRSXMK'\n        os.environ.setdefault('LESS', '-R')\n        # A login shell everywhere, in the home folder (v4.6.0). ash used to\n        # start with no profile at all: a bare \"/ #\" prompt.\n        home = os.path.expanduser('~') or '/'\n        os.environ['HOME'] = home\n        try:\n            os.chdir(home)\n        except Exception:\n            pass\n        if rc:\n            os.environ['ENV'] = rc\n        os.execvp(shell, [shell, '-l'])\n    else:\n        _ws_terminal_fd = fd\n        _ws_terminal_pid = pid\n        set_pty_size(fd, rows, cols)\n        log.info('PTY spawned via WS, pid=%d, shell=%s, %dx%d', pid, shell, cols, rows)\n        # Tell the portal straight away. The shell still has to source its\n        # profile before it prints a prompt, but the PTY is open and the kernel\n        # buffers anything typed at it, so the administrator can start typing\n        # now rather than waiting for the first character to appear.\n        ws_send({'type': 'terminal_ready'})\n\n        # Holds a partial multi-byte character between reads instead of\n        # destroying it.\n        decoder = codecs.getincrementaldecoder('utf-8')(errors='replace')\n        try:\n            while True:\n                r, _, _ = select.select([fd], [], [], 1.0)\n                if fd in r:\n                    data = os.read(fd, 65536)\n                    if not data:\n                        break\n                    text = decoder.decode(data)\n                    if text and _ws_conn:\n                        try:\n                            _ws_conn.send(json.dumps({'type': 'terminal_data', 'text': text}))\n                        except Exception:\n                            break\n        except (OSError, ValueError):\n            pass\n        finally:\n            log.info('PTY read loop ended')\n            close_ws_terminal()\n\n\ndef set_pty_size(fd, rows, cols):\n    \"\"\"Resize the PTY. The kernel sends SIGWINCH to the foreground process\n    group by itself, which is how top and friends learn to redraw.\"\"\"\n    import struct, fcntl, termios\n    try:\n        rows = max(4, min(300, int(rows) or 24))\n        cols = max(20, min(500, int(cols) or 80))\n        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))\n        return True\n    except Exception as e:\n        log.debug('TIOCSWINSZ failed: %s', e)\n        return False\n\n\ndef close_ws_terminal():\n    \"\"\"Tear the session down, including anything the shell started.\n\n    SIGKILL to the shell's own pid left the foreground program running: top\n    holds the PTY open, so the session looked closed in the portal while the\n    process carried on. Signalling the process group, and giving it a moment to\n    exit cleanly first, ends the whole thing.\n    \"\"\"\n    global _ws_terminal_fd, _ws_terminal_pid\n    if _ws_terminal_pid is not None:\n        for sig in (signal.SIGHUP, signal.SIGTERM):\n            try:\n                os.killpg(os.getpgid(_ws_terminal_pid), sig)\n            except Exception:\n                try: os.kill(_ws_terminal_pid, sig)\n                except Exception: pass\n            time.sleep(0.15)\n            try:\n                gone, _ = os.waitpid(_ws_terminal_pid, os.WNOHANG)\n                if gone:\n                    _ws_terminal_pid = None\n                    break\n            except Exception:\n                _ws_terminal_pid = None\n                break\n        if _ws_terminal_pid is not None:\n            try: os.killpg(os.getpgid(_ws_terminal_pid), signal.SIGKILL)\n            except Exception:\n                try: os.kill(_ws_terminal_pid, signal.SIGKILL)\n                except Exception: pass\n            try: os.waitpid(_ws_terminal_pid, os.WNOHANG)\n            except Exception: pass\n        _ws_terminal_pid = None\n\n    if _ws_terminal_fd is not None:\n        try: os.close(_ws_terminal_fd)\n        except Exception: pass\n        _ws_terminal_fd = None\n\n_ws_now = threading.Event()\n\ndef ws_connection(server, token, browser, display, cfg):\n    \"\"\"Hold the WebSocket open until it drops. Returns True if it opened.\"\"\"\n    global _ws_conn\n    try:\n        import websocket\n    except ImportError:\n        log.warning('websocket-client not installed — HTTP polling only (Live View needs it)')\n        return False\n\n    ws_proto = 'wss' if server.startswith('https') else 'ws'\n    ws_url = f'{ws_proto}://{server.split(\"//\",1)[1]}/api/pi-ws?token={token}'\n    opened = [False]\n\n    def on_message(ws, raw):\n        _ws_contact()                                  # v4.9.6\n        try:\n            msg = json.loads(raw)\n            log.info('WS message: type=%s', msg.get('type','?'))\n            handle_server_message(msg, server, token, browser, display, cfg)\n        except Exception as e:\n            log.error('WS message handling error: %s', e)\n\n    def on_open(ws):\n        opened[0] = True\n        _server_ok['at'] = time.time()\n        _ws_contact()                                  # v4.9.6\n        log.info('WebSocket connected to %s', server)\n        try:\n            metrics = get_metrics()\n            metrics['type'] = 'metrics'\n            ws.send(json.dumps(metrics))\n        except Exception:\n            pass\n\n    def on_pong(ws, data):\n        _ws_contact()                                  # v4.9.6: the 30-second ping answered\n\n    def on_close(ws, code, reason):\n        log.info('WebSocket closed (code=%s, reason=%s)', code, reason)\n\n    def on_error(ws, err):\n        log.warning('WebSocket error: %s', err)\n\n    try:\n        _ws_conn = websocket.WebSocketApp(ws_url,\n            on_message=on_message, on_open=on_open, on_pong=on_pong,\n            on_close=on_close, on_error=on_error)\n        _ws_conn.run_forever(ping_interval=30, ping_timeout=10,\n            suppress_origin=True,\n            sockopt=((socket.IPPROTO_TCP, socket.TCP_NODELAY, 1),),\n            http_proxy_timeout=15)\n    except Exception as e:\n        log.error('WebSocket connection failed: %s', e)\n    finally:\n        _ws_conn = None\n    return opened[0]\n\ndef ensure_deps():\n    \"\"\"Everything Live View, remote control and the input lock need (v4.5.0).\n    Distribution packages first (Alpine has no pip), pip as the last resort.\"\"\"\n    import importlib\n    if not _websocket_available():\n        log.warning('websocket-client missing — installing (Live View and instant updates need it)')\n        if not _os_install(['python3-websocket'], ['py3-websocket-client']):\n            _run([sys.executable, '-m', 'pip', 'install', 'websocket-client>=1.6.0',\n                  '--break-system-packages'], timeout=180)\n        log.info('websocket-client now %s', 'available' if _websocket_available() else 'STILL MISSING')\n    try:\n        importlib.invalidate_caches()\n        from Xlib.ext import xinput  # noqa: F401\n    except ImportError:\n        log.warning('python-xlib missing — installing (input lock, window guard, Ta kontroll)')\n        _os_install(['python3-xlib'], ['py3-xlib'])\n        importlib.invalidate_caches()\n        global _xlib_failed_at\n        _xlib_failed_at = 0\n\n# ══ v4.5.0: one agent, real lockdown, dependencies that install themselves ══\n\n# ── One agent per screen ────────────────────────────────────────────────\n# The Pi started the agent twice: systemd (as the kiosk user) and the Openbox\n# autostart (as root, via sudo xinit). Both connected with the same token, the\n# server dropped one (\"Replaced\"), they took turns doing that, and both fell\n# back to long HTTP-only stretches. Live View said \"not connected\" most of the\n# time, and a reboot only reshuffled the race.\n#\n# A subtler variant showed up during the 4.9.38 -> 4.9.39 rollout: a second\n# process had already imported the OLD Python file and was waiting here as a\n# standby. The active process installed the new file and restarted, but the\n# already-loaded standby won the lock in the handoff gap and became the active\n# old agent. Its PID then kept heartbeating v4.9.38 forever even though the file\n# on disk was v4.9.39. A standby must therefore never acquire the lock with code\n# that no longer matches the file on disk.\n_instance_sock = None\n\ndef _reload_standby_if_agent_changed(waited=0):\n    \"\"\"Re-exec a waiting process if the installed agent changed underneath it.\"\"\"\n    try:\n        disk_version = installed_agent_version()\n    except Exception:\n        return False\n    if not disk_version or disk_version == 'unknown' or disk_version == AGENT_VERSION:\n        return False\n    agent_file = AGENT_FILE\n    log.warning('Standby agent v%s noticed installed v%s after %ss — re-executing before lock takeover',\n                AGENT_VERSION, disk_version, waited)\n    try:\n        sys.stdout.flush(); sys.stderr.flush()\n        os.execv(sys.executable, [sys.executable, agent_file])\n    except Exception as e:\n        log.error('Standby re-exec to installed agent v%s failed: %s', disk_version, e)\n    return False\n\ndef _agent_process_pids():\n    \"\"\"PIDs actually executing the installed agent (old or new name), no pgrep self-hit.\"\"\"\n    out = []\n    target = AGENT_FILE\n    proc_re = re.compile(r'/' + AGENT_PROC_RE + r'$')\n    try:\n        names = os.listdir('/proc')\n    except Exception:\n        return out\n    for name in names:\n        if not name.isdigit():\n            continue\n        pid = int(name)\n        if pid == os.getpid():\n            continue\n        try:\n            raw = open(f'/proc/{pid}/cmdline', 'rb').read().split(b'\\0')\n            args = [x.decode('utf-8', 'replace') for x in raw if x]\n            if any(os.path.realpath(a) == target for a in args if a.startswith('/')):\n                out.append(pid)\n            elif any(proc_re.search(a) for a in args):\n                out.append(pid)\n        except Exception:\n            pass\n    return sorted(set(out))\n\ndef _service_main_pid():\n    \"\"\"Return the init-supervised agent PID where the service manager exposes it.\"\"\"\n    try:\n        if shutil.which('systemctl'):\n            # Both names: until its reboot a migrated screen can still run the\n            # old unit while the new one is already installed (v4.9.51).\n            for unit in ('infoscreen-agent.service', f'{LEGACY}-agent.service'):\n                if not os.path.exists(f'/etc/systemd/system/{unit}'):\n                    continue\n                r = subprocess.run(['systemctl', 'show', '-p', 'MainPID', '--value', unit],\n                                   capture_output=True, text=True, timeout=3)\n                pid = int((r.stdout or '0').strip() or '0')\n                if pid > 1:\n                    return pid, 'systemd'\n    except Exception:\n        pass\n    for pf in ('/run/infoscreen-agent.pid', '/var/run/infoscreen-agent.pid',\n               f'/run/{LEGACY}-agent.pid', f'/var/run/{LEGACY}-agent.pid'):\n        try:\n            pid = int(open(pf).read().strip())\n            if pid > 1 and os.path.exists(f'/proc/{pid}'):\n                return pid, 'openrc'\n        except Exception:\n            pass\n    return 0, ''\n\ndef _evict_stray_agents(pids):\n    pids = [p for p in sorted(set(pids)) if p > 1 and p != os.getpid()]\n    if not pids:\n        return\n    log.warning('Init-supervised agent is reclaiming single-instance ownership from stray PID(s): %s',\n                ', '.join(map(str, pids)))\n    for pid in pids:\n        try: os.kill(pid, signal.SIGTERM)\n        except ProcessLookupError: pass\n        except Exception as e: log.debug('could not TERM stray agent %s: %s', pid, e)\n    deadline = time.time() + 4\n    while time.time() < deadline and any(os.path.exists(f'/proc/{p}') for p in pids):\n        time.sleep(0.2)\n    for pid in pids:\n        if os.path.exists(f'/proc/{pid}'):\n            try: os.kill(pid, signal.SIGKILL)\n            except Exception: pass\n\ndef acquire_single_instance():\n    \"\"\"One active agent, with the init service as authoritative owner.\n\n    A field Pi had PID 1464 actively owning the old lock while systemd MainPID\n    1532 waited forever as standby. That defeats Restart=always and makes update\n    handoffs look random. From v4.9.43 the init-supervised process evicts only\n    other processes executing this exact installed agent. Conversely, an\n    unmanaged Openbox copy exits when it notices an init-owned instance.\n    \"\"\"\n    global _instance_sock\n    waited = 0\n    evicted = False\n    while True:\n        if waited:\n            _reload_standby_if_agent_changed(waited)\n        service_pid, manager = _service_main_pid()\n        managed_self = service_pid == os.getpid() and bool(manager)\n        if service_pid and service_pid != os.getpid() and not managed_self:\n            # We are the duplicate. Do not remain a permanently loaded standby\n            # that can take over later with stale code.\n            log.warning('Init-managed InfoScreen-Agent PID %s already owns this screen; duplicate PID %s exits',\n                        service_pid, os.getpid())\n            return False\n        s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\n        legacy = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\n        try:\n            # v4.9.51: hold BOTH lock names. Agents before 4.9.51 take only the\n            # old one, so an old and a new agent can never run side by side,\n            # whichever starts first and whatever it is called.\n            s.bind('\\0infoscreen-agent-instance')\n            try:\n                legacy.bind(f'\\0{LEGACY}-agent-instance')\n            except OSError:\n                s.close()\n                raise\n            _instance_sock = (s, legacy)\n            if waited:\n                log.info('Single-instance lock acquired after %ds%s', waited,\n                         ' by init-supervised agent' if managed_self else '')\n            return True\n        except OSError:\n            s.close()\n            legacy.close()\n            if waited == 0:\n                log.warning('Another InfoScreen-Agent is already running on this screen')\n            if managed_self and waited >= 2 and not evicted:\n                others = _agent_process_pids()\n                # Never touch the current service MainPID. Only exact agent\n                # executables that predate/compete with this instance qualify.\n                _evict_stray_agents([p for p in others if p != service_pid])\n                evicted = True\n            time.sleep(1)\n            waited += 1\n            # If init ownership cannot be determined (very old image), preserve\n            # the old standby behavior but refresh loaded code before takeover.\n            if waited % 15 == 0:\n                _reload_standby_if_agent_changed(waited)\n\n\n# ── Distribution packages the agent needs ──────────────────────────────\n# Alpine laptops have no pip, and the installer never added the WebSocket or\n# X libraries: Live View (frames ride the WebSocket), Ta kontroll and the\n# window guard (python-xlib) could never work on a laptop. Installed here,\n# once, the way each distribution expects.\n_pkg_tried = {}\n\ndef _os_install(apt_pkgs, apk_pkgs):\n    key = ' '.join(apk_pkgs or apt_pkgs)\n    if time.time() - _pkg_tried.get(key, 0) < 1800:\n        return False\n    _pkg_tried[key] = time.time()\n    try:\n        if shutil.which('apk'):\n            if os.geteuid() != 0:\n                return False\n            r = subprocess.run(['apk', 'add', '--no-cache', *apk_pkgs], capture_output=True, timeout=300)\n            log.info('apk add %s -> %s', ' '.join(apk_pkgs), r.returncode)\n            return r.returncode == 0\n        if shutil.which('apt-get'):\n            env = dict(os.environ, DEBIAN_FRONTEND='noninteractive')\n            pre = [] if os.geteuid() == 0 else ['sudo', '-n']\n            cmd = pre + ['apt-get', 'install', '-y', '--no-install-recommends', *apt_pkgs]\n            r = subprocess.run(cmd, capture_output=True, timeout=900, env=env)\n            if r.returncode != 0:\n                subprocess.run(pre + ['apt-get', 'update'], capture_output=True, timeout=600, env=env)\n                r = subprocess.run(cmd, capture_output=True, timeout=900, env=env)\n            log.info('apt-get install %s -> %s', ' '.join(apt_pkgs), r.returncode)\n            return r.returncode == 0\n    except Exception as e:\n        log.warning('package install (%s) failed: %s', key, e)\n    return False\n\n\ndef _websocket_available():\n    try:\n        import importlib\n        importlib.invalidate_caches()\n        import websocket  # noqa: F401\n        return True\n    except ImportError:\n        return False\n\n\n# ── Root, only where it is needed ──────────────────────────────────────\n# The USB guard writes sysfs and the lockdown script writes /etc: both need\n# root. On a Pi the agent runs as the kiosk user, so the guard silently ran\n# report-only and every keyboard worked — and /usr/local/bin/infoscreen-harden\n# was installed once and never updated, so lockdown fixes never arrived.\n# A tiny root helper does exactly those jobs, validated, and nothing else.\nPRIV_HELPER = N('/usr/local/sbin/infoscreen-priv')\nPRIV_SUDOERS = N('/etc/sudoers.d/infoscreen-priv')\n_PRIV_HELPER_NEW = r'''#!/bin/sh\n# infoscreen-priv — the few things the display agent must do as root (v4.5.0).\n#   usb-write <sysfs-path> <0|1>   (de)authorize a USB device / controller default\n#   harden                         run the kiosk lockdown now\n#   install-harden <file>          install the agent's downloaded lockdown script\n#   runner-repair                  repair/start the privileged image-update runner\n#   set-url <url> [previous-url]   point /etc/infoscreen.env at another server\n#                                  (v4.6.0: moving servers without root)\n# Everything else is refused. Installed by the agent (once, with the installer's\n# sudo cp rights) or by infoscreen-harden itself.\nset -eu\ncase \"${1:-}\" in\n  usb-write)\n    p=\"${2:-}\"; v=\"${3:-}\"\n    case \"$v\" in 0|1) ;; *) echo \"bad value\" >&2; exit 2 ;; esac\n    case \"$p\" in *..*|*\" \"*) echo \"bad path\" >&2; exit 2 ;; esac\n    case \"$p\" in\n      /sys/bus/usb/devices/*/authorized|/sys/bus/usb/devices/*/authorized_default) ;;\n      *) echo \"path not allowed\" >&2; exit 2 ;;\n    esac\n    printf '%s' \"$v\" > \"$p\" ;;\n  harden)\n    exec /usr/local/bin/infoscreen-harden >>/var/log/infoscreen-harden.log 2>&1 ;;\n  install-harden)\n    f=\"${2:-}\"\n    case \"$f\" in /opt/infoscreen-agent/harden-kiosk.sh) ;; *) echo \"only the agent's copy\" >&2; exit 2 ;; esac\n    head -c 2 \"$f\" | grep -q '#!' || { echo \"not a script\" >&2; exit 2; }\n    sh -n \"$f\" || { echo \"does not parse\" >&2; exit 2; }\n    install -m 0755 -o root -g root \"$f\" /usr/local/bin/infoscreen-harden ;;\n  runner-repair)\n    exec /usr/local/bin/infoscreen-harden --runner-only >>/var/log/infoscreen-harden.log 2>&1 ;;\n  set-url)\n    u=\"${2:-}\"; prev=\"${3:-}\"\n    printf '%s' \"$u\" | grep -Eq '^https?://[A-Za-z0-9.-]+(:[0-9]{1,5})?$' || { echo \"bad url\" >&2; exit 2; }\n    [ -z \"$prev\" ] || printf '%s' \"$prev\" | grep -Eq '^https?://[A-Za-z0-9.-]+(:[0-9]{1,5})?$' || { echo \"bad previous url\" >&2; exit 2; }\n    f=/etc/infoscreen.env; t=$(mktemp)\n    grep -v -e '^INFOSCREEN_URL=' -e '^INFOSCREEN_URL_PREVIOUS=' -e '^INFOSCREEN_MOVED_AT=' \"$f\" > \"$t\" 2>/dev/null || true\n    printf 'INFOSCREEN_URL=%s\\n' \"$u\" >> \"$t\"\n    [ -z \"$prev\" ] || printf 'INFOSCREEN_URL_PREVIOUS=%s\\nINFOSCREEN_MOVED_AT=%s\\n' \"$prev\" \"$(date +%s)\" >> \"$t\"\n    cat \"$t\" > \"$f\"; rm -f \"$t\" ;;\n  *) echo \"usage: infoscreen-priv usb-write|harden|install-harden|runner-repair|set-url\" >&2; exit 2 ;;\nesac\n'''\n# The helper as the lockdown script of a screen that is not renamed yet writes\n# it (v4.9.54, byte for byte), so the agent and that script never fight over it.\n_PRIV_HELPER_LEGACY = r'''#!/bin/sh\n# piscreen-priv — the few things the display agent must do as root (v4.5.0).\n#   usb-write <sysfs-path> <0|1>   (de)authorize a USB device / controller default\n#   harden                         run the kiosk lockdown now\n#   install-harden <file>          install the agent's downloaded lockdown script\n#   runner-repair                  repair/start the privileged image-update runner\n#   set-url <url> [previous-url]   point /etc/piscreen.env at another server\n#                                  (v4.6.0: moving servers without root)\n# Everything else is refused. Installed by the agent (once, with the installer's\n# sudo cp rights) or by piscreen-harden itself.\nset -eu\ncase \"${1:-}\" in\n  usb-write)\n    p=\"${2:-}\"; v=\"${3:-}\"\n    case \"$v\" in 0|1) ;; *) echo \"bad value\" >&2; exit 2 ;; esac\n    case \"$p\" in *..*|*\" \"*) echo \"bad path\" >&2; exit 2 ;; esac\n    case \"$p\" in\n      /sys/bus/usb/devices/*/authorized|/sys/bus/usb/devices/*/authorized_default) ;;\n      *) echo \"path not allowed\" >&2; exit 2 ;;\n    esac\n    printf '%s' \"$v\" > \"$p\" ;;\n  harden)\n    exec /usr/local/bin/piscreen-harden >>/var/log/piscreen-harden.log 2>&1 ;;\n  install-harden)\n    f=\"${2:-}\"\n    case \"$f\" in /opt/infoscreen-agent/harden-kiosk.sh|/opt/piscreen-agent/harden-kiosk.sh) ;; *) echo \"only the agent's copy\" >&2; exit 2 ;; esac\n    head -c 2 \"$f\" | grep -q '#!' || { echo \"not a script\" >&2; exit 2; }\n    sh -n \"$f\" || { echo \"does not parse\" >&2; exit 2; }\n    install -m 0755 -o root -g root \"$f\" /usr/local/bin/piscreen-harden ;;\n  runner-repair)\n    exec /usr/local/bin/piscreen-harden --runner-only >>/var/log/piscreen-harden.log 2>&1 ;;\n  set-url)\n    u=\"${2:-}\"; prev=\"${3:-}\"\n    printf '%s' \"$u\" | grep -Eq '^https?://[A-Za-z0-9.-]+(:[0-9]{1,5})?$' || { echo \"bad url\" >&2; exit 2; }\n    [ -z \"$prev\" ] || printf '%s' \"$prev\" | grep -Eq '^https?://[A-Za-z0-9.-]+(:[0-9]{1,5})?$' || { echo \"bad previous url\" >&2; exit 2; }\n    f=/etc/piscreen.env; t=$(mktemp)\n    grep -v -e '^PISCREEN_URL=' -e '^PISCREEN_URL_PREVIOUS=' -e '^PISCREEN_MOVED_AT=' \"$f\" > \"$t\" 2>/dev/null || true\n    printf 'PISCREEN_URL=%s\\n' \"$u\" >> \"$t\"\n    [ -z \"$prev\" ] || printf 'PISCREEN_URL_PREVIOUS=%s\\nPISCREEN_MOVED_AT=%s\\n' \"$prev\" \"$(date +%s)\" >> \"$t\"\n    cat \"$t\" > \"$f\"; rm -f \"$t\" ;;\n  *) echo \"usage: piscreen-priv usb-write|harden|install-harden|runner-repair|set-url\" >&2; exit 2 ;;\nesac\n'''\nPRIV_HELPER_SRC = _PRIV_HELPER_NEW if RENAMED else _PRIV_HELPER_LEGACY\n\ndef _run(cmd, timeout=30, **kw):\n    try:\n        return subprocess.run(cmd, capture_output=True, timeout=timeout, **kw)\n    except Exception as e:\n        log.debug('%s failed: %s', cmd[:3], e)\n        return None\n\n\ndef priv_helper_ready():\n    if os.geteuid() == 0:\n        return True\n    if not os.path.isfile(PRIV_HELPER) or not shutil.which('sudo'):\n        return False\n    r = _run(['sudo', '-n', '-l', PRIV_HELPER], timeout=10)\n    return bool(r and r.returncode == 0)\n\n\ndef _install_file(data, dest, mode=0o755):\n    \"\"\"Put `data` at `dest`: directly when allowed, else via the installer's sudo cp.\"\"\"\n    tmp = f'/tmp/.infoscreen-{os.path.basename(dest)}.{os.getpid()}'\n    try:\n        with open(tmp, 'wb') as f:\n            f.write(data)\n        os.chmod(tmp, mode)\n        d = os.path.dirname(dest)\n        if os.access(d, os.W_OK) and (not os.path.exists(dest) or os.access(dest, os.W_OK)):\n            shutil.copy(tmp, dest + '.new')\n            os.chmod(dest + '.new', mode)\n            os.replace(dest + '.new', dest)\n            return True\n        if os.geteuid() != 0 and shutil.which('sudo'):\n            for cmd in (['sudo', '-n', 'cp', tmp, dest], ['sudo', '-n', 'chmod', oct(mode)[2:], dest]):\n                r = _run(cmd)\n                if not r or r.returncode != 0:\n                    log.warning('install %s: %s failed: %s', dest, cmd[2],\n                                (r.stderr if r else b'').decode('utf-8', 'replace').strip()[:160])\n                    return False\n            return True\n    except Exception as e:\n        log.warning('install %s failed: %s', dest, e)\n    finally:\n        try: os.remove(tmp)\n        except Exception: pass\n    return False\n\n\ndef ensure_priv_helper():\n    \"\"\"Give a non-root agent its root helper, once. Returns True when usable.\"\"\"\n    if os.geteuid() == 0:\n        return True\n    try:\n        have = open(PRIV_HELPER, 'rb').read() if os.path.isfile(PRIV_HELPER) else b''\n    except Exception:\n        have = b''\n    if have == PRIV_HELPER_SRC.encode() and priv_helper_ready():\n        return True\n    import pwd\n    user = pwd.getpwuid(os.geteuid()).pw_name\n    if not re.match(r'^[a-z_][a-z0-9_-]{0,31}$', user):\n        log.warning('priv helper: unusual user name %r — not installing', user)\n        return False\n    if not _install_file(PRIV_HELPER_SRC.encode(), PRIV_HELPER, 0o755):\n        log.warning('priv helper: could not install %s (no sudo cp rights?) — the lockdown '\n                    'script installs it at the next boot instead', PRIV_HELPER)\n        return False\n    line = f'# InfoScreen v4.5.0: the display agent may run its root helper, nothing else.\\n{user} ALL=(root) NOPASSWD: {PRIV_HELPER}\\n'\n    if not priv_helper_ready():\n        cand = _private_tmp('.infoscreen-sudoers-check-')\n        with open(cand, 'w') as f:\n            f.write(line)\n        visudo = next((v for v in ('/usr/sbin/visudo', '/sbin/visudo', shutil.which('visudo') or '') if v and os.path.exists(v)), None)\n        if visudo:\n            r = _run([visudo, '-cf', cand], timeout=15)\n            try: os.remove(cand)\n            except OSError: pass\n            if not r or r.returncode != 0:\n                log.warning('priv helper: sudoers line did not validate (%s) — not installing',\n                            (r.stdout + r.stderr).decode('utf-8', 'replace').strip()[:200] if r else 'no visudo')\n                return False\n        if not _install_file(line.encode(), PRIV_SUDOERS, 0o440):\n            return False\n    ok = priv_helper_ready()\n    log.info('priv helper %s', 'ready — USB lock and lockdown can run as root' if ok else 'NOT usable')\n    try:\n        if _usbguard is not None and hasattr(_usbmod, 'reset_helper_check'):\n            _usbmod.reset_helper_check()\n            _usbguard.apply()\n    except Exception:\n        pass\n    return ok\n\n\ndef _sha256(b):\n    return hashlib.sha256(b).hexdigest()\n\n\n_needs_restart = False\n\ndef sync_privileged_components(server, token):\n    \"\"\"Keep privileged screen components identical to the server's copy.\n\n    v4.9.22 also stages the *active* token for the root runner.  The Python\n    agent can provision into /etc/infoscreen.token or ~/.infoscreen.token, while\n    old root runners only sourced PI_TOKEN from /etc/infoscreen.env.  That split\n    let the display agent stay online while infoscreen-commands could never\n    authenticate.  A fixed agent-owned token file gives the root runner the\n    same credential without granting the kiosk user any broader root access.\n\n    v4.9.14 deliberately stages the command runner/updater BEFORE invoking the\n    root hardening pass. The previous order could start hardening in a thread,\n    race ahead of the downloads, and leave an old or missing root runner in\n    place until the next 30-minute component check.\n    \"\"\"\n    global _needs_restart\n    headers = {'X-Pi-Token': token}\n    runner_changed = False\n\n    try:\n        if token:\n            token_path = os.path.join(AGENT_DIR, '.runner-token')\n            old_token = ''\n            try:\n                with open(token_path, 'r', encoding='utf-8') as f:\n                    old_token = f.read().strip()\n            except Exception:\n                pass\n            if old_token != token:\n                tmp = token_path + f'.{os.getpid()}.tmp'\n                with open(tmp, 'w', encoding='utf-8') as f:\n                    f.write(token.strip() + '\\n')\n                os.chmod(tmp, 0o600)\n                os.replace(tmp, token_path)\n                log.info('staged active Pi token for privileged command runner')\n    except Exception as e:\n        log.warning('could not stage privileged-runner token: %s', e)\n\n    # Stage root update scripts first. run_hardening() below installs these\n    # fixed paths through the narrow root helper and restarts their service.\n    # Staged under the names this screen's lockdown script picks them up by.\n    for component, local_name in (('command-runner', N('infoscreen-commands.sh')),\n                                  ('update-helper', N('infoscreen-update.sh')),\n                                  ('boot-repair', N('infoscreen-boot-repair.sh'))):\n        try:\n            r = requests.get(component_url(server, component), headers=headers, timeout=20)\n            if r.status_code == 200 and r.content.startswith(b'#!'):\n                chk = f'/tmp/.infoscreen-{local_name}-check.{os.getpid()}'\n                with open(chk, 'wb') as f:\n                    f.write(r.content)\n                c = _run(['sh', '-n', chk], timeout=15)\n                try: os.remove(chk)\n                except Exception: pass\n                if c and c.returncode == 0:\n                    target = os.path.join(AGENT_DIR, local_name)\n                    try:\n                        have = _sha256(open(target, 'rb').read()) if os.path.isfile(target) else None\n                    except Exception:\n                        have = None\n                    if have != _sha256(r.content) and _install_file(r.content, target, 0o755):\n                        runner_changed = True\n                        log.info('%s staged for the root updater bootstrap', local_name)\n        except Exception as e:\n            log.warning('%s sync failed: %s', component, e)\n\n    harden_changed = False\n    try:\n        r = requests.get(component_url(server, 'harden'), headers=headers, timeout=20)\n        if r.status_code == 200 and r.content.startswith(b'#!'):\n            want = _sha256(r.content)\n            agent_copy = os.path.join(AGENT_DIR, 'harden-kiosk.sh')\n            try:\n                cur = open(agent_copy, 'rb').read() if os.path.isfile(agent_copy) else b''\n            except Exception:\n                cur = b''\n            if _sha256(cur) != want:\n                _install_file(r.content, agent_copy, 0o755)\n            target = HARDEN_BIN\n            try:\n                have = _sha256(open(target, 'rb').read()) if os.path.isfile(target) else None\n            except Exception:\n                have = None\n            if have != want:\n                ok = False\n                if os.geteuid() != 0 and priv_helper_ready():\n                    # Helpers installed before 4.9.51 accept only the old path\n                    # string; it points at this same file before and after the move.\n                    via = HARDEN_COPY_PATH if (os.path.exists(HARDEN_COPY_PATH) and\n                        os.path.realpath(HARDEN_COPY_PATH) == os.path.realpath(agent_copy)) else agent_copy\n                    rr = _run(['sudo', '-n', PRIV_HELPER, 'install-harden', via], timeout=60)\n                    ok = bool(rr and rr.returncode == 0)\n                if not ok:\n                    ok = _install_file(r.content, target, 0o755)\n                log.info('Kiosk lockdown script %s', 'updated to the server\\'s copy' if ok else 'could NOT be updated')\n                harden_changed = bool(ok)\n    except Exception as e:\n        log.warning('lockdown script sync failed: %s', e)\n\n    # Only after all staged inputs exist do we ask root to install/restart them.\n    # Startup also runs hardening unconditionally, so this covers both immediate\n    # upgrades and the recurring 30-minute repair loop.\n    if runner_changed or harden_changed:\n        threading.Thread(target=run_hardening, args=(server,), daemon=True).start()\n\n    try:\n        r = requests.get(component_url(server, 'usbguard'), headers=headers, timeout=30)\n        if r.status_code == 200 and b'UsbGuard' in r.content:\n            guard_path = os.path.join(AGENT_DIR, GUARD_FILE)\n            try:\n                have = _sha256(open(guard_path, 'rb').read()) if os.path.isfile(guard_path) else None\n            except Exception:\n                have = None\n            if have != _sha256(r.content):\n                chk = _private_tmp('.infoscreen-usbguard-check-', '.py')\n                with open(chk, 'wb') as f:\n                    f.write(r.content)\n                c = _run([sys.executable, '-m', 'py_compile', chk], timeout=30)\n                try: os.remove(chk)\n                except OSError: pass\n                if c and c.returncode == 0 and _install_file(r.content, guard_path, 0o755):\n                    log.info('USB guard updated to the server\\'s copy — restarting to load it')\n                    _needs_restart = True\n                    return True\n    except Exception as e:\n        log.warning('USB guard sync failed: %s', e)\n    return False\n\n\n_runner_repair_lock = threading.Lock()\n\n\ndef _runner_ready_now():\n    \"\"\"Return whether the privileged image-update service is actually alive.\"\"\"\n    runner = RUNNER_BIN\n    if not (os.path.isfile(runner) and os.access(runner, os.X_OK)):\n        return False\n    try:\n        if shutil.which('systemctl'):\n            rr = subprocess.run(['systemctl', 'is-active', '--quiet', RUNNER_SVC], timeout=3)\n            return rr.returncode == 0\n        if shutil.which('rc-service'):\n            rr = subprocess.run(['rc-service', RUNNER_SVC, 'status'],\n                                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=3)\n            return rr.returncode == 0\n        return True\n    except Exception:\n        return False\n\n\ndef repair_command_runner(server, token, reason='server request'):\n    \"\"\"Repair/start the root-owned image updater without broadening sudo rights.\n\n    A missing runner used to create the worst possible state for an automatic\n    rollout: the server correctly refused to hand the root-owned bundle to the\n    kiosk user, but nothing actively repaired the root runner, so the command\n    could remain ``I kø`` forever.  The server can now explicitly ask for this\n    repair.  The agent stages canonical scripts, invokes the narrow root helper\n    in ``runner-repair`` mode, then reports fresh metrics immediately.\n    \"\"\"\n    if not _runner_repair_lock.acquire(blocking=False):\n        log.info('Privileged runner repair already in progress')\n        return\n    try:\n        log.warning('Repairing privileged image runner (%s)', reason)\n        log_event(server, token, 'runner_repair_start', str(reason)[:300], retries=2)\n\n        helper_ok = True\n        if os.geteuid() != 0:\n            try:\n                helper_ok = ensure_priv_helper()\n            except Exception as e:\n                helper_ok = False\n                log.warning('runner repair: root helper preparation failed: %s', e)\n\n        try:\n            sync_privileged_components(server, token)\n        except Exception as e:\n            log.warning('runner repair: component staging failed: %s', e)\n\n        repair_ok = False\n        detail = ''\n        if os.geteuid() == 0:\n            # Root installs can invoke only the runner part directly.\n            harden = HARDEN_BIN\n            if os.path.isfile(harden):\n                rr = _run(['sh', harden, '--runner-only'], timeout=90)\n                repair_ok = bool(rr and rr.returncode == 0)\n                if rr and rr.returncode != 0:\n                    detail = (rr.stderr or rr.stdout or b'').decode('utf-8', 'replace').strip()[-300:]\n        elif helper_ok and priv_helper_ready():\n            rr = _run(['sudo', '-n', PRIV_HELPER, 'runner-repair'], timeout=90)\n            repair_ok = bool(rr and rr.returncode == 0)\n            if rr and rr.returncode != 0:\n                detail = (rr.stderr or rr.stdout or b'').decode('utf-8', 'replace').strip()[-300:]\n        else:\n            detail = 'root helper unavailable'\n\n        ready = False\n        # systemd/OpenRC can take a moment to report the freshly restarted unit.\n        for _ in range(12):\n            ready = _runner_ready_now()\n            if ready:\n                break\n            time.sleep(1)\n\n        try:\n            metrics = get_metrics()\n            if metrics:\n                metrics['type'] = 'metrics'\n                ws_send(metrics)\n        except Exception:\n            pass\n\n        if ready:\n            log.info('Privileged image runner is ready')\n            log_event(server, token, 'runner_repair_done', f'{RUNNER_SVC} is active', retries=3)\n        else:\n            msg = detail or ('runner-only repair returned success but service is not active' if repair_ok\n                             else 'runner-only repair failed')\n            log.error('Privileged image runner repair failed: %s', msg)\n            log_event(server, token, 'runner_repair_failed', msg[:900], retries=3)\n    finally:\n        _runner_repair_lock.release()\n\n\ndef component_sync_loop(server, token):\n    while True:\n        time.sleep(1800)\n        try:\n            if sync_privileged_components(server, token) and not _maint:\n                restart_agent_process()\n            # Keep the privileged updater healthy even when no release is being\n            # pushed. A service that died between releases should repair itself\n            # before the next image update arrives (v4.9.20).\n            if not _runner_ready_now():\n                repair_command_runner(server, token, 'periodic self-heal')\n        except Exception as e:\n            log.debug('component sync: %s', e)\n\n\ndef dedupe_openbox_autostart():\n    \"\"\"Stop the Pi's Openbox autostart from launching a second agent: systemd\n    supervises this one (INVOCATION_ID is set only under systemd).\"\"\"\n    if not os.environ.get('INVOCATION_ID'):\n        return\n    for home in ('/home/kiosk', '/home/pi', os.path.expanduser('~')):\n        p = os.path.join(home, '.config', 'openbox', 'autostart')\n        try:\n            txt = open(p).read()\n        except Exception:\n            continue\n        new = re.sub(r'(?m)^(python3 /opt/(?:info|pi)screen-agent/(?:info|pi)screen-agent\\.py &)\\s*$',\n                     r'# \\1   # v4.5.0: systemd runs the agent; a second copy fought it', txt)\n        if new != txt:\n            try:\n                with open(p, 'w') as f:\n                    f.write(new)\n                log.info('Removed the duplicate agent start from %s', p)\n            except Exception as e:\n                log.debug('autostart dedupe: %s', e)\n\n\n# ── Keyboard and mouse off at the display server ──────────────────────\n# USB rules cannot reach a laptop's own keyboard and touchpad (PS/2, I2C),\n# and anything the guard does not stop still types into the kiosk. So every\n# physical keyboard and pointer is switched off in X itself (\"Device\n# Enabled\" = 0). The XTEST devices stay on: that is how Ta kontroll in Live\n# View types, so remote control keeps working with every port locked.\n# Physical maintenance switches everything back on until it ends.\n_input_lock_wake = threading.Event()\n_input_lock = {'available': None, 'method': None, 'locked': 0, 'allowed': 0,\n               'devices': [], 'error': None, 'at': None}\n_XI_SLAVE_USES = (3, 4, 5)        # slave pointer, slave keyboard, floating slave\n\n\ndef _usb_name_for_node(node):\n    \"\"\"/dev/input/event5 -> '1-1.3' (the USB device it hangs off), None if not USB.\"\"\"\n    base = os.path.basename(node or '')\n    if not base.startswith('event'):\n        return None\n    try:\n        real = os.path.realpath(f'/sys/class/input/{base}/device')\n    except Exception:\n        return None\n    found = re.findall(r'/(\\d+-[\\d.]+)(?=/|$)', real)\n    return found[-1] if found else None\n\n\ndef _input_allowed(name, usb):\n    if 'xtest' in (name or '').lower():\n        return True                                   # remote control and the agent itself\n    if _maint and _maint.get('mode') == 'physical':\n        return True                                   # a technician is at the screen\n    g = _usbguard\n    if g is None:\n        return False\n    if getattr(g, '_released', False):\n        return True                                   # same safety valve as the USB guard\n    pol = getattr(g, 'policy', {}) or {}\n    if pol.get('enforce', True) is False:\n        return True                                   # IT chose report-only for this screen\n    if usb and hasattr(g, 'allows_input'):\n        try:\n            return bool(g.allows_input(usb))\n        except Exception:\n            return False\n    return pol.get('internal_input') == 'allow'\n\n\ndef _prop_text(reply):\n    v = getattr(reply, 'value', None)\n    if isinstance(v, tuple) and len(v) == 2 and isinstance(v[0], int):\n        v = v[1]\n    if isinstance(v, (bytes, bytearray)):\n        return bytes(v).decode('utf-8', 'replace').rstrip('\\x00')\n    if isinstance(v, str):\n        return v.rstrip('\\x00')\n    try:\n        return bytes(v).decode('utf-8', 'replace').rstrip('\\x00')\n    except Exception:\n        return ''\n\n\ndef _xi_devices_xlib(d):\n    from Xlib.ext import xinput\n    from Xlib import X\n    node_atom = d.intern_atom('Device Node', only_if_exists=True)\n    out = []\n    for dev in d.xinput_query_device(xinput.AllDevices).devices:\n        if dev.use not in _XI_SLAVE_USES:\n            continue\n        name = dev.name.decode('utf-8', 'replace') if isinstance(dev.name, bytes) else str(dev.name)\n        node = ''\n        if node_atom:\n            try:\n                node = _prop_text(d.xinput_get_device_property(dev.deviceid, node_atom, X.AnyPropertyType, 0, 256))\n            except Exception:\n                node = ''\n        out.append({'id': int(dev.deviceid), 'name': name, 'enabled': bool(dev.enabled), 'node': node})\n    return out\n\n\ndef _xi_set_xlib(d, devid, on):\n    from Xlib import X, Xatom\n    atom = d.intern_atom('Device Enabled')\n    d.xinput_change_device_property(devid, atom, Xatom.INTEGER, X.PropModeReplace,\n                                    (8, b'\\x01' if on else b'\\x00'))\n\n\ndef _xi_devices_cli(env):\n    r = subprocess.run(['xinput', 'list', '--short'], env=env, capture_output=True, text=True, timeout=5)\n    out = []\n    for line in r.stdout.splitlines():\n        m = re.search(r'^[^A-Za-z0-9]*(.*?)\\s+id=(\\d+)\\s+\\[(master|slave|floating slave)', line)\n        if not m or m.group(3) == 'master':\n            continue\n        props = subprocess.run(['xinput', 'list-props', m.group(2)], env=env,\n                               capture_output=True, text=True, timeout=5).stdout\n        node = (re.search(r'Device Node \\(\\d+\\):\\s*\"([^\"]*)\"', props) or [None, ''])[1]\n        en = (re.search(r'Device Enabled \\(\\d+\\):\\s*(\\d)', props) or [None, '1'])[1] == '1'\n        out.append({'id': int(m.group(2)), 'name': m.group(1).strip(), 'enabled': en, 'node': node})\n    return out\n\n\ndef _input_lock_public():\n    s = dict(_input_lock)\n    s['devices'] = list(s.get('devices') or [])[:24]\n    return s\n\n\n# ── Mouse pointer (v4.7.0) ───────────────────────────────────────────\n# The pointer sat in the middle of the screen. `unclutter -idle 1` only hides\n# it once it has moved and then stopped, so a pointer that never moves after\n# X starts is shown for ever; and on a screen installed without unclutter\n# nothing hid it at all. XFixes HideCursor hides it for the whole X server,\n# over Chromium and every web page inside it, for as long as this connection\n# stays open. It comes back during maintenance, where someone uses a mouse,\n# and on screens with SHOW_CURSOR=1 in /etc/infoscreen.env.\n_cursor = {'hidden': None, 'method': None, 'error': None}\n\ndef _cursor_wanted_hidden():\n    if _maint:\n        return False\n    try:\n        return str(load_config().get('SHOW_CURSOR', '')).lower() not in ('1', 'true', 'yes', 'on')\n    except Exception:\n        return True\n\ndef _cursor_fallback(env):\n    \"\"\"No XFixes from Python: start unclutter, whichever flavour is here.\"\"\"\n    if subprocess.run(['pgrep', '-f', 'unclutter'], capture_output=True).returncode == 0:\n        return 'unclutter (running)'\n    for argv in (['unclutter-xfixes', '--timeout', '1', '--start-hidden', '--fork'],\n                 ['unclutter', '--timeout', '1', '--start-hidden', '--fork'],   # Debian's unclutter-xfixes\n                 ['unclutter', '-idle', '1', '-root', '-noevents']):\n        if not shutil.which(argv[0]):\n            continue\n        try:\n            pr = subprocess.Popen(argv, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n            time.sleep(1.5)\n            if pr.poll() in (None, 0):\n                return ' '.join(argv[:2])\n        except Exception:\n            continue\n    return None\n\ndef cursor_hide_loop(display):\n    time.sleep(3)\n    d = root = None\n    fallback_tried = False\n    while True:\n        try:\n            want = _cursor_wanted_hidden()\n            if d is None and _import_xlib():\n                env = _display_env(display)\n                from Xlib import display as xdisplay\n                if env.get('XAUTHORITY'):\n                    os.environ.setdefault('XAUTHORITY', env['XAUTHORITY'])\n                d = xdisplay.Display(env['DISPLAY'])\n                if not d.has_extension('XFIXES'):\n                    raise RuntimeError('X server has no XFIXES extension')\n                d.xfixes_query_version()\n                root = d.screen().root\n                _cursor['hidden'] = None          # new connection: nothing hidden yet\n            if d is not None:\n                if want != _cursor['hidden']:\n                    if want:\n                        root.xfixes_hide_cursor()\n                    else:\n                        root.xfixes_show_cursor()\n                    d.sync()\n                    log.info('Mouse pointer %s', 'hidden' if want else 'shown')\n                    _cursor.update(hidden=want, method='xfixes', error=None)\n                else:\n                    d.sync()                      # notices an X restart (raises)\n            elif want and not fallback_tried:\n                fallback_tried = True\n                m = _cursor_fallback(_display_env(display))\n                _cursor.update(hidden=bool(m), method=m, error=None if m else 'no XFixes and no unclutter')\n                if m:\n                    log.info('Mouse pointer hidden with %s', m)\n                else:\n                    log.warning('Mouse pointer cannot be hidden: no python-xlib/XFixes and no unclutter')\n        except Exception as e:\n            _cursor['error'] = str(e)[:200]\n            try:\n                if d is not None:\n                    d.close()\n            except Exception:\n                pass\n            d = root = None\n            time.sleep(8)                         # X not up yet, or restarting\n        time.sleep(2)\n\n\ndef input_lock_loop(display):\n    time.sleep(8)\n    d = None\n    last = None\n    while True:\n        try:\n            env = _display_env(display)\n            devs, method = None, None\n            if _import_xlib():\n                try:\n                    if d is None:\n                        from Xlib import display as xdisplay\n                        if env.get('XAUTHORITY'):\n                            os.environ.setdefault('XAUTHORITY', env['XAUTHORITY'])\n                        d = xdisplay.Display(env['DISPLAY'])\n                        if not d.has_extension('XInputExtension'):\n                            raise RuntimeError('X server has no XInput extension')\n                        d.xinput_query_version()\n                    devs, method = _xi_devices_xlib(d), 'xlib'\n                except Exception as e:\n                    _input_lock['error'] = f'xlib: {e}'\n                    d = None\n            if devs is None and shutil.which('xinput'):\n                devs, method = _xi_devices_cli(env), 'xinput'\n            if devs is None:\n                _input_lock.update(available=False, method=None)\n            else:\n                locked = allowed = 0\n                listed = []\n                for dv in devs:\n                    usb = _usb_name_for_node(dv['node'])\n                    ok = _input_allowed(dv['name'], usb)\n                    if 'xtest' not in dv['name'].lower():\n                        listed.append({'name': dv['name'][:60], 'usb': usb, 'on': ok})\n                        if ok: allowed += 1\n                        else: locked += 1\n                    if dv['enabled'] != ok:\n                        if method == 'xlib':\n                            _xi_set_xlib(d, dv['id'], ok)\n                        else:\n                            subprocess.run(['xinput', 'set-prop', str(dv['id']), 'Device Enabled', '1' if ok else '0'],\n                                           env=env, capture_output=True, timeout=5)\n                        (log.info if ok else log.warning)('Input lock: %s %s (%s)',\n                            'enabled' if ok else 'DISABLED', dv['name'], usb or 'built-in')\n                if method == 'xlib':\n                    d.sync()\n                _input_lock.update(available=True, method=method, locked=locked, allowed=allowed,\n                                   devices=listed, error=None, at=time.strftime('%Y-%m-%d %H:%M:%S'))\n                summary = (locked, allowed, method)\n                if summary != last:\n                    last = summary\n                    try:\n                        if _usbguard is not None:\n                            report_topology(_usbguard.topology(), policy_applied=_usb_policy_cache is not None)\n                    except Exception:\n                        pass\n        except Exception as e:\n            _input_lock['error'] = str(e)[:200]\n            d = None\n        _input_lock_wake.wait(timeout=1.5)\n        _input_lock_wake.clear()\n\n\ndef ws_metrics_loop(interval):\n    \"\"\"One metrics sender for the life of the agent. It used to be one more\n    thread per reconnect, each sending its own copy for ever.\"\"\"\n    while True:\n        time.sleep(interval)\n        if not _ws_is_up():\n            continue\n        try:\n            m = get_metrics()\n            m['type'] = 'metrics'\n            ws_send(m)\n        except Exception as e:\n            log.debug('Metrics send error: %s', e)\n\n\ndef main():\n    global _cfg, _pi_token\n    if not acquire_single_instance():\n        return\n    threading.Thread(target=ensure_deps, daemon=True).start()\n    init_metrics_db()\n    start_live_server()\n    threading.Thread(target=check_apt_updates, daemon=True).start()\n    cfg = load_config()\n    server   = cfg.get('INFOSCREEN_URL','').rstrip('/')\n    browser  = cfg.get('BROWSER','')\n    display  = cfg.get('DISPLAY',':0')\n    interval = int(cfg.get('POLL_INTERVAL','10'))\n    if not server:\n        log.error('INFOSCREEN_URL not set in %s', CONFIG_FILE); sys.exit(1)\n    configure_network_family(server, force=True)\n    token = cfg.get('PI_TOKEN','') or load_saved_token()\n    if not token:\n        log.info('No token — starting provisioning')\n        # Branded \"awaiting approval\" instead of a black screen while we enrol\n        # and poll. The page flips itself to content the moment IT approves.\n        try: show_hold(server, browser, display, 'pending', '', cfg)\n        except Exception as e: log.debug('hold screen: %s', e)\n        token = provision(cfg)\n        if not token: log.error('Provisioning failed'); sys.exit(1)\n    _cfg = {'server': server, 'token': token}\n    _pi_token = token or ''\n    log.info('Event-Admin screen agent %s (%s). Server: %s', AGENT_VERSION, AGENT_UPSTREAM, server)\n    threading.Thread(target=log_event, args=(server, token, 'agent_start', socket.gethostname()), daemon=True).start()\n    threading.Thread(target=display_keepalive_loop, args=(display,), daemon=True).start()\n\n    # v4.9.40: do not deliberately black the display while the agent performs\n    # component sync/hardening/network work.  Start the authenticated viewer\n    # immediately from the saved device token; the viewer itself has branded\n    # startup/offline states and will receive the short-lived viewer key on the\n    # first heartbeat.  This also means a slow or temporarily unavailable\n    # server can never turn a rebooted Pi into an unexplained black rectangle.\n    global current_viewer_url\n    current_viewer_url = viewer_url_for(server, token)\n    try:\n        open_url(current_viewer_url, browser, display)\n    except Exception as e:\n        log.warning('Initial viewer launch failed; watchdog will retry: %s', e)\n\n    threading.Thread(target=watchdog, args=(server,token,browser,display), daemon=True).start()\n    threading.Thread(target=kiosk_window_guard, args=(server,token,browser,display), daemon=True).start()\n    threading.Thread(target=ensure_display_tuning, args=(server, token), daemon=True).start()   # v4.8.3\n    _EV.update(server=server, token=token)                                                     # v4.9.3: network results to the portal\n    if _IS_ALPINE and _IS_PC:\n        threading.Thread(target=net_failover_loop, daemon=True).start()                        # v4.9.3: cable first, then WiFi\n    threading.Thread(target=extension_sync_loop, args=(server, browser, display), daemon=True).start()\n    threading.Thread(target=journal_forwarder, args=(server, lambda: token), daemon=True).start()\n    threading.Thread(target=live_stream_loop, args=(server, token), daemon=True).start()\n    threading.Thread(target=screen_stream_loop, daemon=True).start()\n    threading.Thread(target=ws_metrics_loop, args=(interval,), daemon=True).start()\n    threading.Thread(target=input_lock_loop, args=(display,), daemon=True).start()\n    threading.Thread(target=cursor_hide_loop, args=(display,), daemon=True).start()\n    try: dedupe_openbox_autostart()\n    except Exception: pass\n\n    # Lock the kiosk down before the browser is ever pointed at content, and\n    # bring the USB guard up deny-by-default. Both run every boot: a package\n    # upgrade or an image restore can quietly put a policy file back, and a\n    # screen that has lost its lockdown should get it back without a visit.\n    # Repair anything a bad bundle left out, before the browser starts — the\n    # consent extension is only read at Chromium launch, so fetching it later\n    # would not take effect until the next restart.\n    components_repaired = False\n    try:\n        if heal_components(server, token):\n            components_repaired = True\n            log.info('Components repaired at startup')\n    except Exception as e:\n        log.warning('Component check failed: %s', e)\n\n    # v4.9.40 launches the branded viewer before these network/component checks\n    # so a reboot never looks like a dead black panel. If startup repair changed\n    # the consent extension, restart Chromium once now so the browser actually\n    # loads the repaired extension; otherwise a missing extension could remain\n    # absent until the next browser crash/reboot even though the file was fixed.\n    if components_repaired and current_viewer_url:\n        try:\n            log.info('Restarting initial viewer after component repair')\n            open_url(current_viewer_url, browser, display)\n        except Exception as e:\n            log.warning('Viewer restart after component repair failed: %s', e)\n\n    # v4.5.0: the root helper, and the lockdown script and USB guard kept\n    # identical to the server's (they used to be fetched only when missing).\n    try:\n        ensure_priv_helper()\n    except Exception as e:\n        log.warning('priv helper: %s', e)\n    try:\n        sync_privileged_components(server, token)\n    except Exception as e:\n        log.warning('Component sync failed: %s', e)\n    if _needs_restart:\n        restart_agent_process()\n    threading.Thread(target=component_sync_loop, args=(server, token), daemon=True).start()\n    threading.Thread(target=move_watchdog, args=(server, token), daemon=True).start()\n\n    threading.Thread(target=run_hardening, args=(server,), daemon=True).start()\n    # Never let the guard take the agent down with it. A screen with no USB\n    # lockdown still shows content and can still be reached; a screen whose\n    # agent died on startup is gone until someone visits it.\n    try:\n        start_usb_guard()\n    except Exception as e:\n        log.error('USB guard failed to start (screen continues unprotected): %s', e)\n\n    # Do one immediate HTTP heartbeat to get config and launch browser fast\n    log.info('Initial heartbeat to get config...')\n    token = heartbeat(server, token, browser, display, cfg) or token\n\n    # Wi-Fi may only have become routable during the first heartbeat. Recheck\n    # the dual-stack path now; if IPv6 is the broken half, relaunch once with\n    # --disable-ipv6 so the viewer cannot spend minutes on an unreachable AAAA.\n    _was_ipv4 = bool(_net_family.get('prefer_ipv4'))\n    _net_family['checked'] = 0.0\n    if configure_network_family(server, force=True) and not _was_ipv4 and current_viewer_url:\n        log.info('Restarting viewer once with IPv4 preference after network became ready')\n        open_url(current_viewer_url, browser, display)\n\n    # Main loop (v4.5.0): WebSocket first, never more than a minute between\n    # attempts, and straight away when the server says someone opened Live\n    # View. The old version could sit on HTTP for 16 minutes after a hiccup.\n    failures = 0\n    last_attempt = 0.0\n    while True:\n        wait = 5 - (time.time() - last_attempt)\n        if wait > 0:\n            time.sleep(wait)\n        last_attempt = time.time()\n        _ws_now.clear()\n        if _websocket_available():\n            log.info('Attempting WebSocket connection...')\n            if ws_connection(server, token, browser, display, cfg):\n                failures = 0\n                log.info('WebSocket closed — reconnecting in 3 s')\n                time.sleep(3)\n                continue\n        failures += 1\n        backoff = min(5 * (2 ** min(failures - 1, 4)), 60)\n        log.info('WebSocket unavailable (attempt %d) — HTTP polling, next try in %ds', failures, backoff)\n        end = time.time() + backoff\n        while time.time() < end:\n            token = heartbeat(server, token, browser, display, cfg) or token\n            if _ws_now.wait(timeout=max(1, min(interval, end - time.time()))):\n                if _websocket_available():\n                    log.info('Server asked for the WebSocket (Live View is open) — connecting now')\n                    break\n                _ws_now.clear()\n\n\nsignal.signal(signal.SIGTERM, lambda s,f: (kill_browser(), sys.exit(0)))\nsignal.signal(signal.SIGINT,  lambda s,f: (kill_browser(), sys.exit(0)))\n\nif __name__ == '__main__':\n    main()\n",
  "install-agent.sh": "#!/bin/bash\n# InfoScreen-Agent installer\n# Raspberry Pi OS Lite (64-bit), Ubuntu, Debian\n# Usage: sudo bash install-agent.sh\n\nset -e\nAGENT_DIR=\"/opt/infoscreen-agent\"\n\necho \"=== InfoScreen-Agent installer ===\"\necho \"\"\n\n# ── Detect run user ───────────────────────────────────────────────\nRUN_USER=\"\"\nfor u in kiosk pi ulldev user ubuntu; do\n    id \"$u\" > /dev/null 2>&1 && RUN_USER=\"$u\" && break\ndone\n[ -z \"$RUN_USER\" ] && RUN_USER=$(logname 2>/dev/null || echo \"pi\")\necho \"Running as user: $RUN_USER\"\n\n# ── Fix hostname resolution ───────────────────────────────────────\n# Read hostname from infoscreen.env if available\nPI_HOSTNAME=\"\"\nif [ -f infoscreen.env ]; then\n    PI_HOSTNAME=$(grep -m1 '^PI_HOSTNAME=' infoscreen.env | cut -d= -f2- | tr -d '\"' | tr -d \"'\" | tr -d '[:space:]')\nfi\n\nif [ -n \"$PI_HOSTNAME\" ]; then\n    echo \"Setting hostname to: $PI_HOSTNAME\"\n    hostnamectl set-hostname \"$PI_HOSTNAME\" 2>/dev/null || echo \"$PI_HOSTNAME\" > /etc/hostname\n    # Update /etc/hosts\n    sed -i \"s/127.0.1.1.*/127.0.1.1\\t$PI_HOSTNAME/\" /etc/hosts 2>/dev/null || \\\n        echo \"127.0.1.1 $PI_HOSTNAME\" >> /etc/hosts\nfi\n\nCURRENT_HOSTNAME=$(hostname)\nif ! grep -q \"127.0.0.1.*$CURRENT_HOSTNAME\" /etc/hosts 2>/dev/null; then\n    echo \"Fixing hostname: $CURRENT_HOSTNAME\"\n    echo \"127.0.0.1 $CURRENT_HOSTNAME\" >> /etc/hosts\n    echo \"::1 $CURRENT_HOSTNAME\" >> /etc/hosts\nfi\n\n# ── Clear stale token ─────────────────────────────────────────────\n#\n# Only on a genuine first install. This used to run unconditionally, so every\n# re-run wiped the token of an already-registered screen and the Pi re-\n# provisioned itself — which, combined with a first-boot unit that never\n# disarmed, meant a fresh duplicate device in the portal on every single boot.\n#\n# INFOSCREEN_FORCE_REPROVISION=1 restores the old behaviour when a screen really\n# does need to be re-registered.\nif [ -f /etc/infoscreen.token ]; then\n    if [ -s /etc/infoscreen.token ] && [ ! -f /var/lib/infoscreen/firstrun.done ] \\\n       && [ \"${INFOSCREEN_FORCE_REPROVISION:-0}\" != \"1\" ]; then\n        echo \"Keeping the existing token — this device is already provisioned.\"\n        echo \"  (set INFOSCREEN_FORCE_REPROVISION=1 to re-register it)\"\n    elif [ \"${INFOSCREEN_FORCE_REPROVISION:-0}\" = \"1\" ] || [ ! -s /etc/infoscreen.token ]; then\n        echo \"Removing stale token — will re-provision on start\"\n        rm -f /etc/infoscreen.token\n    else\n        echo \"Keeping the existing token — this device is already provisioned.\"\n    fi\nfi\n\n# ── Install packages ──────────────────────────────────────────────\nif command -v apt-get > /dev/null 2>&1; then\n    echo \"Installing packages...\"\n\n    # apt-get update is NOT allowed to be fatal here.\n    #\n    # This script runs under `set -e`, and apt-daily.service fires on the same\n    # boot as the first-boot install. When the two collide, apt-get update\n    # returns non-zero, `set -e` kills this script instantly, and the caller\n    # reports \"[FAILED] Failed to start infoscreen-firstrun.service\" with no\n    # indication that the only problem was a lock held for ten seconds.\n    #\n    # So: wait for the locks properly, retry, and carry on either way — the\n    # package installs below already tolerate a stale index, and the Python\n    # module verification further down is what actually decides success.\n    for _lock in /var/lib/dpkg/lock-frontend /var/lib/apt/lists/lock /var/cache/apt/archives/lock; do\n        _w=0\n        while fuser \"$_lock\" >/dev/null 2>&1 && [ \"$_w\" -lt 24 ]; do\n            [ $((_w % 4)) = 0 ] && echo \"  waiting for $_lock ($((_w * 5))s)...\"\n            sleep 5; _w=$((_w + 1))\n        done\n    done\n\n    APT_UPDATED=0\n    for _try in 1 2 3; do\n        if apt-get update -qq -o DPkg::Lock::Timeout=120; then\n            APT_UPDATED=1; break\n        fi\n        echo \"  apt-get update failed (attempt $_try/3), retrying in 15s...\"\n        sleep 15\n    done\n    [ \"$APT_UPDATED\" = 1 ] || echo \"WARNING: apt-get update did not succeed — continuing with the cached index\"\n    # Python dependencies come from apt, not pip.\n    #\n    # Debian 12 and 13 mark the system Python as externally managed (PEP 668),\n    # so `pip3 install requests` fails outright. The old line papered over that\n    # with --break-system-packages and a bare fallback — and because this script\n    # runs under `set -e`, both attempts failing killed the install here, with\n    # the error sent to /dev/null. The visible result is a Pi that boots to a\n    # login prompt and no kiosk, with nothing explaining why.\n    #\n    # Every one of these exists in Debian, so apt is both more reliable and\n    # faster than building wheels on a Pi.\n    apt-get install -y \\\n        python3 python3-pip \\\n        python3-requests python3-psutil python3-websocket \\\n        xorg xserver-xorg xinit \\\n        openbox \\\n        xdotool unclutter scrot ffmpeg \\\n        xterm python3-xlib \\\n        curl \\\n        keyboard-configuration console-setup \\\n        --no-install-recommends -qq || \\\n      echo \"WARNING: some packages failed to install — see above\" \n\n    # ── Keyboard layout (Norwegian by default) ───────────────────────\n    # Debian: /etc/default/keyboard drives both the console (console-setup) and\n    # X (the xorg keyboard InputClass reads the same file). A US map on a\n    # Norwegian keyboard misplaces | / \\ @ and the quotes, which makes a rescue\n    # shell almost unusable. INFOSCREEN_KEYMAP overrides the default.\n    _KM=\"${INFOSCREEN_KEYMAP:-no}\"\n    cat > /etc/default/keyboard << KBEOF\nXKBMODEL=\"pc105\"\nXKBLAYOUT=\"$_KM\"\nXKBVARIANT=\"${INFOSCREEN_KEYMAP_VARIANT:-}\"\nXKBOPTIONS=\"\"\nBACKSPACE=\"guess\"\nKBEOF\n    # Apply to the console now; X picks it up from the same file when it starts.\n    if command -v setupcon >/dev/null 2>&1; then\n      setupcon --save-only 2>/dev/null || true\n      setupcon 2>/dev/null || true\n    fi\n    DEBIAN_FRONTEND=noninteractive dpkg-reconfigure -f noninteractive \\\n      keyboard-configuration >/dev/null 2>&1 || true\n    echo \"Keyboard layout set to $_KM\"\n\n    # ── Chromium — try both package names ────────────────────────────\n    apt-get install -y chromium --no-install-recommends -qq 2>/dev/null || \\\n    apt-get install -y chromium-browser --no-install-recommends -qq 2>/dev/null || \\\n    echo \"WARNING: chromium not found — install manually\"\n\nelif command -v apk > /dev/null 2>&1; then\n    apk add --no-cache python3 py3-pip chromium xorg-server xinit openbox xdotool curl\nelif command -v dnf > /dev/null 2>&1; then\n    dnf install -y python3 python3-pip chromium xorg-x11-server-Xorg xinit openbox curl\nfi\n\n# ── Detect chromium binary ────────────────────────────────────────\nCHROMIUM_BIN=\"\"\nfor b in chromium chromium-browser google-chrome; do\n    command -v \"$b\" > /dev/null 2>&1 && CHROMIUM_BIN=\"$b\" && break\ndone\n[ -z \"$CHROMIUM_BIN\" ] && CHROMIUM_BIN=\"chromium\"\necho \"Chromium binary: $CHROMIUM_BIN\"\n\n# ── Python dependencies ───────────────────────────────────────────\necho \"Installing Python packages...\"\n# Only fill gaps apt could not. Never fatal on its own — the verification\n# below is what decides whether the agent can actually run.\nfor mod in requests psutil websocket; do\n    python3 -c \"import $mod\" 2>/dev/null && continue\n    case \"$mod\" in\n      websocket) pkg=websocket-client ;;\n      *)         pkg=\"$mod\" ;;\n    esac\n    echo \"  $mod missing after package install — trying pip for $pkg\"\n    pip3 install \"$pkg\" --break-system-packages -q 2>/dev/null \\\n      || pip3 install \"$pkg\" -q 2>/dev/null \\\n      || echo \"  WARNING: could not install $pkg\"\ndone\n\n# Verify, and say exactly what is missing. The agent imports these at startup;\n# without them the service fails on every boot and the screen sits at a login\n# prompt looking like a broken OS.\nMISSING=\"\"\nfor mod in requests psutil websocket; do\n    python3 -c \"import $mod\" 2>/dev/null || MISSING=\"$MISSING $mod\"\ndone\nif [ -n \"$MISSING\" ]; then\n    echo \"\"\n    echo \"ERROR: the agent cannot run — missing Python modules:$MISSING\"\n    echo \"       Install with: apt-get install -y python3-requests python3-psutil python3-websocket\"\n    exit 1\nfi\necho \"Python dependencies OK (requests, psutil, websocket)\"\n\n# ── Install agent ─────────────────────────────────────────────────\nmkdir -p \"$AGENT_DIR\"\nchown -R ${RUN_USER}:${RUN_USER} \"$AGENT_DIR\"\ncp infoscreen-agent.py \"$AGENT_DIR/\"\nchmod +x \"$AGENT_DIR/infoscreen-agent.py\"\nchown ${RUN_USER}:${RUN_USER} \"$AGENT_DIR/infoscreen-agent.py\"\n\n# Cookie/consent extension. This was referenced in the browser launch flags all\n# along but never actually copied, so Chromium was being pointed at a directory\n# that did not exist and silently started without it — which is why consent\n# banners were never dismissed on any site.\nif [ -d cookie-dismiss ]; then\n  rm -rf \"$AGENT_DIR/cookie-dismiss\"\n  cp -r cookie-dismiss \"$AGENT_DIR/\"\n  chmod -R a+rX \"$AGENT_DIR/cookie-dismiss\"\n  # Owned by the agent's user, so the agent can replace it with a newer\n  # version from the server without root (v4.0.0).\n  chown -R ${RUN_USER}:${RUN_USER} \"$AGENT_DIR/cookie-dismiss\" 2>/dev/null || true\n  echo \"  cookie-dismiss extension installed\"\nfi\n\n# USB guard. Without this file the agent still runs, but the screen's USB ports\n# accept anything — which is the hole this release exists to close, so it is\n# installed unconditionally and the agent logs loudly if it is missing.\nif [ -f infoscreen-usbguard.py ]; then\n  cp infoscreen-usbguard.py \"$AGENT_DIR/\"\n  chmod 0755 \"$AGENT_DIR/infoscreen-usbguard.py\"\nfi\n\n# Kiosk hardening (Chromium policy, no VT switching, no console gettys).\n#\n# This used to say \"run on every boot by the agent\". Nothing ran it: the\n# agent's run_hardening() was never called, and the agent runs as $RUN_USER, so\n# it could not have written /etc/chromium or masked gettys anyway. The portal\n# then showed \"Kiosk-lås\" and \"Chromium-policy\" as missing forever, reboots or\n# not (ITDemo2). The laptop has always run it as root on every boot from\n# /etc/local.d; the Pi now does the same through a oneshot unit ordered before\n# the agent, and runs it once right here so it is in force before first boot.\nfor h in kiosk/harden-kiosk.sh ../scripts/kiosk/harden-kiosk.sh harden-kiosk.sh; do\n  if [ -f \"$h\" ]; then\n    install -m 0755 \"$h\" /usr/local/bin/infoscreen-harden 2>/dev/null || {\n      cp \"$h\" \"$AGENT_DIR/harden-kiosk.sh\"; chmod +x \"$AGENT_DIR/harden-kiosk.sh\"; }\n    break\n  fi\ndone\n\ncat > /etc/systemd/system/infoscreen-harden.service << 'HARDENEOF'\n[Unit]\nDescription=InfoScreen kiosk lockdown (Chromium policy, VT switching, console)\nBefore=infoscreen-agent.service\nAfter=local-fs.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/bin/sh -c 'if [ -x /usr/local/bin/infoscreen-harden ]; then exec /usr/local/bin/infoscreen-harden; else exec /bin/sh /opt/infoscreen-agent/harden-kiosk.sh; fi >>/var/log/infoscreen-harden.log 2>&1'\n\n[Install]\nWantedBy=multi-user.target\nHARDENEOF\n\n# ── Install config ────────────────────────────────────────────────\nif [ -f infoscreen.env ]; then\n    cp infoscreen.env /etc/infoscreen.env\n    echo \"Installed pre-configured infoscreen.env\"\nelif [ ! -f /etc/infoscreen.env ]; then\n    cat > /etc/infoscreen.env << 'ENVEOF'\nINFOSCREEN_URL=https://infoscreen.yourdomain.com\nPROVISION_SECRET=\nPI_TOKEN=\nPOLL_INTERVAL=10\nBROWSER=\nDISPLAY=:0\nENVEOF\n    echo \"Created /etc/infoscreen.env — edit INFOSCREEN_URL and PROVISION_SECRET\"\nfi\n\n# ── Install identity ──────────────────────────────────────────────\n# A random UUID, minted once and kept in /etc/infoscreen.env. This is what the\n# server knows the screen by — never a MAC address.\n#\n# On a Pi that means the identity lives on the SD card, so moving a card into\n# another board keeps the same screen with the same content, which is how these\n# actually get serviced. The laptop installer does the same thing at install\n# time, so both platforms behave identically.\nif ! grep -q '^INSTALL_ID=.\\+' /etc/infoscreen.env 2>/dev/null; then\n    NEW_ID=$(cat /proc/sys/kernel/random/uuid 2>/dev/null)\n    [ -z \"$NEW_ID\" ] && NEW_ID=$(od -An -tx1 -N16 /dev/urandom 2>/dev/null | tr -d ' \\n')\n    [ -z \"$NEW_ID\" ] && NEW_ID=\"inst-$(date +%s)-$$\"\n    sed -i '/^INSTALL_ID=/d' /etc/infoscreen.env\n    echo \"INSTALL_ID=$NEW_ID\" >> /etc/infoscreen.env\n    echo \"Assigned install identity: $NEW_ID\"\nelse\n    echo \"Keeping existing install identity: $(grep '^INSTALL_ID=' /etc/infoscreen.env | cut -d= -f2)\"\nfi\n\n# Update BROWSER in env if we found chromium\nif [ -n \"$CHROMIUM_BIN\" ]; then\n    sed -i \"s|^BROWSER=.*|BROWSER=$CHROMIUM_BIN|\" /etc/infoscreen.env\nfi\n\n# ── Create token file with correct permissions ────────────────────\ntouch /etc/infoscreen.token\nchown ${RUN_USER}:${RUN_USER} /etc/infoscreen.token\nchmod 600 /etc/infoscreen.token\necho \"Token file created: /etc/infoscreen.token (owned by $RUN_USER)\"\n\n# ── Fix TTY permissions for X ─────────────────────────────────────\nusermod -a -G tty,video,input,render \"$RUN_USER\" 2>/dev/null || true\n\n# udev rules for persistent TTY permissions\ncat > /etc/udev/rules.d/99-infoscreen.rules << 'UDEVEOF'\nKERNEL==\"tty0\", GROUP=\"tty\", MODE=\"0660\"\nKERNEL==\"tty1\", GROUP=\"tty\", MODE=\"0660\"\nUDEVEOF\n\n# Apply immediately\nchmod 660 /dev/tty0 /dev/tty1 2>/dev/null || true\n\n# ── Display driver (modesetting + KMS) ────────────────────────────\n# Debian Trixie dropped fbdev — Pi needs modesetting with KMS overlay.\n# Pi 5 (BCM2712) has two DRM cards: card0 = V3D (3D-only, no display)\n# and card1 = vc4-drm (HDMI connectors). X falls back to card0 and\n# fails with \"no screens found\" unless we explicitly ignore V3D and\n# pin the display card.\nmkdir -p /etc/X11/xorg.conf.d\n\n# Auto-detect: find the card with HDMI connectors\nDISPLAY_CARD=\"\"\nfor card in /dev/dri/card*; do\n    cardname=$(basename \"$card\")\n    if ls /sys/class/drm/${cardname}-HDMI-A-* >/dev/null 2>&1 || \\\n       ls /sys/class/drm/${cardname}-DP-*     >/dev/null 2>&1; then\n        DISPLAY_CARD=\"$card\"\n        echo \"Detected display card: $DISPLAY_CARD\"\n        break\n    fi\ndone\n\n# Check if V3D-only card exists (Pi 5 dual-card setup)\nHAS_V3D_ONLY=false\nfor card in /dev/dri/card*; do\n    cardname=$(basename \"$card\")\n    driverfile=\"/sys/class/drm/${cardname}/device/uevent\"\n    if [ -f \"$driverfile\" ] && grep -q \"DRIVER=v3d\" \"$driverfile\"; then\n        # This card is V3D-only (no connectors) — must be ignored\n        HAS_V3D_ONLY=true\n        echo \"Found V3D-only card: $card (will be ignored by X)\"\n        break\n    fi\ndone\n\nif [ -n \"$DISPLAY_CARD\" ]; then\n    if [ \"$HAS_V3D_ONLY\" = true ]; then\n        # Pi 5: ignore V3D card, pin display card explicitly\n        cat > /etc/X11/xorg.conf.d/98-modesetting.conf << XEOF\nSection \"OutputClass\"\n    Identifier \"v3d-ignore\"\n    MatchDriver \"v3d\"\n    Option \"Ignore\" \"true\"\nEndSection\n\nSection \"Device\"\n    Identifier \"default\"\n    Driver \"modesetting\"\n    Option \"kmsdev\" \"$DISPLAY_CARD\"\n    Option \"PrimaryGPU\" \"true\"\nEndSection\nXEOF\n        echo \"Xorg config: Pi 5 mode (ignore V3D, pin $DISPLAY_CARD)\"\n    else\n        # Pi 4 / single-card: simple modesetting\n        cat > /etc/X11/xorg.conf.d/98-modesetting.conf << XEOF\nSection \"Device\"\n    Identifier \"default\"\n    Driver \"modesetting\"\n    Option \"kmsdev\" \"$DISPLAY_CARD\"\nEndSection\nXEOF\n        echo \"Xorg config: single-card mode ($DISPLAY_CARD)\"\n    fi\nelse\n    # Fallback: no HDMI connector detected, use generic config\n    cat > /etc/X11/xorg.conf.d/98-modesetting.conf << 'XEOF'\nSection \"Device\"\n    Identifier \"default\"\n    Driver \"modesetting\"\nEndSection\nXEOF\n    echo \"Xorg config: generic fallback (no HDMI connector detected)\"\nfi\n\n# Ensure KMS overlay is enabled in Pi config\n# hdmi_force_hotplug=1 keeps HDMI active even when TV input switches away\nif [ -f /boot/firmware/config.txt ]; then\n  grep -q \"dtoverlay=vc4-kms-v3d\" /boot/firmware/config.txt || echo \"dtoverlay=vc4-kms-v3d\" >> /boot/firmware/config.txt\n  grep -q \"hdmi_force_hotplug\" /boot/firmware/config.txt || echo \"hdmi_force_hotplug=1\" >> /boot/firmware/config.txt\n  grep -q \"hdmi_blanking\" /boot/firmware/config.txt || echo \"hdmi_blanking=0\" >> /boot/firmware/config.txt\nelif [ -f /boot/config.txt ]; then\n  grep -q \"dtoverlay=vc4-kms-v3d\" /boot/config.txt || echo \"dtoverlay=vc4-kms-v3d\" >> /boot/config.txt\n  grep -q \"hdmi_force_hotplug\" /boot/config.txt || echo \"hdmi_force_hotplug=1\" >> /boot/config.txt\n  grep -q \"hdmi_blanking\" /boot/config.txt || echo \"hdmi_blanking=0\" >> /boot/config.txt\nfi\n\n# ── Disable screen blanking ───────────────────────────────────────\nmkdir -p /etc/X11/xorg.conf.d\ncat > /etc/X11/xorg.conf.d/99-infoscreen.conf << 'XEOF'\nSection \"ServerFlags\"\n  Option \"BlankTime\" \"0\"\n  Option \"StandbyTime\" \"0\"\n  Option \"SuspendTime\" \"0\"\n  Option \"OffTime\" \"0\"\nEndSection\nSection \"Monitor\"\n  Identifier \"Monitor0\"\n  Option \"DPMS\" \"false\"\nEndSection\nXEOF\n\n# ── Openbox autostart ─────────────────────────────────────────────\nmkdir -p /home/${RUN_USER}/.config/openbox\ncat > /home/${RUN_USER}/.config/openbox/autostart << OBEOF\n# Disable screen blanking\nxset s reset &\nxset dpms force on &\nxset s off &\nxset s noblank &\nxset -dpms &\n\n# Hide the mouse pointer. The agent hides it for the whole X session through\n# XFixes (v4.7.0); this is the fallback. Classic unclutter only hides a pointer\n# that has moved and stopped, so prefer the xfixes flavour when it is here.\nif unclutter --help 2>&1 | grep -q start-hidden; then\n  unclutter --timeout 1 --start-hidden &\nelse\n  unclutter -idle 1 -root -noevents &\nfi\n\n# The agent is started by systemd (infoscreen-agent.service), not here: a\n# second copy from this file fought the first one for the connection and\n# Live View was \"not connected\" most of the time (v4.5.0).\nOBEOF\nchown -R ${RUN_USER}:${RUN_USER} /home/${RUN_USER}/.config 2>/dev/null || true\n\n# ── .bashrc X autostart (runs on autologin to tty1) ──────────────\n# Remove any old infoscreen block first\nsed -i '/# InfoScreen X autostart/,/^fi$/d' /home/${RUN_USER}/.bashrc 2>/dev/null || true\n\ncat >> /home/${RUN_USER}/.bashrc << BASHEOF\n\n# InfoScreen X autostart\nif [ -z \"\\$DISPLAY\" ] && [ \"\\$(tty)\" = \"/dev/tty1\" ]; then\n  sudo xinit /usr/bin/openbox-session -- :0 vt1 -nolisten tcp\nfi\nBASHEOF\n\n# ── Allow pi to run xinit without password ────────────────────────\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /usr/bin/xinit\" > /etc/sudoers.d/infoscreen-xinit\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /sbin/reboot\" >> /etc/sudoers.d/infoscreen-xinit\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /usr/sbin/reboot\" >> /etc/sudoers.d/infoscreen-xinit\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /usr/sbin/netplan\" >> /etc/sudoers.d/infoscreen-xinit\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /usr/bin/netplan\" >> /etc/sudoers.d/infoscreen-xinit\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /usr/bin/apt-get\" >> /etc/sudoers.d/infoscreen-xinit\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /usr/bin/cp\" >> /etc/sudoers.d/infoscreen-xinit\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /bin/cp\" >> /etc/sudoers.d/infoscreen-xinit\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /usr/bin/chmod\" >> /etc/sudoers.d/infoscreen-xinit\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /bin/chmod\" >> /etc/sudoers.d/infoscreen-xinit\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /usr/bin/nmcli\" >> /etc/sudoers.d/infoscreen-xinit\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /usr/bin/rfkill\" >> /etc/sudoers.d/infoscreen-xinit\necho \"${RUN_USER} ALL=(ALL) NOPASSWD: /sbin/rfkill\" >> /etc/sudoers.d/infoscreen-xinit\nchmod 440 /etc/sudoers.d/infoscreen-xinit\n\n# Ensure WiFi radio is unblocked on boot\ncat > /etc/rc.local << 'RCEOF'\n#!/bin/sh\nrfkill unblock wifi 2>/dev/null || true\nexit 0\nRCEOF\nchmod +x /etc/rc.local\n\n# ── Enable autologin on tty1 ──────────────────────────────────────\nmkdir -p /etc/systemd/system/getty@tty1.service.d\ncat > /etc/systemd/system/getty@tty1.service.d/autologin.conf << AUTOEOF\n[Service]\nExecStart=\nExecStart=-/sbin/agetty --autologin ${RUN_USER} --noclear %I \\$TERM\nAUTOEOF\n\n# ── Systemd agent service ─────────────────────────────────────────\ncat > /etc/systemd/system/infoscreen-agent.service << SVCEOF\n[Unit]\nDescription=Event-Admin screen agent\nAfter=network-online.target\nWants=network-online.target\n\n[Service]\nType=simple\nUser=${RUN_USER}\nGroup=${RUN_USER}\nEnvironment=DISPLAY=:0\nEnvironment=XAUTHORITY=/home/${RUN_USER}/.Xauthority\nEnvironmentFile=/etc/infoscreen.env\nExecStartPre=/bin/sleep 3\nExecStart=/usr/bin/python3 /opt/infoscreen-agent/infoscreen-agent.py\nRestart=always\nRestartSec=15\nStandardOutput=journal\nStandardError=journal\n\n[Install]\nWantedBy=multi-user.target\nSVCEOF\n\n# ── Put the status on the login screen ────────────────────────────────────\n#\n# Every report from a Pi has been a photograph of \"nypi login:\", and from that\n# alone there was no way to tell whether the agent was missing, stopped, or\n# running with its display failing — so every round ended with \"please log in\n# and run these commands\". The login screen is the one thing always in the\n# photo, so it now carries the answer. agetty prints /etc/issue.d/*.issue\n# above the prompt; this rewrites that file on every boot, before getty.\ncat > /usr/local/sbin/infoscreen-issue << 'ISSUEEOF'\n#!/bin/sh\nF=/etc/issue.d/infoscreen.issue\nmkdir -p /etc/issue.d\nAV=$(grep -m1 AGENT_VERSION /opt/infoscreen-agent/infoscreen-agent.py 2>/dev/null | sed \"s/.*= *['\\\"]//; s/['\\\"].*//\")\nAS=$(systemctl is-active infoscreen-agent.service 2>/dev/null)\nAE=$(systemctl is-enabled infoscreen-agent.service 2>/dev/null)\nEXP=$(grep -m1 '^PI_HOSTNAME=' /etc/infoscreen.env 2>/dev/null | cut -d= -f2- | tr -d '\"'\"'\"' ')\nSRV=$(grep -m1 '^INFOSCREEN_URL=' /etc/infoscreen.env 2>/dev/null | cut -d= -f2- | tr -d '\"'\"'\"' ')\nTOK=no; [ -s /etc/infoscreen.token ] && TOK=yes\n# Reachability, with belt AND braces on the timeout. curl -m bounds the whole\n# request, but a hung DNS lookup can still stall before curl arms its timer, so\n# also cap the connect phase and wrap the lot in `timeout`. This banner must\n# never be the reason a boot or a getty stalls.\nREACH=unknown\nif [ -n \"$SRV\" ]; then\n  if command -v timeout >/dev/null 2>&1; then\n    timeout 8 curl -fsS -m 6 --connect-timeout 4 -o /dev/null \"$SRV\" 2>/dev/null \\\n      && REACH=yes || REACH=NO\n  else\n    curl -fsS -m 6 --connect-timeout 4 -o /dev/null \"$SRV\" 2>/dev/null \\\n      && REACH=yes || REACH=NO\n  fi\nfi\n{\n  echo \"InfoScreen agent ${AV:-NOT INSTALLED} : ${AS:-unknown} (enabled: ${AE:-no})\"\n  echo \"  server ${SRV:-<none>} reachable: $REACH   enrolled: $TOK\"\n  [ -n \"$EXP\" ] && [ \"$EXP\" != \"$(hostname)\" ] && echo \"  hostname is $(hostname), expected $EXP\"\n  [ \"$AS\" != \"active\" ] && echo \"  -> journalctl -u infoscreen-agent -b    for why\"\n  echo\n} > \"$F.tmp\" && mv \"$F.tmp\" \"$F\"\nISSUEEOF\nchmod 0755 /usr/local/sbin/infoscreen-issue\n\ncat > /etc/systemd/system/infoscreen-issue.service << 'UNITEOF'\n[Unit]\nDescription=InfoScreen status on the login screen\n# NOT before getty, and nothing waits on it.\n#\n# The first version of this unit hung boot for 7+ minutes with \"no limit\",\n# because it was Type=oneshot with no timeout, it ran a network curl on the\n# critical path, and its ExecStartPost restarted getty@tty1 while the unit was\n# itself ordered Before=getty@tty1 — a getty waiting on a job that was waiting\n# on the getty. It now runs entirely in the background, after boot, and blocks\n# nothing.\nAfter=infoscreen-agent.service\n\n[Service]\nType=simple\n# The whole thing is backgrounded: refresh the login banner a few times as the\n# agent settles, then exit. Nothing depends on this unit, so a hang here can\n# only affect this unit — and it cannot hang anyway, because the status script\n# has hard timeouts on every external call.\nExecStart=/bin/sh -c 'for _i in 0 10 30 60; do sleep \"$_i\"; /usr/local/sbin/infoscreen-issue; done'\nTimeoutStartSec=180\nRestart=no\n# Redraw the login prompt so the freshly written banner shows without a manual\n# keypress. This is fire-and-forget and never waited on.\nExecStartPost=-/bin/systemctl kill -s SIGHUP getty@tty1.service\n\n[Install]\nWantedBy=multi-user.target\nUNITEOF\n\nsystemctl daemon-reload\nsystemctl enable infoscreen-agent\nsystemctl enable infoscreen-harden.service 2>/dev/null || true\n# Apply the lockdown now, with /etc/infoscreen.env in place, so it is in force\n# before the first real boot instead of waiting for it.\nif [ -x /usr/local/bin/infoscreen-harden ]; then\n  /usr/local/bin/infoscreen-harden >>/var/log/infoscreen-harden.log 2>&1 \\\n    && echo \"Kiosk hardening applied\" || echo \"WARN: kiosk hardening failed (see /var/log/infoscreen-harden.log)\"\nelif [ -f \"$AGENT_DIR/harden-kiosk.sh\" ]; then\n  /bin/sh \"$AGENT_DIR/harden-kiosk.sh\" >>/var/log/infoscreen-harden.log 2>&1 \\\n    && echo \"Kiosk hardening applied\" || echo \"WARN: kiosk hardening failed (see /var/log/infoscreen-harden.log)\"\nfi\nsystemctl enable infoscreen-issue.service 2>/dev/null || true\n/usr/local/sbin/infoscreen-issue 2>/dev/null || true\n\n# Enable autologin\nsystemctl enable getty@tty1.service 2>/dev/null || true\n\necho \"\"\necho \"=== Installation complete ===\"\necho \"\"\necho \"User:     $RUN_USER\"\necho \"Chromium: $CHROMIUM_BIN\"\necho \"Token:    /etc/infoscreen.token (writable by $RUN_USER)\"\necho \"\"\nif grep -q \"yourdomain\" /etc/infoscreen.env 2>/dev/null; then\n    echo \"IMPORTANT: Edit config before starting:\"\n    echo \"  sudo nano /etc/infoscreen.env\"\n    echo \"\"\nfi\necho \"Reboot to start automatically:\"\necho \"  sudo reboot\"\necho \"\"\necho \"Or start manually now:\"\necho \"  sudo systemctl start infoscreen-agent\"\necho \"  sudo xinit /usr/bin/openbox-session -- :0 vt1 -nolisten tcp\"\necho \"\"\necho \"Logs:\"\necho \"  journalctl -u infoscreen-agent -f\"\n",
  "firstrun-infoscreen.sh": "#!/bin/bash\n# InfoScreen First-Boot Installer\n# Run: sudo bash /boot/firmware/firstrun-infoscreen.sh\n#\n# When used with infoscreen-firstrun.service (dropped on bootfs),\n# systemd handles ordering (After=network-online.target).\n# When run manually, the script waits for network itself.\n#\n# The heavy lifting still lives in install-agent.sh. What changed is the look:\n# if the package ships tui.sh (the same status screen the laptop installer and\n# the boot splash use), we render the whole first boot through it instead of\n# raw apt/unzip output. If tui.sh is not found we fall back to plain echo, so a\n# stripped-down package still installs exactly as before.\n\nset -e\nLOG=/var/log/infoscreen-install.log\nSTAMP=/var/lib/infoscreen/firstrun.done\nBOOTDIR=/boot/firmware\n[ -d \"$BOOTDIR\" ] || BOOTDIR=/boot\n\n# ── Already done? ─────────────────────────────────────────────────────────\n#\n# Nothing used to turn this off. The script ends in `reboot`, the unit stays\n# enabled and /boot/firmware/firstrun-infoscreen.sh stays in place, so it fired\n# again on the next boot, and the next. Either it \"succeeded\" and rebooted —\n# an endless reboot loop — or it failed and the console showed\n#\n#     [FAILED] Failed to start infoscreen-firstrun.service\n#\n# on a Pi where the agent was already installed and running perfectly well.\n# A first-boot installer has to be able to tell that the first boot is over.\nif [ -f \"$STAMP\" ]; then\n    echo \"InfoScreen first-boot install already completed on $(cat \"$STAMP\" 2>/dev/null). Nothing to do.\"\n    exit 0\nfi\n\n# ── Disarm ────────────────────────────────────────────────────────────────\n# Called once the install has actually verified. Removes the trigger, the\n# payload and the unit, so the next boot is a normal boot.\ninfoscreen_disarm() {\n    # A service must not demolish its own unit while it is running inside it.\n    #\n    # This used to `systemctl disable`, delete /etc/systemd/system/\n    # infoscreen-firstrun.service, delete the very script it was executing, and\n    # then daemon-reload — all from inside that service. systemd reloads, finds\n    # the unit gone, and can no longer complete the start job, so it reports\n    #\n    #     [FAILED] Failed to start infoscreen-firstrun.service\n    #\n    # on an install that had just succeeded. And because StandardOutput is a\n    # property of the unit, every line after that point stopped reaching the\n    # console — which is why the log ends at \"Agent present:\" with no\n    # \"Install complete\" and no reboot message.\n    #\n    # The stamp alone is enough. The unit carries\n    # ConditionPathExists=!/var/lib/infoscreen/firstrun.done, so once that file\n    # exists systemd skips the unit on every future boot and reports it as\n    # skipped, not failed. Deleting the files is cosmetic, so it is deferred to\n    # a boot where nothing is running out of them.\n    mkdir -p \"$(dirname \"$STAMP\")\" 2>/dev/null || true\n    date -u '+%Y-%m-%dT%H:%M:%SZ' > \"$STAMP\" 2>/dev/null || true\n\n    # The boot-partition trigger is not ours to be running from, so it is safe\n    # to remove now — and it is the one that matters, because it is what starts\n    # the whole chain on the next boot.\n    rm -f \"$BOOTDIR/firstrun-infoscreen.sh\" \"$BOOTDIR/infoscreen-provision.env\" \\\n          \"$BOOTDIR/infoscreen-stage0.sh\" 2>/dev/null || true\n\n    # The unit files are deliberately left in place. ConditionPathExists=!\n    # on the stamp makes the unit inert: systemd skips it on every future boot\n    # and logs \"Condition check resulted in ... being skipped\", which is not an\n    # error and shows no red line. Two kilobytes of dormant unit is a better\n    # trade than a cleanup path that only runs under conditions that no longer\n    # occur after a successful install — a path that never runs still looks\n    # like cleanup is happening.\n    sync\n    return 0\n}\n\n# ── Is the network actually usable? ───────────────────────────────────────\n#\n# The old test was `ping 8.8.8.8 || ping 1.1.1.1`. On a municipal network\n# outbound ICMP to public resolvers is routinely dropped at the firewall, so\n# a Pi with a perfectly good address, a default route and full access to the\n# InfoScreen server reported \"No network after 5 minutes\" and the unit failed.\n#\n# What matters is not whether Google answers pings — it is whether this Pi can\n# reach the things it needs. Test those, in order of relevance, and accept any\n# one of them.\ninfoscreen_online() {\n    # No default route means there is genuinely nothing to test yet.\n    ip route show default 2>/dev/null | grep -q default || return 1\n\n    # 1. The InfoScreen server itself. This is the only thing that has to work.\n    if [ -n \"${INFOSCREEN_URL:-}\" ]; then\n        curl -fsS -m 8 -o /dev/null \"${INFOSCREEN_URL%/}/api/health\" 2>/dev/null && return 0\n        curl -fsS -m 8 -o /dev/null \"$INFOSCREEN_URL\" 2>/dev/null && return 0\n    fi\n\n    # 2. The package mirrors — needed for the install itself.\n    curl -fsS -m 8 -o /dev/null http://deb.debian.org/ 2>/dev/null && return 0\n    curl -fsS -m 8 -o /dev/null http://archive.raspberrypi.com/ 2>/dev/null && return 0\n\n    # 3. Plain DNS resolution: proves resolver + routing without needing ICMP.\n    getent hosts deb.debian.org  >/dev/null 2>&1 && return 0\n    getent hosts archive.debian.org >/dev/null 2>&1 && return 0\n\n    # 4. The local gateway. A filtered network still answers its own gateway.\n    _gw=$(ip route show default 2>/dev/null | awk '/default/ {print $3; exit}')\n    [ -n \"$_gw\" ] && ping -c1 -W3 \"$_gw\" >/dev/null 2>&1 && return 0\n\n    # 5. Finally, the old public-ICMP test, for networks where it does work.\n    ping -c1 -W3 8.8.8.8 >/dev/null 2>&1 && return 0\n    ping -c1 -W3 1.1.1.1 >/dev/null 2>&1 && return 0\n\n    return 1\n}\n\n# Pick up INFOSCREEN_URL if the SD card was prepared with one, so the check above\n# can test the server that actually matters.\nfor _envf in \"$BOOTDIR/infoscreen-provision.env\" /etc/infoscreen.env; do\n    if [ -f \"$_envf\" ]; then\n        INFOSCREEN_URL=$(grep -m1 '^INFOSCREEN_URL=' \"$_envf\" 2>/dev/null | cut -d= -f2- | tr -d '\"'\"'\"'')\n        [ -n \"$INFOSCREEN_URL\" ] && break\n    fi\ndone\nexport INFOSCREEN_URL=\"${INFOSCREEN_URL:-}\"\n\n# ── Find the package zip (local — no network needed yet) ──────────\n# The card writer names the package after the host: ull-infoskjerm-pi-<name>.zip.\n# The packaged/manual path uses infoscreen-pi-*.zip. This script is now the single\n# implementation behind both, so it has to accept either — looking for only one\n# of them is an instant \"no package found\" on every card written by the other\n# path, which is precisely the kind of contract mismatch that duplication hides.\nfind_package_zip() {\n    for _m in /boot/firmware /boot /var/lib/infoscreen ~kiosk ~pi ~; do\n        [ -d \"$_m\" ] || continue\n        for _pat in \"$_m\"/ull-infoskjerm-pi-*.zip \"$_m\"/infoscreen-pi-*.zip \"$_m\"/ull-infoskjerm-pi-agent.zip; do\n            [ -f \"$_pat\" ] && { printf '%s' \"$_pat\"; return 0; }\n        done\n    done\n    return 1\n}\nZIP=$(find_package_zip || true)\n\n# ── Extract early so we can pick up tui.sh for the nice UI ─────────\nSETUP=/tmp/infoscreen-setup\nif [ -n \"$ZIP\" ]; then\n    mkdir -p \"$SETUP\"\n    unzip -o \"$ZIP\" -d \"$SETUP\" >/dev/null 2>&1 || unzip -o \"$ZIP\" -d \"$SETUP\" || true\nfi\n\n# Locate tui.sh inside the extracted package.\nTUILIB=\"\"\nfor d in \"$SETUP\" \"$SETUP/kiosk\" \"$SETUP/scripts/kiosk\"; do\n    [ -f \"$d/tui.sh\" ] && TUILIB=\"$d\" && break\ndone\n\nINFOSCREEN_VERSION=\"${INFOSCREEN_VERSION:-4.4.1}\"\n\n# ══════════════════════════════════════════════════════════════════\n# Path A — the package has tui.sh: render the first boot in the TUI.\n# ══════════════════════════════════════════════════════════════════\nif [ -n \"$TUILIB\" ]; then\n    # Render onto the screen even when started by systemd (no controlling tty).\n    export TUI_TTY=\"${TUI_TTY:-/dev/tty1}\"\n    export TUI_LOG=\"$LOG\"\n\n    # getty owns tty1 and redraws /etc/issue and a login prompt whenever\n    # anything else writes there. The result is the TUI and \"raspberrypi login:\"\n    # scribbling over each other — the unreadable console in the v3.9.3 photos.\n    # Stop getty for the duration and put it back afterwards.\n    TTY_UNIT=\"\"\n    case \"$TUI_TTY\" in\n      /dev/tty[0-9]*)\n        TTY_UNIT=\"getty@$(basename \"$TUI_TTY\").service\"\n        if systemctl is-active --quiet \"$TTY_UNIT\" 2>/dev/null; then\n            systemctl stop \"$TTY_UNIT\" >/dev/null 2>&1 || TTY_UNIT=\"\"\n        else\n            TTY_UNIT=\"\"\n        fi\n        ;;\n    esac\n    restore_tty() { [ -n \"$TTY_UNIT\" ] && systemctl start \"$TTY_UNIT\" >/dev/null 2>&1 || true; }\n    # shellcheck disable=SC1090\n    . \"$TUILIB/tui.sh\"\n\n    # A failure here must not take the console with it. Show the error, put\n    # getty back so somebody can log in and read the log, then exit non-zero so\n    # systemd retries on a schedule instead of the Pi silently doing nothing.\n    ps_die() {\n        tui_stage_fail \"${CURSTAGE:-1}\"\n        tui_fatal \"$1\"\n        echo \"infoscreen-firstrun: $1\" >> \"$LOG\" 2>/dev/null || true\n        # Dump before parking, so the card carries the whole story out.\n        for _d in /usr/local/sbin/infoscreen-collect-diagnostics.sh \\\n                  \"$BOOTDIR/infoscreen-collect-diagnostics.sh\"; do\n            [ -f \"$_d\" ] && { PS_DIAG_QUIET=1 bash \"$_d\" 2>/dev/null || true; break; }\n        done\n        sleep 20\n        tui_end 2>/dev/null || true\n        restore_tty\n        exit 1\n    }\n\n    tui_begin \"Raspberry Pi Setup\" \"$INFOSCREEN_VERSION\"\n    tui_stages \"Waiting for the network\nSyncing the clock\nInstalling InfoScreen\nStarting the display\"\n    tui_headline \"$(hostname 2>/dev/null)  ·  $(uname -m)  ·  first boot\"\n\n    [ -z \"$ZIP\" ] && ps_die \"No package zip found on the boot partition.\\n     Looked for ull-infoskjerm-pi-*.zip and infoscreen-pi-*.zip.\"\n\n    # ── Stage 1: network ──────────────────────────────────────────\n    CURSTAGE=1; tui_stage_start 1 \"Bringing up the network\"\n    tui_status \"Waiting for NetworkManager\"\n    for i in $(seq 1 30); do\n        systemctl is-active --quiet NetworkManager 2>/dev/null && { tui_log \"NetworkManager active (${i})\"; break; }\n        sleep 2\n    done\n    CONNECTED=0\n    for i in $(seq 1 60); do\n        if infoscreen_online; then\n            CONNECTED=1\n            tui_log \"network up: $(ip -4 addr show scope global 2>/dev/null | sed -n 's/.*inet \\([0-9.]*\\).*/\\1/p' | head -1)\"\n            break\n        fi\n        [ $((i % 4)) = 0 ] && tui_log \"waiting for connectivity... ${i}/60\"\n        tui_pct $(( 5 + i )); sleep 5\n    done\n    if [ $CONNECTED -eq 0 ]; then\n        # Say what was actually tried, so this is diagnosable from the screen\n        # instead of being a bare \"no network\" on a Pi that clearly has an IP.\n        tui_log \"--- network diagnosis ---\"\n        tui_log \"address : $(ip -4 addr show scope global 2>/dev/null | sed -n 's/.*inet \\([0-9.]*\\/[0-9]*\\).*/\\1/p' | tr '\\n' ' ')\"\n        tui_log \"route   : $(ip route show default 2>/dev/null | head -1)\"\n        tui_log \"dns     : $(awk '/^nameserver/ {printf \"%s \", $2}' /etc/resolv.conf 2>/dev/null)\"\n        tui_log \"server  : ${INFOSCREEN_URL:-<not configured>}\"\n        ps_die \"No usable network after 5 minutes.\n     Tried the InfoScreen server, the Debian mirrors, DNS, and the local gateway.\n     Connect ethernet or configure WiFi, then reboot.\"\n    fi\n    tui_pct 30; tui_stage_done 1\n\n    # ── Stage 2: clock ────────────────────────────────────────────\n    CURSTAGE=2; tui_stage_start 2 \"Syncing the clock (the Pi has no battery clock)\"\n    timedatectl set-ntp true 2>/dev/null || true\n    for i in $(seq 1 30); do\n        if timedatectl show -p NTPSynchronized --value 2>/dev/null | grep -q yes; then\n            tui_log \"clock synced: $(date)\"; break\n        fi\n        if [ $i -eq 15 ]; then\n            HTTP_DATE=$(curl -sI http://deb.debian.org 2>/dev/null | grep -i \"^date:\" | cut -d' ' -f2-)\n            [ -n \"$HTTP_DATE\" ] && date -s \"$HTTP_DATE\" 2>/dev/null && { tui_log \"clock set from HTTP: $(date)\"; break; }\n        fi\n        sleep 2\n    done\n    tui_pct 40; tui_stage_done 2\n\n    # ── Stage 3: install ──────────────────────────────────────────\n    CURSTAGE=3; tui_stage_start 3 \"Installing InfoScreen\"\n    for i in $(seq 1 12); do\n        flock -n /var/lib/dpkg/lock-frontend true 2>/dev/null && break\n        tui_log \"apt busy... ${i}/12\"; sleep 5\n    done\n    cd \"$SETUP\"\n    chmod +x install-agent.sh 2>/dev/null || true\n    # Pipe the installer's output line-by-line into the TUI log pane, so its\n    # progress scrolls in the status screen instead of raw text on the console.\n    bash install-agent.sh 2>&1 | while IFS= read -r line; do\n        case \"$line\" in \"\"|\"===\"*) : ;; *) tui_log \"$line\" ;; esac\n    done\n    RC=${PIPESTATUS[0]}\n    [ \"$RC\" = 0 ] || ps_die \"The installer exited with code $RC. See $LOG for the full output.\"\n    tui_pct 92; tui_stage_done 3\n\n    # ── Stage 4: hand over ────────────────────────────────────────\n    CURSTAGE=4; tui_stage_start 4 \"Starting the InfoScreen agent\"\n    systemctl start infoscreen-agent 2>/dev/null || tui_log \"agent will start on the next boot\"\n    tui_log \"this screen will appear in System -> Provisioning once approved\"\n    tui_pct 100; tui_stage_done 4\n\n    # Verify before declaring success. Reporting \"complete\" and rebooting into\n    # a Pi with no agent looks identical to a working one until someone notices\n    # the screen never appears in the portal.\n    if [ ! -f /opt/infoscreen-agent/infoscreen-agent.py ]; then\n        ps_die \"The installer finished but /opt/infoscreen-agent/infoscreen-agent.py is missing.\n     Nothing has been disarmed, so this will be retried on the next boot.\"\n    fi\n    tui_log \"agent present: $(grep -m1 AGENT_VERSION /opt/infoscreen-agent/infoscreen-agent.py 2>/dev/null || echo unknown)\"\n\n    # Turn the first-boot installer off. Without this the unit stays enabled,\n    # the script stays on the boot partition, and every subsequent boot either\n    # reinstalls and reboots (a loop) or fails on the console.\n    infoscreen_disarm\n    tui_log \"first-boot installer disarmed — this will not run again\"\n\n    tui_status \"Install complete — rebooting\"\n    sleep 4\n    tui_end 2>/dev/null || true\n    restore_tty\n    # See the note in the Path B reboot: a plain reboot from inside a oneshot\n    # makes systemd stop this unit mid-run and record the job as failed.\n    systemctl --no-block reboot 2>/dev/null || reboot &\n    exit 0\nfi\n\n# ══════════════════════════════════════════════════════════════════\n# Path B — no tui.sh in the package: original plain-text install.\n# ══════════════════════════════════════════════════════════════════\nexec > >(tee -a \"$LOG\") 2>&1\necho \"=== InfoScreen First-Boot Install $(date) ===\"\n\necho \"Waiting for NetworkManager...\"\nfor i in $(seq 1 30); do\n    systemctl is-active --quiet NetworkManager 2>/dev/null && { echo \"NetworkManager active after ${i} attempts\"; break; }\n    sleep 2\ndone\n\necho \"Waiting for network connectivity...\"\nCONNECTED=0\nfor i in $(seq 1 60); do\n    if infoscreen_online; then\n        echo \"Network up after ~$((i*5))s\"; CONNECTED=1; break\n    fi\n    echo \"  No network yet ($i/60)...\"; sleep 5\ndone\nif [ $CONNECTED -eq 0 ]; then\n    echo \"ERROR: No usable network after 5 minutes.\"\n    echo \"  address : $(ip -4 addr show scope global 2>/dev/null | sed -n 's/.*inet \\([0-9.]*\\/[0-9]*\\).*/\\1/p' | tr '\\n' ' ')\"\n    echo \"  route   : $(ip route show default 2>/dev/null | head -1)\"\n    echo \"  dns     : $(awk '/^nameserver/ {printf \"%s \", $2}' /etc/resolv.conf 2>/dev/null)\"\n    echo \"  server  : ${INFOSCREEN_URL:-<not configured>}\"\n    exit 1\nfi\n\necho \"Syncing clock via NTP...\"\ntimedatectl set-ntp true 2>/dev/null || true\nfor i in $(seq 1 30); do\n    timedatectl show -p NTPSynchronized --value 2>/dev/null | grep -q yes && { echo \"Clock synced: $(date)\"; break; }\n    if [ $i -eq 15 ]; then\n        HTTP_DATE=$(curl -sI http://deb.debian.org 2>/dev/null | grep -i \"^date:\" | cut -d' ' -f2-)\n        [ -n \"$HTTP_DATE\" ] && date -s \"$HTTP_DATE\" 2>/dev/null && { echo \"Clock set from HTTP: $(date)\"; break; }\n    fi\n    sleep 2\ndone\n\n[ -z \"$ZIP\" ] && ZIP=$(find_package_zip || true)\nif [ -z \"$ZIP\" ]; then\n    echo \"ERROR: no package zip found. Looked for ull-infoskjerm-pi-*.zip and\"\n    echo \"       infoscreen-pi-*.zip in /boot/firmware, /boot and /var/lib/infoscreen.\"\n    echo \"       Contents of /boot/firmware:\"\n    ls -la /boot/firmware 2>/dev/null | head -20\n    exit 1\nfi\necho \"Found package: $ZIP\"\n\necho \"Waiting for apt lock...\"\nfor i in $(seq 1 12); do\n    flock -n /var/lib/dpkg/lock-frontend true 2>/dev/null && break\n    echo \"  apt busy ($i/12)...\"; sleep 5\ndone\n\necho \"Installing from $SETUP ...\"\ncd \"$SETUP\"\nchmod +x install-agent.sh\nbash install-agent.sh\nsystemctl start infoscreen-agent 2>/dev/null || true\n\nsleep 3\nif [ ! -f /opt/infoscreen-agent/infoscreen-agent.py ]; then\n    echo \"ERROR: agent was not installed to /opt/infoscreen-agent\"\n    exit 1\nfi\necho \"Agent present: $(grep -m1 AGENT_VERSION /opt/infoscreen-agent/infoscreen-agent.py || echo unknown)\"\n\n# Turn the first-boot installer off so it does not run again on every boot.\ninfoscreen_disarm\necho \"First-boot installer disarmed.\"\n\necho \"\"\necho \"=== Install complete! ===\"\necho \"Rebooting in 5 seconds...\"\nsleep 5\n# --no-block, then exit 0 immediately. A plain `reboot` from inside a oneshot\n# starts the shutdown while this unit is still running, so systemd stops it\n# mid-flight and records the job as failed — a red line on a clean install.\n# Returning 0 first lets the unit finish properly, and the reboot follows.\nsystemctl --no-block reboot 2>/dev/null || reboot &\nexit 0\n",
  "infoscreen-stage0.sh": "#!/bin/bash\n# InfoScreen first-boot STAGE 0 — runs from cmdline.txt via systemd.run=\n#\n# This script does exactly one job: get the real installer onto the rootfs as a\n# normal systemd unit, then reboot. It does NOT touch the network, and it must\n# never need to.\n#\n# ── Why this exists ────────────────────────────────────────────────────────\n#\n# systemd.run= makes kernel-command-line.target the default target for that\n# boot. That is a minimal target: NetworkManager is WantedBy=multi-user.target\n# and is therefore never started, there is no getty, and normal service\n# ordering does not happen. Everything that \"just works\" on a normal boot has\n# to be hand-rolled.\n#\n# The old design tried to perform the entire install in there: start the\n# network stack by hand, wait for DHCP, sync the clock, apt-get, unzip, install\n# the agent. Every one of those is a way to fail in an environment where\n# nothing is set up, and the observed failures were exactly that —\n#\n#   * 90 seconds of \"No network yet (N/18)\" and a reboot, because NM had been\n#     started 1.3 seconds earlier and DHCP had not finished\n#   * the provisioning config being read AFTER the network wait, so the WiFi\n#     profile did not exist yet and $SERVER was empty during the check\n#   * a retry unit whose ExecStart had been copied with `|| true` and silently\n#     was not there, giving [FAILED] on every boot forever\n#\n# None of those are network problems. They are all \"the minimal target is the\n# wrong place to do this\" problems.\n#\n# So stage 0 is deliberately tiny and offline. The real install happens on the\n# next boot, in multi-user.target, where NetworkManager, DNS, resolv.conf and\n# cloud-init have all run normally and none of it needs hand-rolling.\n\nset -u\n\nBOOTDIR=/boot/firmware\n[ -d \"$BOOTDIR\" ] || BOOTDIR=/boot\nCMDLINE=\"$BOOTDIR/cmdline.txt\"\nSTATEDIR=/var/lib/infoscreen\nLOG=/var/log/infoscreen-install.log\nBOOTLOG=\"$BOOTDIR/infoscreen-install.log\"\n\nmkdir -p \"$STATEDIR\" 2>/dev/null || true\n\n# ── Pin the cloud-init datasource ──────────────────────────────────────────\n# The Raspberry Pi OS images used here ship cloud-init with no datasource to\n# find. On the SECOND boot (the real install, in multi-user.target) its\n# metadata probe runs to timeout — measured at 436 and 446 seconds on two\n# images, see LES-MEG-v3.9.5 \"Anbefaling utenfor koden\". For those seven\n# minutes the Pi shows nothing and does nothing, which is indistinguishable\n# from a dead board, and it lengthened every normal boot besides.\n#\n# v3.9.5 only recommended the fix in prose; it was never in the code, so every\n# freshly written card still hung. Stage 0 is the one place on the device that\n# rewrites cmdline.txt right before the boot where the probe runs, so pin the\n# datasource to NoCloud here. Idempotent: only appended if not already present,\n# and stage 0's own trigger cleanup ('sed s| systemd.run||') leaves it intact.\nensure_nocloud() {\n    [ -f \"$CMDLINE\" ] || return 0\n    grep -qw 'ds=nocloud' \"$CMDLINE\" 2>/dev/null && return 0\n    sed -i 's/$/ ds=nocloud/' \"$CMDLINE\"\n    echo \"cloud-init datasource pinned: ds=nocloud added to $(basename \"$CMDLINE\")\"\n}\n\n# ── Persistent logs ────────────────────────────────────────────────────────\n# journald on these images keeps logs only in RAM, so everything is wiped on\n# reboot. That is why the first-boot install failure on ITDemo2 was\n# undiagnosable: the install runs on the SECOND boot, and by the time anyone\n# looked, that boot's journal was already gone (\"no persistent journal was\n# found\"). Turn on persistent storage here, on the FIRST boot, so the very next\n# boot — the one that installs — records to disk and survives a reboot.\n# Idempotent. journald picks /var/log/journal up automatically at its start.\nensure_persistent_journal() {\n    mkdir -p /var/log/journal 2>/dev/null || true\n    _jc=/etc/systemd/journald.conf\n    [ -f \"$_jc\" ] || return 0\n    if grep -qiE '^[[:space:]]*#?[[:space:]]*Storage=' \"$_jc\"; then\n        sed -i -E 's/^[[:space:]]*#?[[:space:]]*Storage=.*/Storage=persistent/I' \"$_jc\"\n    else\n        printf '\\n[Journal]\\nStorage=persistent\\n' >> \"$_jc\"\n    fi\n    echo \"persistent journald enabled (/var/log/journal); next boot's logs survive a reboot\"\n}\n\n# Log to the boot partition too: it is FAT, so it can be read by putting the\n# card in any PC. That is the only way to see what happened when the Pi will\n# not come up at all.\nexec > >(tee -a \"$LOG\" \"$BOOTLOG\") 2>&1\necho \"=== InfoScreen first-boot stage 0 — $(date -u '+%Y-%m-%dT%H:%M:%SZ') ===\"\n\n# ── Already installed? ─────────────────────────────────────────────────────\n# Check the outcome, not the paperwork. However the agent got onto this Pi, if\n# it is there and enabled then the first boot is over and nothing here should\n# run again.\nif [ -f /opt/infoscreen-agent/infoscreen-agent.py ] \\\n   && systemctl is-enabled --quiet infoscreen-agent.service 2>/dev/null; then\n    echo \"InfoScreen agent already installed and enabled — nothing to stage.\"\n    date -u '+%Y-%m-%dT%H:%M:%SZ' > \"$STATEDIR/firstrun.done\" 2>/dev/null || true\n    sed -i 's| systemd\\.run[^ ]*||g' \"$CMDLINE\" 2>/dev/null || true\n    ensure_nocloud\n    rm -f \"$BOOTDIR/firstrun-infoscreen.sh\" \"$BOOTDIR/infoscreen-stage0.sh\" 2>/dev/null || true\n    sync\n    exit 0\nfi\n\nif [ -f \"$STATEDIR/firstrun.done\" ]; then\n    echo \"firstrun.done present ($(cat \"$STATEDIR/firstrun.done\" 2>/dev/null)) — nothing to stage.\"\n    sed -i 's| systemd\\.run[^ ]*||g' \"$CMDLINE\" 2>/dev/null || true\n    ensure_nocloud\n    sync\n    exit 0\nfi\n\n\n# ── Dump diagnostics on any failure ────────────────────────────────────────\n# A photograph of a console shows forty lines. The failure is usually explained\n# by something that scrolled past minutes earlier. Write the whole picture to\n# the FAT boot partition, where it can be read by putting the card in any PC.\nps_dump() {\n    for d in \"$BOOTDIR/infoscreen-collect-diagnostics.sh\" \\\n             /usr/local/sbin/infoscreen-collect-diagnostics.sh; do\n        [ -f \"$d\" ] || continue\n        echo \"Collecting diagnostics...\"\n        PS_DIAG_QUIET=1 bash \"$d\" 2>/dev/null || true\n        return 0\n    done\n    echo \"(infoscreen-collect-diagnostics.sh not found — no dump written)\"\n}\nps_fail() { echo \"ERROR: $1\"; ps_dump; exit 1; }\n\n# ── Find the real installer ────────────────────────────────────────────────\n# It ships on the boot partition next to this script.\nINSTALLER=\"\"\nfor c in \"$BOOTDIR/firstrun-infoscreen.sh\" /boot/firstrun-infoscreen.sh; do\n    if [ -f \"$c\" ] && head -1 \"$c\" 2>/dev/null | grep -q '^#!'; then\n        INSTALLER=\"$c\"; break\n    fi\ndone\n\nif [ -z \"$INSTALLER\" ]; then\n    echo \"ERROR: firstrun-infoscreen.sh not found on the boot partition.\"\n    echo \"       Looked in: $BOOTDIR and /boot\"\n    echo \"       Leaving the boot trigger in place so this can be retried once\"\n    echo \"       the file is copied onto the card.\"\n    ps_dump\n    exit 1\nfi\n\n# ── Stage it onto the rootfs ───────────────────────────────────────────────\necho \"Staging $INSTALLER -> /usr/local/sbin/infoscreen-firstrun.sh\"\nmkdir -p /usr/local/sbin\nif ! cp \"$INSTALLER\" /usr/local/sbin/infoscreen-firstrun.sh; then\n    echo \"ERROR: could not copy the installer onto the rootfs.\"\n    echo \"       Not removing the boot trigger — this will be retried next boot.\"\n    ps_dump\n    exit 1\nfi\nchmod 0755 /usr/local/sbin/infoscreen-firstrun.sh\n\n# Verify rather than assume. A unit whose ExecStart is missing fails with\n# status 203/EXEC instantly, on every boot, and writes nothing to the\n# installer's own log because the installer never runs. That exact failure\n# shipped once because the copy above was written as `cp ... || true`.\nif [ ! -s /usr/local/sbin/infoscreen-firstrun.sh ]; then\n    echo \"ERROR: the staged installer is empty. Refusing to arm a unit that\"\n    echo \"       cannot run. The boot trigger stays in place.\"\n    rm -f /usr/local/sbin/infoscreen-firstrun.sh\n    ps_dump\n    exit 1\nfi\nif ! bash -n /usr/local/sbin/infoscreen-firstrun.sh; then\n    echo \"ERROR: the staged installer is not valid bash. Refusing to arm it.\"\n    rm -f /usr/local/sbin/infoscreen-firstrun.sh\n    ps_dump\n    exit 1\nfi\necho \"Installer staged and syntax-checked.\"\n\n# Stage the diagnostics collector too, so stage 1 can dump even after the boot\n# partition has been tidied up.\nfor d in \"$BOOTDIR/infoscreen-collect-diagnostics.sh\" /boot/infoscreen-collect-diagnostics.sh; do\n    [ -f \"$d\" ] || continue\n    cp \"$d\" /usr/local/sbin/infoscreen-collect-diagnostics.sh 2>/dev/null || true\n    chmod 0755 /usr/local/sbin/infoscreen-collect-diagnostics.sh 2>/dev/null || true\n    echo \"Diagnostics collector staged.\"\n    break\ndone\n\n# Carry the provisioning config across to the rootfs so stage 1 does not depend\n# on the boot partition still being mounted or still holding it.\nfor f in infoscreen-provision.env; do\n    [ -f \"$BOOTDIR/$f\" ] || continue\n    cp \"$BOOTDIR/$f\" \"$STATEDIR/$f\" 2>/dev/null || true\n    chmod 0600 \"$STATEDIR/$f\" 2>/dev/null || true\n    echo \"Copied $f to $STATEDIR\"\ndone\n\n# ── Arm the real unit ──────────────────────────────────────────────────────\ncat > /etc/systemd/system/infoscreen-firstrun.service << 'UNIT'\n[Unit]\nDescription=InfoScreen First-Boot Installer\n# Ordered behind the things the install actually needs. In multi-user.target\n# these all exist and work; in the minimal systemd.run target none of them do,\n# which is the entire reason the install no longer happens there.\n#\n# NOT ordered After=cloud-init.target. That ordering left the install unit\n# \"inactive (dead)\" with no queued job and no log on a Debian 13 / RPi image\n# where `cloud-init status` stayed \"running\" long after its stage services had\n# exited — the start job was stalled or dropped and the first boot never\n# installed anything (ITDemo2). The installer script waits for NetworkManager\n# and for real connectivity, and syncs its own clock over NTP, so it does not\n# need cloud-init to have finished first. Removing the dependency removes the\n# failure class.\nAfter=network-online.target NetworkManager-wait-online.service\nWants=network-online.target NetworkManager-wait-online.service\nConditionPathExists=/usr/local/sbin/infoscreen-firstrun.sh\nConditionPathExists=!/var/lib/infoscreen/firstrun.done\nStartLimitIntervalSec=3600\nStartLimitBurst=4\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\n# Through bash, so a lost exec bit is not a silent 203/EXEC.\nExecStart=/bin/bash /usr/local/sbin/infoscreen-firstrun.sh\n# On the console as well as the journal. A retry running invisibly behind a\n# login prompt is indistinguishable from a Pi that has given up.\nStandardOutput=journal+console\nStandardError=journal+console\nTimeoutStartSec=1800\nRestart=on-failure\nRestartSec=90\n\n[Install]\nWantedBy=multi-user.target\nUNIT\n\nmkdir -p /etc/systemd/system/multi-user.target.wants\nln -sf /etc/systemd/system/infoscreen-firstrun.service \\\n       /etc/systemd/system/multi-user.target.wants/infoscreen-firstrun.service\n\n# NetworkManager-wait-online is what makes network-online.target mean anything.\n# Without it the target is reached immediately and stage 1 starts before DHCP.\nif [ -f /usr/lib/systemd/system/NetworkManager-wait-online.service ]; then\n    mkdir -p /etc/systemd/system/NetworkManager.service.wants\n    ln -sf /usr/lib/systemd/system/NetworkManager-wait-online.service \\\n           /etc/systemd/system/NetworkManager.service.wants/NetworkManager-wait-online.service\nfi\n\nsystemctl daemon-reload 2>/dev/null || true\necho \"infoscreen-firstrun.service armed for the next boot.\"\n\n# ── Disarm the boot trigger ────────────────────────────────────────────────\n# Only now, once the replacement is in place and verified. Doing this first\n# risks a card that has neither the trigger nor the unit.\nif [ -f \"$CMDLINE\" ]; then\n    sed -i 's| systemd\\.run[^ ]*||g' \"$CMDLINE\"\n    # Pin the datasource on the very command line the next (install) boot reads,\n    # so cloud-init's metadata probe cannot turn that boot into a silent 7-minute\n    # stall that looks like a hung Pi.\n    ensure_nocloud\n    sync\n    echo \"Boot trigger removed from $CMDLINE — the next boot is a normal one.\"\nfi\n\n# Make the install boot's logs survive, so if it fails it is diagnosable\n# instead of a black box (the ITDemo2 lesson).\nensure_persistent_journal\n\ndate -u '+%Y-%m-%dT%H:%M:%SZ' > \"$STATEDIR/stage0.done\" 2>/dev/null || true\nsync\n\necho \"\"\necho \"=== Stage 0 complete. Rebooting into a normal system to install. ===\"\necho \"    Nothing has been installed yet; that happens on the next boot,\"\necho \"    where NetworkManager and DNS are running normally.\"\nsleep 5\nreboot\nexit 0\n",
  "infoscreen-collect-diagnostics.sh": "#!/bin/bash\n# InfoScreen diagnostics collector (Raspberry Pi).\n#\n# Writes everything needed to diagnose a failed first boot to a text file on the\n# FAT boot partition — and onto a USB stick if one is plugged in. Both are\n# readable by putting the card or the stick into any Windows machine.\n#\n# Photographing a console has been the bottleneck in every round of this so far.\n# A photo shows forty lines; the failure is usually explained by something that\n# scrolled past four minutes earlier.\n#\n# Runs three ways:\n#   * automatically, when stage 0 fails\n#   * automatically, when the first-boot install fails\n#   * by hand:  sudo bash /boot/firmware/infoscreen-collect-diagnostics.sh\n#\n# The output is deliberately the same shape as the laptop collector, so the same\n# eyes can read both.\n\nBOOTDIR=/boot/firmware\n[ -d \"$BOOTDIR\" ] || BOOTDIR=/boot\n\nSTAMP=$(date -u '+%Y%m%d-%H%M%S' 2>/dev/null || echo unknown)\nHOST=$(hostname 2>/dev/null || echo unknown)\nOUT=\"/tmp/infoscreen-diag-${HOST}-${STAMP}.txt\"\n\n: > \"$OUT\" 2>/dev/null || OUT=/tmp/infoscreen-diag.txt\n\nsec()    { printf '\\n===== %s =====\\n' \"$1\" >> \"$OUT\"; }\nrun()    { printf '\\n--- $ %s\\n' \"$*\" >> \"$OUT\"; \"$@\" >> \"$OUT\" 2>&1 || printf '(command failed, exit %d)\\n' $? >> \"$OUT\"; }\ncat_if() { printf '\\n--- %s\\n' \"$1\" >> \"$OUT\"\n           if [ -f \"$1\" ]; then cat \"$1\" >> \"$OUT\" 2>&1; else echo \"(missing)\" >> \"$OUT\"; fi; }\n\n# ── Identity ───────────────────────────────────────────────────────────────\nsec \"INFOSCREEN PI DIAGNOSTICS\"\n{\n  echo \"collected : $(date -u '+%Y-%m-%dT%H:%M:%SZ' 2>/dev/null)\"\n  echo \"hostname  : $HOST\"\n  echo \"uptime    : $(cut -d' ' -f1 /proc/uptime 2>/dev/null)s\"\n  echo \"model     : $(tr -d '\\0' < /proc/device-tree/model 2>/dev/null)\"\n  echo \"os        : $(. /etc/os-release 2>/dev/null; echo \"$PRETTY_NAME\")\"\n  echo \"kernel    : $(uname -a)\"\n  echo \"boot dir  : $BOOTDIR\"\n} >> \"$OUT\" 2>&1\n\n# ── The question that matters first: is this thing installed or not? ───────\nsec \"INSTALL STATE\"\n{\n  for f in /opt/infoscreen-agent/infoscreen-agent.py \\\n           /usr/local/sbin/infoscreen-firstrun.sh \\\n           /etc/systemd/system/infoscreen-firstrun.service \\\n           /var/lib/infoscreen/firstrun.done \\\n           /var/lib/infoscreen/stage0.done \\\n           /var/lib/infoscreen/firstrun-attempts \\\n           \"$BOOTDIR/firstrun-infoscreen.sh\" \\\n           \"$BOOTDIR/infoscreen-stage0.sh\" \\\n           /etc/infoscreen.token; do\n    if [ -e \"$f\" ]; then echo \"PRESENT: $f\"; else echo \"MISSING: $f\"; fi\n  done\n  echo\n  echo \"agent version : $(grep -m1 AGENT_VERSION /opt/infoscreen-agent/infoscreen-agent.py 2>/dev/null || echo '(no agent)')\"\n  echo \"firstrun.done : $(cat /var/lib/infoscreen/firstrun.done 2>/dev/null || echo '(not set)')\"\n  echo \"attempts      : $(cat /var/lib/infoscreen/firstrun-attempts 2>/dev/null || echo 0)\"\n  echo\n  echo \"package zips on the boot partition:\"\n  ls -la \"$BOOTDIR\"/*.zip 2>/dev/null || echo \"  (none — this is why 'no package found' happens)\"\n} >> \"$OUT\" 2>&1\n\n# ── Services ───────────────────────────────────────────────────────────────\nsec \"SYSTEMD UNITS\"\nfor u in infoscreen-firstrun.service infoscreen-agent.service NetworkManager.service \\\n         NetworkManager-wait-online.service cloud-init.target ssh.service; do\n  printf '\\n--- %s\\n' \"$u\" >> \"$OUT\"\n  systemctl status \"$u\" --no-pager -l >> \"$OUT\" 2>&1 || true\ndone\nrun systemctl --failed --no-pager\nrun systemctl list-units --state=failed --no-pager\n\nsec \"FIRSTRUN JOURNAL (this boot)\"\njournalctl -u infoscreen-firstrun.service -b --no-pager >> \"$OUT\" 2>&1 || echo \"(no journal)\" >> \"$OUT\"\nsec \"FIRSTRUN JOURNAL (previous boot)\"\njournalctl -u infoscreen-firstrun.service -b -1 --no-pager >> \"$OUT\" 2>&1 || echo \"(no previous boot)\" >> \"$OUT\"\nsec \"AGENT JOURNAL\"\njournalctl -u infoscreen-agent.service -b --no-pager >> \"$OUT\" 2>&1 || echo \"(no journal)\" >> \"$OUT\"\n\n# ── Network: the single most common failure ────────────────────────────────\nsec \"NETWORK\"\nrun ip -4 -o addr show\nrun ip -6 -o addr show scope global\nrun ip route show\nrun ip -br link\nprintf '\\n--- carrier / operstate per interface\\n' >> \"$OUT\"\nfor n in /sys/class/net/*; do\n  i=$(basename \"$n\"); [ \"$i\" = lo ] && continue\n  printf '%-12s carrier=%s operstate=%s\\n' \"$i\" \\\n    \"$(cat \"$n/carrier\" 2>/dev/null || echo '?')\" \\\n    \"$(cat \"$n/operstate\" 2>/dev/null || echo '?')\" >> \"$OUT\"\ndone\ncat_if /etc/resolv.conf\nrun nmcli -t -f DEVICE,TYPE,STATE,CONNECTION device\nrun nmcli -t -f NAME,TYPE,AUTOCONNECT connection show\nprintf '\\n--- WiFi profiles present (contents NOT dumped)\\n' >> \"$OUT\"\nls -la /etc/NetworkManager/system-connections/ >> \"$OUT\" 2>&1 || echo \"(none)\" >> \"$OUT\"\n\nprintf '\\n--- reachability\\n' >> \"$OUT\"\nSERVER=\"\"\nfor c in /var/lib/infoscreen/infoscreen-provision.env \"$BOOTDIR/infoscreen-provision.env\" /etc/infoscreen.env; do\n  [ -f \"$c\" ] || continue\n  SERVER=$(grep -m1 -E '^(INFOSCREEN_URL|SERVER)=' \"$c\" 2>/dev/null | cut -d= -f2- | tr -d '\"'\"'\"'')\n  [ -n \"$SERVER\" ] && break\ndone\necho \"configured server: ${SERVER:-<none found>}\" >> \"$OUT\"\nif [ -n \"$SERVER\" ]; then\n  printf 'curl %s -> ' \"$SERVER\" >> \"$OUT\"\n  curl -fsS -m 8 -o /dev/null -w '%{http_code}\\n' \"$SERVER\" >> \"$OUT\" 2>&1 || echo \"FAILED\" >> \"$OUT\"\nfi\nfor h in deb.debian.org archive.raspberrypi.com; do\n  printf 'dns %s -> ' \"$h\" >> \"$OUT\"\n  getent hosts \"$h\" >> \"$OUT\" 2>&1 || echo \"FAILED\" >> \"$OUT\"\ndone\nGW=$(ip route show default 2>/dev/null | awk '/default/{print $3; exit}')\n[ -n \"$GW\" ] && run ping -c2 -W3 \"$GW\"\n\n# ── cloud-init: it has been adding ~7 minutes to every boot ────────────────\nsec \"CLOUD-INIT\"\nrun cloud-init status --long\nrun systemd-analyze blame\nprintf '\\n--- cloud-init boot stage timings\\n' >> \"$OUT\"\njournalctl -b --no-pager 2>/dev/null | grep -i \"boot stage\" >> \"$OUT\" 2>&1 || echo \"(none)\" >> \"$OUT\"\n\n# ── Logs ───────────────────────────────────────────────────────────────────\nsec \"XORG\"\ncat_if /var/log/Xorg.0.log\ncat_if /var/log/infoscreen-x.log\ncat_if /var/log/infoscreen-session.log\nprintf '\\n--- Xorg (EE) lines\\n' >> \"$OUT\"\ngrep \"^\\[.*(EE)\" /var/log/Xorg.0.log >> \"$OUT\" 2>&1 || echo \"(none)\" >> \"$OUT\"\nrun ls -l /dev/dri\nrun ls -l /dev/input\n\nsec \"DISPLAY PACKAGES\"\ncat_if /etc/infoscreen/display-packages\nrun ls -la /usr/lib/xorg/modules/drivers\nrun ls -la /usr/lib/xorg/modules/input\nrun ls -la /usr/lib/dri\n\nsec \"INFOSCREEN LOGS\"\nfor f in /var/log/infoscreen-install.log /var/log/infoskjerm-install.log \\\n         \"$BOOTDIR/infoscreen-install.log\" \"$BOOTDIR/infoskjerm-install.log\" \\\n         /var/log/infoscreen-agent.log; do\n  cat_if \"$f\"\ndone\n\nsec \"BOOT CONFIG\"\ncat_if \"$BOOTDIR/cmdline.txt\"\ncat_if /proc/cmdline\n\nsec \"STORAGE\"\nrun df -h\nrun lsblk -o NAME,SIZE,FSTYPE,MOUNTPOINT\n\nsec \"DMESG (tail)\"\ndmesg 2>/dev/null | tail -200 >> \"$OUT\" 2>&1 || echo \"(unavailable)\" >> \"$OUT\"\n\nsec \"BOOT JOURNAL (tail)\"\njournalctl -b --no-pager 2>/dev/null | tail -400 >> \"$OUT\" 2>&1 || echo \"(no journal)\" >> \"$OUT\"\n\n# ── Redact before this file leaves the machine ─────────────────────────────\n#\n# This report is meant to be carried out on an SD card or a stick and emailed.\n# It must not contain the root password, the WiFi PSK or the provisioning\n# secret. Auditing every log line that might one day print one is a losing\n# game, so redact the finished artifact instead — that survives future changes\n# to what gets logged.\n_K='(ROOT_)?PASSWORD|PASSWD|WIFI_PASS|PSK|PROVISION_SECRET|SECRET|TOKEN|API_?KEY|BEARER'\nsed -i -E \\\n  -e \"s/($_K)[[:space:]]*[=:][[:space:]]*\\\"[^\\\"]*\\\"/\\1=\\\"<redacted>\\\"/Ig\" \\\n  -e \"s/($_K)[[:space:]]*[=:][[:space:]]*'[^']*'/\\1='<redacted>'/Ig\" \\\n  -e \"s/($_K)[[:space:]]*:[[:space:]]*.*$/\\1: <redacted>/Ig\" \\\n  -e \"s/($_K)([\\\"' ]*=[\\\"' ]*)[^\\\"'[:space:]]+/\\1\\2<redacted>/Ig\" \\\n  -e \"s/(psk=)[^[:space:]]+/\\1<redacted>/Ig\" \\\n  -e \"s#(https?://)[^:/[:space:]]+:[^@[:space:]]+@#\\1<redacted>:<redacted>@#g\" \\\n  \"$OUT\" 2>/dev/null || true\nprintf '\\n===== REDACTION =====\\nPasswords, PSKs, tokens and provisioning secrets were replaced with\\n<redacted> before this file was written. Safe to share.\\n' >> \"$OUT\"\n\n# ── Drop it somewhere removable ────────────────────────────────────────────\nBASE=$(basename \"$OUT\")\nSAVED=\"\"\n\n# 1. The FAT boot partition. Always there, readable in any PC, survives a Pi\n#    that will not boot at all.\nif mkdir -p \"$BOOTDIR/infoscreen-logs\" 2>/dev/null && cp \"$OUT\" \"$BOOTDIR/infoscreen-logs/\" 2>/dev/null; then\n  sync\n  SAVED=\"$BOOTDIR/infoscreen-logs/$BASE\"\nfi\n\n# 2. Any USB stick that happens to be plugged in — easier than pulling the SD\n#    card out of a mounted screen.\nfor m in /media/*/* /media/* /mnt/usb /mnt/*; do\n  [ -d \"$m\" ] || continue\n  case \"$m\" in /media/pi|/media|/mnt) continue ;; esac\n  mountpoint -q \"$m\" 2>/dev/null || continue\n  if mkdir -p \"$m/infoscreen-logs\" 2>/dev/null && cp \"$OUT\" \"$m/infoscreen-logs/\" 2>/dev/null; then\n    sync\n    SAVED=\"${SAVED:+$SAVED and }$m/infoscreen-logs/$BASE\"\n  fi\ndone\n\nif [ \"${PS_DIAG_QUIET:-0}\" = 1 ]; then\n  [ -n \"$SAVED\" ] && echo \"  Diagnostics saved to: $SAVED\" || echo \"  Diagnostics at $OUT (could not write to removable media)\"\n  exit 0\nfi\n\necho\necho \"  ============================================================\"\necho \"   InfoScreen diagnostics collected\"\necho \"  ============================================================\"\necho\nif [ -n \"$SAVED\" ]; then\n  echo \"   Saved to: $SAVED\"\n  echo\n  echo \"   Power the Pi off, put the SD card (or the stick) in a PC, and\"\n  echo \"   open \\\\infoscreen-logs\\\\$BASE with Notepad.\"\n  echo \"   It is plain text, and secrets have been redacted.\"\nelse\n  echo \"   COULD NOT WRITE TO REMOVABLE MEDIA.\"\n  echo \"   The report is at $OUT (lost on reboot).\"\n  echo\n  echo \"   Mounts seen:\"\n  mount | sed 's/^/     /'\nfi\necho\n",
  "kiosk/harden-kiosk.sh": "#!/bin/sh\n# infoscreen-harden — lock the kiosk down so a screen is a screen, not a PC.\n#\n# Why this exists: with a keyboard attached, the kiosk browser was a general\n# purpose browser. Ctrl+Shift+N opened a private window, F1 opened help in a new\n# tab, Ctrl+T opened a tab, and from there the screen could be pointed anywhere.\n# Alt+F4 killed it, though the supervisor did bring it back — that part was\n# already working and is left alone.\n#\n# Five layers, because each one alone has a hole:\n#\n#   1. USB    — a keyboard is refused before the driver binds (infoscreen-usbguard).\n#               This is the real fix; everything below is defence in depth for\n#               the case where IT has deliberately authorised a keyboard.\n#   2. Chromium managed policy — incognito off, devtools off, one allowed origin.\n#               Policy beats command-line flags: flags can be dropped by a\n#               restart from somewhere else, a policy file cannot.\n#   3. Openbox — no keybindings, no root menu, no window decorations.\n#   4. X       — no VT switching, no zapping the server, screen blanking off.\n#   5. Console — getty on the physical TTYs disabled, so Ctrl+Alt+F2 has nothing\n#               to land on even if someone gets that far.\n#\n# Idempotent. Safe to re-run on every boot, and it is.\n#\n# Usage: infoscreen-harden [server-url]\n\nset -eu\n\nSERVER_URL=\"${1:-${INFOSCREEN_URL:-}}\"\n[ -z \"$SERVER_URL\" ] && [ -f /etc/infoscreen.env ] && \\\n  SERVER_URL=$(. /etc/infoscreen.env 2>/dev/null; printf '%s' \"${INFOSCREEN_URL:-}\")\n\nlog() { echo \"[harden] $*\"; }\n\n# v4.9.55: this script runs only on screens named InfoScreen throughout (new\n# installs, and screens renamed by their screen bundle). Screens that still\n# have the old names are served the copy kept for them in pi-agent/legacy.\nAGENT_DIR=/opt/infoscreen-agent\nAGENT_PY=\"$AGENT_DIR/infoscreen-agent.py\"\nAGENT_SVC=infoscreen-agent\n# Any agent process, whatever folder it was started from before the reboot.\nAGENT_RE='screen-agent/[a-z]*screen-agent\\.py'\n\n# Origin only — the allowlist is matched on scheme+host+port, and pinning it to\n# a full path would break the viewer's own query strings.\nALLOWED_ORIGIN=$(printf '%s' \"$SERVER_URL\" | sed -E 's#^(https?://[^/]+).*#\\1#')\n[ -z \"$ALLOWED_ORIGIN\" ] && ALLOWED_ORIGIN=\"http://localhost\"\n\n# ── 1. Chromium managed policy ──────────────────────────────────────\n# Both paths are written: Debian/Raspberry Pi OS reads /etc/chromium/policies,\n# Alpine and some builds read /etc/chromium-browser/policies, Chrome proper\n# reads /etc/opt/chrome. Writing all three costs nothing and removes a whole\n# class of \"it worked on the other image\" bug — which matters more now that the\n# same software runs on Pi boards and on x86 laptops.\n#\n# Note on URL filtering: an information screen legitimately shows arbitrary\n# external websites, because that is what departments schedule on it. A blanket\n# URLBlocklist with only the server allowed would lock the product down by\n# breaking it. So the blocklist covers only what a visitor could use to leave\n# the kiosk — local files, browser internals, other apps — and leaves the open\n# web alone. Navigation is prevented by there being no keyboard, not by a list.\n\n# Unpacked extensions get an ID derived from the SHA-256 of their absolute\n# path: first 32 hex digits, each mapped 0-f to a-p. Computing it here lets the\n# consent extension stay loadable while every other extension is blocked.\next_id_for() {\n  _p=\"$1\"\n  command -v sha256sum >/dev/null 2>&1 || { printf ''; return; }\n  printf '%s' \"$_p\" | sha256sum | cut -c1-32 | tr '0123456789abcdef' 'abcdefghijklmnop'\n}\n\nEXT_DIR=\"$AGENT_DIR/cookie-dismiss\"\nEXT_ID=$(ext_id_for \"$EXT_DIR\")\n\nwrite_chromium_policy() {\n  _allow_ext=\"\"\n  [ -n \"$EXT_ID\" ] && _allow_ext=\"\\\"$EXT_ID\\\"\"\n\n  for base in /etc/chromium /etc/chromium-browser /etc/opt/chrome; do\n    dir=\"$base/policies/managed\"\n    mkdir -p \"$dir\" 2>/dev/null || continue\n    cat > \"$dir/infoscreen.json\" <<JSON\n{\n  \"_comment\": \"Managed by InfoScreen. Hand edits are overwritten on every boot.\",\n\n  \"IncognitoModeAvailability\": 1,\n  \"DeveloperToolsAvailability\": 2,\n  \"_devmode_note\": \"v4.9.56: Chromium 155 also switches off extension developer mode when DevTools are disabled, and without developer mode it ignores --load-extension: the screen helper never ran, so website videos never started on the Pis. Developer mode on (0) only lets unpacked extensions load; DevTools stay off and the kiosk has no extensions page to open.\",\n  \"ExtensionDeveloperModeSettings\": 0,\n  \"RemoteDebuggingAllowed\": false,\n  \"BrowserSignin\": 0,\n  \"BrowserGuestModeEnabled\": false,\n  \"BrowserAddPersonEnabled\": false,\n  \"SyncDisabled\": true,\n  \"SafeBrowsingProtectionLevel\": 1,\n  \"NetworkPredictionOptions\": 2,\n  \"SearchSuggestEnabled\": false,\n  \"PasswordManagerEnabled\": false,\n  \"AutofillAddressEnabled\": false,\n  \"AutofillCreditCardEnabled\": false,\n  \"PrintingEnabled\": false,\n  \"DownloadRestrictions\": 3,\n  \"AllowFileSelectionDialogs\": false,\n  \"DefaultSearchProviderEnabled\": false,\n  \"BookmarkBarEnabled\": false,\n  \"EditBookmarksEnabled\": false,\n  \"ShowHomeButton\": false,\n  \"SavingBrowserHistoryDisabled\": true,\n  \"TranslateEnabled\": false,\n  \"MetricsReportingEnabled\": false,\n  \"BackgroundModeEnabled\": false,\n  \"PromptForDownloadLocation\": false,\n  \"TaskManagerEndProcessEnabled\": false,\n  \"_extension_note\": \"No blanket ExtensionInstallBlocklist here, deliberately. Allowlisting an unpacked extension requires its ID, which Chrome derives from the SHA-256 of its resolved absolute path -- and the updater symlink-swaps /opt/infoscreen-agent, so that path is not stable. A wrong ID silently blocks the consent extension and cookie banners come back with nothing in any log to say why. The kiosk has no keyboard and no browser UI, so there is no route to install an extension anyway; this was defence in depth that was costing a working feature.\",\n  \"ExtensionInstallSources\": [],\n  \"DefaultPopupsSetting\": 2,\n  \"DefaultNotificationsSetting\": 2,\n  \"DefaultGeolocationSetting\": 2,\n  \"DefaultSensorsSetting\": 2,\n  \"DefaultWebBluetoothGuardSetting\": 2,\n  \"DefaultWebUsbGuardSetting\": 2,\n  \"DefaultSerialGuardSetting\": 2,\n  \"DefaultHidGuardSetting\": 2,\n  \"DefaultFileSystemReadGuardSetting\": 2,\n  \"DefaultFileSystemWriteGuardSetting\": 2,\n  \"AudioCaptureAllowed\": false,\n  \"VideoCaptureAllowed\": false,\n  \"ScreenCaptureAllowed\": false,\n  \"URLBlocklist\": [\n    \"file://*\",\n    \"chrome://*\",\n    \"chrome-untrusted://*\",\n    \"devtools://*\",\n    \"view-source:*\",\n    \"filesystem://*\",\n    \"ftp://*\",\n    \"smb://*\",\n    \"about:flags\",\n    \"chrome-extension://*\"\n  ],\n  \"_lna_note\": \"v4.4.1: Chrome 142+ asks 'wants to Access other apps and services on this device' when a page loads anything from localhost. The viewer plays videos from the agent's local cache (http://localhost:7779), so every video put that dialog on the screen, where any passer-by could answer it. Allowed here for our own server only.\",\n  \"LocalNetworkAccessAllowedForUrls\": [\"$ALLOWED_ORIGIN\"],\n  \"URLAllowlist\": [\n    \"chrome://newtab\",\n    \"$ALLOWED_ORIGIN\"\n  ],\n  \"ClearBrowsingDataOnExitList\": [\"browsing_history\", \"download_history\", \"cookies_and_other_site_data\", \"cached_images_and_files\", \"password_signin\", \"autofill\"]\n}\nJSON\n    log \"chromium policy -> $dir/infoscreen.json\"\n  done\n  if [ -n \"$EXT_ID\" ]; then log \"consent extension allowlisted as $EXT_ID\"; fi\n}\n\n# Incognito is off by policy, and a policy cannot be dropped by restarting the\n# browser with different flags the way a command-line switch can. Together with\n# devtools being off and view-source blocked, the Ctrl+Shift+N route is closed\n# whether or not a keyboard is ever authorised.\n\n# ── 2. Openbox: strip every keybinding and the root menu ────────────\nwrite_openbox_config() {\n  for home in /root /home/pi /home/kiosk /home/infoscreen /home/piscreen; do\n    [ -d \"$home\" ] || continue\n    dir=\"$home/.config/openbox\"\n    mkdir -p \"$dir\" 2>/dev/null || continue\n    cat > \"$dir/rc.xml\" <<'XML'\n<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<openbox_config xmlns=\"http://openbox.org/3.4/rc\">\n  <!-- InfoScreen kiosk profile. No useful keybindings: every shortcut the\n       window manager acts on is one a visitor could use. No mouse bindings\n       on the desktop either, so right-click has no menu.\n\n       The keybinds below are the exception, and they do nothing on purpose.\n       A key the window manager does NOT claim goes straight to Chromium, and\n       Chromium closes itself on Alt+F4, Ctrl+W, Ctrl+Shift+W, Ctrl+Q and\n       Ctrl+F4 (found in the field, v4.0.0). Claiming them here means Chromium\n       never sees them. \"true\" is a no-op command. -->\n  <resistance><strength>0</strength></resistance>\n  <focus>\n    <focusNew>yes</focusNew>\n    <followMouse>no</followMouse>\n    <underMouse>no</underMouse>\n  </focus>\n  <placement><policy>Smart</policy></placement>\n  <theme>\n    <name>Clearlooks</name>\n    <keepBorder>no</keepBorder>\n    <animateIconify>no</animateIconify>\n    <titleLayout></titleLayout>\n  </theme>\n  <desktops>\n    <number>1</number>\n    <firstdesk>1</firstdesk>\n    <popupTime>0</popupTime>\n  </desktops>\n  <keyboard>\n    <chainQuitKey></chainQuitKey>\n    <!-- INFOSCREEN-SWALLOW-KEYS: closes the kiosk browser if it reaches it -->\n    <keybind key=\"A-F4\"><action name=\"Execute\"><command>true</command></action></keybind>\n    <keybind key=\"C-w\"><action name=\"Execute\"><command>true</command></action></keybind>\n    <keybind key=\"C-S-w\"><action name=\"Execute\"><command>true</command></action></keybind>\n    <keybind key=\"C-q\"><action name=\"Execute\"><command>true</command></action></keybind>\n    <keybind key=\"C-S-q\"><action name=\"Execute\"><command>true</command></action></keybind>\n    <keybind key=\"C-F4\"><action name=\"Execute\"><command>true</command></action></keybind>\n    <keybind key=\"C-n\"><action name=\"Execute\"><command>true</command></action></keybind>\n    <keybind key=\"C-t\"><action name=\"Execute\"><command>true</command></action></keybind>\n    <!-- v4.4.1: Ctrl+Shift+T restored a closed window as a NORMAL browser\n         window (tabs, address bar) outside kiosk mode; Ctrl+Shift+N opens\n         another window. Only window-openers here: everything else a visitor\n         could reach (browser pages, devtools, files, printing, downloads) is\n         already blocked by policy, and these bindings also apply in a\n         maintenance terminal, where Ctrl+H/U/J/P must keep working. The\n         agent's window guard catches whatever still gets through. -->\n    <keybind key=\"C-S-t\"><action name=\"Execute\"><command>true</command></action></keybind>\n    <keybind key=\"C-S-n\"><action name=\"Execute\"><command>true</command></action></keybind>\n  </keyboard>\n  <mouse>\n    <dragThreshold>8</dragThreshold>\n    <doubleClickTime>200</doubleClickTime>\n    <context name=\"Desktop\"></context>\n    <context name=\"Root\"></context>\n    <context name=\"Frame\"></context>\n    <context name=\"Titlebar\"></context>\n    <context name=\"Client\"></context>\n  </mouse>\n  <applications>\n    <application class=\"*\">\n      <decor>no</decor>\n      <maximized>yes</maximized>\n      <fullscreen>yes</fullscreen>\n      <layer>normal</layer>\n    </application>\n  </applications>\n</openbox_config>\nXML\n    log \"openbox profile → $dir/rc.xml\"\n  done\n  # Apply to a session that is already running, so the close keys are blocked\n  # now rather than after the next reboot. Harmless when no X is up.\n  if command -v openbox >/dev/null 2>&1; then\n    for xa in /root/.Xauthority /home/kiosk/.Xauthority /home/pi/.Xauthority /home/infoscreen/.Xauthority /home/piscreen/.Xauthority; do\n      [ -f \"$xa\" ] || continue\n      DISPLAY=:0 XAUTHORITY=\"$xa\" openbox --reconfigure >/dev/null 2>&1 && { log \"openbox reconfigured\"; break; }\n    done\n  fi\n}\n\n# ── 3. X server: no VT switching, no Ctrl+Alt+Backspace ─────────────\nwrite_xorg_config() {\n  mkdir -p /etc/X11/xorg.conf.d 2>/dev/null || return 0\n  cat > /etc/X11/xorg.conf.d/99-infoscreen-kiosk.conf <<'CONF'\n# Managed by InfoScreen.\n#\n# DontVTSwitch removes Ctrl+Alt+F1..F12, which is how you would otherwise drop\n# out of the kiosk to a text console and get a root shell on an image where\n# autologin is on. DontZap removes Ctrl+Alt+Backspace, which killed the X\n# server — the supervisor restarts it, but the seconds in between showed a bare\n# console on a screen in a public corridor.\nSection \"ServerFlags\"\n    Option \"DontVTSwitch\" \"true\"\n    Option \"DontZap\"      \"true\"\n    Option \"BlankTime\"    \"0\"\n    Option \"StandbyTime\"  \"0\"\n    Option \"SuspendTime\"  \"0\"\n    Option \"OffTime\"      \"0\"\nEndSection\nCONF\n  log \"xorg lockdown → /etc/X11/xorg.conf.d/99-infoscreen-kiosk.conf\"\n}\n\n# ── 4. Console logins on the physical TTYs ──────────────────────────\ndisable_getty() {\n  # Belt and braces with DontVTSwitch: if a future image ships an X server\n  # that ignores the option, there is still nothing to log in to.\n  if command -v systemctl >/dev/null 2>&1; then\n    for n in 2 3 4 5 6; do\n      systemctl mask \"getty@tty$n.service\" >/dev/null 2>&1 || true\n    done\n    log \"masked getty on tty2-tty6\"\n  elif [ -f /etc/inittab ]; then\n    if ! grep -q '^# infoscreen-harden' /etc/inittab; then\n      sed -i -E 's|^(tty[2-6]:.*)$|# infoscreen-harden \\1|' /etc/inittab 2>/dev/null || true\n      echo '# infoscreen-harden: physical console logins disabled' >> /etc/inittab\n      log \"disabled tty2-tty6 in inittab\"\n    fi\n  fi\n}\n\n# ── 5. Runtime X settings ───────────────────────────────────────────\napply_x_runtime() {\n  DISPLAY=\"${DISPLAY:-:0}\"\n  export DISPLAY\n  # Wake first, then disable the mechanisms that can blank it again.  Doing\n  # only `xset -dpms` is not enough when a display manager has already put the\n  # output into the Off state.\n  xset s reset      2>/dev/null || true\n  xset dpms force on 2>/dev/null || true\n  xset s off        2>/dev/null || true\n  xset s noblank    2>/dev/null || true\n  xset -dpms        2>/dev/null || true\n  # Ctrl+Alt+F* again, this time at the keymap level, for a running server that\n  # was started before the config above existed.\n  setxkbmap -option srvrkeys:none 2>/dev/null || true\n  log \"runtime X settings applied on $DISPLAY (awake, saver off, DPMS off)\"\n}\n\n# ── 5b. Desktop lockers/savers are not kiosk security ───────────────\n# USB/input lockdown is the security boundary. A desktop screensaver or lock\n# program only paints over Chromium after an idle timeout and can leave a wall\n# display looking dead while the agent/browser are both healthy. Disable the\n# dedicated locker daemons and their common XDG autostart names, without\n# touching the window manager or the browser.\ndisable_screen_lockers() {\n  for p in xscreensaver light-locker xss-lock xautolock slock i3lock; do\n    pkill -x \"$p\" >/dev/null 2>&1 || true\n  done\n  for home in /root /home/pi /home/kiosk /home/infoscreen /home/piscreen; do\n    [ -d \"$home\" ] || continue\n    mkdir -p \"$home/.config/autostart\" 2>/dev/null || true\n    for d in xscreensaver.desktop light-locker.desktop xss-lock.desktop xautolock.desktop; do\n      cat > \"$home/.config/autostart/$d\" <<'DESKTOP'\n[Desktop Entry]\nType=Application\nHidden=true\nDESKTOP\n    done\n  done\n  log \"desktop screen lockers/savers disabled; kiosk input lockdown remains active\"\n}\n\n# ── 6. Record what we did ───────────────────────────────────────────\nstamp() {\n  mkdir -p /var/lib/infoscreen 2>/dev/null || return 0\n  cat > /var/lib/infoscreen/hardening.json <<JSON\n{\n  \"hardened_at\": \"$(date -u '+%Y-%m-%dT%H:%M:%SZ')\",\n  \"allowed_origin\": \"$ALLOWED_ORIGIN\",\n  \"chromium_policy\": true,\n  \"openbox_locked\": true,\n  \"vt_switch_disabled\": true,\n  \"console_login_disabled\": true,\n  \"platform\": \"$(grep -qi raspberry /proc/device-tree/model 2>/dev/null && echo rpi || echo laptop)\",\n  \"laptop_power_fixed\": $( [ -d /proc/acpi/button/lid ] && echo true || echo false )\n}\nJSON\n}\n\n# ── 6. Laptops ──────────────────────────────────────────────────────\n# An information screen built on a laptop has failure modes a Pi does not.\n# Closing the lid suspends it; the battery runs down and it sleeps; the power\n# button shuts it off with one press. All three look identical from the\n# corridor — a dead screen — and all three are configuration, not hardware.\n# Alpine: make sure udev is the device manager, not mdev. A screen that was\n# installed by an older build has eudev on disk and mdev in sysinit, which is\n# why X will not start on it. Repairing from here means the fix reaches every\n# already-installed laptop through a normal agent update, with nobody visiting.\nensure_udev() {\n  command -v rc-update >/dev/null 2>&1 || return 0          # not OpenRC\n  [ -f /etc/init.d/udev ] || return 0                        # eudev not installed\n  rc-status sysinit 2>/dev/null | grep -q '\\budev\\b' && return 0   # already right\n\n  log \"Alpine: switching device manager from mdev to udev (needed by Xorg)\"\n  rc-update del mdev sysinit        >/dev/null 2>&1 || true\n  for svc in udev udev-trigger udev-settle; do\n    [ -f \"/etc/init.d/$svc\" ] && rc-update add \"$svc\" sysinit >/dev/null 2>&1 || true\n  done\n  [ -f /etc/init.d/udev-postmount ] && rc-update add udev-postmount default >/dev/null 2>&1 || true\n  # Start it now so X can come up without waiting for a reboot.\n  rc-service udev start         >/dev/null 2>&1 || true\n  rc-service udev-trigger start >/dev/null 2>&1 || true\n  log \"udev enabled — the display should start on the next attempt\"\n}\n\nharden_laptop() {\n  # Nothing to do on a board with no lid and no power button worth trapping.\n  [ -d /proc/acpi/button/lid ] || [ -d /sys/class/power_supply/BAT0 ] || return 0\n\n  if [ -d /etc/systemd ]; then\n    mkdir -p /etc/systemd/logind.conf.d 2>/dev/null || true\n    cat > /etc/systemd/logind.conf.d/infoscreen.conf <<'CONF'\n# Managed by InfoScreen.\n# A screen mounted on a wall or sitting on a shelf is very often running with\n# the lid shut. The default action for that is suspend, which is why a laptop\n# kiosk \"randomly turns itself off\". The power button is trapped for the same\n# reason: one press by a passer-by should not end the day.\n[Login]\nHandleLidSwitch=ignore\nHandleLidSwitchDocked=ignore\nHandleLidSwitchExternalPower=ignore\nHandlePowerKey=ignore\nHandleSuspendKey=ignore\nHandleHibernateKey=ignore\nIdleAction=ignore\nCONF\n    log \"laptop: lid, power key and idle suspend disabled\"\n\n    # Belt and braces — logind can be overridden by a desktop power manager,\n    # masking the targets cannot.\n    systemctl mask sleep.target suspend.target hibernate.target hybrid-sleep.target >/dev/null 2>&1 || true\n    systemctl restart systemd-logind >/dev/null 2>&1 || true\n  fi\n\n  # Alpine/OpenRC laptops use acpid; tell it to do nothing on lid or power.\n  if [ -d /etc/acpi ]; then\n    mkdir -p /etc/acpi/events 2>/dev/null || true\n    for ev in lid power; do\n      cat > \"/etc/acpi/events/infoscreen-$ev\" <<CONF\nevent=button/$ev.*\naction=/bin/true\nCONF\n    done\n    command -v rc-service >/dev/null 2>&1 && rc-service acpid restart >/dev/null 2>&1 || true\n    log \"laptop: acpid lid/power events neutralised\"\n  fi\n\n  # Backlight to full. A laptop panel restored from a previous owner's settings\n  # can come up at minimum brightness, which on a wall-mounted screen is\n  # indistinguishable from a machine that failed to boot. Nothing else in the\n  # stack touches this.\n  for bl in /sys/class/backlight/*/; do\n    [ -d \"$bl\" ] || continue\n    if [ -r \"$bl/max_brightness\" ] && [ -w \"$bl/brightness\" ]; then\n      cat \"$bl/max_brightness\" > \"$bl/brightness\" 2>/dev/null \\\n        && log \"backlight $(basename \"$bl\") set to maximum\"\n    fi\n  done\n\n  # Keep the panel lit. xset handles the X blanker; this handles the console\n  # blanker that takes over before X starts and after it dies.\n  command -v setterm >/dev/null 2>&1 && setterm -blank 0 -powerdown 0 >/dev/null 2>&1 || true\n\n  # A laptop that is unplugged should still tell us before it dies rather than\n  # vanishing from the portal. The agent reports battery state; this just makes\n  # sure the kernel exposes it.\n  if [ -d /sys/class/power_supply ]; then log \"laptop: battery reporting available\"; fi\n}\n\n# ── 6b. Init service owns the agent (v4.9.43) ───────────────────────\n# Older images can still have an Openbox/autostart copy of infoscreen-agent.py.\n# If that orphan starts a fraction of a second before systemd, the real service\n# becomes a permanent standby and Restart=always no longer protects the screen.\n# Install a narrow ExecStartPre that kills only the exact InfoScreen agent command\n# before the supervised process starts. The Python agent has the same ownership\n# rule at runtime; this is the boot-time belt-and-braces version.\ninstall_agent_service_guard() {\n  mkdir -p /usr/local/sbin\n  cat > /usr/local/sbin/infoscreen-agent-cleanup <<'CLEANEOF'\n#!/bin/sh\nset -u\n_pids=$(pgrep -f 'screen-agent/[a-z]*screen-agent\\.py' 2>/dev/null || true)\n[ -n \"$_pids\" ] || exit 0\nfor _p in $_pids; do\n  [ \"$_p\" = \"$$\" ] && continue\n  kill -TERM \"$_p\" 2>/dev/null || true\ndone\nsleep 1\nfor _p in $_pids; do\n  [ \"$_p\" = \"$$\" ] && continue\n  kill -0 \"$_p\" 2>/dev/null && kill -KILL \"$_p\" 2>/dev/null || true\ndone\nexit 0\nCLEANEOF\n  chmod 0755 /usr/local/sbin/infoscreen-agent-cleanup\n\n  if command -v systemctl >/dev/null 2>&1 && [ -f \"/etc/systemd/system/$AGENT_SVC.service\" ]; then\n    mkdir -p \"/etc/systemd/system/$AGENT_SVC.service.d\"\n    cat > \"/etc/systemd/system/$AGENT_SVC.service.d/10-infoscreen-single-owner.conf\" <<'UNITEOF'\n[Service]\nExecStartPre=/usr/local/sbin/infoscreen-agent-cleanup\nUNITEOF\n    systemctl daemon-reload >/dev/null 2>&1 || true\n    log \"agent supervisor guard installed (systemd)\"\n    return 0\n  fi\n\n  # Newer OpenRC units use a pidfile, but many legacy laptop images do not.\n  # The Python-side ownership check handles those. Keep the cleanup helper on\n  # disk so an image/update can add start_pre without downloading anything.\n  if command -v rc-service >/dev/null 2>&1; then\n    log \"agent supervisor cleanup helper installed (OpenRC runtime guard is in agent)\"\n  fi\n  return 0\n}\n\n# ── 7. Root helper for a non-root agent (v4.5.0) ───────────────────\n# On a Pi the agent runs as the kiosk user, so the USB guard could not write\n# sysfs (it ran report-only: every keyboard worked) and this script could only\n# change anything at boot. The helper does exactly three things as root —\n# (de)authorize a USB device, run this lockdown, install the agent's\n# downloaded copy of it — and the sudoers line allows only the helper. The\n# agent installs the same helper itself if it gets there first; the text is\n# kept identical by a contract.\ninstall_priv_helper() {\n  _u=$(sed -n 's/^User=//p' \"/etc/systemd/system/$AGENT_SVC.service\" 2>/dev/null | head -1)\n  if [ -z \"$_u\" ] || [ \"$_u\" = root ]; then log \"agent runs as root — no helper needed\"; return 0; fi\n  case \"$_u\" in *[!a-z0-9_-]*) log \"unusual agent user '$_u' — helper not installed\"; return 0 ;; esac\n  mkdir -p /usr/local/sbin\n  cat > /usr/local/sbin/infoscreen-priv <<'PRIVEOF'\n#!/bin/sh\n# infoscreen-priv — the few things the display agent must do as root (v4.5.0).\n#   usb-write <sysfs-path> <0|1>   (de)authorize a USB device / controller default\n#   harden                         run the kiosk lockdown now\n#   install-harden <file>          install the agent's downloaded lockdown script\n#   runner-repair                  repair/start the privileged image-update runner\n#   set-url <url> [previous-url]   point /etc/infoscreen.env at another server\n#                                  (v4.6.0: moving servers without root)\n# Everything else is refused. Installed by the agent (once, with the installer's\n# sudo cp rights) or by infoscreen-harden itself.\nset -eu\ncase \"${1:-}\" in\n  usb-write)\n    p=\"${2:-}\"; v=\"${3:-}\"\n    case \"$v\" in 0|1) ;; *) echo \"bad value\" >&2; exit 2 ;; esac\n    case \"$p\" in *..*|*\" \"*) echo \"bad path\" >&2; exit 2 ;; esac\n    case \"$p\" in\n      /sys/bus/usb/devices/*/authorized|/sys/bus/usb/devices/*/authorized_default) ;;\n      *) echo \"path not allowed\" >&2; exit 2 ;;\n    esac\n    printf '%s' \"$v\" > \"$p\" ;;\n  harden)\n    exec /usr/local/bin/infoscreen-harden >>/var/log/infoscreen-harden.log 2>&1 ;;\n  install-harden)\n    f=\"${2:-}\"\n    case \"$f\" in /opt/infoscreen-agent/harden-kiosk.sh) ;; *) echo \"only the agent's copy\" >&2; exit 2 ;; esac\n    head -c 2 \"$f\" | grep -q '#!' || { echo \"not a script\" >&2; exit 2; }\n    sh -n \"$f\" || { echo \"does not parse\" >&2; exit 2; }\n    install -m 0755 -o root -g root \"$f\" /usr/local/bin/infoscreen-harden ;;\n  runner-repair)\n    exec /usr/local/bin/infoscreen-harden --runner-only >>/var/log/infoscreen-harden.log 2>&1 ;;\n  set-url)\n    u=\"${2:-}\"; prev=\"${3:-}\"\n    printf '%s' \"$u\" | grep -Eq '^https?://[A-Za-z0-9.-]+(:[0-9]{1,5})?$' || { echo \"bad url\" >&2; exit 2; }\n    [ -z \"$prev\" ] || printf '%s' \"$prev\" | grep -Eq '^https?://[A-Za-z0-9.-]+(:[0-9]{1,5})?$' || { echo \"bad previous url\" >&2; exit 2; }\n    f=/etc/infoscreen.env; t=$(mktemp)\n    grep -v -e '^INFOSCREEN_URL=' -e '^INFOSCREEN_URL_PREVIOUS=' -e '^INFOSCREEN_MOVED_AT=' \"$f\" > \"$t\" 2>/dev/null || true\n    printf 'INFOSCREEN_URL=%s\\n' \"$u\" >> \"$t\"\n    [ -z \"$prev\" ] || printf 'INFOSCREEN_URL_PREVIOUS=%s\\nINFOSCREEN_MOVED_AT=%s\\n' \"$prev\" \"$(date +%s)\" >> \"$t\"\n    cat \"$t\" > \"$f\"; rm -f \"$t\" ;;\n  *) echo \"usage: infoscreen-priv usb-write|harden|install-harden|runner-repair|set-url\" >&2; exit 2 ;;\nesac\nPRIVEOF\n  chmod 0755 /usr/local/sbin/infoscreen-priv\n  chown root:root /usr/local/sbin/infoscreen-priv 2>/dev/null || true\n  _tmp=$(mktemp)\n  printf '# InfoScreen v4.5.0: the display agent may run its root helper, nothing else.\\n%s ALL=(root) NOPASSWD: /usr/local/sbin/infoscreen-priv\\n' \"$_u\" > \"$_tmp\"\n  if command -v visudo >/dev/null 2>&1 && visudo -cf \"$_tmp\" >/dev/null 2>&1; then\n    install -m 0440 -o root -g root \"$_tmp\" /etc/sudoers.d/infoscreen-priv\n    log \"root helper installed for $_u\"\n  else\n    log \"WARNING: the sudoers line did not validate — root helper not enabled\"\n  fi\n  rm -f \"$_tmp\"\n}\n\n# ── 8. Root update runner (v4.9.10) ───────────────────────────────────\n# Agent-only Pi installs did not have infoscreen-commands at all. Full screen\n# bundles contain root-owned files, while the Python agent is intentionally\n# non-root after kiosk hardening. The agent stages the server's canonical\n# runner and updater in its own directory; this root pass installs them and\n# starts a dedicated service. From then on image_update is executed here, not\n# by the display agent.\nensure_update_runner() {\n  _src_cmd=\"$AGENT_DIR/infoscreen-commands.sh\"\n  _src_upd=\"$AGENT_DIR/infoscreen-update.sh\"\n  _src_boot=\"$AGENT_DIR/infoscreen-boot-repair.sh\"\n  [ -s \"$_src_cmd\" ] && [ -s \"$_src_upd\" ] || { log \"update runner bootstrap: staged scripts not ready yet\"; return 0; }\n  sh -n \"$_src_cmd\" >/dev/null 2>&1 || { log \"update runner bootstrap: command script does not parse\"; return 1; }\n  sh -n \"$_src_upd\" >/dev/null 2>&1 || { log \"update runner bootstrap: update script does not parse\"; return 1; }\n  [ ! -s \"$_src_boot\" ] || sh -n \"$_src_boot\" >/dev/null 2>&1 || { log \"update runner bootstrap: boot repair script does not parse\"; return 1; }\n\n  _changed=0\n  if ! cmp -s \"$_src_cmd\" /usr/local/bin/infoscreen-commands 2>/dev/null; then\n    install -m 0755 -o root -g root \"$_src_cmd\" /usr/local/bin/infoscreen-commands || return 1\n    _changed=1\n  fi\n  if ! cmp -s \"$_src_upd\" /usr/local/bin/infoscreen-update 2>/dev/null; then\n    install -m 0755 -o root -g root \"$_src_upd\" /usr/local/bin/infoscreen-update || return 1\n    _changed=1\n  fi\n  if [ -s \"$_src_boot\" ] && ! cmp -s \"$_src_boot\" /usr/local/bin/infoscreen-boot-repair 2>/dev/null; then\n    install -m 0755 -o root -g root \"$_src_boot\" /usr/local/bin/infoscreen-boot-repair || return 1\n    _changed=1\n  fi\n\n  if command -v systemctl >/dev/null 2>&1; then\n    _unit=/etc/systemd/system/infoscreen-commands.service\n    _tmp=$(mktemp)\n    cat > \"$_tmp\" <<'UNITEOF'\n[Unit]\nDescription=InfoScreen privileged command runner\nAfter=network-online.target\nWants=network-online.target\n\n[Service]\nType=simple\nExecStart=/usr/local/bin/infoscreen-commands\nRestart=always\nRestartSec=10\n\n[Install]\nWantedBy=multi-user.target\nUNITEOF\n    if ! cmp -s \"$_tmp\" \"$_unit\" 2>/dev/null; then\n      install -m 0644 -o root -g root \"$_tmp\" \"$_unit\" || { rm -f \"$_tmp\"; return 1; }\n      _changed=1\n      systemctl daemon-reload >/dev/null 2>&1 || true\n    fi\n    rm -f \"$_tmp\"\n    systemctl enable infoscreen-commands >/dev/null 2>&1 || true\n    if [ \"$_changed\" -eq 1 ]; then systemctl restart infoscreen-commands >/dev/null 2>&1 || systemctl start infoscreen-commands >/dev/null 2>&1 || return 1\n    else systemctl is-active --quiet infoscreen-commands || systemctl start infoscreen-commands >/dev/null 2>&1 || return 1\n    fi\n    log \"root update runner ready (systemd)\"\n    return 0\n  fi\n\n  if command -v rc-service >/dev/null 2>&1; then\n    _init=/etc/init.d/infoscreen-commands\n    if [ ! -f \"$_init\" ]; then\n      cat > \"$_init\" <<'SVCEOF'\n#!/sbin/openrc-run\ndescription=\"InfoScreen privileged command runner\"\ncommand=\"/usr/local/bin/infoscreen-commands\"\ncommand_background=true\npidfile=\"/run/infoscreen-commands.pid\"\noutput_log=\"/var/log/infoscreen-commands.log\"\nerror_log=\"/var/log/infoscreen-commands.log\"\ndepend() { need net; after networking; }\nSVCEOF\n      chmod 0755 \"$_init\"\n      _changed=1\n    fi\n    command -v rc-update >/dev/null 2>&1 && rc-update add infoscreen-commands default >/dev/null 2>&1 || true\n    if [ \"$_changed\" -eq 1 ]; then rc-service infoscreen-commands restart >/dev/null 2>&1 || rc-service infoscreen-commands start >/dev/null 2>&1 || return 1\n    else rc-service infoscreen-commands status >/dev/null 2>&1 || rc-service infoscreen-commands start >/dev/null 2>&1 || return 1\n    fi\n    log \"root update runner ready (OpenRC)\"\n    return 0\n  fi\n\n  log \"update runner bootstrap: no supported service manager\"\n  return 1\n}\n\n# v4.9.29 legacy-agent rescue. A 4.9.22 process can be alive and authenticated\n# yet be unable to replace its own root-owned Python file. runner-repair is one\n# operation the old agent can already ask root to perform, so while we are here\n# we also stage the server's authenticated current agent atomically. This is NOT\n# a generic root downloader: the URL is fixed, requires the device token, the\n# result must compile as Python, and only the known agent path can be replaced.\nrescue_current_agent() {\n  _srv=\"${INFOSCREEN_URL:-}\"\n  if [ -f /etc/infoscreen.env ]; then\n    # shellcheck disable=SC1091\n    . /etc/infoscreen.env 2>/dev/null || true\n    _srv=\"${INFOSCREEN_URL:-$_srv}\"\n  fi\n  [ -n \"$_srv\" ] || { log \"agent rescue skipped: INFOSCREEN_URL is unavailable\"; return 1; }\n  _tok=\"${PI_TOKEN:-}\"\n  if [ -z \"$_tok\" ]; then\n    for _tf in /etc/infoscreen.token \"$AGENT_DIR/.runner-token\" /home/*/.infoscreen.token; do\n      [ -f \"$_tf\" ] || continue\n      _tok=$(tr -d '\\r\\n' < \"$_tf\" 2>/dev/null || true)\n      [ -n \"$_tok\" ] && break\n    done\n  fi\n  [ -n \"$_tok\" ] || { log \"agent rescue skipped: device token is unavailable\"; return 1; }\n\n  mkdir -p \"$AGENT_DIR\" /tmp\n  _tmp=/tmp/.infoscreen-agent-rescue.$$\n  rm -f \"$_tmp\"\n  if command -v curl >/dev/null 2>&1; then\n    curl -fsSL --connect-timeout 10 --max-time 60 -H \"X-Pi-Token: $_tok\" \\\n      \"${_srv%/}/api/pi/agent-download\" -o \"$_tmp\" || { rm -f \"$_tmp\"; log \"agent rescue download failed\"; return 1; }\n  elif command -v wget >/dev/null 2>&1; then\n    wget -q -T 60 --header=\"X-Pi-Token: $_tok\" -O \"$_tmp\" \\\n      \"${_srv%/}/api/pi/agent-download\" || { rm -f \"$_tmp\"; log \"agent rescue download failed\"; return 1; }\n  else\n    log \"agent rescue skipped: curl/wget missing\"; return 1\n  fi\n  [ -s \"$_tmp\" ] || { rm -f \"$_tmp\"; log \"agent rescue downloaded an empty file\"; return 1; }\n  grep -q \"^AGENT_VERSION[[:space:]]*=\" \"$_tmp\" || { rm -f \"$_tmp\"; log \"agent rescue rejected unexpected payload\"; return 1; }\n  _py=$(command -v python3 || command -v python || true)\n  [ -n \"$_py\" ] || { rm -f \"$_tmp\"; log \"agent rescue skipped: Python missing\"; return 1; }\n  \"$_py\" -m py_compile \"$_tmp\" >/dev/null 2>&1 || { rm -f \"$_tmp\"; log \"agent rescue rejected agent that does not compile\"; return 1; }\n\n  _dst=\"$AGENT_PY\"\n  _same=0\n  if [ -f \"$_dst\" ] && cmp -s \"$_tmp\" \"$_dst\"; then\n    rm -f \"$_tmp\"\n    _same=1\n    log \"agent rescue: installed agent already matches server; handoff is still required\"\n  else\n    _new=\"${_dst}.new.$$\"\n    mv \"$_tmp\" \"$_new\"\n    chmod 0755 \"$_new\"\n    chown --reference=\"$AGENT_DIR\" \"$_new\" 2>/dev/null || chown root:root \"$_new\" 2>/dev/null || true\n    mv -f \"$_new\" \"$_dst\"\n    _ver=$(sed -n \"s/^AGENT_VERSION[[:space:]]*=[[:space:]]*['\\\"]\\([^'\\\"]*\\)['\\\"].*/\\1/p\" \"$_dst\" | head -1)\n    log \"agent rescue installed ${_ver:-current server agent}; scheduling agent handoff\"\n  fi\n\n  # Snapshot first. Only processes that were already alive when rescue started\n  # are candidates for termination; a freshly restarted replacement must never\n  # be caught by a broad pkill. This also makes a repeated repair useful when\n  # the file is already current but an old loaded Python process is still alive.\n  _old_agent_pids=$(pgrep -f \"$AGENT_RE\" 2>/dev/null || true)\n  ( sleep 5\n    if command -v systemctl >/dev/null 2>&1; then systemctl restart \"$AGENT_SVC\" >/dev/null 2>&1 || true\n    elif command -v rc-service >/dev/null 2>&1; then rc-service \"$AGENT_SVC\" restart >/dev/null 2>&1 || true\n    elif command -v service >/dev/null 2>&1; then service \"$AGENT_SVC\" restart >/dev/null 2>&1 || true\n    fi\n    sleep 2\n    for _p in $_old_agent_pids; do\n      [ \"$_p\" = \"$$\" ] && continue\n      kill -TERM \"$_p\" >/dev/null 2>&1 || true\n    done\n    sleep 3\n    for _p in $_old_agent_pids; do\n      [ \"$_p\" = \"$$\" ] && continue\n      kill -0 \"$_p\" >/dev/null 2>&1 && kill -KILL \"$_p\" >/dev/null 2>&1 || true\n    done\n    # Legacy images can have no init-managed agent at all. In that case the\n    # Openbox supervisor normally brings it back; keep a final root-side safety\n    # net so a repair never leaves a permanently black screen.\n    if ! pgrep -f \"$AGENT_RE\" >/dev/null 2>&1; then\n      ( python3 \"$AGENT_PY\" >>/var/log/infoscreen-agent.log 2>&1 & ) || true\n    fi\n  ) </dev/null >/dev/null 2>&1 &\n  return 0\n}\n\n# v4.9.20/v4.9.29: the display agent can ask the narrow root helper to repair\n# only the privileged image-update service. Keep the runner result as the exit\n# code, but always attempt the legacy-agent rescue too, even if the runner itself\n# cannot start/authenticate yet.\nif [ \"${1:-}\" = \"--runner-only\" ]; then\n  _runner_rc=0\n  ensure_update_runner || _runner_rc=$?\n  rescue_current_agent || true\n  exit \"$_runner_rc\"\nfi\n\n# ── 9. Magic SysRq off (v4.5.0) ─────────────────────────────────────\n# The kernel acts on Alt+SysRq+<key> whatever X is doing: a keyboard at the\n# screen could reboot it (B) or kill every process (I) in one chord.\ndisable_sysrq() {\n  mkdir -p /etc/sysctl.d 2>/dev/null || true\n  printf '%s\\n' '# Managed by InfoScreen (v4.5.0): no Alt+SysRq on a public screen.' 'kernel.sysrq = 0' \\\n    > /etc/sysctl.d/99-infoscreen-sysrq.conf 2>/dev/null || true\n  echo 0 > /proc/sys/kernel/sysrq 2>/dev/null || true\n  log \"magic SysRq disabled\"\n}\n\n# Every step runs even if an earlier one fails. Under set -e a single failing\n# command used to abort the whole lockdown, and systemd showed only \"FAILED\"\n# at boot with the Chromium policy and everything after it never applied.\n# A step that fails is logged by name; the run fails (and systemd says so)\n# only if the Chromium policy itself could not be written.\nFAILED_STEPS=\"\"\nstep() {\n  if \"$@\"; then :; else\n    _rc=$?\n    log \"WARNING: step '$1' failed (exit $_rc) — continuing with the rest\"\n    FAILED_STEPS=\"$FAILED_STEPS $1\"\n  fi\n}\n\n# v4.9.55: on a screen renamed by its last bundle, put the old units, the old\n# env file and the old sudo lines away once the reboot has stopped them.\nretire_old_names() {\n  for _m in /usr/local/bin/infoscreen-agent-migrate /usr/local/bin/infoscreen-migrate; do\n    [ -x \"$_m\" ] || continue\n    case \"$_m\" in *agent-migrate) \"$_m\" ;; *) \"$_m\" --retire ;; esac || return 1\n  done\n}\n\nstep retire_old_names\nstep write_chromium_policy\nstep write_openbox_config\nstep write_xorg_config\nstep disable_getty\nstep ensure_udev\nstep harden_laptop\nstep apply_x_runtime\nstep disable_screen_lockers\nstep install_agent_service_guard\nstep install_priv_helper\nstep ensure_update_runner\nstep disable_sysrq\nstep stamp\n\nif [ -n \"$FAILED_STEPS\" ]; then\n  log \"kiosk hardening finished with failed step(s):$FAILED_STEPS\"\n  case \" $FAILED_STEPS \" in *\" write_chromium_policy \"*) exit 1 ;; esac\nelse\n  log \"kiosk hardening complete (allowed origin: $ALLOWED_ORIGIN)\"\nfi\nexit 0\n",
};

// Generated from the Infoskjerm 4.9.71 installer templates (routes/system.js).
// Every value in v is shell-quoted by the caller (_shq) or is a whole script.
function _screenSdScriptText(v) {
  return `#!/bin/bash
# Event-Admin screen SD card configurator (Raspberry Pi 5, Raspberry Pi OS 64-bit)
# Forked from the Infoskjerm configurator, version 4.9.71
# Run on the machine with the SD card reader after writing Pi OS with Imager.
# Usage: sudo bash configure-sd.sh
set -e

HOSTNAME=${v.hostname}
SERVER=${v.server}
INTERVAL=${v.interval}
PROVISION_SECRET=${v.secret}
WIFI_SSID=${v.wifiSsid}
WIFI_PASS=${v.wifiPass}
SCREEN_LANG=${v.lang}

echo ""
echo "======================================================="
echo "  Event-Admin screen - SD card configurator"
echo "======================================================="
echo ""

# ── Find partitions ──────────────────────────────────────────────
BOOT=""
ROOT=""

BOOT=$(findmnt -n -o TARGET -S LABEL=bootfs 2>/dev/null || true)
ROOT=$(findmnt -n -o TARGET -S LABEL=rootfs 2>/dev/null || true)

if [ -z "$BOOT" ]; then
  for p in /run/media/*/bootfs /media/*/bootfs /mnt/bootfs; do
    [ -d "$p" ] && BOOT="$p" && break
  done
fi
if [ -z "$ROOT" ]; then
  for p in /run/media/*/rootfs /media/*/rootfs /mnt/rootfs; do
    [ -d "$p" ] && ROOT="$p" && break
  done
fi

if [ -z "$BOOT" ]; then
  echo "ERROR: Cannot find bootfs partition."
  echo "Make sure the SD card is inserted and mounted."
  exit 1
fi
if [ -z "$ROOT" ]; then
  echo "ERROR: Cannot find rootfs partition."
  echo "Try: sudo mount /dev/sdX2 /mnt && ROOT=/mnt"
  exit 1
fi

echo "  bootfs: $BOOT"
echo "  rootfs: $ROOT"
echo ""

# ── Set hostname ─────────────────────────────────────────────────
if [ -n "$HOSTNAME" ]; then
  echo "[1/6] Setting hostname: $HOSTNAME"
  echo "$HOSTNAME" > "$ROOT/etc/hostname"
  sed -i "s/127.0.1.1.*/127.0.1.1\\\\t$HOSTNAME/" "$ROOT/etc/hosts"
else
  echo "[1/6] Hostname: skipped (not set)"
fi

# ── Create infoscreen.env ──────────────────────────────────────────
echo "[2/6] Writing /etc/infoscreen.env"
cat > "$ROOT/etc/infoscreen.env" << ENVEOF
INFOSCREEN_URL=$SERVER
INFOSCREEN_POLL_INTERVAL=$INTERVAL
INFOSCREEN_PROVISION_SECRET=$PROVISION_SECRET
SCREEN_LANG=$SCREEN_LANG
ENVEOF
chmod 644 "$ROOT/etc/infoscreen.env"

# ── Configure WiFi ───────────────────────────────────────────────
if [ -n "$WIFI_SSID" ]; then
  echo "[3/6] Configuring WiFi: $WIFI_SSID"
  NM_DIR="$ROOT/etc/NetworkManager/system-connections"
  mkdir -p "$NM_DIR"
  cat > "$NM_DIR/$WIFI_SSID.nmconnection" << WIFIEOF
[connection]
id=$WIFI_SSID
type=wifi
interface-name=wlan0
autoconnect=true
autoconnect-priority=100

[wifi]
ssid=$WIFI_SSID
mode=infrastructure

[wifi-security]
key-mgmt=wpa-psk
psk=$WIFI_PASS

[ipv4]
method=auto

[ipv6]
method=auto
WIFIEOF
  chmod 600 "$NM_DIR/$WIFI_SSID.nmconnection"
else
  echo "[3/6] WiFi: skipped (not set - using wired)"
fi

# ── Download agent package to bootfs ─────────────────────────────
echo "[4/6] Downloading agent package..."
ZIPNAME="infoscreen-pi-\${HOSTNAME:-agent}.zip"
curl -fSL -o "$BOOT/$ZIPNAME" \\
  "$SERVER/api/screens/sd-package?secret=$PROVISION_SECRET&hostname=$HOSTNAME&interval=$INTERVAL&lang=$SCREEN_LANG" \\
  || { echo "ERROR: Download failed. Check server URL and network."; exit 1; }
echo "  -> $BOOT/$ZIPNAME"
# Verify it's a real zip
FILETYPE=$(file -b "$BOOT/$ZIPNAME")
if echo "$FILETYPE" | grep -qi zip; then
  ZIPSIZE=$(du -h "$BOOT/$ZIPNAME" | cut -f1)
  echo "  ✓ Valid zip ($ZIPSIZE)"
  echo "  Contents:"
  unzip -l "$BOOT/$ZIPNAME" 2>/dev/null | grep -E "^\\s+[0-9]" | awk '{print "    " $4 " (" $1 " bytes)"}'
else
  echo "  ✗ ERROR: Downloaded file is not a valid zip!"
  echo "  File type: $FILETYPE"
  echo "  First 200 bytes:"
  head -c 200 "$BOOT/$ZIPNAME"
  echo ""
  rm -f "$BOOT/$ZIPNAME"
  exit 1
fi

# ── Enable KMS display driver on bootfs ──────────────────────────
echo "[5/7] Configuring display driver..."
CFGTXT="$BOOT/config.txt"
if [ -f "$CFGTXT" ]; then
  if ! grep -q "dtoverlay=vc4-kms-v3d" "$CFGTXT"; then
    echo "dtoverlay=vc4-kms-v3d" >> "$CFGTXT"
    echo "  Added dtoverlay=vc4-kms-v3d to config.txt"
  else
    echo "  KMS overlay already present"
  fi
  # Ensure GPU memory is adequate
  if ! grep -q "gpu_mem=" "$CFGTXT"; then
    echo "gpu_mem=128" >> "$CFGTXT"
    echo "  Added gpu_mem=128"
  fi
else
  echo "  WARNING: config.txt not found on bootfs"
fi

# ── Write firstrun script to bootfs ──────────────────────────────
echo "[6/7] Writing firstrun script..."
cat > "$BOOT/infoscreen-stage0.sh" << 'STAGE0EOF'
${v.stage0}
STAGE0EOF
chmod +x "$BOOT/infoscreen-stage0.sh"

# The real installer rides along on the boot partition. Stage 0 copies it
# onto the rootfs, verifies it, arms a normal systemd unit and reboots.
cat > "$BOOT/firstrun-infoscreen.sh" << 'FIRSTRUNEOF'
${v.firstrun}
FIRSTRUNEOF

# The diagnostics collector rides along. When a first boot fails, this is what
# writes the whole story to the FAT partition so the card can be pulled and read
# in any PC — instead of the failure being a photograph of forty console lines.
cat > "$BOOT/infoscreen-collect-diagnostics.sh" << 'DIAGEOF'
${v.diag}
DIAGEOF
chmod +x "$BOOT/infoscreen-collect-diagnostics.sh"
chmod +x "$BOOT/firstrun-infoscreen.sh"

# ── Install firstrun systemd service on rootfs ───────────────────
echo "[7/7] Installing firstrun service..."
cat > "$ROOT/etc/systemd/system/infoscreen-firstrun.service" << SVCEOF
[Unit]
Description=Event-Admin screen first-boot installer
After=network-online.target NetworkManager-wait-online.service
Wants=network-online.target
Requires=NetworkManager-wait-online.service
ConditionPathExists=/boot/firmware/firstrun-infoscreen.sh

[Service]
Type=oneshot
ExecStart=/bin/bash /boot/firmware/firstrun-infoscreen.sh
StandardOutput=journal+console
StandardError=journal+console
TimeoutStartSec=600

[Install]
WantedBy=multi-user.target
SVCEOF

mkdir -p "$ROOT/etc/systemd/system/multi-user.target.wants"
ln -sf /etc/systemd/system/infoscreen-firstrun.service \\
  "$ROOT/etc/systemd/system/multi-user.target.wants/infoscreen-firstrun.service"

# Also enable NetworkManager-wait-online so network-online.target works
mkdir -p "$ROOT/etc/systemd/system/NetworkManager.service.wants"
ln -sf /usr/lib/systemd/system/NetworkManager-wait-online.service \\
  "$ROOT/etc/systemd/system/NetworkManager.service.wants/NetworkManager-wait-online.service"

echo ""
echo "======================================================="
echo "  SD card configured!"
echo "-------------------------------------------------------"
echo "  Hostname: \${HOSTNAME:-<default>}"
echo "  Server:   $SERVER"
echo "  WiFi:     \${WIFI_SSID:-<none - wired>}"
echo "-------------------------------------------------------"
echo "  Files on bootfs:"
ls -lh "$BOOT"/*.zip "$BOOT"/firstrun-infoscreen.sh 2>/dev/null | awk '{print "    " $NF " (" $5 ")"}'
echo "  Files on rootfs:"
echo "    /etc/infoscreen.env"
echo "    /etc/systemd/system/infoscreen-firstrun.service"
[ -n "$WIFI_SSID" ] && echo "    /etc/NetworkManager/system-connections/$WIFI_SSID.nmconnection"
echo "-------------------------------------------------------"
echo "  Eject SD card -> insert into Pi -> power on"
echo "  Pi will connect, install, and appear in the queue."
echo "======================================================="
echo ""
`;
}

function _screenPcScriptText(v) {
  return `#!/bin/bash
set -e
echo "========================================"
echo "  Event-Admin screen installer (Debian laptop / PC)"
echo "========================================"

[ "$(id -u)" -ne 0 ] && { echo "ERROR: Run as root (sudo)"; exit 1; }

_DEF_SERVER=${v.server}
_DEF_SECRET=${v.secret}
_DEF_HOST=${v.hostname}
_DEF_SSH_USER=${v.sshUser}
_DEF_SSH_PASS=${v.sshPass}
_DEF_LANG=${v.lang}
WIFI_SSID=${v.wifiSsid}
WIFI_PASS=${v.wifiPass}
SERVER="\${INFOSCREEN_URL:-$_DEF_SERVER}"
SECRET="\${PROVISION_SECRET:-$_DEF_SECRET}"
SCREEN_LANG="\${SCREEN_LANG:-$_DEF_LANG}"
HOSTNAME_NEW="\${PI_HOSTNAME:-\${_DEF_HOST:-\$(hostname)}}"
POLL_INTERVAL="\${POLL_INTERVAL:-30}"
SSH_USER="\${SSH_USER:-$_DEF_SSH_USER}"
SSH_PASS="\${SSH_PASS:-$_DEF_SSH_PASS}"

for f in /boot/firmware/infoscreen-provision.env /boot/infoscreen-provision.env ./infoscreen.env /tmp/infoscreen.env; do
    [ -f "$f" ] && { echo "Reading config from $f"; . "$f"; } && break
done

echo "Server:   $SERVER"
echo "Hostname: $HOSTNAME_NEW"
echo "SSH user: $SSH_USER"
echo "WiFi:     \${WIFI_SSID:-<wired>}"

if [ -n "$HOSTNAME_NEW" ]; then
    hostnamectl set-hostname "$HOSTNAME_NEW" 2>/dev/null || echo "$HOSTNAME_NEW" > /etc/hostname
    sed -i "s/127.0.1.1.*/127.0.1.1\\t$HOSTNAME_NEW/" /etc/hosts 2>/dev/null || true
    echo "[1/9] Hostname set: $HOSTNAME_NEW"
fi

# SSH user setup
echo "[2/9] Configuring SSH user: $SSH_USER"
id -u "$SSH_USER" >/dev/null 2>&1 || useradd -m -s /bin/bash "$SSH_USER"
echo "$SSH_USER:$SSH_PASS" | chpasswd
usermod -aG audio,video,input,tty,sudo "$SSH_USER" 2>/dev/null || usermod -aG audio,video,input,tty "$SSH_USER"
# Enable passwordless sudo for the kiosk user
echo "$SSH_USER ALL=(ALL) NOPASSWD:ALL" > /etc/sudoers.d/$SSH_USER
chmod 440 /etc/sudoers.d/$SSH_USER

# Root gets the SAME password as the SSH user, and root SSH is permitted.
# Previously PermitRootLogin was forced to "no", so anyone trying to log in as
# root (the obvious first attempt) was refused no matter what password they had.
# Now both work:  ssh root@<ip>  and  ssh $SSH_USER@<ip>  with $SSH_PASS.
echo "root:$SSH_PASS" | chpasswd 2>/dev/null || true

# Enable and configure SSH. Write the directives idempotently - appending if the
# key is absent - instead of assuming a commented default line is present.
apt-get install -y -qq openssh-server 2>/dev/null || true
systemctl enable ssh 2>/dev/null || systemctl enable sshd 2>/dev/null || true
systemctl start ssh 2>/dev/null || systemctl start sshd 2>/dev/null || true
set_sshd() {
  if grep -qiE "^[#[:space:]]*$1[[:space:]]" /etc/ssh/sshd_config 2>/dev/null; then
    sed -i "s|^[#[:space:]]*$1[[:space:]].*|$1 $2|I" /etc/ssh/sshd_config
  else
    printf '%s %s\\n' "$1" "$2" >> /etc/ssh/sshd_config
  fi
}
set_sshd PasswordAuthentication yes
set_sshd PermitRootLogin yes
systemctl restart ssh 2>/dev/null || systemctl restart sshd 2>/dev/null || true
echo "      SSH ready: ssh root@<ip> or ssh $SSH_USER@<ip> (password: the SSH password)"

if [ -n "$WIFI_SSID" ]; then
    NM_DIR="/etc/NetworkManager/system-connections"
    mkdir -p "$NM_DIR"
    cat > "$NM_DIR/$WIFI_SSID.nmconnection" << WEOF
[connection]
id=$WIFI_SSID
type=wifi
autoconnect=true
[wifi]
ssid=$WIFI_SSID
mode=infrastructure
[wifi-security]
key-mgmt=wpa-psk
psk=$WIFI_PASS
[ipv4]
method=auto
[ipv6]
method=auto
WEOF
    chmod 600 "$NM_DIR/$WIFI_SSID.nmconnection"
    nmcli connection reload 2>/dev/null || true
    echo "[3/9] WiFi configured: $WIFI_SSID"
else
    echo "[3/9] WiFi: skipped (wired)"
fi

echo "[4/9] Waiting for network..."
# Not ICMP-only: outbound pings to public resolvers are dropped on plenty of
# corporate and municipal networks, and this loop then burns its full 60s on a
# machine that is perfectly online.
for i in $(seq 1 30); do
    if ip route show default 2>/dev/null | grep -q default; then
        curl -fsS -m 5 -o /dev/null "$SERVER" 2>/dev/null && break
        getent hosts deb.debian.org >/dev/null 2>&1 && break
        ping -c1 -W3 8.8.8.8 >/dev/null 2>&1 && break
    fi
    sleep 2
done

echo "[5/9] Installing packages..."
export DEBIAN_FRONTEND=noninteractive
# apt-daily runs on the same boot and holds the lists lock. Wait for it, and
# retry rather than proceeding against a half-updated index.
for _try in 1 2 3; do
    apt-get update -qq -o DPkg::Lock::Timeout=120 && break
    echo "  apt-get update failed (attempt $_try/3), retrying in 15s..."
    sleep 15
done
apt-get install -y -qq xinit openbox chromium xdotool curl python3 python3-pip python3-requests \\
    python3-psutil scrot imagemagick unclutter network-manager fonts-dejavu \\
    xserver-xorg xserver-xorg-video-all x11-xserver-utils

pip3 install websocket-client --break-system-packages 2>/dev/null || pip3 install websocket-client

echo "[6/9] Installing the Event-Admin screen agent..."
mkdir -p /opt/infoscreen-agent
curl -fsSL "$SERVER/agent" -o /opt/infoscreen-agent/infoscreen-agent.py
chown -R $SSH_USER:$SSH_USER /opt/infoscreen-agent

cat > /etc/infoscreen.env << EEOF
INFOSCREEN_URL=$SERVER
PROVISION_SECRET=$SECRET
POLL_INTERVAL=$POLL_INTERVAL
PI_HOSTNAME=$HOSTNAME_NEW
SCREEN_LANG=$SCREEN_LANG
EEOF

echo "[7/9] Creating services..."
cat > /etc/systemd/system/infoscreen-agent.service << SEOF
[Unit]
Description=Event-Admin screen agent
After=network-online.target graphical.target
Wants=network-online.target
[Service]
Type=simple
User=$SSH_USER
Environment=DISPLAY=:0
EnvironmentFile=/etc/infoscreen.env
ExecStartPre=/bin/sleep 3
ExecStart=/usr/bin/python3 /opt/infoscreen-agent/infoscreen-agent.py
Restart=always
RestartSec=10
[Install]
WantedBy=multi-user.target
SEOF

echo "[8/9] Configuring auto-login and kiosk..."
mkdir -p /etc/systemd/system/getty@tty1.service.d
cat > /etc/systemd/system/getty@tty1.service.d/autologin.conf << AEOF
[Service]
ExecStart=
ExecStart=-/sbin/agetty --autologin $SSH_USER --noclear %I \\\\\\$TERM
AEOF

cat > /home/$SSH_USER/.xinitrc << 'XEOF'
xset s off; xset s noblank; xset -dpms
unclutter -idle 0.5 -root &
exec openbox-session
XEOF
chown $SSH_USER:$SSH_USER /home/$SSH_USER/.xinitrc

cat > /home/$SSH_USER/.bash_profile << 'BEOF'
if [ -z "$DISPLAY" ] && [ "$(tty)" = "/dev/tty1" ]; then startx -- -nocursor 2>/dev/null; fi
BEOF
chown $SSH_USER:$SSH_USER /home/$SSH_USER/.bash_profile

mkdir -p /etc/X11/xorg.conf.d
cat > /etc/X11/xorg.conf.d/10-monitor.conf << 'MEOF'
Section "ServerFlags"
    Option "BlankTime" "0"
    Option "StandbyTime" "0"
    Option "SuspendTime" "0"
    Option "OffTime" "0"
    Option "DPMS" "false"
EndSection
MEOF

systemctl daemon-reload
systemctl enable infoscreen-agent

echo "[9/9] Done!"
echo ""
echo "========================================"
echo "  Installation complete!"
echo "  Hostname: $HOSTNAME_NEW"
echo "  Server:   $SERVER"
echo "  SSH:      $SSH_USER@$HOSTNAME_NEW"
echo "  Reboot to start kiosk mode."
echo "========================================"
`;
}

// ╔══════════════════════════════════════════════════════════════════════╗
// ║  MODULE: SCREENS                                                     ║
// ║  Screen management with the forked Infoskjerm agent (v4.9.71).       ║
// ║  Event-Admin speaks the agent's device protocol unchanged:           ║
// ║    POST /api/provision · GET /api/provision/poll                     ║
// ║    /api/pi/* (heartbeat, command-ack, log, …) · GET /viewer · /hold  ║
// ║  so the screen-side files stay identical to the field-proven ones.   ║
// ║  The old Node agent (/api/tv-nodes, /api/tv-heartbeat) is untouched. ║
// ╚══════════════════════════════════════════════════════════════════════╝

const SCREENS_FILE         = path.join(DATA, "screens.json");
const SCREEN_QUEUE_FILE    = path.join(DATA, "screen_enroll_queue.json");
const SCREEN_COMMANDS_FILE = path.join(DATA, "screen_commands.json");
const SCREEN_CONFIG_FILE   = path.join(DATA, "screen_config.json");
const SCREEN_LOG_DIR       = path.join(DATA, "screen_logs");
try { fs.mkdirSync(SCREEN_LOG_DIR, { recursive: true }); } catch (e) {}

const SCREEN_ONLINE_MS      = 2 * 60 * 1000;        // no heartbeat for 2 min = offline
const SCREEN_PENDING_TTL_MS = 24 * 3600 * 1000;     // enrollment requests expire after a day
const SCREEN_CMD_STALE_MS   = 20 * 60 * 1000;       // a sent command with no ack is retried
const SCREEN_CMD_EXPIRE_MS  = 7 * 24 * 3600 * 1000; // a command nobody picked up expires
const SCREEN_LOG_MAX        = 1000;
const SCREEN_LANGS          = ["nb", "sv", "en", "da", "fi"];

// Admin command -> how it reaches the agent.
//   bus:  handed out in heartbeat.commands, acknowledged on /api/pi/command-ack
//   flag: a heartbeat field the agent acts on; acknowledged through /api/pi/log
const SCREEN_COMMAND_TYPES = {
  reboot:          { bus: "reboot" },
  refresh:         { bus: "refresh_content" },
  selfcheck:       { bus: "run_selfcheck" },
  agent_update:    { bus: "image_update" },
  apt_upgrade:     { flag: "apt_upgrade" },
  change_password: { flag: "change_password" },
};

// Admin-facing messages (English source, translated on the way out by tr())
Object.assign(TRANSLATIONS, {
  "Screen not found":                         { no: "Fant ikke skjermen",                       sv: "Skärmen hittades inte" },
  "Enrollment request not found":             { no: "Fant ikke innmeldingen",                   sv: "Anmälan hittades inte" },
  "Unknown department":                       { no: "Ukjent avdeling",                          sv: "Okänd avdelning" },
  "Unknown command":                          { no: "Ukjent kommando",                          sv: "Okänt kommando" },
  "A new password is required":               { no: "Nytt passord mangler",                     sv: "Nytt lösenord saknas" },
  "The password must be at least 8 characters": { no: "Passordet må ha minst 8 tegn",           sv: "Lösenordet måste ha minst 8 tecken" },
  "Choose a department":                      { no: "Velg en avdeling",                         sv: "Välj en avdelning" },
  "Command cannot be cancelled now":          { no: "Kommandoen kan ikke avbrytes nå",          sv: "Kommandot kan inte avbrytas nu" },
  "The install link is invalid or has expired": { no: "Installasjonslenken er ugyldig eller utløpt", sv: "Installationslänken är ogiltig eller har gått ut" },
  // Hold screen
  "Waiting for approval":                     { no: "Venter på godkjenning",                    sv: "Väntar på godkännande" },
  "An administrator must approve this screen in Event-Admin (TV → Screens).": { no: "En administrator må godkjenne skjermen i Event-Admin (TV → Skjermer).", sv: "En administratör måste godkänna skärmen i Event-Admin (TV → Skärmar)." },
  "This screen is not registered":            { no: "Skjermen er ikke registrert",              sv: "Skärmen är inte registrerad" },
  "It will register itself again if enrollment is switched on.": { no: "Den melder seg inn på nytt hvis innmelding er slått på.", sv: "Den anmäler sig igen om anmälan är påslagen." },
  "This screen has been removed":             { no: "Skjermen er fjernet",                      sv: "Skärmen har tagits bort" },
  "Contact the administrator of Event-Admin.": { no: "Kontakt administratoren for Event-Admin.", sv: "Kontakta administratören för Event-Admin." },
  "Enrollment was rejected":                  { no: "Innmeldingen ble avvist",                  sv: "Anmälan avvisades" },
  "Approval timed out":                       { no: "Godkjenningen gikk ut på tid",             sv: "Godkännandet tog för lång tid" },
  "Restart the screen to ask again.":         { no: "Start skjermen på nytt for å spørre igjen.", sv: "Starta om skärmen för att fråga igen." },
  "No department yet":                        { no: "Ingen avdeling ennå",                      sv: "Ingen avdelning än" },
  "Choose a department for this screen in Event-Admin (TV → Screens).": { no: "Velg avdeling for skjermen i Event-Admin (TV → Skjermer).", sv: "Välj avdelning för skärmen i Event-Admin (TV → Skärmar)." },
  "Screen name":                              { no: "Skjermnavn",                               sv: "Skärmnamn" },
});

// ── Storage helpers ───────────────────────────────────────────────────
function readScreens()         { var a = readJSON(SCREENS_FILE);         return Array.isArray(a) ? a : []; }
function saveScreens(a)        { writeJSON(SCREENS_FILE, a); }
function readScreenQueue()     { var a = readJSON(SCREEN_QUEUE_FILE);    return Array.isArray(a) ? a : []; }
function saveScreenQueue(a)    { writeJSON(SCREEN_QUEUE_FILE, a); }
function readScreenCommands()  { var a = readJSON(SCREEN_COMMANDS_FILE); return Array.isArray(a) ? a : []; }
function saveScreenCommands(a) { writeJSON(SCREEN_COMMANDS_FILE, a); }

function screenConfig() {
  var c = readJSON(SCREEN_CONFIG_FILE);
  if (!c || Array.isArray(c)) c = {};
  var changed = false;
  if (!c.secret)  { c.secret  = require("crypto").randomBytes(18).toString("base64url"); changed = true; }
  if (!c.signKey) { c.signKey = require("crypto").randomBytes(24).toString("hex");       changed = true; }
  if (typeof c.enabled !== "boolean")     { c.enabled = false;     changed = true; }
  if (typeof c.autoApprove !== "boolean") { c.autoApprove = false; changed = true; }
  if (!Number.isInteger(c.nextCommandId)) { c.nextCommandId = 1;   changed = true; }
  if (changed) writeJSON(SCREEN_CONFIG_FILE, c);
  return c;
}

function _scrHash(t) { return require("crypto").createHash("sha256").update(String(t)).digest("hex"); }
function _scrNewToken() { return require("crypto").randomBytes(32).toString("base64url"); }
function _scrNow() { return new Date().toISOString(); }
function _scrDept(deptId) {
  if (!deptId) return null;
  return (getSettings().departments || []).find(function(d) { return d.id === deptId; }) || null;
}
// Single-quoted for bash: the only character that needs care inside '…' is '
function _shq(v) { return "'" + String(v == null ? "" : v).replace(/'/g, "'\\''") + "'"; }
function _scrHostname(v) { return String(v || "").replace(/[^a-zA-Z0-9-]/g, "").slice(0, 40); }
function _scrLang(v) { v = String(v || "").toLowerCase(); return SCREEN_LANGS.indexOf(v) >= 0 ? v : "nb"; }
function _scrServerUrl(req) {
  var proto = (req.headers["x-forwarded-proto"] || req.protocol || "https").split(",")[0].trim();
  var host  = (req.headers["x-forwarded-host"] || req.headers.host || "").split(",")[0].trim();
  return (proto + "://" + host).replace(/\/+$/, "");
}

// ── Department-scoped enrollment secret ───────────────────────────────
// Same idea as Infoskjerm's lib/enroll.js: <secret>.d<department>.<signature>.
// Every package already writes PROVISION_SECRET and every agent sends it, so
// the department rides along. Editing the department on an SD card breaks the
// signature, and the device then enrolls without a department.
function _scrSig(deptId) {
  return require("crypto").createHmac("sha256", screenConfig().signKey).update("dept:" + deptId).digest("hex").slice(0, 12);
}
function screenScopedSecret(deptId) {
  var base = screenConfig().secret;
  if (!deptId || !_scrDept(deptId)) return base;
  return base + ".d" + Buffer.from(deptId).toString("base64url") + "." + _scrSig(deptId);
}
// -> { ok, deptId, badSig }
function screenParseSecret(given) {
  var expected = screenConfig().secret;
  given = String(given || "");
  if (!expected || !given) return { ok: false };
  if (given === expected) return { ok: true, deptId: null };
  var m = /^([A-Za-z0-9_-]+)\.d([A-Za-z0-9_-]+)\.([0-9a-f]{12})$/.exec(given);
  if (!m || m[1] !== expected) return { ok: false };
  var deptId = "";
  try { deptId = Buffer.from(m[2], "base64url").toString("utf8"); } catch (e) { return { ok: true, deptId: null, badSig: true }; }
  var want = _scrSig(deptId);
  var good = require("crypto").timingSafeEqual(Buffer.from(m[3]), Buffer.from(want));
  if (!good) return { ok: true, deptId: null, badSig: true };
  return { ok: true, deptId: _scrDept(deptId) ? deptId : null };
}

// Bad-secret throttle per address (enrollment is unauthenticated by design)
var _scrBadSecret = new Map();
function _scrNoteBadSecret(ip) {
  var e = _scrBadSecret.get(ip) || { n: 0, at: Date.now() };
  if (Date.now() - e.at > 15 * 60 * 1000) e = { n: 0, at: Date.now() };
  e.n++; _scrBadSecret.set(ip, e);
  return e.n;
}
function _scrObservedIp(req) {
  return clientIp(req);
}

// What a device reports about itself, reduced to plain fields we can show.
function _scrHardware(raw) {
  var h = {};
  if (raw && typeof raw === "object") h = raw;
  else if (typeof raw === "string" && raw.length < 20000) { try { h = JSON.parse(raw); } catch (e) { h = { model: raw.slice(0, 120) }; } }
  if (!h || typeof h !== "object") h = {};
  function s(v, n) { return v == null ? null : String(v).slice(0, n || 120); }
  return {
    model: s(h.model || h.pi_model || h.product), cpu: s(h.cpu), arch: s(h.arch, 20),
    os: s(h.os || h.os_pretty || h.distro), isPc: typeof h.browser_is_pc === "boolean" ? h.browser_is_pc : null,
    gpu: typeof h.browser_gpu_accelerated === "boolean" ? h.browser_gpu_accelerated : null,
    videoPref: ["smooth", "balanced", "quality"].indexOf(h.video_playback_profile) >= 0 ? h.video_playback_profile : null,
  };
}

// Which video version this screen plays. Pi 5 has no H.264 hardware decoder
// and most older laptops decode in software too, so the light 720p30 copy is
// the default unless the browser runs GPU-accelerated on a PC.
function screenVideoProfile(scr) {
  if (scr.videoProfile === "smooth" || scr.videoProfile === "quality") return scr.videoProfile;
  var hw = scr.hardware || {};
  if (hw.videoPref === "quality") return "quality";
  if (hw.videoPref === "smooth") return "smooth";
  return (hw.isPc && hw.gpu) ? "quality" : "smooth";
}

function screenIsOnline(scr) {
  return !!(scr.lastSeen && Date.now() - Date.parse(scr.lastSeen) < SCREEN_ONLINE_MS);
}

// ── Device logs (one file per screen, newest last, capped) ────────────
function _scrLogFile(screenId) { return path.join(SCREEN_LOG_DIR, String(screenId).replace(/[^a-zA-Z0-9-]/g, "") + ".json"); }
function screenLog(screenId, event, detail, at) {
  var f = _scrLogFile(screenId);
  var list = readJSON(f); if (!Array.isArray(list)) list = [];
  list.push({ at: at || _scrNow(), event: String(event || "").slice(0, 80), detail: detail == null ? null : String(detail).slice(0, 2000) });
  if (list.length > SCREEN_LOG_MAX) list.splice(0, list.length - SCREEN_LOG_MAX);
  writeJSON(f, list);
}

// Recent metrics, in memory only (sparkline in the admin)
var _scrMetrics = new Map();
function _scrPushMetrics(screenId, m) {
  var a = _scrMetrics.get(screenId) || [];
  a.push(m); if (a.length > 120) a.shift();
  _scrMetrics.set(screenId, a);
}

// ── Device authentication ─────────────────────────────────────────────
function screenByToken(token) {
  if (!token) return null;
  var h = _scrHash(token);
  return readScreens().find(function(s) { return s.tokenHash === h; }) || null;
}
function screenByViewerKey(vk) {
  if (!vk) return null;
  return readScreens().find(function(s) { return s.viewerKey && s.viewerKey === String(vk); }) || null;
}
function requireScreenToken(req, res, next) {
  var token = req.headers["x-pi-token"];
  if (!token) return res.status(401).json({ error: "Missing token" });
  var scr = screenByToken(String(token));
  if (!scr) return res.status(401).json({ error: "Invalid token" });
  if (scr.revokedAt) return res.status(403).json({ error: "Device revoked", state: "revoked" });
  req.screen = scr;
  next();
}
function _scrUpdate(id, patch) {
  var list = readScreens();
  var i = list.findIndex(function(s) { return s.id === id; });
  if (i < 0) return null;
  Object.assign(list[i], patch);
  saveScreens(list);
  return list[i];
}

function _scrCreate(entry, deptId, approvedBy) {
  var token = _scrNewToken();
  var list = readScreens();
  var short = "scr-" + require("crypto").randomBytes(3).toString("hex");
  var scr = {
    id: uuid(), shortId: short,
    name: entry.hostname || short, hostname: entry.hostname || null,
    installId: entry.installId || null, mac: entry.mac || null,
    deptId: deptId && _scrDept(deptId) ? deptId : null,
    tokenHash: _scrHash(token), viewerKey: require("crypto").randomBytes(24).toString("base64url"),
    videoProfile: "auto", hardware: entry.hardware || {},
    ip: entry.ip || null, observedIp: entry.observedIp || null,
    createdAt: _scrNow(), approvedBy: approvedBy || null, lastSeen: null,
  };
  list.push(scr);
  saveScreens(list);
  screenLog(scr.id, "enrolled", approvedBy ? ("approved by " + approvedBy) : "auto-approved");
  return { screen: scr, token: token };
}

// ── Enrollment: POST /api/provision ───────────────────────────────────
app.post("/api/provision", function(req, res) {
  var b = req.body || {};
  var cfg = screenConfig();
  var observedIp = _scrObservedIp(req);
  if (!cfg.enabled) return res.status(403).json({ error: "Provisioning is disabled" });

  var enroll = screenParseSecret(b.secret);
  if (!enroll.ok) {
    if (_scrNoteBadSecret(observedIp) > 20) { res.setHeader("Retry-After", "900"); return res.status(429).json({ error: "Too many invalid provisioning attempts" }); }
    return res.status(401).json({ error: "Invalid provisioning secret" });
  }
  var hostname = _scrHostname(b.hostname);
  if (!hostname) return res.status(400).json({ error: "hostname required" });
  var installId = String(b.install_id || "").slice(0, 80) || null;
  var mac = String(b.mac_address || "").toLowerCase().slice(0, 40) || null;
  var localIp = typeof b.local_ip === "string" && /^[0-9.]{7,15}$/.test(b.local_ip.trim()) ? b.local_ip.trim() : null;
  var entry = { hostname: hostname, installId: installId, mac: mac, hardware: _scrHardware(b.hardware_info), ip: localIp || observedIp, observedIp: observedIp };

  // Known device that lost its token (re-flashed agent, deleted token file):
  // a fresh token, same screen. A device enrolling for another department
  // than the one it belongs to is refused.
  if (installId) {
    var existing = readScreens().find(function(s) { return s.installId === installId; });
    if (existing && existing.revokedAt) return res.status(403).json({ status: "revoked", message: "This device has been removed by an administrator." });
    if (existing) {
      if (enroll.deptId && existing.deptId && enroll.deptId !== existing.deptId) return res.status(403).json({ error: "Device is outside this enrollment scope" });
      var t = _scrNewToken();
      _scrUpdate(existing.id, { tokenHash: _scrHash(t), hostname: hostname, mac: mac || existing.mac });
      screenLog(existing.id, "re_enrolled", "new token issued to " + hostname);
      return res.json({ status: "already_provisioned", api_token: t, device_id: existing.shortId });
    }
  }

  if (cfg.autoApprove) {
    var made = _scrCreate(entry, enroll.deptId, null);
    var q0 = readScreenQueue();
    q0.push({ id: uuid(), hostname: hostname, installId: installId, mac: mac, hardware: entry.hardware, ip: entry.ip,
              requestedDeptId: enroll.deptId || null, status: "approved", requestedAt: _scrNow(), approvedAt: _scrNow(), screenId: made.screen.id });
    saveScreenQueue(q0);
    return res.json({ status: "approved", api_token: made.token, device_id: made.screen.shortId });
  }

  var q = readScreenQueue();
  _scrExpireQueue(q);
  var bootId = String(b.boot_id || "").trim().slice(0, 64) || null;
  if (installId) {
    var dead = q.filter(function(e) { return e.installId === installId && (e.status === "rejected" || e.status === "expired"); })
               .sort(function(a, c) { return String(c.requestedAt).localeCompare(String(a.requestedAt)); })[0];
    if (dead) {
      var rebooted = bootId && dead.bootId && bootId !== dead.bootId;
      if (!rebooted) {
        saveScreenQueue(q);
        return res.json({ status: dead.status, message: dead.status === "expired"
          ? "Approval was not given within 24 hours. Restart the device to request again."
          : "This device was rejected by an administrator." });
      }
      q = q.filter(function(e) { return e !== dead; });
    }
  }
  var pending = q.find(function(e) { return e.status === "pending" && ((installId && e.installId === installId) || (!installId && e.hostname === hostname)); });
  if (pending) {
    Object.assign(pending, { lastSeenAt: _scrNow(), ip: entry.ip, bootId: bootId || pending.bootId, hardware: entry.hardware });
    if (enroll.deptId) pending.requestedDeptId = enroll.deptId;
  } else {
    q.push({ id: uuid(), hostname: hostname, installId: installId, mac: mac, hardware: entry.hardware, ip: entry.ip, observedIp: observedIp,
             requestedDeptId: enroll.deptId || null, status: "pending", requestedAt: _scrNow(), lastSeenAt: _scrNow(), bootId: bootId });
  }
  saveScreenQueue(q);
  res.json({ status: "pending", message: "Awaiting approval" });
});

function _scrExpireQueue(q) {
  var changed = false;
  q.forEach(function(e) {
    if (e.status === "pending" && Date.now() - Date.parse(e.lastSeenAt || e.requestedAt) > SCREEN_PENDING_TTL_MS) {
      e.status = "expired"; e.rejectedAt = _scrNow(); changed = true;
    }
  });
  // Keep a short history of finished requests, not every one forever
  var finished = q.filter(function(e) { return e.status !== "pending"; });
  if (finished.length > 200) {
    var drop = finished.sort(function(a, c) { return String(a.requestedAt).localeCompare(String(c.requestedAt)); }).slice(0, finished.length - 200);
    drop.forEach(function(d) { var i = q.indexOf(d); if (i >= 0) q.splice(i, 1); });
    changed = true;
  }
  return changed;
}

// GET /api/provision/poll — the agent waits here for the approval
app.get("/api/provision/poll", function(req, res) {
  var enroll = screenParseSecret(req.headers["x-provision-secret"]);
  if (!enroll.ok) return res.status(401).json({ error: "Invalid provisioning secret" });
  var installId = String(req.query.install_id || "");
  var hostname = _scrHostname(req.query.hostname);
  var q = readScreenQueue();
  if (_scrExpireQueue(q)) saveScreenQueue(q);
  var e = q.filter(function(x) { return installId ? x.installId === installId : x.hostname === hostname; })
           .sort(function(a, c) { return String(c.requestedAt).localeCompare(String(a.requestedAt)); })[0];
  if (!e) return res.json({ status: "unknown" });
  if (e.status === "pending") { e.lastSeenAt = _scrNow(); saveScreenQueue(q); return res.json({ status: "pending" }); }
  if (e.status === "approved") {
    // The token stays available until the screen's first heartbeat proves it
    // arrived; a lost poll response is simply answered again.
    if (e.deliverToken) return res.json({ status: "approved", api_token: e.deliverToken });
    return res.json({ status: "already_provisioned" });
  }
  res.json({ status: e.status });
});

// ── Heartbeat ─────────────────────────────────────────────────────────
function _scrNextCommandId() {
  var c = screenConfig();
  var id = c.nextCommandId || 1;
  c.nextCommandId = id + 1;
  writeJSON(SCREEN_CONFIG_FILE, c);
  return id;
}

function _scrMaintainCommands(cmds) {
  var changed = false, now = Date.now();
  cmds.forEach(function(c) {
    if ((c.status === "sent" || c.status === "running") && c.sentAt && now - Date.parse(c.sentAt) > SCREEN_CMD_STALE_MS) {
      if (c.attempts < c.maxAttempts) { c.status = "queued"; c.result = "No answer from the screen – sending again"; }
      else { c.status = "failed"; c.finishedAt = _scrNow(); c.result = "No answer from the screen"; }
      if (c.payload && c.type === "change_password") c.payload = null;
      changed = true;
    }
    if (c.status === "queued" && now - Date.parse(c.createdAt) > SCREEN_CMD_EXPIRE_MS) {
      c.status = "expired"; c.finishedAt = _scrNow(); if (c.type === "change_password") c.payload = null; changed = true;
    }
  });
  // History: keep the last 50 finished commands per screen
  var byScreen = {};
  cmds.forEach(function(c) { if (["done", "failed", "cancelled", "expired"].indexOf(c.status) >= 0) (byScreen[c.screenId] = byScreen[c.screenId] || []).push(c); });
  Object.keys(byScreen).forEach(function(k) {
    var arr = byScreen[k];
    if (arr.length > 50) {
      arr.sort(function(a, b) { return a.id - b.id; }).slice(0, arr.length - 50).forEach(function(old) {
        var i = cmds.indexOf(old); if (i >= 0) cmds.splice(i, 1);
      });
      changed = true;
    }
  });
  return changed;
}

app.post("/api/pi/heartbeat", requireScreenToken, function(req, res) {
  var b = req.body || {};
  var scr = req.screen;
  function num(v) { var n = Number(v); return Number.isFinite(n) ? n : null; }
  var hw = b.hardware_info ? _scrHardware(b.hardware_info) : (scr.hardware || {});
  var metrics = {
    cpuLoad: num(b.cpu_load), cpuTemp: num(b.cpu_temp),
    memUsed: num(b.memory_used), memTotal: num(b.memory_total),
    diskUsed: num(b.disk_used), diskTotal: num(b.disk_total),
    uptime: num(b.uptime), osVersion: b.os_version ? String(b.os_version).slice(0, 80) : null,
    netIface: b.net_iface ? String(b.net_iface).slice(0, 20) : null,
    netSsid: b.net_ssid ? String(b.net_ssid).slice(0, 64) : null,
    aptUpdates: num(b.apt_updates) || 0, rebootRequired: !!b.reboot_required,
    screenW: num(b.screen_width), screenH: num(b.screen_height),
  };
  var firstContact = !scr.lastSeen;
  var updated = _scrUpdate(scr.id, {
    lastSeen: _scrNow(), metrics: metrics, hardware: hw,
    ip: (typeof b.local_ip === "string" ? b.local_ip.slice(0, 45) : null) || scr.ip,
    observedIp: _scrObservedIp(req),
    agentVersion: b.agent_version ? String(b.agent_version).slice(0, 30) : scr.agentVersion,
    agentUser: b.agent_user != null ? String(b.agent_user).slice(0, 30) : scr.agentUser,
    mac: b.mac_address ? String(b.mac_address).toLowerCase().slice(0, 40) : scr.mac,
  }) || scr;
  _scrPushMetrics(scr.id, { at: Date.now(), cpu: metrics.cpuLoad, temp: metrics.cpuTemp });
  if (firstContact) screenLog(scr.id, "first_contact", "agent " + (updated.agentVersion || "?"));

  // The approval token has now demonstrably arrived: stop handing it out.
  var q = readScreenQueue();
  var qe = q.find(function(e) { return e.screenId === scr.id && e.deliverToken; });
  if (qe) { delete qe.deliverToken; saveScreenQueue(q); }

  var dept = _scrDept(updated.deptId);
  var response = {
    content_type: "rotation", rotation: [], layout: "single", settings: {},
    reboot: false, agent_update: false, terminal_requested: false, privileged_exec: null,
    authz: "approved", viewer_key: updated.viewerKey, commands: [],
  };
  if (!dept) { response.hold = "no_department"; response.content_type = "blank"; }

  var cmds = readScreenCommands();
  var changed = _scrMaintainCommands(cmds);
  cmds.filter(function(c) { return c.screenId === scr.id; }).sort(function(a, c) { return a.id - c.id; }).forEach(function(c) {
    var def = SCREEN_COMMAND_TYPES[c.type]; if (!def) return;
    if (def.bus && c.status === "queued" && !response.hold) {
      c.status = "sent"; c.sentAt = _scrNow(); c.attempts = (c.attempts || 0) + 1; changed = true;
      response.commands.push({ id: c.id, type: def.bus, payload: c.payload || {} });
    } else if (def.flag === "apt_upgrade" && (c.status === "queued" || c.status === "sent")) {
      // Repeated until the agent reports apt progress on /api/pi/log
      response.apt_upgrade = true;
      if (c.status === "queued") { c.status = "sent"; c.sentAt = _scrNow(); c.attempts = (c.attempts || 0) + 1; changed = true; }
    } else if (def.flag === "change_password" && c.status === "queued" && c.payload && c.payload.password) {
      // The agent has no acknowledgement for this one: delivered once, then
      // the password is removed from the server for good.
      response.change_password = { user: c.payload.user || "kiosk", password: c.payload.password };
      c.status = "done"; c.sentAt = _scrNow(); c.finishedAt = _scrNow(); c.attempts = 1;
      c.result = "Delivered to the screen"; c.payload = { user: c.payload.user || "kiosk" }; changed = true;
      screenLog(scr.id, "password_change_sent", "user " + (c.payload.user || "kiosk"));
    }
  });
  if (changed) saveScreenCommands(cmds);

  if (updated.identifyUntil) {
    var left = Math.round((Date.parse(updated.identifyUntil) - Date.now()) / 1000);
    if (left > 0) response.identify = { on: true, seconds_left: left };
  }
  res.json(response);
});

// Command acknowledgement from the agent's command bus
app.post("/api/pi/command-ack", requireScreenToken, function(req, res) {
  var b = req.body || {};
  var id = Number(b.id);
  if (!id) return res.status(400).json({ error: "id required" });
  var cmds = readScreenCommands();
  var c = cmds.find(function(x) { return x.id === id && x.screenId === req.screen.id; });
  if (!c) return res.status(404).json({ error: "Unknown command for this device" });
  if (["done", "failed", "cancelled", "expired"].indexOf(c.status) >= 0) return res.json({ ok: true, ignored: true, final_status: c.status });
  var result = String(b.result || "").slice(0, 1000);
  if (b.status === "running") {
    c.status = "running"; c.sentAt = _scrNow(); c.result = result;   // a running ack renews the lease
    saveScreenCommands(cmds);
    return res.json({ ok: true, content_fit: "auto", moving: false });
  }
  var final = b.status === "done" ? "done" : "failed";
  if (final === "failed" && c.attempts < c.maxAttempts) {
    c.status = "queued"; c.result = result;
  } else {
    c.status = final; c.result = result; c.finishedAt = _scrNow();
  }
  saveScreenCommands(cmds);
  screenLog(req.screen.id, "command_" + c.status, c.type + (result ? ": " + result.slice(0, 300) : ""));
  res.json({ ok: true });
});

// Event log from the agent. Some events double as acknowledgements.
app.post("/api/pi/log", requireScreenToken, function(req, res) {
  var b = req.body || {};
  var event = String(b.event || "").slice(0, 80);
  screenLog(req.screen.id, event, b.detail);
  var m = /^apt_(?:update_(start|done|failed)|upgrade_(received|start|progress|error|done|failed))$/.exec(event);
  if (m) {
    var phase = m[1] || m[2];
    var cmds = readScreenCommands();
    var c = cmds.filter(function(x) { return x.screenId === req.screen.id && x.type === "apt_upgrade" && ["queued", "sent", "running"].indexOf(x.status) >= 0; })
                .sort(function(a, b2) { return a.id - b2.id; })[0];
    if (c) {
      if (phase === "done") { c.status = "done"; c.finishedAt = _scrNow(); }
      else if (phase === "failed" || phase === "error") { c.status = "failed"; c.finishedAt = _scrNow(); }
      else { c.status = "running"; c.sentAt = _scrNow(); }
      c.result = b.detail ? String(b.detail).slice(0, 500) : c.result;
      saveScreenCommands(cmds);
    }
  }
  res.json({ ok: true });
});

app.post("/api/pi/logs/bulk", requireScreenToken, function(req, res) {
  var lines = Array.isArray((req.body || {}).lines) ? req.body.lines.slice(0, 300) : [];
  // Journal lines: keep warnings and errors only (priority 0–4); the agent
  // forwards everything, which would push the useful events out of the log.
  var kept = 0;
  lines.forEach(function(l) {
    var pri = parseInt(l && l.pri, 10);
    if (Number.isFinite(pri) && pri > 4) return;
    screenLog(req.screen.id, "journal:" + String((l && l.unit) || "").slice(0, 40), l && l.msg, l && l.ts ? String(l.ts) : null);
    kept++;
  });
  res.json({ ok: true, inserted: kept });
});

app.post("/api/pi/incident", requireScreenToken, function(req, res) {
  var b = req.body || {};
  screenLog(req.screen.id, "incident:" + String(b.kind || b.type || "unknown").slice(0, 40), JSON.stringify(b).slice(0, 1500));
  res.json({ ok: true });
});
app.post("/api/pi/hardware", requireScreenToken, function(req, res) {
  var b = req.body || {};
  _scrUpdate(req.screen.id, { hardwareReport: JSON.stringify(b).slice(0, 20000), hardwareReportAt: _scrNow() });
  res.json({ ok: true });
});
app.post("/api/pi/diagnostics", requireScreenToken, function(req, res) {
  var b = req.body || {};
  var text = typeof b.report === "string" ? b.report : (typeof b.text === "string" ? b.text : JSON.stringify(b));
  _scrUpdate(req.screen.id, { diagnostics: String(text).slice(0, 200000), diagnosticsAt: _scrNow() });
  screenLog(req.screen.id, "diagnostics", String(b.reason || "uploaded").slice(0, 80));
  res.json({ ok: true });
});
// Live frames (the screen's own screenshot): kept in memory, newest only
var _scrFrames = new Map();
app.post("/api/pi/live-frame", requireScreenToken, function(req, res) {
  var b = req.body || {};
  var img = typeof b.frame === "string" ? b.frame : (typeof b.image === "string" ? b.image : "");
  if (img && img.length < 3 * 1024 * 1024) _scrFrames.set(req.screen.id, { at: Date.now(), data: img });
  res.json({ ok: true });
});
// Accepted and ignored: features this fork does not use (USB/tamper, viewer
// reports for the Infoskjerm viewer, server moves, privileged shells).
["/api/pi/tamper", "/api/pi/viewer-report", "/api/pi/move-status", "/api/pi/privileged-result"].forEach(function(p) {
  app.post(p, requireScreenToken, function(req, res) { res.json({ ok: true }); });
});
app.get("/api/pi/whoami", requireScreenToken, function(req, res) {
  res.json({ ok: true, id: req.screen.id, device_id: req.screen.shortId, instance_id: "event-admin" });
});
app.get("/api/pi/config", requireScreenToken, function(req, res) {
  res.json({ ok: true, settings: {}, rotation: [] });
});

// The agent itself (self-update tries GET /agent first, then this)
function _scrAgentSource() { return SCREEN_FILES["infoscreen-agent.py"]; }
function screenAgentVersion() {
  var m = /AGENT_VERSION = '([^']+)'/.exec(_scrAgentSource().slice(0, 4000));
  return m ? m[1] : "?";
}
app.get("/agent", function(req, res) {
  res.type("text/x-python").send(_scrAgentSource());
});
app.get("/api/pi/agent-download", requireScreenToken, function(req, res) {
  res.type("text/x-python");
  res.setHeader("Content-Disposition", 'attachment; filename="infoscreen-agent.py"');
  res.send(_scrAgentSource());
});
// Components: only the kiosk lockdown is served. USB guard, port guard and
// the root update runner are not part of this fork; the agent skips them.
app.get("/api/pi/component/:name", requireScreenToken, function(req, res) {
  if (req.params.name === "harden") return res.type("text/x-shellscript").send(SCREEN_FILES["kiosk/harden-kiosk.sh"]);
  res.status(404).json({ error: "not available" });
});

// Identify: the TV page asks with its viewer key and flashes the screen name
app.get("/api/pi/identify", function(req, res) {
  var scr = screenByViewerKey(req.query.vk);
  if (!scr) return res.status(401).json({ error: "Invalid key" });
  var secs = scr.identifyUntil ? Math.round((Date.parse(scr.identifyUntil) - Date.now()) / 1000) : 0;
  res.json({ identify: secs > 0, seconds_left: Math.max(0, secs), name: scr.name || scr.shortId, device_id: scr.shortId });
});

// ── What the screen's browser opens ───────────────────────────────────
function _scrHoldLang(req) {
  var q = String(req.query.lang || "");
  if (q === "sv" || q === "no" || q === "en") return q;
  var al = String(req.headers["accept-language"] || "").toLowerCase();
  if (/^(nb|nn|no)\b/.test(al)) return "no";
  if (/^sv\b/.test(al)) return "sv";
  return "en";
}
function _scrHoldPage(req, state, hostLabel) {
  var lang = _scrHoldLang(req);
  var s = getSettings();
  var accent = (s.colors && s.colors.accent) || "#FFD100";
  if (!/^#[0-9a-fA-F]{3,8}$/.test(accent)) accent = "#FFD100";
  var texts = {
    pending:        ["Waiting for approval", "An administrator must approve this screen in Event-Admin (TV → Screens)."],
    unknown_device: ["This screen is not registered", "It will register itself again if enrollment is switched on."],
    revoked:        ["This screen has been removed", "Contact the administrator of Event-Admin."],
    rejected:       ["Enrollment was rejected", "Restart the screen to ask again."],
    expired:        ["Approval timed out", "Restart the screen to ask again."],
    no_department:  ["No department yet", "Choose a department for this screen in Event-Admin (TV → Screens)."],
  };
  var t = texts[state] || texts.pending;
  var langAttr = lang === "no" ? "nb" : lang;
  return "<!DOCTYPE html><html lang='" + langAttr + "' translate='no'><head><meta charset='UTF-8'/>"
    + "<meta name='viewport' content='width=device-width,initial-scale=1'/><title>" + escHtml(s.siteName || "Event-Admin") + "</title>"
    + "<style>*{margin:0;padding:0;box-sizing:border-box}html,body{height:100%}"
    + "body{background:#0b0b0d;color:#f2f2f2;font-family:'Helvetica Neue',Arial,sans-serif;display:flex;align-items:center;justify-content:center;text-align:center;cursor:none}"
    + ".w{max-width:70vw}.dot{width:1.2vw;height:1.2vw;border-radius:50%;background:" + accent + ";display:inline-block;margin-bottom:2.2vw;animation:p 2s ease-in-out infinite}"
    + "@keyframes p{0%,100%{opacity:.25}50%{opacity:1}}h1{font-size:3.4vw;font-weight:800;margin-bottom:1.2vw}p{font-size:1.6vw;opacity:.75;line-height:1.5}"
    + ".host{margin-top:3vw;font-family:monospace;font-size:2.4vw;color:" + accent + ";letter-spacing:.05em}"
    + ".site{position:fixed;bottom:2vw;left:0;right:0;font-size:1vw;opacity:.35}</style></head><body><div class='w'>"
    + "<div class='dot'></div><h1>" + escHtml(trLang(t[0], lang)) + "</h1><p>" + escHtml(trLang(t[1], lang)) + "</p>"
    + (hostLabel ? "<div class='host'>" + escHtml(trLang("Screen name", lang)) + ": " + escHtml(hostLabel) + "</div>" : "")
    + "</div><div class='site'>" + escHtml(s.siteName || "Event-Admin") + "</div></body></html>";
}
app.get("/hold", function(req, res) {
  var state = String(req.query.state || "pending").replace(/[^a-z_]/g, "").slice(0, 30);
  res.set("Cache-Control", "no-store");
  res.send(_scrHoldPage(req, state, _scrHostname(req.query.host)));
});
app.get("/viewer", function(req, res) {
  res.set("Cache-Control", "no-store");
  var scr = screenByViewerKey(req.query.vk) || screenByToken(req.query.token);
  if (!scr) return res.send(_scrHoldPage(req, "unknown_device", ""));
  if (scr.revokedAt) return res.send(_scrHoldPage(req, "revoked", scr.hostname));
  var dept = _scrDept(scr.deptId);
  if (!dept) return res.send(_scrHoldPage(req, "no_department", scr.name || scr.hostname));
  res.redirect(302, "/tv/" + encodeURIComponent(dept.id)
    + "?vk=" + encodeURIComponent(scr.viewerKey) + "&profile=" + screenVideoProfile(scr));
});

// ── Admin API ─────────────────────────────────────────────────────────
function _scrVisible(user, scr) {
  if (!user) return false;
  if (user.role === "admin") return true;
  return !!scr.deptId && hasDeptAccess(user, scr.deptId);
}
function _scrQueueVisible(user, e) {
  if (!user) return false;
  if (user.role === "admin") return true;
  return !!e.requestedDeptId && hasDeptAccess(user, e.requestedDeptId);
}
function _scrPublic(scr, cmds) {
  var mine = cmds.filter(function(c) { return c.screenId === scr.id; });
  var open = mine.filter(function(c) { return ["queued", "sent", "running"].indexOf(c.status) >= 0; });
  var last = mine.filter(function(c) { return ["done", "failed", "expired", "cancelled"].indexOf(c.status) >= 0; })
                 .sort(function(a, b) { return b.id - a.id; })[0] || null;
  var dept = _scrDept(scr.deptId);
  return {
    id: scr.id, shortId: scr.shortId, name: scr.name, hostname: scr.hostname,
    deptId: scr.deptId, deptName: dept ? (dept.displayName || dept.name) : null,
    online: screenIsOnline(scr), lastSeen: scr.lastSeen, createdAt: scr.createdAt,
    ip: scr.ip, observedIp: scr.observedIp, mac: scr.mac,
    agentVersion: scr.agentVersion || null, agentUser: scr.agentUser || null,
    metrics: scr.metrics || {}, hardware: scr.hardware || {},
    videoProfile: scr.videoProfile || "auto", effectiveVideoProfile: screenVideoProfile(scr),
    identifying: !!(scr.identifyUntil && Date.parse(scr.identifyUntil) > Date.now()),
    hasDiagnostics: !!scr.diagnostics, diagnosticsAt: scr.diagnosticsAt || null,
    hasFrame: _scrFrames.has(scr.id),
    openCommands: open.map(function(c) { return { id: c.id, type: c.type, status: c.status, createdAt: c.createdAt, attempts: c.attempts, result: c.result || null }; }),
    lastCommand: last ? { id: last.id, type: last.type, status: last.status, finishedAt: last.finishedAt, result: last.result || null } : null,
    sparkline: (_scrMetrics.get(scr.id) || []).slice(-30).map(function(m) { return m.cpu; }),
  };
}

app.get("/api/screens", auth, managerOrAdmin, function(req, res) {
  var u = req.session.user;
  var cfg = screenConfig();
  var q = readScreenQueue();
  if (_scrExpireQueue(q)) saveScreenQueue(q);
  var cmds = readScreenCommands();
  var screens = readScreens().filter(function(s) { return _scrVisible(u, s); })
    .map(function(s) { return _scrPublic(s, cmds); })
    .sort(function(a, b) { return String(a.deptName || "").localeCompare(String(b.deptName || "")) || String(a.name).localeCompare(String(b.name)); });
  var queue = q.filter(function(e) { return e.status === "pending" && _scrQueueVisible(u, e); }).map(function(e) {
    var d = _scrDept(e.requestedDeptId);
    return { id: e.id, hostname: e.hostname, mac: e.mac, ip: e.ip, hardware: e.hardware || {}, requestedDeptId: e.requestedDeptId,
             requestedDeptName: d ? (d.displayName || d.name) : null, requestedAt: e.requestedAt, lastSeenAt: e.lastSeenAt };
  });
  res.json({
    screens: screens, queue: queue,
    agentVersion: screenAgentVersion(),
    config: u.role === "admin" ? { enabled: cfg.enabled, autoApprove: cfg.autoApprove, secret: cfg.secret } : { enabled: cfg.enabled, autoApprove: cfg.autoApprove },
  });
});

app.put("/api/screens/config", auth, adminOnly, function(req, res) {
  var c = screenConfig();
  if (typeof req.body.enabled === "boolean") c.enabled = req.body.enabled;
  if (typeof req.body.autoApprove === "boolean") c.autoApprove = req.body.autoApprove;
  writeJSON(SCREEN_CONFIG_FILE, c);
  res.json({ ok: true, enabled: c.enabled, autoApprove: c.autoApprove });
});
// A new base secret invalidates every SD card and install link made before,
// but not screens that are already enrolled (they use their own token).
app.post("/api/screens/config/new-secret", auth, adminOnly, function(req, res) {
  var c = screenConfig();
  c.secret = require("crypto").randomBytes(18).toString("base64url");
  writeJSON(SCREEN_CONFIG_FILE, c);
  res.json({ ok: true, secret: c.secret });
});

function _scrFindVisible(req, res) {
  var scr = readScreens().find(function(s) { return s.id === req.params.id; });
  if (!scr || !_scrVisible(req.session.user, scr)) { res.status(404).json({ error: tr("Screen not found", req) }); return null; }
  return scr;
}

app.put("/api/screens/:id", auth, managerOrAdmin, function(req, res) {
  var scr = _scrFindVisible(req, res); if (!scr) return;
  var b = req.body || {}, patch = {};
  if (typeof b.name === "string" && b.name.trim()) patch.name = b.name.trim().slice(0, 60);
  if (b.deptId !== undefined) {
    if (b.deptId && !_scrDept(b.deptId)) return res.status(400).json({ error: tr("Unknown department", req) });
    if (b.deptId && !hasDeptAccess(req.session.user, b.deptId)) return res.status(403).json({ error: st("no_access_department", req) });
    if (!b.deptId && req.session.user.role !== "admin") return res.status(400).json({ error: tr("Choose a department", req) });
    patch.deptId = b.deptId || null;
  }
  if (b.videoProfile !== undefined) patch.videoProfile = ["auto", "smooth", "quality"].indexOf(b.videoProfile) >= 0 ? b.videoProfile : "auto";
  var updated = _scrUpdate(scr.id, patch);
  if (patch.deptId !== undefined && patch.deptId !== scr.deptId) {
    screenLog(scr.id, "department_changed", (scr.deptId || "-") + " → " + (patch.deptId || "-") + " by " + req.session.user.email);
    // A screen already showing a department reloads its viewer so the change shows at once
    _scrQueueCommand(scr.id, "refresh", null, req.session.user.email);
  } else if (patch.videoProfile !== undefined && patch.videoProfile !== scr.videoProfile) {
    _scrQueueCommand(scr.id, "refresh", null, req.session.user.email);
  }
  var cmds = readScreenCommands();
  res.json({ ok: true, screen: _scrPublic(updated, cmds) });
});

app.delete("/api/screens/:id", auth, managerOrAdmin, function(req, res) {
  var scr = _scrFindVisible(req, res); if (!scr) return;
  // Removed, not just hidden: the token stops working at once and the
  // screen shows the "removed" hold screen on its next heartbeat.
  var list = readScreens().filter(function(s) { return s.id !== scr.id; });
  saveScreens(list);
  var cmds = readScreenCommands().filter(function(c) { return c.screenId !== scr.id; });
  saveScreenCommands(cmds);
  _scrFrames.delete(scr.id); _scrMetrics.delete(scr.id);
  console.log("[screens] " + req.session.user.email + " removed screen " + scr.shortId + " (" + scr.name + ")");
  res.json({ ok: true });
});

function _scrQueueCommand(screenId, type, payload, by) {
  var cmds = readScreenCommands();
  // One open command of a kind per screen: pressing twice does not reboot twice
  var open = cmds.find(function(c) { return c.screenId === screenId && c.type === type && ["queued", "sent", "running"].indexOf(c.status) >= 0; });
  if (open && type !== "change_password") return open;
  if (open) { open.status = "cancelled"; open.finishedAt = _scrNow(); open.payload = null; }
  var c = { id: _scrNextCommandId(), screenId: screenId, type: type, payload: payload || null, status: "queued",
            attempts: 0, maxAttempts: type === "agent_update" ? 2 : 3, createdAt: _scrNow(), createdBy: by || null,
            sentAt: null, finishedAt: null, result: null };
  cmds.push(c);
  saveScreenCommands(cmds);
  return c;
}

app.post("/api/screens/:id/commands", auth, managerOrAdmin, function(req, res) {
  var scr = _scrFindVisible(req, res); if (!scr) return;
  var type = String((req.body || {}).type || "");
  var by = req.session.user.email;
  if (type === "identify") {
    _scrUpdate(scr.id, { identifyUntil: new Date(Date.now() + 60 * 1000).toISOString() });
    screenLog(scr.id, "identify", "by " + by);
    return res.json({ ok: true, identify: true });
  }
  if (!SCREEN_COMMAND_TYPES[type]) return res.status(400).json({ error: tr("Unknown command", req) });
  var payload = null;
  if (type === "change_password") {
    var pw = String((req.body || {}).password || "");
    var user = _scrHostname((req.body || {}).user) || "kiosk";
    if (!pw) return res.status(400).json({ error: tr("A new password is required", req) });
    if (pw.length < 8) return res.status(400).json({ error: tr("The password must be at least 8 characters", req) });
    payload = { user: user, password: pw.slice(0, 128) };
  }
  var c = _scrQueueCommand(scr.id, type, payload, by);
  screenLog(scr.id, "command_queued", type + " by " + by);
  res.json({ ok: true, command: { id: c.id, type: c.type, status: c.status } });
});

app.post("/api/screens/commands/:cmdId/cancel", auth, managerOrAdmin, function(req, res) {
  var cmds = readScreenCommands();
  var c = cmds.find(function(x) { return x.id === Number(req.params.cmdId); });
  var scr = c && readScreens().find(function(s) { return s.id === c.screenId; });
  if (!c || !scr || !_scrVisible(req.session.user, scr)) return res.status(404).json({ error: tr("Screen not found", req) });
  if (c.status !== "queued") return res.status(409).json({ error: tr("Command cannot be cancelled now", req) });
  c.status = "cancelled"; c.finishedAt = _scrNow(); c.payload = null;
  saveScreenCommands(cmds);
  res.json({ ok: true });
});

app.get("/api/screens/:id/logs", auth, managerOrAdmin, function(req, res) {
  var scr = _scrFindVisible(req, res); if (!scr) return;
  var list = readJSON(_scrLogFile(scr.id)); if (!Array.isArray(list)) list = [];
  var cmds = readScreenCommands().filter(function(c) { return c.screenId === scr.id; })
    .sort(function(a, b) { return b.id - a.id; }).slice(0, 30)
    .map(function(c) { return { id: c.id, type: c.type, status: c.status, createdAt: c.createdAt, createdBy: c.createdBy, finishedAt: c.finishedAt, attempts: c.attempts, result: c.result }; });
  res.json({ logs: list.slice(-300).reverse(), commands: cmds });
});

app.get("/api/screens/:id/diagnostics", auth, managerOrAdmin, function(req, res) {
  var scr = _scrFindVisible(req, res); if (!scr) return;
  res.type("text/plain").send(scr.diagnostics || "");
});

app.post("/api/screens/queue/:qid/approve", auth, managerOrAdmin, function(req, res) {
  var q = readScreenQueue();
  var e = q.find(function(x) { return x.id === req.params.qid && x.status === "pending"; });
  if (!e || !_scrQueueVisible(req.session.user, e)) return res.status(404).json({ error: tr("Enrollment request not found", req) });
  var deptId = (req.body || {}).deptId !== undefined ? ((req.body || {}).deptId || null) : e.requestedDeptId;
  if (deptId && !_scrDept(deptId)) return res.status(400).json({ error: tr("Unknown department", req) });
  if (deptId && !hasDeptAccess(req.session.user, deptId)) return res.status(403).json({ error: st("no_access_department", req) });
  if (!deptId && req.session.user.role !== "admin") return res.status(400).json({ error: tr("Choose a department", req) });
  var made = _scrCreate({ hostname: e.hostname, installId: e.installId, mac: e.mac, hardware: e.hardware, ip: e.ip, observedIp: e.observedIp }, deptId, req.session.user.email);
  var name = String((req.body || {}).name || "").trim();
  if (name) _scrUpdate(made.screen.id, { name: name.slice(0, 60) });
  Object.assign(e, { status: "approved", approvedAt: _scrNow(), approvedBy: req.session.user.email, screenId: made.screen.id, deliverToken: made.token });
  saveScreenQueue(q);
  res.json({ ok: true, screenId: made.screen.id });
});

app.post("/api/screens/queue/:qid/reject", auth, managerOrAdmin, function(req, res) {
  var q = readScreenQueue();
  var e = q.find(function(x) { return x.id === req.params.qid && x.status === "pending"; });
  if (!e || !_scrQueueVisible(req.session.user, e)) return res.status(404).json({ error: tr("Enrollment request not found", req) });
  Object.assign(e, { status: "rejected", rejectedAt: _scrNow(), rejectedBy: req.session.user.email });
  saveScreenQueue(q);
  res.json({ ok: true });
});

// ── Install packages ──────────────────────────────────────────────────
function _scrCheckDeptForPackage(req, res, deptId) {
  var u = req.session.user;
  if (deptId && !_scrDept(deptId)) { res.status(400).json({ error: tr("Unknown department", req) }); return false; }
  if (deptId && !hasDeptAccess(u, deptId)) { res.status(403).json({ error: st("no_access_department", req) }); return false; }
  if (!deptId && u.role !== "admin") { res.status(400).json({ error: tr("Choose a department", req) }); return false; }
  return true;
}

// Small in-memory ZIP (deflate) for the SD package
function _scrZip(files) {
  var zlib = require("zlib");
  var locals = [], centrals = [], offset = 0;
  var dt = _zipDosTime(new Date());
  Object.keys(files).forEach(function(name) {
    var data = Buffer.isBuffer(files[name]) ? files[name] : Buffer.from(String(files[name]), "utf8");
    var comp = zlib.deflateRawSync(data, { level: 9 });
    var crc = _crc32Update(0, data);
    var nameBuf = Buffer.from(name, "utf8");
    var lh = Buffer.alloc(30);
    lh.writeUInt32LE(0x04034b50, 0); lh.writeUInt16LE(20, 4); lh.writeUInt16LE(0x0800, 6); lh.writeUInt16LE(8, 8);
    lh.writeUInt16LE(dt.time, 10); lh.writeUInt16LE(dt.date, 12); lh.writeUInt32LE(crc, 14);
    lh.writeUInt32LE(comp.length, 18); lh.writeUInt32LE(data.length, 22); lh.writeUInt16LE(nameBuf.length, 26); lh.writeUInt16LE(0, 28);
    var ch = Buffer.alloc(46);
    ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(0x031e, 4); ch.writeUInt16LE(20, 6); ch.writeUInt16LE(0x0800, 8); ch.writeUInt16LE(8, 10);
    ch.writeUInt16LE(dt.time, 12); ch.writeUInt16LE(dt.date, 14); ch.writeUInt32LE(crc, 16);
    ch.writeUInt32LE(comp.length, 20); ch.writeUInt32LE(data.length, 24); ch.writeUInt16LE(nameBuf.length, 28);
    ch.writeUInt16LE(0, 30); ch.writeUInt16LE(0, 32); ch.writeUInt16LE(0, 34); ch.writeUInt16LE(0, 36);
    ch.writeUInt32LE(((/\.(sh|py)$/.test(name) ? 0o100755 : 0o100644) << 16) >>> 0, 38); ch.writeUInt32LE(offset, 42);
    locals.push(lh, nameBuf, comp);
    centrals.push(ch, nameBuf);
    offset += lh.length + nameBuf.length + comp.length;
  });
  var cd = Buffer.concat(centrals);
  var end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(Object.keys(files).length, 8); end.writeUInt16LE(Object.keys(files).length, 10);
  end.writeUInt32LE(cd.length, 12); end.writeUInt32LE(offset, 16);
  return Buffer.concat(locals.concat([cd, end]));
}

function _scrEnvFile(server, secret, hostname, interval, lang) {
  return [
    "# Event-Admin screen agent configuration",
    "INFOSCREEN_URL=" + server,
    "PROVISION_SECRET=" + secret,
    "POLL_INTERVAL=" + interval,
    hostname ? "PI_HOSTNAME=" + hostname : "",
    "SCREEN_LANG=" + lang,
    "BROWSER=",
    "DISPLAY=:0",
  ].filter(Boolean).join("\n") + "\n";
}

// SD-card configurator for Raspberry Pi 5 (run on Linux with the fresh card mounted)
app.get("/api/screens/sd-script", auth, managerOrAdmin, function(req, res) {
  var deptId = String(req.query.deptId || "") || null;
  if (!_scrCheckDeptForPackage(req, res, deptId)) return;
  var hostname = _scrHostname(req.query.hostname);
  var script = _screenSdScriptText({
    hostname: _shq(hostname), server: _shq(_scrServerUrl(req)), interval: _shq("15"),
    secret: _shq(screenScopedSecret(deptId)), wifiSsid: _shq(String(req.query.wifiSsid || "").slice(0, 64)),
    wifiPass: _shq(String(req.query.wifiPass || "").slice(0, 128)), lang: _shq(_scrLang(req.query.lang)),
    stage0: SCREEN_FILES["infoscreen-stage0.sh"], firstrun: SCREEN_FILES["firstrun-infoscreen.sh"],
    diag: SCREEN_FILES["infoscreen-collect-diagnostics.sh"],
  });
  res.setHeader("Content-Type", "application/x-shellscript");
  res.setHeader("Content-Disposition", 'attachment; filename="configure-sd' + (hostname ? "-" + hostname : "") + '.sh"');
  res.send(script);
});

// The package the configurator puts on the card. Public, but only with a
// valid enrollment secret (it is what the card writer downloads).
app.get("/api/screens/sd-package", function(req, res) {
  var enroll = screenParseSecret(req.query.secret);
  if (!enroll.ok || enroll.badSig) return res.status(403).json({ error: "Invalid provision secret" });
  var hostname = _scrHostname(req.query.hostname);
  var interval = Math.max(5, Math.min(120, parseInt(req.query.interval, 10) || 15));
  var files = {
    "infoscreen-agent.py": SCREEN_FILES["infoscreen-agent.py"],
    "install-agent.sh": SCREEN_FILES["install-agent.sh"],
    "kiosk/harden-kiosk.sh": SCREEN_FILES["kiosk/harden-kiosk.sh"],
    "infoscreen.env": _scrEnvFile(_scrServerUrl(req), String(req.query.secret), hostname, interval, _scrLang(req.query.lang)),
  };
  if (hostname) files.hostname = hostname + "\n";
  res.setHeader("Content-Type", "application/zip");
  res.setHeader("Content-Disposition", 'attachment; filename="infoscreen-pi-' + (hostname || "agent") + '.zip"');
  res.send(_scrZip(files));
});

// Laptops: a one-line install for Debian 12/13. The link carries a short-lived
// key; passwords stay on the server instead of in the command line.
var _scrInstallKeys = new Map();
app.post("/api/screens/pc-install-key", auth, managerOrAdmin, function(req, res) {
  var b = req.body || {};
  var deptId = String(b.deptId || "") || null;
  if (!_scrCheckDeptForPackage(req, res, deptId)) return;
  var sshPass = String(b.sshPass || "");
  if (sshPass.length < 8) return res.status(400).json({ error: tr("The password must be at least 8 characters", req) });
  var key = require("crypto").randomBytes(24).toString("hex");
  var expires = Date.now() + 2 * 3600 * 1000;
  for (var e of _scrInstallKeys) if (e[1].expires < Date.now()) _scrInstallKeys.delete(e[0]);
  _scrInstallKeys.set(key, {
    expires: expires, deptId: deptId, hostname: _scrHostname(b.hostname),
    sshUser: _scrHostname(b.sshUser) || "kiosk", sshPass: sshPass.slice(0, 128),
    wifiSsid: String(b.wifiSsid || "").slice(0, 64), wifiPass: String(b.wifiPass || "").slice(0, 128),
    lang: _scrLang(b.lang), by: req.session.user.email,
  });
  var url = _scrServerUrl(req) + "/api/screens/pc-install-script?key=" + key;
  res.json({ ok: true, key: key, expiresAt: new Date(expires).toISOString(), command: "curl -fsSL '" + url + "' | sudo bash" });
});
app.get("/api/screens/pc-install-script", function(req, res) {
  var k = _scrInstallKeys.get(String(req.query.key || ""));
  if (!k || k.expires < Date.now()) {
    return res.status(401).type("text/plain").send('echo ' + _shq(tr("The install link is invalid or has expired", req)) + ' >&2; exit 1\n');
  }
  res.setHeader("Content-Type", "text/plain");
  res.setHeader("Content-Disposition", 'attachment; filename="event-admin-screen-install.sh"');
  res.send(_screenPcScriptText({
    server: _shq(_scrServerUrl(req)), secret: _shq(screenScopedSecret(k.deptId)), hostname: _shq(k.hostname),
    sshUser: _shq(k.sshUser), sshPass: _shq(k.sshPass), wifiSsid: _shq(k.wifiSsid), wifiPass: _shq(k.wifiPass), lang: _shq(k.lang),
  }));
});

// Self-check at start: a broken embedded script would only show up on a Pi
(function verifyScreenFilesAtStartup() {
  var problems = [];
  ["infoscreen-agent.py", "install-agent.sh", "firstrun-infoscreen.sh", "infoscreen-stage0.sh", "infoscreen-collect-diagnostics.sh", "kiosk/harden-kiosk.sh"].forEach(function(n) {
    var s = SCREEN_FILES[n];
    if (!s || s.length < 200) problems.push(n + " missing");
    else if (n.endsWith(".sh") && !/^#!/.test(s)) problems.push(n + " has no shebang");
  });
  if (problems.length) console.error("[screens] Embedded screen files are broken: " + problems.join(", "));
  else console.log("[screens] Screen agent " + screenAgentVersion() + " ready (forked from InfoScreen-Agent 4.9.71)");
})();
