const TV_AGENT_JS = `#!/usr/bin/env node
/*
 * Event-Admin TV-node agent
 * ─────────────────────────
 * Runs as a systemd service on the Raspberry Pi (or any kiosk box).
 * Exposes a small local HTTP API over the Tailscale interface so
 * Event-Admin's server can read status and issue commands.
 *
 * Every request must include header:  X-Agent-Token: <token>
 * The token is generated at install time and stored in /etc/tv-agent/token.
 */

const http = require("http");
const os = require("os");
const fs = require("fs");
const { exec, execFile } = require("child_process");

const CONFIG_DIR = "/etc/tv-agent";
const TOKEN_FILE = CONFIG_DIR + "/token";
const URL_FILE   = CONFIG_DIR + "/kiosk-url";
const PATHS_FILE = CONFIG_DIR + "/paths.json";
const PREVIOUS_URL_FILE = CONFIG_DIR + "/kiosk-url.before-identify";
const PORT = 9191;

function readTrim(path, fallback) {
  try { return fs.readFileSync(path, "utf8").trim(); } catch (e) { return fallback; }
}

const AGENT_TOKEN = readTrim(TOKEN_FILE, null);
if (!AGENT_TOKEN) {
  console.error("No token found at " + TOKEN_FILE + " — run install.sh first.");
  process.exit(1);
}

// Resolved binary paths (written by install.sh — these vary across distros,
// e.g. reboot is often a symlink to systemctl rather than a real /sbin/reboot).
let BIN_PATHS = { reboot: "/usr/sbin/reboot", chpasswd: "/usr/sbin/chpasswd", systemctl: "/usr/bin/systemctl" };
try {
  const raw = fs.readFileSync(PATHS_FILE, "utf8");
  BIN_PATHS = Object.assign(BIN_PATHS, JSON.parse(raw));
} catch (e) {
  console.warn("Could not read " + PATHS_FILE + " — using fallback binary paths. Re-run install.sh to fix.");
}

function sendJson(res, code, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(code, { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) });
  res.end(body);
}

function getUptimeSeconds() { return Math.floor(os.uptime()); }

function getTemperature(cb) {
  // Raspberry Pi thermal zone — present on Pi OS / Ubuntu for Pi
  fs.readFile("/sys/class/thermal/thermal_zone0/temp", "utf8", function (err, data) {
    if (err) return cb(null);
    const milliC = parseInt(data.trim(), 10);
    if (isNaN(milliC)) return cb(null);
    cb(Math.round(milliC / 100) / 10); // one decimal place
  });
}

function getDiskFree(cb) {
  exec("df -h / --output=avail,pcent | tail -1", function (err, stdout) {
    if (err) return cb(null);
    const parts = stdout.trim().split(/\\s+/);
    cb({ avail: parts[0] || null, usedPercent: parts[1] || null });
  });
}

function getMemory() {
  const total = os.totalmem();
  const free = os.freemem();
  return {
    totalMB: Math.round(total / 1024 / 1024),
    freeMB: Math.round(free / 1024 / 1024),
    usedPercent: Math.round(((total - free) / total) * 100),
  };
}

function getKioskUrl() { return readTrim(URL_FILE, null); }

function handleStatus(req, res) {
  getTemperature(function (tempC) {
    getDiskFree(function (disk) {
      const identifying = !!_identifyTimer;
      const realUrl = identifying ? readTrim(PREVIOUS_URL_FILE, getKioskUrl()) : getKioskUrl();
      sendJson(res, 200, {
        ok: true,
        hostname: os.hostname(),
        uptimeSeconds: getUptimeSeconds(),
        loadAvg: os.loadavg(),
        memory: getMemory(),
        disk: disk,
        tempC: tempC,
        kioskUrl: realUrl,
        identifying: identifying,
        agentVersion: "1.0.0",
        now: new Date().toISOString(),
      });
    });
  });
}

function handleReboot(req, res) {
  sendJson(res, 200, { ok: true, message: "Reboot scheduled" });
  // Small delay so the HTTP response actually reaches the server before the box goes down
  setTimeout(function () { exec("sudo " + BIN_PATHS.reboot); }, 800);
}

function handleSetUrl(req, res, body) {
  let parsed;
  try { parsed = JSON.parse(body); } catch (e) { return sendJson(res, 400, { ok: false, error: "Invalid JSON" }); }
  const url = (parsed.url || "").trim();
  if (!url || !/^https?:\\/\\//i.test(url)) {
    return sendJson(res, 400, { ok: false, error: "url must start with http:// or https://" });
  }
  // Manual URL change cancels any in-progress identify countdown — otherwise
  // the timer would silently overwrite this URL a moment later.
  clearIdentifyTimer();
  try {
    fs.writeFileSync(URL_FILE, url + "\\n");
  } catch (e) {
    return sendJson(res, 500, { ok: false, error: "Could not write kiosk URL file" });
  }
  // Ask the kiosk-watcher (installed alongside) to reload the browser to the new URL.
  // The watcher script polls URL_FILE and re-execs chromium when it changes — see install.sh.
  exec("sudo " + BIN_PATHS.systemctl + " restart tv-kiosk.service", function (err) {
    sendJson(res, 200, { ok: true, message: "URL updated, kiosk restarting", url: url });
  });
}

let _identifyTimer = null;

function clearIdentifyTimer() {
  if (_identifyTimer) { clearTimeout(_identifyTimer); _identifyTimer = null; }
}

function restartKiosk(cb) {
  exec("sudo " + BIN_PATHS.systemctl + " restart tv-kiosk.service", function (err) {
    if (cb) cb(err);
  });
}

function handleIdentify(req, res, body) {
  let parsed;
  try { parsed = JSON.parse(body); } catch (e) { return sendJson(res, 400, { ok: false, error: "Invalid JSON" }); }
  const identifyUrl = (parsed.identifyUrl || "").trim();
  const durationSeconds = Math.max(10, Math.min(600, parseInt(parsed.durationSeconds, 10) || 120));
  if (!identifyUrl || !/^https?:\\/\\//i.test(identifyUrl)) {
    return sendJson(res, 400, { ok: false, error: "identifyUrl must start with http:// or https://" });
  }

  // Cancel any identify already in progress (re-triggering just restarts the countdown).
  clearIdentifyTimer();

  // Save whatever the kiosk is currently showing so we can restore it —
  // but only if we're not already mid-identify (avoid saving the identify
  // page itself as the "previous" URL on a re-trigger).
  let previousUrl = getKioskUrl();
  try {
    const saved = readTrim(PREVIOUS_URL_FILE, null);
    if (saved && previousUrl && previousUrl.indexOf("/tv-identify/") === -1) {
      fs.writeFileSync(PREVIOUS_URL_FILE, previousUrl + "\\n");
    } else if (!saved) {
      fs.writeFileSync(PREVIOUS_URL_FILE, (previousUrl || "") + "\\n");
    }
    // else: already mid-identify, keep the previously saved original URL as-is
  } catch (e) {}

  fs.writeFileSync(URL_FILE, identifyUrl + "\\n");

  // Schedule the revert FIRST, unconditionally — even if the restart command
  // below fails for some reason, we never want the kiosk permanently stuck
  // showing the identify page with no way back.
  _identifyTimer = setTimeout(function () {
    _identifyTimer = null;
    const restoreUrl = readTrim(PREVIOUS_URL_FILE, null);
    if (restoreUrl) {
      try { fs.writeFileSync(URL_FILE, restoreUrl + "\\n"); } catch (e) {}
    }
    restartKiosk(function () {});
  }, durationSeconds * 1000);

  restartKiosk(function (err) {
    if (err) return sendJson(res, 500, { ok: false, error: "Could not restart kiosk (will still auto-revert in " + durationSeconds + "s)" });
    sendJson(res, 200, { ok: true, message: "Identify shown for " + durationSeconds + "s", durationSeconds: durationSeconds });
  });
}

function handleChangePassword(req, res, body) {
  let parsed;
  try { parsed = JSON.parse(body); } catch (e) { return sendJson(res, 400, { ok: false, error: "Invalid JSON" }); }
  const newPassword = (parsed.newPassword || "");
  if (newPassword.length < 8) {
    return sendJson(res, 400, { ok: false, error: "Password must be at least 8 characters" });
  }
  const user = os.userInfo().username;
  // chpasswd reads "user:password" from stdin — avoids putting the password in argv/process list
  const child = execFile("sudo", [BIN_PATHS.chpasswd], function (err, stdout, stderr) {
    if (err) return sendJson(res, 500, { ok: false, error: "Password change failed: " + (stderr || err.message) });
    sendJson(res, 200, { ok: true, message: "Password updated for user " + user });
  });
  child.stdin.write(user + ":" + newPassword + "\\n");
  child.stdin.end();
}

function handleSoftReset(req, res) {
  // Clears agent identity (token, node-id, kiosk URL) so the Pi can be
  // re-registered to a new slot without touching the OS or software.
  // The agent service keeps running but enters "pending" state.
  try {
    fs.writeFileSync(URL_FILE, "about:blank\\n");
    fs.writeFileSync(CONFIG_DIR + "/node-id", "\\n");
    // Stop the kiosk browser so the screen goes blank
    exec("sudo " + BIN_PATHS.systemctl + " stop tv-kiosk.service", function () {});
  } catch (e) {
    return sendJson(res, 500, { ok: false, error: "Reset failed: " + e.message });
  }
  sendJson(res, 200, { ok: true, message: "Soft reset complete — agent is pending re-registration." });
}

function handleHardReset(req, res) {
  // Removes everything installed by install.sh:
  //  - tv-kiosk.service (stopped + disabled + deleted)
  //  - tv-agent.service (stopped + disabled)
  //  - autologin override for getty@tty1
  //  - .xinitrc and .bash_profile kiosk entries
  //  - /etc/tv-agent/ config directory
  //  - /opt/tv-agent/ agent directory
  // Tailscale is left intact (it was installed independently).
  // Respond FIRST — agent will be gone before we could respond otherwise.
  sendJson(res, 200, { ok: true, message: "Hard reset initiated — agent will stop in 2s." });

  setTimeout(function () {
    var agentUser = "pi";
    try { agentUser = require("fs").readFileSync(CONFIG_DIR + "/agent-user", "utf8").trim(); } catch (e) {}

    var cmds = [
      "systemctl stop tv-kiosk.service 2>/dev/null || true",
      "systemctl disable tv-kiosk.service 2>/dev/null || true",
      "rm -f /etc/systemd/system/tv-kiosk.service",
      "rm -f /etc/systemd/system/getty@tty1.service.d/override.conf",
      "rmdir /etc/systemd/system/getty@tty1.service.d 2>/dev/null || true",
      "systemctl daemon-reload",
      "systemctl reset-failed 2>/dev/null || true",
      // Remove kiosk entries from .bash_profile and .xinitrc
      "sed -i '/tv-agent kiosk autostart/,/fi/d' /home/" + agentUser + "/.bash_profile 2>/dev/null || true",
      "rm -f /home/" + agentUser + "/.xinitrc",
      // Remove config and agent files
      "rm -rf /etc/tv-agent",
      "rm -rf /opt/tv-agent",
      "rm -f /etc/sudoers.d/tv-agent",
      // Stop and disable agent service last
      "systemctl stop tv-agent.service 2>/dev/null || true",
      "systemctl disable tv-agent.service 2>/dev/null || true",
      "rm -f /etc/systemd/system/tv-agent.service",
      "systemctl daemon-reload",
    ].join(" && ");

    exec("sudo bash -c '" + cmds.replace(/'/g, "'\\\\''") + "'", function (err) {
      // Agent process exits naturally once its config is gone
      process.exit(0);
    });
  }, 2000);
}


function handleUpdateAgent(req, res, body) {
  var parsed;
  try { parsed = JSON.parse(body); } catch (e) {
    return sendJson(res, 400, { ok: false, error: "Invalid JSON" });
  }
  var agentUrl = (parsed.agentUrl || "").trim();
  if (!agentUrl) return sendJson(res, 400, { ok: false, error: "Missing agentUrl" });

  var agentPath = __filename;
  var tmpPath = agentPath + ".update.tmp";

  // Fetch the new agent.js from the server using this node's own token
  var token = readTrim(TOKEN_FILE, "");
  var urlParsed = require("url").parse(agentUrl);
  var proto = urlParsed.protocol === "https:" ? require("https") : require("http");
  var reqOpts = {
    hostname: urlParsed.hostname,
    port: urlParsed.port || (urlParsed.protocol === "https:" ? 443 : 80),
    path: urlParsed.path,
    method: "GET",
    headers: { "X-Agent-Token": token },
  };

  var fetchReq = proto.request(reqOpts, function (fetchRes) {
    if (fetchRes.statusCode !== 200) {
      return sendJson(res, 502, { ok: false, error: "Server returned HTTP " + fetchRes.statusCode });
    }
    var chunks = [];
    fetchRes.on("data", function (c) { chunks.push(c); });
    fetchRes.on("end", function () {
      var content = Buffer.concat(chunks);
      try {
        fs.writeFileSync(tmpPath, content);
        fs.renameSync(tmpPath, agentPath);
      } catch (e) {
        try { fs.unlinkSync(tmpPath); } catch (e2) {}
        return sendJson(res, 500, { ok: false, error: "Write failed: " + e.message });
      }
      sendJson(res, 200, { ok: true, message: "Agent updated (" + content.length + " bytes) — restarting in 1s" });
      setTimeout(function () {
        exec("sudo " + BIN_PATHS.systemctl + " restart tv-agent.service", function () {});
      }, 1000);
    });
  });
  fetchReq.on("error", function (e) { sendJson(res, 502, { ok: false, error: "Fetch failed: " + e.message }); });
  fetchReq.end();
}

function handleSetupKiosk(req, res) {
  // Re-runs the kiosk setup without reinstalling Node.js or the agent.
  // Useful when: kiosk service is missing, first install was agent-only,
  // or you need to reconfigure autologin/Chromium after a fresh OS install.
  const agentUser = (function() {
    try { return require("fs").readFileSync("/etc/tv-agent/agent-user", "utf8").trim(); } catch(e) {}
    return "pi";
  })();

  const chromiumBin = (function() {
    for (const b of ["/usr/bin/chromium-browser", "/usr/bin/chromium", "/snap/bin/chromium"]) {
      try { require("fs").accessSync(b, require("fs").constants.X_OK); return b; } catch (e) {}
    }
    return null;
  })();

  if (!chromiumBin) {
    return sendJson(res, 500, { ok: false, error: "Chromium not found on this device — install it first" });
  }

  const kioskServiceName = "tv-kiosk.service";

  const serviceUnit = [
    "[Unit]",
    "Description=TV kiosk browser",
    "After=graphical.target",
    "",
    "[Service]",
    "Type=simple",
    "User=" + agentUser,
    "Environment=DISPLAY=:0",
    "ExecStart=/bin/sh -c '" + chromiumBin + " --kiosk --noerrdialogs --disable-infobars --disable-session-crashed-bubble --disable-features=TranslateUI --check-for-update-interval=31536000 --autoplay-policy=no-user-gesture-required \\"$(cat " + CONFIG_DIR + "/kiosk-url)\\"'",
    "Restart=always",
    "RestartSec=3",
    "",
    "[Install]",
    "WantedBy=graphical.target",
  ].join("\\n");

  const autologinConf = [
    "[Service]",
    "ExecStart=",
    "ExecStart=-/sbin/agetty --autologin " + agentUser + " --noclear %I $TERM",
  ].join("\\n");

  const xinitrc = [
    "#!/bin/sh",
    "xset -dpms",
    "xset s off",
    "xset s noblank",
    "unclutter -idle 0.5 -root &",
    "openbox-session &",
    "sleep 2",
    "exec systemctl start --no-block " + kioskServiceName,
  ].join("\\n");

  const bashProfileAppend = "\\n# tv-agent kiosk autostart\\nif [ -z \\"$DISPLAY\\" ] && [ \\"$(tty)\\" = \\"/dev/tty1\\" ]; then\\n  exec startx\\nfi\\n";

  try {
    const fs = require("fs");
    fs.mkdirSync("/etc/systemd/system", { recursive: true });
    fs.writeFileSync("/etc/systemd/system/" + kioskServiceName, serviceUnit);
    fs.mkdirSync("/etc/systemd/system/getty@tty1.service.d", { recursive: true });
    fs.writeFileSync("/etc/systemd/system/getty@tty1.service.d/override.conf", autologinConf);
    const xinitrcPath = "/home/" + agentUser + "/.xinitrc";
    fs.writeFileSync(xinitrcPath, xinitrc);
    fs.chmodSync(xinitrcPath, 0o755);
    const profilePath = "/home/" + agentUser + "/.bash_profile";
    const existingProfile = fs.existsSync(profilePath) ? fs.readFileSync(profilePath, "utf8") : "";
    if (!existingProfile.includes("tv-agent kiosk autostart")) {
      fs.appendFileSync(profilePath, bashProfileAppend);
    }
  } catch (e) {
    return sendJson(res, 500, { ok: false, error: "File write failed: " + e.message });
  }

  exec("systemctl daemon-reload && systemctl enable tv-kiosk.service", function (err) {
    if (err) return sendJson(res, 500, { ok: false, error: "systemctl failed: " + err.message });
    sendJson(res, 200, { ok: true, message: "Kiosk setup complete — reboot to start.", chromiumBin: chromiumBin });
  });
}

const server = http.createServer(function (req, res) {
  const token = req.headers["x-agent-token"];
  if (token !== AGENT_TOKEN) {
    return sendJson(res, 401, { ok: false, error: "Invalid or missing X-Agent-Token" });
  }

  if (req.method === "GET" && req.url === "/status") {
    return handleStatus(req, res);
  }
  if (req.method === "GET" && req.url.startsWith("/cache/")) {
    return handleCacheServe(req, res);
  }
  if (req.method === "POST" && req.url === "/reboot") {
    return handleReboot(req, res);
  }

  let body = "";
  req.on("data", function (chunk) { body += chunk; if (body.length > 1e5) req.destroy(); });
  req.on("end", function () {
    if (req.method === "POST" && req.url === "/set-url") return handleSetUrl(req, res, body);
    if (req.method === "POST" && req.url === "/identify") return handleIdentify(req, res, body);
    if (req.method === "POST" && req.url === "/change-password") return handleChangePassword(req, res, body);
    if (req.method === "POST" && req.url === "/setup-kiosk") return handleSetupKiosk(req, res);
    if (req.method === "POST" && req.url === "/update-agent") return handleUpdateAgent(req, res, body);
    if (req.method === "POST" && req.url === "/soft-reset") return handleSoftReset(req, res);
    if (req.method === "POST" && req.url === "/hard-reset") return handleHardReset(req, res);
    sendJson(res, 404, { ok: false, error: "Unknown endpoint" });
  });
});

server.listen(PORT, "0.0.0.0", function () {
  console.log("tv-agent listening on :" + PORT);
});

// ── Video Cache — pre-downloads videos and serves from RAM/disk ──
const CACHE_RAM = "/dev/shm/tv-cache";
const CACHE_DISK = "/var/cache/tv-agent";
const _videoCache = {}; // url -> localPath

function getCacheDir() {
  try {
    const stats = fs.statfsSync ? fs.statfsSync("/dev/shm") : null;
    if (stats) {
      const freeBytes = stats.bavail * stats.bsize;
      if (freeBytes > 100 * 1024 * 1024) {
        try { fs.mkdirSync(CACHE_RAM, { recursive: true }); } catch(e) {}
        return CACHE_RAM;
      }
    }
  } catch(e) {}
  try { fs.mkdirSync(CACHE_DISK, { recursive: true }); } catch(e) {}
  return CACHE_DISK;
}

function cacheFilename(url) {
  const crypto2 = require("crypto");
  const ext = require("path").extname(url.split("?")[0]) || ".mp4";
  return crypto2.createHash("md5").update(url).digest("hex") + ext;
}

function handleCacheServe(req, res) {
  const encoded = req.url.slice("/cache/".length);
  const url = decodeURIComponent(encoded);
  const localPath = _videoCache[url];
  if (localPath && fs.existsSync(localPath)) {
    const stat = fs.statSync(localPath);
    const ext = require("path").extname(localPath).toLowerCase();
    const mime = { ".mp4": "video/mp4", ".webm": "video/webm", ".mov": "video/quicktime" }[ext] || "application/octet-stream";
    res.writeHead(200, { "Content-Type": mime, "Content-Length": stat.size, "Cache-Control": "public, max-age=3600" });
    fs.createReadStream(localPath).pipe(res);
  } else {
    sendJson(res, 404, { error: "Not cached" });
  }
}

function downloadVideo(url, cb) {
  if (_videoCache[url] && fs.existsSync(_videoCache[url])) return cb(null, _videoCache[url]);
  const cacheDir = getCacheDir();
  const localPath = require("path").join(cacheDir, cacheFilename(url));
  console.log("[cache] Downloading: " + url);
  const urlParsed = require("url").parse(url);
  const proto = urlParsed.protocol === "https:" ? require("https") : require("http");
  const fileStream = fs.createWriteStream(localPath);
  const req = proto.get(url, function(resp) {
    if (resp.statusCode !== 200) { fileStream.close(); try { fs.unlinkSync(localPath); } catch(e) {} return cb("HTTP " + resp.statusCode); }
    resp.pipe(fileStream);
    fileStream.on("finish", function() {
      fileStream.close();
      const sizeMB = (fs.statSync(localPath).size / 1024 / 1024).toFixed(1);
      console.log("[cache] Cached: " + url + " (" + sizeMB + " MB, " + (cacheDir === CACHE_RAM ? "RAM" : "disk") + ")");
      _videoCache[url] = localPath;
      cb(null, localPath);
    });
  });
  req.on("error", function(e) { try { fs.unlinkSync(localPath); } catch(e2) {} cb(e.message); });
  req.setTimeout(120000, function() { req.destroy(); });
}

// Pre-cache videos from the kiosk URL page
function precacheVideos() {
  const kioskUrl = getKioskUrl();
  if (!kioskUrl) return;
  // Fetch the TV page and extract mp4 URLs
  const urlParsed = require("url").parse(kioskUrl);
  const proto = urlParsed.protocol === "https:" ? require("https") : require("http");
  const req = proto.get(kioskUrl, function(resp) {
    if (resp.statusCode !== 200) return;
    let body = "";
    resp.on("data", function(c) { body += c; });
    resp.on("end", function() {
      // Find mp4 URLs in the page content (in slide data)
      const mp4s = [];
      const re = /"url":"(https?:[^"]*\\.mp4[^"]*)"/gi;
      let m;
      while ((m = re.exec(body)) !== null) {
        mp4s.push(m[1].replace(/\\\\/g, ""));
      }
      if (mp4s.length) {
        console.log("[cache] Found " + mp4s.length + " video(s) to pre-cache");
        mp4s.forEach(function(url) { downloadVideo(url, function(){}); });
      }
    });
  });
  req.on("error", function(){}); req.setTimeout(30000, function(){ req.destroy(); });
}

// Run pre-cache after startup and every 30 minutes
setTimeout(precacheVideos, 15000);
setInterval(precacheVideos, 30 * 60 * 1000);

// ── HTTP Heartbeat — report metrics to Event-Admin server ──────────
const SERVER_URL_FILE = CONFIG_DIR + "/server-url";
const HB_SERVER = readTrim(SERVER_URL_FILE, null);
const HB_INTERVAL = 30000;

// Job log buffer — collects stdout/stderr from tracked commands, flushed with each heartbeat
var _jobLogBuffer = []; // [ { jobId, lines[], status? } ]

function trackCommand(jobId, cmd, opts) {
  if (!jobId) { exec(cmd, opts || {}); return; }
  var logEntry = { jobId: jobId, lines: [], status: null };
  _jobLogBuffer.push(logEntry);
  logEntry.lines.push("[agent] Starter: " + cmd.substring(0, 120));
  logEntry.status = "running";
  var child = exec(cmd, Object.assign({ maxBuffer: 10 * 1024 * 1024 }, opts || {}));
  child.stdout.on("data", function(d) {
    d.toString().split("\\n").forEach(function(ln) { if (ln) logEntry.lines.push(ln); });
  });
  child.stderr.on("data", function(d) {
    d.toString().split("\\n").forEach(function(ln) { if (ln) logEntry.lines.push("[stderr] " + ln); });
  });
  child.on("close", function(code) {
    logEntry.lines.push("[agent] Avsluttet med kode " + code);
    logEntry.status = (code === 0) ? "done" : "failed";
    // Flush immediately so the popup gets the result without waiting for next heartbeat
    flushJobLogsNow();
  });
  return child;
}

function flushJobLogs() {
  if (!_jobLogBuffer.length) return [];
  var out = _jobLogBuffer.map(function(entry) {
    var chunk = { jobId: entry.jobId, lines: entry.lines.splice(0), status: entry.status };
    return chunk;
  });
  // Remove completed entries that have been flushed
  _jobLogBuffer = _jobLogBuffer.filter(function(entry) {
    return entry.status !== "done" && entry.status !== "failed";
  });
  return out;
}

// Immediate flush to server — used before agent restart so logs aren't lost
function flushJobLogsNow(cb) {
  var logs = flushJobLogs();
  if (!logs.length || !HB_SERVER) { if (cb) cb(); return; }
  var payload = JSON.stringify({ jobLogs: logs });
  var urlParsed = require("url").parse(HB_SERVER + "/api/tv-job-logs");
  var proto = urlParsed.protocol === "https:" ? require("https") : require("http");
  var req = proto.request({
    hostname: urlParsed.hostname, port: urlParsed.port || (urlParsed.protocol === "https:" ? 443 : 80),
    path: urlParsed.path, method: "POST", timeout: 5000,
    headers: { "X-Agent-Token": AGENT_TOKEN, "Content-Type": "application/json", "Content-Length": Buffer.byteLength(payload) },
  }, function (resp) {
    resp.on("data", function(){});
    resp.on("end", function(){ if (cb) cb(); });
  });
  req.on("error", function(){ if (cb) cb(); });
  req.on("timeout", function(){ req.destroy(); if (cb) cb(); });
  req.write(payload); req.end();
}

function checkAptUpdates(cb) {
  exec("apt-get -s dist-upgrade 2>/dev/null | grep '^Inst ' | wc -l", function (err, stdout) {
    var count = parseInt((stdout || "").trim(), 10) || 0;
    var reboot = false;
    try { reboot = fs.existsSync("/var/run/reboot-required"); } catch(e) {}
    cb(count, reboot);
  });
}

function getNetInfo(cb) {
  exec("ip route show default 2>/dev/null | head -1", function (err, stdout) {
    var iface = null, ip = null, ssid = null;
    if (stdout) { var m = stdout.match(/dev\\s+(\\S+)/); if (m) iface = m[1]; }
    if (iface) {
      exec("ip -4 addr show " + iface + " | grep inet | head -1", function (e2, out2) {
        if (out2) { var m2 = out2.match(/inet\\s+([\\d.]+)/); if (m2) ip = m2[1]; }
        if (iface && iface.startsWith("wlan")) {
          exec("iwgetid " + iface + " -r 2>/dev/null", function (e3, out3) { cb(iface, ip, (out3||"").trim()||null); });
        } else { cb(iface, ip, null); }
      });
    } else { cb(null, null, null); }
  });
}

function doHeartbeat() {
  if (!HB_SERVER) return;
  getTemperature(function (tempC) {
    getDiskFree(function (disk) {
      getNetInfo(function (iface, ip, ssid) {
        checkAptUpdates(function (aptCount, rebootReq) {
          var mem = getMemory();
          var jobLogs = flushJobLogs();
          var payload = JSON.stringify({
            hostname: os.hostname(), cpuLoad: os.loadavg()[0], cpuTemp: tempC,
            memoryUsed: mem.totalMB - mem.freeMB, memoryTotal: mem.totalMB,
            diskUsed: disk ? disk.usedPercent : null, diskTotal: disk ? disk.avail : null,
            uptime: getUptimeSeconds(), osVersion: os.release(), agentVersion: "2.4.3",
            netIface: iface, netSsid: ssid, localIp: ip, aptUpdates: aptCount, rebootRequired: rebootReq,
            jobLogs: jobLogs.length ? jobLogs : undefined,
          });
          var urlParsed = require("url").parse(HB_SERVER + "/api/tv-heartbeat");
          var proto = urlParsed.protocol === "https:" ? require("https") : require("http");
          var req = proto.request({
            hostname: urlParsed.hostname, port: urlParsed.port || (urlParsed.protocol === "https:" ? 443 : 80),
            path: urlParsed.path, method: "POST", timeout: 15000,
            headers: { "X-Agent-Token": AGENT_TOKEN, "Content-Type": "application/json", "Content-Length": Buffer.byteLength(payload) },
          }, function (resp) {
            var chunks = [];
            resp.on("data", function (c) { chunks.push(c); });
            resp.on("end", function () {
              try {
                var data = JSON.parse(Buffer.concat(chunks).toString());
                if (data.reboot) { console.log("[hb] reboot"); setTimeout(function(){ exec("sudo "+BIN_PATHS.reboot); },2000); }
                if (data.aptUpgrade) { console.log("[hb] apt upgrade"); trackCommand(data.aptUpgradeJobId, "sudo apt-get update && sudo apt-get dist-upgrade -y 2>&1"); }
                if (data.agentUpdate && data.agentUrl) {
                  console.log("[hb] agent update");
                  var _auJobId = data.agentUpdateJobId;
                  if (_auJobId) {
                    var _auEntry = { jobId: _auJobId, lines: ["[agent] Laster ned ny agent fra server..."], status: "running" };
                    _jobLogBuffer.push(_auEntry);
                    // Override handleUpdateAgent's restart to flush logs first
                    var _origExec = exec;
                    var _auRes = {
                      writeHead: function(){},
                      end: function(body) {
                        try {
                          var r = JSON.parse(body || "{}");
                          _auEntry.lines.push("[agent] " + (r.message || r.error || "Oppdatering fullført"));
                          _auEntry.status = r.ok ? "done" : "failed";
                        } catch(e) { _auEntry.lines.push("[agent] Svar mottatt"); _auEntry.status = "done"; }
                        // Flush logs to server before agent restarts
                        flushJobLogsNow(function() {
                          console.log("[hb] job logs flushed, restarting agent");
                        });
                      }
                    };
                    handleUpdateAgent(null, _auRes, JSON.stringify({agentUrl: data.agentUrl}));
                  } else {
                    handleUpdateAgent(null,{writeHead:function(){},end:function(){}},JSON.stringify({agentUrl:data.agentUrl}));
                  }
                }
                if (data.terminalRequested) { console.log("[hb] terminal"); startHttpTerminal(); }
                if (data.wifiProfiles) { console.log("[hb] wifi"); applyWifiProfiles(data.wifiProfiles); }
                if (data.changePassword && data.changePassword.password) {
                  console.log("[hb] password change for " + (data.changePassword.user || "pi"));
                  exec("echo '" + (data.changePassword.user || "pi") + ":" + data.changePassword.password + "' | sudo chpasswd", function(err) {
                    console.log("[hb] password " + (err ? "FAILED: " + err.message : "changed OK"));
                  });
                }
                if (data.setUrl) {
                  console.log("[hb] set kiosk URL: " + data.setUrl);
                  try { require("fs").writeFileSync(CONFIG_DIR + "/kiosk-url", data.setUrl.trim() + "\\n"); } catch(e) {}
                  // Restart chromium to load new URL
                  exec("pkill -f chromium 2>/dev/null; sleep 2; pkill -9 -f chromium 2>/dev/null", function() {
                    console.log("[hb] chromium restarted for new URL");
                  });
                }
                if (data.setHostname) {
                  console.log("[hb] set hostname: " + data.setHostname);
                  exec("sudo hostnamectl set-hostname " + JSON.stringify(data.setHostname), function(err) {
                    console.log("[hb] hostname " + (err ? "FAILED: " + err.message : "set to " + data.setHostname));
                  });
                }
              } catch(e) {}
            });
          });
          req.on("error", function(){}); req.on("timeout", function(){req.destroy();}); req.write(payload); req.end();
        });
      });
    });
  });
}

function startHttpTerminal() {
  if (!HB_SERVER) return;
  var urlP = require("url").parse(HB_SERVER+"/api/tv-terminal/connect");
  var pr=(urlP.protocol==="https:"?require("https"):require("http"));
  var p=JSON.stringify({});
  var r=pr.request({hostname:urlP.hostname,port:urlP.port||(urlP.protocol==="https:"?443:80),path:urlP.path,method:"POST",timeout:10000,
    headers:{"X-Agent-Token":AGENT_TOKEN,"Content-Type":"application/json","Content-Length":Buffer.byteLength(p)}},function(resp){
    var ch=[];resp.on("data",function(c){ch.push(c);});resp.on("end",function(){
      try{var data=JSON.parse(Buffer.concat(ch).toString());if(!data.ok)return;
        var pty=require("child_process").spawn("/bin/bash",["-l"],{env:Object.assign({},process.env,{TERM:"xterm-256color"}),stdio:["pipe","pipe","pipe"]});
        function sOut(t){var pp=JSON.stringify({sessionId:data.sessionId,data:t});var u=require("url").parse(HB_SERVER+"/api/tv-terminal/output");var pr2=(u.protocol==="https:"?require("https"):require("http"));var r2=pr2.request({hostname:u.hostname,port:u.port||(u.protocol==="https:"?443:80),path:u.path,method:"POST",headers:{"X-Agent-Token":AGENT_TOKEN,"Content-Type":"application/json","Content-Length":Buffer.byteLength(pp)},timeout:5000});r2.on("error",function(){});r2.write(pp);r2.end();}
        pty.stdout.on("data",function(d){sOut(d.toString());});pty.stderr.on("data",function(d){sOut(d.toString());});
        var pt=setInterval(function(){var u=require("url").parse(HB_SERVER+"/api/tv-terminal/input?sessionId="+data.sessionId);var pr2=(u.protocol==="https:"?require("https"):require("http"));var r2=pr2.request({hostname:u.hostname,port:u.port||(u.protocol==="https:"?443:80),path:u.path,method:"GET",headers:{"X-Agent-Token":AGENT_TOKEN},timeout:5000});r2.on("response",function(r3){var c2=[];r3.on("data",function(c){c2.push(c);});r3.on("end",function(){try{var d=JSON.parse(Buffer.concat(c2).toString());if(d.closed){pty.kill();clearInterval(pt);return;}if(d.input)pty.stdin.write(d.input);}catch(e){}});});r2.on("error",function(){});r2.end();},150);
        pty.on("exit",function(){clearInterval(pt);});
      }catch(e){console.error("[terminal]",e.message);}
    });
  });r.on("error",function(e){console.error("[terminal]",e.message);});r.write(p);r.end();
}

function applyWifiProfiles(profiles) {
  profiles.forEach(function(p){if(!p.ssid)return;
    var cmd=p.password?"sudo nmcli connection add type wifi ifname wlan0 con-name '"+p.ssid+"' ssid '"+p.ssid+"' wifi-sec.key-mgmt wpa-psk wifi-sec.psk '"+p.password+"' connection.autoconnect yes 2>/dev/null || sudo nmcli connection modify '"+p.ssid+"' wifi-sec.psk '"+p.password+"' 2>/dev/null":"sudo nmcli connection add type wifi ifname wlan0 con-name '"+p.ssid+"' ssid '"+p.ssid+"' connection.autoconnect yes 2>/dev/null";
    exec(cmd,function(e){console.log("[wifi] "+(e?"Failed: ":"OK: ")+p.ssid);});
  });
}

if (HB_SERVER) { console.log("HTTP heartbeat -> " + HB_SERVER); setTimeout(doHeartbeat,5000); setInterval(doHeartbeat,HB_INTERVAL); }
else { console.log("No server-url — SSH-only mode"); }

`;

const TV_AGENT_INSTALL_SH = `#!/usr/bin/env bash
# Event-Admin TV-node agent — installer
# Run as: sudo bash install.sh
#
# Two ways to run this:
#  1. Via the one-line command from Event-Admin -> TV-kanal -> Enheter
#     (sets TV_AGENT_TOKEN / TV_AGENT_NODE_ID / TV_AGENT_SERVER env vars
#     automatically — this is the recommended path, it links the device
#     and sets up the kiosk browser pointed at the right department URL).
#  2. Manually: sudo bash install.sh
#     (agent-only install, generates its own token, no kiosk setup —
#     use this if you already have a working kiosk browser and just
#     want remote management added on top, as before.)
set -euo pipefail

if [ "$EUID" -ne 0 ]; then
  echo "Please run as root: sudo bash install.sh"
  exit 1
fi

AGENT_USER="\${SUDO_USER:-$(logname 2>/dev/null || echo kiosk)}"
CONFIG_DIR="/etc/tv-agent"
INSTALL_DIR="/opt/tv-agent"
KIOSK_SERVICE_NAME="tv-kiosk.service"
LINKED_INSTALL=false
if [ -n "\${TV_AGENT_TOKEN:-}" ] && [ -n "\${TV_AGENT_NODE_ID:-}" ] && [ -n "\${TV_AGENT_SERVER:-}" ]; then
  LINKED_INSTALL=true
fi

echo "── Event-Admin TV-node agent installer ──"
echo "Installing for user: $AGENT_USER"
if [ "$LINKED_INSTALL" = true ]; then
  echo "Mode: linked install (device pre-registered in Event-Admin)"
else
  echo "Mode: standalone install (agent only, no kiosk setup)"
fi
echo

# 0. Ensure Node.js is present (clean Debian/Ubuntu/Pi OS installs won't have it)
if ! command -v node >/dev/null 2>&1; then
  echo "Node.js not found — installing via NodeSource (Node 20 LTS)..."
  apt-get update -qq
  apt-get install -y -qq curl ca-certificates >/dev/null
  curl -fsSL https://deb.nodesource.com/setup_20.x | bash - >/dev/null
  apt-get install -y -qq nodejs
  echo "Node.js installed: $(node -v)"
else
  echo "Node.js already present: $(node -v)"
fi
echo

mkdir -p "$CONFIG_DIR"
mkdir -p "$INSTALL_DIR"

# 1. Agent token: either supplied by Event-Admin (linked install) or
#    generated locally (standalone install, kept stable across re-runs).
if [ "$LINKED_INSTALL" = true ]; then
  TOKEN="$TV_AGENT_TOKEN"
  echo "$TOKEN" > "$CONFIG_DIR/token"
  echo "$TV_AGENT_NODE_ID" > "$CONFIG_DIR/node-id"
  echo "$TV_AGENT_SERVER" > "$CONFIG_DIR/server-url"
  echo "Using token + device ID supplied by Event-Admin."
elif [ ! -f "$CONFIG_DIR/token" ]; then
  TOKEN=$(head -c 32 /dev/urandom | base64 | tr -dc 'a-zA-Z0-9' | head -c 40)
  echo "$TOKEN" > "$CONFIG_DIR/token"
  echo "Generated new agent token."
else
  TOKEN=$(cat "$CONFIG_DIR/token")
  echo "Using existing agent token."
fi
chmod 644 "$CONFIG_DIR/token"

# 2. Copy the agent script
cp "$(dirname "$0")/agent.js" "$INSTALL_DIR/agent.js"
chmod 755 "$INSTALL_DIR/agent.js"

# 3. Default kiosk URL file — overwritten below for linked installs once we
#    fetch the real department URL; kept as-is on re-runs otherwise.
if [ ! -f "$CONFIG_DIR/kiosk-url" ]; then
  echo "https://example.ddos.nu" > "$CONFIG_DIR/kiosk-url"
fi

# 4. Resolve actual binary paths — these vary across distros (e.g. reboot is
#    often a symlink to systemctl at /usr/sbin/reboot, not /sbin/reboot).
REBOOT_BIN="$(command -v reboot)"
CHPASSWD_BIN="$(command -v chpasswd)"
SYSTEMCTL_BIN="$(command -v systemctl)"
if [ -z "$REBOOT_BIN" ] || [ -z "$CHPASSWD_BIN" ] || [ -z "$SYSTEMCTL_BIN" ]; then
  echo "Could not resolve reboot/chpasswd/systemctl on PATH — aborting."
  exit 1
fi
echo "Resolved: reboot=$REBOOT_BIN  chpasswd=$CHPASSWD_BIN  systemctl=$SYSTEMCTL_BIN"

cat > "$CONFIG_DIR/paths.json" <<EOF
{"reboot":"$REBOOT_BIN","chpasswd":"$CHPASSWD_BIN","systemctl":"$SYSTEMCTL_BIN"}
EOF
chmod 644 "$CONFIG_DIR/paths.json"

# Sudoers rule — allow the agent (running as AGENT_USER) to reboot and run chpasswd
# WITHOUT a password prompt, but restricted to exactly these resolved binaries.
SUDOERS_FILE="/etc/sudoers.d/tv-agent"
cat > "$SUDOERS_FILE" <<EOF
$AGENT_USER ALL=(root) NOPASSWD: $REBOOT_BIN
$AGENT_USER ALL=(root) NOPASSWD: $CHPASSWD_BIN
$AGENT_USER ALL=(root) NOPASSWD: $SYSTEMCTL_BIN restart $KIOSK_SERVICE_NAME
$AGENT_USER ALL=(root) NOPASSWD: $SYSTEMCTL_BIN restart tv-agent.service
$AGENT_USER ALL=(root) NOPASSWD: $SYSTEMCTL_BIN daemon-reload
$AGENT_USER ALL=(root) NOPASSWD: $SYSTEMCTL_BIN enable $KIOSK_SERVICE_NAME
EOF
chmod 440 "$SUDOERS_FILE"
visudo -c -f "$SUDOERS_FILE" >/dev/null || { echo "sudoers syntax check failed — aborting"; rm -f "$SUDOERS_FILE"; exit 1; }

# 5. systemd service for the agent itself
NODE_BIN="$(command -v node)"
cat > /etc/systemd/system/tv-agent.service <<EOF
[Unit]
Description=Event-Admin TV-node agent
After=network-online.target tailscaled.service
Wants=network-online.target

[Service]
Type=simple
User=$AGENT_USER
ExecStart=$NODE_BIN $INSTALL_DIR/agent.js
Restart=always
RestartSec=3
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
EOF

systemctl daemon-reload
systemctl enable tv-agent.service
systemctl restart tv-agent.service

# 6. Determine Tailscale IP (used both for the printout and, on linked
#    installs, reported back to Event-Admin so the device record fills
#    itself in automatically).
TS_IP=""
if command -v tailscale >/dev/null 2>&1; then
  TS_IP=$(tailscale ip -4 2>/dev/null || true)
fi

# 7. Linked-install-only steps: report our IP, fetch the assigned
#    department URL, and set up Chromium kiosk + autologin.
if [ "$LINKED_INSTALL" = true ]; then
  echo
  echo "Reporting this device to Event-Admin..."
  if [ -n "$TS_IP" ]; then
    curl -fsSL -X POST "$TV_AGENT_SERVER/api/tv-nodes/$TV_AGENT_NODE_ID/checkin" \\
      -H "X-Agent-Token: $TOKEN" -H "Content-Type: application/json" \\
      -d "{\\"host\\":\\"$TS_IP\\"}" >/dev/null || echo "  (check-in failed, you can still add the host manually in Enheter)"
  else
    echo "  No Tailscale IP detected, skipping check-in. Run 'tailscale up' and add the host manually."
  fi

  echo "Fetching kiosk URL for this device's assigned department..."
  KIOSK_URL_RESP=$(curl -fsSL "$TV_AGENT_SERVER/api/tv-nodes/$TV_AGENT_NODE_ID/kiosk-url" -H "X-Agent-Token: $TOKEN" || true)
  FETCHED_URL=$(echo "$KIOSK_URL_RESP" | node -e "try{const d=JSON.parse(require('fs').readFileSync(0,'utf8'));if(d.url)console.log(d.url);}catch(e){}" 2>/dev/null || true)
  if [ -n "$FETCHED_URL" ]; then
    echo "$FETCHED_URL" > "$CONFIG_DIR/kiosk-url"
    echo "  Kiosk URL set to: $FETCHED_URL"
  else
    echo "  Could not fetch a department URL yet (device may not be linked to a department)."
    echo "  Using placeholder, update it later from Enheter -> Endre URL."
  fi

  echo
  echo "Setting up Chromium kiosk mode + autologin..."

  apt-get update -qq
  if ! command -v chromium-browser >/dev/null 2>&1 && ! command -v chromium >/dev/null 2>&1; then
    apt-get install -y -qq chromium-browser 2>/dev/null || apt-get install -y -qq chromium 2>/dev/null || true
  fi
  CHROMIUM_BIN="$(command -v chromium-browser || command -v chromium || true)"
  if [ -z "$CHROMIUM_BIN" ]; then
    echo "  WARNING: could not install Chromium automatically. Install it manually and re-run install.sh,"
    echo "  or set up the kiosk service by hand, see README.md."
  fi

  if ! dpkg -l | grep -qE '^ii\\s+(xserver-xorg|raspberrypi-ui-mods|ubuntu-desktop)' 2>/dev/null; then
    apt-get install -y -qq xserver-xorg xinit openbox unclutter >/dev/null 2>&1 || true
  fi

  mkdir -p /etc/systemd/system/getty@tty1.service.d
  cat > /etc/systemd/system/getty@tty1.service.d/override.conf <<EOF
[Service]
ExecStart=
ExecStart=-/sbin/agetty --autologin $AGENT_USER --noclear %I \\$TERM
EOF

  PROFILE_FILE="/home/$AGENT_USER/.bash_profile"
  if ! grep -q "tv-agent kiosk autostart" "$PROFILE_FILE" 2>/dev/null; then
    cat >> "$PROFILE_FILE" <<'PROFEOF'

# tv-agent kiosk autostart
if [ -z "$DISPLAY" ] && [ "$(tty)" = "/dev/tty1" ]; then
  exec startx
fi
PROFEOF
    chown "$AGENT_USER:$AGENT_USER" "$PROFILE_FILE"
  fi

  XINITRC_FILE="/home/$AGENT_USER/.xinitrc"
  cat > "$XINITRC_FILE" <<EOF
#!/bin/sh
xset -dpms
xset s off
xset s noblank
unclutter -idle 0.5 -root &
openbox-session &
sleep 2
exec systemctl start --no-block $KIOSK_SERVICE_NAME
EOF
  chmod +x "$XINITRC_FILE"
  chown "$AGENT_USER:$AGENT_USER" "$XINITRC_FILE"

  if [ -n "$CHROMIUM_BIN" ]; then
    cat > /etc/systemd/system/$KIOSK_SERVICE_NAME <<EOF
[Unit]
Description=TV kiosk browser
After=graphical.target

[Service]
Type=simple
User=$AGENT_USER
Environment=DISPLAY=:0
ExecStart=/bin/sh -c '$CHROMIUM_BIN --kiosk --noerrdialogs --disable-infobars --disable-session-crashed-bubble --disable-features=TranslateUI --check-for-update-interval=31536000 --autoplay-policy=no-user-gesture-required "\\$(cat $CONFIG_DIR/kiosk-url)"'
Restart=always
RestartSec=3

[Install]
WantedBy=graphical.target
EOF
    systemctl daemon-reload
    systemctl enable $KIOSK_SERVICE_NAME >/dev/null 2>&1 || true
    echo "  Kiosk service installed: $KIOSK_SERVICE_NAME"
  fi

  echo "  Autologin configured for tty1 -> startx -> openbox -> chromium kiosk."
fi

echo
echo "── Done ──"
echo "Agent running on port 9191."
if [ -n "$TS_IP" ]; then
  echo "Tailscale IP: $TS_IP"
fi

if [ "$LINKED_INSTALL" = true ]; then
  echo
  echo "This device is linked to Event-Admin and should now appear as"
  echo "registered in TV-kanal -> Enheter. Reboot to start the kiosk:"
  echo
  echo "  sudo reboot"
else
  echo
  echo "Add this device in Event-Admin -> TV-kanal -> Enheter with:"
  echo "  Host:  \${TS_IP:-<Tailscale IP of this device>}"
  echo "  Token: $TOKEN"
  echo
  echo "NOTE: this was a standalone install, it did not set up the kiosk"
  echo "      browser. It assumes you already have one running, or that"
  echo "      you will wire it up by hand per README.md. For automatic kiosk"
  echo "      setup, use the per-device install command from the Enheter tab"
  echo "      instead (pre-register the device there first)."
fi
`;

const TV_AGENT_README_MD = `# Event-Admin TV-node agent

Small agent that runs on a TV-node (e.g. Raspberry Pi 5) and lets Event-Admin's
admin panel see status and send commands over Tailscale: reboot, change the
displayed department URL, and reset the Linux login password.

## Two ways to install

### 1. Linked install (recommended — sets up everything)

In Event-Admin → TV-kanal → Enheter, click **＋ Legg til enhet**, choose
**📦 Ny enhet**, give it a name, and pick the department it should show. You'll
get a one-line install command, valid for 15 minutes:

\`\`\`bash
curl -fsSL 'https://your-event-admin/api/tv-agent/bootstrap?token=...' | sudo bash
\`\`\`

Run that on a clean Debian/Ubuntu install (Raspberry Pi OS counts) that
already has Tailscale connected (\`tailscale up\`). It will:

- install Node.js if missing
- install the agent, pre-linked to the device record you just created
  (no manual token copy-pasting)
- report this device's Tailscale IP back to Event-Admin automatically
- fetch the assigned department's TV URL and set it as the kiosk page
- install Chromium and set up autologin → kiosk mode, so the screen comes
  up showing the right page after a reboot, no popups or config screens

Reboot when it's done and the screen takes over.

### 2. Standalone install (agent only, no kiosk setup)

\`\`\`bash
scp agent.js install.sh pi@<pi-ip>:~/
ssh pi@<pi-ip>
sudo bash install.sh
\`\`\`

Use this if you already have a working kiosk browser (as your original Pi
does) and only want remote management added on top, without touching the
display setup at all. The script detects there's no linked device and skips
all the Chromium/autologin steps — agent-only, exactly like before.

It prints a Tailscale IP and a generated token at the end; paste both into
**＋ Legg til enhet → 🔧 Koble til eksisterende** in Event-Admin.

## What "linked install" actually changes on the system

- Installs \`xserver-xorg\`, \`xinit\`, \`openbox\`, \`unclutter\`, and Chromium
  (skipped if a desktop environment is already detected, so it won't fight
  an existing GUI setup)
- Sets tty1 to auto-login as the installing user (\`getty@tty1.service\`
  override)
- Adds a kiosk autostart to that user's \`.bash_profile\` / \`.xinitrc\`
  (\`startx\` → openbox → Chromium kiosk)
- Installs \`tv-kiosk.service\`, which reads \`/etc/tv-agent/kiosk-url\` each
  time it (re)starts — this is what the agent's "change URL" command
  restarts to switch screens

None of this touches your data partition or existing services; it's
additive config plus a few apt packages.

## Wiring up remote URL changes manually (only needed for standalone installs)

If you used the standalone install and want "change displayed URL remotely"
to work too, your existing kiosk autostart needs two small changes:

1. Read the URL from \`/etc/tv-agent/kiosk-url\` instead of a hardcoded value:

   \`\`\`bash
   chromium-browser --kiosk --noerrdialogs --disable-infobars \\
     "$(cat /etc/tv-agent/kiosk-url)"
   \`\`\`

2. Wrap that launch command in a systemd service named \`tv-kiosk.service\`,
   so the agent's \`/set-url\` command can restart it cleanly — see the
   \`[Service]\` block install.sh generates for the linked-install path if you
   want to copy the exact pattern.

If you skip this, reboot/status/password-change still work fine — only the
"push a new URL" button won't actually change what's on screen until you
update it manually.

## Re-running install.sh

Safe to re-run — it keeps the existing token, node-id, and kiosk-url file
rather than overwriting them (except when invoked via the linked bootstrap
URL again, which intentionally re-applies the latest token/department).

\`\`\`bash
sudo bash install.sh
\`\`\`

## Security notes

- The agent only accepts requests carrying the exact token in the
  \`X-Agent-Token\` header, anyone else on your tailnet hitting port 9191
  gets a 401.
- The same token also authenticates the one-time check-in and kiosk-url
  fetch calls the install script makes back to Event-Admin during a linked
  install.
- The sudoers rule is locked to exactly three resolved binaries (\`reboot\`,
  \`chpasswd\`, \`systemctl restart tv-kiosk.service\`), the agent process
  itself does not run as root.
- The install bootstrap link (curl | sudo bash) is single-use and expires
  after 15 minutes, so it can't be replayed later even if it ends up in
  shell history or a chat log.
- Traffic is only as secure as your Tailscale network, fine for a private
  tailnet, but don't expose port 9191 to the public internet.
`;

// ── TV Agent Heartbeat (HTTP-based, no Tailscale needed) ─────────
var _tvPendingCommands = {}; // nodeId -> { reboot, aptUpgrade, agentUpdate, ... }

// ── TV Job Tracking (live logging for remote commands) ───────────
var _tvJobs = {}; // jobId -> { nodeId, type, status, logs[], created, updated }
var _tvJobCounter = 0;

function createTvJob(nodeId, type) {
  var jobId = "job_" + Date.now() + "_" + (++_tvJobCounter);
  _tvJobs[jobId] = {
    id: jobId, nodeId: nodeId, type: type,
    status: "queued", // queued -> running -> done / failed
    logs: [],
    created: new Date().toISOString(),
    updated: new Date().toISOString(),
  };
  // Prune old completed jobs (keep max 200, remove >1h completed)
  var keys = Object.keys(_tvJobs);
  if (keys.length > 200) {
    var cutoff = Date.now() - 3600000;
    keys.forEach(function(k) {
      var j = _tvJobs[k];
      if ((j.status === "done" || j.status === "failed") && new Date(j.updated).getTime() < cutoff) {
        delete _tvJobs[k];
      }
    });
  }
  return jobId;
}

function appendTvJobLogs(jobId, lines, status) {
  var job = _tvJobs[jobId];
  if (!job) return;
  if (lines && lines.length) {
    job.logs = job.logs.concat(lines);
    // Cap at 5000 lines
    if (job.logs.length > 5000) job.logs = job.logs.slice(-5000);
  }
  if (status) job.status = status;
  job.updated = new Date().toISOString();
}

app.post("/api/tv-heartbeat", function (req, res) {
  var token = req.headers["x-agent-token"];
  if (!token) return res.status(403).json({ error: "Missing token" });

  var nodes = readTvNodes();
  var node = nodes.find(function(n) { return n.token === token; });
  if (!node) return res.status(403).json({ error: "Unknown token" });

  var b = req.body || {};

  // Update node with health data
  node.status = "registered";
  node.lastSeen = new Date().toISOString();
  node.host = (b.localIp ? b.localIp + ":9191" : node.host) || "";
  node.hostname = b.hostname || node.hostname || node.name;
  node.health = {
    cpuLoad: b.cpuLoad, cpuTemp: b.cpuTemp,
    memoryUsed: b.memoryUsed, memoryTotal: b.memoryTotal,
    diskUsed: b.diskUsed, diskTotal: b.diskTotal,
    uptime: b.uptime, osVersion: b.osVersion,
    agentVersion: b.agentVersion,
    netIface: b.netIface, netSsid: b.netSsid, localIp: b.localIp,
    aptUpdates: b.aptUpdates || 0, rebootRequired: !!b.rebootRequired,
  };
  // Re-read to preserve any admin changes made since we read (race condition fix)
  var freshNodes = readTvNodes();
  var freshIdx = freshNodes.findIndex(function(n) { return n.token === token; });
  if (freshIdx >= 0) {
    // Only update health-related fields, preserve admin-set fields (name, deptId)
    freshNodes[freshIdx].status = "registered";
    freshNodes[freshIdx].lastSeen = node.lastSeen;
    freshNodes[freshIdx].host = node.host;
    freshNodes[freshIdx].hostname = node.hostname;
    freshNodes[freshIdx].health = node.health;
    saveTvNodes(freshNodes);
  } else {
    saveTvNodes(nodes);
  }

  // Ingest job logs from agent
  if (b.jobLogs && Array.isArray(b.jobLogs)) {
    b.jobLogs.forEach(function(jl) {
      if (jl.jobId && _tvJobs[jl.jobId]) {
        appendTvJobLogs(jl.jobId, jl.lines || [], jl.status || null);
      }
    });
  }

  // Return any pending commands
  var cmds = _tvPendingCommands[node.id] || {};
  delete _tvPendingCommands[node.id];

  var response = { ok: true };
  if (cmds.reboot) response.reboot = true;
  if (cmds.aptUpgrade) {
    response.aptUpgrade = true;
    if (cmds._aptJobId) {
      response.aptUpgradeJobId = cmds._aptJobId;
      appendTvJobLogs(cmds._aptJobId, ["[server] Kommando hentet av enhet, starter…"], "running");
    }
  }
  if (cmds.agentUpdate) {
    response.agentUpdate = true;
    var proto = req.protocol || "https";
    var host = req.headers["x-forwarded-host"] || req.headers.host || ADMIN_DOMAIN;
    response.agentUrl = proto + "://" + host + "/api/tv-agent/agent-code";
    if (cmds._agentJobId) {
      response.agentUpdateJobId = cmds._agentJobId;
      appendTvJobLogs(cmds._agentJobId, ["[server] Kommando hentet av enhet, starter…"], "running");
    }
  }
  if (cmds.changePassword) response.changePassword = cmds.changePassword;
  if (cmds.setUrl) response.setUrl = cmds.setUrl;
  if (cmds.setHostname) response.setHostname = cmds.setHostname;

  res.json(response);
});

// Queue a command for next heartbeat
function queueTvCommand(nodeId, cmd) {
  if (!_tvPendingCommands[nodeId]) _tvPendingCommands[nodeId] = {};
  // For trackable commands, create a job
  var jobId = null;
  if (cmd.aptUpgrade) {
    jobId = createTvJob(nodeId, "apt-upgrade");
    cmd._aptJobId = jobId;
  } else if (cmd.agentUpdate) {
    jobId = createTvJob(nodeId, "agent-update");
    cmd._agentJobId = jobId;
  }
  Object.assign(_tvPendingCommands[nodeId], cmd);
  return jobId;
}

// Override the existing reboot/update endpoints to use heartbeat queue
// when the node isn't directly reachable via Tailscale
app.post("/api/tv-nodes/:id/hb-reboot", auth, managerOrAdmin, function (req, res) {
  queueTvCommand(req.params.id, { reboot: true });
  res.json({ ok: true, message: "Reboot queued for next heartbeat" });
});

app.post("/api/tv-nodes/:id/hb-update", auth, managerOrAdmin, function (req, res) {
  var jobId = queueTvCommand(req.params.id, { agentUpdate: true });
  res.json({ ok: true, message: "Agent update queued for next heartbeat", jobId: jobId });
});

app.post("/api/tv-nodes/:id/hb-password", auth, managerOrAdmin, function (req, res) {
  var password = req.body.password;
  var user = req.body.user || "kiosk";
  if (!password) return res.status(400).json({ error: "Password required" });
  queueTvCommand(req.params.id, { changePassword: { user: user, password: password } });
  res.json({ ok: true, message: "Password change queued for next heartbeat" });
});

app.post("/api/tv-nodes/:id/hb-apt-upgrade", auth, managerOrAdmin, function (req, res) {
  var jobId = queueTvCommand(req.params.id, { aptUpgrade: true });
  res.json({ ok: true, message: "OS upgrade queued for next heartbeat", jobId: jobId });
});

// GET job logs for live popup
app.get("/api/tv-jobs/:jobId", auth, managerOrAdmin, function (req, res) {
  var job = _tvJobs[req.params.jobId];
  if (!job) return res.status(404).json({ error: "Job not found" });
  var since = parseInt(req.query.since) || 0;
  res.json({
    id: job.id, nodeId: job.nodeId, type: job.type,
    status: job.status, created: job.created, updated: job.updated,
    logs: job.logs.slice(since),
    offset: since, total: job.logs.length,
  });
});

// POST job logs from agent (immediate flush, e.g. before restart)
app.post("/api/tv-job-logs", function (req, res) {
  var token = req.headers["x-agent-token"];
  if (!token) return res.status(403).json({ error: "Missing token" });
  var nodes = readTvNodes();
  var node = nodes.find(function(n) { return n.token === token; });
  if (!node) return res.status(403).json({ error: "Unknown token" });
  var logs = req.body && req.body.jobLogs;
  if (logs && Array.isArray(logs)) {
    logs.forEach(function(jl) {
      if (jl.jobId && _tvJobs[jl.jobId]) {
        appendTvJobLogs(jl.jobId, jl.lines || [], jl.status || null);
      }
    });
  }
  res.json({ ok: true });
});

// GET node health for the UI
