// One-liner installer: curl this URL into bash on the Pi to fetch + run install.sh
// (auth-gated via a short-lived signed token query param, since curl can't send session cookies)
app.get("/api/tv-agent/bootstrap-token", auth, managerOrAdmin, function (req, res) {
  var nodeId = req.query.nodeId;
  var node = readTvNodes().find(function (n) { return n.id === nodeId; });
  if (!node) return res.status(404).json({ error: st("device_not_found_create", req) });

  var crypto = require("crypto");
  var bootstrapToken = crypto.randomBytes(24).toString("base64url");
  var expires = Date.now() + 15 * 60 * 1000; // 15 minutes
  global._tvAgentBootstrapTokens = global._tvAgentBootstrapTokens || new Map();
  global._tvAgentBootstrapTokens.set(bootstrapToken, { nodeId: nodeId, expires: expires });
  // Garbage-collect expired entries opportunistically
  global._tvAgentBootstrapTokens.forEach(function (v, t) {
    if (v.expires < Date.now()) global._tvAgentBootstrapTokens.delete(t);
  });
  var proto = req.headers["x-forwarded-proto"] || req.protocol;
  var host = req.headers.host;
  var base = proto + "://" + host;
  res.json({
    ok: true,
    token: bootstrapToken,
    expiresInMinutes: 15,
    curlCommand: "curl -fsSL '" + base + "/api/tv-agent/bootstrap?token=" + bootstrapToken + "' | sudo bash",
  });
});

// Unauthenticated (token-gated) bundle install script — fetches agent.js + install.sh
// and runs install.sh, all from one curl|bash command for the Pi terminal.
// Bakes in the target device's own (pre-generated) agent token and node id,
// so the agent comes up already linked to the right Event-Admin device record
// and install.sh can fetch the assigned department's kiosk URL automatically.
app.get("/api/tv-agent/bootstrap", function (req, res) {
  var bootstrapToken = req.query.token;
  var tokens = global._tvAgentBootstrapTokens;
  var entry = tokens && tokens.get(bootstrapToken);
  if (!entry || entry.expires < Date.now()) {
    res.setHeader("Content-Type", "text/plain");
    return res.status(403).send("# Token expired or invalid. Generate a new install command from Event-Admin -> TV-kanal -> Enheter.\n");
  }
  if (tokens) tokens.delete(bootstrapToken); // single-use
  var node = readTvNodes().find(function (n) { return n.id === entry.nodeId; });
  if (!node) {
    res.setHeader("Content-Type", "text/plain");
    return res.status(404).send("# Device was deleted from Event-Admin before install completed.\n");
  }
  var proto = req.headers["x-forwarded-proto"] || req.protocol;
  var host = req.headers.host;
  var base = proto + "://" + host;

  // Embed agent.js and install.sh directly as base64 — avoids needing a
  // second authenticated request to download them separately, which would
  // fail since the Pi has no session cookie during bootstrap.
  var agentB64    = Buffer.from(TV_AGENT_JS).toString("base64");
  var installB64  = Buffer.from(TV_AGENT_INSTALL_SH).toString("base64");

  var script = [
    "#!/usr/bin/env bash",
    "set -euo pipefail",
    "echo 'Setting up Event-Admin TV-agent...'",
    "WORKDIR=$(mktemp -d)",
    "cd \"$WORKDIR\"",
    // Decode the embedded files instead of downloading them
    "echo '" + agentB64 + "' | base64 -d > agent.js",
    "echo '" + installB64 + "' | base64 -d > install.sh",
    "chmod +x install.sh",
    "export TV_AGENT_TOKEN=" + JSON.stringify(node.token),
    "export TV_AGENT_NODE_ID=" + JSON.stringify(node.id),
    "export TV_AGENT_SERVER=" + JSON.stringify(base),
    "bash install.sh",
    "cd /",
    "rm -rf \"$WORKDIR\"",
  ].join("\n") + "\n";
  res.setHeader("Content-Type", "text/x-shellscript");
  res.send(script);
});

// ══════════════════════════════════════════════════════════════════
// TV zero-touch provisioning + kiosk image builder
// ------------------------------------------------------------------
// Two related features for the TV → Enheter tab:
//
//  1. Provisioning: a shared secret is baked into a kiosk image. On
//     first boot the device calls home, and is either auto-approved or
//     placed in an approval queue. Approval creates a normal tv_nodes
//     record, so everything downstream (agent, kiosk, remote control)
//     works exactly as it does for a hand-installed device.
//
//  2. Image builder: builds a ready-to-flash image with the server URL
//     and provisioning secret already inside it — a Raspberry Pi SD
//     image (.img.gz) or a bootable x86 ISO for thin clients.
//
// The Pi image is customised with mtools, which edits the FAT boot
// partition inside the image file directly. No loop device, no mount,
// no root, no privileged container.
// ══════════════════════════════════════════════════════════════════

// ── SD Card provisioning package ──────────────────────────────────
app.get("/api/tv-agent/sd-package", function(req, res) {
  var archiver; try { archiver = require("archiver"); } catch(e) { return res.status(500).json({ error: "archiver not available — npm install archiver" }); }
  var provConfig = getProvisionConfig();
  if (!provConfig.enabled || !provConfig.secret || req.query.secret !== provConfig.secret) {
    return res.status(403).json({ error: "Invalid or missing provision secret" });
  }
  var hostname = req.query.hostname || "";
  var deptId = req.query.dept || "";
  var server = req.query.server || ("https://" + ADMIN_DOMAIN);
  var wifiSsid = req.query.wifi_ssid || "";
  var wifiPass = req.query.wifi_pass || "";
  var settings = getSettings();
  var dept = deptId ? (settings.departments || []).find(function(d){ return d.id === deptId; }) : null;
  var tvUrl = dept ? ("https://" + (dept.slug || dept.id) + "." + DOMAIN + "/tv/" + deptId) : "";
  var provConfig = getProvisionConfig();
  var provSecret = provConfig.secret || "";

  // Build the env file
  var envContent = [
    "# TV Agent configuration — generated by Event-Admin",
    "TV_AGENT_SERVER=" + server,
    "TV_AGENT_SECRET=" + provSecret,
    "TV_AGENT_KIOSK_URL=" + tvUrl,
    hostname ? "TV_AGENT_HOSTNAME=" + hostname : "",
    deptId ? "TV_AGENT_DEPT=" + deptId : "",
  ].filter(function(l){ return l; }).join("\n") + "\n";

  // Build the firstrun script
  var firstrunScript = '#!/bin/bash\nset -e\nLOG=/var/log/tv-agent-install.log\nexec > >(tee -a $LOG) 2>&1\necho "=== Event-Admin TV Agent First-Boot Install $(date) ==="\n\necho "Waiting for network..."\nCONNECTED=0\nfor i in $(seq 1 60); do\n    if ip route show default 2>/dev/null | grep -q default; then\n        if ping -c1 -W3 8.8.8.8 >/dev/null 2>&1; then\n            echo "Network up"; CONNECTED=1; break\n        fi\n    fi\n    echo "  No network yet ($i/60)..."; sleep 5\ndone\n[ $CONNECTED -eq 0 ] && { echo "ERROR: No network after 5 min."; exit 1; }\n\necho "Syncing clock..."\ntimedatectl set-ntp true 2>/dev/null || true\nsleep 5\n\necho "Installing dependencies..."\napt-get update -qq\napt-get install -y nodejs chromium-browser xdotool unclutter curl -qq 2>/dev/null || apt-get install -y nodejs chromium xdotool unclutter curl -qq 2>/dev/null || true\n\necho "Installing TV agent..."\nSERVER="' + server + '"\nTOKEN=$(cat /boot/firmware/tv-agent-token 2>/dev/null || echo "")\ncurl -fsSL "$SERVER/api/tv-agent/bootstrap?token=$TOKEN" | bash\n\n# Cleanup\nsystemctl disable tv-agent-firstrun.service 2>/dev/null || true\nrm -f /etc/systemd/system/tv-agent-firstrun.service\nrm -f /boot/firmware/firstrun-tv-agent.sh\nrm -f /boot/firmware/tv-agent-token\n\necho "=== Install complete! Rebooting in 5s... ==="\nsleep 5\nreboot\n';

  var firstrunService = "[Unit]\nDescription=TV Agent First-Boot Installer\nAfter=network-online.target\nWants=network-online.target\nConditionPathExists=/boot/firmware/firstrun-tv-agent.sh\n\n[Service]\nType=oneshot\nExecStart=/bin/bash /boot/firmware/firstrun-tv-agent.sh\nStandardOutput=journal+console\nStandardError=journal+console\nTimeoutStartSec=600\n\n[Install]\nWantedBy=multi-user.target\n";

  var filename = "tv-agent-" + (hostname || "pi") + ".zip";
  res.setHeader("Content-Type", "application/zip");
  res.setHeader("Content-Disposition", 'attachment; filename="' + filename + '"');

  var archive = archiver("zip", { zlib: { level: 9 } });
  archive.on("error", function(err){ console.error("[SD-Pkg]", err); });
  archive.pipe(res);
  archive.append(envContent, { name: "tv-agent.env" });
  archive.append(firstrunScript, { name: "firstrun-tv-agent.sh" });
  archive.append(firstrunService, { name: "tv-agent-firstrun.service" });
  if (req.query.token) archive.append(req.query.token + "\n", { name: "tv-agent-token" });
  archive.append([
    "# Event-Admin TV Agent — SD Card Package",
    hostname ? "## Configured for: " + hostname : "",
    "## Server: " + server,
    tvUrl ? "## TV URL: " + tvUrl : "",
    "",
    "## Setup",
    "1. Write Raspberry Pi OS Lite (64-bit) with Imager — set username 'kiosk', enable SSH",
    "2. Keep SD card inserted, run: sudo bash configure-sd.sh",
    "3. Eject → insert into Pi → power on",
    "4. Pi connects, installs, appears in TV-kanal → Enheter",
  ].filter(function(l){ return l; }).join("\n"), { name: "README.md" });
  archive.finalize();
});

// SD configure script (Linux/Mac)
app.get("/api/tv-agent/sd-script", function(req, res) {
  var provConfig = getProvisionConfig();
  if (!provConfig.enabled || !provConfig.secret || req.query.secret !== provConfig.secret) {
    return res.status(403).json({ error: "Invalid provision secret" });
  }
  var hostname = req.query.hostname || "";
  var server = req.query.server || ("https://" + ADMIN_DOMAIN);
  var provSecret = provConfig.secret || "";
  var wifiSsid = req.query.wifi_ssid || "";
  var wifiPass = req.query.wifi_pass || "";
  var deptId = req.query.dept || "";
  var _s = getSettings();
  var _dept = deptId ? (_s.departments || []).find(function(d){ return d.id === deptId; }) : null;
  var tvUrl = _dept ? ("https://" + (_dept.slug || _dept.id) + "." + DOMAIN + "/tv/" + deptId) : "";

  // Use backtick template to avoid quote-escaping hell
  var script = '#!/bin/bash\n'
    + '# Event-Admin TV Agent — SD Card Configurator\n'
    + '# Usage: sudo bash configure-sd.sh\n'
    + '# Fully self-contained — no server calls during SD config.\n'
    + 'set -e\n\n'
    + 'HOSTNAME="' + hostname + '"\n'
    + 'SERVER="' + server + '"\n'
    + 'PROV_SECRET="' + provSecret + '"\n'
    + 'WIFI_SSID="' + wifiSsid + '"\n'
    + 'WIFI_PASS="' + wifiPass + '"\n'
    + 'TV_URL="' + tvUrl + '"\n'
    + 'DEPT="' + deptId + '"\n\n'
    + 'echo ""\n'
    + 'echo "======================================================="\n'
    + 'echo "  Event-Admin TV Agent — SD Card Configurator"\n'
    + 'echo "======================================================="\n'
    + 'echo ""\n\n'
    + 'BOOT=$(findmnt -n -o TARGET -S LABEL=bootfs 2>/dev/null || true)\n'
    + 'ROOT=$(findmnt -n -o TARGET -S LABEL=rootfs 2>/dev/null || true)\n'
    + 'if [ -z "$BOOT" ]; then\n'
    + '  for p in /run/media/*/bootfs /media/*/bootfs /mnt/bootfs; do [ -d "$p" ] && BOOT="$p" && break; done\n'
    + 'fi\n'
    + 'if [ -z "$ROOT" ]; then\n'
    + '  for p in /run/media/*/rootfs /media/*/rootfs /mnt/rootfs; do [ -d "$p" ] && ROOT="$p" && break; done\n'
    + 'fi\n'
    + '[ -z "$BOOT" ] && { echo "ERROR: Cannot find bootfs. Is the SD card inserted?"; exit 1; }\n'
    + '[ -z "$ROOT" ] && { echo "ERROR: Cannot find rootfs."; exit 1; }\n'
    + 'echo "  bootfs: $BOOT"\n'
    + 'echo "  rootfs: $ROOT"\n'
    + 'echo ""\n\n'
    + 'if [ -n "$HOSTNAME" ]; then\n'
    + '  echo "[1/6] Setting hostname: $HOSTNAME"\n'
    + '  echo "$HOSTNAME" > "$ROOT/etc/hostname"\n'
    + '  sed -i "s/127.0.1.1.*/127.0.1.1\\t$HOSTNAME/" "$ROOT/etc/hosts"\n'
    + 'else\n'
    + '  echo "[1/6] Hostname: skipped"\n'
    + 'fi\n\n'
    + 'if [ -n "$WIFI_SSID" ]; then\n'
    + '  echo "[2/6] Configuring WiFi: $WIFI_SSID"\n'
    + '  NM_DIR="$ROOT/etc/NetworkManager/system-connections"\n'
    + '  mkdir -p "$NM_DIR"\n'
    + '  cat > "$NM_DIR/$WIFI_SSID.nmconnection" << WIFIEOF\n'
    + '[connection]\nid=$WIFI_SSID\ntype=wifi\ninterface-name=wlan0\nautoconnect=true\n\n'
    + '[wifi]\nssid=$WIFI_SSID\nmode=infrastructure\n\n'
    + '[wifi-security]\nkey-mgmt=wpa-psk\npsk=$WIFI_PASS\n\n'
    + '[ipv4]\nmethod=auto\nWIFIEOF\n'
    + '  chmod 600 "$NM_DIR/$WIFI_SSID.nmconnection"\n'
    + 'else\n'
    + '  echo "[2/6] WiFi: skipped (wired)"\n'
    + 'fi\n\n'
    + 'echo "[3/6] Enabling SSH + password auth"\n'
    + 'touch "$BOOT/ssh"\n'
    + 'SSHD_CFG="$ROOT/etc/ssh/sshd_config"\n'
    + 'if [ -f "$SSHD_CFG" ]; then\n'
    + '  sed -i "s/^#*PasswordAuthentication.*/PasswordAuthentication yes/" "$SSHD_CFG"\n'
    + 'fi\n\n'
    + 'echo "[4/6] Writing agent config"\n'
    + 'cat > "$BOOT/tv-agent.env" << ENVEOF\n'
    + 'TV_SERVER=$SERVER\nTV_PROV_SECRET=$PROV_SECRET\nTV_HOSTNAME=$HOSTNAME\nTV_KIOSK_URL=$TV_URL\nTV_DEPT=$DEPT\n'
    + 'ENVEOF\n\n'
    + 'echo "[5/6] Writing firstrun script"\n'
    + "cat > \"$BOOT/firstrun-tv-agent.sh\" << 'FIRSTRUNEOF'\n"
    + '#!/bin/bash\n'
    + 'set -e\n'
    + 'LOG=/var/log/tv-agent-install.log\n'
    + 'exec > >(tee -a $LOG) 2>&1\n'
    + 'echo "=== Event-Admin TV Agent First-Boot Install $(date) ==="\n'
    + 'BOOT_DIR=""\n'
    + 'for d in /boot/firmware /boot; do [ -f "$d/tv-agent.env" ] && BOOT_DIR="$d" && break; done\n'
    + '[ -z "$BOOT_DIR" ] && { echo "ERROR: tv-agent.env not found"; exit 1; }\n'
    + '. "$BOOT_DIR/tv-agent.env"\n'
    + 'echo "Server: $TV_SERVER"\n'
    + 'echo "Waiting for network..."\n'
    + 'CONNECTED=0\n'
    + 'for i in $(seq 1 90); do\n'
    + '    if ip route show default 2>/dev/null | grep -q default; then\n'
    + '        if ping -c1 -W3 8.8.8.8 >/dev/null 2>&1 || ping -c1 -W3 1.1.1.1 >/dev/null 2>&1; then\n'
    + '            echo "Network up"; CONNECTED=1; break\n'
    + '        fi\n'
    + '    fi\n'
    + '    sleep 3\n'
    + 'done\n'
    + '[ $CONNECTED -eq 0 ] && { echo "ERROR: No network"; exit 1; }\n'
    + '\n'
    + 'echo "Syncing clock..."\n'
    + 'timedatectl set-ntp true 2>/dev/null || true\n'
    + 'SYNCED=0\n'
    + 'for i in $(seq 1 20); do\n'
    + '    if timedatectl show -p NTPSynchronized --value 2>/dev/null | grep -q yes; then\n'
    + '        echo "NTP synced: $(date)"; SYNCED=1; break\n'
    + '    fi\n'
    + '    sleep 2\n'
    + 'done\n'
    + 'if [ $SYNCED -eq 0 ]; then\n'
    + '    echo "NTP failed, using HTTP date fallback..."\n'
    + '    for url in http://deb.debian.org http://google.com http://cloudflare.com; do\n'
    + '        HTTP_DATE=$(curl -sI "$url" 2>/dev/null | grep -i "^date:" | sed "s/^[Dd]ate: //")\n'
    + '        if [ -n "$HTTP_DATE" ]; then\n'
    + '            date -s "$HTTP_DATE" 2>/dev/null && echo "Clock set from HTTP: $(date)" && break\n'
    + '        fi\n'
    + '    done\n'
    + 'fi\n'
    + 'echo "Current time: $(date)"\n'
    + '\n'
    + 'echo "Waiting for apt lock..."\n'
    + 'for i in $(seq 1 30); do\n'
    + '    flock -n /var/lib/dpkg/lock-frontend true 2>/dev/null && break\n'
    + '    sleep 5\n'
    + 'done\n'
    + '\n'
    + 'echo "Ensuring SSH password auth..."\n'
    + 'sed -i "s/^#*PasswordAuthentication.*/PasswordAuthentication yes/" /etc/ssh/sshd_config 2>/dev/null || true\n'
    + 'sed -i "s/^#*KbdInteractiveAuthentication.*/KbdInteractiveAuthentication yes/" /etc/ssh/sshd_config 2>/dev/null || true\n'
    + 'systemctl restart ssh 2>/dev/null || true\n'
    + '\n'
    + 'apt-get update -qq\n'
    + 'apt-get install -y nodejs npm xserver-xorg xinit openbox dbus-x11 chromium-browser xdotool unclutter scrot curl -qq --no-install-recommends 2>/dev/null \\\n'
    + '  || apt-get install -y nodejs npm xserver-xorg xinit openbox dbus-x11 chromium xdotool unclutter scrot curl -qq --no-install-recommends 2>/dev/null || true\n'
    + '[ -n "$TV_HOSTNAME" ] && hostnamectl set-hostname "$TV_HOSTNAME" 2>/dev/null || true\n'
    + 'mkdir -p /tmp/tv-agent-setup\n'
    + 'curl -fsSL "$TV_SERVER/api/tv-agent/agent-code" -o /tmp/tv-agent-setup/agent.js\n'
    + 'curl -fsSL "$TV_SERVER/api/tv-agent/install-script" -o /tmp/tv-agent-setup/install.sh\n'
    + 'chmod +x /tmp/tv-agent-setup/install.sh\n'
    + 'export TV_AGENT_SERVER="$TV_SERVER"\n'
    + 'export TV_AGENT_KIOSK_URL="$TV_KIOSK_URL"\n'
    + 'cd /tmp/tv-agent-setup && bash install.sh\n'
    + '\n'
    + '# Set up kiosk browser if we have a TV URL\n'
    + 'if [ -n "$TV_KIOSK_URL" ]; then\n'
    + '  echo "=== Setting up kiosk for: $TV_KIOSK_URL ==="\n'
    + '  KIOSK_USER="kiosk"\n'
    + '  KIOSK_HOME="/home/$KIOSK_USER"\n'
    + '  \n'
    + '  # Detect chromium binary\n'
    + '  CHROMIUM=""\n'
    + '  for b in chromium chromium-browser google-chrome; do\n'
    + '    command -v "$b" >/dev/null 2>&1 && CHROMIUM="$b" && break\n'
    + '  done\n'
    + '  [ -z "$CHROMIUM" ] && CHROMIUM="chromium"\n'
    + '  echo "Chromium: $CHROMIUM"\n'
    + '  \n'
    + '  # Install openbox if missing\n'
    + '  apt-get install -y openbox scrot --no-install-recommends -qq 2>/dev/null || true\n'
    + '  \n'
    + '  # TTY/video group permissions\n'
    + '  usermod -a -G tty,video,input,render "$KIOSK_USER" 2>/dev/null || true\n'
    + '  cat > /etc/udev/rules.d/99-tv-agent.rules << UDEVEOF\n'
    + 'KERNEL=="tty0", GROUP="tty", MODE="0660"\n'
    + 'KERNEL=="tty1", GROUP="tty", MODE="0660"\n'
    + 'UDEVEOF\n'
    + '  chmod 660 /dev/tty0 /dev/tty1 2>/dev/null || true\n'
    + '  \n'
    + '  # Xorg display driver config (Pi 5 dual-card fix)\n'
    + '  mkdir -p /etc/X11/xorg.conf.d\n'
    + '  DISPLAY_CARD=""\n'
    + '  for card in /dev/dri/card*; do\n'
    + '    cn=$(basename "$card")\n'
    + '    if ls /sys/class/drm/${cn}-HDMI-A-* >/dev/null 2>&1 || ls /sys/class/drm/${cn}-DP-* >/dev/null 2>&1; then\n'
    + '      DISPLAY_CARD="$card"; echo "Display card: $DISPLAY_CARD"; break\n'
    + '    fi\n'
    + '  done\n'
    + '  HAS_V3D=false\n'
    + '  for card in /dev/dri/card*; do\n'
    + '    cn=$(basename "$card")\n'
    + '    [ -f "/sys/class/drm/${cn}/device/uevent" ] && grep -q "DRIVER=v3d" "/sys/class/drm/${cn}/device/uevent" && HAS_V3D=true && break\n'
    + '  done\n'
    + '  if [ -n "$DISPLAY_CARD" ] && [ "$HAS_V3D" = true ]; then\n'
    + '    cat > /etc/X11/xorg.conf.d/98-modesetting.conf << XEOF\n'
    + 'Section "OutputClass"\n'
    + '    Identifier "v3d-ignore"\n'
    + '    MatchDriver "v3d"\n'
    + '    Option "Ignore" "true"\n'
    + 'EndSection\n'
    + 'Section "Device"\n'
    + '    Identifier "default"\n'
    + '    Driver "modesetting"\n'
    + '    Option "kmsdev" "DISPLAY_CARD_PLACEHOLDER"\n'
    + '    Option "PrimaryGPU" "true"\n'
    + 'EndSection\n'
    + 'XEOF\n'
    + '    sed -i "s|DISPLAY_CARD_PLACEHOLDER|$DISPLAY_CARD|" /etc/X11/xorg.conf.d/98-modesetting.conf\n'
    + '  elif [ -n "$DISPLAY_CARD" ]; then\n'
    + '    cat > /etc/X11/xorg.conf.d/98-modesetting.conf << XEOF\n'
    + 'Section "Device"\n'
    + '    Identifier "default"\n'
    + '    Driver "modesetting"\n'
    + '    Option "kmsdev" "DISPLAY_CARD_PLACEHOLDER"\n'
    + 'EndSection\n'
    + 'XEOF\n'
    + '    sed -i "s|DISPLAY_CARD_PLACEHOLDER|$DISPLAY_CARD|" /etc/X11/xorg.conf.d/98-modesetting.conf\n'
    + '  fi\n'
    + '  \n'
    + '  # KMS overlay\n'
    + '  for cfg in /boot/firmware/config.txt /boot/config.txt; do\n'
    + '    [ -f "$cfg" ] && ! grep -q "vc4-kms-v3d" "$cfg" && echo "dtoverlay=vc4-kms-v3d" >> "$cfg" && break\n'
    + '  done\n'
    + '  \n'
    + '  # Disable screen blanking\n'
    + '  cat > /etc/X11/xorg.conf.d/99-tv-agent.conf << XEOF\n'
    + 'Section "ServerFlags"\n'
    + '  Option "BlankTime" "0"\n'
    + '  Option "StandbyTime" "0"\n'
    + '  Option "SuspendTime" "0"\n'
    + '  Option "OffTime" "0"\n'
    + 'EndSection\n'
    + 'Section "Monitor"\n'
    + '  Identifier "Monitor0"\n'
    + '  Option "DPMS" "false"\n'
    + 'EndSection\n'
    + 'XEOF\n'
    + '  \n'
    + '  # Write kiosk URL\n'
    + '  mkdir -p /etc/tv-agent\n'
    + '  echo "$TV_KIOSK_URL" > /etc/tv-agent/kiosk-url\n'
    + '  echo "$TV_SERVER" > /etc/tv-agent/server-url\n'
    + '  echo "allowed_users=anybody" > /etc/X11/Xwrapper.config 2>/dev/null || true\n'
    + '  \n'
    + '  # Detect chromium binary\n'
    + '  CHROMIUM_BIN=$(which chromium 2>/dev/null || which chromium-browser 2>/dev/null || echo chromium)\n'
    + '  echo "Detected browser: $CHROMIUM_BIN"\n'
    + '  \n'
    + '  # Openbox autostart\n'
    + '  mkdir -p /root/.config/openbox\n'
    + '  cat > /root/.config/openbox/autostart << OBEOF\n'
    + 'xset s off &\n'
    + 'xset s noblank &\n'
    + 'xset -dpms &\n'
    + 'unclutter -idle 1 -root &\n'
    + 'sleep 2\n'
    + 'URL=\\$(cat /etc/tv-agent/kiosk-url 2>/dev/null || echo about:blank)\n'
    + '$CHROMIUM_BIN --kiosk --noerrdialogs --disable-infobars --no-first-run --disable-session-crashed-bubble --disable-features=TranslateUI --no-sandbox --disable-dev-shm-usage --disable-gpu --user-data-dir=/tmp/tv-browser "\\$URL" &\n'
    + 'OBEOF\n'
    + '  # Also copy to kiosk home for reference\n  mkdir -p "$KIOSK_HOME/.config/openbox"\n  cp /root/.config/openbox/autostart "$KIOSK_HOME/.config/openbox/autostart"\n  chown -R $KIOSK_USER:$KIOSK_USER "$KIOSK_HOME/.config"\n'
    + '  \n'
    + '  # Sudoers for xinit\n'
    + '  echo "$KIOSK_USER ALL=(ALL) NOPASSWD: /usr/bin/xinit" > /etc/sudoers.d/tv-agent\n'
    + '  echo "$KIOSK_USER ALL=(ALL) NOPASSWD: /sbin/reboot" >> /etc/sudoers.d/tv-agent\n'
    + '  chmod 440 /etc/sudoers.d/tv-agent\n'
    + '  \n'
    + '  # Remove old .bash_profile that blocks .bashrc\n'
    + '  rm -f "$KIOSK_HOME/.bash_profile"\n'
    + '  # Ensure .profile sources .bashrc\n'
    + '  grep -q "bashrc" "$KIOSK_HOME/.profile" 2>/dev/null || echo "[ -f ~/.bashrc ] && . ~/.bashrc" >> "$KIOSK_HOME/.profile"\n'
    + '  \n'
    + '  # Autostart X from .bashrc on tty1\n'
    + '  sed -i "/# tv-agent kiosk/,/^fi$/d" "$KIOSK_HOME/.bashrc" 2>/dev/null || true\n'
    + '  cat >> "$KIOSK_HOME/.bashrc" << \'BASHEOF\'\n'
    + '\n'
    + '# tv-agent kiosk\n'
    + 'if [ -z "$DISPLAY" ] && [ "$(tty)" = "/dev/tty1" ]; then\n'
    + '  sudo xinit /usr/bin/openbox-session -- :0 vt1 -nolisten tcp\n'
    + 'fi\n'
    + 'BASHEOF\n'
    + '  \n'
    + '  # Autologin on tty1\n'
    + '  mkdir -p /etc/systemd/system/getty@tty1.service.d\n'
    + "  cat > /etc/systemd/system/getty@tty1.service.d/autologin.conf << ALEOF\n"
    + '[Service]\n'
    + 'ExecStart=\n'
    + 'ExecStart=-/sbin/agetty --autologin $KIOSK_USER --noclear %I $TERM\n'
    + 'ALEOF\n'
    + '  systemctl daemon-reload\n'
    + '  echo "Kiosk setup complete"\n'
    + 'fi\n'
    + 'MAC=$(cat /sys/class/net/eth0/address 2>/dev/null || cat /sys/class/net/wlan0/address 2>/dev/null || echo "unknown")\n'
    + 'AGENT_TOKEN=$(cat /etc/tv-agent/token 2>/dev/null || echo "")\n'
    + 'LOCAL_IP=$(hostname -I 2>/dev/null | awk "{print \\$1}" || echo "")\n'
    + 'echo "Registering: hostname=$TV_HOSTNAME mac=$MAC ip=$LOCAL_IP token=${AGENT_TOKEN:0:8}..."\n'
    + 'curl -sS -X POST "$TV_SERVER/api/tv-provision/register" \\\n'
    + '  -H "Content-Type: application/json" \\\n'
    + '  -d "{\\"secret\\":\\"$TV_PROV_SECRET\\",\\"hostname\\":\\"$TV_HOSTNAME\\",\\"mac\\":\\"$MAC\\",\\"token\\":\\"$AGENT_TOKEN\\",\\"ip\\":\\"$LOCAL_IP\\",\\"dept\\":\\"$TV_DEPT\\"}" || true\n'
    + '\n'
    + '# Restart agent so it sends first heartbeat with correct token\n'
    + 'systemctl restart tv-agent 2>/dev/null || true\n'
    + 'sleep 5\n'
    + '\n'
    + 'systemctl disable tv-agent-firstrun.service 2>/dev/null || true\n'
    + 'rm -f /etc/systemd/system/tv-agent-firstrun.service\n'
    + 'rm -f "$BOOT_DIR/firstrun-tv-agent.sh" "$BOOT_DIR/tv-agent.env"\n'
    + 'echo "=== Install complete! Rebooting... ==="\n'
    + 'sleep 3 && reboot\n'
    + 'FIRSTRUNEOF\n'
    + 'chmod +x "$BOOT/firstrun-tv-agent.sh"\n\n'
    + 'echo "[6/6] Installing firstrun service"\n'
    + 'cat > "$ROOT/etc/systemd/system/tv-agent-firstrun.service" << SVCEOF\n'
    + '[Unit]\nDescription=TV Agent First-Boot Installer\nAfter=network-online.target\nWants=network-online.target\n'
    + 'ConditionPathExists=/boot/firmware/firstrun-tv-agent.sh\n\n'
    + '[Service]\nType=oneshot\nExecStart=/bin/bash /boot/firmware/firstrun-tv-agent.sh\n'
    + 'StandardOutput=journal+console\nStandardError=journal+console\nTimeoutStartSec=600\n\n'
    + '[Install]\nWantedBy=multi-user.target\nSVCEOF\n\n'
    + 'mkdir -p "$ROOT/etc/systemd/system/multi-user.target.wants"\n'
    + 'ln -sf /etc/systemd/system/tv-agent-firstrun.service "$ROOT/etc/systemd/system/multi-user.target.wants/tv-agent-firstrun.service"\n\n'
    + 'echo ""\n'
    + 'echo "======================================================="\n'
    + 'echo "  SD card configured!"\n'
    + 'echo "  Hostname: ${HOSTNAME:-<default>}"\n'
    + 'echo "  Server:   $SERVER"\n'
    + 'echo "  WiFi:     ${WIFI_SSID:-<none - wired>}"\n'
    + 'echo "  Eject -> insert into Pi -> power on"\n'
    + 'echo "======================================================="\n';

  res.setHeader("Content-Type", "application/x-shellscript");
  res.setHeader("Content-Disposition", 'attachment; filename="configure-sd' + (hostname ? '-' + hostname : '') + '.sh"');
  res.send(script);
});
// SD configure script (Windows/PowerShell)
app.get("/api/tv-agent/sd-script-win", function(req, res) {
  var provConfig = getProvisionConfig();
  if (!provConfig.enabled || !provConfig.secret || req.query.secret !== provConfig.secret) {
    return res.status(403).json({ error: "Invalid provision secret" });
  }
  var hostname = req.query.hostname || "";
  var server = req.query.server || ("https://" + ADMIN_DOMAIN);
  var token = req.query.secret || "";
  var wifiSsid = req.query.wifi_ssid || "";
  var wifiPass = req.query.wifi_pass || "";

  var script = '# Event-Admin TV Agent - SD Card Configurator (Windows)\n# Run: powershell -ExecutionPolicy Bypass -File configure-sd.ps1\n\n$Hostname = "' + hostname + '"\n$Server = "' + server + '"\n$Token = "' + token + '"\n$WifiSsid = "' + wifiSsid + '"\n$WifiPass = "' + wifiPass + '"\n\nWrite-Host ""\nWrite-Host "Event-Admin TV Agent - SD Card Configurator" -ForegroundColor Yellow\nWrite-Host ""\n\n# Find bootfs\n$Boot = $null\nGet-Volume | Where-Object { $_.FileSystemLabel -eq "bootfs" } | ForEach-Object {\n    $Boot = "$($_.DriveLetter):"\n}\nif (-not $Boot) {\n    Write-Host "ERROR: Cannot find bootfs partition." -ForegroundColor Red\n    Write-Host "Make sure the SD card is inserted."\n    exit 1\n}\nWrite-Host "bootfs: $Boot"\n\nWrite-Host "[1/3] Writing bootstrap token..."\n$Token | Out-File "$Boot\\tv-agent-token" -Encoding utf8 -NoNewline\n\nWrite-Host "[2/3] Downloading firstrun files..."\nInvoke-WebRequest -Uri "$Server/api/tv-agent/sd-package?token=$Token&hostname=$Hostname&format=zip" -OutFile "$Boot\\tv-pkg.zip"\nExpand-Archive -Path "$Boot\\tv-pkg.zip" -DestinationPath "$Boot" -Force\nRemove-Item "$Boot\\tv-pkg.zip"\n\nif ($Hostname) {\n    Write-Host "[3/3] Setting hostname: $Hostname"\n    $Hostname | Out-File "$Boot\\hostname" -Encoding utf8 -NoNewline\n} else {\n    Write-Host "[3/3] Hostname: skipped"\n}\n\nWrite-Host ""\nWrite-Host "SD card configured!" -ForegroundColor Green\nWrite-Host "NOTE: Windows cannot write to rootfs (ext4)." -ForegroundColor Yellow\nWrite-Host "The firstrun script will be triggered via cmdline.txt." -ForegroundColor Yellow\nWrite-Host ""\nWrite-Host "Add to cmdline.txt (on bootfs, SAME line, append with a space):"\nWrite-Host "  systemd.run=/boot/firmware/firstrun-tv-agent.sh systemd.run_success_action=reboot" -ForegroundColor Cyan\nWrite-Host ""\nWrite-Host "Then eject -> insert into Pi -> power on."\n';

  res.setHeader("Content-Type", "application/octet-stream");
  res.setHeader("Content-Disposition", 'attachment; filename="configure-sd' + (hostname ? '-' + hostname : '') + '.ps1"');
  res.send(script);
});


// Default base OS. Overridable per build so a customer can pin a version
// or point at an internal mirror.
const PI_OS_DEFAULT_URL =
  "https://downloads.raspberrypi.com/raspios_lite_arm64_latest";

function ensureTvImageDirs() {
  try {
    if (!fs.existsSync(TV_IMAGE_DIR))   fs.mkdirSync(TV_IMAGE_DIR,   { recursive: true });
    if (!fs.existsSync(TV_IMAGE_CACHE)) fs.mkdirSync(TV_IMAGE_CACHE, { recursive: true });
  } catch(e) {}
}

function readProvisionQueue()  { return readJSON(TV_PROVISION_FILE) || []; }
function saveProvisionQueue(l) { writeJSON(TV_PROVISION_FILE, l); }

function getProvisionConfig() {
  const s = getSettings();
  const c = s.tvProvision || {};
  return {
    enabled:       !!c.enabled,
    secret:        (c.secret || "").toString(),
    autoApprove:   !!c.autoApprove,
    defaultDeptId: c.defaultDeptId || null,
  };
}

function saveProvisionConfig(patch) {
  const s = getSettings();
  const cur = s.tvProvision || {};
  s.tvProvision = {
    enabled:       patch.enabled       !== undefined ? !!patch.enabled       : !!cur.enabled,
    secret:        patch.secret        !== undefined ? String(patch.secret).slice(0, 64) : (cur.secret || ""),
    autoApprove:   patch.autoApprove   !== undefined ? !!patch.autoApprove   : !!cur.autoApprove,
    defaultDeptId: patch.defaultDeptId !== undefined ? (patch.defaultDeptId || null) : (cur.defaultDeptId || null),
  };
  saveSettings(s);
  return s.tvProvision;
}

function newProvisionSecret() {
  return require("crypto").randomBytes(18).toString("base64url").replace(/[-_]/g, "").toUpperCase().slice(0, 24);
}

// Constant-time compare so the secret can't be probed by timing
function secretMatches(presented, expected) {
  if (!expected || !presented) return false;
  const a = Buffer.from(String(presented));
  const b = Buffer.from(String(expected));
  if (a.length !== b.length) return false;
  try { return require("crypto").timingSafeEqual(a, b); } catch(e) { return false; }
}

// Creates the tv_nodes record a provisioned device will use. Mirrors the
// pre-registration path of POST /api/tv-nodes so the device shows up
// identically to one added by hand.
function createNodeFromProvision(entry, deptId) {
  const list = readTvNodes();
  const node = {
    id:        uuid(),
    name:      (entry.hostname || "TV-node").slice(0, 60),
    host:      (entry.localIp || entry.ip || "").replace(/^::ffff:/, "") || null,
    port:      9191,
    token:     entry.agentToken || require("crypto").randomBytes(24).toString("base64url"),
    deptId:    entry.dept || deptId || null,
    status:    "registered",
    mac:       entry.mac || null,
    model:     entry.model || null,
    provisioned: true,
    createdAt: new Date().toISOString(),
  };
  list.push(node);
  saveTvNodes(list);
  return node;
}

// ── Admin API ─────────────────────────────────────────────────────
app.get("/api/tv-provision/settings", auth, adminOnly, function(req, res) {
  const c = getProvisionConfig();
  res.json({
    enabled:       c.enabled,
    autoApprove:   c.autoApprove,
    defaultDeptId: c.defaultDeptId,
    secret:        c.secret,
    hasSecret:     !!c.secret,
  });
});

app.put("/api/tv-provision/settings", auth, adminOnly, function(req, res) {
  res.json(saveProvisionConfig(req.body || {}));
});

app.post("/api/tv-provision/secret", auth, adminOnly, function(req, res) {
  const secret = newProvisionSecret();
  saveProvisionConfig({ secret: secret });
  res.json({ secret: secret });
});

app.get("/api/tv-provision/queue", auth, adminOnly, function(req, res) {
  const nodes = readTvNodes();
  res.json(readProvisionQueue().slice(-200).reverse().map(function(q) {
    const node = q.nodeId ? nodes.find(function(n) { return n.id === q.nodeId; }) : null;
    return Object.assign({}, q, { nodeName: node ? node.name : null, nodeExists: !!node });
  }));
});

app.post("/api/tv-provision/queue/:id/approve", auth, adminOnly, function(req, res) {
  const list = readProvisionQueue();
  const idx  = list.findIndex(function(q) { return q.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: st("does_not_exist", req) });
  if (list[idx].status !== "pending") return res.status(400).json({ error: st("not_pending", req) });

  const deptId = (req.body && req.body.deptId) || getProvisionConfig().defaultDeptId || null;
  const node   = createNodeFromProvision(list[idx], deptId);
  list[idx].status     = "approved";
  list[idx].nodeId     = node.id;
  list[idx].handledAt  = new Date().toISOString();
  list[idx].handledBy  = req.session.user.name || req.session.user.id;
  saveProvisionQueue(list);
  res.json({ ok: true, nodeId: node.id });
});

app.post("/api/tv-provision/queue/:id/reject", auth, adminOnly, function(req, res) {
  const list = readProvisionQueue();
  const idx  = list.findIndex(function(q) { return q.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: st("does_not_exist", req) });
  list[idx].status    = "rejected";
  list[idx].handledAt = new Date().toISOString();
  list[idx].handledBy = req.session.user.name || req.session.user.id;
  saveProvisionQueue(list);
  res.json({ ok: true });
});

app.delete("/api/tv-provision/queue/:id", auth, adminOnly, function(req, res) {
  saveProvisionQueue(readProvisionQueue().filter(function(q) { return q.id !== req.params.id; }));
  res.json({ ok: true });
});

// ── Device API (shared secret, no session) ────────────────────────
// Rate limit per IP so a leaked endpoint can't be brute-forced cheaply.
const _provisionHits = new Map();
function provisionRateOk(ip) {
  const now = Date.now();
  const rec = _provisionHits.get(ip) || { count: 0, reset: now + 60000 };
  if (now > rec.reset) { rec.count = 0; rec.reset = now + 60000; }
  rec.count++;
  _provisionHits.set(ip, rec);
  if (_provisionHits.size > 5000) _provisionHits.clear();
  return rec.count <= 20;
}

app.post("/api/tv-provision/register", function(req, res) {
  const cfg = getProvisionConfig();
  const ip  = clientIp(req);
  if (!provisionRateOk(ip)) return res.status(429).json({ error: st("too_many_attempts", req) });
  if (!cfg.enabled)         return res.status(403).json({ error: st("provisioning_disabled", req) });

  const b = req.body || {};
  if (!secretMatches(b.secret, cfg.secret)) {
    console.warn("[tv-provision] Rejected registration from " + ip + " (bad secret)");
    return res.status(401).json({ error: st("invalid_key", req) });
  }
  const hostname = (b.hostname || "").toString().slice(0, 60).trim();
  const mac      = (b.mac || "").toString().slice(0, 20).trim().toLowerCase() || null;
  if (!hostname) return res.status(400).json({ error: st("hostname_missing", req) });

  // Known MAC → hand back the existing node, so a reflash or reboot
  // doesn't create a duplicate device.
  if (mac) {
    const known = readTvNodes().find(function(n) { return (n.mac || "").toLowerCase() === mac; });
    if (known) {
      // Update token and IP if the agent sent them (reflash scenario)
      if (b.token && b.token !== known.token) {
        var _nodes = readTvNodes();
        var _ni = _nodes.findIndex(function(n){ return n.id === known.id; });
        if (_ni >= 0) { _nodes[_ni].token = b.token; if (b.ip) _nodes[_ni].host = b.ip; _nodes[_ni].status = "registered"; saveTvNodes(_nodes); }
      }
      return res.json({ status: "approved", nodeId: known.id, token: known.token, deptId: known.deptId });
    }
  }

  const list = readProvisionQueue();
  const existing = mac
    ? list.find(function(q) { return q.mac === mac && q.status === "pending"; })
    : list.find(function(q) { return q.hostname === hostname && q.status === "pending"; });
  if (existing) return res.json({ status: "pending", id: existing.id });

  const entry = {
    id:          uuid(),
    hostname:    hostname,
    mac:         mac,
    model:       (b.model || "").toString().slice(0, 80) || null,
    ip:          ip,
    localIp:     (b.ip || "").toString().slice(0, 40) || null,
    dept:        (b.dept || "").toString().slice(0, 60) || null,
    agentToken:  (b.token || "").toString().slice(0, 100) || null,
    status:      "pending",
    requestedAt: new Date().toISOString(),
    nodeId:      null,
  };

  if (cfg.autoApprove) {
    const node = createNodeFromProvision(entry, cfg.defaultDeptId);
    entry.status    = "approved";
    entry.nodeId    = node.id;
    entry.handledAt = new Date().toISOString();
    entry.handledBy = "auto";
    list.push(entry);
    saveProvisionQueue(list);
    console.log("[tv-provision] Auto-approved " + hostname + " (" + (mac || "no mac") + ")");
    return res.json({ status: "approved", nodeId: node.id, token: node.token, deptId: node.deptId });
  }

  list.push(entry);
  saveProvisionQueue(list);
  console.log("[tv-provision] Queued " + hostname + " (" + (mac || "no mac") + ") for approval");
  res.json({ status: "pending", id: entry.id });
});

app.get("/api/tv-provision/poll", function(req, res) {
  const cfg = getProvisionConfig();
  const ip  = clientIp(req);
  if (!provisionRateOk(ip)) return res.status(429).json({ error: st("too_many_attempts", req) });
  if (!secretMatches(req.query.secret, cfg.secret)) return res.status(401).json({ error: st("invalid_key", req) });

  const mac      = (req.query.mac || "").toString().toLowerCase().trim();
  const hostname = (req.query.hostname || "").toString().trim();

  if (mac) {
    const node = readTvNodes().find(function(n) { return (n.mac || "").toLowerCase() === mac; });
    if (node) return res.json({ status: "approved", nodeId: node.id, token: node.token, deptId: node.deptId });
  }
  const list  = readProvisionQueue();
  const entry = mac
    ? list.slice().reverse().find(function(q) { return q.mac === mac; })
    : list.slice().reverse().find(function(q) { return q.hostname === hostname; });
  if (!entry) return res.json({ status: "not_found" });
  if (entry.status === "approved" && entry.nodeId) {
    const node = readTvNodes().find(function(n) { return n.id === entry.nodeId; });
    if (node) return res.json({ status: "approved", nodeId: node.id, token: node.token, deptId: node.deptId });
  }
  res.json({ status: entry.status });
});

// Returns the agent installer with this device's token baked in. Gated on
// the provisioning secret plus a matching node id, since the device has no
// session. Same script the one-line install command produces.
app.get("/api/tv-provision/installer", function(req, res) {
  const cfg = getProvisionConfig();
  const ip  = clientIp(req);
  res.setHeader("Content-Type", "text/x-shellscript");
  if (!provisionRateOk(ip))                        return res.status(429).send("# rate limited\n");
  if (!cfg.enabled)                                return res.status(403).send("# provisioning disabled\n");
  if (!secretMatches(req.query.secret, cfg.secret)) return res.status(401).send("# invalid secret\n");

  const node = readTvNodes().find(function(n) { return n.id === req.query.nodeId; });
  if (!node) return res.status(404).send("# unknown node\n");

  const proto = req.headers["x-forwarded-proto"] || req.protocol;
  const base  = proto + "://" + req.headers.host;
  res.send([
    "#!/usr/bin/env bash",
    "set -euo pipefail",
    "WORKDIR=$(mktemp -d)",
    "cd \"$WORKDIR\"",
    "echo '" + Buffer.from(TV_AGENT_JS).toString("base64") + "' | base64 -d > agent.js",
    "echo '" + Buffer.from(TV_AGENT_INSTALL_SH).toString("base64") + "' | base64 -d > install.sh",
    "chmod +x install.sh",
    "export TV_AGENT_TOKEN=" + JSON.stringify(node.token),
    "export TV_AGENT_NODE_ID=" + JSON.stringify(node.id),
    "export TV_AGENT_SERVER=" + JSON.stringify(base),
    "bash install.sh",
    "cd /",
    "rm -rf \"$WORKDIR\"",
  ].join("\n") + "\n");
});

// ══════════════════════════════════════════════════════════════════
// Kiosk image builder
// ══════════════════════════════════════════════════════════════════

// ── Embedded build scripts (written to a temp file per build) ─────
const TV_BUILD_PI_SH = "#!/bin/sh\n# Event-Admin kiosk SD-image builder (Raspberry Pi)\n# ------------------------------------------------------------------\n# Takes an official Raspberry Pi OS Lite image and writes the boot-time\n# configuration into it: hostname, user, SSH, WiFi, timezone and a\n# first-boot script that provisions the device against Event-Admin.\n#\n# The FAT boot partition is edited in place with mtools, so this needs\n# no loop device, no mount and no root \u2014 it runs in a normal container.\n#\n# Env in: EA_SERVER EA_SECRET EA_OUT EA_CACHE EA_BASE_URL EA_HOSTPREFIX\n#         EA_ROTATE EA_TIMEZONE EA_WIFI_SSID EA_WIFI_PASS EA_WIFI_COUNTRY\n#         EA_PI_USER EA_PI_PASS\nset -e\n\n: \"${EA_SERVER:?EA_SERVER required}\"\n: \"${EA_SECRET:?EA_SECRET required}\"\n: \"${EA_OUT:?EA_OUT required}\"\nEA_CACHE=\"${EA_CACHE:-/tmp/ea-base}\"\nEA_HOSTPREFIX=\"${EA_HOSTPREFIX:-tv}\"\nEA_ROTATE=\"${EA_ROTATE:-normal}\"\nEA_TIMEZONE=\"${EA_TIMEZONE:-Europe/Oslo}\"\nEA_WIFI_COUNTRY=\"${EA_WIFI_COUNTRY:-NO}\"\nEA_PI_USER=\"${EA_PI_USER:-pi}\"\n\nWORK=\"${TMPDIR:-/tmp}/ea-pi-$$\"\nmkdir -p \"$WORK\" \"$EA_CACHE\"\ncleanup() { rm -rf \"$WORK\"; }\ntrap cleanup EXIT INT TERM\n\nlog() { echo \"[pi] $*\"; }\n\n# \u2500\u2500 1. tools \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nneed_install=\"\"\nfor t in mcopy mdir xz gzip; do\n  command -v \"$t\" >/dev/null 2>&1 || need_install=\"$need_install $t\"\ndone\nif [ -n \"$need_install\" ]; then\n  log \"Missing tools:$need_install \u2014 attempting install\"\n  if command -v apk >/dev/null 2>&1; then\n    apk add --no-cache mtools xz gzip >/dev/null 2>&1 || true\n  elif command -v apt-get >/dev/null 2>&1; then\n    apt-get update -qq >/dev/null 2>&1 || true\n    DEBIAN_FRONTEND=noninteractive apt-get install -y -qq mtools xz-utils gzip >/dev/null 2>&1 || true\n  fi\nfi\nfor t in mcopy xz gzip; do\n  command -v \"$t\" >/dev/null 2>&1 || { echo \"[error] Required tool missing: $t (install the 'mtools' and 'xz' packages in the container image)\"; exit 1; }\ndone\nlog \"Tools OK: $(mcopy --version 2>&1 | head -1)\"\n\n# Downloader\nif command -v curl >/dev/null 2>&1; then\n  fetch() { curl -fL --retry 3 --connect-timeout 20 -o \"$1\" \"$2\"; }\nelif command -v wget >/dev/null 2>&1; then\n  fetch() { wget -q -O \"$1\" \"$2\"; }\nelse\n  echo \"[error] Neither curl nor wget is available\"; exit 1\nfi\n\n# \u2500\u2500 2. base image (cached) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nBASE_XZ=\"$EA_CACHE/raspios-lite.img.xz\"\nif [ -s \"$BASE_XZ\" ]; then\n  log \"Using cached base image: $(du -h \"$BASE_XZ\" | cut -f1)\"\nelse\n  log \"Downloading base image (this takes a few minutes)...\"\n  fetch \"$BASE_XZ.part\" \"$EA_BASE_URL\"\n  mv \"$BASE_XZ.part\" \"$BASE_XZ\"\n  log \"Downloaded: $(du -h \"$BASE_XZ\" | cut -f1)\"\nfi\n\n# \u2500\u2500 3. decompress \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nIMG=\"$WORK/work.img\"\nlog \"Decompressing base image...\"\nxz -dc \"$BASE_XZ\" > \"$IMG\"\nlog \"Image size: $(du -h \"$IMG\" | cut -f1)\"\n\n# \u2500\u2500 4. locate the FAT boot partition (MBR entry 1, LBA start @ 0x1C6) \u2500\u2500\nLBA=$(od -An -t u1 -j 454 -N 4 \"$IMG\" | awk '{print $1 + $2*256 + $3*65536 + $4*16777216}')\nif [ -z \"$LBA\" ] || [ \"$LBA\" -le 0 ] 2>/dev/null; then\n  echo \"[error] Could not read partition table \u2014 is this a Raspberry Pi OS image?\"; exit 1\nfi\nOFFSET=$((LBA * 512))\nlog \"Boot partition at offset $OFFSET (LBA $LBA)\"\nexport MTOOLS_SKIP_CHECK=1\nmdir -i \"$IMG@@$OFFSET\" :: >/dev/null 2>&1 || { echo \"[error] Boot partition is not readable as FAT\"; exit 1; }\n\n# \u2500\u2500 5. build the config files \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# Password hash for the default user. Pi OS refuses to boot without a user.\nif [ -n \"$EA_PI_PASS\" ]; then\n  if command -v openssl >/dev/null 2>&1; then\n    PASS_HASH=$(openssl passwd -6 \"$EA_PI_PASS\")\n  elif command -v python3 >/dev/null 2>&1; then\n    PASS_HASH=$(python3 -c 'import crypt,os,sys; print(crypt.crypt(sys.argv[1], crypt.mksalt(crypt.METHOD_SHA512)))' \"$EA_PI_PASS\")\n  else\n    echo \"[error] Need openssl or python3 to hash the device password\"; exit 1\n  fi\n  printf '%s:%s\\n' \"$EA_PI_USER\" \"$PASS_HASH\" > \"$WORK/userconf.txt\"\n  mcopy -o -i \"$IMG@@$OFFSET\" \"$WORK/userconf.txt\" ::userconf.txt\n  log \"User configured: $EA_PI_USER\"\nfi\n\n# Enable SSH\n: > \"$WORK/ssh\"\nmcopy -o -i \"$IMG@@$OFFSET\" \"$WORK/ssh\" ::ssh\n\n# WiFi (ignored by the OS when an ethernet cable is present)\nif [ -n \"$EA_WIFI_SSID\" ]; then\n  cat > \"$WORK/wpa_supplicant.conf\" <<WPAEOF\ncountry=$EA_WIFI_COUNTRY\nctrl_interface=DIR=/var/run/wpa_supplicant GROUP=netdev\nupdate_config=1\nnetwork={\n\tssid=\"$EA_WIFI_SSID\"\n\tpsk=\"$EA_WIFI_PASS\"\n}\nWPAEOF\n  mcopy -o -i \"$IMG@@$OFFSET\" \"$WORK/wpa_supplicant.conf\" ::wpa_supplicant.conf\n  log \"WiFi configured: $EA_WIFI_SSID\"\nfi\n\n# First-boot script\ncat > \"$WORK/firstrun.sh\" <<FIRSTEOF\n#!/bin/bash\n# Event-Admin kiosk provisioning \u2014 runs once on first boot\nset +e\nexec >> /var/log/eventadmin-firstrun.log 2>&1\necho \"=== Event-Admin provisioning \\$(date) ===\"\n\nSERVER=\"$EA_SERVER\"\nSECRET=\"$EA_SECRET\"\nROTATE=\"$EA_ROTATE\"\n\n# --- hostname: prefix + last 3 bytes of the MAC, so it is stable and unique\nMAC=\\$(cat /sys/class/net/*/address 2>/dev/null | grep -v '00:00:00:00:00:00' | head -1)\nSUFFIX=\\$(echo \"\\$MAC\" | tr -d ':' | tail -c 7)\nNEWHOST=\"$EA_HOSTPREFIX-\\${SUFFIX:-\\$RANDOM}\"\nOLDHOST=\\$(cat /etc/hostname | tr -d ' \\t\\n\\r')\necho \"\\$NEWHOST\" > /etc/hostname\nsed -i \"s/127.0.1.1.*\\$OLDHOST/127.0.1.1\\t\\$NEWHOST/g\" /etc/hosts\nhostnamectl set-hostname \"\\$NEWHOST\" 2>/dev/null\n\n# --- timezone\nrm -f /etc/localtime\necho \"$EA_TIMEZONE\" > /etc/timezone\ndpkg-reconfigure -f noninteractive tzdata 2>/dev/null\n\n# --- rotation (applied by the kiosk session)\nmkdir -p /etc/tv-agent\necho \"ROTATE=\\$ROTATE\" > /etc/tv-agent/display.env\n\nsystemctl enable ssh 2>/dev/null\nsystemctl start  ssh 2>/dev/null\n\n# --- wait for a working network\nfor i in \\$(seq 1 60); do\n  ping -c1 -W2 1.1.1.1 >/dev/null 2>&1 && break\n  getent hosts \"\\$(echo \"\\$SERVER\" | sed -e 's|^https\\\\?://||' -e 's|[:/].*$||')\" >/dev/null 2>&1 && break\n  sleep 5\ndone\n\ncommand -v curl >/dev/null 2>&1 || { apt-get update -qq; apt-get install -y -qq curl; }\n\njson_field() { echo \"\\$1\" | grep -o \"\\\"\\$2\\\":\\\"[^\\\"]*\\\"\" | head -1 | cut -d'\"' -f4; }\n\n# --- register, then poll until IT approves\nNODE_ID=\"\"\nfor attempt in \\$(seq 1 120); do\n  RESP=\\$(curl -fsS -m 25 -X POST \"\\$SERVER/api/tv-provision/register\" \\\\\n    -H 'Content-Type: application/json' \\\\\n    -d \"{\\\\\"secret\\\\\":\\\\\"\\$SECRET\\\\\",\\\\\"hostname\\\\\":\\\\\"\\$NEWHOST\\\\\",\\\\\"mac\\\\\":\\\\\"\\$MAC\\\\\",\\\\\"model\\\\\":\\\\\"\\$(tr -d '\\\\0' < /proc/device-tree/model 2>/dev/null)\\\\\"}\" 2>/dev/null)\n  STATUS=\\$(json_field \"\\$RESP\" status)\n  echo \"attempt \\$attempt: \\$STATUS\"\n  if [ \"\\$STATUS\" = \"approved\" ]; then\n    NODE_ID=\\$(json_field \"\\$RESP\" nodeId)\n    break\n  fi\n  if [ \"\\$STATUS\" = \"rejected\" ]; then\n    echo \"Rejected by Event-Admin \u2014 stopping.\"\n    break\n  fi\n  sleep 15\n  RESP=\\$(curl -fsS -m 25 \"\\$SERVER/api/tv-provision/poll?secret=\\$SECRET&mac=\\$MAC&hostname=\\$NEWHOST\" 2>/dev/null)\n  STATUS=\\$(json_field \"\\$RESP\" status)\n  if [ \"\\$STATUS\" = \"approved\" ]; then\n    NODE_ID=\\$(json_field \"\\$RESP\" nodeId)\n    break\n  fi\n  sleep 15\ndone\n\n# --- install the agent + kiosk once approved\nif [ -n \"\\$NODE_ID\" ]; then\n  echo \"Approved as node \\$NODE_ID \u2014 installing agent\"\n  curl -fsSL \"\\$SERVER/api/tv-provision/installer?secret=\\$SECRET&nodeId=\\$NODE_ID\" | bash\n  echo \"Agent install finished with code \\$?\"\nelse\n  echo \"Not approved yet. Re-running provisioning at next boot.\"\n  cp /boot/firstrun.sh /boot/firmware/firstrun.sh 2>/dev/null\n  exit 0\nfi\n\n# --- clean up so this only runs once\nrm -f /boot/firstrun.sh /boot/firmware/firstrun.sh\nsed -i 's| systemd.run=[^ ]*||g; s| systemd.run_success_action=[^ ]*||g; s| systemd.unit=[^ ]*||g' /boot/cmdline.txt 2>/dev/null\nsed -i 's| systemd.run=[^ ]*||g; s| systemd.run_success_action=[^ ]*||g; s| systemd.unit=[^ ]*||g' /boot/firmware/cmdline.txt 2>/dev/null\necho \"=== provisioning complete ===\"\nexit 0\nFIRSTEOF\nmcopy -o -i \"$IMG@@$OFFSET\" \"$WORK/firstrun.sh\" ::firstrun.sh\nlog \"First-boot script written\"\n\n# \u2500\u2500 6. patch cmdline.txt so firstrun.sh actually runs \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nmtype -i \"$IMG@@$OFFSET\" ::cmdline.txt > \"$WORK/cmdline.txt\" 2>/dev/null || {\n  echo \"[error] Could not read cmdline.txt from the boot partition\"; exit 1; }\n# strip any previous firstrun hooks, then append ours (must stay one line)\nCMD=$(tr -d '\\n\\r' < \"$WORK/cmdline.txt\" \\\n  | sed -e 's| systemd.run=[^ ]*||g' -e 's| systemd.run_success_action=[^ ]*||g' -e 's| systemd.unit=[^ ]*||g')\nprintf '%s systemd.run=/boot/firstrun.sh systemd.run_success_action=reboot systemd.unit=kernel-command-line.target\\n' \"$CMD\" > \"$WORK/cmdline.new\"\nmcopy -o -i \"$IMG@@$OFFSET\" \"$WORK/cmdline.new\" ::cmdline.txt\nlog \"cmdline.txt patched\"\n\n# \u2500\u2500 7. compress \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nlog \"Compressing (this takes a while)...\"\ngzip -1 -c \"$IMG\" > \"$EA_OUT\"\nlog \"Done: $EA_OUT ($(du -h \"$EA_OUT\" | cut -f1))\"\n";

const TV_BUILD_X86_SH = "#!/bin/sh\n# Event-Admin kiosk ISO builder (x86 thin clients, old PCs, laptops)\n# ------------------------------------------------------------------\n# Ported from PiScreen's build-kiosk-iso.sh, with provisioning pointed\n# at Event-Admin and the Node tv-agent instead of the Python agent.\n#\n# Boots Alpine from RAM, installs a kiosk session, provisions against\n# Event-Admin and starts Chromium on the assigned department channel.\n#\n# Env in: EA_SERVER EA_SECRET EA_OUT EA_ROTATE EA_WIFI_SSID EA_WIFI_PASS\nset -e\n\n: \"${EA_SERVER:?EA_SERVER required}\"\n: \"${EA_SECRET:?EA_SECRET required}\"\n: \"${EA_OUT:?EA_OUT required}\"\nEA_ROTATE=\"${EA_ROTATE:-normal}\"\n\nlog() { echo \"[iso] $*\"; }\n\nif ! command -v xorriso >/dev/null 2>&1; then\n  log \"Installing xorriso...\"\n  if command -v apk >/dev/null 2>&1; then\n    apk add --no-cache xorriso >/dev/null 2>&1 || true\n  elif command -v apt-get >/dev/null 2>&1; then\n    apt-get update -qq >/dev/null 2>&1 || true\n    DEBIAN_FRONTEND=noninteractive apt-get install -y -qq xorriso >/dev/null 2>&1 || true\n  fi\nfi\ncommand -v xorriso >/dev/null 2>&1 || { echo \"[error] xorriso not available \u2014 install it in the container image\"; exit 1; }\nlog \"xorriso: $(xorriso --version 2>&1 | head -1)\"\n\nif command -v curl >/dev/null 2>&1; then\n  fetch() { curl -fL --retry 3 --connect-timeout 20 -o \"$1\" \"$2\"; }\nelse\n  fetch() { wget -q -O \"$1\" \"$2\"; }\nfi\n\nALPINE_VER=\"3.19\"\nBASE_URL=\"https://dl-cdn.alpinelinux.org/alpine/v${ALPINE_VER}/releases/x86_64\"\nWORK=\"${TMPDIR:-/tmp}/ea-iso-$$\"\nISOROOT=\"$WORK/iso\"\nmkdir -p \"$ISOROOT/boot/grub\" \"$ISOROOT/eventadmin\" \"$ISOROOT/etc/local.d\"\ncleanup() { rm -rf \"$WORK\"; }\ntrap cleanup EXIT INT TERM\n\nlog \"Downloading Alpine ${ALPINE_VER} netboot...\"\nfetch \"$ISOROOT/boot/vmlinuz\"   \"$BASE_URL/netboot/vmlinuz-lts\"\nfetch \"$ISOROOT/boot/initramfs\" \"$BASE_URL/netboot/initramfs-lts\"\nfetch \"$ISOROOT/boot/modloop\"   \"$BASE_URL/netboot/modloop-lts\"\nlog \"Netboot files downloaded\"\n\ncat > \"$ISOROOT/eventadmin/kiosk.conf\" <<CONFEOF\nEA_SERVER=${EA_SERVER}\nEA_SECRET=${EA_SECRET}\nROTATE=${EA_ROTATE}\nWIFI_SSID=${EA_WIFI_SSID}\nWIFI_PASS=${EA_WIFI_PASS}\nCONFEOF\n\ncat > \"$ISOROOT/eventadmin/kiosk.sh\" <<'KIOSKEOF'\n#!/bin/sh\n# Event-Admin kiosk startup (runs inside the live Alpine system)\nfor mnt in /media/usb /media/sda1 /media/sdb1 /media/cdrom /media/sr0; do\n  [ -f \"$mnt/eventadmin/kiosk.conf\" ] && CONF=\"$mnt/eventadmin/kiosk.conf\" && break\ndone\n[ -z \"$CONF\" ] && echo \"No kiosk.conf found\" && sleep 30 && exit 1\n. \"$CONF\"\n\necho \"Event-Admin kiosk \u2014 server: $EA_SERVER\"\n\napk add --quiet --no-cache \\\n  nodejs npm curl \\\n  xorg-server xf86-video-fbdev xf86-video-vesa xf86-input-evdev xf86-input-libinput \\\n  xinit openbox chromium \\\n  dhcpcd wpa_supplicant xset xrandr font-noto 2>/dev/null\n\nip link set eth0 up 2>/dev/null\ndhcpcd -q eth0 2>/dev/null &\nsleep 4\n\nif [ -n \"$WIFI_SSID\" ] && ! ip addr show eth0 2>/dev/null | grep -q \"inet \"; then\n  ip link set wlan0 up 2>/dev/null\n  wpa_passphrase \"$WIFI_SSID\" \"$WIFI_PASS\" > /tmp/wpa.conf 2>/dev/null\n  wpa_supplicant -B -D nl80211,wext -i wlan0 -c /tmp/wpa.conf 2>/dev/null\n  dhcpcd -q wlan0 2>/dev/null &\n  sleep 6\nfi\n\nMAC=$(cat /sys/class/net/eth0/address 2>/dev/null || cat /sys/class/net/wlan0/address 2>/dev/null)\nHOST=\"kiosk-$(echo \"$MAC\" | tr -d ':' | tail -c 7)\"\nhostname \"$HOST\"\n\njson_field() { echo \"$1\" | grep -o \"\\\"$2\\\":\\\"[^\\\"]*\\\"\" | head -1 | cut -d'\"' -f4; }\n\n# Register and wait for approval\nNODE_ID=\"\"\nfor i in $(seq 1 120); do\n  RESP=$(curl -fsS -m 25 -X POST \"$EA_SERVER/api/tv-provision/register\" \\\n    -H 'Content-Type: application/json' \\\n    -d \"{\\\"secret\\\":\\\"$EA_SECRET\\\",\\\"hostname\\\":\\\"$HOST\\\",\\\"mac\\\":\\\"$MAC\\\",\\\"model\\\":\\\"x86 kiosk\\\"}\" 2>/dev/null)\n  S=$(json_field \"$RESP\" status)\n  [ \"$S\" = \"approved\" ] && NODE_ID=$(json_field \"$RESP\" nodeId) && break\n  sleep 15\n  RESP=$(curl -fsS -m 25 \"$EA_SERVER/api/tv-provision/poll?secret=$EA_SECRET&mac=$MAC&hostname=$HOST\" 2>/dev/null)\n  S=$(json_field \"$RESP\" status)\n  [ \"$S\" = \"approved\" ] && NODE_ID=$(json_field \"$RESP\" nodeId) && break\n  sleep 15\ndone\n\nif [ -n \"$NODE_ID\" ]; then\n  curl -fsSL \"$EA_SERVER/api/tv-provision/installer?secret=$EA_SECRET&nodeId=$NODE_ID\" -o /tmp/inst.sh 2>/dev/null\n  sh /tmp/inst.sh 2>/dev/null || true\nfi\n\nmkdir -p /etc/X11/xorg.conf.d\ncat > /etc/X11/xorg.conf.d/99-eventadmin.conf <<'XEOF'\nSection \"ServerFlags\"\n  Option \"BlankTime\" \"0\"\n  Option \"StandbyTime\" \"0\"\n  Option \"SuspendTime\" \"0\"\n  Option \"OffTime\" \"0\"\nEndSection\nXEOF\n\nmkdir -p /root/.config/openbox\ncat > /root/.config/openbox/autostart <<OBEOF\nxset s off &\nxset s noblank &\nxset -dpms &\nxrandr -o ${ROTATE:-normal} &\nsleep 2\nchromium-browser --kiosk --noerrdialogs --disable-infobars \\\n  --disable-session-crashed-bubble --check-for-update-interval=31536000 \\\n  \"$EA_SERVER/tv/pending?node=$NODE_ID\" &\nOBEOF\n\nexec startx /usr/bin/openbox-session -- :0 vt1 -nolisten tcp 2>&1 | logger -t eventadmin\nKIOSKEOF\nchmod +x \"$ISOROOT/eventadmin/kiosk.sh\"\n\ncat > \"$ISOROOT/etc/local.d/eventadmin.start\" <<'LOCALEOF'\n#!/bin/sh\nfor mnt in /media/usb /media/sda1 /media/sdb1 /media/cdrom /media/sr0; do\n  if [ -f \"$mnt/eventadmin/kiosk.sh\" ]; then\n    cp \"$mnt/eventadmin/kiosk.sh\" /tmp/kiosk.sh && chmod +x /tmp/kiosk.sh\n    /tmp/kiosk.sh &\n    exit 0\n  fi\ndone\nLOCALEOF\nchmod +x \"$ISOROOT/etc/local.d/eventadmin.start\"\n\ncat > \"$ISOROOT/boot/grub/grub.cfg\" <<GRUBEOF\nset timeout=3\nset default=0\nmenuentry \"Event-Admin Kiosk\" {\n  linux  /boot/vmlinuz modules=loop,squashfs,sd-mod,usb-storage,ext4 alpine_dev=usb:vfat modloop=/boot/modloop quiet loglevel=1 console=tty1\n  initrd /boot/initramfs\n}\nmenuentry \"Event-Admin Kiosk (verbose)\" {\n  linux  /boot/vmlinuz modules=loop,squashfs,sd-mod,usb-storage,ext4 alpine_dev=usb:vfat modloop=/boot/modloop console=tty1\n  initrd /boot/initramfs\n}\nGRUBEOF\n\nlog \"Building ISO...\"\nxorriso -as mkisofs -r -V \"EA-KIOSK\" -J -joliet-long -o \"$EA_OUT\" \"$ISOROOT\" 2>&1\nlog \"Done: $EA_OUT ($(du -h \"$EA_OUT\" 2>/dev/null | cut -f1))\"\n";

const _tvImageBuilds = {};

function tvImageBuildLog(id, line) {
  const b = _tvImageBuilds[id];
  if (!b) return;
  b.log.push(line);
  if (b.log.length > 400) b.log.splice(0, b.log.length - 400);
  console.log("[tv-image] " + line);
}

app.get("/api/tv-image/status", auth, adminOnly, function(req, res) {
  ensureTvImageDirs();
  let files = [];
  try {
    files = fs.readdirSync(TV_IMAGE_DIR)
      .filter(function(f) { return /\.(img\.gz|iso)$/.test(f); })
      .map(function(f) {
        const st = fs.statSync(path.join(TV_IMAGE_DIR, f));
        return { name: f, size: st.size, created: st.mtime };
      })
      .sort(function(a, b) { return b.created - a.created; });
  } catch(e) {}
  const builds = {};
  Object.keys(_tvImageBuilds).forEach(function(k) {
    builds[k] = {
      status: _tvImageBuilds[k].status,
      type:   _tvImageBuilds[k].type,
      started: _tvImageBuilds[k].started,
      outName: _tvImageBuilds[k].outName,
    };
  });
  res.json({ builds: builds, files: files });
});

app.get("/api/tv-image/log/:id", auth, adminOnly, function(req, res) {
  const b = _tvImageBuilds[req.params.id];
  if (!b) return res.status(404).json({ error: "Ukjent bygg" });
  res.json({ status: b.status, log: b.log, outName: b.outName, type: b.type });
});

app.get("/api/tv-image/download/:name", auth, adminOnly, function(req, res) {
  const name = path.basename(req.params.name);
  const p    = path.join(TV_IMAGE_DIR, name);
  if (!fs.existsSync(p)) return res.status(404).json({ error: st("file_not_found", req) });
  res.download(p, name);
});

app.delete("/api/tv-image/:name", auth, adminOnly, function(req, res) {
  const name = path.basename(req.params.name);
  try { fs.unlinkSync(path.join(TV_IMAGE_DIR, name)); } catch(e) {}
  res.json({ ok: true });
});

app.post("/api/tv-image/build", auth, adminOnly, function(req, res) {
  if (IS_DEMO) return res.status(403).json({ error: st("not_available_in_demo", req) });
  ensureTvImageDirs();

  const cfg = getProvisionConfig();
  if (!cfg.enabled || !cfg.secret) {
    return res.status(400).json({ error: st("enable_provisioning_first", req) });
  }
  if (Object.keys(_tvImageBuilds).some(function(k) { return _tvImageBuilds[k].status === "building"; })) {
    return res.status(409).json({ error: st("build_already_running", req) });
  }

  const b     = req.body || {};
  const type  = b.type === "x86" ? "x86" : "pi";
  const label = (b.label || "kiosk").toLowerCase().replace(/[^a-z0-9-]/g, "-").slice(0, 24) || "kiosk";
  const proto = req.headers["x-forwarded-proto"] || req.protocol;
  const server = (b.serverUrl || (proto + "://" + req.headers.host)).replace(/\/+$/, "");

  const buildId = label + "-" + Date.now();
  const outName = type === "pi"
    ? "eventadmin-kiosk-" + label + "-" + Date.now() + ".img.gz"
    : "eventadmin-kiosk-" + label + "-" + Date.now() + ".iso";
  const outPath = path.join(TV_IMAGE_DIR, outName);

  _tvImageBuilds[buildId] = {
    status: "building", type: type, started: new Date().toISOString(),
    log: [], outName: null,
  };
  res.json({ ok: true, buildId: buildId, outName: outName });

  // Script is written fresh each build so an update to the app updates it too
  const scriptPath = path.join(require("os").tmpdir(), "ea-build-" + buildId + ".sh");
  try {
    fs.writeFileSync(scriptPath, type === "pi" ? TV_BUILD_PI_SH : TV_BUILD_X86_SH, { mode: 0o700 });
  } catch(e) {
    _tvImageBuilds[buildId].status = "failed";
    return tvImageBuildLog(buildId, "[error] Kunne ikke skrive byggeskript: " + e.message);
  }

  const env = Object.assign({}, process.env, {
    EA_SERVER:       server,
    EA_SECRET:       cfg.secret,
    EA_OUT:          outPath,
    EA_CACHE:        TV_IMAGE_CACHE,
    EA_LABEL:        label,
    EA_BASE_URL:     (b.baseUrl || PI_OS_DEFAULT_URL),
    EA_HOSTPREFIX:   (b.hostPrefix || "tv").replace(/[^a-zA-Z0-9-]/g, "").slice(0, 20) || "tv",
    EA_ROTATE:       ["normal", "left", "right", "inverted"].indexOf(b.rotate) >= 0 ? b.rotate : "normal",
    EA_TIMEZONE:     (b.timezone || "Europe/Oslo").replace(/[^A-Za-z0-9\/_+-]/g, "").slice(0, 40),
    EA_WIFI_SSID:    (b.wifiSsid || "").slice(0, 64),
    EA_WIFI_PASS:    (b.wifiPass || "").slice(0, 128),
    EA_WIFI_COUNTRY: (b.wifiCountry || "NO").replace(/[^A-Z]/gi, "").slice(0, 2).toUpperCase() || "NO",
    EA_PI_USER:      (b.piUser || "pi").replace(/[^a-z0-9_-]/gi, "").slice(0, 20) || "pi",
    EA_PI_PASS:      (b.piPass || "").slice(0, 128),
    PATH:            "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin",
  });

  tvImageBuildLog(buildId, "[info] Type: " + type + "  Server: " + server);
  tvImageBuildLog(buildId, "[info] Output: " + outName);

  const proc = require("child_process").spawn("sh", [scriptPath], { env: env, stdio: ["ignore", "pipe", "pipe"] });
  let outBuf = "", errBuf = "";

  proc.stdout.on("data", function(d) {
    outBuf += d.toString();
    const lines = outBuf.split("\n");
    outBuf = lines.pop();
    lines.forEach(function(l) { l = l.replace(/\r/g, "").trim(); if (l) tvImageBuildLog(buildId, l); });
  });
  proc.stderr.on("data", function(d) {
    errBuf += d.toString();
    const lines = errBuf.split("\n");
    errBuf = lines.pop();
    lines.forEach(function(l) {
      l = l.replace(/\r.*$/, "").trim();
      if (l && !/^[\s.]+$/.test(l)) tvImageBuildLog(buildId, l.startsWith("[") ? l : "[stderr] " + l);
    });
  });
  proc.on("close", function(code) {
    if (outBuf.trim()) tvImageBuildLog(buildId, outBuf.trim());
    if (errBuf.trim()) tvImageBuildLog(buildId, "[stderr] " + errBuf.trim());
    try { fs.unlinkSync(scriptPath); } catch(e) {}
    const ok = code === 0 && fs.existsSync(outPath);
    _tvImageBuilds[buildId].status  = ok ? "done" : "failed";
    _tvImageBuilds[buildId].outName = ok ? outName : null;
    if (!ok) { try { fs.unlinkSync(outPath); } catch(e) {} }
    tvImageBuildLog(buildId, ok ? "[done] Ferdig: " + outName : "[error] Bygget feilet (kode " + code + ")");
  });
  proc.on("error", function(err) {
    _tvImageBuilds[buildId].status = "failed";
    tvImageBuildLog(buildId, "[error] Kunne ikke starte bygget: " + err.message);
  });
});

// Agent calls this once after install to report its own Tailscale IP and
// flip the device record from "pending" to "registered". Authenticated by
// the device's own token (not a session) since the Pi has no admin login.
app.post("/api/tv-nodes/:id/checkin", function (req, res) {
  var list = readTvNodes();
  var idx = list.findIndex(function (n) { return n.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: "Not found" });
  var node = list[idx];
  var presented = (req.headers["x-agent-token"] || "").trim();
  if (!presented || presented !== node.token) return res.status(401).json({ error: "Invalid token" });

  var host = (req.body && req.body.host || "").trim();
  if (host) node.host = host;
  node.status = "registered";
  node.lastCheckin = new Date().toISOString();
  saveTvNodes(list);
  res.json({ ok: true });
});

// Agent (or install.sh, before the systemd service is even running) calls this
// to fetch the department's TV URL it should display. Token-gated the same way.
app.get("/api/tv-nodes/:id/kiosk-url", function (req, res) {
  var node = readTvNodes().find(function (n) { return n.id === req.params.id; });
  if (!node) return res.status(404).json({ error: "Not found" });
  var presented = (req.headers["x-agent-token"] || "").trim();
  if (!presented || presented !== node.token) return res.status(401).json({ error: "Invalid token" });

  if (!node.deptId) return res.status(404).json({ error: st("device_not_linked_prefix", req) + deptWord() + " ennå" });
  var s = getSettings();
  var dept = (s.departments || []).find(function (d) { return d.id === node.deptId; });
  if (!dept) return res.status(404).json({ error: st("department_gone", req) });
  var slug = dept.slug || dept.id;
  var proto = req.headers["x-forwarded-proto"] || req.protocol;
  var host = req.headers.host;
  var url = proto + "://" + slug + "." + DOMAIN;
  // Fall back to same-host path style if DOMAIN-based subdomain routing isn't configured
  res.json({ ok: true, url: url, deptName: dept.name });
});

// ── TV Channel API ──────────────────────────────────────────────

// SSE stream for TV channel
// ── TV preview of a single event (admin event list) ──────────────
// The TV page opened as /tv/<dept>?preview=1&event=<id> shows only this
// event, without SSE, cameras or broadcasting to companion screens.
app.get("/api/tv-preview/event/:id", auth, function(req, res) {
  const e = readJSON(EVENTS_FILE).find(function(x) { return x.id === req.params.id; });
  if (!e) return res.status(404).json({ error: "Not found" });
  if (e.department && !hasDeptAccess(req.session.user, e.department)) return res.status(403).json({ error: "Forbidden" });
  try {
    const regs = (e.registrations || []).filter(function(r) { return !r.anonymized; });
    let routeSummary = null;
    if (e.route && Array.isArray(e.route.days) && e.route.days.length) {
      let km = 0; const stops = [];
      e.route.days.forEach(function(d) { ((d && d.stages) || []).forEach(function(et) {
        if (et && et.from && stops.indexOf(et.from) === -1) stops.push(et.from);
        if (et && et.to && stops.indexOf(et.to) === -1) stops.push(et.to);
        if (et && et.km) km += parseFloat(et.km) || 0;
      }); });
      routeSummary = { days: e.route.days.length, km: km > 0 ? Math.round(km) : null, stops: stops.slice(0, 4) };
    }
    const gbPhotos = [];
    (e.guestbook || []).forEach(function(g) { if (g.approved) (g.photos || []).forEach(function(p) { if (p) gbPhotos.push(p); }); });
    const ev = {
      id: e.id, title: e.title, date: e.date, endDate: e.endDate || null, endTime: e.endTime || null,
      location: e.location, eventType: e.eventType, image: e.image || null, ..._tvSubgroupInfo(e),
      tvImageTop: e.tvImageTop || null, tvImageBottom: e.tvImageBottom || null,
      description: e.description ? String(e.description).slice(0, 300) : null,
      registrationCount: regs.length, maxParticipants: e.maxParticipants || null,
      routeSummary, routeMapImage: e.routeMapImage || null, dayMapImages: e.dayMapImages || null,
      liveTrackingUrl: e.liveTrackingUrl || null, gbPhotos, tvSidePhotos: e.tvSidePhotos || [],
      cancelled: !!e.cancelled, cancelReason: e.cancelReason || null, status: e.status || null,
      rescheduledToDate: e.rescheduledToDate || null, rescheduledToUrl: e.rescheduledToUrl || null, movedNote: e.movedNote || null,
    };
    const st8 = getTvState(e.department || "");
    res.json({
      event: ev,
      state: { slideInterval: st8.slideInterval, ticker: "", showLogo: st8.showLogo, progressColor: st8.progressColor },
      typeNames: getSettings().typeNames || {}, typeColors: getSettings().typeColors || {}, colors: getSettings().colors || {},
    });
  } catch (err) { res.status(500).json({ error: "Preview failed" }); }
});

app.get("/api/tv/:deptId/stream", function(req, res) {
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders();
  const clientId = tvNextId++;
  const deptId = req.params.deptId;   // department or «dept~group»
  tvClients.set(clientId, { res, deptId });
  const state = getTvState(_tvChan(deptId).dept);
  // Include upcoming events for this dept (or group)
  const events = readJSON(EVENTS_FILE);
  const now = Date.now();
  const upcoming = events
    .filter(function(e) {
        if (!_tvEventIn(e, deptId) || !e.date || e.hideFromList) return false;
        // If cancelled and replaced by a new event, hide the old shell from TV
        if (e.cancelled && e.rescheduledTo) return false;
        var startMs = new Date(e.date).getTime();
        // Always include ongoing events (started any time, not yet ended)
        var endMs = (function() {
          var ed = e.endDate ? new Date(e.endDate) : new Date(e.date);
          if (e.endTime) { var p = e.endTime.split(":"); ed.setHours(+p[0], +p[1], 59, 999); }
          else ed.setHours(23, 59, 59, 999);
          return ed.getTime();
        })();
        var isOngoingNow = startMs <= now && endMs >= now;
        if (isOngoingNow) return true;
        // Include upcoming events (starting within next 30 days)
        return startMs > now - 3600000; // Show all upcoming events
      })
    .sort(function(a, b) {
        // Ongoing events first, then by date
        var nowMs = Date.now();
        var aStart = new Date(a.date).getTime();
        var bStart = new Date(b.date).getTime();
        var aOngoing = aStart <= nowMs;
        var bOngoing = bStart <= nowMs;
        if (aOngoing && !bOngoing) return -1;
        if (!aOngoing && bOngoing) return 1;
        return aStart - bStart;
      })
    .slice(0, state.eventCount || 5)
    .map(function(e) {
        try {
          var regs = (e.registrations || []).filter(function(r){ return !r.anonymized; });
          var route = e.route || null;
          var routeSummary = null;
          if (route && Array.isArray(route.days) && route.days.length) {
            var totalKm = 0;
            var stops = [];
            route.days.forEach(function(d) {
              ((d && d.stages) || []).forEach(function(et) {
                if (et && et.from && stops.indexOf(et.from) === -1) stops.push(et.from);
                if (et && et.to && stops.indexOf(et.to) === -1) stops.push(et.to);
                if (et && et.km) totalKm += parseFloat(et.km) || 0;
              });
            });
            routeSummary = {
              days: route.days.length,
              km: totalKm > 0 ? Math.round(totalKm) : null,
              stops: stops.slice(0, 4),
            };
          }
          return {
            id: e.id, title: e.title, date: e.date,
            endDate: e.endDate || null, endTime: e.endTime || null,
            location: e.location, eventType: e.eventType, image: e.image || null,
            ..._tvSubgroupInfo(e),
            tvImageTop: e.tvImageTop || null, tvImageBottom: e.tvImageBottom || null,
            description: e.description ? String(e.description).slice(0, 300) : null,
            registrationCount: regs.length,
            maxParticipants: e.maxParticipants || null,
            routeSummary: routeSummary,
            routeMapImage: e.routeMapImage || null,
            dayMapImages: e.dayMapImages || null,
            liveTrackingUrl: e.liveTrackingUrl || null,
            cancelled: !!e.cancelled,
            cancelReason: e.cancelReason || null,
            status: e.status || null,
            rescheduledToDate: e.rescheduledToDate || null,
            rescheduledToUrl: e.rescheduledToUrl || null,
            movedNote: e.movedNote || null,
          };
        } catch(mapErr) {
          return { id: e.id, title: e.title, date: e.date, location: e.location, eventType: e.eventType, image: e.image || null };
        }
      });
  res.write("data: " + JSON.stringify(Object.assign({ type: "state" }, state, { upcoming }, {
    typeNames:  (getSettings().typeNames  || {}),
    typeColors: (getSettings().typeColors || {}),
    colors:     (getSettings().colors    || {}),
  })) + "\n\n");
  const keepAlive = setInterval(function() {
    try { res.write(": keepalive\n\n"); } catch(e) {}
  }, 25000);
  req.on("close", function() { tvClients.delete(clientId); clearInterval(keepAlive); });
});

// Get TV state
app.get("/api/tv/:deptId/state", function(req, res) {
  const state = getTvState(_tvChan(req.params.deptId).dept);
  const events = readJSON(EVENTS_FILE);
  const now = Date.now();
  const upcoming = events
    .filter(function(e) {
        if (!_tvEventIn(e, req.params.deptId) || !e.date || e.hideFromList) return false;
        var sMs = new Date(e.date).getTime();
        var eD = e.endDate ? new Date(e.endDate) : new Date(e.date);
        if (e.endTime) { var eP = e.endTime.split(":"); eD.setHours(+eP[0], +eP[1], 59, 999); }
        else eD.setHours(23, 59, 59, 999);
        if (sMs <= now && eD.getTime() >= now) return true;
        return sMs > now - 3600000 && sMs < now + 30 * 24 * 3600000;
      })
    .sort(function(a, b) {
        var aS = new Date(a.date).getTime(); var bS = new Date(b.date).getTime();
        var aO = aS <= now; var bO = bS <= now;
        if (aO && !bO) return -1; if (!aO && bO) return 1;
        return aS - bS;
      })
    .slice(0, state.eventCount || 5)
    .map(function(e) {
        try {
          var regs = (e.registrations || []).filter(function(r){ return !r.anonymized; });
          var route = e.route || null;
          var routeSummary = null;
          if (route && Array.isArray(route.days) && route.days.length) {
            var totalKm = 0;
            var stops = [];
            route.days.forEach(function(d) {
              ((d && d.stages) || []).forEach(function(et) {
                if (et && et.from && stops.indexOf(et.from) === -1) stops.push(et.from);
                if (et && et.to && stops.indexOf(et.to) === -1) stops.push(et.to);
                if (et && et.km) totalKm += parseFloat(et.km) || 0;
              });
            });
            routeSummary = {
              days: route.days.length,
              km: totalKm > 0 ? Math.round(totalKm) : null,
              stops: stops.slice(0, 4),
            };
          }
          return {
            id: e.id, title: e.title, date: e.date,
            endDate: e.endDate || null, endTime: e.endTime || null,
            location: e.location, eventType: e.eventType, image: e.image || null,
            ..._tvSubgroupInfo(e),
            tvImageTop: e.tvImageTop || null, tvImageBottom: e.tvImageBottom || null,
            description: e.description ? String(e.description).slice(0, 300) : null,
            registrationCount: regs.length,
            maxParticipants: e.maxParticipants || null,
            routeSummary: routeSummary,
            routeMapImage: e.routeMapImage || null,
            dayMapImages: e.dayMapImages || null,
            liveTrackingUrl: e.liveTrackingUrl || null,
            cancelled: !!e.cancelled,
            cancelReason: e.cancelReason || null,
            status: e.status || null,
            rescheduledToDate: e.rescheduledToDate || null,
            rescheduledToUrl: e.rescheduledToUrl || null,
            movedNote: e.movedNote || null,
          };
        } catch(mapErr) {
          return { id: e.id, title: e.title, date: e.date, location: e.location, eventType: e.eventType, image: e.image || null };
        }
      });
  res.json(Object.assign({}, state, { upcoming }));
});

// Update TV state (department or admin)
app.post("/api/tv/:deptId/state", auth, managerOrAdmin, deptGuard, function(req, res) {
  const deptId = req.params.deptId;
  const prev = getTvState(deptId);
  const next = Object.assign({}, prev);
  if (req.body.mode !== undefined)          next.mode = req.body.mode;
  if (req.body.showEvents !== undefined)    next.showEvents = !!req.body.showEvents;
  if (req.body.ticker !== undefined)        next.ticker = String(req.body.ticker || "").slice(0, 300);
  if (req.body.slideInterval !== undefined) next.slideInterval = Math.max(3, Math.min(300, parseInt(req.body.slideInterval) || 15));
  if (req.body.eventCount !== undefined)    next.eventCount = Math.max(1, Math.min(20, parseInt(req.body.eventCount) || 5));
  if (req.body.slideOrder !== undefined)    next.slideOrder = req.body.slideOrder === "random" ? "random" : "sequential";
  if (req.body.showLogo !== undefined)      next.showLogo = !!req.body.showLogo;
  if (req.body.progressColor !== undefined) next.progressColor = String(req.body.progressColor || "").slice(0, 20);
  if (Array.isArray(req.body.slides))       next.slides = req.body.slides;
  if (Array.isArray(req.body.urlSlides))    next.urlSlides = req.body.urlSlides;
  tvState.set(deptId, next);
  _saveTvState();
  broadcastTv(deptId, Object.assign({ type: "state" }, next));
  res.json({ ok: true, state: next });
});

