// ── Global TV Channel (rotates through all departments) ─────────
app.get("/api/tv/_global/state", function(req, res) {
  var settings = getSettings();
  var depts = settings.departments || [];
  var events = readJSON(EVENTS_FILE);
  var now = Date.now();
  var globalState = getTvState("_global");

  var deptViews = [];
  depts.forEach(function(dept) {
    var deptApp = getDeptAppearanceById(dept.id);
    var deptState = getTvState(dept.id);
    var upcoming = events
      .filter(function(e) {
        if (e.department !== dept.id || !e.date || e.hideFromList) return false;
        var sMs = new Date(e.date).getTime();
        var eD = e.endDate ? new Date(e.endDate) : new Date(e.date);
        if (e.endTime) { var eP = e.endTime.split(":"); eD.setHours(+eP[0], +eP[1], 59, 999); }
        else eD.setHours(23, 59, 59, 999);
        if (sMs <= now && eD.getTime() >= now) return true;
        return sMs > now - 3600000;
      })
      .sort(function(a, b) {
        var aS = new Date(a.date).getTime(); var bS = new Date(b.date).getTime();
        var aO = aS <= now; var bO = bS <= now;
        if (aO && !bO) return -1; if (!aO && bO) return 1;
        return aS - bS;
      })
      .slice(0, deptState.eventCount || 5)
      .map(function(e) {
        try {
          var regs = (e.registrations || []).filter(function(r) { return !r.anonymized; });
          return {
            id: e.id, title: e.title, date: e.date, endDate: e.endDate || null, endTime: e.endTime || null,
            location: e.location, eventType: e.eventType, image: e.image || null,
            description: e.description ? String(e.description).slice(0, 300) : null,
            registrationCount: regs.length, maxParticipants: e.maxParticipants || null,
            cancelled: !!e.cancelled, cancelReason: e.cancelReason || null,
          };
        } catch(mapErr) {
          return { id: e.id, title: e.title, date: e.date, location: e.location, eventType: e.eventType, image: e.image || null };
        }
      });
    // Only include departments that have events
    if (upcoming.length > 0) {
      deptViews.push({
        id: dept.id, name: dept.displayName || dept.name, slug: dept.slug || dept.id,
        accent: deptApp.accent, logo: deptApp.logo, theme: deptApp.themeTV || deptApp.theme,
        upcoming: upcoming,
      });
    }
  });

  // Collect media pool: all slides from all departments
  var mediaPool = [];
  depts.forEach(function(dept) {
    var st = getTvState(dept.id);
    (st.slides || []).forEach(function(slide) {
      var url = typeof slide === "string" ? slide : (slide && slide.url ? slide.url : null);
      var thumb = typeof slide === "string" ? slide : (slide && slide.thumb ? slide.thumb : url);
      if (url) mediaPool.push({ url: url, thumb: thumb || url, department: dept.id, departmentName: dept.displayName || dept.name });
    });
  });

  res.json({
    departments: deptViews,
    mediaPool: mediaPool,
    interleaveMedia: globalState.interleaveMedia || [],
    slideInterval: globalState.slideInterval || 20,
    typeNames: settings.typeNames || {},
    typeColors: settings.typeColors || {},
    colors: settings.colors || {},
  });
});

app.post("/api/tv/_global/state", auth, function(req, res) {
  if (req.session.user.role !== "admin") return res.status(403).json({ error: "Admin only" });
  var prev = getTvState("_global");
  var next = Object.assign({}, prev);
  if (req.body.slideInterval !== undefined) next.slideInterval = parseInt(req.body.slideInterval) || 20;
  if (req.body.interleaveMedia !== undefined) next.interleaveMedia = req.body.interleaveMedia || [];
  tvState.set("_global", next);
  _saveTvState();
  res.json({ ok: true });
});

// Global TV SSE stream
app.get("/api/tv/_global/stream", function(req, res) {
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders();
  var clientId = tvNextId++;
  tvClients.set(clientId, { res, deptId: "_global" });
  // Send initial state
  res.write("data: " + JSON.stringify({ type: "refresh" }) + "\n\n");
  var keepAlive = setInterval(function() {
    try { res.write(": keepalive\n\n"); } catch(e) {}
  }, 25000);
  req.on("close", function() { tvClients.delete(clientId); clearInterval(keepAlive); });
});

// Global TV public page
app.get("/tv/_global", function(req, res) {
  var settings = getSettings();
  var siteName = settings.siteName || "Events";
  var globalAccent = (settings.colors && settings.colors.accent) || "#FFD100";
  var globalLogo = settings.logoUrl || "";
  var globalTheme = settings.theme || "dark";
  res.send(buildGlobalTvPage(siteName, globalAccent, globalLogo, globalTheme));
});
app.get("/tv/avdelinger", function(req, res) { res.redirect("/tv/_global"); });

// ── TV Channel Page ──────────────────────────────────────────────
// Subgroup name/colour of an event for the TV screens (null when none)
function _tvSubgroupInfo(e) {
  if (!e || !e.subgroup) return { subgroupName: null, subgroupColor: null };
  const dept = (getSettings().departments || []).find(function(d) { return d.id === e.department; });
  const sg = dept && (dept.subgroups || []).find(function(x) { return x.id === e.subgroup; });
  return sg ? { subgroupName: sg.name || null, subgroupColor: sg.color || null } : { subgroupName: null, subgroupColor: null };
}

app.get("/tv/:deptId", function(req, res) {
  const settings  = getSettings();
  const deptId    = req.params.deptId;
  const dept      = (settings.departments || []).find(function(d) { return d.id === deptId || d.slug === deptId; });
  const deptName  = dept ? (dept.displayName || dept.name) : deptId;
  const siteName  = settings.siteName || "Events";
  const canonId   = dept ? dept.id : deptId;
  const deptApp   = getDeptAppearanceById(deptId);
  const accent    = deptApp.accent;
  const logo      = deptApp.logo;
  const theme     = deptApp.themeTV || deptApp.theme;
  const typo      = deptApp.typography;

  res.send(buildTvPage(canonId, deptName, siteName, accent, logo, theme, typo));
});




// ── Broadcast active event to companion screens ───────────────────
app.post("/api/tv/:deptId/active-event", rateLimit(60, 60000), function(req, res) {
  var deptId = String(req.params.deptId || "");
  var evId   = req.body && req.body.evId ? String(req.body.evId) : null;
  // The TV page itself is public, so this stays without login, but it may only
  // point the side screens at a real event in that department (or clear them).
  var _tvDept = (getSettings().departments || []).find(function(d) { return d.id === deptId || d.slug === deptId; });
  if (!_tvDept && deptId !== "_global") return res.status(404).json({ error: "Not found" });
  if (evId) {
    var _tvEv = (readJSON(EVENTS_FILE) || []).find(function(e) { return e.id === evId; });
    if (!_tvEv || (_tvDept && _tvEv.department !== _tvDept.id)) return res.status(400).json({ error: "Unknown event" });
  }
  // Broadcast to center (for other center viewers) and both companion channels
  broadcastTv(deptId,             { type: "activeEvent", evId: evId });
  broadcastTv(deptId + ":left",   { type: "activeEvent", evId: evId });
  broadcastTv(deptId + ":right",  { type: "activeEvent", evId: evId });
  res.json({ ok: true });
});

// ── TV side-screen photo tagging ─────────────────────────────────
// POST /api/events/:id/tv-side-photos  { url, tagged: true/false }
app.post("/api/events/:id/tv-side-photos", auth, managerOrAdmin, function(req, res) {
  var events = readJSON(EVENTS_FILE);
  var idx = events.findIndex(function(e) { return e.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ err: "Event not found" });
  var url = req.body.url;
  var tagged = req.body.tagged !== false;
  if (!url) return res.status(400).json({ err: "url required" });
  events[idx].tvSidePhotos = events[idx].tvSidePhotos || [];
  var existing = events[idx].tvSidePhotos.indexOf(url);
  if (tagged && existing === -1) {
    events[idx].tvSidePhotos.push(url);
  } else if (!tagged && existing !== -1) {
    events[idx].tvSidePhotos.splice(existing, 1);
  }
  writeJSON(EVENTS_FILE, events);
  _broadcastTvUpcoming(events[idx].department);
  res.json({ ok: true, tvSidePhotos: events[idx].tvSidePhotos });
});


// ── Live viewer count ─────────────────────────────────────────────
app.get("/api/tv/:deptId/viewers", auth, deptGuard, function(req, res) {
  var deptId = req.params.deptId;
  var dept = (getSettings().departments || []).find(function(d) {
    return d.id === deptId || d.slug === deptId;
  });
  var canonId = dept ? dept.id : deptId;
  var count = 0;
  var groups = {};
  tvClients.forEach(function(client) {
    if (client.deptId === canonId) count++;
    else if (String(client.deptId).indexOf(canonId + "~") === 0) { count++; var g = _tvChan(client.deptId).sg; groups[g] = (groups[g] || 0) + 1; }
  });
  res.json({ count: count, deptId: canonId, groups: groups });
});

// ── TV channel → device assignment ("Play on…") ──────────────────
// Ported from ull-infoskjerm's "Assign to Displays" flow. A manager
// opens the active TV channel of a department and picks which TV
// devices (Pi nodes) should play it, and in which multiscreen
// position (center / left / right). The node record keeps deptId +
// screen, and the new kiosk URL is queued for the next heartbeat.
var TV_SCREEN_POSITIONS = ["center", "left", "right"];

function tvChannelUrl(deptId, screen) {
  var dept = getDept(deptId);
  if (!dept) return null;
  var url = "https://" + (dept.slug || dept.id) + "." + DOMAIN + "/tv/" + dept.id;
  if (screen === "left" || screen === "right") url += "/" + screen;
  return url;
}

// Admins see every node. Managers only see nodes that already belong
// to a department they have access to.
function tvNodeVisibleTo(user, node) {
  if (!user || !node) return false;
  if (user.role === "admin") return true;
  return !!node.deptId && hasDeptAccess(user, node.deptId);
}

function findDeptByIdOrSlug(idOrSlug) {
  return (getSettings().departments || []).find(function(d) {
    return d.id === idOrSlug || d.slug === idOrSlug;
  }) || null;
}

app.get("/api/tv/:deptId/devices", auth, managerOrAdmin, deptGuard, function(req, res) {
  var dept = findDeptByIdOrSlug(req.params.deptId);
  if (!dept) return res.status(404).json({ error: st("department_gone", req) });
  var user = req.session.user;
  var depts = getSettings().departments || [];
  var now = Date.now();
  var devices = readTvNodes().filter(function(n) { return tvNodeVisibleTo(user, n); }).map(function(n) {
    var cur = depts.find(function(d) { return d.id === n.deptId; });
    var seen = n.lastSeen ? Date.parse(n.lastSeen) : 0;
    var pending = _tvPendingCommands[n.id] || {};
    return {
      id: n.id,
      name: n.name,
      hostname: n.hostname || null,
      status: n.status || "registered",
      online: !!seen && (now - seen) < 120000,
      lastSeen: n.lastSeen || null,
      deptId: n.deptId || null,
      deptName: cur ? (cur.displayName || cur.name) : null,
      screen: TV_SCREEN_POSITIONS.indexOf(n.screen) >= 0 ? n.screen : "center",
      here: n.deptId === dept.id,
      agentVersion: n.health && n.health.agentVersion || null,
      urlPending: !!pending.setUrl,
      channelAssignedAt: n.channelAssignedAt || null,
    };
  });
  devices.sort(function(a, b) {
    if (a.here !== b.here) return a.here ? -1 : 1;
    if (a.online !== b.online) return a.online ? -1 : 1;
    return String(a.name || "").localeCompare(String(b.name || ""));
  });
  res.json({ deptId: dept.id, deptName: dept.displayName || dept.name, devices: devices });
});

app.post("/api/tv/:deptId/devices", auth, managerOrAdmin, deptGuard, function(req, res) {
  var dept = findDeptByIdOrSlug(req.params.deptId);
  if (!dept) return res.status(404).json({ error: st("department_gone", req) });
  var user = req.session.user;
  var assignments = Array.isArray(req.body && req.body.assignments) ? req.body.assignments.slice(0, 200) : [];
  if (!assignments.length) return res.status(400).json({ error: "No devices selected" });

  var list = readTvNodes();
  var nowIso = new Date().toISOString();
  var results = [];
  assignments.forEach(function(a) {
    var nodeId = a && a.nodeId;
    var node = list.find(function(n) { return n.id === nodeId; });
    if (!node) return results.push({ nodeId: nodeId, ok: false, error: "not_found" });
    if (!tvNodeVisibleTo(user, node)) return results.push({ nodeId: nodeId, ok: false, error: "forbidden" });
    var screen = TV_SCREEN_POSITIONS.indexOf(a.screen) >= 0 ? a.screen : "center";
    var changed = node.deptId !== dept.id || (node.screen || "center") !== screen;
    node.deptId = dept.id;
    node.screen = screen;
    if (changed) {
      var url = tvChannelUrl(dept.id, screen);
      node.kioskUrl = url;
      node.channelAssignedAt = nowIso;
      node.channelAssignedBy = user.email || user.id || null;
      if (url) queueTvCommand(node.id, { setUrl: url });
    }
    results.push({ nodeId: node.id, ok: true, changed: changed, screen: screen, online: !!node.lastSeen && (Date.now() - Date.parse(node.lastSeen)) < 120000 });
  });
  saveTvNodes(list);
  res.json({ ok: true, results: results });
});

// ── Multiscreen companion pages ──────────────────────────────────
app.get("/tv/:deptId/left",  function(req, res) { serveTvCompanion(req, res, "left");  });
app.get("/tv/:deptId/right", function(req, res) { serveTvCompanion(req, res, "right"); });
app.get("/tv/:deptId/center", function(req, res) { res.redirect("/tv/" + req.params.deptId); });

// ── Group channels: /tv/romerike/mc (+ /left, /right) ──
// The group is found by id, slug or name («mc», «MC», «Motorsykkel» → «motorsykkel»)
function _tvSlug(t) { return String(t || "").toLowerCase().replace(/æ/g, "ae").replace(/ø/g, "o").replace(/å/g, "a").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""); }
function _tvFindGroup(dept, key) {
  if (!dept) return null;
  var k = _tvSlug(decodeURIComponent(key || ""));
  return (dept.subgroups || []).find(function(sg) { return sg.id === key || (sg.slug && _tvSlug(sg.slug) === k) || _tvSlug(sg.name) === k; }) || null;
}
function _tvGroupOr404(req, res) {
  const dept = findDeptByIdOrSlug(req.params.deptId);
  const sg = _tvFindGroup(dept, req.params.group);
  if (!dept || !sg) {
    res.status(404).send(_evalMsgPage("no", "📺", "Fant ikke gruppen", "«" + req.params.group + "» er ikke en gruppe i " + (dept ? (dept.displayName || dept.name) : "denne avdelingen") + ". " +
      (dept && (dept.subgroups || []).length ? "Grupper: " + dept.subgroups.map(function(x) { return "/tv/" + (dept.slug || dept.id) + "/" + _tvSlug(x.slug || x.name); }).join(", ") : "")));
    return null;
  }
  return { dept: dept, sg: sg, chan: dept.id + "~" + sg.id };
}
app.get("/tv/:deptId/:group", function(req, res) {
  const g = _tvGroupOr404(req, res); if (!g) return;
  const settings = getSettings();
  // the group's own colours/theme when it has them, else the department's
  const app      = getDeptAppearance({ department: g.dept.id, subgroup: g.sg.id });
  const logo     = _logoFor(g.dept.id, g.sg.id).url || app.logo;
  const name     = (g.dept.displayName || g.dept.name) + " · " + g.sg.name;
  res.locals.favicon = _faviconHref(g.dept.id, g.sg.id);
  res.send(buildTvPage(g.chan, name, settings.siteName || "Events", app.accent, logo, app.themeTV || app.theme, app.typography));
});
app.get("/tv/:deptId/:group/left",  function(req, res) { const g = _tvGroupOr404(req, res); if (!g) return; req.params.deptId = g.chan; serveTvCompanion(req, res, "left"); });
app.get("/tv/:deptId/:group/right", function(req, res) { const g = _tvGroupOr404(req, res); if (!g) return; req.params.deptId = g.chan; serveTvCompanion(req, res, "right"); });

// ── Global TV page: rotates through all departments ─────────────
function buildGlobalTvPage(siteName, accent, logo, theme) {
  var isDark = (theme || "dark") !== "light";
  var bg = isDark ? "#0a0a0a" : "#f0f0f0";
  var text = isDark ? "#fff" : "#111";
  var esc = escHtml;
  return `<!DOCTYPE html>
<html lang="no">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>${esc(siteName)} – Global TV</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
html{font-size:1vw}
body{background:${bg};color:${text};font-family:"Helvetica Neue",Arial,sans-serif;overflow:hidden;height:100dvh;width:100dvw}

/* ── Single-dept mode (default) ─────────────────────── */
#screen{width:100%;height:100%;position:relative;overflow:hidden;display:flex}
#evList{width:50%;flex-shrink:0;display:flex;flex-direction:column;justify-content:center;padding:5vh 5vw;overflow:hidden;z-index:2;
  background:${isDark ? "linear-gradient(135deg,#0d0d0d 0%,#111 100%)" : "linear-gradient(135deg,#e8e8e8 0%,#f4f4f4 100%)"};
  border-right:1px solid ${isDark ? "rgba(255,255,255,.04)" : "rgba(0,0,0,.07)"};
  transition:opacity .6s}
.dept-header{font-size:clamp(.7rem,1.3vw,1.8vw);font-weight:800;letter-spacing:.03em;margin-bottom:1.2vh;padding-bottom:.8vh;display:flex;align-items:center;gap:.8vw;
  color:${isDark ? "#999" : "#555"}}
.dept-header img{height:clamp(16px,2.2vw,3vw);object-fit:contain;border-radius:.3vw;opacity:.85}
.dept-accent-line{height:2px;margin-bottom:1.5vh}
.ev-card{display:flex;gap:2vw;align-items:flex-start;margin-bottom:2vh;opacity:0;transform:translateY(15px);transition:opacity .5s ease,transform .5s ease}
.ev-card.visible{opacity:1;transform:translateY(0)}
.ev-card.active{background:${isDark?"rgba(255,255,255,.03)":"rgba(0,0,0,.03)"};border-radius:.8vw;padding:.6vw;margin-left:-.6vw;margin-right:-.6vw}
.ev-thumb{width:clamp(36px,5vw,7vw);height:clamp(36px,5vw,7vw);object-fit:cover;border-radius:.8vw;flex-shrink:0;border:2px solid ${isDark?"rgba(255,255,255,.1)":"rgba(0,0,0,.12)"}}
.ev-thumb-ph{width:clamp(36px,5vw,7vw);height:clamp(36px,5vw,7vw);border-radius:.8vw;flex-shrink:0;display:flex;align-items:center;justify-content:center;
  background:${isDark?"#1a1a1a":"#ddd"};border:2px solid ${isDark?"rgba(255,255,255,.08)":"rgba(0,0,0,.1)"}}
.ev-badge{font-size:clamp(.4rem,.65vw,.9vw);font-weight:800;text-transform:uppercase;letter-spacing:.06em;padding:.15vw .6vw;border-radius:2vw;display:inline-block;margin-bottom:.3vh}
.ev-title{font-size:clamp(.55rem,1.4vw,2vw);font-weight:900;line-height:1.2;margin-bottom:.2vh}
.ev-meta{font-size:clamp(.42rem,.85vw,1.2vw);color:${isDark?"#888":"#666"}}

/* Right detail panel (single mode only) */
#evDetail{flex:1;position:relative;display:flex;flex-direction:column;justify-content:center;padding:6vh 4vw;overflow:hidden}
#evDetailBg{position:absolute;inset:0;transition:background 1.2s ease}
#evDetailContent{position:relative;z-index:1;display:flex;flex-direction:column;gap:2vh}
#edBadge{font-size:clamp(.46rem,.75vw,1.1vw);font-weight:800;text-transform:uppercase;letter-spacing:.08em;padding:.35vh 1.2vw;border-radius:2vw;display:inline-block}
#edTitle{font-size:clamp(1.1rem,3.2vw,4.5vw);font-weight:900;line-height:1.15}
.ed-row{display:flex;align-items:center;gap:.8vw;font-size:clamp(.63rem,1.35vw,1.9vw);color:${isDark?"#ccc":"#333"}}
#edDesc{font-size:clamp(.5rem,1.25vw,1.8vw);color:${isDark?"#999":"#555"};line-height:1.55;margin-top:.5vh;padding-top:.5vh;border-top:1px solid ${isDark?"rgba(255,255,255,.07)":"rgba(0,0,0,.08)"}}
#edImage{width:100%;max-height:28vh;object-fit:cover;border-radius:1vw;display:none;margin-bottom:1vh}

/* ── Grid mode (4K / many departments) ──────────────── */
#gridScreen{display:none;width:100%;height:100%;position:relative;overflow:hidden}
#gridContainer{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;width:100%;height:100%;gap:1px;background:${isDark?"#222":"#ccc"}}
.grid-cell{background:${isDark ? "linear-gradient(135deg,#0d0d0d 0%,#111 100%)" : "linear-gradient(135deg,#e8e8e8 0%,#f4f4f4 100%)"};
  display:flex;flex-direction:column;justify-content:center;padding:3vh 3vw;overflow:hidden;position:relative;
  opacity:0;transform:scale(.97);transition:opacity .5s ease,transform .5s ease}
.grid-cell.visible{opacity:1;transform:scale(1)}
.grid-cell .dept-header{font-size:clamp(.5rem,.9vw,1.3vw);margin-bottom:.8vh;padding-bottom:.5vh}
.grid-cell .dept-header img{height:clamp(12px,1.5vw,2vw)}
.grid-cell .ev-card{gap:1.2vw;margin-bottom:1.2vh}
.grid-cell .ev-thumb,.grid-cell .ev-thumb-ph{width:clamp(28px,3.5vw,5vw);height:clamp(28px,3.5vw,5vw);border-radius:.6vw}
.grid-cell .ev-badge{font-size:clamp(.35rem,.5vw,.7vw);padding:.1vw .5vw}
.grid-cell .ev-title{font-size:clamp(.45rem,.95vw,1.4vw)}
.grid-cell .ev-meta{font-size:clamp(.35rem,.7vw,1vw)}

/* Slide layer for interleave media */
#slideLayer{position:absolute;inset:0;background:#000;z-index:10;opacity:0;transition:opacity .8s;pointer-events:none}
#slideLayer.active{opacity:1}
#slideLayer img{width:100%;height:100%;object-fit:contain}

/* Progress bar */
#progressBar{position:absolute;bottom:0;left:0;height:.35vh;min-height:3px;z-index:20;transition:width 0s linear}

/* Slide dots */
#slideDots{position:absolute;bottom:1.5vh;right:2vw;display:flex;flex-direction:column;gap:.4vh;z-index:20}
.sdot{width:.6vw;height:.6vw;min-width:5px;min-height:5px;border-radius:50%;background:${isDark?"#333":"#bbb"}}
.sdot.active{background:var(--dot-accent,${esc(accent)})}
</style>
</head>
<body>
<!-- Single-department mode -->
<div id="screen">
  <div id="evList">
    <div id="evDeptHeader" class="dept-header"></div>
    <div id="evDeptAccentLine" class="dept-accent-line"></div>
    <div id="evCards"></div>
  </div>
  <div id="evDetail">
    <div id="evDetailBg"></div>
    <div id="evDetailContent">
      <img id="edImage" src="" alt=""/>
      <span id="edBadge"></span>
      <div id="edTitle"></div>
      <div id="edMeta"></div>
      <div id="edDesc"></div>
    </div>
  </div>
</div>
<!-- Grid mode -->
<div id="gridScreen">
  <div id="gridContainer"></div>
</div>
<!-- Shared overlays -->
<div id="slideLayer"><img id="slideImg" src="" alt=""/></div>
<div id="progressBar"></div>
<div id="slideDots"></div>

<script>
var IS_DARK = ${JSON.stringify(isDark)};
var GRID_MODE = false;
var GRID_SIZE = 4;
var data = null;
var deptIdx = 0, evIdx = 0;
var evTimer = null, deptTimer = null;
var cycleItems = [], cyclePos = 0;

function detectGridMode() {
  var sw = window.screen.width || window.innerWidth;
  var deptCount = (data && data.departments) ? data.departments.length : 0;
  // Grid mode: screen wide enough for 4 cells AND at least 4 departments
  GRID_MODE = (sw >= 2560 && deptCount >= 4);
  document.getElementById("screen").style.display     = GRID_MODE ? "none" : "flex";
  document.getElementById("gridScreen").style.display  = GRID_MODE ? "block" : "none";
}

function formatDate(d) {
  if (!d) return "";
  var dt = new Date(d);
  var days = ["s\u00f8n","man","tir","ons","tor","fre","l\u00f8r"];
  var months = ["jan","feb","mar","apr","mai","jun","jul","aug","sep","okt","nov","des"];
  var h = String(dt.getHours()).padStart(2,"0");
  var m = String(dt.getMinutes()).padStart(2,"0");
  return days[dt.getDay()] + " " + dt.getDate() + ". " + months[dt.getMonth()] + " kl. " + h + ":" + m;
}
function formatDateFull(d) {
  if (!d) return "";
  var dt = new Date(d);
  var days = ["s\u00f8ndag","mandag","tirsdag","onsdag","torsdag","fredag","l\u00f8rdag"];
  var months = ["januar","februar","mars","april","mai","juni","juli","august","september","oktober","november","desember"];
  var h = String(dt.getHours()).padStart(2,"0");
  var m = String(dt.getMinutes()).padStart(2,"0");
  return days[dt.getDay()] + " " + dt.getDate() + ". " + months[dt.getMonth()] + " kl. " + h + ":" + m;
}
function getTypeColor(type) {
  if (!data || !type) return IS_DARK ? "#444" : "#ccc";
  return (data.typeColors || {})[type] || (IS_DARK ? "#444" : "#ccc");
}
function getTypeName(type) {
  if (!data || !type) return type || "";
  return (data.typeNames || {})[type] || type;
}
function textOnBg(hex) {
  if (!hex || hex.length < 7) return "#fff";
  var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return (0.299*r + 0.587*g + 0.114*b) > 140 ? "#111" : "#fff";
}

// \u2500\u2500 Render event cards into a container \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function renderDeptCards(container, dept, useShortDate) {
  container.innerHTML = "";
  var hdr = document.createElement("div"); hdr.className = "dept-header";
  hdr.innerHTML = (dept.logo ? '<img src="' + dept.logo + '" alt=""/>' : '') + '<span>' + dept.name + '</span>';
  container.appendChild(hdr);
  var line = document.createElement("div"); line.className = "dept-accent-line";
  line.style.background = dept.accent;
  container.appendChild(line);
  (dept.upcoming || []).forEach(function(ev, i) {
    var tc = getTypeColor(ev.eventType);
    var tn = getTypeName(ev.eventType);
    var div = document.createElement("div"); div.className = "ev-card";
    div.innerHTML =
      (ev.image ? '<img class="ev-thumb" src="' + ev.image + '" alt=""/>' : '<div class="ev-thumb-ph"><svg viewBox="0 0 24 24" width="100%" height="100%" fill="' + (IS_DARK?"#333":"#bbb") + '"><path d="M21 19V5a2 2 0 00-2-2H5a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2zM8.5 13.5l2.5 3L14.5 12l4.5 6H5l3.5-4.5z"/></svg></div>') +
      '<div>' +
        '<span class="ev-badge" style="background:' + tc + ';color:' + textOnBg(tc) + '">' + tn + '</span>' +
        '<div class="ev-title">' + ev.title + '</div>' +
        '<div class="ev-meta">' + (useShortDate ? formatDate(ev.date) : formatDateFull(ev.date)) + '</div>' +
      '</div>';
    container.appendChild(div);
    setTimeout(function() { div.classList.add("visible"); }, 80 * (i + 1));
  });
}

// \u2500\u2500 Single-department mode \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function showDept(dept) {
  var list = document.getElementById("evList");
  renderDeptCards(list, dept, false);
  evIdx = 0;
  showEventDetail(dept, 0);
}

function showEventDetail(dept, idx) {
  var ev = (dept.upcoming || [])[idx];
  if (!ev) return;
  var tc = getTypeColor(ev.eventType);
  var tn = getTypeName(ev.eventType);
  document.querySelectorAll("#evList .ev-card").forEach(function(c, i) {
    c.classList.toggle("active", i === idx);
  });
  var bg = document.getElementById("evDetailBg");
  bg.style.background = IS_DARK
    ? "linear-gradient(135deg," + tc + "08 0%," + tc + "03 100%)"
    : "linear-gradient(135deg," + tc + "0a 0%," + tc + "05 100%)";
  var img = document.getElementById("edImage");
  if (ev.image) { img.src = ev.image; img.style.display = "block"; }
  else { img.style.display = "none"; }
  var badge = document.getElementById("edBadge");
  badge.textContent = tn; badge.style.background = tc; badge.style.color = textOnBg(tc);
  document.getElementById("edTitle").textContent = ev.title;
  var rows = '<div class="ed-row"><strong>Dato:</strong> ' + formatDateFull(ev.date) + '</div>';
  if (ev.location) rows += '<div class="ed-row"><strong>Sted:</strong> ' + ev.location + '</div>';
  if (ev.registrationCount) rows += '<div class="ed-row"><strong>P\u00e5meldte:</strong> ' + ev.registrationCount + (ev.maxParticipants ? ' / ' + ev.maxParticipants : '') + '</div>';
  document.getElementById("edMeta").innerHTML = rows;
  var desc = document.getElementById("edDesc");
  if (ev.description) { desc.textContent = ev.description; desc.style.display = ""; }
  else { desc.style.display = "none"; }
}

// \u2500\u2500 Grid mode (2\u00d72) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
var gridPage = 0;

function showGridPage(page) {
  var depts = data.departments;
  var start = page * GRID_SIZE;
  var slice = depts.slice(start, start + GRID_SIZE);
  var grid = document.getElementById("gridContainer");
  grid.innerHTML = "";
  slice.forEach(function(dept, i) {
    var cell = document.createElement("div");
    cell.className = "grid-cell";
    renderDeptCards(cell, dept, true);
    grid.appendChild(cell);
    setTimeout(function() { cell.classList.add("visible"); }, 120 * (i + 1));
  });
  // Fill empty cells if <4 departments in this page
  for (var f = slice.length; f < GRID_SIZE; f++) {
    var empty = document.createElement("div");
    empty.className = "grid-cell visible";
    empty.style.opacity = "0.15";
    grid.appendChild(empty);
  }
}

// \u2500\u2500 Cycle management \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function buildCycle() {
  cycleItems = [];
  if (!data || !data.departments || !data.departments.length) return;
  var interleave = data.interleaveMedia || [];
  var mediaIdx = 0;

  if (GRID_MODE) {
    // Pages of GRID_SIZE departments
    var pages = Math.ceil(data.departments.length / GRID_SIZE);
    for (var p = 0; p < pages; p++) {
      cycleItems.push({ type: "grid", page: p });
      if (interleave.length > 0) {
        cycleItems.push({ type: "media", url: interleave[mediaIdx % interleave.length] });
        mediaIdx++;
      }
    }
  } else {
    // One department at a time
    data.departments.forEach(function(dept, i) {
      cycleItems.push({ type: "dept", idx: i });
      if (interleave.length > 0) {
        cycleItems.push({ type: "media", url: interleave[mediaIdx % interleave.length] });
        mediaIdx++;
      }
    });
  }
}

function renderDots() {
  var el = document.getElementById("slideDots");
  if (!cycleItems.length) { el.innerHTML = ""; return; }
  var accent = "${esc(accent)}";
  if (data && data.departments && data.departments[deptIdx]) accent = data.departments[deptIdx].accent;
  el.innerHTML = cycleItems.map(function(_, i) {
    return '<div class="sdot' + (i === cyclePos ? ' active' : '') + '" style="' + (i === cyclePos ? '--dot-accent:' + accent : '') + '"></div>';
  }).join("");
}

function showMediaSlide(url) {
  document.getElementById("slideImg").src = url;
  document.getElementById("slideLayer").classList.add("active");
}
function hideMediaSlide() {
  document.getElementById("slideLayer").classList.remove("active");
}

function startProgress(durationS, accent) {
  var bar = document.getElementById("progressBar");
  bar.style.background = accent;
  bar.style.width = "0%";
  bar.style.transition = "none";
  requestAnimationFrame(function() {
    requestAnimationFrame(function() {
      bar.style.transition = "width " + durationS + "s linear";
      bar.style.width = "100%";
    });
  });
}

function advanceCycle() {
  cyclePos = (cyclePos + 1) % cycleItems.length;
  showCycleItem();
}

function showCycleItem() {
  if (!cycleItems.length) return;
  var item = cycleItems[cyclePos];
  var interval = (data && data.slideInterval) || 20;
  var accent = "${esc(accent)}";

  if (item.type === "dept") {
    var dept = data.departments[item.idx];
    deptIdx = item.idx;
    accent = dept.accent || accent;
    hideMediaSlide();
    showDept(dept);
    if (evTimer) clearInterval(evTimer);
    var evCount = (dept.upcoming || []).length;
    if (evCount > 1) {
      var perEv = Math.max(3, Math.floor(interval / evCount));
      evTimer = setInterval(function() {
        evIdx = (evIdx + 1) % evCount;
        showEventDetail(dept, evIdx);
      }, perEv * 1000);
    }
  } else if (item.type === "grid") {
    if (evTimer) clearInterval(evTimer);
    hideMediaSlide();
    gridPage = item.page;
    showGridPage(item.page);
    // Use first dept in page for accent
    var firstDept = data.departments[item.page * GRID_SIZE];
    if (firstDept) accent = firstDept.accent;
  } else if (item.type === "media") {
    if (evTimer) clearInterval(evTimer);
    showMediaSlide(item.url);
  }

  startProgress(interval, accent);
  renderDots();
  if (deptTimer) clearTimeout(deptTimer);
  deptTimer = setTimeout(advanceCycle, interval * 1000);
}

async function loadData() {
  try {
    var r = await fetch("/api/tv/_global/state");
    data = await r.json();
    detectGridMode();
    buildCycle();
    if (cycleItems.length) {
      cyclePos = 0;
      showCycleItem();
    }
  } catch(e) { console.error("Failed to load global TV state:", e); }
}

function connectSSE() {
  var es = new EventSource("/api/tv/_global/stream");
  es.onmessage = function(ev) {
    try {
      var msg = JSON.parse(ev.data);
      if (msg.type === "refresh" || msg.type === "upcoming") loadData();
    } catch(e) {}
  };
  es.onerror = function() { es.close(); setTimeout(connectSSE, 5000); };
}

loadData();
connectSSE();
</script>
</body>
</html>`;
}

function serveTvCompanion(req, res, position) {
  const settings = getSettings();
  const chanIn   = req.params.deptId;                 // department, or «dept~group» for a group screen
  const deptId   = _tvChan(chanIn).dept;
  const dept     = (settings.departments || []).find(function(d) { return d.id === deptId || d.slug === deptId; });
  const canonId  = (dept ? dept.id : deptId) + (_tvChan(chanIn).sg ? "~" + _tvChan(chanIn).sg : "");
  const deptApp  = getDeptAppearanceById(deptId);
  const accent   = deptApp.accent;
  const logo     = deptApp.logo;
  const theme    = deptApp.themeTV || deptApp.theme;
  const isDark   = (theme || "dark") !== "light";
  const bg       = isDark ? "#080808" : "#f0f0f0";
  const text     = isDark ? "#ffffff" : "#111111";
  const siteName = settings.siteName || "Events";
  const esc      = escHtml;
  const isLeft   = position === "left";

  res.send(`<!DOCTYPE html>
<html lang="no">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>${esc(siteName)} – TV ${isLeft ? "Venstre" : "Høyre"}</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
html,body{width:100dvw;height:100dvh;overflow:hidden;background:${bg};color:${text};font-family:"Helvetica Neue",Arial,sans-serif}

/* ── Layout ── */
#root{width:100%;height:100%;display:flex;flex-direction:column;position:relative}

/* ── Logo / header strip ── */
#strip{height:9vh;display:flex;align-items:center;padding:0 4vw;gap:2vw;background:linear-gradient(to bottom,${isDark?"rgba(0,0,0,.7)":"rgba(255,255,255,.7)"} 0%,transparent 100%);position:absolute;top:0;left:0;right:0;z-index:10}
#stripLogo{height:6vh;max-height:5vw;object-fit:contain;display:${logo?"block":"none"}}
#stripName{font-size:clamp(.8rem,1.6vw,2.2rem);font-weight:900;color:${esc(accent)}}
#posLabel{margin-left:auto;font-size:clamp(.55rem,.85vw,1.1rem);font-weight:700;color:${isDark?"#555":"#aaa"};text-transform:uppercase;letter-spacing:.12em}

/* ── Main photo area ── */
#photoWrap{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;overflow:hidden}
#photoBg{position:absolute;inset:-5%;background-size:cover;background-position:center;filter:blur(28px) brightness(.35);transition:background-image 1.2s ease;z-index:0}
#photoImg{position:relative;z-index:1;max-width:92%;max-height:86vh;object-fit:contain;border-radius:1.2vw;box-shadow:0 2vw 8vw rgba(0,0,0,.7);transition:opacity .8s ease;opacity:0}
#photoImg.visible{opacity:1}

/* ── Event info overlay ── */
#infoBar{position:absolute;bottom:0;left:0;right:0;z-index:10;padding:3vh 4vw;background:linear-gradient(to top,${isDark?"rgba(0,0,0,.85)":"rgba(0,0,0,.6)"} 0%,transparent 100%)}
#infoEvent{font-size:clamp(.9rem,2.2vw,3rem);font-weight:900;color:#fff;margin-bottom:.5vh;line-height:1.2;text-shadow:0 2px 12px rgba(0,0,0,.7)}
#infoMeta{font-size:clamp(.6rem,1.2vw,1.6rem);color:rgba(255,255,255,.65);display:flex;gap:1.5vw;flex-wrap:wrap}

/* ── Ambient dots ── */
#ambientDots{position:absolute;bottom:6.5vh;right:2.5vw;display:flex;flex-direction:column;gap:.5vh;z-index:5}
.adot{width:.6vw;height:.6vw;min-width:5px;min-height:5px;border-radius:50%;background:${isDark?"#333":"#bbb"};transition:background .4s}
.adot.active{background:${esc(accent)}}

/* ── No-content placeholder ── */
#placeholder{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2vh;opacity:.25}
#placeholder svg{width:12vw;height:12vw}
#placeholder p{font-size:clamp(.7rem,1.5vw,2rem);font-weight:700;text-transform:uppercase;letter-spacing:.1em}

/* ── Ticker ── */
#ticker{position:absolute;bottom:0;left:0;right:0;height:5.5vh;min-height:32px;background:${esc(accent)};color:#111;display:none;align-items:center;overflow:hidden;z-index:15}
#tickerInner{white-space:nowrap;font-weight:700;font-size:clamp(.65rem,1.5vw,2.2rem);padding-left:100%;animation:scroll 30s linear infinite}
@keyframes scroll{from{transform:translateX(0)}to{transform:translateX(-200%)}}}

@keyframes fadeIn{from{opacity:0;transform:scale(1.03)}to{opacity:1;transform:scale(1)}}
</style>
</head>
<body>
<div id="root">
  <div id="photoWrap">
    <div id="photoBg"></div>
    <img id="photoImg" src="" alt=""/>
    <div id="placeholder">
      <svg viewBox="0 0 80 60" fill="${isDark?"#fff":"#000"}"><rect x="5" y="5" width="70" height="50" rx="6" fill="none" stroke="currentColor" stroke-width="4"/><circle cx="26" cy="24" r="8" fill="none" stroke="currentColor" stroke-width="3"/><polyline points="5,55 28,32 46,48 58,36 75,55" fill="none" stroke="currentColor" stroke-width="3"/></svg>
      <p>${isLeft ? "Venstre skjerm" : "Høyre skjerm"}</p>
    </div>
  </div>

  <div id="strip">
    ${logo ? '<img id="stripLogo" src="' + esc(logo) + '" alt="' + esc(siteName) + '"/>' : ""}
    <div id="stripName">${esc(siteName)}</div>
    <div id="posLabel">${isLeft ? "◀ Venstre" : "Høyre ▶"}</div>
  </div>

  <div id="infoBar" style="display:none">
    <div id="infoEvent"></div>
    <div id="infoMeta"></div>
  </div>

  <div id="ambientDots"></div>
  <div id="ticker"><div id="tickerInner"></div></div>
</div>

<script>
var DEPT_ID  = ${JSON.stringify(canonId)};
var ACCENT   = ${JSON.stringify(accent)};
var IS_LEFT  = ${JSON.stringify(isLeft)};
var IS_DARK  = ${JSON.stringify(isDark)};
var state    = { upcoming:[], slides:[], ticker:"" };
var photos   = [];   // flat list of { src, evTitle, evDate, evLocation }
var photoIdx = 0;
var timer    = null;

// \u2500\u2500 SSE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function connect() {
  var es = new EventSource("/api/tv/" + DEPT_ID + "/stream");
  es.onmessage = function(e) {
    try {
      var d = JSON.parse(e.data);
      if (d.type === "upcoming") { state.upcoming = d.upcoming || []; rebuildPhotos(); return; }
      if (d.type === "state")    { Object.assign(state, d); rebuildPhotos(); updateTicker(); }
      // activeEvent: sent when center screen switches to show a specific event
      if (d.type === "activeEvent") {
        activeEvId = d.evId || null;
        rebuildPhotos();
        return;
      }
      // multiscreenCompanion: sent when a multiscreen playlist is activated on center
      if (d.type === "multiscreenCompanion") {
        multiscreenConfig = d.multiscreenConfig || null;
        rebuildPhotos();
        return;
      }
    } catch(x) {}
  };
  es.onerror = function() { es.close(); setTimeout(connect, 3000); };
}
connect();

// \u2500\u2500 Build photo list from upcoming events + slides \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Priority: tvSidePhotos (manually tagged) > gbPhotos > other event images
// activeEvId is set when the center screen switches to an event, synced via SSE
var activeEvId = null;
var multiscreenConfig = null; // set when multiscreen playlist activates

function rebuildPhotos() {
  var list = buildPhotoList(state.upcoming || [], activeEvId);

  // Left screen: even-indexed photos. Right: odd-indexed.
  photos = list.filter(function(_, i) { return IS_LEFT ? (i % 2 === 0) : (i % 2 === 1); });
  if (!photos.length) photos = list; // fallback: show all if not enough

  photoIdx = 0;
  updateDots();
  if (photos.length) {
    showPhoto(0);
    if (!timer) scheduleTick();
  } else {
    document.getElementById("placeholder").style.display = "flex";
    document.getElementById("infoBar").style.display = "none";
  }
}

function buildPhotoList(upcoming, focusEvId) {
  var list = [];

  // If an event is actively shown on the center screen, prioritise its photos
  var focusEv = focusEvId ? upcoming.find(function(e) { return e.id === focusEvId; }) : null;
  if (focusEv) {
    list = photosForEvent(focusEv);
    // If the focused event has photos, use only those
    if (list.length) return list;
  }

  // Otherwise build from all upcoming events
  upcoming.forEach(function(ev) {
    photosForEvent(ev).forEach(function(p) { list.push(p); });
  });

  // If still nothing, fall back to slides
  if (!list.length) {
    (state.slides || []).forEach(function(sl) {
      var src = (typeof sl === "string") ? sl : (sl && sl.bg) ? sl.bg : null;
      if (src && !src.endsWith(".mp4")) list.push({ src: src, evTitle: null, evId: null });
    });
  }
  return list;
}

function photosForEvent(ev) {
  var imgs = [];
  // 1. Manually tagged side-screen photos (highest priority)
  if (ev.tvSidePhotos && ev.tvSidePhotos.length) {
    ev.tvSidePhotos.forEach(function(u) { if (u) imgs.push({ src: u, evTitle: ev.title, evDate: ev.date, evLocation: ev.location, evId: ev.id, tagged: true }); });
    return imgs; // If any manually tagged, use only those
  }
  // 2. Approved guestbook photos
  if (ev.gbPhotos && ev.gbPhotos.length) {
    ev.gbPhotos.forEach(function(u) { if (u) imgs.push({ src: u, evTitle: ev.title, evDate: ev.date, evLocation: ev.location, evId: ev.id }); });
  }
  // 3. Other event images as fallback
  if (!imgs.length) {
    if (ev.image)        imgs.push({ src: ev.image,        evTitle: ev.title, evDate: ev.date, evLocation: ev.location, evId: ev.id });
    if (ev.tvImageTop)   imgs.push({ src: ev.tvImageTop,   evTitle: ev.title, evDate: ev.date, evLocation: ev.location, evId: ev.id });
    if (ev.tvImageBottom)imgs.push({ src: ev.tvImageBottom, evTitle: ev.title, evDate: ev.date, evLocation: ev.location, evId: ev.id });
    if (ev.routeMapImage)imgs.push({ src: ev.routeMapImage, evTitle: ev.title, evDate: ev.date, evLocation: ev.location, evId: ev.id });
    if (ev.dayMapImages) ev.dayMapImages.forEach(function(u) { if (u) imgs.push({ src: u, evTitle: ev.title, evDate: ev.date, evLocation: ev.location, evId: ev.id }); });
  }
  return imgs;
}

function scheduleTick() {
  clearTimeout(timer);
  var interval = (state.slideInterval || 12) * 1000;
  // Offset left/right so they don't switch at the same time
  var offset = IS_LEFT ? 0 : Math.round(interval * 0.45);
  timer = setTimeout(function() { nextPhoto(); }, interval + offset);
}

function nextPhoto() {
  if (!photos.length) return;
  photoIdx = (photoIdx + 1) % photos.length;
  showPhoto(photoIdx);
  scheduleTick();
}

function showPhoto(idx) {
  if (!photos.length) return;
  var p = photos[idx];
  var img = document.getElementById("photoImg");
  var bg  = document.getElementById("photoBg");
  var ph  = document.getElementById("placeholder");

  ph.style.display = "none";
  img.classList.remove("visible");

  setTimeout(function() {
    img.src = p.src;
    bg.style.backgroundImage = "url(" + p.src + ")";
    img.onload = function() { img.classList.add("visible"); };
    // If already cached, onload may not fire
    if (img.complete && img.naturalWidth) img.classList.add("visible");

    // Info bar
    var infoBar  = document.getElementById("infoBar");
    var infoEv   = document.getElementById("infoEvent");
    var infoMeta = document.getElementById("infoMeta");
    if (p.evTitle) {
      infoEv.textContent = p.evTitle;
      var meta = [];
      if (p.evDate)     meta.push(new Date(p.evDate).toLocaleDateString("nb-NO", { weekday:"long", day:"numeric", month:"long" }));
      if (p.evLocation) meta.push("\ud83d\udccd " + p.evLocation);
      infoMeta.textContent = meta.join("   \u00b7   ");
      infoBar.style.display = "block";
    } else {
      infoBar.style.display = "none";
    }
    updateDots();
  }, 400);
}

function updateDots() {
  var d = document.getElementById("ambientDots");
  d.innerHTML = photos.slice(0, 12).map(function(_, i) {
    return '<div class="adot' + (i === photoIdx ? " active" : "") + '"></div>';
  }).join("");
}

function updateTicker() {
  var t  = document.getElementById("ticker");
  var ti = document.getElementById("tickerInner");
  if (state.ticker && state.ticker.trim()) {
    ti.textContent = state.ticker;
    t.style.display = "flex";
  } else {
    t.style.display = "none";
  }
}

// Hide cursor
setTimeout(function() { document.body.style.cursor = "none"; }, 3000);
document.addEventListener("mousemove", function() {
  document.body.style.cursor = "";
  clearTimeout(window._ct);
  window._ct = setTimeout(function() { document.body.style.cursor = "none"; }, 3000);
});
</script>
</body>
</html>`);
}

function buildTvPage(deptId, deptName, siteName, accent, logo, theme, typography) {
  const _tvTypo = typography || {};
  const _tvFont = _tvTypo.fontFamily || '"Helvetica Neue",Arial,"Noto Color Emoji",sans-serif';
  const _tvIsDark = (theme || "dark") !== "light";
  const _tvBg = _tvIsDark ? "#0a0a0a" : "#f0f0f0";
  const _tvText = _tvIsDark ? "#fff" : "#111";
  const esc = escHtml;
  return `<!DOCTYPE html>
<html lang="no">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<script>
// Auto-scale for 4K / high-res displays
// Detects actual window size and scales up if running below native resolution
(function(){
  var w = window.screen.width;
  var h = window.screen.height;
  // If screen reports 4K+ but window is 1080p (common Pi setup), apply scale
  if ((w >= 3840 || h >= 2160) && window.innerWidth <= 1920) {
    var s = w / window.innerWidth;
    document.documentElement.style.transform = 'scale(' + s + ')';
    document.documentElement.style.transformOrigin = '0 0';
    document.documentElement.style.width = (100/s) + '%';
    document.documentElement.style.height = (100/s) + '%';
  }
})();
</script>
<title>${esc(deptName)} – TV</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
html{font-size:1vw}
body{background:${_tvBg};color:${_tvText};font-family:${_tvFont};overflow:hidden;height:100dvh;width:100dvw}
#screen{width:100%;height:100%;position:relative;overflow:hidden}

/* SLIDE LAYER */
#slideLayer{position:absolute;inset:0;background:#000;transition:opacity .8s ease}
#slideImg{width:100%;height:100%;object-fit:contain;display:block}

/* CAMERA LAYER — fullscreen live stream overlay */
#cameraLayer{position:absolute;inset:0;background:#000;display:none;z-index:20}
#cameraLayer video{width:100%;height:100%;object-fit:cover}
#cameraLabel{position:absolute;bottom:1.5rem;left:1.5rem;background:rgba(0,0,0,.6);
  color:#fff;font-size:1.2rem;font-weight:700;padding:.4rem 1rem;border-radius:6px;
  display:flex;align-items:center;gap:.5rem}
#cameraLabel::before{content:"🔴";animation:tvpulse 1.5s ease-in-out infinite}
#cameraCount{position:absolute;top:1rem;right:1rem;background:rgba(0,0,0,.5);
  color:#fff;font-size:.9rem;padding:.3rem .8rem;border-radius:20px;display:none}
#slideEmpty{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:${_tvIsDark?"#555":"#999"};font-size:4vw}

/* EVENT LAYER — split: left list / right detail */
#eventLayer{position:absolute;inset:0;opacity:0;transition:opacity .8s ease;display:flex;overflow:hidden}

/* Left: event card list */
#evList{width:50%;flex-shrink:0;background:${_tvIsDark?"linear-gradient(135deg,#0d0d0d 0%,#111 100%)":"linear-gradient(135deg,#e8e8e8 0%,#f4f4f4 100%)"};display:flex;flex-direction:column;justify-content:center;padding:5vh 5vw;overflow:hidden;z-index:2;border-right:1px solid ${_tvIsDark?"rgba(255,255,255,.04)":"rgba(0,0,0,.07)"}}
.ev-card-tv{display:flex;gap:2.5vw;align-items:flex-start;margin-bottom:2.5vh;opacity:0;transform:translateY(20px);transition:opacity .5s,transform .5s}
.ev-card-tv.visible{opacity:1;transform:translateY(0)}
.ev-card-tv.active-ev{opacity:1}
.ev-thumb{width:clamp(44px,5.5vw,8vw);height:clamp(44px,5.5vw,8vw);object-fit:cover;border-radius:1vw;flex-shrink:0;border:2px solid ${_tvIsDark?"rgba(255,255,255,.1)":"rgba(0,0,0,.12)"}}
.ev-thumb-placeholder{width:clamp(44px,5.5vw,8vw);height:clamp(44px,5.5vw,8vw);border-radius:1vw;flex-shrink:0;display:flex;align-items:center;justify-content:center;border:2px solid ${_tvIsDark?"rgba(255,255,255,.08)":"rgba(0,0,0,.1)"}}
.ev-info{}
.ev-type-badge{font-size:clamp(.4.25vw,.7vw,1vw);font-weight:800;text-transform:uppercase;letter-spacing:.06em;padding:.2vw .7vw;border-radius:2vw;display:inline-block;margin-bottom:.4vh}
.ev-title-tv{font-size:clamp(.6.8vw,1.55vw,2.2vw);font-weight:900;line-height:1.2;margin-bottom:.3vh;color:${_tvText}}
.ev-meta-tv{font-size:clamp(.46.75vw,.95vw,1.4vw);color:${_tvIsDark?"#888":"#666"};display:flex;gap:.6vw;flex-wrap:wrap}
.ev-meta-tv span{display:flex;align-items:center;gap:.25vw}
.ev-card-tv.active-ev .ev-title-tv{color:${_tvText}}
.ev-card-tv{opacity:1}
/* ACTIVE ROW HIGHLIGHT — clearly marks which event is shown on the right */
.ev-card-tv{border-radius:1vw;padding:.9vh 1vw;margin-left:-1vw;margin-right:-1vw;transition:background .45s ease,box-shadow .45s ease,opacity .45s ease,transform .45s ease}
.ev-card-tv.active-ev{opacity:1;background:${esc(accent)}${_tvIsDark ? "30" : "26"}!important;box-shadow:0 .6vh 2vh ${_tvIsDark ? "rgba(0,0,0,.45)" : "rgba(0,0,0,.12)"};transform:translateX(.6vw)}
.ev-card-tv.active-ev .ev-thumb,.ev-card-tv.active-ev .ev-thumb-placeholder{box-shadow:0 0 0 .25vw ${esc(accent)}!important;border-color:transparent}
.ev-card-tv.active-ev .ev-meta-tv{color:${_tvIsDark ? "#ddd" : "#222"};font-weight:700}

/* Right: active event detail */
#evDetail{flex:1;position:relative;display:flex;flex-direction:column;justify-content:center;padding:6vh 4vw;overflow:hidden}
#evDetailBg{position:absolute;inset:0;transition:background 1.2s ease}
#evDetailContent{position:relative;z-index:1;display:flex;flex-direction:column;gap:2vh;font-family:inherit}

#evDetailBadgeRow{display:flex;align-items:center;gap:1vw;flex-wrap:wrap}
#evDetailBadge,#evDetailSgBadge{font-size:clamp(.46.75vw,.75vw,1.1vw);font-weight:800;text-transform:uppercase;letter-spacing:.08em;padding:.35vh 1.2vw;border-radius:2vw}
#evDetailOngoing{display:none;align-items:center;gap:.4vw;font-size:clamp(.4.25vw,.7vw,1vw);font-weight:800;text-transform:uppercase;letter-spacing:.05em;padding:.3vh .9vw;border-radius:2vw}
#evDetailTitle{font-size:clamp(1.19vw,3.2vw,4.5vw);font-weight:900;line-height:1.15;color:${_tvText}}
#evDetailMeta{display:flex;flex-direction:column;gap:.7vh}
.ev-detail-row{display:flex;align-items:center;gap:.8vw;font-size:clamp(.63.75vw,1.35vw,1.9vw);color:${_tvIsDark?"#ccc":"#333"}}

/* HEADER BAR */
#tvHeader{position:absolute;top:0;left:0;right:0;height:9vh;display:flex;align-items:center;padding:0 5vw;gap:2vw;z-index:10;background:linear-gradient(to bottom,${_tvIsDark?"rgba(0,0,0,.7)":"rgba(255,255,255,.7)"} 0%,transparent 100%)}
#tvLogo{height:6vh;max-height:5vw;object-fit:contain;display:${logo ? "block" : "none"}}
#tvSiteName{font-size:clamp(0.85vw,1.8vw,2.6vw);font-weight:900;color:${esc(accent)};letter-spacing:-.01em}

/* TICKER */
#ticker{position:absolute;bottom:0;left:0;right:0;height:5.5vh;min-height:32px;background:${esc(accent)};color:#111;display:flex;align-items:center;overflow:hidden;z-index:10}
#tickerInner{white-space:nowrap;font-weight:700;font-size:clamp(.7.65vw,1.6vw,2.4vw);padding-left:100%;animation:ticker-scroll 30s linear infinite}
@keyframes ticker-scroll{from{transform:translateX(0)}to{transform:translateX(-200%)}}
#ticker.hidden{display:none}

/* PROGRESS BAR */
#progressBar{position:absolute;bottom:5.5vh;left:0;height:.35vh;min-height:3px;background:${esc(accent)};transition:width 0s linear;z-index:5}

/* SLIDE FOOTER — department + event + uploader */
#slideFooter{position:absolute;bottom:5.5vh;left:0;right:0;display:none;align-items:flex-end;justify-content:space-between;padding:1.5vh 3vw;z-index:6;
  background:linear-gradient(to top,rgba(0,0,0,.65) 0%,transparent 100%);pointer-events:none}
#slideFooter.visible{display:flex}
#sfDept{font-size:clamp(.6rem,1.1vw,1.5rem);font-weight:800;color:#fff;opacity:.9;display:flex;align-items:center;gap:.6vw}
#sfDept img{height:clamp(14px,1.8vw,2.2rem);object-fit:contain;border-radius:.2vw}
#sfRight{text-align:right;max-width:50%}
#sfEvent{font-size:clamp(.55rem,1vw,1.3rem);font-weight:700;color:#fff;opacity:.9;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#sfUploader{font-size:clamp(.42rem,.7vw,.9rem);color:rgba(255,255,255,.6);font-weight:400;margin-top:.15vh}

/* SLIDE DOTS */
#slideDots{position:absolute;bottom:7vh;right:3vw;display:flex;flex-direction:column;gap:.5vh;z-index:5}
.sdot{width:.7vw;height:.7vw;min-width:6px;min-height:6px;border-radius:50%;background:${_tvIsDark?"#333":"#bbb"}}
.sdot.active{background:${esc(accent)}}

/* ANIMATION */
@keyframes evpulse{0%,100%{opacity:1}50%{opacity:.3}}
#evDetailOngoing span.pulse{animation:evpulse 1.2s ease-in-out infinite;display:inline-block}
.ev-card-tv.ev-ongoing .ev-thumb,.ev-card-tv.ev-ongoing .ev-thumb-placeholder{box-shadow:0 0 0 .3vw var(--ev-accent,#FFD100)}
/* NEXT YEAR: divider in the list, accent-tinted date, year pill in the detail */
.tv-year-div{display:flex;align-items:center;gap:1vw;margin:-1.2vh 0 1.3vh;font-size:clamp(.55rem,.9vw,1.3vw);font-weight:900;letter-spacing:.2em;color:${esc(accent)}}
.tv-year-div:before,.tv-year-div:after{content:"";flex:1;height:.25vh;min-height:2px;border-radius:2px;background:linear-gradient(90deg,transparent,${esc(accent)})}
.tv-year-div:after{background:linear-gradient(90deg,${esc(accent)},transparent)}
.tv-year-div span{padding:.2vh 1vw;border-radius:2vw;border:2px solid ${esc(accent)};background:${esc(accent)}22;color:${_tvIsDark ? esc(accent) : _tvText}}
.ev-card-tv.ev-next-year .ev-meta-tv{color:${_tvIsDark ? "#bbb" : "#444"}}
.ev-card-tv.ev-next-year .ev-meta-tv span:first-child{font-weight:700}
#evDetailYear{font-size:clamp(.46rem,.75vw,1.1vw);font-weight:900;letter-spacing:.12em;padding:.35vh 1.2vw;border-radius:2vw;border:2px solid ${esc(accent)};color:${_tvIsDark ? esc(accent) : _tvText};background:${esc(accent)}22}
.ev-detail-desc{font-size:clamp(.5.95vw,1.25vw,1.8vw);color:${_tvIsDark?"#999":"#555"};line-height:1.55;margin-top:.5vh;padding-top:.5vh;border-top:1px solid ${_tvIsDark?"rgba(255,255,255,.07)":"rgba(0,0,0,.08)"}}
.ev-detail-indent{opacity:.8}

/* TV-bilder topp/bunn */
#evDetailTopImg{width:100%;max-height:22vh;object-fit:cover;border-radius:1vw;display:none;margin-bottom:0}
#evDetailBottomImg{width:100%;max-height:22vh;object-fit:cover;border-radius:1vw;display:none;margin-top:0}

/* URL layer */
#urlLayer{position:absolute;inset:0;opacity:0;transition:opacity .8s;z-index:3;background:${_tvBg}}
</style>
</head>
<body>
<div id="screen">
  <!-- Header / watermark -->
  <div id="tvHeader" style="opacity:0;transition:opacity .4s">
    ${logo ? '<img id="tvLogo" src="' + (esc(logo)) + '" alt="' + (esc(siteName)) + '" style="height:6vh;max-height:5vw;object-fit:contain"/>' : ""}
    <div id="tvSiteName">${esc(siteName)}</div>
  </div>

  <!-- Slide layer -->
  <div id="slideLayer">
    <img id="slideImg" src="" style="display:none"/>
    <video id="slideVideo" autoplay muted playsinline loop style="display:none;position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#000;z-index:3"></video>
    <div id="slideMulti" style="display:none;position:absolute;inset:0;flex-direction:row;background:#000;z-index:3;gap:2px"></div>
    <div id="slideEmpty"><svg viewBox="0 0 60 50" style="width:6vw;height:5vw;fill:${_tvIsDark?"#333":"#ccc"}"><rect x="5" y="2" width="50" height="35" rx="4"/><rect x="20" y="37" width="20" height="6" fill="${_tvIsDark?"#222":"#bbb"}"/><rect x="14" y="43" width="32" height="4" rx="2"/></svg></div>
  </div>

  <!-- Camera live stream overlay -->
  <div id="cameraLayer">
    <video id="cameraVideo" autoplay muted playsinline style="width:100%;height:100%;object-fit:cover"></video>
    <div id="cameraLabel">Live</div>
    <div id="cameraCount"></div>
  </div>

  <!-- Event layer: left=cards (original), right=active detail -->
  <div id="eventLayer">
    <!-- Left: original event cards -->
    <div id="evList">
      <div id="evDeptName" style="font-size:clamp(.7rem,1.3vw,1.8vw);font-weight:800;letter-spacing:.03em;color:${_tvIsDark?'#999':'#555'};margin-bottom:1.8vh;padding-bottom:1vh;border-bottom:2px solid ${esc(accent)};display:flex;align-items:center;gap:.8vw">
        ${logo ? '<img src="' + esc(logo) + '" style="height:clamp(16px,2.2vw,3vw);object-fit:contain;border-radius:.3vw;opacity:.85" alt=""/>' : ''}
        <span>${esc(deptName)}</span>
      </div>
      <div id="evCards"></div>
    </div>
    <!-- Right: active event detail with color glow -->
    <div id="evDetail">
      <div id="evDetailBg"></div>
      <div id="evDetailContent">
        <img id="evDetailTopImg" src="" alt="" style="width:100%;max-height:22vh;object-fit:cover;border-radius:1vw;display:none;margin-bottom:0"/>
        <div style="display:flex;gap:1.5vw;align-items:flex-start;width:100%">
          <!-- Info-kolonne -->
          <div id="evDetailInfo" style="flex:1;min-width:0;display:flex;flex-direction:column;gap:.7vh">
            <div id="evDetailBadgeRow">
              <span id="evDetailSgBadge" style="display:none"></span>
              <span id="evDetailBadge"></span>
              <span id="evDetailOngoing">
                <span class="pulse" style="width:.5vw;height:.5vw;min-width:5px;min-height:5px;border-radius:50%;background:currentColor;display:inline-block"></span>
                Pågår nå
              </span>
            </div>
            <div id="evDetailTitle"></div>
            <div id="evDetailMeta"></div>
          </div>
          <!-- Tracking-kart til høyre -->
          <div id="evDetailTrackImg" style="width:38%;max-width:38%;flex-shrink:0;height:32vh;border-radius:1vw;overflow:hidden;display:none"></div>
        </div>
        <img id="evDetailBottomImg" src="" alt="" style="width:100%;max-height:22vh;object-fit:cover;border-radius:1vw;display:none;margin-top:0"/>
      </div>
    </div>
  </div>

  <!-- URL iframe layer -->
  <div id="urlLayer" style="position:absolute;inset:0;opacity:0;transition:opacity .8s;z-index:3;background:${_tvBg}"></div>

  <!-- Slide footer: department + event + uploader -->
  <div id="slideFooter">
    <div id="sfDept">${logo ? '<img src="' + esc(logo) + '" alt=""/>' : ''}<span>${esc(deptName)}</span></div>
    <div id="sfRight"><div id="sfEvent"></div><div id="sfUploader"></div></div>
  </div>

  <!-- Progress bar -->
  <div id="progressBar" style="width:0%"></div>

  <!-- Slide dots -->
  <div id="slideDots"></div>

  <!-- Ticker -->
  <div id="ticker" class="hidden"><div id="tickerInner"></div></div>
</div>

<script>
var DEPT_ID   = ${JSON.stringify(deptId)};
// Admin preview of one event (event list → «TV-forhåndsvisning»): ?preview=1&event=<id>
var _TV_PREVIEW_EV = new URLSearchParams(window.location.search).get('event') || '';
var DEPT_NAME = ${JSON.stringify(deptName)};
var ACCENT    = ${JSON.stringify(accent)};
// Compute whether text on ACCENT background should be dark or light
function accentTextColor(hex) {
  hex = hex.replace("#","");
  if (hex.length === 3) hex = hex[0]+hex[0]+hex[1]+hex[1]+hex[2]+hex[2];
  var r = parseInt(hex.slice(0,2),16);
  var g = parseInt(hex.slice(2,4),16);
  var b = parseInt(hex.slice(4,6),16);
  // Perceived luminance
  var lum = 0.299*r + 0.587*g + 0.114*b;
  return lum > 140 ? "#111111" : "#ffffff";
}
var ACCENT_TEXT = accentTextColor(ACCENT);
var IS_DARK = ${JSON.stringify(_tvIsDark)};

var state = { mode:"events", slides:[], slideInterval:15, showEvents:true, upcoming:[], ticker:"", eventCount:5 };
var slideIdx = 0;
var cyclePos = 0;
var timer = null;
var progressTimer = null;
var progressStart = 0;

// \u2500\u2500 Live camera streaming \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
var _cameras      = [];      // active HLS streams from server
var _camIdx       = 0;       // which camera is showing
var _camTimer     = null;    // rotation interval
var _camRotateS   = 30;      // seconds between camera switches
var _camHls       = null;    // current hls.js instance
var _camActive    = false;   // whether camera layer is showing

function loadHlsScript(cb) {
  if (window.Hls) return cb();
  var s = document.createElement('script');
  s.src = 'https://cdn.jsdelivr.net/npm/hls.js@latest';
  s.onload = cb;
  document.head.appendChild(s);
}

async function fetchCameras() {
  if (_TV_PREVIEW_EV) { _cameras = []; return; }
  try {
    var r = await fetch('/api/streams/public');
    var data = await r.json();
    _cameras = data.streams || [];
  } catch(e) { _cameras = []; }
}

async function startCameraMode() {
  await fetchCameras();
  if (!_cameras.length) return;   // no streams, stay in slide mode
  _camActive = true;
  _camIdx    = 0;
  document.getElementById('cameraLayer').style.display = 'block';
  if (_cameras.length > 1) {
    document.getElementById('cameraCount').style.display = 'block';
  }
  loadHlsScript(function() { showCamera(_camIdx); });
  if (_cameras.length > 1) {
    _camTimer = setInterval(function() {
      _camIdx = (_camIdx + 1) % _cameras.length;
      showCamera(_camIdx);
    }, _camRotateS * 1000);
  }
}

function stopCameraMode() {
  _camActive = false;
  document.getElementById('cameraLayer').style.display = 'none';
  document.getElementById('cameraCount').style.display = 'none';
  if (_camTimer) { clearInterval(_camTimer); _camTimer = null; }
  if (_camHls)   { _camHls.destroy(); _camHls = null; }
}

function showCamera(idx) {
  var cam = _cameras[idx];
  if (!cam) return;
  var video = document.getElementById('cameraVideo');
  var label = document.getElementById('cameraLabel');
  var count = document.getElementById('cameraCount');

  // Update label
  if (label) label.innerHTML = '\ud83d\udd34 ' + (cam.label || cam.key);
  if (count && _cameras.length > 1) {
    count.textContent = (idx + 1) + ' / ' + _cameras.length;
  }

  // Destroy previous HLS instance
  if (_camHls) { _camHls.destroy(); _camHls = null; }

  if (window.Hls && Hls.isSupported()) {
    _camHls = new Hls({ lowLatencyMode: true, maxBufferLength: 10 });
    _camHls.loadSource(cam.hlsUrl);
    _camHls.attachMedia(video);
    _camHls.on(Hls.Events.ERROR, function(e, data) {
      if (data.fatal) {
        console.warn('[camera] HLS error for ' + cam.key + ', skipping');
        // Try next camera on fatal error
        if (_cameras.length > 1) {
          _camIdx = (_camIdx + 1) % _cameras.length;
          showCamera(_camIdx);
        }
      }
    });
  } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
    video.src = cam.hlsUrl;
  }
  video.play().catch(function(){});
}

// Check for new cameras every 30 seconds
setInterval(async function() {
  var prev = _cameras.length;
  await fetchCameras();
  if (_cameras.length > 0 && !_camActive) {
    // Cameras appeared \u2014 switch to camera mode
    startCameraMode();
  } else if (_cameras.length === 0 && _camActive) {
    // All cameras gone \u2014 switch back to slides
    stopCameraMode();
  } else if (_cameras.length !== prev && _camActive) {
    // Camera count changed \u2014 update display
    document.getElementById('cameraCount').style.display = _cameras.length > 1 ? 'block' : 'none';
  }
}, 30000);

// Check for cameras on load
setTimeout(async function() {
  await fetchCameras();
  if (_cameras.length > 0) startCameraMode();
}, 3000);

// \u2500\u2500 SSE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function _loadPreviewEvent() {
  fetch('/api/tv-preview/event/' + encodeURIComponent(_TV_PREVIEW_EV), { credentials: 'same-origin', cache: 'no-store' })
    .then(function(r) { return r.ok ? r.json() : null; })
    .then(function(d) {
      if (!d || !d.event) { showNoSlides(); return; }
      applyState(Object.assign({}, d.state || {}, {
        type: 'state', mode: 'events', showEvents: true, slides: [], urlSlides: [],
        eventCount: 1, slideOrder: 'order', upcoming: [d.event],
        typeNames: d.typeNames || {}, typeColors: d.typeColors || {}, colors: d.colors || {}
      }));
    }).catch(function() { showNoSlides(); });
}
function _connectTvSSE() {
  if (_TV_PREVIEW_EV) { _loadPreviewEvent(); return; }
  var es = new EventSource("/api/tv/" + DEPT_ID + "/stream");
  es.onmessage = function(e) {
    try {
      var d = JSON.parse(e.data);
      if (d.type === "upcoming") {
        state.upcoming = d.upcoming || [];
        rebuildCycle();
        return;
      }
      applyState(d);
    } catch(x) {}
  };
  es.onerror = function() {
    es.close();
    setTimeout(_connectTvSSE, 3000);
  };
}
_connectTvSSE();

// Detect preview mode (embedded in admin iframe)
var IS_PREVIEW = new URLSearchParams(window.location.search).has('preview');

// Screens run by the screen agent open this page with their viewer key and
// the video version they should play (see MODULE: SCREENS in server.js).
var SCREEN_VK = new URLSearchParams(window.location.search).get('vk') || '';
var VIDEO_PROFILE = new URLSearchParams(window.location.search).get('profile') === 'smooth' ? 'smooth' : 'quality';
function _videoUrlFor(slide) {
  return (VIDEO_PROFILE === 'smooth' && slide && slide.smoothUrl) ? slide.smoothUrl : slide.url;
}
function _identifyEsc(s) { var d = document.createElement('div'); d.textContent = String(s == null ? '' : s); return d.innerHTML; }
if (SCREEN_VK) {
  (function pollIdentify() {
    fetch('/api/pi/identify?vk=' + encodeURIComponent(SCREEN_VK), { cache: 'no-store' })
      .then(function(r) { return r.ok ? r.json() : null; })
      .then(function(d) {
        var el = document.getElementById('screenIdentify');
        if (d && d.identify) {
          if (!el) {
            el = document.createElement('div');
            el.id = 'screenIdentify';
            el.style.cssText = 'position:fixed;inset:0;z-index:99999;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1vw;background:rgba(0,0,0,.85);color:#fff;text-align:center;box-shadow:inset 0 0 0 1.2vw ' + ACCENT;
            document.body.appendChild(el);
          }
          el.innerHTML = '<div style="font-size:6vw;font-weight:900">' + _identifyEsc(d.name) + '</div>'
            + '<div style="font-size:2vw;opacity:.7;font-family:monospace">' + _identifyEsc(d.device_id) + '</div>';
        } else if (el) {
          el.remove();
        }
      })
      .catch(function() {})
      .then(function() { setTimeout(pollIdentify, 5000); });
  })();
}

// \u2500\u2500 State \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function applyState(s) {
  if (s.type === "state") {
    Object.assign(state, s);
    // Rebuild and restart cycle when state changes
    if (timer) { clearTimeout(timer); timer = null; }
    rebuildCycle();
  }
  updateTicker();
  updateDots();
  updateLogo();
  syncAccentColor();
  if (!timer) startCycle();
}

function syncAccentColor() {
  var c = (state.progressColor && state.progressColor.trim()) ? state.progressColor : ACCENT;
  var dn = document.getElementById("evDeptName");
  if (dn) dn.style.borderBottomColor = c;
}

function updateLogo() {
  var header = document.getElementById("tvHeader");
  if (header) header.style.opacity = (state.showLogo !== false) ? "1" : "0";
}

// \u2500\u2500 Ticker \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function updateTicker() {
  var t = document.getElementById("ticker");
  var ti = document.getElementById("tickerInner");
  if (state.ticker && state.ticker.trim()) {
    ti.textContent = state.ticker;
    t.classList.remove("hidden");
  } else {
    t.classList.add("hidden");
  }
}

// \u2500\u2500 Dots \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function updateDots() {
  var d = document.getElementById("slideDots");
  var slides = state.slides || [];
  d.innerHTML = slides.map(function(_, i) {
    return '<div class="sdot' + (i === slideIdx ? " active" : "") + '"></div>';
  }).join("");
}

// \u2500\u2500 Progress bar \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function startProgress(duration) {
  var bar = document.getElementById("progressBar");
  if (!bar) return;
  var barColor = (state.progressColor && state.progressColor.trim()) ? state.progressColor : ACCENT;
  bar.style.background = barColor;
  bar.style.transition = "none";
  bar.style.width = "0%";
  requestAnimationFrame(function() {
    requestAnimationFrame(function() {
      bar.style.transition = "width " + duration + "s linear";
      bar.style.width = "100%";
    });
  });
}

// \u2500\u2500 Main cycle \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// The cycle is built ONCE and stored. Rebuilt only when state changes.
// Structure in "events" mode (events are most important):
//   [events, slide, slide, slide, events, slide, slide, slide, ...]
// Structure in "slides" mode:
//   [slide, slide, slide, ...]
var SLIDES_PER_BLOCK = 3;
var _builtCycle = [];   // stable cycle array, rebuilt on state change
var _cycleIdx   = 0;    // current position in _builtCycle

function rebuildCycle() {
  var slides   = state.slides || [];
  var upcoming = state.upcoming || [];
  var wantEvents = state.mode === "events" && state.showEvents && upcoming.length > 0;

  // Build index list \u2014 shuffle once if random
  var idxList = slides.map(function(_, i) { return i; });
  if (state.slideOrder === "random" && idxList.length > 1) {
    for (var s = idxList.length - 1; s > 0; s--) {
      var r = Math.floor(Math.random() * (s + 1));
      var tmp = idxList[s]; idxList[s] = idxList[r]; idxList[r] = tmp;
    }
  }

  var cycle = [];
  var evCount = wantEvents ? Math.min(upcoming.length, state.eventCount || 5) : 0;

  // build event-slots: tur-events with dagskart splittes in \u00e9n slot per dag
  var eventSlots = [];
  for (var ei = 0; ei < evCount; ei++) {
    var ev = upcoming[ei];
    if (ev && ev.eventType === 'tur' && ev.dayMapImages && ev.dayMapImages.length > 1) {
      for (var dj = 0; dj < ev.dayMapImages.length; dj++) {
        eventSlots.push({ type: 'event', evIdx: ei, dayIdx: dj });
      }
    } else {
      eventSlots.push({ type: 'event', evIdx: ei, dayIdx: null });
    }
  }

  if (!idxList.length) {
    for (var si2 = 0; si2 < eventSlots.length; si2++) {
      cycle.push(eventSlots[si2]);
    }
  } else if (!wantEvents) {
    // only slides
    idxList.forEach(function(i) { cycle.push({ type: "slide", idx: i }); });
  } else {
    // all event-slots sammenhengende, deretter slides
    for (var ei2 = 0; ei2 < eventSlots.length; ei2++) {
      cycle.push(eventSlots[ei2]);
    }
    idxList.forEach(function(i) { cycle.push({ type: "slide", idx: i }); });
  }

  // Append URL slides
  var urlSlides = state.urlSlides || [];
  urlSlides.forEach(function(u) {
    if (u && u.url) cycle.push({ type: "url", url: u.url, label: u.label || "", screenshotUrl: u.screenshotUrl || "" });
  });

  _builtCycle = cycle;
  _cycleIdx   = 0;
}

function startCycle() {
  if (timer) clearTimeout(timer);
  rebuildCycle();
  step();
}

function step() {
  var defaultInterval = (state.slideInterval || 15) * 1000;

  if (!_builtCycle.length) {
    showNoSlides();
    timer = setTimeout(step, defaultInterval);
    return;
  }

  if (_cycleIdx >= _builtCycle.length) {
    if (state.slideOrder === "random") {
      rebuildCycle();
    } else {
      _cycleIdx = 0;
    }
    if (!_TV_PREVIEW_EV) {
      setTimeout(function() { location.reload(); }, defaultInterval);
      return;
    }
  }

  var item = _builtCycle[_cycleIdx];
  _cycleIdx++;

  if (item.type === "event") {
    var _ev = (state.upcoming || [])[item.evIdx];
    if (_ev && !_TV_PREVIEW_EV) { fetch("/api/tv/" + DEPT_ID + "/active-event", { method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({ evId: _ev.id }) }).catch(function(){}); }
    showEventCards(state.upcoming || [], item.evIdx, item.dayIdx);
  } else if (item.type === "url") {
    if (!_TV_PREVIEW_EV) fetch("/api/tv/" + DEPT_ID + "/active-event", { method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({ evId: null }) }).catch(function(){});
    showUrlCard(item.url, item.label, item.screenshotUrl);
  } else {
    if (!_TV_PREVIEW_EV) fetch("/api/tv/" + DEPT_ID + "/active-event", { method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({ evId: null }) }).catch(function(){});
    showSlide(item.idx);
  }

  // find visningstid for denne sliden
  var slide = (item.type === "slide") ? (state.slides || [])[item.idx] : null;
  var interval = defaultInterval;

  if (slide && typeof slide === "object" && slide.type === "mp4-slide" && !slide.converting) {
    var vid = document.getElementById("slideVideo");
    clearTimeout(timer);

    // Preview-loop mode (e.g. tour camera angles): loop the clip and advance
    // strictly after duration seconds, like a timed slide.
    if (slide.loop) {
      var dur = (slide.duration || 20) * 1000;
      if (vid) { vid.loop = true; }
      startProgress(dur / 1000);
      timer = setTimeout(step, dur);
      return;
    }

    // Default video behaviour: play the full clip, then advance (max 10 min)
    var maxWait = Math.min((slide.duration || 600), 600) * 1000;
    var fallback = setTimeout(function() {
      if (vid) vid.removeEventListener("ended", onEnded);
      startProgress(defaultInterval / 1000);
      timer = setTimeout(step, defaultInterval);
    }, maxWait);
    var onEnded = function() {
      clearTimeout(fallback);
      if (vid) vid.removeEventListener("ended", onEnded);
      timer = setTimeout(step, 500);
    };
    if (vid) {
      vid.addEventListener("ended", onEnded);
      // If the video has already finished (loop=false), move on
      vid.loop = false;
    }
    startProgress(maxWait / 1000);
    return;
  } else if (slide && typeof slide === "object" && slide.duration) {
    // Individuell visningstid
    interval = slide.duration * 1000;
  }

  startProgress(interval / 1000);
  timer = setTimeout(step, interval);
}

// \u2500\u2500 Show slide \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function showDayMapSlide(item) {
  var sl      = document.getElementById("slideLayer");
  var img     = document.getElementById("slideImg");
  var vid     = document.getElementById("slideVideo");
  var empty   = document.getElementById("slideEmpty");
  var evLayer = document.getElementById("eventLayer");

  clearInterval(_evCycleTimer);
  sl.style.opacity  = "0";
  evLayer.style.opacity = "0";
  var urll = document.getElementById("urlLayer"); if (urll) urll.style.opacity = "0";
  if (vid) { vid.pause(); vid.style.display = "none"; vid.src = ""; }

  setTimeout(function() {
    empty.style.display = "none";
    img.style.display   = "block";
    img.src             = item.url;
    img.style.opacity   = "1";
    img.style.objectFit = "contain";

    // Day label at the top
    var existing = sl.querySelector(".daymap-label");
    if (existing) existing.remove();
    var label = document.createElement("div");
    label.className = "daymap-label";
    label.style.cssText = "position:absolute;top:1.5vh;left:50%;transform:translateX(-50%);background:rgba(0,0,0,.65);color:#fff;font-size:clamp(.8rem,1.2vw,1.4rem);font-weight:700;padding:.4vh 1.5vw;border-radius:2vw;z-index:10;white-space:nowrap;letter-spacing:.03em";
    label.textContent = (item.evTitle ? item.evTitle + " \u2013 " : "") + "Dag " + item.day + " av " + item.totalDays;
    sl.appendChild(label);

    sl.style.opacity = "1";
    updateDots();
  }, 100);
}

function showSlide(idx) {
  var slides = state.slides || [];
  if (!slides.length) { showNoSlides(); return; }
  var sl    = document.getElementById("slideLayer");
  var img   = document.getElementById("slideImg");
  var vid   = document.getElementById("slideVideo");
  var empty = document.getElementById("slideEmpty");
  var evLayer = document.getElementById("eventLayer");

  clearInterval(_evCycleTimer);
  sl.style.opacity = "0";
  evLayer.style.opacity = "0";
  var urll = document.getElementById("urlLayer"); if (urll) urll.style.opacity = "0";

  // remove eventuelle previous video-overlays and daymap-label
  sl.querySelectorAll(".slide-video-overlay,.daymap-label").forEach(function(v) { if (v.pause) v.pause(); v.remove(); });

  var slide = slides[idx];
  var isMp4   = slide && typeof slide === "object" && slide.type === "mp4-slide";
  var isMulti = slide && typeof slide === "object" && slide.type === "multi-slide";

  setTimeout(function() {
    empty.style.display = "none";
    var multiEl = document.getElementById("slideMulti");

    if (isMulti) {
      img.style.display = "none";
      if (vid) { vid.pause(); vid.style.display = "none"; vid.removeAttribute("data-src"); vid.src = ""; }
      multiEl.style.display = "flex";
      multiEl.innerHTML = "";
      var panels = slide.panels || [];
      panels.forEach(function(p) {
        var cell = document.createElement("div");
        cell.style.cssText = "flex:1;min-width:0;height:100%;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center";
        if (p.kind === "text") {
          cell.style.background = p.bg || "#111";
          var t = document.createElement("div");
          t.style.cssText = "color:" + (p.textColor || "#fff") + ";font-size:clamp(1.2rem,3vw,3.2rem);font-weight:700;text-align:center;padding:0 1.5rem;line-height:1.3;word-break:break-word";
          t.textContent = p.text || "";
          cell.appendChild(t);
        } else {
          cell.style.background = "#000";
          var pImg = document.createElement("img");
          pImg.src = p.url;
          pImg.style.cssText = "width:100%;height:100%;display:block";
          // Smart fit: detect orientation once loaded, portrait -> cover, landscape -> contain
          pImg.onload = function() {
            var portrait = pImg.naturalHeight > pImg.naturalWidth;
            pImg.style.objectFit = portrait ? "cover" : "contain";
          };
          cell.appendChild(pImg);
        }
        multiEl.appendChild(cell);
      });
    } else if (isMp4) {
      multiEl.style.display = "none"; multiEl.innerHTML = "";
      // use persistent video-element
      img.style.display = "none";
      vid.style.display = "block";
      var _vsrc = _videoUrlFor(slide);
      if (vid.getAttribute("data-src") !== _vsrc) {
        vid.setAttribute("data-src", _vsrc);
        if (SCREEN_VK) {
          // Screen agent: straight from the server (the old agent's cache port does not exist there)
          vid.onerror = null;
          vid.src = _vsrc;
          vid.load();
        } else {
          // Old agent: try its local cache first (port 9191/cache/), then the server — once
          var cacheUrl = "http://localhost:9191/cache/" + encodeURIComponent(_vsrc);
          var _fellBack = false;
          vid.onerror = function() {
            if (_fellBack) return;
            _fellBack = true;
            console.log("[tv] Cache miss, falling back to server:", _vsrc);
            vid.src = _vsrc;
            vid.load();
          };
          vid.src = cacheUrl;
          vid.load();
        }
      }
      if (IS_PREVIEW) {
        // In preview mode skip autoplay \u2014 browser blocks background-tab video
        vid.pause();
        // Show a still frame overlay instead
        var prevOverlay = sl.querySelector('.preview-vid-label');
        if (!prevOverlay) {
          prevOverlay = document.createElement('div');
          prevOverlay.className = 'preview-vid-label';
          prevOverlay.style.cssText = 'position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.5rem;background:rgba(0,0,0,.6);z-index:4;pointer-events:none';
          prevOverlay.innerHTML = '<span style="font-size:3vw">\ud83c\udfac</span><span style="font-size:1vw;color:var(--text2);font-weight:700">Video (forh\u00e5ndsvisning)</span>';
          sl.appendChild(prevOverlay);
        }
        prevOverlay.style.display = 'flex';
      } else {
        var _prevLbl = sl.querySelector('.preview-vid-label');
        if (_prevLbl) _prevLbl.style.display = 'none';
        var pp = vid.play();
        if (pp !== undefined) {
          pp.catch(function(e) {
            vid.muted = true;
            vid.play().catch(function(){});
          });
        }
      }
      // Camera-angle name label (tour multi-cam), styled like the daymap label
      if (slide.label) {
        var angLbl = document.createElement("div");
        angLbl.className = "daymap-label";
        angLbl.style.cssText = "position:absolute;top:1.5vh;left:50%;transform:translateX(-50%);background:rgba(0,0,0,.65);color:#fff;font-size:clamp(.8rem,1.2vw,1.4rem);font-weight:700;padding:.4vh 1.5vw;border-radius:2vw;z-index:10;white-space:nowrap;letter-spacing:.03em";
        angLbl.textContent = "\ud83d\udcf9 " + slide.label;
        sl.appendChild(angLbl);
      }
    } else {
      multiEl.style.display = "none"; multiEl.innerHTML = "";
      // PNG slide
      if (vid) { vid.pause(); vid.style.display = "none"; vid.removeAttribute("data-src"); vid.src = ""; }
      img.style.display = "block";
      img.src = (typeof slide === "string") ? slide : (slide && slide.bg) ? slide.bg : "";
    }

    sl.style.opacity = "1";

    // Update slide footer with event/uploader info
    var footer = document.getElementById("slideFooter");
    if (footer) {
      var hasInfo = slide && typeof slide === "object" && (slide.eventTitle || slide.uploaderName);
      var isMedia = (sl.style.opacity === "1" && evLayer.style.opacity === "0");
      if (isMedia || hasInfo) {
        footer.classList.add("visible");
        var sfEv = document.getElementById("sfEvent");
        var sfUp = document.getElementById("sfUploader");
        if (sfEv) sfEv.textContent = (slide && typeof slide === "object" && slide.eventTitle) ? slide.eventTitle : "";
        if (sfUp) sfUp.textContent = (slide && typeof slide === "object" && slide.uploaderName) ? "Foto: " + slide.uploaderName : "";
      } else {
        footer.classList.remove("visible");
      }
    }

    updateDots();
    var dots = document.querySelectorAll(".sdot");
    dots.forEach(function(d, i) { d.classList.toggle("active", i === idx); });
  }, 100);
}

function showNoSlides() {
  var sl = document.getElementById("slideLayer");
  var img = document.getElementById("slideImg");
  var empty = document.getElementById("slideEmpty");
  var evLayer = document.getElementById("eventLayer");
  img.style.display = "none";
  empty.style.display = "flex";
  sl.style.opacity = "1";
  evLayer.style.opacity = "0";
}

// \u2500\u2500 Show event cards \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function esc(s) { return String(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
// Subgroup badge colours: subgroup colour (or the screen accent) with readable text
function sgBadgeStyle(ev) {
  var c = String(ev.subgroupColor || ${JSON.stringify(accent || "#FFD100")}).replace("#", "");
  if (c.length === 3) c = c.charAt(0) + c.charAt(0) + c.charAt(1) + c.charAt(1) + c.charAt(2) + c.charAt(2);
  var n = parseInt(c, 16);
  if (isNaN(n) || c.length !== 6) { c = "FFD100"; n = parseInt(c, 16); }
  var lum = 0.299 * ((n >> 16) & 255) + 0.587 * ((n >> 8) & 255) + 0.114 * (n & 255);
  return { bg: "#" + c, color: lum > 150 ? "#111" : "#fff" };
}
function sgBadgeHtml(ev) {
  if (!ev || !ev.subgroupName) return "";
  var st = sgBadgeStyle(ev);
  return '<span class="ev-type-badge ev-sg-badge" style="background:' + st.bg + ';color:' + st.color + ';border:1px solid ' + st.bg + ';margin-right:.4vw">' + esc(ev.subgroupName) + '</span>';
}

function evTypeStyle(type) {
  var defaults = {
    stand: { bg:"#0d2a0d", color:"#7dff7d", border:"#2a5a2a" },
    mote:  { bg:"#2a2a0a", color:"#f5c500", border:"#5a5a0a" },
    kurs:  { bg:"#0a1a2a", color:"#7dc8ff", border:"#1a3a5a" },
    tur:   { bg:"#1a0a2a", color:"#d8b4fe", border:"#3a1a5a" },
  };
  // read from state.typeColors (satt from settings)
  if (state.typeColors && state.typeColors[type]) {
    var tc = state.typeColors[type];
    return { bg: tc.bg || defaults[type].bg, color: tc.text || defaults[type].color, border: tc.border || defaults[type].border };
  }
  // Fallback: read from colors.courseBg osv. (gammel settings-struktur)
  if (state.colors) {
    var c = state.colors;
    var fbMap = {
      kurs:  { bg: c.courseBg  || defaults.kurs.bg,  color: c.courseText  || defaults.kurs.color,  border: c.courseBorder  || defaults.kurs.border },
      tur:   { bg: c.tripBg   || defaults.tur.bg,   color: c.tripText   || defaults.tur.color,   border: c.tripBorder   || defaults.tur.border },
      stand: { bg: c.boothBg || defaults.stand.bg, color: c.boothText || defaults.stand.color, border: c.boothBorder || defaults.stand.border },
      mote:  { bg: c.anyBg   || defaults.mote.bg,  color: c.anyText   || defaults.mote.color,  border: c.anyBorder   || defaults.mote.border },
    };
    if (fbMap[type]) return fbMap[type];
  }
  return defaults[type] || defaults.stand;
}

function evTypeLabel(type) {
  // read from state.typeNames if tilgjengelig
  if (state.typeNames && state.typeNames[type]) return state.typeNames[type];
  var map = { stand:"Stand", mote:"M\u00f8te", kurs:"Kurs", tur:"Tur" };
  return map[type] || "Arrangement";
}

// "YYYY-MM-DD" (no time) is a local day, not UTC midnight (that showed "kl. 02:00")
function tvParseDate(d) {
  var s = String(d || "");
  if (s.length === 10 && s.charAt(4) === "-" && s.charAt(7) === "-") return new Date(+s.slice(0, 4), +s.slice(5, 7) - 1, +s.slice(8, 10));
  return new Date(d);
}
function tvHasTime(d) { return String(d || "").length > 10; }
// Years ahead of today (0 = this year)
function tvYearsAhead(d) { if (!d) return 0; return tvParseDate(d).getFullYear() - new Date().getFullYear(); }
function fmtDate(d) {
  if (!d) return "";
  var dt = tvParseDate(d);
  var opts = { weekday:"long", day:"numeric", month:"long" };
  if (dt.getFullYear() !== new Date().getFullYear()) opts.year = "numeric"; // next year: say so
  return dt.toLocaleDateString("nb-NO", opts)
    + (tvHasTime(d) ? " kl. " + dt.toLocaleTimeString("nb-NO", { hour:"2-digit", minute:"2-digit" }) : "");
}
function tvYearDivider(y) {
  return '<div class="tv-year-div"><span>' + y + '</span></div>';
}

function evEndMs(ev) {
  if (!ev.date) return null;
  if (ev.endDate) {
    var ed = new Date(ev.endDate);
    if (ev.endTime) { var p = ev.endTime.split(":"); ed.setHours(+p[0], +p[1], 0, 0); }
    else ed.setHours(23, 59, 59, 999);
    return ed.getTime();
  }
  var ed2 = new Date(ev.date);
  if (ev.endTime) { var p2 = ev.endTime.split(":"); ed2.setHours(+p2[0], +p2[1], 0, 0); if (ed2 <= new Date(ev.date)) ed2.setDate(ed2.getDate() + 1); }
  else ed2.setHours(23, 59, 59, 999);
  return ed2.getTime();
}

function isOngoing(ev) {
  if (!ev.date) return false;
  if (ev.cancelled) return false;          // cancelled events are never "ongoing"
  if (ev.status === 'moved' || ev.status === 'postponed') return false; // moved away
  if (ev.rescheduledToDate) return false;  // has a new date \u2014 not ongoing on the old one
  var now = Date.now();
  var start = new Date(ev.date).getTime();
  var end = evEndMs(ev);
  return start <= now && end && end >= now;
}

// \u2500\u2500 Per-event cycling state \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
var _evCurrentIdx = 0;
var _evCycleTimer = null;
var _evDayIdx = {};  // evId -> n\u00e5v\u00e6rende dag-indeks for dagskart-bl\u00e4dring

function showEventCards(upcoming, activeIdx, dayIdx) {
  if (!upcoming || !upcoming.length) return;
  var sl      = document.getElementById('slideLayer');
  var evLayer = document.getElementById('eventLayer');
  var cards   = document.getElementById('evCards');
  var count   = Math.min(upcoming.length, state.eventCount || 5);
  if (activeIdx === undefined) activeIdx = 0;
  activeIdx = activeIdx % count;

  sl.style.opacity = '0';
  var urll = document.getElementById('urlLayer'); if (urll) urll.style.opacity = '0';

  // \u2500\u2500 Left: render all cards, highlight the active one \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  var _prevYear = new Date().getFullYear();
  cards.innerHTML = upcoming.slice(0, count).map(function(ev, i) {
    var _yAhead = tvYearsAhead(ev.date);
    var _evYear = ev.date ? tvParseDate(ev.date).getFullYear() : _prevYear;
    var _divider = '';
    if (_evYear > _prevYear) { _divider = tvYearDivider(_evYear); _prevYear = _evYear; }
    var style   = evTypeStyle(ev.eventType);
    var ongoing = isOngoing(ev);
    var isActive = i === activeIdx;

    var ongoingBadge = ongoing
      ? '<span style="background:' + ACCENT + ';color:' + ACCENT_TEXT + ';font-size:clamp(.45rem,.65vw,.95vw);font-weight:800;padding:.2vh .7vw;border-radius:2vw;text-transform:uppercase;letter-spacing:.06em;margin-left:.4vw"><span class="pulse" style="display:inline-block;width:.5vw;height:.5vw;min-width:5px;min-height:5px;border-radius:50%;background:currentColor;margin-right:.25vw;vertical-align:middle"></span>P\u00e5g\u00e5r n\u00e5</span>'
      : '';
    // "Idag"-badge: event starts today but has not yet started
    var evDate = ev.date ? tvParseDate(ev.date) : null;
    var nowD   = new Date();
    var isToday = evDate
      && evDate.getFullYear() === nowD.getFullYear()
      && evDate.getMonth()    === nowD.getMonth()
      && evDate.getDate()     === nowD.getDate()
      && evDate.getTime()     > Date.now(); // not yet started
    var todayBadge = (!ongoing && isToday)
      ? '<span style="background:#1a2a3a;color:#60c8ff;border:1px solid #2a5a8a;font-size:clamp(.45rem,.65vw,.95vw);font-weight:800;padding:.2vh .7vw;border-radius:2vw;text-transform:uppercase;letter-spacing:.06em;margin-left:.4vw">I dag</span>'
      : '';
    // Background: active gets type-color tint, ongoing gets accent tint
    var cardBg = '';
    if (ongoing) {
      cardBg = 'background:' + ACCENT + '18;';
    } else if (isToday) {
      cardBg = 'background:#60c8ff0d;border-left:2px solid #60c8ff44;';
    }
    // Active row highlight is handled by the .active-ev CSS class
    var dotColor = ev.eventType === 'stand' ? '#4ade80' : ev.eventType === 'kurs' ? '#60a5fa' : ev.eventType === 'tur' ? '#c084fc' : '#facc15';
    var ringStyle = ongoing ? 'box-shadow:0 0 0 .3vw ' + ACCENT + ';' : '';
    var thumbWrapped = ev.image
      ? '<img class="ev-thumb" src="' + esc(ev.image) + '" style="' + ringStyle + '"/>'
      : '<div class="ev-thumb-placeholder" style="background:' + style.bg + ';' + ringStyle + ';display:flex;align-items:center;justify-content:center">'
          + '<div style="width:42%;height:42%;border-radius:50%;background:' + dotColor + '"></div>'
        + '</div>';
    // Status: cancelled, cancelled+moved (rescheduled), or moved-in-place
    var _isMoved = (ev.cancelled && ev.rescheduledToDate) || (!ev.cancelled && ev.status === 'moved');
    var _isCancelledOnly = ev.cancelled && !ev.rescheduledToDate;
    var _movedDateShort = ev.rescheduledToDate ? new Date(ev.rescheduledToDate).toLocaleDateString('nb-NO',{day:'numeric',month:'short'}) : '';
    var _statusBadge = '';
    if (_isCancelledOnly) {
      _statusBadge = cancelledBadge(ev, 'large');
    } else if (_isMoved) {
      _statusBadge = '<span style="margin-left:.4rem;background:#f59e0b;color:#1a1a1a;font-size:.6rem;font-weight:800;padding:2px 7px;border-radius:8px;letter-spacing:.04em">FLYTTET' + (_movedDateShort ? ' \u2192 ' + _movedDateShort : '') + '</span>';
    }
    var _dimCard   = _isCancelledOnly; // only fully-cancelled events are dimmed/struck
    var _borderCol = _isCancelledOnly ? '#ef4444' : (_isMoved ? '#f59e0b' : '');
    return _divider + '<div class="ev-card-tv' + (isActive ? ' active-ev' : '') + (ongoing ? ' ev-ongoing' : '') + (_isCancelledOnly ? ' ev-cancelled-tv' : '') + (_yAhead > 0 ? ' ev-next-year' : '') + '" id="evc_' + i + '" style="' + cardBg + (_borderCol ? ';border-left:4px solid ' + _borderCol + (_dimCard ? ';opacity:.85' : '') : '') + '">'
      + thumbWrapped
      + '<div class="ev-info">'
      + '<div>' + sgBadgeHtml(ev) + '<span class="ev-type-badge" style="background:' + style.bg + ';color:' + style.color + ';border:1px solid ' + style.border + '">' + evTypeLabel(ev.eventType) + '</span>' + ongoingBadge + todayBadge + _statusBadge + '</div>'
      + '<div class="ev-title-tv" style="' + (_dimCard ? 'text-decoration:line-through;opacity:.6' : '') + '">' + esc(ev.title) + '</div>'
      + '<div class="ev-meta-tv">'
      + (ev.date ? '<span>' + (isToday ? 'I dag kl. ' + new Date(ev.date).toLocaleTimeString('nb-NO',{hour:'2-digit',minute:'2-digit'}) : fmtDate(ev.date)) + '</span>' : '')
      + (_isMoved && _movedDateShort ? '<span style="color:#f59e0b;font-weight:700">Ny dato: ' + esc(new Date(ev.rescheduledToDate).toLocaleDateString('nb-NO',{weekday:'short',day:'numeric',month:'long'})) + '</span>' : '')
      + '</div></div></div>';
  }).join('');

  // Animate cards in
  setTimeout(function() {
    evLayer.style.opacity = '1';
    var sftr = document.getElementById("slideFooter"); if (sftr) sftr.classList.remove("visible");
    var cardEls = cards.querySelectorAll('.ev-card-tv');
    cardEls.forEach(function(c, i) {
      setTimeout(function() { c.classList.add('visible'); }, i * 120);
    });
  }, 80);

  // \u2500\u2500 Right: show detail for active event only \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  clearInterval(_evCycleTimer); // no internal cycling \u2014 cycle is driven by step()
  _showEvDetail(upcoming, activeIdx, count, dayIdx);
}


function _showEvDetail(upcoming, idx, count, dayIdx) {
  var ev    = upcoming[idx];
  var style = evTypeStyle(ev.eventType);
  var going = isOngoing(ev);

  for (var i = 0; i < count; i++) {
    var c = document.getElementById('evc_' + i);
    if (c) c.classList.toggle('active-ev', i === idx);
  }

  var bg = document.getElementById('evDetailBg');
  if (bg) {
    var _bgBase = IS_DARK ? '#080808' : '#e8e8e8';
    var _bgOuter = IS_DARK ? '#0d0d0d' : '#f0f0f0';
    bg.style.background =
      'radial-gradient(ellipse 80% 90% at 40% 50%, '
      + style.color + (IS_DARK ? '28' : '18') + ' 0%, '
      + style.color + '0d 50%, '
      + _bgBase + ' 100%), ' + _bgOuter;
  }

  var topImg = document.getElementById('evDetailTopImg');
  if (topImg) {
    // for tur-events: show rutekart top
    var topSrc = (ev.eventType === 'tur' && ev.routeMapImage) ? ev.routeMapImage : ev.tvImageTop;
    if (topSrc) { topImg.src = topSrc; topImg.style.display = 'block'; }
    else         { topImg.src = ''; topImg.style.display = 'none'; }
  }

  // Live tracking for trip events - only while the event is running now
  var trackDiv = document.getElementById('evDetailTrackImg');
  if (trackDiv) {
    clearInterval(window._trackingRefresh);
    if (!IS_PREVIEW && ev.eventType === 'tur' && ev.liveTrackingUrl && going) {
      trackDiv.style.display = 'block';
      trackDiv.innerHTML = '<div style="position:relative;width:100%;height:100%;overflow:hidden;border-radius:1vw">'
        + '<iframe src="' + ev.liveTrackingUrl + '" style="width:160%;height:160%;border:none;transform:scale(0.625);transform-origin:top left;pointer-events:none" allow="geolocation" sandbox="allow-scripts allow-same-origin allow-popups"></iframe>'
        + '<div style="position:absolute;top:.4rem;left:.4rem;background:rgba(0,0,0,.6);color:#fff;font-size:.7rem;padding:2px 6px;border-radius:4px;z-index:2">\ud83d\udce1 LIVE SPORING</div>'
        + '</div>';
      window._trackingRefresh = setInterval(function() {
        var iframe = trackDiv.querySelector('iframe');
        if (iframe) iframe.src = ev.liveTrackingUrl + (ev.liveTrackingUrl.includes('?') ? '&' : '?') + '_t=' + Date.now();
      }, 30000);
    } else {
      trackDiv.style.display = 'none';
      trackDiv.innerHTML = '';
    }
  }




  var yearPill = document.getElementById('evDetailYear');
  if (!yearPill) {
    var _row = document.getElementById('evDetailBadgeRow');
    if (_row) { yearPill = document.createElement('span'); yearPill.id = 'evDetailYear'; _row.appendChild(yearPill); }
  }
  if (yearPill) {
    if (tvYearsAhead(ev.date) > 0) { yearPill.textContent = tvParseDate(ev.date).getFullYear(); yearPill.style.display = ''; }
    else yearPill.style.display = 'none';
  }
  var sgBadge = document.getElementById('evDetailSgBadge');
  if (sgBadge) {
    if (ev.subgroupName) {
      var sgSt = sgBadgeStyle(ev);
      sgBadge.textContent = ev.subgroupName;
      sgBadge.style.background = sgSt.bg;
      sgBadge.style.color = sgSt.color;
      sgBadge.style.border = '1px solid ' + sgSt.bg;
      sgBadge.style.display = '';
    } else {
      sgBadge.style.display = 'none';
    }
  }
  var badge = document.getElementById('evDetailBadge');
  if (badge) {
    badge.textContent      = evTypeLabel(ev.eventType);
    badge.style.background = style.bg;
    badge.style.color      = style.color;
    badge.style.border     = '1px solid ' + style.border;
  }

  var ongoingEl = document.getElementById('evDetailOngoing');
  if (ongoingEl) {
    ongoingEl.style.display    = going ? 'inline-flex' : 'none';
    ongoingEl.style.background = ACCENT;
    ongoingEl.style.color      = ACCENT_TEXT;
  }

  var titleEl = document.getElementById('evDetailTitle');
  if (titleEl) {
    titleEl.textContent = ev.title || '';
    titleEl.style.textDecoration = ev.cancelled ? 'line-through' : '';
    titleEl.style.opacity        = ev.cancelled ? '0.6' : '';
  }

  // Cancelled banner in detail
  var cancelBanner = document.getElementById('evDetailCancelBanner');
  if (!cancelBanner) {
    cancelBanner = document.createElement('div');
    cancelBanner.id = 'evDetailCancelBanner';
    cancelBanner.style.cssText = 'display:none;background:#ef4444;color:#fff;font-weight:800;font-size:1.1rem;letter-spacing:.05em;padding:.6rem 1.25rem;border-radius:.6vw;margin-bottom:.75rem;text-align:center';
    var detailContent = document.getElementById('evDetailContent') || document.getElementById('evDetailMeta');
    if (detailContent && detailContent.parentNode) {
      detailContent.parentNode.insertBefore(cancelBanner, detailContent);
    }
  }
  if (cancelBanner) {
    var _detMoved = (ev.cancelled && ev.rescheduledToDate) || (!ev.cancelled && ev.status === 'moved');
    if (ev.cancelled && !ev.rescheduledToDate) {
      cancelBanner.style.display = 'block';
      cancelBanner.style.background = '#ef4444';
      cancelBanner.style.color = '#fff';
      cancelBanner.textContent = '\ud83d\udeab AVLYST' + (ev.cancelReason ? ' \u2013 ' + ev.cancelReason : '');
    } else if (_detMoved) {
      cancelBanner.style.display = 'block';
      cancelBanner.style.background = '#f59e0b';
      cancelBanner.style.color = '#1a1a1a';
      var _newD = ev.rescheduledToDate ? fmtDate(ev.rescheduledToDate) : '';
      cancelBanner.textContent = '\ud83d\udcc5 FLYTTET' + (_newD ? ' til ' + _newD : ' til ny dato')
        + (ev.movedNote ? ' \u2013 ' + ev.movedNote : (ev.cancelReason ? ' \u2013 ' + ev.cancelReason : ''));
      titleEl && (titleEl.style.textDecoration = '', titleEl.style.opacity = '');
    } else {
      cancelBanner.style.display = 'none';
      cancelBanner.textContent = '';
    }
  }

  var metaEl = document.getElementById('evDetailMeta');
  if (metaEl) {
    // Build rows using DOM to avoid any quote issues
    var frag = document.createDocumentFragment();

    function addRow(icon, text) {
      var d = document.createElement('div');
      d.className = 'ev-detail-row';
      var s1 = document.createElement('span');
      s1.textContent = icon;
      s1.style.cssText = 'color:' + (IS_DARK ? '#888' : '#666') + ';font-size:.85em;min-width:6em;flex-shrink:0';
      var s2 = document.createElement('span');
      s2.textContent = text;
      d.appendChild(s1);
      d.appendChild(s2);
      frag.appendChild(d);
    }

    if (ev.date)     addRow('Dato:', fmtDate(ev.date));
    if (ev.rescheduledToDate) addRow('Ny dato:', fmtDate(ev.rescheduledToDate));
    if (ev.location) addRow('Sted:', ev.location);

    if (ev.maxParticipants || ev.registrationCount) {
      var regStr = '';
      if (ev.registrationCount !== null && ev.registrationCount !== undefined) {
        regStr = ev.registrationCount + (ev.maxParticipants ? ' / ' + ev.maxParticipants : '') + ' p\u00e5meldt';
      } else if (ev.maxParticipants) {
        regStr = 'Maks ' + ev.maxParticipants + ' plasser';
      }
      if (regStr) addRow('Deltakere:', regStr);
    }

    if (ev.routeSummary) {
      var r = ev.routeSummary;
      var routeParts = [];
      if (r.days > 1) routeParts.push(r.days + ' dager');
      if (r.km)       routeParts.push(r.km + ' km');
      if (routeParts.length) addRow('Rute:', routeParts.join(' \u00b7 '));
      if (r.stops && r.stops.length >= 2) {
        addRow('', r.stops[0] + ' \u2192 ' + r.stops[r.stops.length - 1]);
      }
    }

    if (ev.description) {
      // Descriptions are rich-text HTML; show them as plain text (tags appeared literally)
      // DOMParser builds an inert document: nothing in it loads or runs
      var _doc = new DOMParser().parseFromString(String(ev.description).split('</p>').join('</p> ').split('<br>').join(' '), 'text/html');
      var plain = ((_doc.body && _doc.body.textContent) || '').replace(/ +/g, ' ').trim();
      var desc = plain.length > 180 ? plain.slice(0, 177) + '\u2026' : plain;
      var dd = document.createElement('div');
      dd.className = 'ev-detail-desc';
      dd.textContent = desc;
      frag.appendChild(dd);
    }

    metaEl.innerHTML = '';
    metaEl.appendChild(frag);
  }

  var botImg = document.getElementById('evDetailBottomImg');
  if (botImg) {
    var botSrc = null;
    if (ev.eventType === 'tur' && ev.dayMapImages && ev.dayMapImages.length) {
      var useDayIdx = (dayIdx !== null && dayIdx !== undefined) ? dayIdx : 0;
      botSrc = ev.dayMapImages[useDayIdx] || ev.dayMapImages[0];
    }
    if (!botSrc) botSrc = ev.tvImageBottom;
    if (botSrc) { botImg.src = botSrc; botImg.style.display = 'block'; }
    else         { botImg.style.display = 'none'; }
  }
}


// \u2500\u2500 URL QR card slide \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function showUrlCard(url, label, screenshotUrl) {
  var sl      = document.getElementById('slideLayer');
  var evLayer = document.getElementById('eventLayer');
  var urlLay  = document.getElementById('urlLayer');
  if (!urlLay) return;
  clearInterval(_evCycleTimer);
  sl.style.opacity = '0';
  evLayer.style.opacity = '0';
  urlLay.innerHTML = '';

  // Full-screen QR card \u2014 works even when sites block iframes
  var card = document.createElement('div');
  // If we have a screenshot, show it as a dark-overlaid background
  if (screenshotUrl) {
    urlLay.style.backgroundImage = 'url(' + screenshotUrl + ')';
    urlLay.style.backgroundSize = 'cover';
    urlLay.style.backgroundPosition = 'top center';
    // Dark overlay so QR card is readable
    var overlay = document.createElement('div');
    overlay.style.cssText = 'position:absolute;inset:0;background:rgba(0,0,0,.65);z-index:0';
    urlLay.appendChild(overlay);
  } else {
    urlLay.style.backgroundImage = '';
  }

  card.style.cssText = 'position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4vh;text-align:center;padding:6vh 8vw;width:100%;height:100%';

  // Label / title
  if (label) {
    var titleEl = document.createElement('div');
    titleEl.style.cssText = 'font-size:clamp(1.4rem,2.8vw,4vw);font-weight:900;color:#fff;letter-spacing:-.01em';
    titleEl.textContent = label;
    card.appendChild(titleEl);
  }

  // QR code \u2014 large and centered
  var qrWrap = document.createElement('div');
  qrWrap.style.cssText = 'background:#fff;border-radius:1.5vw;padding:1.2vw;box-shadow:0 .8vw 4vw rgba(0,0,0,.5)';
  var qrImg = document.createElement('img');
  var size = Math.round(Math.min(window.innerWidth, window.innerHeight) * 0.32);
  var qrColor = ACCENT.replace('#', '');
  qrImg.src = '/qr.png?s=' + size + '&m=2&c=' + qrColor + '&d=' + encodeURIComponent(url);
  qrImg.style.cssText = 'display:block;width:' + size + 'px;height:' + size + 'px;max-width:32vw;max-height:32vw';
  qrWrap.appendChild(qrImg);
  card.appendChild(qrWrap);

  // Instruction text
  var scanTxt = document.createElement('div');
  scanTxt.style.cssText = 'font-size:clamp(.85rem,1.8vw,2.6vw);color:var(--ev-muted);font-weight:600';
  scanTxt.textContent = 'Scan QR-koden for \u00e5 \u00e5pne p\u00e5 din mobil';
  card.appendChild(scanTxt);

  // URL text
  var urlTxt = document.createElement('div');
  urlTxt.style.cssText = 'font-size:clamp(.65rem,1.1vw,1.6vw);color:var(--text2);font-family:monospace';
  urlTxt.textContent = url.split('://').slice(1).join('://') || url;
  card.appendChild(urlTxt);

  urlLay.appendChild(card);
  setTimeout(function() { urlLay.style.opacity = '1'; }, 50);
}

// \u2500\u2500 Init \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Hide cursor after 3s
setTimeout(function() { document.body.style.cursor = "none"; }, 3000);
document.addEventListener("mousemove", function() {
  document.body.style.cursor = "";
  clearTimeout(window._cursorTimer);
  window._cursorTimer = setTimeout(function() { document.body.style.cursor = "none"; }, 3000);
});
</script>

<footer style="position:fixed;bottom:5.5vh;left:0;right:0;text-align:center;padding:.25rem;font-size:.55rem;color:rgba(255,255,255,.25);pointer-events:none;z-index:200;letter-spacing:.04em">Event-Admin.online \u00b7 v${APP_VERSION}</footer>
</body>
</html>`;
}

app.get("/display/:evId", function(req, res) {
  const rawId  = req.params.evId;
  const ev     = readJSON(EVENTS_FILE).find(function(e) { return e.id === rawId || e.slug === rawId; });
  const evId   = ev ? ev.id : rawId;
  const title  = ev ? escHtml(ev.title || '') : "Arrangement";
  const settings = getSettings();
  const siteName = settings.siteName || "Event-Admin";
  const deptApp  = ev ? getDeptAppearance(ev) : getDeptAppearanceById(null);
  const accent   = deptApp.accent;
  const _dispTheme = deptApp.themeDisplay || deptApp.theme;
  const _dispTypo  = deptApp.typography || {};
  const _dispFont  = _dispTypo.fontFamily || 'system-ui,sans-serif';
  const _dispIsDark = _dispTheme !== 'light';

  res.send(`<!DOCTYPE html>
<html lang="no">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<script>
// Auto-scale for 4K / high-res displays
// Detects actual window size and scales up if running below native resolution
(function(){
  var w = window.screen.width;
  var h = window.screen.height;
  // If screen reports 4K+ but window is 1080p (common Pi setup), apply scale
  if ((w >= 3840 || h >= 2160) && window.innerWidth <= 1920) {
    var s = w / window.innerWidth;
    document.documentElement.style.transform = 'scale(' + s + ')';
    document.documentElement.style.transformOrigin = '0 0';
    document.documentElement.style.width = (100/s) + '%';
    document.documentElement.style.height = (100/s) + '%';
  }
})();
</script>
<title>${title} – Skjerm</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box}
  body{background:${_dispIsDark?"#0a0a0a":"#f5f5f5"};color:${_dispIsDark?"#fff":"#111"};font-family:${_dispFont};overflow:hidden;height:100dvh;width:100dvw}
  #screen{width:100%;height:100%;position:relative;display:flex;align-items:center;justify-content:center}

  /* SLIDES */
  #slideWrap{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:#000}
  #slideImg{width:100%;height:100%;object-fit:cover;transition:opacity .5s}
  #slideEmpty{color:#333;font-size:1.5rem;text-align:center;padding:2rem}
  #slideNav{position:absolute;bottom:1.2rem;left:50%;transform:translateX(-50%);display:flex;gap:.5rem;z-index:2}
  .sdot{width:9px;height:9px;border-radius:50%;background:#333;transition:background .3s}
  .sdot.active{background:${accent}}
@keyframes tvpulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.4;transform:scale(.7)}}
.ev-ongoing{animation:tv-glow 2.5s ease-in-out infinite}
@keyframes tv-glow{0%,100%{box-shadow:none}50%{box-shadow:inset 0 0 0 1px ${accent}33}}
  #slideProgress{position:absolute;bottom:3.2rem;left:0;height:3px;background:${accent};transition:width 0s linear;opacity:.6}

  /* WINNER */
  #winnerWrap{position:absolute;inset:0;display:none;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:2rem;background:radial-gradient(ellipse at center,#1a0a2e 0%,#0a0a0a 70%)}
  #drumRoll{font-size:clamp(1rem,3vw,1.8rem);color:var(--ev-muted);letter-spacing:.15em;text-transform:uppercase;margin-bottom:1rem;min-height:2rem}
  #winnerReveal{opacity:0;transform:scale(.7);transition:opacity .6s ease,transform .6s ease;display:flex;flex-direction:column;align-items:center}
  #winnerReveal.show{opacity:1;transform:scale(1)}
  #prizeImageWrap{margin-bottom:1rem;display:none}
  #prizeImg{width:clamp(120px,20vw,240px);height:clamp(120px,20vw,240px);object-fit:contain;border-radius:16px;border:3px solid ${accent};box-shadow:0 0 40px ${accent}44;animation:bounce 1s ease infinite alternate}
  #winnerEmoji{font-size:clamp(4rem,10vw,8rem);animation:bounce 1s ease infinite alternate;display:block;margin-bottom:.5rem}
  @keyframes bounce{from{transform:scale(1)}to{transform:scale(1.1)}}
  #winnerLabel{font-size:clamp(.9rem,2vw,1.2rem);color:var(--ev-muted);letter-spacing:.1em;text-transform:uppercase;margin-bottom:.35rem}
  #winnerName{font-size:clamp(2.5rem,8vw,6rem);font-weight:900;color:${accent};line-height:1;text-shadow:0 0 60px ${accent}66,0 0 20px ${accent}44}
  #winnerPrize{font-size:clamp(1rem,2.5vw,1.8rem);color:#ccc;margin-top:.75rem}
  #winnerCountdown{position:absolute;bottom:3.5rem;font-size:.85rem;color:var(--text2);letter-spacing:.05em}
  #winnerTag{position:absolute;bottom:1.5rem;font-size:.85rem;color:#2a2a2a;letter-spacing:.12em;text-transform:uppercase}

  /* TICKER */
  #ticker{position:absolute;bottom:0;left:0;right:0;background:${accent};overflow:hidden;height:3.2rem;display:none;z-index:5;display:flex;align-items:center}
  #tickerLabel{flex-shrink:0;background:rgba(0,0,0,.2);color:#111;font-weight:900;font-size:1rem;padding:0 1.4rem 0 1rem;height:100%;display:flex;align-items:center;letter-spacing:.04em;white-space:nowrap;position:relative;margin-right:1.2rem}
  #tickerLabel::after{content:"";position:absolute;right:-1.15rem;top:0;width:0;height:100%;border-style:solid;border-width:calc(3.2rem/2) 0 calc(3.2rem/2) 1.15rem;border-color:transparent transparent transparent rgba(0,0,0,.2)}
  #tickerScroll{flex:1;overflow:hidden;height:100%;position:relative}
  #tickerInner{white-space:nowrap;display:inline-block;font-size:1rem;color:#111;font-weight:700;position:absolute;top:50%;}
  #tickerWinners{white-space:nowrap;display:inline-block;font-size:1rem;color:#fff;position:absolute;top:50%;transform:translateY(-50%);padding-left:2rem}
  @keyframes scrollTicker{from{transform:translateY(-50%) translateX(0)}to{transform:translateY(-50%) translateX(100vw)}}

  /* CONFETTI */
  .confetti{position:absolute;border-radius:2px;opacity:0;pointer-events:none}
  @keyframes confettiFall{0%{opacity:1;transform:translateY(-40px) rotate(0deg) scale(1)}100%{opacity:0;transform:translateY(105vh) rotate(720deg) scale(.5)}}

  /* WINNER CARD (rotation overlay) */
  #winnerCardOverlay{position:absolute;inset:0;display:none;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:3rem;z-index:10;background:radial-gradient(ellipse at center,#1a0a2e 0%,#0a0a0a 80%);opacity:0;transition:opacity .4s}
  #winnerCardOverlay.show{opacity:1}
  #wcLabel{font-size:clamp(.9rem,2vw,1.4rem);color:var(--ev-muted);letter-spacing:.15em;text-transform:uppercase;margin-bottom:.75rem}
  #wcImg{width:clamp(100px,18vw,220px);height:clamp(100px,18vw,220px);object-fit:contain;border-radius:14px;border:3px solid ${accent};margin-bottom:1.25rem;animation:wcBounce 2s ease infinite alternate}
  @keyframes wcBounce{from{transform:scale(1)}to{transform:scale(1.05)}}
  #wcNames{display:flex;flex-wrap:wrap;justify-content:center;gap:.5rem 1.5rem;margin-bottom:.5rem;max-width:90vw}
  .wc-name-single{font-size:clamp(3rem,10vw,7rem);font-weight:900;color:${accent};line-height:1;text-shadow:0 0 60px ${accent}55}
  .wc-name-multi{font-size:clamp(1.8rem,5vw,4rem);font-weight:900;color:${accent};line-height:1.1;text-shadow:0 0 40px ${accent}44}
  #wcPrize{font-size:clamp(1.2rem,3vw,2.5rem);color:#ccc;font-weight:600}
  #wcTrophy{font-size:clamp(2rem,5vw,4rem);margin-bottom:.5rem;animation:wcBounce 1.5s ease infinite alternate}
</style>
</head>
<body>
<div id="screen">

  <div id="slideWrap">
    <div id="slideEmpty">Ingen slides lastet opp ennå</div>
    <img id="slideImg" style="display:none" alt=""/>
    <div id="slideNav"></div>
    <div id="slideProgress" style="width:0%"></div>
  </div>

  <!-- Winner card shown in slide rotation -->
  <div id="winnerCardOverlay">
    <img id="wcImg" src="" alt="" style="display:none"/>
    <div id="wcTrophy">🏆</div>
    <div id="wcLabel">Vinnere</div>
    <div id="wcNames"></div>
    <div id="wcPrize"></div>
  </div>

  <div id="winnerWrap">
    <div id="drumRoll"></div>
    <div id="winnerReveal">
      <div id="prizeImageWrap"><img id="prizeImg" src="" alt="Premie"/></div>
      <span id="winnerEmoji">🏆</span>
      <div id="winnerLabel">Vinner</div>
      <div id="winnerName"></div>
      <div id="winnerPrize"></div>
    </div>
    <div id="winnerCountdown"></div>
    <div id="winnerTag">${escHtml(siteName)}</div>
  </div>

  <div id="ticker">
    <div id="tickerLabel">&#127942; Vinnere</div>
    <div id="tickerScroll"><span id="tickerInner"></span></div>
  </div>
</div>
<script>
var evId   = "${escHtml(evId)}";
var state  = { mode:"slides", slide:0, slides:[], ticker:"", winnerName:"", prize:"", slideInterval:10, winnerDuration:300, winners:[], winnerCardInterval:5 };
var _winnerCardIndex = 0; // which winner to show next in rotation
var _slidesSinceCard = 0; // count slides shown since last winner card
var slideAdvanceTimer = null;
var slideProgressTimer = null;
var winnerReturnTimer  = null;
var winnerShown = false;
var lastWinnerName = "";

function applyState(s) {
  var prevMode = state.mode;
  var prevName = state.winnerName;
  if (s.slides        !== undefined) state.slides        = s.slides;
  if (s.mode          !== undefined) state.mode          = s.mode;
  if (s.slide         !== undefined) state.slide         = parseInt(s.slide) || 0;
  if (s.winnerName    !== undefined) state.winnerName    = s.winnerName || "";
  if (s.prize         !== undefined) state.prize         = s.prize  || "";
  if (s.prizeImage    !== undefined) state.prizeImage    = s.prizeImage || null;
  if (s.ticker        !== undefined) state.ticker        = s.ticker || "";
  if (s.slideInterval !== undefined) state.slideInterval = Math.max(3, parseInt(s.slideInterval) || 10);
  if (s.winnerDuration    !== undefined) state.winnerDuration    = Math.max(10, parseInt(s.winnerDuration) || 300);
  if (s.winners           !== undefined) state.winners           = s.winners || [];
  if (s.winnerCardInterval!== undefined) state.winnerCardInterval= Math.max(0, parseInt(s.winnerCardInterval) || 5);

  // New winner revealed
  var modeChangedToWinner = s.mode === "winner" && prevMode !== "winner";
  var newWinner = state.mode === "winner" && state.winnerName &&
                  (state.winnerName !== lastWinnerName || modeChangedToWinner);
  if (newWinner) lastWinnerName = state.winnerName;

  render(newWinner);
}

function render(newWinner) {
  var slideWrap  = document.getElementById("slideWrap");
  var winnerWrap = document.getElementById("winnerWrap");

  if (state.mode === "winner") {
    slideWrap.style.display  = "none";
    winnerWrap.style.display = "flex";
    stopSlideTimer();
    if (newWinner) {
      startWinnerReveal();
    } else if (!winnerShown) {
      if (state.winnerName) {
        // Switching back to winner mode with existing winner \u2014 show directly
        document.getElementById("winnerName").textContent  = state.winnerName;
        document.getElementById("winnerPrize").textContent = state.prize || "";
        var _drum = document.getElementById("drumRoll");
        if (_drum) _drum.textContent = "";
        var _imgW = document.getElementById("prizeImageWrap");
        var _imgE = document.getElementById("prizeImg");
        var _emoj = document.getElementById("winnerEmoji");
        if (state.prizeImage && _imgW && _imgE) {
          _imgE.src = state.prizeImage; _imgW.style.display = "block";
          if (_emoj) _emoj.style.display = "none";
        } else {
          if (_imgW) _imgW.style.display = "none";
          if (_emoj) _emoj.style.display = "block";
        }
        document.getElementById("winnerReveal").classList.add("show");
        winnerShown = true;
      } else {
        // No winner yet \u2014 show a waiting state
        document.getElementById("winnerReveal").classList.remove("show");
        var _drumEl = document.getElementById("drumRoll");
        if (_drumEl) _drumEl.textContent = "\ud83c\udfc6 Klar for trekning\u2026";
        document.getElementById("winnerName").textContent  = "";
        document.getElementById("winnerPrize").textContent = "";
      }
    }
  } else {
    winnerWrap.style.display = "none";
    winnerShown = false;
    document.getElementById("winnerReveal").classList.remove("show");
    document.getElementById("drumRoll").textContent = "";
    if (winnerReturnTimer) { clearTimeout(winnerReturnTimer); winnerReturnTimer = null; }
    slideWrap.style.display = "flex";
    renderSlides();
    startSlideTimer();
  }

  renderTicker();
}

// \u2500\u2500 Drum roll + reveal sequence \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function startWinnerReveal() {
  winnerShown = false;
  document.getElementById("winnerReveal").classList.remove("show");
  document.getElementById("winnerName").textContent  = "";
  document.getElementById("winnerPrize").textContent = "";
  document.getElementById("winnerCountdown").textContent = "";

  // Drum roll text (cycles names quickly)
  var allNames = ["???","***","\u2026","###","\u2026","???"];
  var drumEl   = document.getElementById("drumRoll");
  drumEl.textContent = "\ud83e\udd41 Trekker vinner\u2026";
  var drumIdx  = 0;
  var drumTimer = setInterval(function(){
    drumEl.textContent = allNames[drumIdx % allNames.length];
    drumIdx++;
  }, 120);

  // After 2.5s: stop drum roll, reveal winner
  setTimeout(function(){
    clearInterval(drumTimer);
    drumEl.textContent = "";
    document.getElementById("winnerName").textContent  = state.winnerName || "\u2014";
    document.getElementById("winnerPrize").textContent = state.prize || "";
    // Show product image if available
    var imgWrap = document.getElementById("prizeImageWrap");
    var imgEl   = document.getElementById("prizeImg");
    var emojiEl = document.getElementById("winnerEmoji");
    if (state.prizeImage && imgWrap && imgEl) {
      imgEl.src = state.prizeImage;
      imgWrap.style.display = "block";
      if (emojiEl) emojiEl.style.display = "none";
    } else {
      if (imgWrap) imgWrap.style.display = "none";
      if (emojiEl) emojiEl.style.display = "block";
    }
    document.getElementById("winnerReveal").classList.add("show");
    winnerShown = true;
    spawnConfetti();
    startWinnerCountdown();
  }, 2500);
}

// \u2500\u2500 Countdown back to slides \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function startWinnerCountdown() {
  if (winnerReturnTimer) clearTimeout(winnerReturnTimer);
  var totalSec = state.winnerDuration;
  var cdEl     = document.getElementById("winnerCountdown");
  var remaining = totalSec;

  function tick() {
    if (state.mode !== "winner") return;
    remaining--;
    if (remaining > 0) {
      var m = Math.floor(remaining / 60);
      var s = remaining % 60;
      cdEl.textContent = "Tilbake til slides om " + (m > 0 ? m + "m " : "") + s + "s";
      winnerReturnTimer = setTimeout(tick, 1000);
    } else {
      cdEl.textContent = "";
      // Auto-return to slides
      state.mode = "slides";
      render(false);
    }
  }
  winnerReturnTimer = setTimeout(tick, 1000);
}

// \u2500\u2500 Slide-avansering med progress-bar \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function startSlideTimer() {
  stopSlideTimer();
  if (!state.slides || state.slides.length <= 1) return;
  var interval = state.slideInterval * 1000;
  var progEl   = document.getElementById("slideProgress");

  // Anim\u00e9r progress-bar
  if (progEl) {
    progEl.style.transition = "none";
    progEl.style.width = "0%";
    setTimeout(function(){
      progEl.style.transition = "width " + state.slideInterval + "s linear";
      progEl.style.width = "100%";
    }, 50);
  }

  slideAdvanceTimer = setTimeout(function(){
    if (state.mode !== "slides") return;

    // Check if it is time to show a winner card
    var wci = state.winnerCardInterval || 0;
    var winners = (state.winners || []);
    _slidesSinceCard++;

    if (wci > 0 && winners.length > 0 && _slidesSinceCard >= wci) {
      _slidesSinceCard = 0;
      // Pick next winner in rotation
      var w = winners[_winnerCardIndex % winners.length];
      _winnerCardIndex++;
      showWinnerCard();
      return; // winner card handles its own return to slides
    }

    state.slide = (state.slide + 1) % state.slides.length;
    renderSlides();
    startSlideTimer();
  }, interval);
}

function stopSlideTimer() {
  if (slideAdvanceTimer) { clearTimeout(slideAdvanceTimer); slideAdvanceTimer = null; }
  var progEl = document.getElementById("slideProgress");
  if (progEl) { progEl.style.transition = "none"; progEl.style.width = "0%"; }
}

// \u2500\u2500 Vinnerkort overlay \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Groups winners by prize, shows one group per card in rotation
var _winnerCardTimer = null;
var _winnerGroups = []; // [{prize, prizeImage, names:[]}]
var _winnerGroupIndex = 0;

function buildWinnerGroups() {
  var winners = state.winners || [];
  var groups = {};
  var order = [];
  winners.forEach(function(w) {
    var key = (w.prize || "").trim() || "\u2014";
    if (!groups[key]) { groups[key] = { prize: key, prizeImage: w.prizeImage || null, names: [] }; order.push(key); }
    var fname = (w.name || "").split(" ")[0];
    if (!groups[key].names.includes(fname)) groups[key].names.push(fname);
  });
  _winnerGroups = order.map(function(k){ return groups[k]; });
}

function showWinnerCard() {
  buildWinnerGroups();
  if (!_winnerGroups.length) {
    // No winners yet \u2014 skip card, continue slides
    state.slide = (state.slide + 1) % Math.max(1, state.slides.length);
    renderSlides();
    startSlideTimer();
    return;
  }

  var group = _winnerGroups[_winnerGroupIndex % _winnerGroups.length];
  _winnerGroupIndex++;

  var el = document.getElementById("winnerCardOverlay");
  if (!el) return;

  // Prize image
  var img = document.getElementById("wcImg");
  if (group.prizeImage) { img.src = group.prizeImage; img.style.display = "block"; }
  else { img.style.display = "none"; }

  // Prize label
  document.getElementById("wcPrize").textContent = group.prize !== "\u2014" ? group.prize : "";

  // Names \u2014 all winners of this prize
  var namesEl = document.getElementById("wcNames");
  if (namesEl) {
    if (group.names.length === 1) {
      namesEl.innerHTML = '<div class="wc-name-single">' + group.names[0] + '</div>';
    } else {
      namesEl.innerHTML = group.names.map(function(n){
        return '<div class="wc-name-multi">' + n + '</div>';
      }).join("");
    }
  }

  // Show
  el.style.display = "flex";
  setTimeout(function(){ el.classList.add("show"); }, 30);

  // Duration: 4s + 1.5s per extra winner
  var duration = 4000 + Math.max(0, group.names.length - 1) * 1500;
  if (_winnerCardTimer) clearTimeout(_winnerCardTimer);
  _winnerCardTimer = setTimeout(function(){
    el.classList.remove("show");
    setTimeout(function(){
      el.style.display = "none";
      state.slide = (state.slide + 1) % Math.max(1, state.slides.length);
      renderSlides();
      startSlideTimer();
    }, 400);
  }, duration);
}

function renderSlides() {
  var wrap  = document.getElementById("slideWrap");
  var img   = document.getElementById("slideImg");
  var empty = document.getElementById("slideEmpty");
  var nav   = document.getElementById("slideNav");

  if (!state.slides || !state.slides.length) {
    img.style.display   = "none";
    empty.style.display = "block";
    nav.innerHTML = "";
    _clearVideoOverlays();
    return;
  }
  empty.style.display = "none";
  var idx   = Math.min(state.slide || 0, state.slides.length - 1);
  var slide = state.slides[idx];

  img.style.opacity = "0";
  _clearVideoOverlays();

  // Hide the img immediately for video slides so it does not block
  var isVideoSlide = slide && typeof slide === "object" && (slide.type === "mp4-slide" || slide.type === "video-slide");
  if (slide && typeof slide === "object" && slide.type === "mp4-slide") {
    img.style.display = "none";
  }

  setTimeout(function(){
    if (slide && typeof slide === "object" && slide.type === "video-slide") {
      // PPTX video overlay slide
      img.src = slide.bg || "";
      img.style.display = "block";
      img.style.opacity = "1";
      (slide.videos || []).forEach(function(v) {
        var vid = document.createElement("video");
        vid.src      = v.url;
        vid.autoplay = true;
        vid.loop     = true;
        vid.muted    = false;
        vid.controls = false;
        vid.playsInline = true;
        vid.className = "slide-video-overlay";
        vid.style.cssText = "position:absolute;left:" + v.left + "%;top:" + v.top + "%;width:" + v.width + "%;height:" + v.height + "%;object-fit:cover;z-index:2";
        wrap.appendChild(vid);
        vid.play().catch(function() {
          vid.muted = true;
          vid.play().catch(function(){});
        });
      });
    } else if (slide && typeof slide === "object" && slide.type === "mp4-slide") {
      // Fullskjerm MP4 video slide
      img.style.display = "none";
      var vid = document.createElement("video");
      vid.src         = slide.url;
      vid.autoplay    = true;
      vid.loop        = true;
      vid.muted       = true;   // Alltid muted for \u00e5 garantere autoplay in nettleser
      vid.controls    = false;
      vid.playsInline = true;
      vid.setAttribute("playsinline", "");
      vid.setAttribute("webkit-playsinline", "");
      vid.className   = "slide-video-overlay";
      vid.style.cssText = "position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#000;z-index:2";
      wrap.appendChild(vid);
      vid.load();
      var playPromise = vid.play();
      if (playPromise !== undefined) {
        playPromise.catch(function(e) {
          console.warn("[TV] Video autoplay feilet:", e.message);
        });
      }
    } else {
      // Normal PNG slide \u2013 show img igjen
      img.style.display = "block";
      img.src = typeof slide === "string" ? slide : "";
      img.style.opacity = "1";
    }
  }, 200);

  nav.innerHTML = state.slides.map(function(s, i){
    var hasVideo = s && typeof s === "object" && s.type === "video-slide";
    return '<div class="sdot' + (i===idx?' active':'') + '" title="' + (hasVideo?'Video':'') + '"></div>';
  }).join('');
}

function _clearVideoOverlays() {
  document.querySelectorAll(".slide-video-overlay").forEach(function(v) {
    v.pause();
    v.remove();
  });
}

function renderTicker() {
  var ticker     = document.getElementById("ticker");
  var tickerInner= document.getElementById("tickerInner");
  var tickerLabel= document.getElementById("tickerLabel");

  // Build winner text from winners list
  var winnerParts = (state.winners || []).map(function(w) {
    var text = "&#127942; " + w.name;
    if (w.prize) text += " &mdash; " + w.prize;
    if (w.redeemedAt) text += " &#9989;";
    return text;
  });

  // Combine manual ticker text and winner names
  var parts = [];
  if (state.ticker) parts.push(state.ticker);
  parts = parts.concat(winnerParts);

  if (!parts.length) {
    ticker.style.display = "none";
    return;
  }

  ticker.style.display = "flex";
  if (tickerLabel) tickerLabel.style.display = winnerParts.length ? "flex" : "none";

  var sep = "          &bull;          ";
  var txt = parts.join(sep);
  tickerInner.innerHTML = txt;

  // Duration based on text length \u2014 longer text scrolls slower
  var charCount = txt.replace(/&[a-z]+;/g,"\u2022").length;
  var dur = Math.max(8, charCount * 0.18);
  tickerInner.style.animation = "none";
  // Force reflow to restart animation
  void tickerInner.offsetWidth;
  tickerInner.style.animation = "scrollTicker " + dur + "s linear 1 forwards";
  // Restart after each cycle
  tickerInner.onanimationend = function() {
    tickerInner.style.animation = "none";
    void tickerInner.offsetWidth;
    tickerInner.style.animation = "scrollTicker " + dur + "s linear 1 forwards";
  };
}

function spawnConfetti() {
  var colors = ["${accent}","#f87171","#4ade80","#60a5fa","#c084fc","#fb923c","#fff"];
  var shapes = ["10px","8px","6px 12px","12px 6px"];
  for (var i = 0; i < 120; i++) {
    (function(i){
      setTimeout(function(){
        var el = document.createElement("div");
        el.className = "confetti";
        el.style.left   = (Math.random()*110 - 5) + "vw";
        el.style.top    = "-20px";
        el.style.width  = (6 + Math.random()*10) + "px";
        el.style.height = (8 + Math.random()*14) + "px";
        el.style.background = colors[Math.floor(Math.random()*colors.length)];
        el.style.borderRadius = Math.random() > .5 ? "50%" : "2px";
        var dur = 2.5 + Math.random() * 2;
        el.style.animation = "confettiFall " + dur + "s ease-in " + (Math.random()*.8) + "s forwards";
        document.getElementById("screen").appendChild(el);
        setTimeout(function(){ el.remove(); }, (dur + 1) * 1000);
      }, i * 25);
    })(i);
  }
}

// SSE
var es = new EventSource("/api/events/" + evId + "/display/stream");
es.onmessage = function(e) {
  try { var d = JSON.parse(e.data); applyState(d); } catch(x){}
};
es.onerror = function() {
  setTimeout(function(){
    es = new EventSource("/api/events/" + evId + "/display/stream");
  }, 3000);
};
</script>

<footer style="position:fixed;bottom:5.5vh;left:0;right:0;text-align:center;padding:.25rem;font-size:.55rem;color:rgba(255,255,255,.25);pointer-events:none;z-index:200;letter-spacing:.04em">Event-Admin.online \u00b7 v${APP_VERSION}</footer>
</body>
</html>`);
});

// ── Mobil-lotteri-kontrollside ───────────────────────────────────
app.get("/lottery/:evId", auth, function(req, res) {
  const evId    = req.params.evId;
  const events  = readJSON(EVENTS_FILE);
  const ev      = events.find(function(e) { return e.id === evId || e.slug === evId; });
  if (!ev) return res.status(404).send("Event not found");
  const lottery = ev.lottery || {};
  if (!lottery.enabled) return res.status(400).send("Lottery is not enabled for this event");

  const settings   = getSettings();
  const siteName   = settings.siteName || "Event-Admin";
  const deptApp2   = getDeptAppearance(ev);
  const accent     = deptApp2.accent;
  const _lotTheme  = deptApp2.themeDisplay || deptApp2.theme;
  const _lotTypo   = deptApp2.typography || {};
  const _lotFont   = _lotTypo.fontFamily || 'system-ui,sans-serif';
  const _lotIsDark = _lotTheme !== 'light';
  const winners  = lottery.winners || [];
  const regs     = ev.registrations || [];
  const winnerIds = new Set(winners.map(function(w) { return w.regId; }));
  const eligible  = regs.filter(function(r) { return !r.anonymized && !winnerIds.has(r.id); }).length;
  const prizeCount = lottery.prizeCount || 1;
  const drawn      = winners.length;
  const allDrawn   = drawn >= prizeCount;
  const minP       = lottery.minParticipants || 0;
  const tooFew     = minP > 0 && eligible < minP;
  const sa         = lottery.startAfter || null;
  const displayUrl = "/display/" + evId;

  res.send(`<!DOCTYPE html>
<html lang="no">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>🎰 ${escHtml(ev.title || '')}</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}
  body{background:${_lotIsDark?"#0a0a0a":"#f5f5f5"};color:${_lotIsDark?"#fff":"#111"};font-family:${_lotFont};min-height:100dvh;padding:1rem;padding-bottom:2rem}
  h1{font-size:1.1rem;font-weight:900;color:${accent};margin-bottom:.15rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .sub{font-size:.75rem;color:var(--text2);margin-bottom:1.25rem}
  .card{background:#111;border:1px solid #1e1e1e;border-radius:12px;padding:1rem;margin-bottom:.85rem}
  .card-title{font-size:.65rem;font-weight:800;color:var(--text);text-transform:uppercase;letter-spacing:.06em;margin-bottom:.65rem}
  .big-btn{width:100%;padding:1rem;border-radius:10px;border:none;font-size:1.1rem;font-weight:800;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:.5rem;margin-bottom:.5rem;transition:opacity .15s}
  .big-btn:active{opacity:.7}
  .big-btn:disabled{opacity:.3;cursor:default}
  .btn-y{background:${accent};color:#111}
  .btn-purple{background:#2d1a4a;border:2px solid #7c3aed;color:#d8b4fe}
  .btn-blue{background:#0d1a2e;border:2px solid #2563eb;color:#60a5fa}
  .btn-green{background:#0a2a0a;border:2px solid #16a34a;color:#4ade80}
  .btn-ghost{background:#1a1a1a;border:1px solid #2a2a2a;color:#888}
  .stat{display:flex;justify-content:space-between;align-items:center;padding:.5rem 0;border-bottom:1px solid #1a1a1a;font-size:.85rem}
  .stat:last-child{border:none}
  .stat-val{font-weight:800;font-size:1rem;color:${accent}}
  .winner-row{padding:.65rem .85rem;background:#0a1a0a;border:1px solid #1a3a1a;border-radius:8px;margin-bottom:.4rem;display:flex;align-items:center;gap:.75rem}
  .winner-row.redeemed{background:#0a200a;border-color:#166534}
  .winner-name{font-weight:700;font-size:.9rem}
  .winner-meta{font-size:.72rem;color:var(--text2);margin-top:.1rem}
  .badge{display:inline-block;font-size:.68rem;padding:2px 7px;border-radius:10px;font-weight:700}
  .badge-green{background:#0a2a0a;color:#4ade80;border:1px solid #166534}
  .badge-yellow{background:#1a1400;color:${accent};border:1px solid #713f12}
  .result{border-radius:10px;padding:1rem;margin-top:.75rem;font-weight:700;font-size:1rem;text-align:center;min-height:3rem;display:flex;align-items:center;justify-content:center;gap:.5rem}
  .result-ok{background:#0a2a0a;border:2px solid #166534;color:#4ade80}
  .result-warn{background:#1a1400;border:2px solid #713f12;color:${accent}}
  .result-err{background:#2a0a0a;border:2px solid #7f1d1d;color:#f87171}
  .hint{font-size:.78rem;color:var(--text);text-align:center;margin-top:.3rem;min-height:1.2rem}
  #scanOverlay{display:none;position:fixed;inset:0;background:#000e;z-index:999;flex-direction:column;align-items:center;justify-content:center;gap:1rem;padding:1rem}
  #scanBox{position:relative;width:min(300px,85vw);height:min(300px,85vw);border:3px solid ${accent};border-radius:12px;overflow:hidden;background:#111}
  #scanVideo{width:100%;height:100%;object-fit:cover}
  .corner{position:absolute;width:24px;height:24px;border-color:${accent};border-style:solid}
  .tl{top:6px;left:6px;border-width:3px 0 0 3px;border-radius:3px 0 0 0}
  .tr{top:6px;right:6px;border-width:3px 3px 0 0;border-radius:0 3px 0 0}
  .bl{bottom:6px;left:6px;border-width:0 0 3px 3px;border-radius:0 0 0 3px}
  .br{bottom:6px;right:6px;border-width:0 3px 3px 0;border-radius:0 0 3px 0}
  #scanStatus{color:#ccc;font-size:.9rem;text-align:center}
</style>
</head>
<body>

<h1>🎰 ${escHtml(ev.title || '')}</h1>
<div class="sub">${lottery.prize ? "🏆 " + escHtml(lottery.prize) + " \u00b7 " : ""}${drawn}/${prizeCount} trukket \u00b7 ${eligible} kvalifisert</div>

<!-- Stats -->
<div class="card">
  <div class="card-title">Status</div>
  <div class="stat"><span>Kvalifiserte</span><span class="stat-val">${eligible}</span></div>
  <div class="stat"><span>Trukket</span><span class="stat-val">${drawn} / ${prizeCount}</span></div>
  <div class="stat"><span>Innløst</span><span class="stat-val">${winners.filter(function(w){return w.redeemedAt;}).length}</span></div>
  ${lottery.startAfter ? '<div class="stat"><span>Trekning åpner</span><span style="color:#888;font-size:.85rem">kl. ' + escHtml(lottery.startAfter) + '</span></div>' : ""}
</div>

<!-- Trekk -->
<div class="card">
  <div class="card-title">Trekning</div>
  <button class="big-btn btn-y" id="drawBtn" onclick="doDraw()" ${allDrawn || tooFew ? "disabled" : ""}>
    🎰 Trekk vinner nå
  </button>
  <div class="hint" id="drawHint">${allDrawn ? "Alle premier er trukket" : tooFew ? "Venter på min. "+minP+" participants" : ""}</div>
  <div class="result" id="drawResult" style="display:none"></div>
</div>

<!-- Skjerm -->
<div class="card">
  <div class="card-title">Publikumsskjerm</div>
  <button class="big-btn btn-purple" onclick="window.open('${escHtml(displayUrl)}','_blank')">↗ Åpne skjerm</button>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;margin-top:.25rem">
    <button class="big-btn btn-ghost" style="font-size:.85rem" onclick="setMode('slides')">🖼 Slides</button>
    <button class="big-btn btn-ghost" style="font-size:.85rem" onclick="setMode('winner')">🏆 Avslør</button>
  </div>
  <div class="hint" id="screenHint"></div>
</div>

<!-- Verifiser -->
<div class="card">
  <div class="card-title">Verifiser vinner</div>
  <button class="big-btn btn-green" onclick="openScan()">\ud83d\udcf7 Scan QR-kode</button>
  <div style="display:flex;gap:.5rem;margin-top:.5rem">
    <input id="nameQ" type="text" placeholder="Søk på navn…"
      style="flex:1;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;border-radius:8px;padding:.65rem .85rem;font-size:.9rem"
      oninput="searchName(this.value)"/>
  </div>
  <div id="nameResults" style="margin-top:.5rem"></div>
  <div class="result" id="scanResult" style="display:none"></div>
</div>

<!-- Vinnerliste -->
<div class="card">
  <div class="card-title">Vinnere (${winners.length})</div>
  ${winners.length ? winners.slice().reverse().map(function(w) {
    var redeemed = !!w.redeemedAt;
    return '<div class="winner-row' + (redeemed?" redeemed":"") + '">'
      + '<div style="flex:1">'
      + '<div class="winner-name">' + escHtml(w.name) + '</div>'
      + (w.prize ? '<div class="winner-meta">🏆 ' + escHtml(w.prize) + '</div>' : '')
      + '<div class="winner-meta">Trekking #' + w.drawNum + '</div>'
      + (redeemed ? '<div class="winner-meta" style="color:#4ade80">✅ Innløst ' + new Date(w.redeemedAt).toLocaleTimeString("nb-NO",{hour:"2-digit",minute:"2-digit"}) + '</div>' : '')
      + '</div>'
      + '<span class="badge ' + (redeemed?"badge-green":"badge-yellow") + '">' + (redeemed?"Hentet":"Venter") + '</span>'
      + '</div>';
  }).join("") : '<div style="color:#444;font-size:.85rem;text-align:center;padding:.5rem">Ingen vinnere ennå</div>'}
</div>

<!-- Scanner overlay -->
<div id="scanOverlay">
  <div style="color:#fff;font-weight:700;font-size:1rem">\ud83d\udcf7 Scan QR-kode</div>
  <div id="scanBox">
    <video id="scanVideo" autoplay playsinline muted></video>
    <div class="corner tl"></div><div class="corner tr"></div>
    <div class="corner bl"></div><div class="corner br"></div>
  </div>
  <div id="scanStatus">Retter kameraet mot QR-koden…</div>
  <button onclick="closeScan()" style="background:#2a0a0a;border:1px solid #7f1d1d;color:#f87171;padding:.75rem 1.5rem;border-radius:8px;font-size:.95rem;cursor:pointer">✕ Avbryt</button>
</div>

<script>
var evId   = "${escHtml(evId)}";
var stream = null, animFrame = null, scanFound = false;
var winners = ${JSON.stringify(winners.map(function(w){ return { regId:w.regId, name:w.name, prize:w.prize, drawNum:w.drawNum, winnerToken:w.winnerToken, redeemedAt:w.redeemedAt||null }; }))};

async function doDraw() {
  var btn = document.getElementById("drawBtn");
  var res = document.getElementById("drawResult");
  btn.disabled = true; btn.textContent = "\u23f3 Trekker\u2026";
  var r = await fetch("/api/events/" + evId + "/lottery/draw", { method:"POST", headers:{"Content-Type":"application/json"}, body:"{}" });
  var d = await r.json();
  btn.textContent = "\ud83c\udfb0 Trekk vinner n\u00e5";
  res.style.display = "flex";
  if (d.ok && d.winner) {
    res.className = "result result-ok";
    res.innerHTML = "\ud83c\udf89 " + esc(d.winner.name) + " vant!";
    // Also push to display screen
    await fetch("/api/events/" + evId + "/display/state", { method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({ mode:"winner", winnerName:d.winner.name, prize:d.winner.prize||"" }) });
    setTimeout(function(){ location.reload(); }, 2000);
  } else {
    btn.disabled = false;
    res.className = "result result-err";
    res.innerHTML = "\u2717 " + esc(d.error || "Error");
  }
}

async function setMode(mode) {
  var hint = document.getElementById("screenHint");
  hint.textContent = "\u23f3 Sender\u2026";
  await fetch("/api/events/" + evId + "/display/state", { method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({ mode }) });
  hint.textContent = mode === "slides" ? "\u2713 Skjerm viser slides" : "\u2713 Skjerm klar for vinneravsl\u00f8ring";
  setTimeout(function(){ hint.textContent=""; }, 2000);
}

function esc(s) { return String(s||"").replace(/[&<>"']/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]}); }

function searchName(q) {
  var out = document.getElementById("nameResults");
  q = (q||"").trim().toLowerCase();
  if (q.length < 2) { out.innerHTML = ""; return; }
  var matches = winners.filter(function(w){ return w.name.toLowerCase().includes(q); });
  if (!matches.length) { out.innerHTML = '<div style="color:#555;font-size:.82rem;padding:.3rem">Ikke funnet i vinnerlisten</div>'; return; }
  out.innerHTML = matches.map(function(w) {
    var redeemed = !!w.redeemedAt;
    return '<div class="winner-row' + (redeemed?" redeemed":"") + '" style="margin-top:.3rem">'
      + '<div style="flex:1"><div class="winner-name">' + esc(w.name) + '</div>'
      + (w.prize ? '<div class="winner-meta">\ud83c\udfc6 ' + esc(w.prize) + '</div>' : '')
      + (redeemed ? '<div class="winner-meta" style="color:#4ade80">\u2705 Allerede innl\u00f8st</div>' : '')
      + '</div>'
      + (!redeemed ? '<button onclick="redeemWinner(\'' + esc(w.winnerToken||"") + '\')" style="background:#166534;border:none;color:#4ade80;padding:.5rem .85rem;border-radius:6px;font-size:.82rem;font-weight:700;cursor:pointer">\u2705 Innl\u00f8s</button>' : '')
      + '</div>';
  }).join("");
}

async function redeemWinner(token) {
  var res = document.getElementById("scanResult");
  res.style.display="flex"; res.className="result"; res.textContent="\u23f3 Sjekker\u2026";
  var r = await fetch("/api/events/" + evId + "/lottery/verify-reg", { method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify({ token }) });
  var d = await r.json();
  if (d.valid && d.isWinner && !d.alreadyRedeemed) {
    res.className="result result-ok"; res.innerHTML="\u2705 Innl\u00f8st \u2013 " + esc(d.name);
    setTimeout(function(){ location.reload(); }, 1500);
  } else if (d.alreadyRedeemed) {
    res.className="result result-warn"; res.textContent="\u26a0 Allerede innl\u00f8st";
  } else {
    res.className="result result-err"; res.textContent="\u2717 " + esc(d.message||d.reason||"Error");
  }
}

function openScan() {
  if (!navigator.mediaDevices) { alert("Kamera ikke tilgjengelig"); return; }
  var ov = document.getElementById("scanOverlay");
  ov.style.display="flex"; scanFound=false;
  navigator.mediaDevices.getUserMedia({ video:{ facingMode:"environment" } }).then(function(s) {
    stream=s;
    var v=document.getElementById("scanVideo"); v.srcObject=s; v.play();
    if (window.BarcodeDetector) {
      var det=new BarcodeDetector({formats:["qr_code"]});
      function tick() {
        if(scanFound)return;
        if(v.readyState>=2) det.detect(v).then(function(codes){
          if(codes&&codes.length){ onScanFound(codes[0].rawValue); return; }
          animFrame=requestAnimationFrame(tick);
        }).catch(function(){ animFrame=requestAnimationFrame(tick); });
        else animFrame=requestAnimationFrame(tick);
      }
      animFrame=requestAnimationFrame(tick);
    } else {
      document.getElementById("scanStatus").textContent="BarcodeDetector is not supported - use name search";
    }
  }).catch(function(e){ closeScan(); alert("Kamerafeil: "+(e.message||e)); });
}

function closeScan() {
  scanFound=true;
  if(animFrame) cancelAnimationFrame(animFrame);
  if(stream) stream.getTracks().forEach(function(t){t.stop();}); stream=null;
  document.getElementById("scanOverlay").style.display="none";
}

async function onScanFound(data) {
  if(scanFound)return; scanFound=true;
  document.getElementById("scanStatus").textContent="\u2705 Kode funnet!";
  setTimeout(async function(){
    closeScan();
    var res=document.getElementById("scanResult");
    res.style.display="flex"; res.className="result"; res.textContent="\u23f3 Verifiserer\u2026";
    var r=await fetch("/api/events/"+evId+"/lottery/verify-reg",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({token:data})});
    var d=await r.json();
    if(!d.valid){ res.className="result result-err"; res.innerHTML="\u274c " + esc(d.message||"Invalid code"); return; }
    if(d.isWinner&&d.alreadyRedeemed){ res.className="result result-warn"; res.innerHTML="\u26a0\ufe0f Allerede innl\u00f8st \u2013 " + esc(d.name); return; }
    if(d.isWinner){ res.className="result result-ok"; res.innerHTML="\ud83c\udfc6 VINNER! " + esc(d.name) + (d.prize?" \u2013 "+esc(d.prize):""); setTimeout(function(){location.reload();},2000); return; }
    res.className="result"; res.style.background="#0d1a2e"; res.style.border="2px solid #2563eb";
    res.innerHTML="\u2705 Registrert participant \u2013 " + esc(d.name) + " \u2013 ikke vinner";
  }, 400);
}
</script>
</body>
</html>`);
});

// Auto-redirect mobile browsers from / to /m
// ── Mobil-admin (/m) ─────────────────────────────────────────────
function isMobileBrowser(req) {
  const ua = (req.headers["user-agent"] || "").toLowerCase();
  return /android|iphone|ipad|ipod|mobile|blackberry|windows phone/.test(ua);
}

const MOBILE_HTML = '<!DOCTYPE html>\n<html lang="no">\n<head>\n<meta charset="UTF-8"/>\n<meta name="viewport" content="width=device-width,initial-scale=1"/>\n<title>__SITENAME__</title>\n<style>\n  *{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}\n  body{background:#0d0d0d;color:#fff;font-family:system-ui,sans-serif;padding-bottom:4rem}\n  header{background:#111;border-bottom:3px solid __ACCENT__;padding:1rem 1rem .85rem;display:flex;justify-content:space-between;align-items:center;position:sticky;top:0;z-index:100}\n  header h1{font-size:1.1rem;font-weight:900;color:__ACCENT__;letter-spacing:-.01em}\n  header a{color:#555;font-size:.78rem;text-decoration:none;padding:.4rem .7rem;border:1px solid #2a2a2a;border-radius:6px}\n\n  /* Event kort */\n  .evcard{border-bottom:1px solid #1a1a1a;cursor:pointer;user-select:none}\n  .evcard-header{padding:.9rem 1rem;display:flex;justify-content:space-between;align-items:center;gap:.75rem;background:#141414}\n  .evcard-header:active{background:#1e1e1e}\n  .evcard-left{flex:1;min-width:0}\n  .evcard-title{font-weight:700;font-size:1rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .evcard-meta{font-size:.75rem;color:var(--text2);margin-top:.15rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .evcard-badges{display:flex;gap:.35rem;margin-top:.35rem;flex-wrap:wrap}\n  .pill{font-size:.68rem;font-weight:700;padding:2px 7px;border-radius:10px;white-space:nowrap}\n  .pill-lottery{background:#1a0a2e;color:#d8b4fe;border:1px solid #5b3a7a}\n  .pill-regs{background:#0a1a0a;color:#4ade80;border:1px solid #166534}\n  .chevron{font-size:1.2rem;color:var(--text2);transition:transform .25s;flex-shrink:0;width:1.5rem;text-align:center}\n  .chevron.open{transform:rotate(90deg);color:__ACCENT__}\n\n  /* Actions panel */\n  .evactions{display:none;background:#0a0a0a;border-bottom:2px solid #1a1a1a;padding:.75rem .85rem;flex-direction:column;gap:.6rem}\n  .evactions.open{display:flex}\n\n  /* Seksjoner */\n  .section{background:#141414;border:1px solid #1e1e1e;border-radius:12px;overflow:hidden}\n  .section-head{padding:.6rem .85rem;font-size:.68rem;font-weight:800;color:var(--text2);text-transform:uppercase;letter-spacing:.07em;border-bottom:1px solid #1e1e1e;display:flex;align-items:center;gap:.4rem}\n  .section-body{padding:.75rem .85rem;display:flex;flex-direction:column;gap:.5rem}\n\n  /* Knapper */\n  .btn-row{display:flex;gap:.4rem}\n  .btn{flex:1;padding:.8rem .5rem;border-radius:9px;border:none;font-size:.88rem;font-weight:700;cursor:pointer;text-align:center;text-decoration:none;display:flex;align-items:center;justify-content:center;gap:.35rem;transition:opacity .12s;line-height:1.2}\n  .btn:active{opacity:.65}\n  .btn-yellow{background:__ACCENT__;color:#111}\n  .btn-blue{background:#0d1a2e;border:1.5px solid #2563eb;color:#60a5fa}\n  .btn-green{background:#0a2a0a;border:1.5px solid #16a34a;color:#4ade80}\n  .btn-purple{background:#1a0a2e;border:1.5px solid #7c3aed;color:#d8b4fe}\n  .btn-ghost{background:#1a1a1a;border:1px solid #2a2a2a;color:#888}\n  .btn-sm{padding:.55rem .5rem;font-size:.8rem;border-radius:7px}\n\n  /* Status melding */\n  .status-msg{font-size:.85rem;font-weight:700;min-height:1.5rem;padding:.1rem 0}\n\n  /* Vinnere */\n  .winner-item{display:flex;justify-content:space-between;align-items:center;padding:.5rem 0;border-bottom:1px solid #1e1e1e;gap:.5rem}\n  .winner-item:last-child{border:none}\n  .winner-name{font-weight:700;font-size:.9rem}\n  .winner-prize{font-size:.75rem;color:__ACCENT__;margin-top:.1rem}\n  .badge{font-size:.7rem;font-weight:700;padding:3px 8px;border-radius:8px;white-space:nowrap;flex-shrink:0}\n  .badge-ok{background:#0a2a0a;color:#4ade80;border:1px solid #166534}\n  .badge-wait{background:#1a1400;color:__ACCENT__;border:1px solid #713f12}\n\n  /* Navn-søk */\n  .name-search-input{width:100%;background:#111;border:1.5px solid #2a2a2a;color:#fff;border-radius:9px;padding:.75rem .9rem;font-size:.95rem;outline:none}\n  .name-search-input:focus{border-color:__ACCENT__44}\n  .name-result{display:flex;justify-content:space-between;align-items:center;background:#141414;border-radius:8px;padding:.6rem .85rem;margin-top:.35rem;gap:.5rem}\n\n  /* QR overlay */\n  #scanOverlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.95);z-index:9999;flex-direction:column;align-items:center;justify-content:center;gap:1rem;padding:1.5rem}\n  #scanBox{position:relative;width:min(290px,82vw);height:min(290px,82vw);border:3px solid __ACCENT__;border-radius:14px;overflow:hidden;background:#111}\n  #scanVideo{width:100%;height:100%;object-fit:cover}\n  .corner{position:absolute;width:22px;height:22px;border-color:__ACCENT__;border-style:solid}\n  .tl{top:6px;left:6px;border-width:3px 0 0 3px;border-radius:3px 0 0 0}\n  .tr{top:6px;right:6px;border-width:3px 3px 0 0;border-radius:0 3px 0 0}\n  .bl{bottom:6px;left:6px;border-width:0 0 3px 3px;border-radius:0 0 0 3px}\n  .br{bottom:6px;right:6px;border-width:0 3px 3px 0;border-radius:0 0 3px 0}\n  #scanStatus{color:#ccc;font-size:.9rem;text-align:center;max-width:280px}\n  #scanResultBox{border-radius:12px;padding:1rem 1.25rem;font-weight:700;font-size:1rem;text-align:center;max-width:300px;width:100%;display:none}\n  .btn-cancel{background:#1a0a0a;border:1.5px solid #7f1d1d;color:#f87171;padding:.8rem 2rem;border-radius:10px;font-size:.95rem;cursor:pointer;font-weight:700}\n\n  .empty{color:#333;text-align:center;padding:4rem 1rem;font-size:.9rem}\n  .section-label{font-size:.65rem;font-weight:800;color:var(--text2);text-transform:uppercase;letter-spacing:.08em;padding:.85rem 1rem .4rem}\n</style>\n</head>\n<body>\n<header>\n  <h1>&#9889; __SITENAME__</h1>\n  <a href="/">&#128187; Full admin</a>\n</header>\n\n__EVCARDS__\n\n<!-- QR scanner overlay -->\n<div id="scanOverlay">\n  <div style="color:#fff;font-weight:800;font-size:1.05rem;letter-spacing:.02em">&#128247; Scan vinner-QR</div>\n  <div id="scanBox">\n    <video id="scanVideo" autoplay playsinline muted></video>\n    <div class="corner tl"></div><div class="corner tr"></div>\n    <div class="corner bl"></div><div class="corner br"></div>\n  </div>\n  <div id="scanStatus">Rett kameraet mot QR-koden&hellip;</div>\n  <div id="scanResultBox"></div>\n  <button class="btn-cancel" onclick="closeScan()">&#10005; Avbryt</button>\n</div>\n\n<script>\nvar _scanEvId=null,_stream=null,_animFrame=null,_scanFound=false;\nvar _winners=__WINNERS_DATA__;\n\nvar _sseConn=null;\nfunction startSSE(){\n  _sseConn=new EventSource("/api/events/stream");\n  _sseConn.onmessage=function(e){\n    try{var d=JSON.parse(e.data);if(d.type==="events_updated")fetchLive();}catch(x){}\n  };\n  _sseConn.onerror=function(){setTimeout(startSSE,4000);};\n}\nasync function fetchLive(){\n  try{\n    var r=await fetch("/api/events",{credentials:"include"});\n    var evs=await r.json();\n    if(!Array.isArray(evs))return;\n    evs.forEach(function(ev){\n      var regs=(ev.registrations||[]).filter(function(r){return !r.anonymized;}).length;\n      var won=(ev.lottery&&ev.lottery.winners)||[];\n      var drawn=won.length;\n      var pc=(ev.lottery&&ev.lottery.prizeCount)||1;\n      var rem=pc-drawn;\n      var re=document.getElementById("regs-"+ev.id);\n      if(re){re.textContent="\u{1F465} "+regs+" p\u00e5meldt";re.style.background="#0a3a0a";setTimeout(function(){re.style.background="";},800);}\n      var le=document.getElementById("lot-"+ev.id);\n      if(le)le.textContent="\uD83C\uDFB0 "+drawn+"/"+pc+" trukket";\n      var db=document.getElementById("drawbtn-"+ev.id);\n      if(db){db.disabled=rem<=0;db.style.opacity=rem<=0?".35":"1";db.textContent=rem>0?"\uD83C\uDFB0 Trekk vinner ("+rem+" igjen)":"\uD83C\uDFB0 Alle trukket";}\n      var sl=document.getElementById("lotsec-"+ev.id);\n      if(sl)sl.textContent="\uD83C\uDFB0 Lotteri \u00b7 "+drawn+"/"+pc+" trukket \u00b7 "+regs+" kvalifisert";\n    });\n  }catch(e){}\n}\nstartSSE();\n\n\nfunction esc(s){return String(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}\n\nfunction toggleEv(id){\n  var a=document.getElementById("act-"+id);\n  var ch=document.getElementById("ch-"+id);\n  var open=a.classList.contains("open");\n  a.classList.toggle("open",!open);\n  if(ch)ch.classList.toggle("open",!open);\n}\n\nasync function apiFetch(method,url,body){\n  var opts={method,credentials:"include",headers:{}};\n  if(body){opts.headers["Content-Type"]="application/json";opts.body=JSON.stringify(body);}\n  try{var r=await fetch(url,opts);return await r.json();}catch(e){return{err:e.message};}\n}\n\nfunction showMsg(id,text,color){\n  var el=document.getElementById(id);\n  if(!el)return;\n  el.textContent=text;\n  el.style.color=color||"#4ade80";\n  if(text)setTimeout(function(){el.textContent="";},4000);\n}\n\nasync function drawLottery(evId,btn){\n  var orig=btn.textContent;\n  btn.disabled=true;btn.textContent="Trekker...";\n  var d=await apiFetch("POST","/api/events/"+evId+"/lottery/draw");\n  btn.disabled=false;btn.textContent=orig;\n  if(d.ok&&d.winner){\n    showMsg("lmsg-"+evId,"&#127881; "+d.winner.name+" vant"+(d.winner.prize?" \\u2013 "+d.winner.prize:"")+"!","#4ade80");\n    await apiFetch("POST","/api/events/"+evId+"/display/state",{mode:"winner",winnerName:d.winner.name,prize:d.winner.prize||"",prizeImage:d.winner.prizeImage||null});\n    setTimeout(function(){location.reload();},2500);\n  }else{\n    showMsg("lmsg-"+evId,"\\u2717 "+(d.error||d.err||"Error"),"#f87171");\n  }\n}\n\nasync function sendEmails(evId){\n  var d=await apiFetch("POST","/api/events/"+evId+"/lottery/send-winner-email");\n  if(d.ok)showMsg("lmsg-"+evId,"\\u2713 Sendt til "+d.sent+" vinner(e)","#60a5fa");\n  else showMsg("lmsg-"+evId,"\\u2717 "+(d.error||d.err||"Error"),"#f87171");\n}\n\nasync function sendConsolation(evId){\n  var d=await apiFetch("POST","/api/events/"+evId+"/lottery/send-consolation-email");\n  if(d.ok)showMsg("lmsg-"+evId,"\\u2713 Tr\\u00f8ste-epost sendt til "+d.sent+" participant(e)","#d8b4fe");\n  else showMsg("lmsg-"+evId,"\\u2717 "+(d.error||d.err||"Error"),"#f87171");\n}\n\nasync function setMode(evId,mode){\n  await apiFetch("POST","/api/events/"+evId+"/display/state",{mode});\n  showMsg("lmsg-"+evId,mode==="slides"?"\\u2713 Slides aktiv":"\\u2713 Vinnermodus aktiv",mode==="slides"?"#60a5fa":"__ACCENT__");\n}\n\nfunction toggleSearch(evId){\n  var el=document.getElementById("nsearch-"+evId);\n  if(el){\n    var show=el.style.display==="none";\n    el.style.display=show?"":"none";\n    if(show)el.querySelector("input").focus();\n  }\n}\n\nfunction nameSearch(evId,q){\n  var out=document.getElementById("nsres-"+evId);\n  if(!out)return;\n  q=(q||"").trim().toLowerCase();\n  if(q.length<2){out.innerHTML="";return;}\n  var winners=_winners[evId]||[];\n  var matches=winners.filter(function(w){return w.name.toLowerCase().includes(q);});\n  if(!matches.length){out.innerHTML=\'<div style="color:#555;font-size:.82rem;padding:.25rem 0">Ikke funnet blant vinnerne</div>\';return;}\n  out.innerHTML=matches.map(function(w){\n    var redeemed=!!w.redeemedAt;\n    return \'<div class="name-result">\'\n      +\'<div><div class="winner-name">\'+esc(w.name)+\'</div>\'+(w.prize?\'<div class="winner-prize">\'+esc(w.prize)+\'</div>\':\'\')+\'</div>\'\n      +(redeemed?\'<span class="badge badge-ok">&#9989; Hentet</span>\'\n        :\'<button onclick="redeemW(\\\'\'+evId+\'\\\',\\\'\'+esc(w.winnerToken||"")+\'\\\',this)" style="background:#166534;border:none;color:#4ade80;padding:.5rem .9rem;border-radius:7px;font-size:.82rem;font-weight:700;cursor:pointer">&#9989; Innl\\u00f8s</button>\')\n      +\'</div>\';\n  }).join("");\n}\n\nasync function redeemW(evId,token,btn){\n  if(btn){btn.disabled=true;btn.textContent="...";}\n  var d=await apiFetch("POST","/api/events/"+evId+"/lottery/verify-reg",{token});\n  if(d.valid&&d.isWinner&&!d.alreadyRedeemed){\n    showMsg("vmsg-"+evId,"\\u2705 Innl\\u00f8st \\u2013 "+d.name,"#4ade80");\n    setTimeout(function(){location.reload();},1500);\n  }else if(d.alreadyRedeemed){\n    showMsg("vmsg-"+evId,"\\u26a0 Allerede innl\\u00f8st","#f59e0b");\n    if(btn){btn.disabled=false;btn.textContent="&#9989; Innl\\u00f8s";}\n  }else{\n    showMsg("vmsg-"+evId,"\\u2717 "+(d.message||d.reason||"Error"),"#f87171");\n    if(btn){btn.disabled=false;btn.textContent="&#9989; Innl\\u00f8s";}\n  }\n}\n\nfunction openQR(evId){\n  _scanEvId=evId;_scanFound=false;\n  var ov=document.getElementById("scanOverlay");\n  var rb=document.getElementById("scanResultBox");\n  ov.style.display="flex";rb.style.display="none";\n  document.getElementById("scanStatus").textContent="Rett kameraet mot QR-koden\\u2026";\n  if(!navigator.mediaDevices){document.getElementById("scanStatus").textContent="Kamera ikke tilgjengelig";return;}\n  navigator.mediaDevices.getUserMedia({video:{facingMode:"environment"}}).then(function(s){\n    _stream=s;\n    var v=document.getElementById("scanVideo");v.srcObject=s;v.play();\n    if(window.BarcodeDetector){\n      var det=new BarcodeDetector({formats:["qr_code"]});\n      function tick(){\n        if(_scanFound)return;\n        if(v.readyState>=2)det.detect(v).then(function(codes){\n          if(codes&&codes.length){onQR(codes[0].rawValue);return;}\n          _animFrame=requestAnimationFrame(tick);\n        }).catch(function(){_animFrame=requestAnimationFrame(tick);});\n        else _animFrame=requestAnimationFrame(tick);\n      }\n      _animFrame=requestAnimationFrame(tick);\n    }else{\n      document.getElementById("scanStatus").textContent="QR-scan ikke st\\u00f8ttet \\u2013 bruk navnes\\u00f8k";\n    }\n  }).catch(function(e){closeScan();alert("Kamerafeil: "+e.message);});\n}\n\nfunction closeScan(){\n  _scanFound=true;\n  if(_animFrame)cancelAnimationFrame(_animFrame);\n  if(_stream)_stream.getTracks().forEach(function(t){t.stop();});_stream=null;\n  document.getElementById("scanOverlay").style.display="none";\n}\n\nasync function onQR(data){\n  if(_scanFound)return;_scanFound=true;\n  document.getElementById("scanStatus").textContent="\\u2705 Kode funnet!";\n  setTimeout(async function(){\n    closeScan();\n    if(!_scanEvId)return;\n    var d=await apiFetch("POST","/api/events/"+_scanEvId+"/lottery/verify-reg",{token:data});\n    var rb=document.getElementById("scanResultBox");\n    rb.style.display="block";\n    if(!d.valid){\n      rb.style.cssText="background:#2a0a0a;border:2px solid #7f1d1d;color:#f87171;border-radius:12px;padding:1rem 1.25rem;font-weight:700;font-size:1rem;text-align:center;display:block";\n      rb.innerHTML="\\u274c "+(d.message||"Invalid code");\n    }else if(d.isWinner&&d.alreadyRedeemed){\n      rb.style.cssText="background:#1a1400;border:2px solid #713f12;color:var(--ev-warn-text);border-radius:12px;padding:1rem 1.25rem;font-weight:700;font-size:1rem;text-align:center;display:block";\n      rb.innerHTML="\\u26a0\\ufe0f Allerede innl\\u00f8st<br><span style=\'font-size:.88rem;font-weight:400\'>"+esc(d.name)+"</span>";\n    }else if(d.isWinner){\n      rb.style.cssText="background:#0a2a0a;border:2px solid #166534;color:#4ade80;border-radius:12px;padding:1rem 1.25rem;font-weight:700;font-size:1.1rem;text-align:center;display:block";\n      rb.innerHTML="\\ud83c\\udfc6 VINNER!<br><span style=\'font-size:.95rem\'>"+esc(d.name)+"</span>"+(d.prize?"<br><span style=\'font-size:.8rem;color:__ACCENT__\'>"+esc(d.prize)+"</span>":"");\n      showMsg("vmsg-"+_scanEvId,"\\u2705 Innl\\u00f8st \\u2013 "+d.name,"#4ade80");\n    }else{\n      rb.style.cssText="background:#0d1a2e;border:2px solid #2563eb;color:#60a5fa;border-radius:12px;padding:1rem 1.25rem;font-weight:700;font-size:1rem;text-align:center;display:block";\n      rb.innerHTML="\\u2705 "+esc(d.name)+"<br><span style=\'font-size:.8rem;font-weight:400;color:#aaa\'>Registrert participant \\u2013 ikke vinner</span>";\n    }\n  },400);\n}\n</script>\n</body>\n</html>\n';

app.get("/m", auth, function(req, res) {
  const settings  = getSettings();
  const siteName  = settings.siteName || "Event-Admin";
  const accent    = (settings.colors && settings.colors.accent) || "#FFD100";
  const eventsAll = readJSON(EVENTS_FILE);
  const user      = req.session.user;
  const now       = new Date();

  const myEvents = eventsAll.filter(function(ev) {
    if (user.role === "admin") return true;
    return getAccessList(user).some(function(a){ return a.department === ev.department; });
  }).sort(function(a,b){
    const da = a.date ? new Date(a.date) : new Date("2099-01-01");
    const db = b.date ? new Date(b.date) : new Date("2099-01-01");
    return da - db;
  });

  const upcoming = myEvents.filter(function(ev){
    if (!ev.date) return true;
    const d = new Date(ev.date);
    return d >= new Date(now.getFullYear(), now.getMonth(), now.getDate());
  }).slice(0, 15);

  function evCard(ev) {
    const hasLottery = ev.lottery && ev.lottery.enabled;
    const dateStr = ev.date
      ? new Date(ev.date).toLocaleDateString("nb-NO",{weekday:"short",day:"numeric",month:"short"})
      : "Ingen dato";
    const regs       = (ev.registrations||[]).filter(function(r){return !r.anonymized;}).length;
    const winners    = (ev.lottery && ev.lottery.winners) || [];
    const drawn      = winners.length;
    const prizeCount = (ev.lottery && ev.lottery.prizeCount) || 1;
    const unredeemed = winners.filter(function(w){return !w.redeemedAt && w.email && w.winnerToken;}).length;
    const remaining  = prizeCount - drawn;
    const id         = escHtml(ev.id);
    const title      = escHtml(ev.title || '');
    const meta       = dateStr + (ev.location ? " &middot; " + escHtml(ev.location) : "");

    let html = "<div class=\"evcard\">"
      + "<div class=\"evcard-header\" onclick=\"toggleEv('" + id + "')\"><div class=\"evcard-left\">"
      + "<div class=\"evcard-title\">" + title + "</div>"
      + "<div class=\"evcard-meta\">" + meta + "</div>"
      + "<div class=\"evcard-badges\">"
      + "<span class=\"pill pill-regs\" id=\"regs-" + id + "\">&#128101; " + regs + " p&aring;meldt</span>"
      + (hasLottery ? "<span class=\"pill pill-lottery\" id=\"lot-" + id + "\">&#127920; " + drawn + "/" + prizeCount + " trukket</span>" : "")
      + "</div></div>"
      + "<div class=\"chevron\" id=\"ch-" + id + "\">&#9654;</div>"
      + "</div>"
      + "<div class=\"evactions\" id=\"act-" + id + "\">";

    // Lottery-seksjon
    if (hasLottery) {
      html += "<div class=\"section\"><div class=\"section-head\" id=\"lotsec-" + id + "\">&#127920; Lotteri &middot; " + drawn + "/" + prizeCount + " trukket &middot; " + regs + " kvalifisert</div><div class=\"section-body\">"
        + "<div class=\"btn-row\">"
        + "<button class=\"btn btn-yellow\" id=\"drawbtn-" + id + "\" onclick=\"drawLottery('" + id + "',this)\" " + (remaining<=0?"disabled style=\"opacity:.35\"":"") + ">"
        + "\uD83C\uDFB0 Trekk vinner" + (remaining>0?" ("+remaining+" igjen)":"") + "</button>"
        + "</div>"
        + (unredeemed>0
          ? "<div class=\"btn-row\"><button class=\"btn btn-blue btn-sm\" onclick=\"sendEmails('" + id + "')\">&#128231; Send QR til " + unredeemed + " vinner(e)</button></div>"
          : "")
        + "<div class=\"btn-row\">"
        + "<button class=\"btn btn-ghost btn-sm\" onclick=\"setMode('" + id + "','slides')\">&#128444; Slides</button>"
        + "<button class=\"btn btn-ghost btn-sm\" onclick=\"setMode('" + id + "','winner')\">&#127942; Vinnermodus</button>"
        + "<button class=\"btn btn-purple btn-sm\" onclick=\"window.open('/display/" + id + "','_blank')\">&#8599; Skjerm</button>"
        + "</div>"
        + "<div class=\"status-msg\" id=\"lmsg-" + id + "\"></div>"
        + "</div></div>";
    }

    // Verifisering
    html += "<div class=\"section\"><div class=\"section-head\">&#128269; Verifiser vinner-QR</div><div class=\"section-body\">"
      + "<div class=\"btn-row\">"
      + "<button class=\"btn btn-green\" onclick=\"openQR('" + id + "')\">&#128247; Scan QR-kode</button>"
      + "<button class=\"btn btn-ghost\" data-shid=\"' + sh.id + '\" onclick=\"openShiftSignup(this.dataset.shid)\"onclick=\"toggleSearch('" + id + "')\">&#128100; S&oslash;k p&aring; navn</button>"
      + "</div>"
      + "<div id=\"nsearch-" + id + "\" style=\"display:none\">"
      + "<input class=\"name-search-input\" type=\"text\" placeholder=\"Skriv navn\u2026\" oninput=\"nameSearch('" + id + "',this.value)\"/>"
      + "<div id=\"nsres-" + id + "\"></div>"
      + "</div>"
      + "<div class=\"status-msg\" id=\"vmsg-" + id + "\"></div>"
      + "</div></div>";

    // Winnerliste
    if (winners.length) {
      html += "<div class=\"section\"><div class=\"section-head\">&#127942; Vinnere</div><div class=\"section-body\">";
      winners.slice().reverse().forEach(function(w) {
        html += "<div class=\"winner-item\">"
          + "<div><div class=\"winner-name\">" + escHtml(w.name) + "</div>"
          + (w.prize ? "<div class=\"winner-prize\">&#127942; " + escHtml(w.prize) + "</div>" : "")
          + "</div>"
          + (w.redeemedAt
            ? "<span class=\"badge badge-ok\">&#9989; Hentet</span>"
            : "<span class=\"badge badge-wait\">&#9203; Venter</span>")
          + "</div>";
      });
      html += "</div></div>";
    }

    html += "</div></div>";
    return html;
  }

  const evCardsHtml = upcoming.length
    ? "<div class=\"section-label\">Kommende arrangementer</div>" + upcoming.map(evCard).join("")
    : "<div class=\"empty\">Ingen kommende arrangementer</div>";

  const winnersData = {};
  upcoming.forEach(function(ev) {
    if (ev.lottery && ev.lottery.winners && ev.lottery.winners.length) {
      winnersData[ev.id] = ev.lottery.winners.map(function(w) {
        return { regId:w.regId, name:w.name, prize:w.prize||"", winnerToken:w.winnerToken||"", redeemedAt:w.redeemedAt||null };
      });
    }
  });

  res.send(MOBILE_HTML
    .replace(/__SITENAME__/g, escHtml(siteName))
    .replace(/__ACCENT__/g, accent)
    .replace("__EVCARDS__", evCardsHtml)
    .replace("__WINNERS_DATA__", JSON.stringify(winnersData))
  );
});

app.get("*", function(req, res) {
  // An unknown /api/* path must not fall through to the app shell: doing so
  // answered a missing endpoint with the entire 2.4 MB index.html, which is
  // both useless to the caller and very expensive.
  if (req.path.indexOf("/api/") === 0) {
    return res.status(404).json({ error: "Unknown endpoint: " + req.path });
  }
  sendAppShell(req, res);
});

// ── Auto-installer for LibreOffice and pdftoppm ──────────────────
// Runs on startup if tools are missing (Alpine/Debian support)
(function ensureConversionTools() {
  const { execSync, execFile } = require("child_process");
  function hasCmd(cmd) {
    try { execSync("which " + cmd + " 2>/dev/null"); return true; } catch(e) { return false; }
  }
  const needsLO   = !hasCmd("libreoffice") && !hasCmd("soffice");
  const needsPppm = !hasCmd("pdftoppm");
  if (!needsLO && !needsPppm) {
    console.log("[tools] LibreOffice og pdftoppm OK");
    return;
  }
  console.log("[tools] Installing conversion tools (this takes 1-3 min the first time)…");
  try {
    // Detect package manager
    if (hasCmd("apk")) {
      // Alpine Linux
      const pkgs = [];
      if (needsLO)   pkgs.push("libreoffice");
      if (needsPppm) pkgs.push("poppler-utils");
      pkgs.push("font-noto", "font-noto-cjk");
      execSync("apk add --no-cache " + pkgs.join(" "), { stdio: "inherit", timeout: 300000 });
    } else if (hasCmd("apt-get")) {
      // Debian/Ubuntu
      const pkgs = [];
      if (needsLO)   pkgs.push("libreoffice");
      if (needsPppm) pkgs.push("poppler-utils");
      pkgs.push("fonts-noto");
      execSync("apt-get update -q && apt-get install -y -q --no-install-recommends " + pkgs.join(" ") + " && rm -rf /var/lib/apt/lists/*", { stdio: "inherit", timeout: 300000, shell: true });
    } else {
      console.warn("[tools] Ukjent pakkebehandler – kan ikke installere LibreOffice automatisk");
    }
    console.log("[tools] Installation complete ✓");
  } catch(e) {
    console.error("[tools] Installasjon feilet:", e.message);
    console.warn("[tools] PPTX-konvertering vil ikke fungere – installer LibreOffice manuelt i Docker-image");
  }
})();

const PORT = process.env.PORT || 3000;
app.listen(PORT, function() {
  // ── Migration: fix events with invalid date values (e.g. "T10:00" from wizard bug) ──
  try {
    var evs3 = readJSON(EVENTS_FILE);
    var fixed3 = 0;
    evs3.forEach(function(ev) {
      if (ev.date && (isNaN(new Date(ev.date).getTime()) || ev.date.startsWith('T'))) {
        console.log("[migration] Clearing invalid date '" + ev.date + "' from: " + ev.title);
        ev.date = null;
        fixed3++;
      }
    });
    if (fixed3 > 0) {
      writeJSON(EVENTS_FILE, evs3);
      console.log("[migration] Fixed invalid dates on " + fixed3 + " events");
    }
  } catch(e) {
    console.error("[migration] date fix failed:", e.message);
  }
  try {
    var evs2 = readJSON(EVENTS_FILE);
    var s2   = getSettings();
    var depts2 = s2.departments || [];
    var fixed2 = 0;
    // Build a map of all valid subgroup IDs across all depts
    var validSgIds = new Set();
    depts2.forEach(function(d) { (d.subgroups||[]).forEach(function(sg){ validSgIds.add(sg.id); }); });
    evs2.forEach(function(ev) {
      if (ev.subgroup && !validSgIds.has(ev.subgroup)) {
        console.log("[migration] Clearing orphaned subgroup " + ev.subgroup + " from: " + ev.title);
        ev.subgroup = null;
        fixed2++;
      }
    });
    if (fixed2 > 0) {
      writeJSON(EVENTS_FILE, evs2);
      console.log("[migration] Cleared orphaned subgroups from " + fixed2 + " events");
    }
  } catch(e) {
    console.error("[migration] subgroup fix failed:", e.message);
  }
  // This happened due to a bug in saveEvent that read from a hidden unchecked checkbox.
  // Safe rule: if an event has isPublic=false AND was created before the fix (no isPublicSetAt),
  // set it back to true so it shows on department pages.
  // Runs once only: events are now created non-public on purpose, and a later run would
  // publish them behind the manager's back.
  try {
    var _migS = getSettings();
    var evs = _migS._isPublicFixDone ? [] : readJSON(EVENTS_FILE);
    var fixed = 0;
    evs.forEach(function(ev) {
      // Only fix events where isPublic is explicitly false but no intentional hide markers
      if (ev.isPublic === false && !ev.hideFromList && !ev.isInternal && !ev.isPublicSetByUser) {
        ev.isPublic = true;
        fixed++;
      }
    });
    if (fixed > 0) {
      writeJSON(EVENTS_FILE, evs);
      console.log("[migration] Fixed isPublic=false on " + fixed + " events");
    }
    if (!_migS._isPublicFixDone) { _migS._isPublicFixDone = new Date().toISOString(); saveSettings(_migS); }
  } catch(e) {
    console.error("[migration] isPublic fix failed:", e.message);
  }
  const bootMs = Date.now() - _bootStart;
  console.log("Event-Admin v" + APP_VERSION + " ready in " + bootMs + "ms on port " + PORT + " (domain: " + DOMAIN + ")");

  // write watchdog.js to /watchdog/ if the volume is mounted
  try {
    const watchdogPath = "/watchdog/watchdog.js";
    const watchdogDir  = "/watchdog";
    if (fs.existsSync(watchdogDir)) {
      const existing = fs.existsSync(watchdogPath) ? fs.readFileSync(watchdogPath, "utf8") : "";
      if (existing !== WATCHDOG_JS) {
        fs.writeFileSync(watchdogPath, WATCHDOG_JS, "utf8");
        console.log("[watchdog] watchdog.js written to " + watchdogPath);
      } else {
        console.log("[watchdog] watchdog.js is already up to date");
      }
    }
  } catch(e) { /* /watchdog not mounted – ignored */ }
  // Migrasjon: normaliser roller til lowercase_underscore
  try {
    const users = readJSON(USERS_FILE);
    let changed = 0;
    users.forEach(function(u) {
      if (u.role) {
        const norm = u.role.toLowerCase().replace(/[- ]/g,"_");
        if (norm !== u.role) { u.role = norm; changed++; }
      }
      // Normalise roles in accessList as well
      (u.accessList||[]).forEach(function(a) {
        if (a.role) {
          const norm = a.role.toLowerCase().replace(/[- ]/g,"_");
          if (norm !== a.role) { a.role = norm; changed++; }
        }
      });
    });
    if (changed > 0) { writeJSON(USERS_FILE, users); console.log("[migrate] Normaliserte " + changed + " roller"); }
  } catch(e) { console.error("[migrate] Feil ved rolenormalisering:", e.message); }
});

// ── Stats reporter: write a stats snapshot to shared STATS_DIR ────────────
// Each instance reports its own stats so the LAB can read them without
// needing direct access to each instance's data directory.
function writeStatsReport() {
  if (!STATS_DIR) return;
  try {
    if (!fs.existsSync(STATS_DIR)) return;  // volume not mounted — skip silently
    const settings  = readJSON(SETTINGS_FILE);
    const visits    = readJSON(VISITS_FILE);
    const slug      = process.env.SLUG || DOMAIN.split(".")[0] || "unknown";
    const now       = new Date();
    const today     = now.toISOString().slice(0, 10);
    const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);

    // Day buckets for last 90 days
    const since90 = new Date(Date.now() - 90 * 86400000).toISOString();
    const recent  = visits.filter(function(v) { return v.ts >= since90; });    const byDay   = {};
    recent.forEach(function(v) {
      const d = v.ts.slice(0, 10);
      byDay[d] = (byDay[d] || 0) + 1;
    });

    const report = {
      slug,
      siteName:  settings.siteName  || slug,
      domain:    DOMAIN || settings.adminDomain || settings.domain || "",
      version:   APP_VERSION,
      updatedAt: now.toISOString(),
      isDemo:    slug.toLowerCase().includes("demo") || IS_DEMO,
      stats: {
        allTime:   visits.length,
        days90:    recent.length,
        today:     byDay[today]     || 0,
        yesterday: byDay[yesterday] || 0,
        byDay,    // full 90-day map
      }
    };

    const outPath = require("path").join(STATS_DIR, slug + ".json");
    fs.writeFileSync(outPath, JSON.stringify(report, null, 2), "utf8");
  } catch(e) {
    console.error("[stats-report] Failed to write stats:", e.message);
  }
}

// Write on startup and then every hour
if (STATS_DIR) {
  writeStatsReport();
  setInterval(writeStatsReport, 60 * 60 * 1000);
  // Also write every 5 min in demo mode so LAB sees fresh data
  if (IS_DEMO) setInterval(writeStatsReport, 5 * 60 * 1000);
  console.log("[stats-report] Reporting to " + STATS_DIR);
}

// ── QUICK WIN 3: 24h reminder emails ──────────────────────────────────────
async function sendEventReminders() {
  const events   = readJSON(EVENTS_FILE);
  const settings = getSettings();
  const now      = Date.now();
  const in24h    = now + 24 * 60 * 60 * 1000;
  const in25h    = now + 25 * 60 * 60 * 1000;

  for (const ev of events) {
    if (!ev.date || !ev.time || ev.hidden) continue;
    const evMs = new Date(ev.date + "T" + (ev.time || "00:00")).getTime();
    // Only send if event is 24-25h from now (1h window to avoid duplicates)
    if (evMs < in24h || evMs > in25h) continue;
    // Skip if already sent
    if (ev._reminderSent) continue;

    const regs = (ev.registrations || []).filter(function(r){
      return !r.anonymized && !r.waitlist && r.email;
    });
    if (!regs.length) continue;

    const dateStr = new Date(ev.date).toLocaleDateString("nb-NO", { weekday:"long", day:"numeric", month:"long" });
    const senderInfo = getEvSenderInfo(ev);

    for (const reg of regs) {
      await sendEmail({
        to: reg.email,
        subject: "Påminnelse: " + ev.title + " i morgen",
        fromName: senderInfo.name,
        html: "<p>Hei " + escHtml(reg.name) + ",</p>"
          + "<p>Dette er en påminnelse om at <strong>" + escHtml(ev.title) + "</strong> er i morgen, "
          + escHtml(dateStr) + " kl. " + escHtml(ev.time) + ".</p>"
          + (ev.location ? "<p>\ud83d\udccd Sted: " + escHtml(ev.location) + "</p>" : "")
          + "<p>Vi gleder oss til å se deg!</p>",
        department: ev.department, eventId: ev.id, category: "registration"
      }).catch(function(){});
    }

    // Mark as sent so we don't send again
    const allEvs = readJSON(EVENTS_FILE);
    const idx = allEvs.findIndex(function(e){ return e.id === ev.id; });
    if (idx >= 0) { allEvs[idx]._reminderSent = true; writeJSON(EVENTS_FILE, allEvs); }
    console.log("[reminder] Sent " + regs.length + " reminders for: " + ev.title);

    // SMS reminders
    const _smsCfg = settings.sms || {};
    if (_smsCfg.triggers && _smsCfg.triggers.reminder) {
      const _smsRegs = (ev.registrations || []).filter(function(r){ return !r.anonymized && !r.waitlist && r.phone; });
      for (const _smsReg of _smsRegs) {
        const _smsText = 'Påminnelse: ' + ev.title + ' er i morgen kl. ' + ev.time + (ev.location ? ', ' + ev.location : '') + '. Vi gleder oss til å se deg!';
        await sendSMS(_smsReg.phone, _smsText).catch(function(){});
      }
      if (_smsRegs.length) console.log('[reminder] Sent ' + _smsRegs.length + ' SMS reminders for: ' + ev.title);
    }
  }
}

// Run reminder check every hour
setInterval(sendEventReminders, 60 * 60 * 1000);
// Also run shortly after startup
setTimeout(sendEventReminders, 30 * 1000);

// ── QUICK WIN 4: Annual report endpoint ───────────────────────────────────
app.get("/api/stats/annual-report", auth, managerOrAdmin, function(req, res) {
  const year   = parseInt(req.query.year) || new Date().getFullYear();
  const events = readJSON(EVENTS_FILE);
  const yearStart = new Date(year, 0, 1).getTime();
  const yearEnd   = new Date(year + 1, 0, 1).getTime();

  const p = getProfile(req);
  const me = p && p.id ? readJSON(USERS_FILE).find(function(u){ return u.id === p.id; }) : null;

  // Filter to dept if manager
  const evYear = events.filter(function(ev) {
    if (!ev.date) return false;
    const t = new Date(ev.date).getTime();
    if (t < yearStart || t >= yearEnd) return false;
    if (!p.isAdmin && me && me.department && ev.department !== me.department) return false;
    return true;
  }).sort(function(a,b){ return new Date(a.date)-new Date(b.date); });

  // Volunteer map
  const volMap = new Map();
  evYear.forEach(function(ev) {
    (ev.staff || []).forEach(function(s) {
      if (s.checkedIn && s.name && s.name !== "[slettet]") {
        const k = s.name.trim();
        volMap.set(k, (volMap.get(k) || 0) + 1);
      }
    });
  });
  const topVols = Array.from(volMap.entries()).sort(function(a,b){return b[1]-a[1];}).slice(0,20);

  // Per-event summary
  const evSummary = evYear.map(function(ev) {
    const regs  = (ev.registrations||[]).filter(function(r){return !r.anonymized&&!r.waitlist;});
    const checkedIn = regs.filter(function(r){return r.checkedIn;}).length;
    return {
      date:       ev.date,
      time:       ev.time || "",
      title:      ev.title,
      type:       ev.eventType || "stand",
      location:   ev.location || "",
      registrations: regs.length,
      checkedIn,
      checkinRate: regs.length ? Math.round(checkedIn/regs.length*100) : null,
      maxParticipants: ev.maxParticipants || null,
      staffCount: (ev.staff||[]).filter(function(s){return s.checkedIn;}).length,
      guestbook:  (ev.guestbook||[]).filter(function(g){return g.approved;}).length,
    };
  });

  // Totals
  const totals = {
    events:        evYear.length,
    registrations: evSummary.reduce(function(s,e){return s+e.registrations;},0),
    checkedIn:     evSummary.reduce(function(s,e){return s+e.checkedIn;},0),
    staffShifts:   evSummary.reduce(function(s,e){return s+e.staffCount;},0),
    guestbook:     evSummary.reduce(function(s,e){return s+e.guestbook;},0),
    uniqueVolunteers: volMap.size,
    byType: { stand:0, kurs:0, tur:0, mote:0 },
  };
  evYear.forEach(function(ev){ const t=ev.eventType||"stand"; if(totals.byType[t]!==undefined)totals.byType[t]++; });
  totals.checkinRate = totals.registrations ? Math.round(totals.checkedIn/totals.registrations*100) : null;

  res.json({ year, totals, events: evSummary, topVolunteers: topVols });
});

